#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define CE_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 1000 // Sample every second

void spi_init(void);
void spi_transfer(uint8_t *data, int length);
void log_reading(const char *timestamp, int raw_value);

int main(int argc, char *argv[]) {
    if (argc != 1) {
        fprintf(stderr, "Usage: %s <moisture_sensor_address>\n", argv[0]);
        exit(1);
    }

    spi_init();

    while (1) {
        spi_transfer((uint8_t *)argv[1], 1);
        int raw_value = pigpio_get_adc_value(ADC_CHANNEL);
        log_reading(time(NULL), raw_value);
        usleep(SAMPLE_INTERVAL * 1000); // Sleep for the interval
    }

    pigpio_terminate(1000); // Terminate pigpio cleanly
    return 0;
}

void spi_init(void) {
    int spi_handle = pigpio_spidev_open(CE_PIN, 0, 0);
    if (spi_handle < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }
}

void spi_transfer(uint8_t *data, int length) {
    int ret = pigpio_spidev_write_read(spi_handle, data, length);
    if (ret < 0) {
        perror("Failed to perform SPI transfer");
        exit(1);
    }
}

void log_reading(const char *timestamp, int raw_value) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    printf("%s: Moisture Level: %d\n", ctime(time_info), raw_value);
}

