#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define ADS1115_ADDR 0x48
#define SDA_PIN 2
#define SCL_PIN 3
#define LOG_INTERVAL 500

#define MLX91219_SENSITIVITY 0.04096  // 40mV/A
#define ZERO_CURRENT_OFFSET 0.0

int i2c_fd;

void init_ads1115(void) {
    int result;

    // Initialize pigpio
    if (piGPIOInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    result = open("/dev/i2c-1", O_RDWR);
    if (result < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        piGPIOExit();
        exit(EXIT_FAILURE);
    }

    // Set I2C bus parameters
    ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR);

    // Configure ADS1115 for single-shot mode, AIN0 single-ended, PGA ±4.096V, 128 samples/s
    result = i2cWriteI2CBlockData(i2c_fd, 0x00, 0x00, 0x00, 0x00); // Set configuration register 0
    result = i2cWriteI2CBlockData(i2c_fd, 0x01, 0x00, 0x00, 0x00); // Set MUX to AIN0 (MUX=100)
    result = i2cWriteI2CBlockData(i2c_fd, 0x02, 0x00, 0x00, 0x00); // Set PGA to ±4.096V
    result = i2cWriteI2CBlockData(i2c_fd, 0x03, 0x00, 0x00, 0x00); // Set data rate to 128 samples/s

    if (result < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        close(i2c_fd);
        piGPIOExit();
        exit(EXIT_FAILURE);
    }
}

int read_ads1115(uint16_t reg, uint16_t *data) {
    int result;

    // Read 16-bit data from ADS1115
    result = i2cReadI2CBlockData(i2c_fd, reg, 0, data, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        return -1;
    }

    return 0;
}

int main(void) {
    int current;
    uint16_t adc_data;
    int i;

    init_ads1115();

    while (1) {
        // Read 12-bit ADC data from AIN0
        read_ads1115(0x00, &adc_data);

        // Convert ADC data to voltage
        current = (adc_data * MLX91219_SENSITIVITY) + ZERO_CURRENT_OFFSET;

        // Log the current to the console
        printf("Current: %.3f A\n", current);

        // Wait for LOG_INTERVAL milliseconds
        usleep(LOG_INTERVAL * 1000);
    }

    // Close I2C bus and terminate pigpio
    close(i2c_fd);
    piGPIOExit();

    return 0;
}

