#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/spi/spidev.h>

#define GPIO4 2
#define SPI_CE0 8
#define SPI_FREQ 1000000
#define FLAME_SENSOR_D0 GPIO4
#define MCP3008_CHANNEL 0
#define TEMP_MAP_FACTOR 10

void log_entry(const char *timestamp, int flame_detected, float temperature) {
    FILE *file = fopen("flame_data.csv", "a");
    if (!file) {
        fprintf(stderr, "Error opening flame_data.csv: %s\n", strerror(errno));
        return;
    }
    fprintf(file, "%s,%d,%f\n", timestamp, flame_detected, temperature);
    fclose(file);
}

int main() {
    int spi_fd, mcp3008_fd;
    struct spidev_dev *dev;
    int ret;

    // Initialize pigpio
    if (piGPIOInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI device
    dev = spidev_open(0, 0);
    if (!dev) {
        fprintf(stderr, "Failed to open SPI device\n");
        return EXIT_FAILURE;
    }

    // Configure SPI
    ret = spidev_setup(dev, 0, SPI_FREQ);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure SPI\n");
        return EXIT_FAILURE;
    }

    // Open MCP3008
    mcp3008_fd = open("MCP3008", O_RDWR);
    if (mcp3008_fd < 0) {
        fprintf(stderr, "Failed to open MCP3008\n");
        return EXIT_FAILURE;
    }

    // Read KY-026 digital output
    int flame_detected = 0;
    int d0_value = spidev_readb(dev, FLAME_SENSOR_D0);
    flame_detected = (d0_value == 0);

    // Read analog output from MCP3008
    int result;
    result = spidev_control(dev, SPI_READ, MCP3008_CHANNEL, 0, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to read from MCP3008\n");
        return EXIT_FAILURE;
    }
    uint16_t adc_value = spidev_readb(dev, MCP3008_CHANNEL);

    // Convert ADC value to temperature
    float temperature = (adc_value * 3.3 / 1023.0) * TEMP_MAP_FACTOR + 10;

    // Log data
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    log_entry(timestamp, flame_detected, temperature);

    // Clean up
    close(mcp3008_fd);
    spidev_close(dev, 0);
    piGPIOExit();

    return EXIT_SUCCESS;
}

