    msg.data = (void *)0;

    if (i2c_write(i2c_client, &msg, 1) < 0) {
        fprintf(stderr, "Failed to configure ADC\n");
        close(i2c_client);
        close(buzzer_fd);
        gpioTerminate();
        return 1;
    }

    if (i2c_write(i2c_client, &msg, 1) < 0) {
        fprintf(stderr, "Failed to set ADC configuration\n");
        close(i2c_client);
        close(buzzer_fd);
        gpioTerminate();
        return 1;
    }

    if (i2c_read(i2c_client, &msg, 1) < 0) {
        fprintf(stderr, "Failed to read ADC data\n");
        close(i2c_client);
        close(buzzer_fd);
        gpioTerminate();
        return 1;
    }

    if (i2c_close(i2c_client) < 0) {
        fprintf(stderr, "Failed to close I2C bus\n");
        close(buzzer_fd);
        gpioTerminate();
        return 1;
    }

    if (pigpioSetup(1, GPIO4, BUZZER_ON, BUZZER_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO pin as output\n");
        close(buzzer_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (pigpioSetup(1, GPIO27, BUZZER_ON, BUZZER_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO pin as output\n");
        close(buzzer_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (pigpioRegisterInterrupt(GPIO4, flame_isr, 0) < 0) {
        fprintf(stderr, "Failed to register flame sensor interrupt\n");
        close(buzzer_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read flame sensor
        if (read(GPIO4, &flame_state) == -1) {
            perror("read flame sensor");
            break;
        }

        // Read temperature
        if (i2c_open(0, 0) < 0) {
            fprintf(stderr, "Failed to open I2C bus\n");
            break;
        }

        msg.address = ADC_ADDRESS;
        msg.len = sizeof(msg);
        msg.data = (void *)&temperature;

        if (i2c_write(i2c_client, &msg, 1) < 0) {
            fprintf(stderr, "Failed to read ADC data\n");
            close(i2c_fd);
            break;
        }

        if (i2c_read(i2c_client, &msg, 1) < 0) {
            fprintf(stderr, "Failed to read ADC data\n");
            close(i2c_fd);
            break;
        }

        if (i2c_close(i2c_client) < 0) {
            fprintf(stderr, "Failed to close I2C bus\n");
            break;
        }

        // Check for fire condition
        if (flame_state && temperature > TEMP_THRESHOLD) {
            // Log event and sound buzzer
            if (write(buzzer_fd, "Flame detected!\n", 18) == -1) {
                perror("write to log file");
            }
            pigpioSetMode(BUZZER_PIN, PIG_OUTPUT);
            pigpioSetDutyCycle(BUZZER_PIN, 255);
            sleep(0.5);
            pigpioSetDutyCycle(BUZZER_PIN, 0);
            sleep(BUZZER_DURATION);
        }

        // Debounce flame sensor
        if (millis() - last_flame_event > DEBOUNCE_TIME) {
            last_flame_event = millis();
        }

        usleep(100000);
    }

    pigpioTerminate();
    close(buzzer_fd);
    close(i2c_fd);
    return 0;
}

void handle_sigint(int signum) {
    flame_state = 0;
    pigpioSetMode(GPIO4, PIG_INPUT);
    pigpioSetMode(GPIO27, PIG_OUTPUT);
    pigpioSetDutyCycle(GPIO27, BUZZER_OFF);
    printf("Exiting...\n");
    exit(0);
}
