#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <spidev.h>
#include <gpio/gpio.h>
#include <time.h>

#define SPI_FILE "/dev/spidev0.0"
#define GPIO_PIN 4
#define FAN_PIN 18
#define ADC_SENSITIVITY 100  // mV/A
#define FAN_THRESHOLD 5.0    // A
#define SAMPLE_INTERVAL 1000000  // us

#define SPI_MODE 0
#define SPI_BITS 8

#define ADC_COMMAND (0x01 << 7)  // Channel 0, single-ended

// Function to read SPI data
int read_spi(int fd, uint8_t *data) {
    int ret = spidev_xfer(fd, &data, 3, 0);
    if (ret < 0) {
        perror("spidev_xfer failed");
        return -1;
    }
    return 0;
}

// Function to convert ADC value to current
float adc_to_current(uint16_t adc_value) {
    return (adc_value * 3.3) / (1024.0 * ADC_SENSITIVITY);
}

// Function to check if sensor is present
int sensor_present(void) {
    uint8_t adc_data[3];
    if (read_spi(open(SPI_FILE, O_RDWR), adc_data) == 0) {
        return adc_data[1] != 0;  // All-ones indicates sensor absent
    }
    return 1;
}

// Function to log the current reading
void log_reading(const char *timestamp) {
    time_t now = time(NULL);
    struct tm *tinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            tinfo->tm_year + 1900, tinfo->tm_mon + 1, tinfo->tm_mday,
            tinfo->tm_hour, tinfo->tm_min, tinfo->tm_sec);

    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        perror("fopen current_log.txt");
        return;
    }

    fprintf(log_file, "%s, %f, %f\n", time_str, adc_to_current(adc_data[1]),
            adc_data[2]);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int spi_fd, gpio_fd;
    struct gpio_desc *gpio_desc;
    int fan_state = 0;

    spi_fd = open(SPI_FILE, O_RDWR);
    if (spi_fd == -1) {
        perror("open SPI_FILE");
        return EXIT_FAILURE;
    }

    gpio_fd = open("/dev/gpiochip4", O_RDWR);
    if (gpio_fd == -1) {
        perror("open gpiochip4");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpio_desc = (struct gpio_desc *)gpio_desc_alloc(gpio_fd);
    if (!gpio_desc) {
        perror("gpio_desc_alloc");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpio_desc->mode = GPIO_OUTPUT;
    gpio_desc->value = 0;  // Turn off fan initially

    if (gpio_set_level(gpio_desc, 0) == -1) {
        perror("gpio_set_level");
        gpio_desc_free(gpio_desc);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        if (!sensor_present()) {
            log_reading("Sensor Absent");
            continue;
        }

        uint16_t adc_value = adc_data[1];
        float current = adc_to_current(adc_value);

        if (current > FAN_THRESHOLD) {
            fan_state = 1;
            log_reading("Fan ON");
        } else {
            fan_state = 0;
            log_reading("Fan OFF");
        }

        if (write(gpio_desc, fan_state) == -1) {
            perror("write to GPIO");
            gpio_desc_free(gpio_desc);
            close(spi_fd);
            return EXIT_FAILURE;
        }

        usleep(SAMPLE_INTERVAL / 1000);
    }

    gpio_desc_free(gpio_desc);
    close(gpio_fd);
    close(spi_fd);

    return EXIT_SUCCESS;
}

