#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <spidev.h>

#define GPIO4 2
#define SPI_CE0 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_CLOCK_HZ 1000000

#define FLAME_SENSOR_D0 GPIO4
#define FLAME_SENSOR_A0 0
#define MCP3008_CHANNEL 0

#define LOG_FILE "flame_data.csv"

void spi_init() {
    int fd = spidev_open(0, 0);
    if (fd < 0) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }

    spidev_control(fd, PIGIO_SPI_SET_MODE, SPI_CE0, 0);
    spidev_control(fd, PIGIO_SPI_SET_BITS, 8);
    spidev_control(fd, PIGIO_SPI_SET_POLARITY, 0);
    spidev_control(fd, PIGIO_SPI_SET_PHASE, 0);
    spidev_control(fd, PIGIO_SPI_SCLK_DIV, SPI_CLOCK_HZ / 100000);
}

void pigpio_init() {
    if (piGPIOInit() < 0) {
        fprintf(stderr, "pigpio_init failed: %s\n", piGPIOGetLastError());
        exit(EXIT_FAILURE);
    }
}

void log_data(int flame_present, float temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%f,%d\n", temperature, flame_present);
    fclose(file);
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "Exiting...\n");
        exit(0);
    }
}

int main() {
    signal(SIGINT, signal_handler);

    pigpio_init();
    spi_init();

    gpioSetMode(GPIO4, GPIO_OUTPUT);
    gpioWrite(GPIO4, 0); // Initially, no flame detected

    while (1) {
        int flame_present = gpioRead(FLAME_SENSOR_D0);
        if (flame_present == 1) {
            int adc_value = read_adc(MCP3008_CHANNEL);
            float temperature = map(adc_value, 0, 4095, 0, 10.0);

            log_data(flame_present, temperature);
        }

        usleep(1000000); // Wait for 1 second
    }

    pigpioExit();
    spidev_close(fd);
    return 0;
}

int read_adc(int channel) {
    int spi_fd = spidev_open(0, 0);
    if (spi_fd < 0) {
        handle_error("Failed to open SPI device");
        return -1;
    }

    spi_control(spi_fd, SPI_CSPOL, 0);
    spi_control(spi_fd, SPI_S_BIT | SPI_MSBFIRST, 0);

    uint8_t command[2] = {MCP3008_READ_REG, channel};
    spi_write(spi_fd, command);

    uint8_t status;
    spi_read(spi_fd, &status, 1);
    if (status != 0) {
        handle_error("SPI read failed");
        return -1;
    }

    uint16_t data = spi_read(spi_fd, 2);
    spi_control(spi_fd, SPI_CSPOL, 1);
    spi_control(spi_fd, SPI_S_BIT | SPI_MSBFIRST, 0);

    return data;
}

