void sigint_handler(int signum) {
    printf("SIGINT received, shutting down...\n");
    exit(0);
}

void sigterm_handler(int signum) {
    printf("SIGTERM received, shutting down...\n");
    exit(0);
}

int main() {
    pigpio_init(5); // Initialize pigpio with 5 available pins (I2C)

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    int i2c_fd;
    char log_file_co[] = "co_log.txt";
    char log_file_alert[] = "alert_log.txt";

    // Open log files
    FILE *fp_co = fopen(log_file_co, "a");
    FILE *fp_alert = fopen(log_alert, "a");

    if (!fp_co || !fp_alert) {
        perror("Error opening log files");
        pigpio_terminate(1);
        return -1;
    }

    // Initialize I2C
    if (pigpio_begin_i2c(I2C_ADDRESS) < 0) {
        perror("Failed to initialize I2C");
        fclose(fp_co);
        fclose(fp_alert);
        pigpio_terminate(1);
        return -1;
    }

    while (1) {
        // Read from the sensor
        uint16_t ox_data, red_data;
        if (pigpio_i2c_mem_read(I2C_ADDRESS, 0x00, 2, &ox_data, 2) < 0) {
            perror("Failed to read from sensor");
            fprintf(fp_alert, "Sensor read failure\n");
            continue;
        }

        // Calculate CO level in PPM
        int co_ppm = (ox_data * 100) / 65536;

        // Log CO level
        if (co_ppm > CO_ALERT_THRESHOLD) {
            fprintf(fp_alert, "CO Alert: %d PPM\n", co_ppm);
        } else {
            fprintf(fp_co, "CO: %d PPM\n", co_ppm);
        }

        // Sleep before next reading
        usleep(LOG_INTERVAL * 1000 / 1000);
    }

    // Clean up and exit
    fclose(fp_co);
    fclose(fp_alert);
    pigpio_terminate(0);
    return 0;
}

