#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define MIC_ADDR1 0x48
#define MIC_ADDR2 0x49
#define SAMPLE_INTERVAL_MS 100
#define MIC_SENSITIVITY -38
#define REFERENCE_PRESSURE 20e-6

#define LOG_FILE "audio_log.txt"

void log_error(const char *msg, double value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }
    fprintf(fp, "%s: %s = %f dB\n", __func__, msg, value);
    fclose(fp);
}

void handle_signal(int signum) {
    log_error("Received signal, shutting down gracefully.", -999.0);
    pigpio_stop();
    exit(0);
}

int main() {
    pigpio_init(1); // Initialize pigpio with I2C bus 1

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int mic1_fd, mic2_fd;
    struct i2c_rdwr_t wr_reg;
    uint16_t data1, data2;

    mic1_fd = open("/dev/i2c-1", O_RDWR);
    if (mic1_fd < 0) {
        log_error("Failed to open I2C bus 1.", -999.0);
        pigpio_stop();
        return EXIT_FAILURE;
    }

    wr_reg.addr = MIC_ADDR1;
    wr_reg.data = &data1;
    wr_reg.len = sizeof(data1);
    if (i2c_transfer(mic1_fd, &wr_reg, 1) < 0) {
        log_error("Failed to read from MIC1.", -999.0);
        close(mic1_fd);
        pigpio_stop();
        return EXIT_FAILURE;
    }

    data1 = (data1 << 8) | read(mic1_fd, &data2, 2);
    close(mic1_fd);

    mic2_fd = open("/dev/i2c-1", O_RDWR);
    if (mic2_fd < 0) {
        log_error("Failed to open I2C bus 1.", -999.0);
        pigpio_stop();
        return EXIT_FAILURE;
    }

    wr_reg.addr = MIC_ADDR2;
    wr_reg.data = &data2;
    wr_reg.len = sizeof(data2);
    if (i2c_transfer(mic2_fd, &wr_reg, 1) < 0) {
        log_error("Failed to read from MIC2.", -999.0);
        close(mic2_fd);
        pigpio_stop();
        return EXIT_FAILURE;
    }

    data2 = (data2 << 8) | read(mic2_fd, &data1, 2);
    close(mic2_fd);

    double pressure1 = ((data1 * 3.3) / (1024.0 * 1024.0)) * MIC_SENSITIVITY + REFERENCE_PRESSURE;
    double pressure2 = ((data2 * 3.3) / (1024.0 * 1024.0)) * MIC_SENSITIVITY + REFERENCE_PRESSURE;

    double avg_pressure = (pressure1 + pressure2) / 2.0;

    if (isnan(avg_pressure)) {
        log_error("Microphone read failed, using error value.", -999.0);
        avg_pressure = -999.0;
    }

    unsigned long timestamp = microsecond();
    log_error("Average sound pressure level: %f dB\n", avg_pressure);
    fprintf(stdout, "Average sound pressure level: %f dB\n", avg_pressure);

    usleep(SAMPLE_INTERVAL_MS * 1000 / 1000); // Wait for next sample

    return 0;
}

