#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>
#include <spidev.h>

#define MIC_CHANNEL_1 0
#define MIC_CHANNEL_2 1
#define LED_PIN 27
#define SAMPLE_INTERVAL_MS 1000
#define SAMPLE_COUNT 100
#define RMS_THRESHOLD 0.7
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1

#define SPI_BUS 0
#define SPI_DEVICE 0

void spi_init(void);
void spi_deinit(void);
void read_adc(int channel, int *data);
float calculate_rms(int *adc_data, int length);
void log_event(const char *timestamp, float rms1, float rms2);
void turn_on_led(void);
void turn_off_led(void);

int main(int argc, char *argv[]) {
    int led_state = 0;
    int spi_fd, adc_fd;
    int adc_data[2];
    struct stat file_stat;
    char *filename = "audio_events.csv";

    spi_init();
    if (spi_fd == -1) {
        perror("SPI initialization failed");
        return EXIT_FAILURE;
    }

    turn_on_led();

    while (1) {
        read_adc(MIC_CHANNEL_1, adc_data);
        read_adc(MIC_CHANNEL_2, adc_data + 1);

        float rms1 = calculate_rms(adc_data, SAMPLE_COUNT);
        float rms2 = calculate_rms(adc_data + 1, SAMPLE_COUNT);

        if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
            log_event(get_timestamp(), rms1, rms2);
            turn_on_led();
            usleep(500000); // 500 ms
        }

        turn_off_led();

        // Log events to CSV
        FILE *file = fopen(filename, "a");
        if (!file) {
            perror("Failed to open file for appending");
            return EXIT_FAILURE;
        }
        fprintf(file, "%f,%f\n", get_timestamp(), rms1);
        fclose(file);

        usleep(SAMPLE_INTERVAL_MS * 1000); // Wait for next sample
    }

    spi_deinit();
    turn_off_led();
    return EXIT_SUCCESS;
}

void spi_init(void) {
    spi_fd = spidev_open(SPI_BUS, 0);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
}

void spi_deinit(void) {
    if (spi_fd != -1) {
        spidev_close(spi_fd);
        spi_fd = -1;
    }
}

void read_adc(int channel, int *data) {
    int status;
    spidev_control(spi_fd, SPID_CIRCULATE, channel);
    status = spidev_recv(spi_fd, data, 2, 1000);
    if (status < 0) {
        perror("SPI read error");
        exit(EXIT_FAILURE);
    }
}

float calculate_rms(int *adc_data, int length) {
    float sum = 0;
    for (int i = 0; i < length; i++) {
        sum += (float)adc_data[i];
    }
    return sqrt(sum / length);
}

void log_event(const char *timestamp, float rms1, float rms2) {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    time ( &rawtime );
    timeinfo = localtime ( &rawtime );
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open file for appending");
        return;
    }
    fprintf(file, "%s,%f,%f\n", buffer, rms1, rms2);
    fclose(file);
}

void turn_on_led(void) {
    led_state = 1;
}

void turn_off_led(void) {
    led_state = 0;
}

float get_timestamp(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (float)ts.tv_sec + (float)ts.tv_nsec / 1e9;
}

