#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/statfs.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define SAMPLE_RATE 10
#define LED_GPIO 17
#define SENSOR_ADDRESS 0x48
#define SDA_PIN 2
#define SCL_PIN 3
#define ADC_CHANNEL A0
#define ADC_THRESHOLD 50.0

#define I2C_BUS 1

int i2c_fd;
int led_gpio;
int adc_channel;
int adc_threshold;
int buffer_index;
int buffer_size;
float current_readings[BUFFER_SIZE];
float current_average;

void init_pigpio(void) {
    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
