#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define REG_ID 0x12
#define REG_ATIME 0x01
#define REG_CONTROL 0x0F
#define REG_ENABLE 0x00
#define REG_CLEAR 0x14
#define REG_RED 0x15
#define REG_GREEN 0x16
#define REG_BLUE 0x17

#define COLOR_LOG_FILE "color_log.csv"

int main() {
    int i2c_fd, error;
    struct i2c_client *client;
    char buffer[3];
    uint16_t clear, red, green, blue;

    pigpio_init(I2C_BUS);
    if ((error = pigpio_open_bus(I2C_BUS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_error_name(error));
        return EXIT_FAILURE;
    }

    client = pigpio_i2c_open(I2C_BUS, I2C_ADDR);
    if (!client) {
        fprintf(stderr, "Failed to open I2C device: %s\n", pigpio_error_name(errno));
        pigpio_close_bus(I2C_BUS);
        return EXIT_FAILURE;
    }

    if (pigpio_i2c_write(client, REG_ID) != 4) {
        fprintf(stderr, "Failed to read ID register\n");
        pigpio_i2c_close(client);
        pigpio_close_bus(I2C_BUS);
        return EXIT_FAILURE;
    }

    if (pigpio_i2c_read(client, buffer, 1) != 4) {
        fprintf(stderr, "Failed to read ID register\n");
        pigpio_i2c_close(client);
        pigpio_close_bus(I2C_BUS);
        return EXIT_FAILURE;
    }

    if (buffer[0] != '0' || buffer[1] != '4' || buffer[2] != '4' || buffer[3] != '4') {
        fprintf(stderr, "Sensor ID does not match. Exiting.\n");
        pigpio_i2c_close(client);
        pigpio_close_bus(I2C_BUS);
        return EXIT_FAILURE;
    }

    pigpio_i2c_write(client, REG_ATIME, 0xFF);
    pigpio_i2c_write(client, REG_CONTROL, 0x01);
    pigpio_i2c_write(client, REG_ENABLE, 0x01 | 0x02);
    usleep(300000); // Wait 300 ms after power-on

    FILE *csv_file = fopen(COLOR_LOG_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open color_log.csv: %s\n", strerror(errno));
        pigpio_i2c_close(client);
        pigpio_close_bus(I2C_BUS);
        return EXIT_FAILURE;
    }

    time_t now = time(NULL);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(csv_file, "%s,%hd,%hd,%hd,%hd\n", buffer, clear, red, green, blue);

    fclose(csv_file);

    while (1) {
        if (pigpio_i2c_read(client, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read clear register\n");
            usleep(100000); // Wait before next read
        }

        clear = (uint16_t)strtoul(buffer, NULL, 16);
        if (pigpio_i2c_read(client, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read red register\n");
            usleep(100000); // Wait before next read
        }

        red = (uint16_t)strtoul(buffer, NULL, 16);
        if (pigpio_i2c_read(client, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read green register\n");
            usleep(100000); // Wait before next read
        }

        green = (uint16_t)strtoul(buffer, NULL, 16);
        if (pigpio_i2c_read(client, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read blue register\n");
            usleep(100000); // Wait before next read
        }

        fprintf(csv_file, "%s,%hd,%hd,%hd,%hd\n", buffer, clear, red, green, blue);

        if (feof(csv_file)) {
            // New file, write header
            fprintf(csv_file, "timestamp,clear,red,green,blue\n");
        }

        fclose(csv_file);
        usleep(1000000); // Read every second
    }

    pigpio_i2c_close(client);
    pigpio_close_bus(I2C_BUS);
    gpioTerminate();

    return EXIT_SUCCESS;
}

