#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>
#include <errno.h>

#define MCP3008_CS_PIN 8
#define MCP3008_MISO_PIN 9
#define MCP3008_MOSI_PIN 10
#define MCP3008_SCLK_PIN 11
#define MOISTURE_CHANNELS 2
#define SAMPLE_INTERVAL 5000 // 5 seconds

void spi_init(int fd) {
    if (fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    struct spi_ioc_transfer t = {
        .tx_buf = (u8 *)"0x01 0x00 0x00 0x00\0", // Command to MCP3008 to start conversion
        .rx_buf = (u8 *)"0x00 0x00 0x00 0x00\0", // Buffer to store result
        .len = 6,
        .timeout_us = 5000000
    };
    if (spidev_transmit_from_mem(fd, &t, 1) < 0) {
        perror("Failed to send command to MCP3008");
        exit(EXIT_FAILURE);
    }
}

int spi_read_data(int fd) {
    struct spi_ioc_transfer t = {
        .tx_buf = (u8 *)"0x02 0x00 0x00 0x00\0", // Command to MCP3008 to read result
        .rx_buf = (u8 *)"0x00 0x00 0x00 0x00\0", // Buffer to store result
        .len = 6,
        .timeout_us = 5000000
    };
    if (spidev_transmit_from_mem(fd, &t, 1) < 0) {
        perror("Failed to read from MCP3008");
        return -1;
    }
    return ntohs(t.rx_buf[2]);
}

void moisture_scale(int raw_value, int *moisture1, int *moisture2) {
    *moisture1 = (raw_value * 100) / 1023;
    *moisture2 = (raw_value * 100) / 1023;
}

int main(int argc, char *argv[]) {
    int spi_fd, ret;
    struct sigaction sa;

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    spi_init(spi_fd);

    // Initialize gpiod lines
    ret = gpio_request(MCP3008_CS_PIN, "mcp3008_cs");
    if (ret < 0) {
        perror("Failed to request MCP3008_CS line");
        exit(EXIT_FAILURE);
    }
    gpio_direction_output(MCP3008_CS_PIN, 0);

    // Initialize libgpiod lines
    ret = libgpiod_add_line(MCP3008_CS_PIN, 1);
    if (ret < 0) {
        perror("Failed to add MCP3008_CS line to libgpiod");
        exit(EXIT_FAILURE);
    }

    // Set CS line as output
    libgpiod_set_line_state(MCP3008_CS_PIN, 1);

    // Start reading moisture values
    while (1) {
        // Wait for 5 seconds
        usleep(SAMPLE_INTERVAL * 1000000 / 1000);

        // Read from both channels
        int moisture1, moisture2;
        int raw_value1 = spi_read_data(spi_fd);
        int raw_value2 = spi_read_data(spi_fd);

        if (raw_value1 == -1 || raw_value2 == -1) {
            // Handle error: MCP3008 not responding
            printf("Error reading from MCP3008\n");
            continue;
        }

        moisture_scale(raw_value1, &moisture1, &moisture2);

        // Log to CSV file
        char timestamp[32];
        time_r(NULL, timestamp);
        FILE *fp = fopen("moisture_log.csv", "a");
        if (!fp) {
            perror("Failed to open moisture_log.csv");
            continue;
        }
        fprintf(fp, "%s,%d,%d\n", timestamp, moisture1, moisture2);
        fclose(fp);

        // Clean up
        libgpiod_set_line_state(MCP3008_CS_PIN, 0);
        gpio_set_value(MCP3008_CS_PIN, 0);
    }

    // Clean up resources on exit
    libgpiod_del_line(MCP3008_CS_PIN);
    close(spi_fd);

    return 0;
}

