#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define MLX90817_ADDR 0x40
#define REG_PRESSURE 0x00
#define LOG_FILE "pressure_log.csv"
#define LOG_HEADER "timestamp,pressure_kPa"

void sigint_handler(int sig) {
    printf("\nCleaning up and exiting...\n");
    pigpio_terminate();
    close(logfd);
    fclose(logfp);
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
}

int main(int argc, char *argv[]) {
    int logfd, logfp;
    pigpio pi;
    struct i2c_rdwr_t i2c_wr;
    int raw_value;
    double pressure_kPa;
    time_t now;
    struct tm *t;
    char timestamp[38];

    if (signal(SIGINT, sigint_handler) == SIG_IGN || signal(SIGTERM, sigterm_handler) == SIG_IGN) {
        fprintf(stderr, "Error setting signal handlers.\n");
        return 1;
    }

    if (pigpio_init() < 0) {
        fprintf(stderr, "Error initializing pigpio.\n");
        return 1;
    }

    if (pi_open_bus(I2C_BUS) < 0) {
        fprintf(stderr, "Error opening I2C bus.\n");
        return 1;
    }

    if (pi_open_i2c(I2C_BUS) < 0) {
        fprintf(stderr, "Error opening I2C device.\n");
        return 1;
    }

    if (pi_write_i2c_block_bd(pi, MLX90817_ADDR, 0x00, &i2c_wr) < 0) {
        fprintf(stderr, "Error writing to I2C register.\n");
        return 1;
    }

    if (pi_read_i2c_block_bd(pi, MLX90817_ADDR, REG_PRESSURE, &raw_value) < 0) {
        if (errno == EIO) {
            fprintf(stderr, "Sensor not present, exiting.\n");
            return 1;
        } else {
            fprintf(stderr, "Error reading from I2C register.\n");
            return 1;
        }
    }

    pressure_kPa = (double)raw_value / 65535.0 * 500.0;

    now = time(NULL);
    t = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", t);

    if (pi_close_i2c(MLX90817_ADDR) < 0) {
        fprintf(stderr, "Error closing I2C device.\n");
        return 1;
    }

    if (pi_close_bus(I2C_BUS) < 0) {
        fprintf(stderr, "Error closing I2C bus.\n");
        return 1;
    }

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("Error opening log file");
        return 1;
    }

    logfp = fopen(LOG_FILE, "a");
    if (logfp == NULL) {
        fprintf(stderr, "Error opening log file for writing.\n");
        close(logfd);
        return 1;
    }

    fprintf(logfp, "%s,%f\n", timestamp, pressure_kPa);
    fclose(logfp);
    printf("Logged pressure: %f kPa\n", pressure_kPa);

    usleep(1000000); // Sleep for 1 second

    return 0;
}

