#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/mman.h>

#define MLX91209_ADDR 0x1A
#define MCP3008_CE 8
#define MCP3008_SCLK 11
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define LOG_FILE "current_log.txt"
#define OVERCURRENT_GPIO 27

#define ZERO_CURRENT_VOLTAGE 1.5
#define SENSITIVITY 0.0066

void spi_init(void);
void spi_transfer(uint8_t *data, size_t len);
void log_reading(const char *timestamp, float voltage, float current);
void handle_overcurrent(void);
void setup_gpio(void);
void cleanup_gpio(void);

int main(int argc, char *argv[]) {
    setup_gpio();

    pigpio_init(1); // Initialize pigpio with 1 as the PID

    spi_init();

    while (1) {
        uint8_t response[3];
        spi_transfer(response, sizeof(response));

        uint16_t adc_value = (response[0] << 8) | response[1];
        float voltage = (adc_value * 3.3) / 1024.0;
        float current = voltage / ZERO_CURRENT_VOLTAGE * SENSITIVITY;

        if (current > 10.0) {
            handle_overcurrent();
        }

        log_reading(get_timestamp(), voltage, current);
        usleep(100000); // Sleep for 100ms
    }

    cleanup_gpio();
    pigpio_terminate(1);
    return 0;
}

void spi_init(void) {
    if (gpioSetup(MCP3008_CE, PIGO_OUTPUT) < 0) {
        perror("Failed to set MCP3008 CE pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(MCP3008_SCLK, PIGO_OUTPUT) < 0) {
        perror("Failed to set MCP3008 SCLK pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(MCP3008_MOSI, PIGO_OUTPUT) < 0) {
        perror("Failed to set MCP3008 MOSI pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(MCP3008_MISO, PIGO_OUTPUT) < 0) {
        perror("Failed to set MCP3008 MISO pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(MCP3008_CE, PIGO_INPUT) < 0) {
        perror("Failed to set MCP3008 CE pin as input");
        exit(EXIT_FAILURE);
    }
}

void spi_transfer(uint8_t *data, size_t len) {
    if (gpioWrite(MCP3008_CE, 0) < 0) {
        perror("Failed to pull CE low");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < len; i++) {
        gpioWrite(MCP3008_SCLK, 0);
        gpioWrite(MCP3008_MOSI, data[i]);
        gpioWrite(MCP3008_MOSI, (data[i] >> 8) | 0x80);
        gpioWrite(MCP3008_SCLK, 1);
        usleep(0.001);
    }

    gpioWrite(MCP3008_CE, 1);
}

void log_reading(const char *timestamp, float voltage, float current) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s, %f, %f\n", timestamp, voltage, current);
    fclose(file);
}

void handle_overcurrent(void) {
    if (gpioWrite(OVERCURRENT_GPIO, 1) < 0) {
        perror("Failed to assert GPIO27");
        exit(EXIT_FAILURE);
    }

    log_reading(get_timestamp(), 0.0, 10.0); // Log OVERCURRENT event
    printf("Overcurrent detected! Motor shutdown initiated.\n");
}

void setup_gpio(void) {
    if (gpioSetup(OVERCURRENT_GPIO, PIGO_OUTPUT) < 0) {
        perror("Failed to set GPIO27 as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(GPIO27, PIGO_INPUT) < 0) {
        perror("Failed to set GPIO27 as input");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(void) {
    gpioTerminate();
    if (gpioSetup(MCP3008_CE, PIGO_OUTPUT) < 0) {
        perror("Failed to set MCP3008 CE pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(MCP3008_SCLK, PIGO_OUTPUT) < 0) {
        perror("Failed to set MCP3008 SCLK pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(MCP3008_MOSI, PIGO_OUTPUT) < 0) {
        perror("Failed to set MCP3008 MOSI pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(MCP3008_MISO, PIGO_OUTPUT) < 0) {
        perror("Failed to set MCP3008 MISO pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(MCP3008_CE, PIGO_INPUT) < 0) {
        perror("Failed to set MCP3008 CE pin as input");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(OVERCURRENT_GPIO, PIGO_INPUT) < 0) {
        perror("Failed to set GPIO27 as input");
        exit(EXIT_FAILURE);
    }
}

const char *get_timestamp(void) {
    char timestamp[64];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    return timestamp;
}

