#include <sys/stat.h>
#include <sys/types.h>
#include <sys/epoll.h>
#include <linux/spi/spidev.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0

#define LEAK_THRESHOLD 1000

#define LOG_FILE "methane_log.txt"

void spi_error_handler(const char *msg, int err) {
    fprintf(stderr, "SPI Error: %s - Error code: %d\n", msg, err);
}

int main(int argc, char *argv[]) {
    int spi_fd, ret;
    struct timeval tv;
    struct timespec ts;
    char timestamp[32];

    // Initialize pigpio
    if ((ret = gpioInitialise()) != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", piErrorString(ret));
        return 1;
    }

    // Open SPI device
    spi_fd = spiOpen(SPI_BUS, SPI_DEVICE);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    // Set SPI transfer callback
    ret = spiSetMode(spi_fd, SPI_MODE0);
    if (ret == -1) {
        fprintf(stderr, "Failed to set SPI mode\n");
        return 1;
    }
    ret = spiSetBaudRate(spi_fd, SPI_SPEED);
    if (ret == -1) {
        fprintf(stderr, "Failed to set SPI baud rate\n");
        return 1;
    }
    ret = spiSetBitsPerWord(spi_fd, 32);
    if (ret == -1) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        return 1;
    }
    ret = spiSetTransferCallback(spi_fd, spiXfer, NULL);
    if (ret == -1) {
        fprintf(stderr, "Failed to set SPI transfer callback\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        // Read ADC value
        ret = spiXfer(spi_fd, 0x01, 0x80, 0x00, 0, 3);
        if (ret == -1) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        // Extract ADC value
        uint16_t adc_value = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];

        // Convert ADC to PPM
        double concentration = (adc_value * 10.0) / 1023.0 * 5000.0;

        // Log reading with timestamp
        time(NULL) & tv;
        localtime_r(&tv, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts));
        fprintf(log_file, "%s, %d\n", timestamp, (int)concentration);

        // Check for leak alarm
        if (concentration > LEAK_THRESHOLD) {
            fprintf(stderr, "Visible leak alarm: %f PPM\n", concentration);
        }

        // Sleep for one second
        usleep(1000000);
    }

    // Handle SIGINT and SIGTERM for graceful shutdown
    if (signal(SIGINT) == SIG_IGN || signal(SIGTERM) == SIG_IGN) {
        fprintf(stderr, "Received SIGINT or SIGTERM, shutting down...\n");
        close(spi_fd);
        pigpioTerminate();
        fclose(log_file);
        return 0;
    }

    return 0;
}

// SPI transfer callback function
static int spiXfer(int fd, uint8_t *tx, uint8_t *rx, int len, void *user_data) {
    int ret;

    // Perform SPI transfer
    ret = spiWrite(fd, tx, len);
    if (ret < 0) {
        fprintf(stderr, "SPI write failed\n");
        return -1;
    }

    // Read data from SPI
    ret = spiRead(fd, rx, len);
    if (ret < 0) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }

    return 0;
}

