#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define AIN_CHANNEL 0
#define ADC_FREQ 1000 // 1Hz
#define LOG_FILE "pressure_log.txt"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S"
#define OFFSET 0.5V
#define SENSITIVITY 0.1V/kPa

#define MAX_PRESSURE_READINGS 100

void log_pressure_reading(double pressure);
void initialize_i2c();
void read_adc(int channel);
void convert_adc_to_pressure(int adc_value, double *pressure);
void handle_error(const char *msg);

int main(int argc, char *argv[]) {
    int i2c_fd, adc_fd;
    int adc_value;
    double pressure;
    struct timeval tv;
    char log_msg[100];

    initialize_i2c();

    while (1) {
        read_adc(AIN_CHANNEL);
        convert_adc_to_pressure(adc_value, &pressure);

        if (pressure >= 0 && pressure <= MAX_PRESSURE_READINGS) {
            struct timeval now;
            gettimeofday(&now, NULL);
            snprintf(log_msg, sizeof(log_msg), LOG_FORMAT " %d", (int)now.tv_sec);
            log_msg[sizeof(log_msg) - 1] = '\0';
            log_msg[sizeof(log_msg) - 1] = 'T';
            log_msg[sizeof(log_msg) - 1] = ' ';
            strcat(log_msg, std::to_string(pressure).c_str());
            strcat(log_msg, "\n");

            if (open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR) == -1) {
                handle_error("Failed to open log file for writing.");
                continue;
            }
            write(fileno(log_fd), log_msg, strlen(log_msg) + 1);
            close(fileno(log_fd));
        }

        usleep(ADC_FREQ * 1000000 / 1000); // Delay for 1 second
    }

    close(i2c_fd);
    close(adc_fd);
    pigpio_stop();
    return 0;
}

void initialize_i2c() {
    int i2c_fd = -1;
    struct i2c_rdwr_t wr;
    wr.address = I2C_ADDR;
    wr.flags = I2C_M_READ | I2C_M_WRITE;
    wr.len = 2;
    wr.buf = (uint8_t *)"01000000"; // ADS1115 register address for I2C mode

    i2c_fd = pigpio_i2c_open(I2C_BUS, &wr);
    if (i2c_fd < 0) {
        handle_error("Failed to open I2C bus.");
        exit(EXIT_FAILURE);
    }
}

void read_adc(int channel) {
    struct i2c_rdwr_t wr;
    wr.address = I2C_ADDR;
    wr.flags = I2C_M_READ;
    wr.len = 1;
    wr.buf = (uint8_t *)&channel;

    struct i2c_rdwr_t rd;
    rd.address = I2C_ADDR;
    rd.flags = I2C_M_READ;
    rd.len = 2;
    rd.buf = (uint8_t *)&adc_value;

    pigpio_i2c_transfer(i2c_fd, &wr, &rd, 2);

    if (adc_value == 0) {
        handle_error("Failed to read ADC value.");
    }
}

void convert_adc_to_pressure(int adc_value, double *pressure) {
    *pressure = (adc_value - OFFSET) * SENSITIVITY;
    if (*pressure < 0) {
        *pressure = 0;
    } else if (*pressure > MAX_PRESSURE_READINGS) {
        *pressure = MAX_PRESSURE_READINGS;
    }
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

