#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>
#include <spidev.h>

#define GPIOCHIP4 4
#define SPI0_DEVICE 0
#define SPI0_SPEED 1000000
#define SPI0_MODE 0
#define SPI0_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define ADC_SPI_DEVICE SPI0_DEVICE
#define ADC_SPI_SPEED SPI0_SPEED
#define ADC_SPI_MODE ADC_MODE_0
#define ADC_SPI_BITS_PER_WORD ADC_BITS_PER_WORD

#define VREF 3300  // 3.3V reference voltage
#define TMP36_V_REF 3300  // TMP36's reference voltage
#define TMP36_MIN_TEMP -40
#define TMP36_MAX_TEMP 125

#define LOG_FILE "temperature_log.csv"

void spi_init(int device, int speed, int mode, int bits_per_word) {
    int fd = spidev_open(device, 0);
    if (fd < 0) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }

    struct spidev_ioctl_args args = {
        .speed = speed,
        .mode = mode,
        .bits_per_word = bits_per_word
    };

    if (spidev_ioctl(fd, SPIDEV_CTL_REGISTER, &args) < 0) {
        perror("spidev_ioctl");
        spidev_close(fd);
        exit(EXIT_FAILURE);
    }
}

void spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len) {
    int ret = spidev_xfer(fd, tx, rx, len);
    if (ret < 0) {
        perror("spidev_xfer");
        exit(EXIT_FAILURE);
    }
}

int read_adc(int fd, int channel) {
    uint8_t tx_buf[2];
    tx_buf[0] = ADC_CHANNEL;
    tx_buf[1] = 0x01;  // Start conversion

    spi_transfer(fd, tx_buf, NULL, 2);

    uint8_t rx_buf[2];
    spi_transfer(fd, NULL, rx_buf, 2);

    return rx_buf[0] << 8 | rx_buf[1];
}

float adc_to_voltage(uint16_t adc_value) {
    float voltage = (adc_value * 3.3) / 4095.0;
    return voltage;
}

float voltage_to_temperature(float voltage) {
    float temp_celsius = (voltage - 0.5) / 0.01;
    if (temp_celsius < TMP36_MIN_TEMP) {
        temp_celsius = TMP36_MIN_TEMP;
    } else if (temp_celsius > TMP36_MAX_TEMP) {
        temp_celsius = TMP36_MAX_TEMP;
    }
    return temp_celsius;
}

void log_temperature(const char *timestamp, float temperature_celsius) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s,%f\n", timestamp, temperature_celsius);
    fclose(file);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        spi_close(ADC_SPI_DEVICE);
        close(fd);
        remove(LOG_FILE);
        exit(0);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd = spidev_open(ADC_SPI_DEVICE, 0);
    if (fd < 0) {
        perror("spidev_open");
        return EXIT_FAILURE;
    }

    spi_init(ADC_SPI_DEVICE, ADC_SPI_SPEED, ADC_SPI_MODE, ADC_BITS_PER_WORD);

    gpiod_set_output_eoc(GPIOCHIP4, ADC_CHANNEL);

    while (1) {
        uint16_t adc_value = read_adc(fd, ADC_CHANNEL);
        float voltage = adc_to_voltage(adc_value);
        float temperature_celsius = voltage_to_temperature(voltage);

        if (temperature_celsius < TMP36_MIN_TEMP || temperature_celsius > TMP36_MAX_TEMP) {
            fprintf(stderr, "Out of range temperature reading: %f\n", temperature_celsius);
            continue;
        }

        log_temperature(ctime(NULL), temperature_celsius);

        usleep(1000000);  // 1Hz sampling rate
    }

    spi_close(ADC_SPI_DEVICE);
    close(fd);
    remove(LOG_FILE);

    return EXIT_SUCCESS;
}

