This code sets up a Raspberry Pi 5 to read temperature data from a TMP36 sensor using an MCP3208 ADC. It uses libgpiod for GPIO control and spidev for SPI communication. The program logs readings to a CSV file, handles errors, and gracefully exits on SIGINT or SIGTERM. The MCP3208's CS line is controlled via GPIO chip 4. The SPI device is opened and closed in the main function, and the log file is closed on program exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADXL335_X_MCP_PIN 8
#define ADXL335_Y_MCP_PIN 7
#define ADXL335_Z_MCP_PIN 6
#define LOG_FILE "impact_log.txt"
#define LOG_FREQ 100
#define SENSITIVITY 0.3
#define SENSIVITY_VOLTAGE 3.3
#define SENSIVITY_GAIN 300
#define IMPACT_THRESHOLD 2.0

void spiInit(void);
void spiTransfer(uint8_t *data, size_t len);
void adcRead(int channel);
void logImpact(const char *message);
void handleInterrupt(int sig);

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(1);
    if (pi == -1) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    spiInit();

    signal(SIGINT, handleInterrupt);

    FILE *logFile = fopen(LOG_FILE, "a");
    if (!logFile) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        // Read accelerometer data
        adcRead(0);
        adcRead(1);
        adcRead(2);

        // Compute acceleration magnitude
        float x = (float)adcRead(0) / 1023.0 * SENSITIVITY * SENSIVITY_GAIN;
        float y = (float)adcRead(1) / 1023.0 * SENSITIVITY * SENSIVITY_GAIN;
        float z = (float)adcRead(2) / 1023.0 * SENSITIVITY * SENSIVITY_GAIN;

        // Calculate magnitude
        float magnitude = sqrt(x * x + y * y + z * z);

        // Log data
        if (magnitude > IMPACT_THRESHOLD) {
            logImpact("IMPACT DETECTED: Magnitude = %.2f g", magnitude);
        } else {
            fprintf(logFile, "%.6f,%.6f,%.6f\n", x, y, z);
        }

        // Sleep for desired frequency
        usleep(LOG_FREQ * 1000000 / 100);
    }

    fclose(logFile);
    pigpio_terminate(pi);
    return 0;
}

void spiInit(void) {
    if (pigpio_init(1) == -1) {
        fprintf(stderr, "Failed to initialize SPI\n");
        exit(1);
    }
}

void spiTransfer(uint8_t *data, size_t len) {
    if (pigpio_spi_transfer(pi, ADXL335_X_MCP_PIN, data, len) == -1) {
        fprintf(stderr, "SPI transfer failed\n");
        exit(1);
    }
}

void adcRead(int channel) {
    uint8_t data[2];
    spiTransfer(data, 2);

    if (data[0] & 0x01) {
        // MCP3008 chip select (CS) is low, read data
        uint8_t adcValue = data[1];
        if (adcValue < 1024) {
            // Convert to voltage
            float voltage = adcValue * 3.3 / 1023.0;
            // Convert to g using ADXL335 sensitivity
            float acceleration = voltage / SENSITIVITY * SENSIVITY_GAIN;
            // Log the value
            fprintf(logFile, "%.6f\n", acceleration);
        } else {
            fprintf(stderr, "ADC read out of range\n");
        }
    }
