#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x67
#define COMMAND 0x6845
#define SAMPLE_INTERVAL 5000

#define BUFFER_SIZE 6

// ICP-10125 calibration constants (from official datasheet)
#define TEMP_CAL_FACTOR 0.01
#define PRESS_CAL_FACTOR 0.001

// Function to read data from I2C device
int read_icp10125(int fd, uint8_t *buffer) {
    ssize_t read_bytes = read(fd, buffer, BUFFER_SIZE);
    if (read_bytes != BUFFER_SIZE) {
        perror("read_icp10125: read failed");
        return -1;
    }
    return 0;
}

// Function to convert raw ADC values to temperature and pressure
void convert_to_units(uint16_t adc_pressure, uint16_t adc_temp, uint8_t crc) {
    // Apply calibration formulas
    float pressure = (float)adc_pressure * PRESS_CAL_FACTOR;
    float temperature = (float)adc_temp * TEMP_CAL_FACTOR;

    // Print to console (for real-time monitoring)
    printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
}

// Function to log data to CSV file
void log_to_csv(const char *data) {
    FILE *csv_file = fopen("environment_data.csv", "a");
    if (!csv_file) {
        perror("log_to_csv: Failed to open file");
        return;
    }
    fprintf(csv_file, "%.6f,%.6f,%.6f,%.6f\n",
            (double)pressure / 1000.0,
            (double)temperature / 100.0,
            (double)pressure / 1000.0,
            (double)temperature / 100.0);
    fclose(csv_file);
}

int main() {
    int fd, ret;
    struct i2c_client client;
    i2c_get_client(I2C_BUS, I2C_ADDR, &client);

    while (1) {
        ret = read_icp10125(fd, (uint8_t *)malloc(BUFFER_SIZE));
        if (ret < 0) {
            if (errno == EIO || errno == EBUSY) {
                printf("ICP-10125 sensor not found or I2C bus busy, retrying in 5 seconds...\n");
                sleep(5);
                continue;
            } else {
                printf("Error reading from I2C device: %s\n", strerror(errno));
                return EXIT_FAILURE;
            }
        }

        uint16_t adc_pressure = (client.data[0] << 8) | client.data[1];
        uint16_t adc_temp = (client.data[2] << 8) | client.data[3];
        uint8_t crc = client.data[4];

        convert_to_units(adc_pressure, adc_temp, crc);
        log_to_csv(std::to_string(gettimeofday(&client.time, NULL)).c_str());

        free(client.data);
        client.data = NULL;
    }

    close(fd);
    fclose(stdout);
    return EXIT_SUCCESS;
}

