#include <mcp3008.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_SECS 60
#define LOG_FILE "moisture_log.txt"

void spi_init() {
    if (pigpioInitialise() < 0) {
        perror("Failed to initialise pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(SPI_CHANNEL, 0, PIGIO_OUTPUT) < 0) {
        perror("Failed to set up SPI channel 0");
        exit(EXIT_FAILURE);
    }
}

void adc_init() {
    if (mcp3008Init() < 0) {
        perror("Failed to initialise MCP3008");
        exit(EXIT_FAILURE);
    }
}

void log_moisture_reading(const uint16_t timestamp, const uint16_t adc_value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%04d-%02d-%02dT%02d:%02d:%02d,%hd\n",
            timestamp / 1000000, timestamp % 1000000 / 1000,
            timestamp % 1000 % 100,
            timestamp % 10000 % 60,
            timestamp % 100000 % 60,
            timestamp % 1000000 % 60,
            adc_value);

    fclose(file);
}

void sample_soil_moisture() {
    uint16_t adc_reading;
    uint32_t timestamp;

    timestamp = micros();
    adc_reading = mcp3008ReadChannel(ADC_CHANNEL);

    if (adc_reading < 0 || adc_reading > 1023) {
        fprintf(stderr, "ADC reading out of range: %d\n", adc_reading);
        return;
    }

    log_moisture_reading(timestamp / 1000000, adc_reading);
}

