#include <errno.h>
#include <libgpiod.h>
#include <spidev.h>

#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define SPI_POLARITY 0
#define SPI_PHASE 0
#define SPI_BITS_PER_WORD 8
#define BUZZER_GPIO 18

#define BUZZER_ON 1
#define BUZZER_OFF 0

#define SAMPLE_INTERVAL 500
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"

#define MCP3008_ADDRESS 0x20
#define MCP3008_SPI_MODE 0
#define MCP3008_SPI_CPOL 0
#define MCP3008_SPI_CPHA 0
#define MCP3008_SPI_DATA_BITS 10
#define MCP3008_SPI_START_BIT 0
#define MCP3008_SPI_SINGLE_ENDED 1
#define MCP3008_SPI_DUMMY_BYTE 0
#define MCP3008_SPI_TRANSFER_SIZE 3

#define KY_FLAME_SENSOR_PIN 0

int main(int argc, char *argv[]) {
    int spi_fd, buzzer_gpio;
    int mcp3008_address, mcp3008_mode, mcp3008_polarity, mcp3008_phase, mcp3008_bits_per_word,
        mcp3008_start_bit, mcp3008_single_ended, mcp3008_dummy_byte, mcp3008_transfer_size;
    int adc_value, compensated_voltage, temperature, flame_detected;
    float ambient_temp;
    struct tm tm;
    char log_entry[100];
    char *temp_str = NULL;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <ambient_temp>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Load ambient temperature
    temp_str = fopen(TEMP_FILE, "r");
    if (!temp_str) {
        ambient_temp = 25.0;
    } else {
        sscanf(temp_str, "%d", &ambient_temp);
        fclose(temp_str);
    }

    // Initialize libgpiod
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(EXIT_FAILURE);
    }

    // Open SPI device
    spi_fd = spidev_open(SPI_DEVICE, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }

    // Configure MCP3008
    mcp3008_address = MCP3008_ADDRESS;
    mcp3008_mode = MCP3008_SPI_MODE;
    mcp3008_polarity = MCP3008_SPI_CPOL;
    mcp3008_phase = MCP3008_SPI_CPHA;
    mcp3008_bits_per_word = MCP3008_BITS_PER_WORD;
    mcp3008_start_bit = MCP3008_SPI_START_BIT;
    mcp3008_single_ended = MCP3008_SPI_SINGLE_ENDED;
    mcp3008_dummy_byte = MCP3008_SPI_DUMMY_BYTE;
    mcp3008_transfer_size = MCP3008_SPI_TRANSFER_SIZE;

    // Initialize MCP3008
    if (spidev_control(spi_fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO buzzer
    buzzer_gpio = GPIO_SET_MODE(BUZZER_GPIO, GPIO_OUTPUT);
    if (buzzer_gpio < 0) {
        fprintf(stderr, "Failed to set GPIO buzzer mode\n");
        exit(EXIT_FAILURE);
    }

    // Read flame sensor data
    while (1) {
        // Read ADC value
        adc_value = 0;
        for (int i = 0; i < 3; i++) {
            if (spidev_transfer(spi_fd, &mcp3008_address, &mcp3008_mode, &mcp3008_polarity,
                                &mcp3008_phase, &mcp3008_bits_per_word, &mcp3008_start_bit,
                                &mcp3008_single_ended, &mcp3008_dummy_byte, &adc_value,
                                mcp3008_transfer_size) < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                fprintf(stderr, "Error logged to %s\n", LOG_FILE);
                GPIO_SET_OUTPUT(buzzer_gpio, BUZZER_OFF);
                continue;
            }

            // Check ADC value out of range
            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr, "ADC value out of range, retrying...\n");
                for (int j = 0; j < 3; j++) {
                    if (spidev_transfer(spi_fd, &mcp3008_address, &mcp3008_mode, &mcp3008_polarity,
                                        &mcp3008_phase, &mcp3008_bits_per_word, &mcp3008_start_bit,
                                        &mcp3008_single_ended, &mcp3008_dummy_byte, &adc_value,
                                        mcp3008_transfer_size) < 0) {
                        fprintf(stderr, "SPI transfer failed\n");
                        fprintf(stderr, "Error logged to %s\n", LOG_FILE);
                        GPIO_SET_OUTPUT(buzzer_gpio, BUZZER_OFF);
                        continue;
                    }

                    if (adc_value < 0 || adc_value > 1023) {
                        fprintf(stderr, "ADC value still out of range, retrying...\n");
                        continue;
                    }
                    break;
                }
            }

            // Compute compensated voltage
            compensated_voltage = adc_value + (ambient_temp - 25.0) * 0.001;

            // Check for flame detection
            if (compensated_voltage > 1.0) {
                flame_detected = BUZZER_ON;
            } else {
                flame_detected = BUZZER_OFF;
            }

            // Log reading
            sprintf(log_entry, "%d-%02d-%02d %02d:%02d:%02d, %d, %f, %f, %d",
                    get_current_time(&tm), tm.tm_hour, tm.tm_min, tm.tm_sec,
                    adc_value, compensated_voltage, ambient_temp, flame_detected);
            fprintf(stdout, "%s", log_entry);
            fwrite(log_entry, sizeof(char), strlen(log_entry) + 1, stdout);
            fflush(stdout);

            // Control buzzer
            GPIO_SET_OUTPUT(buzzer_gpio, flame_detected);

            // Sleep before next reading
            usleep(SAMPLE_INTERVAL * 1000000);
        }
    }

    // Clean up resources
    gpio_shutdown();
    spidev_close(spi_fd);
    fclose(temp_str);
    free(temp_str);

    return 0;
}

