#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <openssl/smtp.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define MIN_RAW_VALUE 300
#define MAX_RAW_VALUE 700
#define MOISTURE_THRESHOLD 30
#define LOG_FREQ 60
#define EMAIL_RECIPIENT "recipient@example.com"
#define MAIL_SMTP_CONFIG "/path/to/msmtp.conf"

void send_email(const char *body) {
    FILE *fp = fopen(MAIL_SMTP_CONFIG, "r");
    if (!fp) {
        perror("Failed to open msmtp config file");
        return;
    }
    char command[1024];
    snprintf(command, sizeof(command), "msmtp -a %s -t %s", getenv("USER"), body);
    FILE *pipe = popen(command, "r");
    if (!pipe) {
        perror("Failed to execute msmtp command");
        fclose(fp);
        return;
    }
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), pipe) != NULL) {
        fputs(buffer, stdout);
    }
    pclose(pipe);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int spi_fd, adc_fd, spi_channel, adc_channel, msmtp_exit_status = 0;
    struct spi_device *device;
    int adc_value;
    time_t now;
    struct tm *timeinfo;
    char timestamp[80];
    char log_entry[128];
    char email_body[1024];

    // Parse command line arguments
    if (argc != 11) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <min_raw> <max_raw> <moisture_threshold> <log_freq> <email> <msmtp_config>\n", argv[0]);
        exit(1);
    }

    spi_channel = atoi(argv[1]);
    adc_channel = atoi(argv[2]);
    min_raw = atoi(argv[3]);
    max_raw = atoi(argv[4]);
    moisture_threshold = atoi(argv[5]);
    log_freq = atoi(argv[6]);
    email_recipient = argv[7];
    msmtp_config_path = argv[8];

    // Initialize pigpio
    if (piGPIOInit(spi_channel) < 0) {
        fprintf(stderr, "Failed to initialize pigpio for SPI channel %d\n", spi_channel);
        return 1;
    }

    // Open MCP3008
    device = spiDeviceOpen(spi_fd, spi_channel);
    if (!device) {
        fprintf(stderr, "Failed to open MCP3008 device\n");
        piGPIOClose(device);
        return 1;
    }

    // Configure MCP3008
    if (spiDeviceWrite(device, 0x40, 0x00) != 0x40) {
        fprintf(stderr, "Failed to configure MCP3008\n");
        spiDeviceClose(device);
        return 1;
    }
    if (spiDeviceWrite(device, 0x42, 0x01) != 0x42) {
        fprintf(stderr, "Failed to set ADC channel\n");
        spiDeviceClose(device);
        return 1;
    }
    if (spiDeviceWrite(device, 0x43, 0x00) != 0x43) {
        fprintf(stderr, "Failed to set single-ended mode\n");
        spiDeviceClose(device);
        return 1;
    }
    if (spiDeviceWrite(device, 0x20, 0x00) != 0x20) {
        fprintf(stderr, "Failed to set sampling rate\n");
        spiDeviceClose(device);
        return 1;
    }

    // Read raw ADC value
    adc_value = spiDeviceRead(device, 0x00);

    // Calibrate raw ADC value
    double moisture_percent = (double)(min_raw - adc_value * (max_raw - min_raw)) / (max_raw - min_raw);
    printf("Current moisture: %.2f%%\n", moisture_percent);

    // Log data
    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    sprintf(log_entry, "%s, %.2f\n", timestamp, moisture_percent);
    FILE *log_file = fopen("plant_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open plant_data.txt for appending\n");
        return 1;
    }
    fprintf(log_file, log_entry);
    fclose(log_file);

    // Check for moisture threshold
    if (moisture_percent < moisture_threshold) {
        send_email(email_body);
        strcpy(email_body, "Moisture level has dropped below threshold. Current moisture: %.2f%%\n", moisture_percent);
        msmtp_exit_status = system("msmtp -a %s -t %s", getenv("USER"), email_body);
        if (mssmtp_exit_status != 0) {
            fprintf(stderr, "Email sending failed with status code %d\n", msmtp_exit_status);
        }
    }

    // Sleep before next reading
    usleep(log_freq * 1000000);

    // Clean up
    spiDeviceClose(device);
    piGPIOClose();

    return 0;
}

