#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define SPI_CLOCK_HZ 1000000
#define CALIBRATION_DRY 700
#define CALIBRATION_WET 300

#define ADC_CHANNEL 0
#define ADC_SPI_TRANSFER_SIZE 3

int spi_fd;

void spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_NRINGS, 1) == -1) {
        perror("Failed to set SPI rings");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_SPEED_HIGH) == -1) {
        perror("Failed to set SPI speed to high");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

int spi_write(uint8_t *data) {
    return write(spi_fd, data, sizeof(uint8_t) * (data[0] & 0xF0) * 2);
}

int spi_read(uint8_t *data) {
    return read(spi_fd, data, sizeof(uint8_t) * (data[0] & 0xF0) * 2);
}

int mcp3008_read_adc(uint8_t channel) {
    uint8_t command[3];
    command[0] = 0x01; // Start conversion
    command[1] = channel;
    command[2] = 0x00; // 10-bit resolution

    if (spi_write(command) != 3) {
        perror("Failed to write to MCP3008");
        return -1;
    }

    uint16_t result;
    if (spi_read(&result) != 3) {
        perror("Failed to read from MCP3008");
        return -1;
    }

    return result;
}

float calculate_moisture(uint16_t adc_value) {
    float voltage = (adc_value * 3.3) / 65535.0;
    float moisture_percentage = 100.0 - (100.0 * (voltage - CALIBRATION_DRY) / (CALIBRATION_WET - CALIBRATION_DRY));
    return moisture_percentage;
}

int main() {
    spi_init();

    while (1) {
        uint16_t adc_value = mcp3008_read_adc(ADC_CHANNEL);
        if (adc_value == -1) {
            break;
        }

        float moisture_percentage = calculate_moisture(adc_value);
        printf("Moisture Percentage: %.2f%%\n", moisture_percentage);

        usleep(5000000); // Wait for 5 seconds
    }

    close(spi_fd);
    return 0;
}

