#include <spidev.h>

#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define READ_INTERVAL 5

#define GPIO_CE0 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9

#define SPI_FILE_DESC -1

void spi_init(void) {
    int fd = spidev_open(SPI_FILE_DESC, 0);
    if (fd < 0) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }

    spi_control(fd, SPI_MODE);
    spi_control(fd, SPI_SPEED);
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    return spidev_xfer(fd, tx, len, rx);
}

int read_adc(void) {
    uint8_t command = 0x01; // Start conversion
    uint8_t data[2];

    spi_transfer(&command, data, 1);

    if (data[0] & 0x02) { // Check for error
        return -1;
    }

    return data[1];
}

float analog_to_moisture(uint16_t adc_value) {
    return (float)(adc_value - MIN_ADC_VALUE) / (MAX_ADC_VALUE - MIN_ADC_VALUE) * 100;
}

int main(void) {
    spi_init();

    while (1) {
        uint16_t adc_value = read_adc();
        if (adc_value == -1) {
            fprintf(stderr, "ADC read error\n");
            continue;
        }

        float moisture_percentage = analog_to_moisture(adc_value);
        printf("Moisture: %.2f%%\n", moisture_percentage);

        usleep(READ_INTERVAL * 1000000); // Sleep for 5 seconds
    }

    spidev_close(fd);
    return 0;
}

