#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>
#include <spidev.h>

#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define VREF 3300
#define CHANNELS 4

void spi_init(void) {
    int fd = spidev_open(SPI_DEVICE, 0);
    if (fd < 0) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }

    spi_control(fd, SPI_SPEED);
    spi_device_enable(fd);
}

void spi_close(void) {
    spi_device_disable(SPI_DEVICE);
    spi_control(SPI_DEVICE, 0);
    spidev_close(SPI_DEVICE, 0);
}

void adc_init(void) {
    gpiod_button_t button;
    gpiod_button_init(&button, GPIO_PIN_8);

    gpiod_button_set(&button, 1); // Enable CE0
}

void adc_close(void) {
    gpiod_button_set(&button, 0); // Disable CE0
}

int read_adc(int channel) {
    int spi_cmd = 0x01;
    spi_cmd |= (channel & 0x03) << 4; // Select channel

    int ret = spidev_spi_write_rd(&fd, &spi_cmd, 1);
    if (ret < 0) {
        perror("spidev_spi_write_rd");
        return -1;
    }

    ret = spidev_spi_read_rd(&fd, &data, 2);
    if (ret < 0) {
        perror("spidev_spi_read_rd");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int main(int argc, char *argv[]) {
    sigset_t sigset;
    int sig;

    // Initialize signal handlers
    sigset_t copy = sigset;
    sigaddset(&copy, SIGINT);
    sigaddset(&copy, SIGTERM);
    sigemptyset(&sigset);
    sigprocmask(SIG_BLOCK, &copy, NULL);

    // Initialize libgpiod and SPI
    spi_init();
    adc_init();

    FILE *fp = fopen("environmental_data.csv", "a");
    if (!fp) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    while (1) {
        for (int i = 0; i < CHANNELS; i++) {
            int adc_value = read_adc(i);
            if (adc_value == -1) {
                fprintf(fp, "ERROR\n");
                continue;
            }

            // Convert ADC value to voltage (assuming 3.3V reference)
            float voltage = adc_value * (3.3 / 1023.0);

            // Add timestamp and voltage to CSV
            char timestamp[20];
            time_r(timestamp);
            fprintf(fp, "%s, %f\n", timestamp, voltage);
        }

        usleep(1000000); // Sleep for 1 second
    }

    // Clean up resources
    spi_close();
    adc_close();
    fclose(fp);
    sigdelset(&sigset, SIGINT);
    sigdelset(&sigset, SIGTERM);
    sigprocmask(SIG_UNBLOCK, &copy, NULL);

    return EXIT_SUCCESS;
}

