#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define MOSI GPIO10
#define MISO GPIO9
#define SCLK GPIO11
#define SPI_CLOCK 1000000
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define LOG_BUFFER_SIZE 20
#define LOG_FILE "/tmp/moisture_log.txt"

typedef struct {
    struct timespec timestamp;
    int moisture;
    int pump_state;
} LogEntry;

LogEntry log_buffer[LOG_BUFFER_SIZE];
int log_buffer_index = 0;

void spi_init() {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file == -1) {
        perror("open /dev/spidev0.0");
        exit(1);
    }

    if (ioctl(file, SPI_IOC_NRINGS, 1) == -1) {
        perror("ioctl SPI_IOC_NRINGS");
        close(file);
        exit(1);
    }

    if (ioctl(file, SPI_IOC_SPEED_HIGH, SPI_CLOCK) == -1) {
        perror("ioctl SPI_IOC_SPEED_HIGH");
        close(file);
        exit(1);
    }

    if (ioctl(file, SPI_IOC_MODE, SPI_MODE0) == -1) {
        perror("ioctl SPI_IOC_MODE");
        close(file);
        exit(1);
    }

    if (ioctl(file, SPI_IOC_NBYTES, 3) == -1) {
        perror("ioctl SPI_IOC_NBYTES");
        close(file);
        exit(1);
    }
}

int spi_xfer(uint8_t *data) {
    return write(fileno(spidev), data, 3);
}

int spi_read(uint8_t *data) {
    return read(fileno(spidev), data, 3);
}

int gpio_init() {
    if (piGPIO_init() < 0) {
        perror("piGPIO_init");
        return -1;
    }

    if (gpioSetup(17, GPIO_OUTPUT) < 0) {
        perror("gpioSetup GPIO17");
        return -1;
    }

    return 0;
}

void water_pump_on() {
    gpioWrite(17, 1);
}

void water_pump_off() {
    gpioWrite(17, 0);
}

void log_entry(int moisture, int pump_state) {
    LogEntry entry;
    entry.timestamp = current_time();
    entry.moisture = moisture;
    entry.pump_state = pump_state;

    if (log_buffer_index < LOG_BUFFER_SIZE) {
        log_buffer[log_buffer_index] = entry;
        log_buffer_index++;
    } else {
        // Log rotation (overwrite oldest entries)
        fsync(fileno(stdout));
        write(fileno(stdout), "Log buffer is full, overwriting oldest entries.\n", 31);
    }
}

void timer_callback(int signal) {
    water_pump_off();
    spi_xfer((uint8_t[]){0x00, 0x00, 0x00}); // Reset MCP3008
    close(spidev);
    piGPIO_shutdown();
    exit(0);
}

int main() {
    signal(SIGINT, timer_callback);
    signal(SIGTERM, timer_callback);

    spi_init();

    if (gpio_init() < 0) {
        return -1;
    }

    pigpio_setup();

    while (1) {
        int moisture_reading = spi_xfer((uint8_t[]){0x00, 0x00, 0x00});
        if (moisture_reading != 3) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        int moisture = moisture_reading >> 8;
        int pump_state = moisture < LOW_THRESHOLD ? 1 : 0;

        log_entry(moisture, pump_state);
        printf("Moisture: %d, Pump State: %d\n", moisture, pump_state);

        usleep(5000000); // 5 seconds
    }

    return 0;
}

