#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define FIFO_REG 0x07
#define MODE_CONFIG 0x06
#define SPO2_CONFIG 0x08
#define LED1_PA 0x09
#define LED2_PA 0x0A
#define RED_BURST_REG 0x07
#define IR_BURST_REG 0x08

#define LOG_FILE "health_log.txt"
#define SAMPLE_INTERVAL 1000

void log_error(const char *msg) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fprintf(log, "%s", msg);
    fclose(log);
}

void log_health_info(const char *msg) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fprintf(log, "%s", msg);
    fclose(log);
}

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_client *client;
    gpioOutput pin;

    gpioInitialise();

    i2c_fd = i2cOpenChannel(I2C_BUS);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C channel");
        return EXIT_FAILURE;
    }

    client = i2cTakeChannel(i2c_fd);
    if (!client) {
        log_error("Failed to acquire I2C client");
        i2cCloseChannel(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = pigpioSetupI2C(client);
    if (ret < 0) {
        log_error("Failed to setup I2C");
        i2cTakeChannel(i2c_fd);
        i2cCloseChannel(i2c_fd);
        return EXIT_FAILURE;
    }

    log_health_info("Starting MAX30102 pulse oximeter monitoring...");

    // Verify sensor presence
    uint8_t part_id;
    ret = i2cWrite(client, MAX30102_ADDR, 0xFF, 1, &part_id);
    if (ret < 0) {
        log_error("Failed to read Part ID register");
        pigpioShutdown();
        i2cTakeChannel(i2c_fd);
        i2cCloseChannel(i2c_fd);
        return EXIT_FAILURE;
    }
    if (part_id != 0x15) {
        log_error("MAX30102 sensor not found");
        pigpioShutdown();
        i2cTakeChannel(i2c_fd);
        i2cCloseChannel(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize the sensor
    ret = i2cWrite(client, MAX30102_ADDR, MODE_CONFIG, 1, 0x40);
    if (ret < 0) {
        log_error("Failed to reset sensor");
        pigpioShutdown();
        i2cTakeChannel(i2c_fd);
        i2cCloseChannel(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = i2cWrite(client, MAX30102_ADDR, SPO2_CONFIG, 1, 0x03);
    if (ret < 0) {
        log_error("Failed to configure SpO2 mode");
        pigpioShutdown();
        i2cTakeChannel(i2c_fd);
        i2cCloseChannel(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = i2cWrite(client, MAX30102_ADDR, LED1_PA, 1, 0x24);
    if (ret < 0) {
        log_error("Failed to set LED1 PA");
        pigpioShutdown();
        i2cTakeChannel(i2c_fd);
        i2cCloseChannel(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = i2cWrite(client, MAX30102_ADDR, LED2_PA, 1, 0x24);
    if (ret < 0) {
        log_error("Failed to set LED2 PA");
        pigpioShutdown();
        i2cTakeChannel(i2c_fd);
        i2cCloseChannel(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read data from FIFO
    uint8_t red_data[3], ir_data[3];
    ret = i2cRead(client, MAX30102_ADDR, RED_BURST_REG, 6, red_data);
    if (ret < 0) {
        log_error("Failed to read red data");
        pigpioShutdown();
        i2cTakeChannel(i2c_fd);
        i2cCloseChannel(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = i2cRead(client, MAX30102_ADDR, IR_BURST_REG, 6, ir_data);
    if (ret < 0) {
        log_error("Failed to read IR data");
        pigpioShutdown();
        i2cTakeChannel(i2c_fd);
        i2cCloseChannel(i2c_fd);
        return EXIT_FAILURE;
    }

    // Compute SpO2 and heart rate
    double spO2, hr;
    spO2 = (red_data[0] + red_data[1]) / (ir_data[0] + ir_data[1]);
    hr = (ir_data[0] > ir_data[1]) ? 100 : 150; // Simple peak detection

    // Log health information
    if (spO2 < 0.95 || hr > 100) {
        time_t now = time(NULL);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
        log_health_info(printf("SpO2: %.2f, HR: %d, %s\n", spO2, hr, timestamp));
    }

    // Sleep before next sample
    usleep(SAMPLE_INTERVAL * 1000000);

    pigpioShutdown();
    i2cTakeChannel(i2c_fd);
    i2cCloseChannel(i2c_fd);

    return EXIT_SUCCESS;
