#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define BUZZER_GPIO 24
#define MQ2_ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 500
#define THRESHOLD 500

int main() {
    int buzzer_state = 0;
    int gas_value;
    pigpio pi = pigpio_init(1);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pii_strerror(pi));
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        pi_terminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(8, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", 8);
        pi_terminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        gpioWrite(BUZZER_GPIO, buzzer_state);

        // Read analog value from MQ-2 sensor via MCP3008 ADC
        if (pigpioSpiRead(0, 0, 1, &gas_value) < 0) {
            fprintf(stderr, "Failed to read from SPI0\n");
            break;
        }

        if (gas_value < THRESHOLD) {
            buzzer_state = 0;
            printf("Gas value below threshold, buzzer OFF\n");
        } else {
            buzzer_state = 1;
            printf("Gas value above threshold, buzzer ON\n");
        }

        usleep(SAMPLE_INTERVAL_MS / 1000);
    }

    gpioTerminate();
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    printf("\nExiting on SIGINT...\n");
    gpioTerminate();
    exit(0);
}

// Register signal handler
signal(SIGINT, sigint_handler);

