#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>
#include <i2c-dev.h>
#include <sys/ioctl.h>

#define RELAY_GPIO 17
#define REED_GPIO 27
#define ADC_ADDR 0x48
#define ADC_SDA 2
#define ADC_SCL 3
#define BASELINE_INTERVAL_MS 50
#define POLL_INTERVAL_MS 200
#define THRESHOLD_PERCENTAGE 80
#define LOG_FILE "/var/log/door_events.log"

#define MAX_LOG_ENTRIES 100
#define LOG_ENTRY_SIZE 1024

void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }
    time_t now = time(NULL);
    char timestamp[12];
    sprintf(timestamp, "%06d-%02d-%02d %02d:%02d:%02d",
            (now / 24) % 100, (now / 1440) % 100, (now / 86400) % 100,
            now % 24, now % 60, now % 60);
    fprintf(log_file, "%s %s\n", timestamp, event);
    fclose(log_file);
}

int main() {
    int relay_gpio = RELAY_GPIO;
    int reed_gpio = REED_GPIO;
    int adc_fd;
    int adc_address = ADC_ADDR;
    int adc_sda = ADC_SDA;
    int adc_scl = ADC_SCL;

    if ((adc_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (libgpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        close(adc_fd);
        return EXIT_FAILURE;
    }

    if (libgpiod_gpio_init(relay_gpio) != 0) {
        fprintf(stderr, "Failed to initialize GPIO for relay\n");
        close(adc_fd);
        return EXIT_FAILURE;
    }

    if (libgpiod_gpio_init(reed_gpio) != 0) {
        fprintf(stderr, "Failed to initialize GPIO for reed sensor\n");
        close(adc_fd);
        return EXIT_FAILURE;
    }

    if (libgpiod_gpio_output(relay_gpio, 1) != 0) {
        fprintf(stderr, "Failed to set relay GPIO as output\n");
        close(adc_fd);
        return EXIT_FAILURE;
    }

    if (libgpiod_gpio_output(reed_gpio, 1) != 0) {
        fprintf(stderr, "Failed to set reed sensor GPIO as output\n");
        close(adc_fd);
        return EXIT_FAILURE;
    }

    if (libgpiod_gpio_read(reed_gpio) == -1) {
        fprintf(stderr, "Failed to read reed sensor GPIO\n");
        close(adc_fd);
        return EXIT_FAILURE;
    }

    if (libgpiod_gpio_read(relay_gpio) == -1) {
        fprintf(stderr, "Failed to read relay GPIO\n");
        close(adc_fd);
        return EXIT_FAILURE;
    }

    int adc_channel = 0; // Assuming ADS1115 uses channel 0 for ADC
    int adc_value;
    int baseline_samples[MAX_LOG_ENTRIES];
    int baseline_count = 0;
    int threshold = 0;

    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        baseline_samples[i] = 0;
    }

    for (int i = 0; i < 10; i++) {
        if (i2c_ioctl(adc_fd, I2C_RDWR, adc_address, 0x40, &adc_value, 2) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break;
        }
        baseline_samples[baseline_count] = adc_value;
        baseline_count++;
        usleep(BASELINE_INTERVAL_MS * 1000 / 1000);
    }

    threshold = (baseline_samples[0] * THRESHOLD_PERCENTAGE) / 100;

    while (1) {
        if (libgpiod_gpio_read(reed_gpio) == -1) {
            fprintf(stderr, "Failed to read reed sensor GPIO\n");
            break;
        }

        if (libgpiod_gpio_read(relay_gpio) == -1) {
            fprintf(stderr, "Failed to read relay GPIO\n");
            break;
        }

        if (libgpiod_gpio_write(relay_gpio, 0) == -1) {
            fprintf(stderr, "Failed to de-energize relay\n");
            break;
        }

        usleep(POLL_INTERVAL_MS * 1000 / 1000);

        if (libgpiod_gpio_read(reed_gpio) == 0) {
            log_event("door opened");
        } else {
            log_event("door not opened");
        }

        // Simulate door lock release
        usleep(3000000); // 3 seconds

        // Re-arm the relay
        lpgio_gpio_write(relay_gpio, 1);
    }

    lpgio_gpio_cleanup();
    close(adc_fd);
    return EXIT_SUCCESS;
}

