#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <libgpiod.h>
#include <spidev.h>

#define MCP3008_CS_PINS {8, 7, 25}
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_SPI_POLARITY 0
#define MCP3008_SPI_PHASE 0
#define MCP3008_CHANNEL 0
#define LOG_INTERVAL 5000 // 5 seconds
#define CSV_HEADER "timestamp,sensor1,sensor2,sensor3"
#define CSV_FILE "soil_moisture_log.csv"

int spi_fd;
int mcp3008_chips[3];

void spi_init(void) {
    spi_fd = spidev_open(0, 0);
    if (spi_fd < 0) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }
}

void mcp3008_init(void) {
    for (int i = 0; i < 3; i++) {
        mcp3008_chips[i] = gpiod_request_pin_out(MCP3008_CS_PINS[i]);
        if (mcp3008_chips[i] < 0) {
            perror("gpiod_request_pin_out");
            exit(EXIT_FAILURE);
        }
        gpiod_pin_config_init(mcp3008_chips[i]);
        gpiod_pin_config_t *config = &gpiod_pin_config_get(mcp3008_chips[i]);
        config->default_output_level = GPIOD_OUTPUT_HIGH;
        gpiod_pin_config(mcp3008_chips[i], config);
    }
}

void spi_write(uint8_t *data) {
    spidev_hw_control(spi_fd, SPI_HDM_ACTIVE);
    spidev_hw_write(spi_fd, data, sizeof(data));
    spidev_hw_control(spi_fd, SPI_HDM_ACTIVE | SPI_HDM_SLPER);
}

int spi_read(uint8_t *data, int len) {
    spidev_hw_control(spi_fd, SPI_RD_DATA);
    return spidev_hw_read(spi_fd, data, len);
}

int mcp3008_select(int chip) {
    gpiod_pin_write(mcp3008_chips[chip], 0);
    return 1;
}

int mcp3008_deselect(int chip) {
    gpiod_pin_write(mcp3008_chips[chip], 1);
    return 1;
}

int mcp3008_read_channel(int chip) {
    spi_write((uint8_t *)"01" << 8 | (MCP3008_CHANNEL << 4));
    spi_write((uint8_t *)0x00);

    int result = spi_read((uint8_t *)&data[0], 2);
    if (result != 2) {
        return -1;
    }

    int adc_value = (data[1] << 8) | data[0];
    return adc_value;
}

void log_to_csv(int timestamp, int sensor1, int sensor2, int sensor3) {
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("fopen");
        return;
    }

    fprintf(file, "%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fclose(file);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        for (int i = 0; i < 3; i++) {
            mcp3008_deselect(i);
        }
        spi_close(spi_fd);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();
    mcp3008_init();

    struct itimerspec timerspec;
    timerspec.timerspec_sec = LOG_INTERVAL / 1000;
    timerspec.timerspec_rem = 0;
    timeradd(&timerspec, timerinfo, &timerspec);

    while (1) {
        int sensor1 = mcp3008_read_channel(0);
        int sensor2 = mcp3008_read_channel(1);
        int sensor3 = mcp3008_read_channel(2);

        if (sensor1 == -1 || sensor2 == -1 || sensor3 == -1) {
            log_to_csv(get_timestamp(), -1, -1, -1);
        } else {
            log_to_csv(get_timestamp(), sensor1, sensor2, sensor3);
        }

        usleep(timerspec.timerspec_rem);
    }

    spi_close(spi_fd);
    for (int i = 0; i < 3; i++) {
        mcp3008_deselect(i);
    }
    return 0;
}

