#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <sys/mman.h>

#define GPIO_RELAY 18
#define GPIO_CE0 8
#define SPI_CLOCK_HZ 1000000
#define SPI_MODE 0
#define DRY_THRESHOLD 200
#define WET_THRESHOLD 800
#define DEFAULT_DURATION 10000
#define DEFAULT_SLEEP_INTERVAL 60000

#define LOG_FILE "irrigation.log"

void spi_init(void);
void gpio_init(void);
void spi_read_mcp3008(uint16_t channel, uint16_t *raw_value);
void log_moisture_reading(uint16_t moisture);
void activate_pump(uint32_t duration);
void deactivate_pump(void);
void handle_signal(int signum);

int main(int argc, char *argv[]) {
    int ret;
    struct sigaction sa;
    pid_t pump_pid;

    spi_init();
    gpio_init();

    // Parse command-line options
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0) {
            threshold = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-d") == 0) {
            duration = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-s") == 0) {
            sleep_interval = atoi(argv[i + 1]);
            i++;
        }
    }

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read moisture sensor
        uint16_t raw_value;
        spi_read_mcp3008(0, &raw_value);
        moisture = (raw_value * 100) / 1023.0;

        // Log moisture reading
        log_moisture_reading(moisture);

        // Check moisture threshold and activate/deactivate pump
        if (moisture < threshold) {
            activate_pump(duration);
        } else {
            deactivate_pump();
        }

        // Sleep before next reading
        usleep(sleep_interval * 1000);
    }

    // Clean up and exit
    deactivate_pump();
    close(GPIO_RELAY);
    pigpio_terminate(1);
    fclose(LOG_FILE);
    return 0;
}

void spi_init(void) {
    int file = open(SPI0_FILE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (file < 0) {
        perror("open SPI0");
        exit(EXIT_FAILURE);
    }

    struct spi_fd *fd = (struct spi_fd *)mmap(NULL, SPI_FD_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, file, 0);
    if (fd == MAP_FAILED) {
        perror("mmap for SPI0");
        close(file);
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    spi_device_configure(fd, SPI_CLOCK_HZ, SPI_MODE);

    // Set up retries for SPI read
    int retries = 3;
    int ret;
    while (retries > 0) {
        ret = spi_transfer(fd, (const uint8_t *)NULL, 0, (const uint8_t *)NULL, 0);
        if (ret == 0) {
            break;
        }
        retries--;
        usleep(100000); // Wait before retry
    }
    if (ret != 0) {
        fprintf(stderr, "Failed to read from SPI after %d retries\n", retries);
        exit(EXIT_FAILURE);
    }
}

void gpio_init(void) {
    if (pigpio_init() != 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

void spi_read_mcp3008(uint16_t channel, uint16_t *raw_value) {
    uint8_t command[2] = {SPI_CMD_MCP3008_READ_CHANNEL, channel};
    spi_transfer(SPI0_FD, (const uint8_t *)command, 2, (uint8_t *)NULL, 2);

    // Read 16-bit value from MCP3008
    uint16_t value;
    spi_transfer(SPI0_FD, (const uint8_t *)&value, 2, (uint8_t *)NULL, 2);
    *raw_value = value;
}

void log_moisture_reading(uint16_t moisture) {
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s: Moisture: %d\n", timestamp, moisture);
    fclose(log_file);
}

void activate_pump(uint32_t duration) {
    ret = pigpio_set_mode(GPIO_RELAY, PIGPIO_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO18 as output\n");
        exit(EXIT_FAILURE);
    }

    ret = pigpio_write(GPIO_RELAY, 1);
    if (ret != 0) {
        fprintf(stderr, "Failed to activate pump\n");
        exit(EXIT_FAILURE);
    }

    usleep(duration * 1000000); // Wait for duration

    ret = pigpio_write(GPIO_RELAY, 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to deactivate pump\n");
        exit(EXIT_FAILURE);
    }
}

void deactivate_pump(void) {
    ret = pigpio_set_mode(GPIO_RELAY, PIGPIO_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO18 as input\n");
        exit(EXIT_FAILURE);
    }
}

void handle_signal(int signum) {
    deactivate_pump();
    close(GPIO_RELAY);
    pigpio_terminate(1);
    fprintf(stderr, "Received signal, shutting down pump and exiting\n");
    exit(signum == SIGINT || signum == SIGTERM ? 0 : EXIT_FAILURE);
}

