#include <errno.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/epoll.h>

#define ADC_CHANNEL 0
#define SPI_CLOCK_FREQ 1000000
#define ADC_SPI_POLARITY 0
#define ADC_SPI_PHASE 0
#define ADC_SPI_DATA_BITS 8
#define ADC_SPI_ADDRESS 0x20
#define ADC_SPI_CE_PIN 8
#define ADC_SPI_CLK_PIN 11
#define ADC_SPI_MOSI_PIN 10
#define ADC_SPI_MISO_PIN 9
#define EMA_THRESHOLD 0.2
#define LOG_FILE "/var/log/sound_events.log"
#define SAMPLE_INTERVAL_MS 10

#define MAX_PEAKS 10

void spi_init();
void pigpio_init();
void spi_read_adc(int channel);
void ema_update(int *ema, int new_value);
void log_peak(int value);
void signal_handler(int signum);

int main(int argc, char *argv[]) {
    pigpio pi;
    int spi_fd, adc_fd;
    int adc_channel = ADC_CHANNEL;
    int spi_ce_pin = ADC_SPI_CE_PIN;
    int spi_clk_pin = ADC_SPI_CLK_PIN;
    int spi_mosi_pin = ADC_SPI_MOSI_PIN;
    int spi_miso_pin = ADC_SPI_MISO_PIN;
    int spi_address = ADC_SPI_ADDRESS;
    int spi_polarity = ADC_SPI_POLARITY;
    int spi_phase = ADC_SPI_PHASE;
    int spi_clock_freq = SPI_CLOCK_FREQ;
    int ema_threshold = EMA_THRESHOLD;
    int max_peaks = MAX_PEAKS;
    int peak_buffer[max_peaks];
    int peak_index = 0;
    int peak_count = 0;
    int peak_value;
    int peak_timestamp;
    FILE *log_file;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (spi_init() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        spi_read_adc(adc_channel);
        ema_update(&peak_value, adc_channel);

        if (peak_count < max_peaks) {
            peak_buffer[peak_count] = adc_channel;
            peak_count++;
        } else {
            peak_buffer[peak_index] = adc_channel;
            peak_index = (peak_index + 1) % max_peaks;
        }

        if (peak_value > ema_threshold * peak_buffer[peak_index]) {
            peak_value = ema_threshold * peak_buffer[peak_index];
            peak_timestamp = (int)(clock() * 1000 / CLOCKS_PER_SEC);
            log_peak(peak_value);
            peak_index = (peak_index + 1) % max_peaks;
            peak_count--;
        }

        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
    }

    fclose(log_file);
    pigpio_terminate();
    spi_close();
    return 0;
}

void spi_init() {
    spi_fd = open("/dev/spidev0.0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_NRINGS, 1) < 0) {
        perror("Failed to set SPI ring count");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_SPEED_HIGH, spi_clock_freq) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_POLARITY(0), spi_polarity) < 0) {
        perror("Failed to set SPI polarity");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_PHASE(0), spi_phase) < 0) {
        perror("Failed to set SPI phase");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void pigpio_init() {
    if (pi_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

void spi_read_adc(int channel) {
    uint8_t data[2];
    int result = read(spi_fd, data, 2);
    if (result == -1) {
        perror("Failed to read from SPI");
        exit(EXIT_FAILURE);
    }

    int adc_value = (data[0] << 8) | data[1];
    pi_set_mode(channel, PI_OUTPUT);
    pi_write(channel, 0);
    pi_pulse(channel, 0, 1000);
    pi_pulse(channel, 1, 1000);
    pi_pulse(channel, 0, 1000);
    pi_read(channel);
    adc_value = pi_read();
    pi_pulse(channel, 0, 1000);
    pi_pulse(channel, 1, 1000);
    pi_pulse(channel, 0, 1000);
    pi_read(channel);
}

void ema_update(int *ema, int new_value) {
    *ema = ema ? (ema * 0.8 + new_value * 0.2) : new_value;
}

void log_peak(int value) {
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(log_file, "%s %d\n", timestamp, value);
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    pi_terminate();
    close(spi_fd);
    fclose(log_file);
    exit(0);
}

void spi_close() {
    close(spi_fd);
}

