#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define PCF8591_ADDRESS 0x48
#define SAMPLE_INTERVAL_MS 100

int main() {
    int fd;
    struct i2c_client *client;
    uint8_t control_byte = 0x00; // Single-ended mode, AIN0, Analog output disabled
    uint16_t sample;

    // Initialize libgpiod
    if (gpio_init() != 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(fd);
    if (!client) {
        perror("Failed to allocate I2C client");
        exit(EXIT_FAILURE);
    }

    control_byte |= 0x01; // Set control byte for single-ended mode on AIN0, Analog output enabled
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        i2c_free(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, WHO_AM_I, &client->who) < 0) {
        perror("Failed to get device information");
        i2c_free(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_MEM_WRITE, PCF8591_ADDRESS, &control_byte, 1) < 0) {
        perror("Failed to write control byte");
        i2c_free(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Perform a dummy read first to get the previous sample
        sample = i2c_mem_read(fd, PCF8591_ADDRESS, 0);
        if (sample == -1) {
            perror("Failed to read dummy sample");
            continue;
        }

        // Read the current sample
        sample = i2c_mem_read(fd, PCF8591_ADDRESS, 1);
        if (sample == -1) {
            perror("Failed to read current sample");
            continue;
        }

        // Discard the dummy sample
        sample = 0;

        // Print the current sample value
        printf("Sample: %d\n", sample);

        // Wait for the specified interval before the next read
        usleep(SAMPLE_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    // Clean up
    i2c_free(client);
    close(fd);
    gpio_shutdown();

    return EXIT_SUCCESS;
}

