#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define BUFFER_SIZE 10
#define THRESHOLD 500
#define GPIO27 27

#define LOG_FACILITY "sensor"
#define LOG_PRIORITY syslog_error

#define I2C_ADDR 0x48
#define ADC_CHANNEL AIN0

#define SS49E_ZERO_FIELD 2.5
#define SS49E_SENSITIVITY 0.0014
#define VCC 3.3

typedef struct {
    int16_t buffer[BUFFER_SIZE];
    int head;
    int tail;
} CircularBuffer;

void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

void log_info(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

void log_warning(const char *msg) {
    syslog(LOG_WARNING, "%s", msg);
}

void init_syslog() {
    openlog(NULL, LOG_PID, LOG_DAEMON);
}

void cleanup_syslog() {
    closelog();
}

int main(int argc, char *argv[]) {
    init_syslog();

    pigpio_init(1);
    if (pigpio_open_gpio(GPIO27) < 0) {
        log_error("Failed to open GPIO27");
        cleanup_syslog();
        return 1;
    }

    pigpio_setmode(GPIO27, PIGIO_OUTPUT);

    CircularBuffer cb = {0};
    int cb_head = 0, cb_tail = 0;

    while (1) {
        int sensor_value = 0;
        int i2c_result = i2c_transfer(I2C_ADDR, 0x00, 0x48, 0, &sensor_value, 1);
        if (i2c_result < 0) {
            log_warning("I2C transfer failed");
            continue;
        }

        if (sensor_value > 32767) {
            log_warning("Sensor value out of range (0-32767)");
            continue;
        }

        int raw_value = sensor_value;
        int magnetic_field = (raw_value - SS49E_ZERO_FIELD) * SS49E_SENSITIVITY / VCC;

        if (cb_head == cb_tail) {
            cb_tail++;
        }

        cb.buffer[cb_head] = magnetic_field;
        cb_head++;

        if (cb_head == BUFFER_SIZE) {
            cb_head = 0;
        }

        int rolling_avg = 0;
        for (int i = cb_tail - BUFFER_SIZE + 1; i <= cb_head - 1; i++) {
            rolling_avg += cb.buffer[i];
        }
        rolling_avg /= BUFFER_SIZE;

        if (rolling_avg > THRESHOLD) {
            pigpio_write(GPIO27, 1);
            log_info("Threshold exceeded, driving GPIO27 HIGH");
        }

        log_info("Magnetic field: %d Gauss", magnetic_field);

        usleep(1000000 / 1000); // 1 Hz sampling rate
    }

    cleanup_syslog();
    pigpio_close_gpio(GPIO27);
    pigpio_cleanup();
    return 0;
}

