#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define MCP3008_CE0 2
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define ADC_FULL_SCALE 1023
#define RAINFALL_INTENSITY_LEVELS 11

void spi_init(void);
void spi_xfer(uint16_t address, uint8_t *data);
void read_adc(uint8_t *data);
void map_adc_to_rainfall(uint16_t adc_value, int *rainfall_intensity);
void log_reading(const char *timestamp, int adc_value, int rainfall_intensity);

int main(int argc, char *argv[]) {
    spi_init();

    pigpio pi = pigpio_begin(NULL);
    if (!pi) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_strerror());
        return 1;
    }

    while (1) {
        read_adc((uint8_t *)NULL);
        int rainfall_intensity = 0;
        map_adc_to_rainfall(adc_value, &rainfall_intensity);
        log_reading(ctime(NULL), adc_value, rainfall_intensity);
        usleep(1000000); // Sleep for 1 second
    }

    pigpio_terminate(pi);
    return 0;
}

void spi_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioErrorString());
        exit(1);
    }

    if (spiInit(MCP3008_CE0, SPI_MODE, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to initialize SPI: %s\n", spiErrorString());
        exit(1);
    }
}

void spi_xfer(uint16_t address, uint8_t *data) {
    if (spiTransfer(address, data, 1) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", spiErrorString());
        // Retry on the next cycle
    }
}

void read_adc(uint8_t *data) {
    if (data == NULL) {
        fprintf(stderr, "Invalid data pointer\n");
        return;
    }

    spi_xfer(0x40, data); // Read from MCP3008 register 0x40 for ADC data
    if (spiTransfer(0x00, data, 1) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", spiErrorString());
        return;
    }

    uint16_t adc_value = (data[0] << 8) | data[1];
    map_adc_to_rainfall(adc_value, NULL);
}

void map_adc_to_rainfall(uint16_t adc_value, int *rainfall_intensity) {
    if (rainfall_intensity == NULL) {
        fprintf(stderr, "Invalid rainfall intensity pointer\n");
        return;
    }

    *rainfall_intensity = (int)((adc_value * 10.0) / ADC_FULL_SCALE) * RAINFALL_INTENSITY_LEVELS;
}

void log_reading(const char *timestamp, int adc_value, int rainfall_intensity) {
    printf("%s: ADC Value = %d, Rainfall Intensity = %d\n", ctime(NULL), adc_value, rainfall_intensity);
}

