    if (pi_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI
    spi_init();

    // Initialize PWM
    pwm_init();

    // Initialize ADC
    adc_init();

