    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int adc_value = read_adc();
        int duty_cycle = map_adc_to_duty_cycle(adc_value);
        update_pwm(duty_cycle);
        printf("ADC: %d, PWM: %d\n", adc_value, duty_cycle);
        usleep(100000); // Sleep for 100 ms
    }

    // Clean up and exit
    pi_terminate();
    return 0;
}

