#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define ADC_ADDRESS 0x48
#define LED_GPIO 17
#define ADC_CHANNEL 0
#define ADC_GAIN 4
#define MAG_THRESHOLD 100.0

int main(int argc, char *argv[]) {
    int led_gpio = LED_GPIO;
    int adc_channel = ADC_CHANNEL;
    int adc_gain = ADC_GAIN;
    double threshold = MAG_THRESHOLD;
    int i2c_fd;
    int adc_read_count;
    float adc_value;
    double gauss_value;

    if (argc < 2) {
        threshold = MAG_THRESHOLD;
    }

    pigpio_init(1); // Initialize pigpio with 1 as the number of available outputs (GPIO pins)

    if (i2c_fd == -1) {
        perror("I2C initialization failed");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    if (i2c_write(i2c_fd, 0x48, 0x01, 2) == -1) {
        perror("I2C write to ADS1115 failed");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, &adc_channel, 1) == -1) {
        perror("I2C read from ADS1115 failed");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, &adc_gain, 1) == -1) {
        perror("I2C read from ADS1115 failed");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, &adc_read_count, 1) == -1) {
        perror("I2C read from ADS1115 failed");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    if (adc_read_count == 0) {
        perror("ADS1115 read count is zero, check hardware connection.");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    gauss_value = (adc_value * 1000.0) / (adc_gain * 4.096);

    if (gauss_value > threshold) {
        gpioOutput(led_gpio, 1); // Turn LED on
        while (1) {
            gpioOutput(led_gpio, 0); // Turn LED off
            usleep(50000); // Delay for 50 ms
            gpioOutput(led_gpio, 1); // Turn LED on
            usleep(50000); // Delay for 50 ms
        }
    }

    printf("Magnetic field strength: %.2f Gauss\n", gauss_value);

    pigpio_terminate();
    close(i2c_fd);
    return 0;
}

