#define HYS_HIGH_THRESHOLD 35

#define LOG_TAG "soil_moisture_controller"

int relay_state = 0;
int moisture_level = 0;
int last_moisture_level = 0;

void spi_init(void);
void gpio_init(void);
void mqtt_init(void);
void read_moisture(void);
void publish_moisture(int moisture_level);
void handle_mqtt_message(mqtt_client *client, mqtt_message *msg);
void handle_relay_command(mqtt_message *msg);
void handle_error(const char *msg, int err);
void cleanup(void);

int main(int argc, char *argv[]) {
    syslog(LOG_INFO, "Starting soil moisture controller");

    spi_init();
    gpio_init();
    mqtt_init();

    while (1) {
        read_moisture();
        publish_moisture(moisture_level);
        usleep(60000000); // 60 seconds
    }

    cleanup();
    syslog(LOG_INFO, "Controller exited");
    return 0;
}

void spi_init(void) {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file < 0) {
        handle_error("Failed to open SPI device", errno);
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = (void *)0,
        .rx_buf = (void *)0,
        .len = 0,
        .speed_hz = SPI_CLOCK_HZ
    };

    if (ioctl(file, SPI_IOC_TRANSFER, &spi_transfer) < 0) {
        handle_error("Failed to initialize SPI", errno);
        exit(EXIT_FAILURE);
    }

    close(file);
}

void gpio_init(void) {
    if (pigpio_init() < 0) {
        handle_error("Failed to initialize pigpio", errno);
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_MCP3008, PI_OUTPUT);
    gpioWrite(GPIO_MCP3008, 0); // Set CE0 low to enable MCP3008
}

void mqtt_init(void) {
    paho_mqtt_client_handle client;
    paho_mqtt_client_config_init(&client);
    paho_mqtt_client_connect_options_init(&client);

    paho_mqtt_client_set_callback(client, handle_mqtt_message, NULL);
    paho_mqtt_client_set_callback(client, handle_relay_command, NULL);

    if (paho_mqtt_client_connect(client, MQTT_HOST, MQTT_PORT, 0, MQTT_KEEPALIVE_INTERVAL, NULL, NULL) != MQTT_SUCCESS) {
        handle_error("Failed to connect to MQTT broker", errno);
        exit(EXIT_FAILURE);
    }

    if (paho_mqtt_client_subscribe(client, MQTT_SUBSCRIBE_TOPIC, 0, NULL) != MQTT_SUCCESS) {
        handle_error("Failed to subscribe to MQTT topic", errno);
        exit(EXIT_FAILURE);
    }
}

void read_moisture(void) {
    int channel = MCP3008_CHANNEL;
    int adc_value = 0;

    if (pigpio_digital_read(GPIO_MCP3008, channel) == 0) {
        adc_value = pigpio_analog_read(GPIO_MCP3008, channel);
        moisture_level = (adc_value * 3.3) / 65535.0; // Convert to percentage

        if (moisture_level < HYS_LOW_THRESHOLD) {
            relay_state = 1; // Activate relay
        } else if (moisture_level > HYS_HIGH_THRESHOLD) {
            relay_state = 0; // Deactivate relay
        }

        if (last_moisture_level != moisture_level) {
            publish_moisture(moisture_level);
            last_moisture_level = moisture_level;
        }
    }
}

void publish_moisture(int moisture_level) {
    char message[100];
    sprintf(message, "soil_moisture=%d", moisture_level);
    if (paho_mqtt_publish(client, MQTT_TOPIC, message, strlen(message), 0) != MQTT_SUCCESS) {
        handle_error("Failed to publish moisture reading", errno);
    }
}

void handle_mqtt_message(mqtt_client *client, mqtt_message *msg) {
    if (strcmp(msg->topic, MQTT_SUBSCRIBE_TOPIC) == 0) {
        if (strcmp(msg->payload, "pump_on") == 0) {
            relay_state = 1;
        } else if (strcmp(msg->payload, "pump_off") == 0) {
            relay_state = 0;
        }
    }
}

void handle_relay_command(mqtt_message *msg) {
    if (strcmp(msg->topic, MQTT_SUBSCRIBE_TOPIC) == 0) {
        if (strcmp(msg->payload, "pump_on") == 0) {
            relay_state = 1;
        } else if (strcmp(msg->payload, "pump_off") == 0) {
            relay_state = 0;
        }
    }
}

void handle_error(const char *msg, int err) {
    syslog(LOG_ERR, "%s: %s", msg, strerror(err));
}

void cleanup(void) {
    paho_mqtt_client_disconnect(client);
    paho_mqtt_client_cleanup(client);
    pigpio_terminate();
    close(relay_state);
    syslog(LOG_INFO, "Resources released");
}

