#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_CLOCK 1000000

#define MCP3008_ADDR 0x29
#define MCP3008_CMD_START 0x01
#define MCP3008_CONFIG_SINGLE_ENDED 0x00
#define MCP3008_CONFIG_CHANNEL_0 0x00
#define MCP3008_CONFIG_BYTE 0x00

#define VREF 3.3

int main() {
    int fd;
    spi_io_ctrl_t ctrl;
    uint8_t cmd[3];

    fd = open(SPI_DEV, O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ctrl.mode = SPI_MODE;
    ctrl.lclkhdiv = SPI_CLOCK / 100000;
    ctrl.bdkhdiv = SPI_CLOCK / 100000;
    ctrl.csbclk = SPI_MODE;
    ctrl.nss = 8;

    if (spidev_ioctl(fd, SPI_IOC_MESSAGE, &ctrl) < 0) {
        perror("spidev_ioctl");
        close(fd);
        exit(EXIT_FAILURE);
    }

    memset(cmd, MCP3008_CMD_START | MCP3008_CONFIG_SINGLE_ENDED | MCP3008_CONFIG_CHANNEL_0, 3);

    if (spidev_write_cd(fd, cmd) < 0) {
        perror("spidev_write_cd");
        close(fd);
        exit(EXIT_FAILURE);
    }

    uint16_t result;
    if (spidev_read_cd(fd, &result, 2) < 0) {
        perror("spidev_read_cd");
        close(fd);
        exit(EXIT_FAILURE);
    }

    uint8_t data[3];
    data[0] = result >> 8;
    data[1] = result & 0xFF;
    data[2] = 0x00;

    printf("Raw value: 0x%04X\n", result);
    double voltage = (double)data[0] * VREF / 1024.0;
    printf("Voltage: %.3f V\n", voltage);

    usleep(500000);

    return 0;
}

