#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>
#include <spidev.h>
#include <linux/spi/spidev.h>

#define MAX_NOISE_LEVEL 500
#define ADC_CHANNEL 0
#define SPI_DEVICE 0
#define SPI_SPEED 10000000
#define ADC_SPI_FILE "/dev/spidev0.0"
#define VIBRATION_MOTOR_GPIO17 17
#define VIBRATION_MOTOR_GPIO27 27

#define LOG_FILE "vibration_log.txt"

void log_event(const char *timestamp, int adc_value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t now = time(NULL);
    fprintf(file, "%s: ADC: %d\n", ctime(&now), adc_value);
    fclose(file);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(1);
    if (!pi) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_strerror());
        return 1;
    }

    spi_init(SPI_DEVICE, SPI_SPEED);
    if (!spi_present(SPI_DEVICE)) {
        fprintf(stderr, "SPI device not found: %s\n", strerror(errno));
        pigpio_terminate(pi);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        pigpio_terminate(pi);
        return 1;
    }

    while (1) {
        struct spidev_xfer xfer;
        xfer.header = SPID_HEADER;
        xfer.len = 1;
        xfer.addr = 0;
        xfer.data[0] = ADC_CHANNEL;

        int adc_value = 0;
        if (spidev_xfer(&xfer) < 0) {
            fprintf(stderr, "Error reading ADC: %s\n", strerror(errno));
            continue;
        }

        int adc_value_scaled = adc_value / 1023.0;
        if (adc_value_scaled < 0.005) {
            // Noise level below threshold, turn motors off
            pi_stop(VIBRATION_MOTOR_GPIO17);
            pi_stop(VIBRATION_MOTOR_GPIO27);
        } else {
            // Map ADC value to PWM duty cycle
            int duty_cycle = (int)(adc_value_scaled * 255);
            pi_set_duty_cycle(VIBRATION_MOTOR_GPIO17, duty_cycle);
            pi_set_duty_cycle(VIBRATION_MOTOR_GPIO27, duty_cycle);

            // Log the event
            log_event(ctime(NULL), adc_value);
        }

        usleep(10000); // Wait for 10 ms
    }

    pigpio_terminate(pi);
    fclose(log_file);
    return 0;
}

