#define SPI_CHANNEL 0
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_INTERVAL 60

#define MAX_RETRIES 3

void spi_init() {
    int spi_device = spidev_open(0, 0);
    if (spi_device < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }
}

void pigpio_init() {
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

int read_analog_channel(int channel) {
    int retries = 0;
    int value = -1;

    while (retries < MAX_RETRIES) {
        value = pigpio_read_digital_pin(channel);
        if (value != -1) {
            break;
        }
        retries++;
        usleep(100000); // Wait for 100ms before retry
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read analog value after %d retries\n", MAX_RETRIES);
        return -1;
    }

    return value;
}

void water_pump_on() {
    pigpio_put(RELAY_GPIO, 1);
}

void water_pump_off() {
    pigpio_put(RELAY_GPIO, 0);
}

void log_moisture_reading(float moisture) {
    time_t now = time(NULL);
    char timestamp[80];
    sprintf(timestamp, "%.2f - %d:%02d:%02d", moisture, now / 3600, (now % 3600) / 60, now % 60);
    printf("%s\n", timestamp);
}

