    spi_init();
    pigpio_init();

    int mcp3008_channel = 0; // MCP3008 channel 0 (CH0)
    int mcp3008_value = read_analog_channel(mcp3008_channel);

    if (mcp3008_value == -1) {
        return EXIT_FAILURE;
    }

    float moisture = mcp3008_value * (3.0 / 1023.0);

    if (moisture < MOISTURE_THRESHOLD) {
        water_pump_on();
        log_moisture_reading(moisture);
    } else {
        water_pump_off();
    }

    usleep(LOG_INTERVAL * 1000000); // Wait for LOG_INTERVAL ms

    signal(SIGINT, sigterm_handler);
    signal(SIGTERM, sigterm_handler);

    return 0;

sigterm_handler:
    water_pump_off();
    spi_close();
    pigpio_terminate();
    return EXIT_SUCCESS;
}

