#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/time.h>

#define SPI_BUS 0
#define MCP3008_CHANNEL 0
#define CO2_CALIBRATION_SLOPE 0.5
#define CO2_CALIBRATION_INTERCEPT -50
#define SAMPLE_INTERVAL 5000 // 5 seconds
#define FAN_GPIO 18

#define LOG_FILE "air_quality.log"

void log_reading(const char *timestamp, float co2_ppm, int fan_state) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s,%f,%d\n", ctime(&now), co2_ppm, fan_state);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int spi_fd, fan_gpio;
    float adc_reading;
    int fan_state = 0;
    int retry_count = 0;

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    fan_gpio = fileno(open(argv[1], "r"));
    if (fan_gpio < 0) {
        perror("Failed to open fan GPIO");
        return EXIT_FAILURE;
    }

    pigpio_init(1); // Initialize pigpio with 1 as the number of available pins

    while (1) {
        // Read from MCP3008 channel 0
        if (spi_write(spi_fd, 0x01) == -1) {
            perror("Failed to write to MCP3008");
            retry_count++;
            if (retry_count > 5) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                pigpio_terminate(1);
                return EXIT_FAILURE;
            }
            continue;
        }

        adc_reading = spi_read(spi_fd);
        if (adc_reading == -1) {
            perror("Failed to read from MCP3008");
            retry_count++;
            if (retry_count > 5) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                pigpio_terminate(1);
                return EXIT_FAILURE;
            }
            continue;
        }

        // Calibration
        float co2_ppm = (adc_reading * CO2_CALIBRATION_SLOPE) + CO2_CALIBRATION_INTERCEPT;

        // Log reading
        log_reading(ctime(NULL), co2_ppm, fan_state);

        // Check if fan should be on
        if (co2_ppm > 700) {
            fan_state = 1;
        } else {
            fan_state = 0;
        }

        // Turn fan on/off
        if (fan_state) {
            write(fan_gpio, 1);
        } else {
            write(fan_gpio, 0);
        }

        // Wait for next sample
        usleep(SAMPLE_INTERVAL * 1000000 / 1000); // Convert to microseconds
    }

    pigpio_terminate(1);
    close(fan_gpio);
    close(spi_fd);
    return EXIT_SUCCESS;
}

