#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>
#include <spidev.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define MCP3008_ADDRESS 0x68
#define GPIO_RELAY 17
#define SPI_CLOCK_HZ 10000000
#define DEBOUNCE_DELAY 1000
#define LOG_FILE "door_events.log"

void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fp, "%s", event);
    fclose(fp);
}

void handle_signal(int signum) {
    log_event("Received SIGINT, cleaning up resources");
    // Add cleanup code here if needed
}

int main(int argc, char *argv[]) {
    int fd;
    struct spidev_dev *dev;
    gpiopin_t relay_pin;
    gpiopin_t *gpio_pins[2];
    gpiopin_direction_t pin_directions[2];
    gpiopin_t *adc_channel;
    uint32_t adc_value;
    uint32_t last_adc_value = 0;
    uint32_t proximity_detected = 0;
    uint32_t debounced = 0;
    uint32_t last_debounce_time = 0;
    unsigned long last_event_time = 0;

    gpio_request(GPIO_RELAY, GPIOPIN_OUTPUT);
    if (gpio_direction_output(GPIO_RELAY) == -1) {
        perror("Failed to set GPIO_RELAY as output");
        return -1;
    }

    relay_pin = GPIO_RELAY;

    gpio_request(0, SPI_BUS);
    if (spi_bus_setup(SPI_BUS, SPI_DEVICE) == -1) {
        perror("Failed to set up SPI bus");
        return -1;
    }

    dev = spi_alloc_device(0, SPI_DEVICE);
    if (!dev) {
        perror("Failed to allocate SPI device");
        return -1;
    }

    adc_channel = (gpiopin_t *)malloc(sizeof(gpiopin_t));
    if (!adc_channel) {
        perror("Failed to allocate memory for ADC channel");
        return -1;
    }

    pin_directions[0] = GPIOPIN_INPUT;
    pin_directions[1] = GPIOPIN_INPUT;

    gpio_pin_configure(GPIO_RELAY, pin_directions[0]);
    gpio_pin_configure(0, pin_directions[1]);

    // Configure MCP3008 as ADC channel 0
    spi_control(dev, SPI_CSPOL_0, SPI_POLARITY_0, SPI_PHASE_0);
    spi_control(dev, SPI_CSHIELD_0, SPI_NO_SHIELDING, SPI_PHASE_0);
    spi_control(dev, SPI_CPOL_0, SPI_POLARITY_0, SPI_PHASE_0);
    spi_control(dev, SPI_CPHA_0, SPI_PHASE_0, SPI_PHASE_0);

    // Set up GPIO pins for SPI communication
    gpio_pin_output_init(0, ADC_CHANNEL);

    // Initialize SPI
    spi_init(dev);

    // Main loop
    while (1) {
        // Read ADC value
        adc_value = spi_read_i2s(dev, ADC_CHANNEL, 4);

        // Check for proximity
        if (adc_value > last_adc_value * 0.9) {
            proximity_detected = 1;
            last_adc_value = adc_value;
        } else {
            proximity_detected = 0;
        }

        // Debounce logic
        if (proximity_detected && !debounced) {
            debounced = 1;
            last_debounce_time = usleep(DEBOUNCE_DELAY * 1000);
        } else if (!proximity_detected && debounced) {
            debounced = 0;
        }

        // Log event
        if (proximity_detected) {
            unsigned long current_time = micros();
            if (current_time - last_event_time > 100) {
                log_event("Proximity detected at %lu", current_time);
                last_event_time = current_time;
            }
        }

        // Energize relay if proximity is detected
        if (proximity_detected) {
            gpio_pin_write(relay_pin, 1);
        }

        // Update last event time
        last_event_time = current_time;

        // Sleep for 100 ms
        usleep(100 * 1000);
    }

    // Clean up resources
    free(adc_channel);
    spi_free(dev);
    gpio_free(0, SPI_BUS);
    gpio_disable(GPIO_RELAY);

    return 0;
}

// Define ADC channel for MCP3008
#define ADC_CHANNEL 0

