    pin_directions[0] = GPIOPIN_INPUT;
    pin_directions[1] = GPIOPIN_INPUT;

    gpio_pin_configure(GPIO_RELAY, pin_directions[0]);
    gpio_pin_configure(0, pin_directions[1]);

    // Configure MCP3008 as ADC channel 0
    spi_control(dev, SPI_CSPOL_0, SPI_POLARITY_0, SPI_PHASE_0);
    spi_control(dev, SPI_CSHIELD_0, SPI_NO_SHIELDING, SPI_PHASE_0);
    spi_control(dev, SPI_CPOL_0, SPI_POLARITY_0, SPI_PHASE_0);
    spi_control(dev, SPI_CPHA_0, SPI_PHASE_0, SPI_PHASE_0);

    // Set up GPIO pins for SPI communication
    gpio_pin_output_init(0, ADC_CHANNEL);

    // Initialize SPI
    spi_init(dev);

    // Main loop
    while (1) {
        // Read ADC value
        adc_value = spi_read_i2s(dev, ADC_CHANNEL, 4);

        // Check for proximity
        if (adc_value > last_adc_value * 0.9) {
            proximity_detected = 1;
            last_adc_value = adc_value;
        } else {
            proximity_detected = 0;
        }

        // Debounce logic
        if (proximity_detected && !debounced) {
            debounced = 1;
            last_debounce_time = usleep(DEBOUNCE_DELAY * 1000);
        } else if (!proximity_detected && debounced) {
            debounced = 0;
        }

        // Log event
        if (proximity_detected) {
            unsigned long current_time = micros();
            if (current_time - last_event_time > 100) {
                log_event("Proximity detected at %lu", current_time);
                last_event_time = current_time;
            }
        }

        // Energize relay if proximity is detected
        if (proximity_detected) {
            gpio_pin_write(relay_pin, 1);
        }

        // Update last event time
        last_event_time = current_time;

        // Sleep for 100 ms
        usleep(100 * 1000);
    }

    // Clean up resources
    free(adc_channel);
    spi_free(dev);
    gpio_free(0, SPI_BUS);
    gpio_disable(GPIO_RELAY);

    return 0;
}

