#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>
#include <spidev.h>

#define GPIO_CE0 8
#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SAMPLE_INTERVAL_SEC 1.0
#define LOG_FILE "alcohol_log.txt"

#define MAX_RETRIES 3
#define DELAY_MS 100

typedef struct {
    int tx[3];
    int rx[2];
} MCP3008_SPI_Command;

typedef struct {
    long long timestamp;
    int adc_value;
    char classification;
} AlcoholReading;

static spidev_t spi;
static MCP3008_SPI_Command command;
static AlcoholReading readings[100];
int reading_count = 0;

void spi_init() {
    int file_desc = spidev_open(SPI_DEVICE, 0);
    if (file_desc < 0) {
        perror("spidev_open failed");
        exit(EXIT_FAILURE);
    }
    spidev_control(file_desc, SPI_CSPAD_SET_LANE, 0);
    spidev_control(file_desc, SPI_CSPAD_SET_CPOL, 0);
    spidev_control(file_desc, SPI_CSPAD_SET_CPHA, 0);
    spidev_control(file_desc, SPI_CSPAD_ENABLE, 0);
}

void spi_deinit() {
    spidev_close(spi);
}

void mcp3008_command(int channel, int mode, int start, int end) {
    command.tx[0] = 0x01;
    command.tx[1] = (channel << 4) | 0x80;
    command.tx[2] = start;
    command.tx[3] = end;
    spidev_write(spi, command.tx);
    delay(100);
}

int mcp3008_read(void) {
    int ret = spidev_isp_read(spi, command.rx);
    if (ret < 0) {
        if (reading_count < MAX_RETRIES) {
            printf("SPI read failed, retrying... (attempt %d of %d)\n", reading_count + 1, MAX_RETRIES);
            usleep(DELAY_MS * 100);
            return mcp3008_read();
        } else {
            perror("SPI read failed after retries");
            return -1;
        }
    }
    return command.rx[1];
}

int adc_value(void) {
    int adc_value = mcp3008_read();
    if (adc_value == -1)
        return -1;
    return adc_value;
}

double ppm_to_alcohol_level(int adc_value) {
    return ((double)adc_value * 0.5) - 10.0;
}

char classification(double ppm) {
    if (ppm > 50.0)
        return 'A';
    else if (ppm < 20.0)
        return 'S';
    else
        return 'R';
}

void log_reading(double ppm) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    fprintf(LOG_FILE, "%ldT%0.3f\n", (long)now, ppm);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        spi_deinit();
        close(LOG_FILE);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();

    while (1) {
        int adc_value = adc_value();
        if (adc_value == -1)
            continue;
        double ppm = ppm_to_alcohol_level(adc_value);
        char classification_str = classification(ppm);
        log_reading(ppm);
        fprintf(LOG_FILE, "%s: %s\n", classification_str, classification_str);
        reading_count++;
        usleep(SAMPLE_INTERVAL_SEC * 1000000);
    }

    spi_deinit();
    close(LOG_FILE);
    return 0;
}

