#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SAMPLING_INTERVAL_SECS 60
#define PUMP_GPIO 18
#define CE_GPIO 8
#define SCLK_GPIO 11
#define MOSI_GPIO 10
#define MISO_GPIO 9
#define SPI_MODE 0
#define SPI_CLOCK_HZ 1000000
#define THRESHOLD 300
#define LOG_FILE "irrigation.log"

void log_entry(const char *message) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1,
            local_time->tm_mday, local_time->tm_hour, local_time->tm_min, local_time->tm_sec);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", time_str, message);
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    log_entry("Turning off water pump and cleaning up resources.");
    pigpio_stop();
    close(CE_GPIO);
    close(SCLK_GPIO);
    close(MOSI_GPIO);
    close(MISO_GPIO);
    log_entry("MCP3008 SPI and GPIOs closed.");
    fclose(stdout);
    remove(LOG_FILE);
    log_entry("Log file removed.");
    exit(0);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_IGN || signal(SIGTERM, signal_handler) == SIG_IGN) {
        fprintf(stderr, "Failed to set signal handler.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetupSPI(CE_GPIO, SPI_MODE, SPI_CLOCK_HZ) < 0) {
        fprintf(stderr, "Failed to set up SPI.\n");
        return 1;
    }

    if (gpioSetupPin(PUMP_GPIO, PIGIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up pump GPIO.\n");
        return 1;
    }

    while (1) {
        int sensor_data = read_analog_channel(0);
        if (sensor_data < THRESHOLD) {
            gpioSetPinState(PUMP_GPIO, PIGIO_HIGH);
            log_entry("Moisture level below threshold, activating pump.");
        } else {
            gpioSetPinState(PUMP_GPIO, PIGIO_LOW);
            log_entry("Moisture level above threshold, deactivating pump.");
        }
        usleep(1000000 * SAMPLING_INTERVAL_SECS / 1000); // Convert seconds to microseconds
