#define GPIO_PIN_24 24
#define GPIO_PIN_25 25
#define MCP3008_SPI_CHANNEL 0
#define MCP3008_CE0 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11
#define MIN_SPEED 50
#define MAX_SPEED 255
#define ACCELERATION_TIME 2
#define HOLD_TIME 2
#define DECELERATION_TIME 5

#define PWM_CHANNEL 1

void spi_init(void);
void gpio_init(void);
void read_potentiometers(void *buffer);
void set_motor_speed(int channel, int speed);
void control_motors(void);
void handle_sigint(int sig);
void handle_sigterm(int sig);

int main(int argc, char *argv[]) {
    int ret;
    pid_t pid;

    spi_init();
    gpio_init();

    while (1) {
        control_motors();
        usleep(ACCELERATION_TIME * 1000 * 1000);
        usleep(HOLD_TIME * 1000 * 1000);
        control_motors(0);
        usleep(DECELERATION_TIME * 1000 * 1000);
    }

    return 0;
}

void spi_init(void) {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file < 0) {
        perror("open /dev/spidev0.0");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer t = {
        .t_flags = SPI_TC_DATA,
        .t_len = 4,
        .t_channel = MCP3008_SPI_CHANNEL,
        .t_data = (void *)0x40
    };

    if (ioctl(file, SPI_IOC_MESSAGE(1), &t) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    close(file);
}

void gpio_init(void) {
    if (pigpio_init() < 0) {
        fprintf(stderr, "pigpio_init() failed\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_PIN_18, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_23, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_24, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_25, PI_OUTPUT);

    if (gpioSetup(GPIO_PIN_18, GPIO_SPEED) < 0) {
        fprintf(stderr, "gpioSetup(GPIO_PIN_18) failed\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetup(GPIO_PIN_23, GPIO_SPEED) < 0) {
        fprintf(stderr, "gpioSetup(GPIO_PIN_23) failed\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetup(GPIO_PIN_24, GPIO_SPEED) < 0) {
        fprintf(stderr, "gpioSetup(GPIO_PIN_24) failed\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetup(GPIO_PIN_25, GPIO_SPEED) < 0) {
        fprintf(stderr, "gpioSetup(GPIO_PIN_25) failed\n");
        exit(EXIT_FAILURE);
    }
}

void read_potentiometers(void *buffer) {
    int ret;
    if (spi_transfer(buffer, 2, 0x00) < 0) {
        perror("spi_transfer");
        exit(EXIT_FAILURE);
    }

    int pot1 = buffer[0];
    int pot2 = buffer[1];

    if (pot1 == 0 || pot2 == 0) {
        fprintf(stderr, "Potentiometer readings are invalid\n");
        exit(EXIT_FAILURE);
    }

    int speed_factor1 = map_potentiometer(pot1);
    int speed_factor2 = map_potentiometer(pot2);

    if (speed_factor1 < MIN_SPEED || speed_factor1 > MAX_SPEED ||
        speed_factor2 < MIN_SPEED || speed_factor2 > MAX_SPEED) {
        fprintf(stderr, "Speed factors are out of range\n");
        exit(EXIT_FAILURE);
    }
}

int map_potentiometer(int value) {
    return (int)((value * 255) / 1023.0 * 255);
}

void set_motor_speed(int channel, int speed) {
    gpioWrite(channel, PI_OUTPUT, speed);
}

void control_motors(int direction) {
    int motor1_speed = map_potentiometer(read_potentiometers(NULL)[0]);
    int motor2_speed = map_potentiometer(read_potentiometers(NULL)[1]);

    gpioWrite(GPIO_PIN_18, PI_OUTPUT, motor1_speed);
    gpioWrite(GPIO_PIN_23, PI_OUTPUT, direction);

    gpioWrite(GPIO_PIN_24, PI_OUTPUT, motor2_speed);
    gpioWrite(GPIO_PIN_25, PI_OUTPUT, !direction);
}

void handle_sigint(int sig) {
    fprintf(stderr, "SIGINT received, exiting gracefully...\n");
    exit(0);
}

void handle_sigterm(int sig) {
    fprintf(stderr, "SIGTERM received, exiting gracefully...\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    pid = fork();
    if (pid == 0) {
        // Child process
        main(argc, argv);
    } else {
        // Parent process
        waitpid(pid, NULL, 0);
    }

    return 0;
}

