#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <spidev.h>

#define MAX_SAMPLES 100
#define LED_GPIO 17
#define SPI_CS_GPIO 8
#define SPI_MOSI_GPIO 10
#define SPI_MISO_GPIO 9
#define SPI_SCLK_GPIO 11
#define MAX_LEVEL 1023
#define NOISE_THRESHOLD 0.1
#define CALIBRATION_TIME 5000

int spi_fd;
int mcp3008_channel = 0;
int spi_mode = SPI_MODE0;
int spi_bits = SPI_BITS_16;
int spi_prescale = SPI_PRESCALE_DIV2;

void spi_init(void);
void spi_close(void);
void mcp3008_init(void);
void mcp3008_read_channel(int channel);
void led_control(int state);
void calibrate_ambient_level(int *avg_level);

int main(int argc, char *argv[]) {
    int samples[MAX_SAMPLES];
    int sample_count = 0;
    int ambient_level = 0;
    int threshold = NOISE_THRESHOLD * ambient_level;
    int led_state = 0;

    spi_init();
    mcp3008_init();

    while (1) {
        mcp3008_read_channel(mcp3008_channel);
        samples[sample_count] = mcp3008_read_channel(mcp3008_channel);
        sample_count++;

        if (sample_count >= MAX_SAMPLES) {
            sample_count = MAX_SAMPLES - 1;

            for (int i = 0; i < MAX_SAMPLES; i++) {
                ambient_level += samples[i];
            }
            ambient_level /= MAX_SAMPLES;

            if (ambient_level > threshold) {
                led_state = 1;
            }
        }

        usleep(10000); // Sample every 10 ms
    }

    spi_close();
    led_control(0); // Turn off LED on exit
    pigpio_terminate(8000); // Terminate pigpio
    return 0;
}

void spi_init(void) {
    spi_fd = spidev_open(0, 0);
    if (spi_fd < 0) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }

    spi_set_mode(spi_fd, spi_mode);
    spi_set_bits(spi_fd, spi_bits);
    spi_set_prescale(spi_fd, spi_prescale);

    if (spi_set_xfer_fmt(spi_fd, SPI_MODE0, SPI_BITS_16, SPI_CLOCK_DIV2) < 0) {
        perror("spi_set_xfer_fmt");
        exit(EXIT_FAILURE);
    }
}

void spi_close(void) {
    if (spi_fd >= 0) {
        spidev_close(spi_fd);
        spi_fd = -1;
    }
}

void mcp3008_init(void) {
    if (spidev_device_open(SPI_CS_GPIO, 0) < 0) {
        perror("spidev_device_open");
        exit(EXIT_FAILURE);
    }
}

void mcp3008_read_channel(int channel) {
    int value;
    if (spidev_device_write_reg(SPI_CS_GPIO, channel, 0x00) < 0) {
        perror("spidev_device_write_reg");
        exit(EXIT_FAILURE);
    }

    if (spidev_device_read_reg(SPI_CS_GPIO, channel) < 0) {
        perror("spidev_device_read_reg");
        exit(EXIT_FAILURE);
    }

    value = (spidev_device_read_reg(SPI_CS_GPIO, channel) & 0x03);
    mcp3008_read_channel[channel] = value;
}

void led_control(int state) {
    if (state != 0 && state != 1) {
        fprintf(stderr, "Invalid LED state\n");
        exit(EXIT_FAILURE);
    }

