#define ADC_CHANNEL 0
#define CE_PIN 4
#define SPI_SPEED 1000000
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL 100

void spi_init() {
    if (pigpioInitialise() < 0) {
        perror("pigpioInitialise");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(CE_PIN, PIGIO_OUTPUT) < 0) {
        perror("gpioSetup");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(SPI_CHANNEL_0, SPI_MODE0, SPI_CPOL_0, SPI_CPOL_0, SPI_NSS_FALLING, SPI_NSP_RISING) < 0) {
        perror("gpioSetup");
        exit(EXIT_FAILURE);
    }
}

int adc_read(int channel) {
    int result = pigget(PIG_ADCSRC, channel);
    if (result < 0) {
        fprintf(stderr, "ERROR: ADC read failed\n");
        return -1;
    }

    return result;
}

int convert_to_slpm(int adc_value) {
    if (adc_value < 0 || adc_value > 200) {
        fprintf(stderr, "ERROR: ADC value out of range\n");
        return -1;
    }

    double voltage = (adc_value * 3.3) / 65535.0; // Assuming 3.3V reference
    double airflow = (voltage - 0.5) / (4.5 - 0.5) * 200;
    return (int)airflow;
}

void log_reading(int airflow) {
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s: %d\n", timestamp, airflow);
    fclose(log_file);
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, closing resources...\n", signum);
    spi_teardown();
    fclose(stdout);
    fclose(stderr);
    pigexit();
}

int main() {
    signal(SIGINT, signal_handler);

    spi_init();

    while (1) {
        int adc_value = adc_read(ADC_CHANNEL);
        if (adc_value == -1) {
            continue;
        }

        int airflow = convert_to_slpm(adc_value);
        if (airflow == -1) {
            continue;
        }

        log_reading(airflow);
        usleep(SAMPLE_INTERVAL * 1000 / SPI_SPEED);
    }

    return 0;
}
