        spi_close(spi_fd);
        exit(EXIT_FAILURE);
    }

    gpio_set_direction(gpio_fd, GPIO_CE0, GPIO_OUT);
    gpio_set_level(gpio_fd, 0); // Drive CE low before SPI transfer

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
