    spi_data.len = sizeof(ADC_READ_COMMAND);

    if (ioctl(fd, SPI_IOC_MESSAGE, &spi_data) == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
}

void spi_ioctl(int fd, uint32_t cmd, void *data) {
    struct spidev_ioc_req req;
    req.cmd = cmd;
    req.data = data;
    req.len = sizeof(uint32_t);

    if (ioctl(fd, SPI_IOC_MESSAGE, &req) == -1) {
        perror("Failed to perform SPI IOCTL");
        exit(EXIT_FAILURE);
    }
}

void spi_close(int fd) {
    close(fd);
}

void gpio_request(const char *devname, const char *name, int bist) {
    int ret = libgpiod_request_device(devname, name, bist);
    if (ret < 0) {
        perror("Failed to request GPIO chip");
        exit(EXIT_FAILURE);
    }
}

void gpio_free(int fd) {
    libgpiod_free_device(fd);
}

void gpio_set_direction(int fd, int pin, int direction) {
    libgpiod_direction_set(fd, pin, direction);
}

void gpio_set_level(int fd, int pin, int level) {
    libgpiod_output_set(fd, pin, level);
}

void handle_signal(int sig) {
    fprintf(stderr, "Received signal %d, shutting down...\n", sig);
    exit(sig);
}

