#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>

#define SPI_CLOCK 1000000
#define ADC_CHANNEL 0
#define VREF 3300

#define LOG_FILE "gas_log.txt"

void spi_init(void) {
    int spi_fd = pigpio_open_spi(0, SPI_CLOCK);
    if (spi_fd < 0) {
        perror("Failed to open SPI bus");
        exit(EXIT_FAILURE);
    }
    pigpio_set_mode(spi_fd, PI_OUTPUT);
}

int adc_read(int spi_fd, int channel) {
    int data[8];
    pigpio_spitsend(spi_fd, 0x20, 0x00, 0, data, 8);
    if (pigpio_spiread(spi_fd, channel, data) < 0) {
        perror("Failed to read ADC data");
        return -1;
    }
    return data[3];
}

float adc_to_voltage(int adc_value) {
    float voltage = (adc_value * 3.3) / 1023.0;
    return voltage;
}

double ppm_calculation(float voltage) {
    return voltage * 1000.0;
}

void log_data(float voltage, double ppm) {
    time_t now = time(NULL);
    char timestamp[80];
    sprintf(timestamp, "%ld", (long)now);
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s, %f, %f\n", timestamp, voltage, ppm_calculation(voltage));
    fclose(file);
}

void print_data(float voltage, double ppm) {
    printf("Voltage: %.2f V, PPM: %.2f\n", voltage, ppm);
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        pigpio_stop(spi_fd);
        fclose(stdout);
        fclose(stderr);
        fclose(stdout);
        pigpio_exit();
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    spi_init();

    while (1) {
        int adc_value = adc_read(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            usleep(100000);
            continue;
        }
        float voltage = adc_to_voltage(adc_value);
        double ppm = ppm_calculation(voltage);
        log_data(voltage, ppm);
        print_data(voltage, ppm);
        usleep(1000000);
    }

    pigpio_stop(spi_fd);
    fclose(stdout);
    fclose(stderr);
    fclose(stdout);
    pigpio_exit();
    return 0;
}

