    if (ioctl(MCP3008_CS, WHO_AM_I, &mcp3008_id) < 0) {
        fprintf(stderr, "Failed to identify MCP3008\n");
        exit(EXIT_FAILURE);
    }
    if (ioctl(MCP3008_CS, MCP3008_MODE, MCP3008_SPI_MODE0) < 0) {
        fprintf(stderr, "Failed to set MCP3008 to SPI mode 0\n");
        exit(EXIT_FAILURE);
    }
    if (ioctl(MCP3008_CS, MCP3008_REF_VOLTAGE, 3300) < 0) {
        fprintf(stderr, "Failed to set reference voltage\n");
        exit(EXIT_FAILURE);
    }
}

void adxl335_init() {
    if (ioctl(ADXL335_X_OUT, ADXL335_MODE, ADXL335_MODE_DIGITAL) < 0) {
        fprintf(stderr, "Failed to set ADXL335 to digital mode\n");
        exit(EXIT_FAILURE);
    }
}

