    if (ioctl(MCP3008_CS, MCP3008_READ_ADC, channel) < 0) {
        fprintf(stderr, "Failed to read ADC\n");
        exit(EXIT_FAILURE);
    }
    adc_buffer[buffer_index] = (uint16_t)ioctl(MCP3008_CS, MCP3008_DATA_OUT);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

