        read_adc(ADXL335_X_OUT);
        read_adc(ADXL335_Y_OUT);
        read_adc(ADXL335_Z_OUT);

        float x_adc = (adc_buffer[0] - 1024) * (SENSITIVITY / 3300.0);
        float y_adc = (adc_buffer[1] - 1024) * (SENSITIVITY / 3300.0);
        float z_adc = (adc_buffer[2] - 1024) * (SENSITIVITY / 3300.0);

        kalman_filter((float[]){x_adc, y_adc, z_adc}, NULL, (float[]){0.0, 0.0, 0.0}, NULL, NULL);

        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_adc, y_adc, z_adc);
        usleep(100000 / SAMPLING_RATE);
    }

    pigpio_terminate(100);
    return 0;
}

