        float z_adc = (adc_buffer[2] - 1024) * (SENSITIVITY / 3300.0);

        kalman_filter((float[]){x_adc, y_adc, z_adc}, NULL, (float[]){0.0, 0.0, 0.0}, NULL, NULL);

        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_adc, y_adc, z_adc);
