#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <libgpiod.h>

#define SENSITIVITY 0.025  // V/mT
#define V_QUIESCENT 1.65   // V
#define VCC 3.3              // V

#define SENSOR_PINS {GPIO4, GPIO17, GPIO27}
#define SAMPLE_INTERVAL 100  // milliseconds

void log_reading(const char *sensor_name, float mT) {
    FILE *file = fopen("magnetic_log.txt", "a");
    if (!file) {
        perror("Failed to open magnetic_log.txt");
        return;
    }
    fprintf(file, "%s,_%f\n", sensor_name, mT);
    fclose(file);
}

int main(int argc, char *argv[]) {
    int gpio_lines[3];
    int ret;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    // Request GPIO lines as inputs
    for (int i = 0; i < 3; i++) {
        gpio_lines[i] = gpiod_line_request_input(SENSOR_PINS[i]);
        if (gpio_lines[i] < 0) {
            perror("Failed to request GPIO line as input");
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (int i = 0; i < 3; i++) {
            ret = gpiod_line_read(gpio_lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Error reading GPIO %d: %s\n", SENSOR_PINS[i], gpiod_strerror(ret));
                continue;
            }

            float voltage = (ret ? VCC : 0.0);
            float mT = (voltage - V_QUIESCENT) * SENSITIVITY;

            if (mT < -100.0 || mT > 100.0) {
                fprintf(stderr, "Warning: Out-of-range magnetic field value detected for sensor %s: %f mT\n", SENSOR_PINS[i], mT);
            }

            log_reading(SENSOR_PINS[i], mT);
        }

        usleep(SAMPLE_INTERVAL * 1000 / 1000);
    }

    // Clean up and exit
    for (int i = 0; i < 3; i++) {
        gpiod_line_free(gpio_lines[i]);
    }
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

