#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define PUMP_GPIO 17
#define LOG_FILE "watering.log"
#define CHECK_INTERVAL 60000

void log_event(const char *event) {
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s: %s\n", timestamp, event);
        fclose(file);
    }
}

void signal_handler(int signum) {
    log_event("Program received signal, shutting down gracefully...");
    pigpio_stop();
    fprintf(stdout, "Program shutting down...\n");
    exit(0);
}

int main() {
    pigpio_initialize(-1);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pigpio_set_mode(PumpGPIO, PIGIO_OUTPUT);

    log_event("Program started.");

    while (1) {
        int moisture_value = pigpio_get_adc(ADC_CHANNEL, 2);
        if (moisture_value == -1) {
            log_event("Error reading ADC data.");
            continue;
        }

        float moisture_percent = (float)moisture_value * 1.0 / 1023.0 * 100;
        log_event(f"Moisture level: %f%%", moisture_percent);

        if (moisture_percent < 30) {
            log_event("Moisture level below 30%, turning on pump...");
            pigpio_write(PumpGPIO, 1);
        } else {
            log_event("Moisture level at or above 30%, turning off pump...");
            pigpio_write(PumpGPIO, 0);
        }

        usleep(CHECK_INTERVAL * 1000);
    }

    pigpio_stop();
    log_event("Program terminated.");
    fclose(stdout);
    return 0;
}

