#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpgod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define CHANNELS 3
#define LOG_INTERVAL 1000

void sigint_handler(int signum) {
    printf("Exiting gracefully...\n");
    close("sensor_data.csv");
    gpiod_resource_release(resource);
    exit(0);
}

int main() {
    gpiod_resource_t resource;
    int fd;
    struct spi_device *dev;
    uint8_t command[3];
    int channel, i;
    FILE *csv_file = fopen("sensor_data.csv", "w");

    if (sigset_t sigset; sigset_t(sigint_handler); sigaddset(&sigset, SIGINT)) {
        printf("Setting up signal handler for SIGINT...\n");
        sigaction(SIGINT, &sigset, NULL, 0);
    }

    fd = open(SPI_DEV, O_RDWR);
    if (fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_RDWR_MODE, &SPI_MODE) == -1) {
        perror("Failed to set SPI mode");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_RDWR_BITS, &SPI_BITS) == -1) {
        perror("Failed to set SPI bits per word");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_RDWR_SPEED, &SPI_SPEED) == -1) {
        perror("Failed to set SPI speed");
        close(fd);
        exit(EXIT_FAILURE);
    }

    for (channel = 0; channel < CHANNELS; channel++) {
        command[0] = 0x01;
        command[1] = 0x80 | (channel << 4);
        command[2] = 0x00;

        if (ioctl(fd, SPI_IOC_MESSAGE, command) == -1) {
            perror("Failed to send command to MCP3008");
            continue;
        }

        int data[3];
        if (ioctl(fd, SPI_IOC_MESSAGE, command, 3) == -1) {
            perror("Failed to read data from MCP3008");
            continue;
        }

        int value = ((data[1] & 0x03) << 8) | data[2];
        fprintf(csv_file, "%d,%d,%d\n", channel, value, value);

        usleep(LOG_INTERVAL * 1000);
    }

    fclose(csv_file);
    gpiod_resource_release(&resource);
    close(fd);

    return 0;
}

