#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define MQTT_QOS 0

void mqtt_callback(char *topic, char *payload, unsigned int payload_len, long long flags) {
    if (flags & MQTT_FLAG_CONNECT) {
        // Connection established, start MQTT loop
        mosquitto_loop_start(NULL);
    } else if (flags & MQTT_FLAG_MESSAGE) {
        // Message received, parse JSON payload
        cJSON *json = cJSON_Parse(payload);
        if (json) {
            cJSON *led_state = cJSON_GetObjectItem(json, "led_state");
            if (cJSON_IsTrue(led_state)) {
                gpioSetMode(LED_PIN, PI_OUTPUT);
                gpioWrite(LED_PIN, HIGH);
            } else {
                gpioSetMode(LED_PIN, PI_OUTPUT);
                gpioWrite(LED_PIN, LOW);
            }
            cJSON_Delete(json);
        } else {
            // Invalid JSON format, log error
            fprintf(stderr, "Invalid JSON format: %s\n", payload);
        }
        cJSON_Delete(cJSON_Parse(payload));
    }
    cJSON_Delete(json);
}

void signal_handler(int signum) {
    // Handle SIGINT and SIGTERM signals
    mosquitto_loop_stop(NULL);
    gpioTerminate();
    exit(0);
}

