#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO17 17  // GPIO17 (BCM numbering) for KY-038 DO pin
#define GPIO18 18  // GPIO18 for simulated alarm LED

int main(int argc, char *argv[]) {
    int ret;
    gpio_init();  // Initialize libgpiod

    // Signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // GPIO lines
    int do_pin = gpio_get_line(GPIO17);
    int led_pin = gpio_get_line(GPIO18);

    if (do_pin < 0 || led_pin < 0) {
        fprintf(stderr, "Failed to open GPIO lines\n");
        return 1;
    }

    gpio_set_dir(do_pin, GPIO_OUT);  // Set DO pin as output
    gpio_set_dir(led_pin, GPIO_OUTPUT); // Set LED pin as output

    while (1) {
        int sound_level = gpio_get_level(do_pin);

        if (sound_level == 0) {
            printf("Sound level: 1\n");
            gpio_set_level(led_pin, 0);  // LED off
        } else {
            printf("Sound level: 0\n");
            gpio_set_level(led_pin, 1);  // LED on
            usleep(100000);  // 100 ms delay
            gpio_set_level(led_pin, 0);  // LED off
        }

        usleep(100000);  // 100 ms delay
    }

    gpio_put_line(do_pin);  // Release GPIO line
    gpio_put_line(led_pin); // Release GPIO line

    return 0;
}

