    gpiod_line_t line;
    gpiod_chip_t chip;
    gpiod_property_t property;
    gpiod_line_property_t line_property;
    gpiod_error_t error;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    error = gpiod_chip_open(CHIP_PATH, &chip);
    if (error != 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the GPIO line
    error = gpiod_chip_line_get(chip, GPIO_LINE, &line_fd);
    if (error != 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line for falling-edge event detection
    error = gpiod_line_request(line_fd, CONSUMER_LABEL, GPIOD_MODE_FALLING, NULL);
    if (error != 0) {
        perror("Failed to request line for falling-edge event");
        gpiod_line_close(line_fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    LOG_FILE = fopen(LOG_FILE, "a");
    if (!LOG_FILE) {
        perror("Failed to open log file");
        gpiod_line_close(line_fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!shutdown_requested) {
        // Wait for a falling-edge event
        error = gpiod_line_event_wait(line_fd, NULL);
        if (error != 0) {
            perror("Failed to wait for falling-edge event");
            break;
        }

        // Read the event
        gpiod_line_event_t event;
        error = gpiod_line_event_read(line_fd, &event);
        if (error != 0) {
            perror("Failed to read falling-edge event");
            break;
        }

        // Log the event and print to stdout
