        printf("[%s] Vibration detected: %s\n", get_timestamp(), event.value ? "HIGH" : "LOW");

        // Shutdown the system
        system("sudo shutdown -h now");
    }

    // Clean up
    gpiod_line_close(line_fd);
    gpiod_chip_close(chip);
    fclose(LOG_FILE);

    return 0;
}

