    if (gpioSetup(10, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 10 as output\n");
        pigpioTerminate();
        exit(1);
    }

    if (gpioSetup(11, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 11 as output\n");
