    } else {
        gpioRead(10, 1);
    }

    if (gpioRead(11) == 1) {
        gpioRead(11, 0);
    } else {
        gpioRead(11, 1);
    }

    gpioWrite(8, 0);
    gpioWrite(9, 0);
    gpioWrite(10, 0);
    gpioWrite(11, 0);
}

