    FILE *file = fopen("temp_log.dat", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open temp_log.dat for writing\n");
        return;
    }

    fwrite(&buffer.data, sizeof(float), BUFFER_SIZE, file);
