#include <linux/i2c-dev.h>
#include <spidev.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define SPI_DEV 0
#define SPI_CHANNEL 0

#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL 1000  // in milliseconds

int i2c_fd;
int spi_fd;

void log_environment(long timestamp, int light_lux, int sound_adc) {
    char log_entry[100];
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);

    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", local_time);
    sprintf(log_entry + strlen(log_entry), "Light: %d, Sound: %d", light_lux, sound_adc);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Error opening file");
        return;
    }
    fprintf(file, "%s\n", log_entry);
    fclose(file);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(EXIT_FAILURE);
    }
}

void init_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
}

void read_light_lux() {
    char command[2] = {0x44, 0x00};  // BH1750 register address for light data
    write(i2c_fd, command, 2);

    u8 data[2];
    read(i2c_fd, data, 2);

    int light_lux = (data[0] << 8) | data[1];
    log_environment(get_timestamp(), light_lux, 0);
}

void read_sound_adc() {
    // Assuming MCP3008 is configured for channel 0
    u8 command[1] = 0x01;  // Start conversion
    write(spi_fd, &command, 1);

    u8 buffer[2];
    read(spi_fd, buffer, 2);

    int sound_adc = (buffer[0] << 8) | buffer[1];
    log_environment(get_timestamp(), 0, sound_adc);
}

void get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
}

int main(int argc, char *argv[]) {
    init_i2c();
    init_spi();

    while (1) {
        read_light_lux();
        read_sound_adc();
        usleep(SAMPLE_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    close(i2c_fd);
    close(spi_fd);
    return 0;
}

