#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define PIN 17
#define LOG_FILE "flame_events.log"
#define ALARM_THRESHOLD 500

void log_event(const char *timestamp, int pin, int state) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s,%d,%d\n", timestamp, pin, state);
    fclose(file);
}

void print_alarm_message() {
    fprintf(stderr, "ALARM: Flame detected!\n");
}

int main(int argc, char *argv[]) {
    int fd;
    gpiod_chip_t chip;
    gpiod_line_t line;
    gpiod_arg_t arg;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <potentiometer_value>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    arg.int_value = atoi(argv[1]);

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    gpiod_init();
    gpiod_chip_add_device(&chip, PIN);
    gpiod_line_init(&line, &chip, PIN);
    gpiod_arg_add(&line, arg);

    if (gpiod_line_direction(&line, GPIOD_IN) == -1) {
        perror("Error setting GPIO line direction");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_pull_up(&line) == -1) {
        perror("Error enabling pull-down resistor");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int state = gpiod_line_get_level(&line);
        if (state == GPIOD_INPUT_HIGH) {
            log_event(ctime(NULL), PIN, 1);
            print_alarm_message();
        } else {
            log_event(ctime(NULL), PIN, 0);
        }

        usleep(1000000); // Sleep for 1 second
    }

    gpiod_line_destroy(&line);
    gpiod_chip_destroy(&chip);
    close(fd);

    return 0;
}

