#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/time.h>

#define TMP36_VREF 3.0
#define MCP3008_CE 0
#define MCP3008_MODE 0
#define MCP3008_SPI_SPEED 500000
#define MCP4725_ADDR 0x62
#define MCP4725_BUS 1

#define LOG_FILE "temperature_log.txt"

void log_reading(const char *timestamp, int raw_adc, float temperature_c, float dac_voltage) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }
    fprintf(log_file, "%s: raw ADC: %d, temperature: %.1f C, DAC voltage: %.2f V\n", time_str, raw_adc, temperature_c, dac_voltage);
    fprintf(stdout, "%s: raw ADC: %d, temperature: %.1f C, DAC voltage: %.2f V\n", time_str, raw_adc, temperature_c, dac_voltage);
    fclose(log_file);
}

int main() {
    int spi_fd, i2c_fd, adc_channel = 0;
    int mcp3008_error = 0;
    int mcp4725_error = 0;
    int adc_value = 0;
    float temperature_c = 0.0;
    float dac_voltage = 0.0;

    pigpio_init(1); // Initialize pigpio with 1 as the file descriptor for standard input/output

    while (1) {
        // Initialize MCP3008
        mcp3008_error = gpioOutput(MCP3008_CE);
        if (mcp3008_error) {
            fprintf(stderr, "Failed to initialize MCP3008 CE pin.\n");
            continue;
        }
        gpioSetup(MCP3008_CE, PIGIO_OUTPUT);
        gpioWrite(MCP3008_CE, 0); // Reset the MCP3008

        // Read ADC value
        mcp3008_error = gpioRead(MCP3008_CE);
        if (mcp3008_error) {
            fprintf(stderr, "Failed to read from MCP3008.\n");
            continue;
        }
        adc_value = gpioRead(MCP3008_CE);

        // Convert ADC value to voltage
        float voltage = (adc_value * TMP36_VREF) / 1000.0;
        temperature_c = (voltage - 0.5) * 100.0; // Convert to Celsius

        // Map temperature to DAC output
        dac_voltage = (temperature_c / 50.0) * 3.3;

        // Log the reading
        log_reading(get_timestamp(), adc_value, temperature_c, dac_voltage);

        // Set DAC output
        mcp4725_error = gpioWrite(MCP4725_ADDR, 0x20); // Set DAC mode 0 (linear)
        if (mcp4725_error) {
            fprintf(stderr, "Failed to set MCP4725 DAC mode.\n");
            continue;
        }
        mcp4725_error = gpioWrite(MCP4725_ADDR, dac_voltage); // Set DAC output

        // Wait for 0.5 seconds
        usleep(500000);
    }

    // Close SPI and I2C
    gpioWrite(MCP3008_CE, 1); // Release CE pin
    pigpio_terminate(1); // Terminate pigpio

    return 0;
}

