#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CS_PIN 2
#define ADC_CHANNELS_COUNT 3
#define ADC_READ_INTERVAL_SECONDS 60
#define LOG_FILE "soil_data.txt"

void spiInit();
void spiClose();
void gpioInit();
void gpioTerminate();
void logData(int adc_value, int channel);

int main(int argc, char *argv[]) {
    spiInit();
    gpioInit();

    while (1) {
        for (int i = 0; i < ADC_CHANNELS_COUNT; i++) {
            int adc_value;
            int error = spiXfer(0, &adc_value, 1, SPI_CS_PIN);
            if (error != 0) {
                fprintf(stderr, "Error reading from MCP3008: %d\n", error);
                spiClose();
                gpioTerminate();
                exit(1);
            }

            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr, "Invalid ADC value from channel %d\n", i);
                spiClose();
                gpioTerminate();
                continue;
            }

            double moisture = (1.0 - (adc_value / 1023.0)) * 100.0;
            time_t now = time(NULL);
            char timestamp[80];
            sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
                    now / 10000, now % 10000 / 100, now % 100,
                    now % 60, now % 60, 0);

            char log_line[128];
            sprintf(log_line, "%s %d\n", timestamp, i);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file.\n");
                spiClose();
                gpioTerminate();
                exit(1);
            }
            fprintf(log_file, log_line);
            fclose(log_file);
        }

        usleep(1000000 * ADC_READ_INTERVAL_SECONDS);
    }

    gpioTerminate();
    spiClose();
    printf("Exiting...\n");
    return 0;
}

void spiInit() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO.\n");
        exit(1);
    }

    if (spiOpen(SPI_CS_PIN) < 0) {
        fprintf(stderr, "Failed to open SPI interface.\n");
        exit(1);
    }
}

void spiClose() {
    if (spiClose() < 0) {
        fprintf(stderr, "Failed to close SPI interface.\n");
    }
}

void gpioInit() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO.\n");
        exit(1);
    }
}

void gpioTerminate() {
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate GPIO.\n");
    }
}

void logData(int adc_value, int channel) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        exit(1);
    }
    fprintf(log_file, "%d\n", adc_value);
    fclose(log_file);
}

