#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/gpiod.h>

#define RELAY_PINS 4
#define RELAY_GPIO 17, 22, 23, 24

void signal_handler(int signum) {
    gpiod_line_set_value(RELAY_PINS, 0, GPIOD_OUTPUT);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpiod_init();

    for (int i = 0; i < RELAY_PINS; i++) {
        gpiod_line_t line;
        gpiod_line_init(&line, RELAY_PINS[i]);
        gpiod_line_request_output_rly(line, 1);
    }

    while (1) {
        for (int i = 0; i < RELAY_PINS; i++) {
            gpiod_line_set_value(RELAY_PINS, i, GPIOD_OUTPUT);
            usleep(1000000); // 1 second delay
            gpiod_line_set_value(RELAY_PINS, i, GPIOD_INPUT);
        }
        usleep(1000000000); // Sleep for 1 second
    }

    return 0;
}

