#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define LED_GPIO 16
#define SPI_CS_GPIO 8
#define ADC_CHANNEL 0
#define ADC_CLOCK_HZ 1000000
#define ADC_BITS 10
#define THRESHOLD 500
#define LOG_FILE "sound_events.log"
#define DEBOUNCE_DELAY 50

void sigint_handler(int signum) {
    printf("Exiting...\n");
    pigpio_terminate();
    close(LED_GPIO);
    close(SPI_CS_GPIO);
    remove(LOG_FILE);
    exit(0);
}

void setup_gpio() {
    if (pigpio_init(1) != 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    if (access(LOG_FILE, R_OK) != 0) {
        if (open(LOG_FILE, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR) == -1) {
            perror("Failed to create log file");
            exit(EXIT_FAILURE);
        }
    }

    if (gpioSetup(LED_GPIO, GPIO_OUTPUT) != 0) {
        perror("Failed to set GPIO16 as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(SPI_CS_GPIO, GPIO_OUTPUT) != 0) {
        perror("Failed to set GPIO8 as output (chip select)");
        exit(EXIT_FAILURE);
    }
}

void read_adc() {
    int spi_fd = open(LOG_FILE, O_RDONLY);
    if (spi_fd == -1) {
        perror("Failed to open log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    int timestamp = (ts.tv_sec * 1000000000) + ts.tv_nsec / 1000;

    int mcp3008_data = spiRead(spi_fd, ADC_CHANNEL, ADC_BITS);
    if (mcp3008_data == -1) {
        perror("SPI transfer failed");
        return;
    }

    int adc_value = mcp3008_data >> 8;
    if (adc_value > THRESHOLD) {
        printf("Sound level detected! Turning on LED\n");
        gpioWrite(LED_GPIO, HIGH);
        printf("Timestamp: %d\n", timestamp);
        sleep(DEBOUNCE_DELAY / 1000);
        gpioWrite(LED_GPIO, LOW);
    }

    close(spi_fd);
}

int main() {
    signal(SIGINT, sigint_handler);

    setup_gpio();

    while (1) {
        read_adc();
        usleep(10000 / 10); // Read every 10 ms
    }

    pigpio_terminate();
    close(LED_GPIO);
    close(SPI_CS_GPIO);
    remove(LOG_FILE);

    return 0;
}

