#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MCP3008_SPI_BUS 0
#define MCP3008_SPI_DEVICE 0
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_MCP3008_CHANNEL 0
#define MCP3008_ADC_BITS 10
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define PWM_SPEED 150
#define RAIN_THRESHOLD 5
#define LOG_FILE "rain_log.txt"
#define LOG_APPEND 1

volatile sig_atomic_t graceful_shutdown = 0;

void sigint_handler(int sig) {
    graceful_shutdown = 1;
}

void sigterm_handler(int sig) {
    graceful_shutdown = 1;
}

void log_rain_reading(int rain_level) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%d\t%d\n", now, rain_level);
    fclose(log_file);
}

void read_rain_sensor() {
    gpioSetup(RAIN_SENSOR_PIN, GPIO_OUTPUT);
    gpioWrite(RAIN_SENSOR_PIN, 0);

    gpioSetup(MCP3008_SPI_BUS, MCP3008_SPI_DEVICE, MCP3008_SPI_SPEED);
    int mcp3008_channel = MCP3008_MCP3008_CHANNEL;
    uint8_t tx[3] = {0x01, (0x08 | mcp3008_channel) << 4, 0x00};
    int mcp3008_transfer_size = 3;
    int mcp3008_transfer_status = pigspiSPITransfer(MCP3008_SPI_BUS, MCP3008_SPI_DEVICE, tx, mcp3008_transfer_size);

    if (mcp3008_transfer_status < 0) {
        perror("Failed to communicate with MCP3008");
        return;
    }

    uint16_t adc_value = (tx[1] & 0x0F) << 8 | tx[2];
    int rain_level = adc_value >> 2;

    if (rain_level >= RAIN_THRESHOLD) {
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        pigspiPWM(MOTOR_ENA, PWM_SPEED);
        sleep(3);
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        pigspiPWM(MOTOR_ENA, 0);
    } else {
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        pigspiPWM(MOTOR_ENA, PWM_SPEED);
        sleep(3);
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        pigspiPWM(MOTOR_ENA, 0);
    }

    log_rain_reading(rain_level);
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_IGN || signal(SIGTERM, sigterm_handler) == SIG_IGN) {
        perror("Failed to set signal handlers");
        return 1;
    }

    if (pigpioInit() != 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    if (open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR) == -1) {
        perror("Failed to open log file");
        pigpioTerminate();
        return 1;
    }

    while (!graceful_shutdown) {
        read_rain_sensor();
        sleep(1);
    }

    pigpioTerminate();
    close(fileno(log_file));
    fclose(log_file);
    remove(LOG_FILE);

    return 0;
}

