#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define MIC_GPIO 26
#define LED_GPIO 16
#define THRESHOLD 700
#define DEBOUNCE_MS 50
#define DETECTION_MS 500

void handle_interrupt(int sig) {
    gpioOutput(LED_GPIO, 0);
}

void clap_detector(void) {
    int led_state = gpioRead(LED_GPIO);
    if (led_state == 0) {
        gpioWrite(LED_GPIO, 1);
        printf("Clap detected at %s\n", ctime(NULL));
        usleep(DEBOUNCE_MS * 1000 / HRTIME_PER_SEC);
        gpioWrite(LED_GPIO, 0);
    }
}

int main(int argc, char *argv[]) {
    int ret;
    sigset_t sigset;
    struct sigaction sa;

    // Initialize pigpio
    ret = pigpio_init(1);
    if (ret != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_strerror(ret));
        exit(EXIT_FAILURE);
    }

    // Configure GPIO pins
    gpioSetMode(MIC_GPIO, PI_OUTPUT);
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up ADC for GPIO26
    ret = pigpio_set_adc_mode(MIC_GPIO, 1, 10);
    if (ret != 0) {
        fprintf(stderr, "Failed to set ADC mode for GPIO%d: %s\n", MIC_GPIO, pigpio_strerror(ret));
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    // Start the SIGINT handler
    sa.sa_handler = handle_interrupt;
    sigaction(SIGINT, &sa, NULL);
    if (sigaddset(&sigset, SIGINT) == 0) {
        if (sigaction(SIGINT, &sa, NULL) == -1) {
            fprintf(stderr, "Failed to add SIGINT signal: %s\n");
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }
    }

    // Main loop
    while (1) {
        clap_detector();
        usleep(DETECTION_MS * 1000 / HRTIME_PER_SEC);
    }

    // Clean shutdown
    pigpio_terminate();
    return 0;
}

