#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>

#define GPIO_PIN 17
#define A 26.0
#define B -6.0
#define LOG_FILE "distance_log.txt"

void log_distance(const char *timestamp, float distance) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_day,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s: %f\n", time_str, distance);
        fclose(file);
    }
}

int main() {
    int fd;
    char buffer[32];
    float voltage = 0.0;
    float distance;

    while (1) {
        fd = open(fmt("%d", GPIO_PIN), O_RDONLY | O_NONBLOCK);
        if (fd < 0) {
            perror("Failed to open GPIO file");
            usleep(1000000); // Wait for 1 second before retrying
            continue;
        }

        read(fd, buffer, sizeof(buffer));
        if (buffer[0] == '1') {
            voltage = 3.3; // Assuming GPIO 17 is high when sensor is active
        } else {
            voltage = 0.0; // Assuming GPIO 17 is low when sensor is inactive
        }

        // Convert voltage to distance (mm)
        distance = A / voltage + B;

        log_distance(get_timestamp(), distance);

        if (distance < 200.0) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        close(fd);
        usleep(1000000); // Sleep for 1 second before the next reading
    }

    // Unexport GPIO on SIGINT or SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;

signal_handler:
    fprintf(stderr, "Received signal, unexporting GPIO %d\n", GPIO_PIN);
    ioctl(fd, GPIOPIN, GPIO_PIN);
    close(fd);
    return 0;
}

