    float voltage = 0.0;
    float distance;

    while (1) {
        fd = open(fmt("%d", GPIO_PIN), O_RDONLY | O_NONBLOCK);
        if (fd < 0) {
            perror("Failed to open GPIO file");
            usleep(1000000); // Wait for 1 second before retrying
            continue;
        }

        read(fd, buffer, sizeof(buffer));
        if (buffer[0] == '1') {
            voltage = 3.3; // Assuming GPIO 17 is high when sensor is active
        } else {
            voltage = 0.0; // Assuming GPIO 17 is low when sensor is inactive
        }

        // Convert voltage to distance (mm)
        distance = A / voltage + B;

        log_distance(get_timestamp(), distance);

        if (distance < 200.0) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        close(fd);
        usleep(1000000); // Sleep for 1 second before the next reading
    }

    // Unexport GPIO on SIGINT or SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;

signal_handler:
    fprintf(stderr, "Received signal, unexporting GPIO %d\n", GPIO_PIN);
    ioctl(fd, GPIOPIN, GPIO_PIN);
    close(fd);
    return 0;
}
```

This code uses the sysfs GPIO interface on GPIO 17 of a Raspberry Pi 5 to read a digital input from a Sharp GP2Y0A21YK0F IR distance sensor. It treats the GPIO as a digital input (0 or 1) and converts it to a placeholder voltage (0V for low, 3.3V for high). The voltage is then converted to a distance in millimeters using the formula `distance (mm) = A / voltage + B`, with A = 26.0 and B = -6.0.

The program logs each reading with a timestamp to "distance_log.txt" in append mode. It also implements a proximity-based pet feeder activation: if the computed distance is below 200 mm, it prints "Feeder Activated" to the console; otherwise, it prints "Feeder Idle".

The program handles GPIO file open or read errors gracefully by printing an error message and retrying after 1 second. On SIGINT or SIGTERM, it unexports GPIO 17 and exits cleanly. The program runs continuously until interrupted.

