#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define GPIO_CS 8
#define ADC_CS 11
#define ADC_CLK 10
#define ADC_DATA 9

#define SAMPLE_INTERVAL 500

int adc_fd;
int gpio_cs_line;

void spi_init() {
    struct spidev_ioctl_data spi_data = {
        .device = SPI_DEVICE,
        .speed = SPI_SPEED,
        .mode = SPI_MODE,
        .bits = SPI_BITS
    };

    if (spidev_open(0, &spi_data) < 0) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    gpio_cs_line = gpiochip0_line_get(0, 8);
    if (gpio_cs_line < 0) {
        perror("gpiochip0_line_get");
        exit(EXIT_FAILURE);
    }

    gpiod_direction_output_init(gpio_cs_line, 1);
}

void adc_read(int channel) {
    struct spidev_xfer_t xfer = {
        .len = 1,
        .addr = channel,
        .data[0] = 0x00
    };

    if (spidev_xfer(&adc_fd, &xfer, 1) < 0) {
        perror("spidev_xfer");
        return;
    }
}

int main(int argc, char *argv[]) {
    spi_init();
    gpio_init();

    adc_fd = spidev_open(0, NULL);
    if (adc_fd < 0) {
        perror("spidev_open");
        return EXIT_FAILURE;
    }

    gpiod_direction_output_set(gpio_cs_line, 1);

    while (1) {
        adc_read(0); // Read from channel 0 (MCP3008 channel 0)

        int adc_value = spidev_rdwr(adc_fd, NULL, 0, 1);
        if (adc_value < 0) {
            perror("spidev_rdwr");
            continue;
        }

        int vout_mV = adc_value * 3300 / 1023;

        // DRV5055-A1 quiescent output is 1650 mV, so subtract this from Vout_mV
        int B_mV = vout_mV - 1650;

        // Convert to mT
        float B_mT = (float)B_mV / 1000.0;

        // Write to log file
        FILE *log_file = fopen("magnetic_log.txt", "a");
        if (!log_file) {
            perror("fopen");
            continue;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f\n", (long)now, B_mT);
        fclose(log_file);

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up resources on exit
    gpiod_direction_output_free(gpio_cs_line);
    spidev_close(adc_fd);

    return EXIT_SUCCESS;
}

