#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <spidev.h>

#define SPI_DEVICE 0
#define SPI_MODE 0
#define SPI_CPOL 0
#define SPI_CPHA 0
#define ADC_CHANNEL 0
#define LED_PIN 21
#define VCC 3.3
#define SENSITIVITY 1.65
#define THRESHOLD 10.0
#define LOG_FILE "magnetic_log.txt"
#define LOG_INTERVAL 100

int main() {
    int led_gpio = LED_PIN;
    int spi_fd, adc_fd;
    struct spidev_dev *dev;
    int adc_value;
    float voltage, field_mT, adc_reading;
    struct timespec start_time, end_time;
    char log_message[100];

    spi_fd = spidev_open(SPI_DEVICE, 0);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    dev = spidev_get_device(spi_fd);
    if (!dev) {
        perror("Failed to get device");
        spidev_close(spi_fd);
        return EXIT_FAILURE;
    }

    pigpio_init(1); // Initialize pigpio with 1 as the number of available pins

    // Configure SPI
    spidev_control(dev, SPI_SDCC_SCLK, SPI_MODE0);
    spidev_control(dev, SPI_SDCC_MOSI, SPI_CPOL0 | SPI_CPHA0);

    while (1) {
        // Read ADC value
        adc_fd = pigpio_spidev_transfer(spi_fd, 0, 0, 0, &adc_value, 1, 1000);
        if (adc_fd < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        // Convert ADC value to voltage
        voltage = adc_value * VCC / 1023.0;

        // Convert voltage to magnetic field strength
        field_mT = (voltage - VCC / 2) * 1000 / SENSITIVITY;

        // Log the reading
        clock_gettime(CLOCK_REALTIME, &start_time);
        strftime(log_message, sizeof(log_message), "%.2f", field_mT);
        write(fileno(LOG_FILE), log_message, strlen(log_message));
        clock_gettime(CLOCK_REALTIME, &end_time);
        double elapsed_ms = (end_time.tv_sec - start_time.tv_sec) * 1000 + (end_time.tv_nsec - end_time.tv_nsec) / 1000000 - (start_time.tv_sec - end_time.tv_sec);
        fprintf(LOG_FILE, "Read at %ld ms\n", (long int)elapsed_ms);

        // Check if field exceeds threshold
        if (field_mT > THRESHOLD) {
            pigpio_set_mode(led_gpio, PIGIO_OUTPUT);
            pigpio_write(led_gpio, 1);
        } else {
            pigpio_set_mode(led_gpio, PIGIO_OUTPUT);
            pigpio_write(led_gpio, 0);
        }

        usleep(LOG_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    // Clean up
    pigpio_stop();
    spidev_close(spi_fd);
    return EXIT_SUCCESS;
}

