#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/mman.h>

#define SPI_CHANNEL 0
#define MCP3008_ADDRESS 0x20
#define ADC_CHANNEL 0
#define ADC_START_BIT 0x01
#define ADC_MODE 0x80
#define MCP3008_RX_BUF_SIZE 2

#define LOG_FILE "moisture_log.txt"

void spi_init() {
    int fd = open(SPI_CHANNEL, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open SPI channel");
        exit(EXIT_FAILURE);
    }

    struct spi_fd_info info;
    memset(&info, 0, sizeof(info));
    info.fd = fd;
    info.speed_hz = 1000000; // 1 MHz
    info.mode = SPI_MODE0;

    if (spi_init(info) < 0) {
        perror("Failed to initialize SPI");
        exit(EXIT_FAILURE);
    }
}

int read_adc(int channel) {
    int ret = spi_write(&channel, ADC_START_BIT | ADC_MODE);
    if (ret < 0) {
        perror("Failed to write to MCP3008");
        return -1;
    }

    ret = spi_read(&channel, MCP3008_RX_BUF, MCP3008_RX_BUF_SIZE);
    if (ret < 0) {
        perror("Failed to read from MCP3008");
        return -1;
    }

    int adc_value = (MCP3008_RX_BUF[1] & 0x03) << 8 | MCP3008_RX_BUF[2] & 0x7F;
    return adc_value;
}

void log_reading(int adc_value) {
    time_t now = time(NULL);
    char timestamp[20];
    sprintf(timestamp, "%d-%04d %02d:%02d:%02d", now / 24, now % 24, now % 120, now % 60, now % 60);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s: %d\n", timestamp, adc_value);
    fclose(log_file);
}

void signal_handler(int signum) {
    spi_close(SPI_CHANNEL);
    pigpio_terminate();
    exit(signum == SIGINT ? 0 : EXIT_FAILURE);
}

int main() {
    signal(SIGINT, signal_handler);

    spi_init();

    pigpio_init(1);

    while (1) {
        int adc_value = read_adc(MCP3008_ADDRESS);
        if (adc_value != -1) {
            log_reading(adc_value);
        }

        usleep(60000000); // 60 seconds
    }

    return 0;
}

