#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <stdlib.h>
#include <pigpio.h>

#define SPI_BUS 0
#define CE_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define SPI_SPEED 1000000
#define SPI_MODE 0

#define MLX91211_CHANNEL 0

volatile int quit_loop = 0;

void spiError(const char *msg) {
    fprintf(stderr, "SPI error: %s\n", msg);
    exit(1);
}

void spiDelay(unsigned long ms) {
    usleep(ms * 1000);
}

void spiXfer(const void *tx, void *rx) {
    int ret = spiTransfer(tx, rx, sizeof(tx), SPI_SPEED, SPI_MODE);
    if (ret < 0) {
        spiError("SPI transfer failed");
    }
}

void logCurrent(double current) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[9];
    sprintf(timestamp, "%4d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *logFile = fopen("current_log.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open current_log.txt\n");
        spiClose(SPI_BUS);
        pigpio_terminate(0);
        exit(1);
    }
    fprintf(logFile, "%s XX.XX A\n", timestamp);
    fclose(logFile);
}

int main(int argc, char *argv[]) {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        spiClose(SPI_BUS);
        pigpio_terminate(0);
        exit(1);
    }

    if (spiOpen(SPI_BUS, CE_PIN) < 0) {
        fprintf(stderr, "Failed to open SPI0\n");
        spiClose(SPI_BUS);
        pigpio_terminate(0);
        exit(1);
    }

    if (spiSetMode(SPI_BUS, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        spiClose(SPI_BUS);
        pigpio_terminate(0);
        exit(1);
    }

    if (spiSetClockDivider(SPI_BUS, SPI_SPEED / 1000) < 0) {
        fprintf(stderr, "Failed to set SPI clock divider\n");
        spiClose(SPI_BUS);
        pigpio_terminate(0);
        exit(1);
    }

    if (spiOpen(SPI_BUS, CE_PIN) < 0) {
        fprintf(stderr, "Failed to open SPI0\n");
        spiClose(SPI_BUS);
        pigpio_terminate(0);
        exit(1);
    }

    while (!quit_loop) {
        unsigned char tx[3] = {0x01, 0x80 | (MLX91211_CHANNEL << 4), 0x00};
        unsigned char rx[3];

        if (spiXfer(tx, rx) < 0) {
            spiError("SPI transfer failed");
            continue;
        }

        int rawValue = rx[1] & 0x03;
        rawValue = ((rawValue << 8) | rx[2]);

        if (rawValue < 0 || rawValue > 1023) {
            fprintf(stderr, "SPI transfer error: raw value out of range\n");
            continue;
        }

        double voltage = (rawValue * 2.0 / 1023.0) * 2.5;
        if (voltage < 0.0 || voltage > 5.0) {
            fprintf(stderr, "Warning: voltage out of range\n");
            continue;
        }

        double current = (voltage - 2.5) * (50.0 / 2.5);
        logCurrent(current);
    }

    spiClose(SPI_BUS);
    pigpio_terminate(0);

    return 0;
}

void signalHandler(int signum) {
    global_signal_handler(SIGINT, quit_loop = 1);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signalHandler);

    // Initialize pigpio, open SPI, and start the main loop
    // ...

    return 0;
}

