#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define DEBOUNCE_INTERVAL 2000  // 2 ms
#define SAMPLE_COUNT 5

int sensor_1_state = 0;
int sensor_2_state = 0;

void debounce(int *sensor_pin) {
    static int last_state = -1;
    int current_state = *sensor_pin;
    int timeout = DEBOUNCE_INTERVAL;

    while (current_state == last_state && timeout > 0) {
        usleep(100000);  // 100 ms delay
        *sensor_pin = 0;  // Pull down the line
        current_state = *sensor_pin;
        timeout--;
    }

    last_state = current_state;
}

void read_sensors() {
    debounce(&sensor_1_state);
    debounce(&sensor_2_state);
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        gpiod_line_release(gpiod_line_from_gpio_number(SENSOR_1_GPIO));
        gpiod_line_release(gpiod_line_from_gpio_number(SENSOR_2_GPIO));
        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(0);
    }
}

int main() {
    struct gpiod_line *lines[2];
    struct gpiod_chip *chip;

    // Open GPIO chip
    if (gpiod_chip_open_by_number(0) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for GPIO4 and GPIO17
    if (gpiod_chip_request_lines(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO), 2) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(EXIT_FAILURE);
    }

    lines[0] = gpiod_line_from_gpio_number(SENSOR_1_GPIO);
    lines[1] = gpiod_line_from_gpio_number(SENSOR_2_GPIO);

    // Set lines as inputs with pull-up enabled
    if (gpiod_line_direction_input(lines[0]) < 0) {
        perror("Failed to set line direction");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_direction_input(lines[1]) < 0) {
        perror("Failed to set line direction");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_pull_up_enable(lines[0]) < 0) {
        perror("Failed to enable pull-up");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_pull_up_enable(lines[1]) < 0) {
        perror("Failed to enable pull-up");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(EXIT_FAILURE);
    }

    // Request input lines
    if (gpiod_line_request_input(lines[0]) < 0) {
        perror("Failed to request input on line");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(lines[1]) < 0) {
        perror("Failed to request input on line");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        read_sensors();

        if (sensor_1_state == 0 && sensor_2_state == 0) {
            printf("Both sensors: No object detected\n");
        } else if (sensor_1_state == 0) {
            printf("Sensor 1: No object detected\n");
        } else if (sensor_2_state == 0) {
            printf("Sensor 2: No object detected\n");
        } else {
            printf("Alert: Both sensors detect object\n");
        }

        usleep(1000000);  // Sleep for 1 second
    }

    // Signal handler setup
    signal(SIGINT, signal_handler);

    return 0;
}

