        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(EXIT_FAILURE);
    }

    // Request input lines
    if (gpiod_line_request_input(lines[0]) < 0) {
        perror("Failed to request input on line");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(lines[1]) < 0) {
        perror("Failed to request input on line");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(gpiod_chip_from_gpio_numbers(SENSOR_1_GPIO, SENSOR_2_GPIO));
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        read_sensors();

        if (sensor_1_state == 0 && sensor_2_state == 0) {
            printf("Both sensors: No object detected\n");
        } else if (sensor_1_state == 0) {
            printf("Sensor 1: No object detected\n");
        } else if (sensor_2_state == 0) {
            printf("Sensor 2: No object detected\n");
        } else {
            printf("Alert: Both sensors detect object\n");
        }

        usleep(1000000);  // Sleep for 1 second
    }

    // Signal handler setup
    signal(SIGINT, signal_handler);

    return 0;
}
