#include <stdbool.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t termination_flag = 0;

void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    termination_flag = 1;
    pigpio_terminate();
    exit(0);
}

void spi_setup(spi_config_t *config) {
    if (spi_init(SPI_CHANNEL, SPI_BAUD, config) < 0) {
        perror("Failed to initialize SPI");
        exit(EXIT_FAILURE);
    }
}

int read_mcp3008(int channel) {
    uint8_t tx_buf[3] = {0x01, (channel << 4) | 0x80, 0x00};
    uint8_t rx_buf[2];

    if (spi_transfer(tx_buf, 2, rx_buf) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return rx_buf[1] << 8 | rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        return -1.0; // Invalid ADC value
    }

    double moisture_percentage = 100.0 - ((adc_value - MIN_ADC) * 100.0 / (MAX_ADC - MIN_ADC));
    return moisture_percentage;
}

void log_data(double moisture_level) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp[8];
    sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d", time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday, time_info->tm_hour, time_info->tm_min, time_info->tm_sec);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%.2f\n", timestamp, moisture_level);
    fclose(file);

    printf("Logged: %s, %.2f\n", timestamp, moisture_level);
}

int main() {
    sigset_t sigset;
    memset(&sigset, 0, sizeof(sigset));
    sigaddset(&sigset, SIGINT);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    spi_config_t config;
    spi_setup(&config);

    pigpio_init(SPI_BAUD);

    while (!termination_flag) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            perror("Failed to read from MCP3008");
            usleep(100000); // Retry after 100ms
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        if (moisture_level == -1.0) {
            continue; // Invalid ADC value, skip logging
        }

        log_data(moisture_level);

        usleep(READ_DELAY * 1000000); // Delay for 60 seconds
    }

    pigpio_terminate();
    return 0;
}

