#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>

#define PIR_PIN 17
#define POLL_INTERVAL 50
#define DEBOUNCE_DELAY 200
#define CAMERA_IMAGE_WIDTH 1280
#define CAMERA_IMAGE_HEIGHT 720
#define CAMERA_IMAGE_FORMAT "jpeg"
#define TIMESTAMP_FORMAT "%Y-%m-%dT%H:%M:%S"
#define CAMERA_IMAGE_PATH "/home/pi/security_cam/security_cam_%Y%m%d_%H%M%S.jpg"

void log_event(const char *level, const char *msg) {
    static int syslog_fd = -1;
    if (syslog_fd == -1) {
        syslog_fd = open("log", O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (syslog_fd == -1) {
            syslog(LOG_CRIT, "Failed to open syslog file");
            exit(EXIT_FAILURE);
        }
    }
    syslog(LOG_INFO, "%s: %s", level, msg);
    fflush(syslog_fd);
}

void init_pigpio() {
    if (piGPIO_init() < 0) {
        log_event("ERROR", "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void configure_gpio(int pin) {
    if (gpioSetup(pin, PI_OUTPUT) < 0) {
        log_event("ERROR", "Failed to configure GPIO%d as output", pin);
        exit(EXIT_FAILURE);
    }
}

void set_pull_up(int pin) {
    gpioOutput(pin, PI_OUTPUT_PULLUP);
}

void configure_pir(int pin) {
    gpioMode(pin, PI_INPUT);
    gpioEdge(pin, PI_FALLING);
    gpioRead(pin, &read_state);
}

void debounce(int pin) {
    static int last_state = 0;
    static int debounce_timer = 0;
    if (read_state == 0) {
        debounce_timer = 0;
    } else {
        debounce_timer++;
    }
    if (debounce_timer >= DEBOUNCE_DELAY) {
        last_state = read_state;
        gpioRead(pin, &read_state);
        debounce_timer = 0;
    }
}

void capture_image() {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still --format %s --width %d --height %d --output %s",
             CAMERA_IMAGE_FORMAT, CAMERA_IMAGE_WIDTH, CAMERA_IMAGE_HEIGHT, CAMERA_IMAGE_PATH);
    log_event("INFO", "Executing: %s", command);
    if (fork() == 0) {
        if (execlp("libcamera-still", "libcamera-still", command, NULL) == -1) {
            log_event("ERROR", "Failed to execute libcamera-still");
            exit(EXIT_FAILURE);
        }
    } else {
        wait(NULL);
        if (WIFEXITED(waitpid(0, NULL, 0))) {
            if (WEXITSTATUS() != 0) {
                log_event("ERROR", "libcamera-still child process exited with error");
            }
        }
    }
}

int main() {
    init_pigpio();
    configure_pir(PIR_PIN);
    set_pull_up(PIR_PIN);

    log_event("INFO", "Starting motion detection loop");

    while (1) {
        gpioRead(PIR_PIN, &read_state);
        debounce(PIR_PIN);
        if (read_state == 1 && last_state == 0) {
            capture_image();
            last_state = read_state;
        }
        usleep(POLL_INTERVAL * 1000 / 1000);
    }

    log_event("INFO", "Stopping motion detection loop");
    piGPIO_shutdown();
    close(syslog_fd);
    syslog(LOG_INFO, "Exiting");
    return 0;
}

