int main(int argc, char *argv[]) {
    int fd, ret;
    struct v4l2_requestcode rc;
    struct v4l2_format fmt;
    struct v4l2_pixfmt_gray8 gray;
    struct timeval tv;
    char filename[20];

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <device_path>\n", argv[0]);
        return 1;
    }

    fd = open(argv[1], O_RDWR | O_SYNC);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    ret = ioctl(fd, VIDIOC_QUERYSTREAMPARAM, &fmt);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    rc = V4L2_BUF_TYPE_VIDEO_OUTPUT;
    fmt.pix_fmt = fmt.pix_fmt;
    fmt.width = fmt.width;
    fmt.height = fmt.height;
    fmt.field = V4L2_FIELD_INTERLACE_NONE;
    fmt.timebase = fmt.timebase;
    fmt.pixel_aspect_ratio = fmt.pixel_aspect_ratio;
    fmt.flags = 0;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    gray.format = V4L2_PIX_FMT_GRAY8;
    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    gray.pixel_mask = V4L2_PIX_FMT_GRAY8_MASK;

    // Set up mmap for memory-mapped streaming
    struct v4l2_requestbuffer reqbuf;
    reqbuf.type = V4L2_BUF_TYPE_REQUEST_BUFFER;
    reqbuf.index = 0;
    reqbuf.memory = V4L2_MEMORY_MMAP;
    reqbuf.length = BUFFER_SIZE;

    ret = ioctl(fd, VIDIOC_REQBUFS(&reqbuf, 1);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    while (1) {
        memset(&reqbuf, 0, sizeof(reqbuf));
        reqbuf.type = V4L2_BUF_TYPE_OUTPUT;
        reqbuf.memory = V4L2_MEMORY_MMAP;
        reqbuf.index = 0;
        reqbuf.length = BUFFER_SIZE;

        ret = ioctl(fd, VIDIOC_QUERYFMT(fd), &fmt);
        if (ret < 0) {
            perror("ioctl");
            break;
        }

