int main(int argc, char *argv[]) {
    int fd, ret;
    struct v4l2_requestcode rc;
    struct v4l2_format fmt;
    struct v4l2_pixfmt_gray8 gray;
    struct timeval tv;
    char filename[20];

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <device_path>\n", argv[0]);
        return 1;
    }

    fd = open(argv[1], O_RDWR | O_SYNC);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    ret = ioctl(fd, VIDIOC_QUERYSTREAMPARAM, &fmt);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
