#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <arpa/inet.h>
#include <errno.h>
#include <linux/videodev2.h>
#include <linux/uaccess.h>

#define BUFFER_SIZE 640 * 480 * 2 // 4 buffers, YUYV, 2 bytes per pixel
#define FRAGMENT_SIZE 65000
#define FRAGMENT_HEADER_SIZE 16

struct frame_header {
    uint32_t index;
    uint32_t fragment_index;
    uint32_t total_fragments;
    uint32_t payload_size;
};

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char *server_ip = argv[1];
    unsigned short server_port = atoi(argv[2]);

    int video_fd = open("/dev/video0", O_RDWR | O_SYNC);
    if (video_fd == -1) {
        perror("Failed to open /dev/video0");
        return 1;
    }

    struct v4l2_compat v4l2_compat;
    memset(&v4l2_compat, 0, sizeof(v4l2_compat));
    v4l2_compat.version = V4L2_VERSION_2_0;
    v4l2_compat.capability = V4L2_CAP_MMAP;

    if (ioctl(video_fd, VIDIOC_S_MMAP, &v4l2_compat) == -1) {
        perror("Failed to set V4L2_CAP_MMAP");
        close(video_fd);
        return 1;
    }

    void *buf_map = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, 0);
    if (buf_map == MAP_FAILED) {
        perror("Failed to mmap /dev/video0");
        close(video_fd);
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    server_addr.sin_addr.s_addr = inet_addr(server_ip);

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("Failed to create socket");
        munmap(buf_map, BUFFER_SIZE);
        close(video_fd);
        return 1;
    }

    struct frame_header header;
    header.index = 0;
    header.total_fragments = 0;

    while (1) {
        uint8_t *frame_buffer = buf_map;
        uint32_t payload_size = BUFFER_SIZE;

        // Capture a frame
        int ret = ioctl(video_fd, VIDIOC_DQBUF, &frame_buffer);
        if (ret < 0) {
            perror("Failed to capture frame");
            break;
        }

        // Process and fragment the frame
        uint32_t fragment_index = 0;
        while (fragment_index < 4 && ret == 0) {
            uint32_t start = fragment_index * FRAGMENT_SIZE;
            uint32_t end = (fragment_index + 1) * FRAGMENT_SIZE;
            if (end > BUFFER_SIZE) end = BUFFER_SIZE;

            uint8_t *fragment = (uint8_t *)buf_map + start;
            ret = sendto(sockfd, fragment, end - start, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
            if (ret == -1) {
                perror("Failed to send fragment");
                break;
            }

            header.fragment_index = fragment_index;
            header.payload_size = end - start;
            header.total_fragments++;

            munmap(frame_buffer, payload_size);
            frame_buffer = (uint8_t *)buf_map + end;
            payload_size = end - start;
        }

        // Update the header
        header.total_fragments++;

        // Send the header
        ret = sendto(sockfd, &header, sizeof(header), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
        if (ret == -1) {
            perror("Failed to send header");
            break;
        }
    }

    munmap(buf_map, BUFFER_SIZE);
    close(sockfd);
    close(video_fd);

    printf("Streaming stopped.\n");
    return 0;
}

