#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_FILE "/dev/video0"
#define BUFFER_COUNT 4
#define PIX_FMT_MJPEG V4L2_PIX_FMT_MJPEG
#define FIELD_NONE V4L2_FIELD_NONE

int main(int argc, char *argv[]) {
    int fd, ret;
    struct v4l2_requestbuffer reqbuf;
    unsigned char *buf;
    long total_bytes;

    fd = open(DEVICE_FILE, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbuf.index = 0;
    reqbuf.memory = V4L2_MEMORY_MMAP;
    reqbuf.length = 1920 * 1080 * 2; // 1920x1080 with 2 bytes per pixel (MJPEG)
    reqbuf.flags = 0;

    if (ioctl(fd, VIDIOC_REQUESTBUFFER, &reqbuf) < 0) {
        perror("VIDIOC_REQUESTBUFFER");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYSTREAMPARAM, &reqbuf) < 0) {
        perror("VIDIOC_QUERYSTREAMPARAM");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (!(reqbuf.flags & V4L2_BUF_TYPE_VIDEO_CAPTURE) || !(reqbuf.memory & V4L2_MEMORY_MMAP)) {
        perror("Unsupported buffer type or memory");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (!(reqbuf.pix_fmt & (V4L2_PIX_FMT_MJPEG | V4L2_PIX_FMT_YUYV | V4L2_PIX_FMT_RGB24))) {
        perror("Unsupported pixel format");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (!(reqbuf.field & V4L2_FIELD_NONE)) {
        perror("Unsupported field");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (reqbuf.length % 2 != 0) {
        perror("Invalid buffer length");
        close(fd);
        exit(EXIT_FAILURE);
    }

    buf = mmap(NULL, reqbuf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buf == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_QBUF, &reqbuf);
    if (ret < 0) {
        perror("VIDIOC_QBUF");
        munmap(buf, reqbuf.length);
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_QUERYBUF, &reqbuf);
    if (ret < 0) {
        perror("VIDIOC_QUERYBUF");
        munmap(buf, reqbuf.length);
        close(fd);
        exit(EXIT_FAILURE);
    }

    total_bytes = reqbuf.length;

    while (total_bytes > 0) {
        ret = ioctl(fd, VIDIOC_DQBUF, &reqbuf);
        if (ret < 0) {
            perror("VIDIOC_DQBUF");
            break;
        }

        if (ret == 0) {
            munmap(buf, reqbuf.length);
            reqbuf.index++;
            total_bytes -= reqbuf.length;
            reqbuf.length = total_bytes;
            continue;
        }

        if (ret == -EAGAIN) {
            // Device is not ready, wait for a bit
            sleep(1);
            continue;
        }

        perror("VIDIOC_DQBUF");
        break;
    }

    munmap(buf, reqbuf.length);
    close(fd);

    // Write raw MJPEG bytes to disk
    FILE *fp = fopen("image.jpg", "wb");
    if (!fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fwrite(buf, 1, total_bytes, fp);
    fclose(fp);

    return 0;
}

// SIGINT/SIGTERM handler
void signal_handler(int signum) {
    printf("Exiting...\n");
    exit(signum == SIGINT || signum == SIGTERM ? 0 : EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Rest of the main function as shown above

    return 0;
}

