    if (cap.num_formats == 0) {
        printf("No supported resolutions.\n");
        close(fd);
        return EXIT_SUCCESS;
    }

    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frame_sizes) < 0) {
        perror("Failed to enumerate frame sizes");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Supported frame sizes:\n");
    for (int i = 0; i < frame_sizes.count; i++) {
        printf("  %dx%d\n", frame_sizes.sizes[i].width, frame_sizes.sizes[i].height);
    }

