        printf("No supported frame sizes.\n");
        close(fd);
        return EXIT_SUCCESS;
    }

    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frame_intervals) < 0) {
        perror("Failed to enumerate frame intervals");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Supported frame intervals:\n");
    for (int i = 0; i < frame_intervals.count; i++) {
        printf("  %d\n", frame_intervals.intervals[i].interval);
    }

    if (frame_intervals.count == 0) {
        printf("No supported frame intervals.\n");
        close(fd);
        return EXIT_SUCCESS;
    }

    if (ioctl(fd, VIDIOC_QUERYCTRL, &focus_control) < 0) {
        perror("Failed to query focus control");
        close(fd);
        return EXIT_FAILURE;
    }

    if (focus_control.id != V4L2_CID_FOCUS_AUTO) {
        printf("Camera does not support autofocus.\n");
        close(fd);
        return EXIT_SUCCESS;
    }

    printf("Autofocus support is available.\n");

    close(fd);
    return EXIT_SUCCESS;
}

