#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_GPIO 4
#define TILT_GPIO 5
#define UP_GPIO 6
#define DOWN_GPIO 7
#define LEFT_GPIO 8
#define RIGHT_GPIO 9
#define CENTER_PULSE 1500

void handle_interrupt(int sig) {
    pigpio_stop(PAN_GPIO);
    pigpio_stop(TILT_GPIO);
    pigpio_terminate(1000);
    exit(0);
}

int main() {
    if (pigpioInit() < 0) {
        fprintf(stderr, "pigpioInit() failed\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);
    gpioSetPullUp(UP_GPIO);
    gpioSetPullUp(DOWN_GPIO);
    gpioSetPullUp(LEFT_GPIO);
    gpioSetPullUp(RIGHT_GPIO);

    gpioServo(PAN_GPIO, CENTER_PULSE);
    gpioServo(TILT_GPIO, CENTER_PULSE);

    printf("Camera Pan-Tilt System\n");
    printf("GPIO4: Pan Servo\n");
    printf("GPIO5: Tilt Servo\n");
    printf("GPIO6: Up Button\n");
    printf("GPIO7: Down Button\n");
    printf("GPIO8: Left Button\n");
    printf("GPIO9: Right Button\n");
    printf("Center Pulse: %d us\n", CENTER_PULSE);

    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    while (1) {
        int button_state = gpioRead(UP_GPIO) || gpioRead(DOWN_GPIO) || gpioRead(LEFT_GPIO) || gpioRead(RIGHT_GPIO);

        if (button_state) {
            if (gpioRead(UP_GPIO)) {
                gpioServo(PAN_GPIO, gpioServoGet(PAN_GPIO) + 10);
            } else if (gpioRead(DOWN_GPIO)) {
                gpioServo(PAN_GPIO, gpioServoGet(PAN_GPIO) - 10);
            } else if (gpioRead(LEFT_GPIO)) {
                gpioServo(TILT_GPIO, gpioServoGet(TILT_GPIO) + 10);
            } else if (gpioRead(RIGHT_GPIO)) {
                gpioServo(TILT_GPIO, gpioServoGet(TILT_GPIO) - 10);
            }
        }

        usleep(50000); // 50 ms loop delay
    }

    pigpio_terminate(1000);
    return 0;
}

