#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>

#define WIDTH 640
#define HEIGHT 480
#define PIX_FMT_YUYV 0
#define FIELD_NONE 0

#define BUFFER_SIZE (200 * 150 * 2)
#define CROP_START_X 100
#define CROP_START_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

int main() {
    int fd;
    struct v4l2_format fmt;
    struct v4l2_pixfmt_yuyv fmt_yuyv;
    struct v4l2_queryconfig qconfig;
    struct v4l2_requestbuffers reqbuf;
    int buf_fd;
    unsigned char *buffer;
    FILE *fp;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open("/dev/video0", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &qconfig) < 0) {
        perror("VIDIOC_QUERYCAP");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < qconfig.n_formats; i++) {
        if (qconfig.formats[i].pix_fmt == PIX_FMT_YUYV) {
            fmt = qconfig.formats[i];
            break;
        }
    }
    if (!fmt.pix_fmt) {
        perror("PIX_FMT_YUYV not found");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_REQBUFS, &reqbuf) < 0) {
        perror("VIDIOC_REQBUFS");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYBUF, &reqbuf) < 0) {
        perror("VIDIOC_QUERYBUF");
        exit(EXIT_FAILURE);
    }

    buf_fd = mmap(NULL, reqbuf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, reqbuf.offset);
    if (buf_fd == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QBUF, buf_fd) < 0) {
        perror("VIDIOC_QBUF");
        exit(EXIT_FAILURE);
    }

    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
    buf.data.ptr = buf_fd;
    buf.length = reqbuf.length;

    while (1) {
        if (select(buf_fd + reqbuf.offset, NULL, NULL, NULL, NULL, NULL, 0) == 0) {
            if (ioctl(fd, VIDIOC_QBUF, buf_fd) < 0) {
                perror("VIDIOC_QBUF");
                exit(EXIT_FAILURE);
            }
        }
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        exit(EXIT_FAILURE);
    }

    struct v4l2_buffer *outbuf = (struct v4l2_buffer *)&buf;
    if (outbuf->type != V4L2_BUF_TYPE_VIDEO_OUTPUT) {
        perror("Invalid buffer type");
        exit(EXIT_FAILURE);
    }

    if (outbuf->data.ptr == outbuf->length) {
        perror("Buffer underflow");
        exit(EXIT_FAILURE);
    }

    struct v4l2_pix_format yuyv;
    if (ioctl(fd, VIDIOC_QUERY_FORMAT, &fmt) < 0) {
        perror("VIDIOC_QUERY_FORMAT");
        exit(EXIT_FAILURE);
    }

    if (yuyv.pix_fmt != PIX_FMT_YUYV) {
        perror("Unexpected pixel format");
        exit(EXIT_FAILURE);
    }

    if (outbuf->length < (WIDTH * HEIGHT * 2)) {
        perror("Buffer too small");
        exit(EXIT_FAILURE);
    }

    buffer = outbuf->data.ptr;
    int y_offset = 0, u_offset = 0, v_offset = 0;

    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            int index = y * WIDTH + x;
            int y_index = index * 2;
            int u_index = y_index + 1;
            int v_index = (y + HEIGHT / 2) * WIDTH + x;

            if (x >= CROP_START_X && x + CROP_WIDTH <= CROP_START_X + CROP_WIDTH &&
                y >= CROP_START_Y && y + CROP_HEIGHT <= CROP_START_Y + CROP_HEIGHT) {
                y_offset += 1;
                u_offset += 1;
                v_offset += 1;
            }

            buffer[y_offset] = buffer[u_offset];
            buffer[y_offset + 1] = buffer[v_index];
            buffer[y_offset + 2] = buffer[y_index];
            buffer[y_offset + 3] = buffer[y_index + 1];

            y_offset += 4;
        }
    }

    fp = fopen("cropped.yuv", "wb");
    if (!fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fwrite(buffer, 1, BUFFER_SIZE, fp);
    fclose(fp);

    munmap(buf_fd, reqbuf.length);
    close(fd);

    return 0;
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, cleaning up...\n", signum);
    munmap(buf_fd, reqbuf.length);
    close(fd);
    exit(EXIT_SUCCESS);
}

void setup_signal_handlers() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
}

int main(int argc, char *argv[]) {
    setup_signal_handlers();
    main();
    return 0;
}

