#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PAN_GPIO 17
#define SERVO_TILT_GPIO 18
#define INITIAL_ANGLE 90
#define INCREMENT 5
#define MAX_ANGLE 180
#define PWM_FREQ 50
#define PWM_MIN_US 500
#define PWM_MAX_US 2500

int pan_angle = INITIAL_ANGLE;
int tilt_angle = INITIAL_ANGLE;

void handle_key_input(int key) {
    switch (key) {
        case 47:  // up arrow
            pan_angle = (pan_angle + INCREMENT) % MAX_ANGLE;
            break;
        case 50:  // down arrow
            pan_angle = (pan_angle - INCREMENT + MAX_ANGLE) % MAX_ANGLE;
            break;
        case 38:  // left arrow
            tilt_angle = (tilt_angle - INCREMENT) % MAX_ANGLE;
            break;
        case 40:  // right arrow
            tilt_angle = (tilt_angle + INCREMENT) % MAX_ANGLE;
            break;
        case 27: // ESC
            pan_angle = INITIAL_ANGLE;
            tilt_angle = INITIAL_ANGLE;
            pigpio_stop();
            exit(0);
        case 13: // enter key
            pigpio_stop();
            exit(0);
        case 10: // 'q' key
            pan_angle = INITIAL_ANGLE;
            tilt_angle = INITIAL_ANGLE;
            pigpio_stop();
            exit(0);
    }
}

void setup_servo(int gpio) {
    if (gpio < 1 || gpio > 255) {
        fprintf(stderr, "Error: Invalid GPIO pin.\n");
        exit(1);
    }

    if (pigpio_begin() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio.\n");
        exit(1);
    }

    if (pigpio_set_mode(gpio, PIGPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode.\n");
        pigpio_stop();
        exit(1);
    }
}

void set_servo_angle(int gpio, int angle) {
    if (angle < PWM_MIN_US || angle > PWM_MAX_US) {
        fprintf(stderr, "Error: Angle out of range. Must be between %d and %d us.\n", PWM_MIN_US, PWM_MAX_US);
        exit(1);
    }

    if (pigpio_set_servo_pulsewidth(gpio, angle) < 0) {
        fprintf(stderr, "Error: Failed to set servo pulsewidth.\n");
        exit(1);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_key_input);

    setup_servo(SERVO_PAN_GPIO);
    setup_servo(SERVO_TILT_GPIO);

    while (1) {
        usleep(100000); // 100 ms delay
        set_servo_angle(SERVO_PAN_GPIO, pan_angle * 20); // Convert to microseconds
        set_servo_angle(SERVO_TILT_GPIO, tilt_angle * 20);

        handle_key_input(getchar());
    }

    pigpio_stop();
    return 0;
}

