    // Main loop
    while (1) {
        read_cpu_temp();
        read_cpu_usage();
        update_display("CPU Temp: ", 0, 0);
        update_display("Usage: ", 10, 0);
        usleep(1000000); // Update every second
    }

    // Clean up and exit
    ssd1306_free();
    pigpio_terminate(1000);
    return 0;
}

// Initialize pigpio
int init_pigpio(int gpio_num) {
    int ret = pigpio_begin(gpio_num);
    if (ret < 0) {
        perror("Failed to initialize pigpio");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c(int bus, int address) {
    int ret = i2c_open(bus, address);
    if (ret < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return ret;
}

// Update the OLED display
void update_display(const char *text, int x, int y) {
    ssd1306_clear();
    ssd1306_draw_string(text, x, y, 1, SSD1306_LEFT_JUSTIFY);
}

// Read CPU temperature
void read_cpu_temp() {
    FILE *temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!temp_file) {
        handle_error("Failed to read CPU temperature");
        return;
    }
    char temp_str[10];
    fgets(temp_str, sizeof(temp_str), temp_file);
    fclose(temp_file);

    if (sscanf(temp_str, "%d", &temp_value) != 1) {
        handle_error("Failed to parse CPU temperature");
        return;
    }

    // Convert to Celsius
    float celsius = temp_value / 1000.0;
    update_display("CPU Temp: ", 0, 0);
    update_display(std::to_string(celsius).c_str(), 4, 0);
}

// Read CPU usage
void read_cpu_usage() {
    FILE *usage_file = fopen("/proc/stat", "r");
    if (!usage_file) {
        handle_error("Failed to read CPU usage");
        return;
    }

    char usage_str[10];
    while (fgets(usage_str, sizeof(usage_str), usage_file)) {
        if (strncmp(usage_str, "cpu", 3) == 0) {
            char *usage_value = strsep(&usage_str, " ");
            long usage_value_long = strtol(usage_value, NULL, 10);
            update_display("Usage: ", 10, 0);
            update_display(std::to_string(usage_value_long).c_str(), 8, 0);
            break;
        }
    }

    fclose(usage_file);
}

// Handle errors
void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}
