            update_lcd(flow_rate, volume);
            last_update_time = time(NULL);
        }
    }

    // Clean up and exit
    piGPIOExit();
    close(lcd_fd);
    i2c_close(lcd_client);
    return 0;
}

void signal_handler(int signum) {
