#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x27
#define SPI_BUS 1
#define SPI_CE0 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 500
#define MAX_PULSES_PER_SAMPLE 1000

#define LCD_ADDRESS 0x27
#define LCD_DATA_PORT 0x3F
#define LCD_R 0
#define LCD_W 16
#define LCD_LINES 2

void interruptHandler(int intid) {
    static int pulseCount = 0;
    static unsigned long lastUpdate = 0;

    if (intid == 1) {
        pulseCount++;
    }

    if (pulseCount > MAX_PULSES_PER_SAMPLE) {
        pulseCount = 0;
        unsigned long currentTime = pigpioGettime();
        if (currentTime - lastUpdate > SAMPLE_INTERVAL_MS / 1000) {
            double windSpeed = (double)pulseCount * 0.5;
            printf("Wind Speed: %.2f m/s\n", windSpeed);
            lastUpdate = pigpioGettime();
        }
    }
}

int main() {
    int spiHandle, i2cHandle;
    int adcHandle;
    int adcValue;
    unsigned long lastWindSpeed = 0;

    pigpioInit(100000); // Initialize pigpio with 100kHz update rate

    // Initialize I2C
    i2cHandle = bbI2COpen(I2C_ADDRESS, SPI_BUS);
    if (i2cHandle == -1) {
        perror("I2C initialization failed");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI
    spiHandle = spi0SPIOpen(SPI_CE0, SPI_BUS);
    if (spiHandle == -1) {
        perror("SPI initialization failed");
        exit(EXIT_FAILURE);
    }

    // Initialize MCP3008 ADC
    adcHandle = pigpioSPIRegisterOutput(spiHandle, ADC_CHANNEL);
    if (adcHandle == -1) {
        perror("ADC initialization failed");
        exit(EXIT_FAILURE);
    }

    // Register interrupt handler
    pigpioSetMode(gpio17, PIGIO_OUTPUT);
    pigpioSetInterrupt(gpio17, PIGIO_RISE, interruptHandler);

    // Initialize LCD
    pigpioI2CWrite(i2cHandle, LCD_ADDRESS, LCD_R, 0x80); // Set display on
    pigpioI2CWrite(i2cHandle, LCD_ADDRESS, LCD_R, 0x01); // Clear display
    pigpioI2CWrite(i2cHandle, LCD_ADDRESS, LCD_R, 0x0C); // Set cursor to home

    // Main loop
    while (1) {
        // Read wind vane from ADC
        if (pigpioSPIRead(spiHandle, adcHandle, &adcValue) == -1) {
            perror("ADC read failed");
            continue;
        }

        // Map ADC value to wind direction
        double direction = adcValue * 3.6; // 10-bit ADC maps to 0-359 degrees
        if (direction == 0 || direction == 1024) {
            printf("ADC stuck at 0 or 1023, skipping reading...\n");
            continue;
        }

        // Calculate wind speed
        double windSpeed = (double)pulseCount * 0.5;
        if (windSpeed != lastWindSpeed) {
            printf("Wind Speed: %.2f m/s\n", windSpeed);
            lastWindSpeed = windSpeed;
        }

        // Sleep for the interval before the next update
        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
    }

    // Clean up and exit
    pigpioSPIClose(spiHandle);
    pigpioI2CClose(i2cHandle);
    pigpioExit();

    return 0;
}

// Register signal handlers
signal(SIGINT, signalHandler);
signal(SIGTERM, signalHandler);

// Signal handler function
void signalHandler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    pigpioExit();
}

