#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

#define SENSOR_PIN 11
#define LCD_ADDRESS 0x27
#define CALIBRATION_FACTOR 7.5
#define TIME_INTERVAL_S 1
#define MAX_PULSES 1000
#define PULSE_CHECK_INTERVAL_S 0.1

void init_pigpio();
void init_i2c();
void setup_gpio(int pin);
void read_sensor_pulses(int *pulses);
void display_flow_rate(float rate);
void close_resources();

int main(int argc, char *argv[]) {
    int sensor_pin, i2c_fd, pulses[MAX_PULSES];
    float flow_rate = 0.0;
    long start_time = 0;

    init_pigpio();
    init_i2c();
    setup_gpio(SENSOR_PIN);

    while (1) {
        read_sensor_pulses(pulses);
        if (pulses[0] > 0) {
            flow_rate = (float)pulses[0] * CALIBRATION_FACTOR / TIME_INTERVAL_S;
            display_flow_rate(flow_rate);
        }
        usleep(PULSE_CHECK_INTERVAL_S * 1000000);
    }

    close_resources();
    return 0;
}

void init_pigpio() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioErrorText());
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    if (wiringPiI2CSetup(1, 0x27) < 0) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", wiringPiI2CError());
        exit(EXIT_FAILURE);
    }
}

void setup_gpio(int pin) {
    if (gpioSetup(pin, PIGPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n", pin, pigpioErrorText());
        exit(EXIT_FAILURE);
    }
}

void read_sensor_pulses(int *pulses) {
    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Failed to read from GPIO%d: %s\n", SENSOR_PIN, pigpioErrorText());
        exit(EXIT_FAILURE);
    }

    if (pulses[0] == 0) {
        pulses[0] = sensor_value;
    } else {
        pulses[0] += sensor_value;
    }
}

void display_flow_rate(float rate) {
    static char buffer[20];
    sprintf(buffer, "Flow Rate: %.2f L/min", rate);
    wiringPiI2CWrite(LCD_ADDRESS, 0x01, 0, buffer);
    wiringPiI2CWrite(LCD_ADDRESS, 0x02, 0, "\n");
}

void close_resources() {
    close(SENSOR_PIN);
    pigpioTerminate();
    wiringPiI2CClose(1);
}

int main(int argc, char *argv[]) {
    init_pigpio();
    init_i2c();
    setup_gpio(SENSOR_PIN);

    while (1) {
        read_sensor_pulses(pulses);
        if (pulses[0] > 0) {
            flow_rate = (float)pulses[0] * CALIBRATION_FACTOR / TIME_INTERVAL_S;
            display_flow_rate(flow_rate);
        }
        usleep(PULSE_CHECK_INTERVAL_S * 1000000);
    }

    close_resources();
    return 0;
}

