#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define COLUMN_PINS {14, 15, 18, 23, 24, 25, 8, 7}
#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COLUMN_RESISTOR 220
#define COLUMN_ON_TIME 150
#define COLUMN_OFF_TIME 0

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up GPIO lines...\n", signum);
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_disable(gpiod_chip_open(0, 0));
    }
    exit(0);
}

int main() {
    struct gpiod_line *lines[NUM_COLS];
    int ret;

    // Initialize signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    ret = gpiod_chip_open(0, 0);
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO lines
    for (int i = 0; i < NUM_COLS; i++) {
        lines[i] = gpiod_line_open(gpiod_chip_get_line(0, COLUMN_PINS[i]), GPIOD_MODE_OUTPUT);
        if (lines[i] == NULL) {
            perror("Failed to open column line");
            gpiod_chip_close(0, 0);
            exit(EXIT_FAILURE);
        }
    }

    // Initialize GPIO lines for rows
    for (int i = 0; i < NUM_ROWS; i++) {
        lines[NUM_COLS + i] = gpiod_line_open(gpiod_chip_get_line(0, ROW_PINS[i]), GPIOD_MODE_OUTPUT);
        if (lines[NUM_COLS + i] == NULL) {
            perror("Failed to open row line");
            gpiod_chip_close(0, 0);
            exit(EXIT_FAILURE);
        }
    }

    // Main animation loop
    while (1) {
        // Turn off all columns
        for (int i = 0; i < NUM_COLS; i++) {
            gpiod_line_write(lines[i], 1);
        }

        // Turn on each column for COLUMN_ON_TIME
        for (int i = 0; i < NUM_COLS; i++) {
            gpiod_line_write(lines[i], 0);
            usleep(COLUMN_ON_TIME * 1000);
            gpiod_line_write(lines[i], 1);
        }

        // Delay for COLUMN_OFF_TIME
        usleep(COLUMN_OFF_TIME * 1000);
    }

    // Clean up GPIO lines and close GPIO chip
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_disable(lines[i]);
        gpiod_line_close(lines[i]);
    }
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_disable(lines[NUM_COLS + i]);
        gpiod_line_close(lines[NUM_COLS + i]);
    }
    gpiod_chip_close(0, 0);

    return 0;
}

