#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define MLX75031_ADDR 0x4C
#define MLX75031_DISTANCE_REG 0x0D
#define LOG_FILE "depth_log.csv"

void log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    static char header[100];
    if (fp == fopen(LOG_FILE, "r")) {
        fgets(header, 100, fp);
        fclose(fp);
        fprintf(fp, "%s", header);
    }

    fprintf(fp, "%f\n", (double)distance);
    fclose(fp);
}

void handle_signal(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    pigpio_terminate();
    fclose(stdout);
    fclose(stderr);
    exit(0);
}

int main() {
    pigpio_initialize();

    if (signal(SIGINT, handle_signal) == SIG_IGN) {
        fprintf(stderr, "Error setting up signal handler\n");
        pigpio_terminate();
        exit(1);
    }

    int i2c_fd = pigpio_open_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_terminate();
        exit(1);
    }

    if (pigpio_i2c_setup(i2c_fd, 100000) < 0) {
        fprintf(stderr, "Failed to configure I2C bus\n");
        pigpio_close_i2c(i2c_fd);
        pigpio_terminate();
        exit(1);
    }

    if (pigpio_i2c_write_byte(i2c_fd, MLX75031_ADDR) < 0) {
        fprintf(stderr, "Failed to write to I2C address\n");
        pigpio_close_i2c(i2c_fd);
        pigpio_terminate();
        exit(1);
    }

    if (pigpio_i2c_write_mem_block(i2c_fd, MLX75031_DISTANCE_REG, 2, (uint8_t *)&0x0D) < 0) {
        fprintf(stderr, "Failed to read distance register\n");
        pigpio_close_i2c(i2c_fd);
        pigpio_terminate();
        exit(1);
    }

    uint16_t distance;
    if (pigpio_i2c_read_mem_block(i2c_fd, MLX75031_DISTANCE_REG, 2, (uint8_t *)&distance, sizeof(distance)) < 0) {
        fprintf(stderr, "Failed to read distance register\n");
        pigpio_close_i2c(i2c_fd);
        pigpio_terminate();
        exit(1);
    }

    if (distance == 0xFFFF) {
        fprintf(stderr, "Error reading distance register, using default value\n");
        distance = 0xFFFF;
    }

    log_distance(distance);

    pigpio_i2c_close(i2c_fd);
    pigpio_terminate();

    return 0;
}

