#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SILICON_LABS_ID 0x45
#define COMMAND_REGISTER 0x18
#define SAMPLE_INTERVAL 500

void sigint_handler(int sig) {
    close(piGPIO_I2C_HANDLE);
    close(piGPIO_LOG_FILE);
    gpioTerminate();
    fprintf(stderr, "SIGINT received, exiting.\n");
    exit(EXIT_SUCCESS);
}

int main() {
    int piGPIO_LOG_FILE = open("biometric_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (piGPIO_LOG_FILE == -1) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    piGPIO_I2C_HANDLE = piGPIO_openI2C(I2C_BUS);
    if (piGPIO_I2C_HANDLE == -1) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    if (read(piGPIO_I2C_HANDLE, &SILICON_LABS_ID, 1) != 1 || SILICON_LABS_ID != SILICON_LABS_ID) {
        fprintf(stderr, "Sensor not present or PART ID mismatch\n");
        piGPIO_closeI2C(piGPIO_I2C_HANDLE);
        return EXIT_FAILURE;
    }

    if (write(piGPIO_I2C_HANDLE, &COMMAND_REGISTER, 1) != 1) {
        fprintf(stderr, "Failed to write command register\n");
        piGPIO_closeI2C(piGPIO_I2C_HANDLE);
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    while (1) {
        int data[2];
        ssize_t read_bytes = read(piGPIO_I2C_HANDLE, data, 2);
        if (read_bytes != 2) {
            fprintf(stderr, "Failed to read from sensor\n");
            usleep(SAMPLE_INTERVAL * 1000);
            continue;
        }

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&ts.tv_sec));
        fprintf(piGPIO_LOG_FILE, "%s\tProximity: %d\tAmbient Light: %d\n", timestamp, data[0], data[1]);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    piGPIO_closeI2C(piGPIO_I2C_HANDLE);
    close(piGPIO_LOG_FILE);
    return 0;
}

