            sprintf(event_str, "2024-01-15T12:34:56Z Object detected");
            log_event(event_str);
            blink_led();
        }

        // Poll for 100 ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up resources
    if (gpiod_gpio_delete(chip, SENSOR_PIN) == -1) {
        fprintf(stderr, "Failed to delete GPIO line %d\n", SENSOR_PIN);
    }
    if (gpiod_gpio_delete(chip, LED_PIN) == -1) {
        fprintf(stderr, "Failed to delete GPIO line %d\n", LED_PIN);
