    if (i2cRead(piGPIO_I2C_HANDLE, ALS_VIS_DATA_REG, 1, &als_vis_data) < 0) {
        perror("i2cRead");
        return EXIT_FAILURE;
    }

    // Log data to CSV file
    time(NULL) & tv;
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(&tv.tv_sec));
    FILE *log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }
    fprintf(log_file, "%s,%d,%d\n", timestamp, ps1_data, als_vis_data);
    fclose(log_file);

    // Flush the log file after every write
    fflush(log_file);

    // SIGINT handler
    signal(SIGINT, sigint_handler);

    // Infinite loop
    while (1) {
        usleep(1000000); // Sleep for 1 second
    }

    // Clean shutdown
    gpioTerminate();
    close(piGPIO_I2C_HANDLE);
    close(piGPIO_LOG_FILE);
    return EXIT_SUCCESS;
}

