#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define VOLTAGE_DIV 1000 // 1kOhm / 2kOhm

#define LOG_FILE "distance_log.txt"
#define LOG_INTERVAL 60 // seconds
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S"
#define REMINDER_DISTANCE 15

void log_entry(const char *entry) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s", entry);
    fclose(file);
}

void handle_signal(int signum) {
    log_entry("Received signal, shutting down...");
    fclose(NULL); // Ensure all files are closed
    exit(signum == SIGINT || signum == SIGTERM ? 0 : EXIT_FAILURE);
}

void setup_gpio(void) {
    int ret;

    ret = gpiod_resource_init();
    if (ret < 0) {
        perror("Failed to initialize gpiod resources");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_resource_create_phys_gpio(TRIGGER_GPIO, GPIOD_MODE_OUTPUT);
    if (ret < 0) {
        perror("Failed to create GPIO output resource");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_resource_create_phys_gpio(ECHO_GPIO, GPIOD_MODE_INPUT);
    if (ret < 0) {
        perror("Failed to create GPIO input resource");
        exit(EXIT_FAILURE);
    }
}

void measure_distance(void) {
    int ret;
    struct timespec start, end;
    double elapsed;
    int echo_rise_time;

    ret = gpiod_edge_event_init(ECHO_GPIO, GPIOD_INPUT, GPIOD_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to initialize edge event for ECHO GPIO");
        return;
    }

    ret = gpiod_edge_event_get_timeout(ECHO_GPIO, GPIOD_INPUT, GPIOD_ACTIVE_HIGH, 30 * 1000 * 1000); // 30 ms timeout
    if (ret < 0) {
        perror("Failed to set timeout for edge event");
        return;
    }

    ret = gpiod_edge_event_get_status(ECHO_GPIO, GPIOD_INPUT, GPIOD_ACTIVE_HIGH, &echo_rise_time);
    if (ret < 0) {
        perror("Failed to get edge event status");
        return;
    }

    if (echo_rise_time == 0) {
        log_entry("Sensor absent");
        return;
    }

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    elapsed = (now.tv_sec - start.tv_sec) * 1000000000 + (now.tv_nsec - start.tv_nsec);

    double pulse_width = (echo_rise_time * 1000000) / 2; // Convert to microseconds
    double distance = (pulse_width * 34300) / 2; // Convert to cm

    if (distance < REMINDER_DISTANCE || distance > 400) {
        log_entry("Invalid distance reading: %f cm", distance);
        return;
    }

    if (distance < REMINDER_DISTANCE) {
        log_entry("Time to water the plant! %f cm", distance);
    }

    log_entry("Distance: %f cm, Timestamp: %s", distance, strftime(LOG_FORMAT, 0, "%Y-%m-%dT%H:%M:%S", localtime(&now.tv_sec)));
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (1) {
        measure_distance();
        usleep(LOG_INTERVAL * 1000000); // Sleep for LOG_INTERVAL seconds
    }

    return 0;
}

