#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define LOG_FILE "color_proximity_log.csv"
#define PROXIMITY_THRESHOLD 200
#define REG_ID_RGB_START 0x96
#define REG_ID_RGB_END 0x9B
#define REG_ID_PROXIMITY 0x9C

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_client *client;
    FILE *log_file;
    time_t now;
    char timestamp[32];

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY | O_NDELAY);
    if (i2c_fd == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(i2c_fd, I2C_BUS);
    if (!client) {
        perror("i2c_client_new");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ret = pigpio_init(1);
    if (ret != 0) {
        fprintf(stderr, "pigpio_init failed: %s\n", pigpio_strerror(ret));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor configuration
    ret = pigpio_write_i2c_reg(client, I2C_ADDR, 0x92, 0xAB);
    if (ret != 0) {
        fprintf(stderr, "Failed to set sensor ID register\n");
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    ret = pigpio_write_i2c_reg(client, I2C_ADDR, 0x80, 0x03);
    if (ret != 0) {
        fprintf(stderr, "Failed to set ENABLE register\n");
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    ret = pigpio_write_i2c_reg(client, I2C_ADDR, 0x81, 0xDB);
    if (ret != 0) {
        fprintf(stderr, "Failed to set ATIME register\n");
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    ret = pigpio_write_i2c_reg(client, I2C_ADDR, 0x83, 0xF6);
    if (ret != 0) {
        fprintf(stderr, "Failed to set WTIME register\n");
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    ret = pigpio_write_i2c_reg(client, I2C_ADDR, 0x8E, 0x87);
    if (ret != 0) {
        fprintf(stderr, "Failed to set PPULSE register\n");
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    ret = pigpio_write_i2c_reg(client, I2C_ADDR, 0xF1, 0x03);
    if (ret != 0) {
        fprintf(stderr, "Failed to set CONTROL register\n");
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    ret = pigpio_write_i2c_reg(client, I2C_ADDR, 0x90, 0x01);
    if (ret != 0) {
        fprintf(stderr, "Failed to set CONFIG2 register\n");
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    // Start reading data
    while (1) {
        now = time(NULL);
        sprintf(timestamp, "%llu", now);
        fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp,
                pigpio_read_i2c_byte(client, I2C_ADDR, REG_ID_RGB_START),
                pigpio_read_i2c_byte(client, I2C_ADDR, REG_ID_RGB_END),
                pigpio_read_i2c_byte(client, I2C_ADDR, REG_ID_PROXIMITY),
                pigpio_read_i2c_byte(client, I2C_ADDR, REG_ID_PROXIMITY + 1));

        if (pigpio_read_i2c_byte(client, I2C_ADDR, REG_ID_PROXIMITY) > PROXIMITY_THRESHOLD) {
            fprintf(log_file, "%s,1,0,0,0\n", timestamp);
        }

        usleep(100000);
    }

    close(log_file);
    pigpio_terminate();
    close(i2c_fd);
    return 0;
}

