                pigpio_read_i2c_byte(client, I2C_ADDR, REG_ID_PROXIMITY),
                pigpio_read_i2c_byte(client, I2C_ADDR, REG_ID_PROXIMITY + 1));

        if (pigpio_read_i2c_byte(client, I2C_ADDR, REG_ID_PROXIMITY) > PROXIMITY_THRESHOLD) {
            fprintf(log_file, "%s,1,0,0,0\n", timestamp);
        }

        usleep(100000);
    }

    close(log_file);
    pigpio_terminate();
    close(i2c_fd);
    return 0;
}
