#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_MS 100

void log_distance(const char *timestamp, int distance_mm) {
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s,%d\n", time_str, distance_mm);
        fclose(file);
    }
}

void signal_handler(int signum) {
    printf("Received SIGINT, shutting down...\n");
    pigpio_terminate();
    fclose(stdout);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    int i2c_fd;
    int result;

    if (!(i2c_fd = pigpio_open(I2C_BUS, VL53L0X_ADDR))) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_strerror(result));
        return 1;
    }

    if (pigpio_write_byte_range(i2c_fd, VL53L0X_ADDR, 0x00, 0x01) != 2) {
        fprintf(stderr, "Failed to write SYSRANGE_START: %s\n", pigpio_strerror(result));
        pigpio_close(i2c_fd);
        return 1;
    }

    if (pigpio_write_byte(i2c_fd, VL53L0X_ADDR, 0x13) != 1) {
        fprintf(stderr, "Failed to set RESULT_INTERRUPT_STATUS bit 0: %s\n", pigpio_strerror(result));
        pigpio_close(i2c_fd);
        return 1;
    }

    static unsigned long start_time = 0;
    unsigned long elapsed_time = 0;

    while (elapsed_time < TIMEOUT_MS) {
        if (pigpio_read_byte_range(i2c_fd, VL53L0X_ADDR, 0x13, 1, &result) != 1) {
            fprintf(stderr, "Failed to read RESULT_INTERRUPT_STATUS: %s\n", pigpio_strerror(result));
            break;
        }

        if (result & 0x01) {
            break;
        }

        elapsed_time++;
    }

    if (elapsed_time >= TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for RESULT_INTERRUPT_STATUS bit 0 to set.\n");
        pigpio_close(i2c_fd);
        return 1;
    }

    if (pigpio_read_byte_range(i2c_fd, VL53L0X_ADDR, 0x14, 14, &result) != 14) {
        fprintf(stderr, "Failed to read RESULT_RANGE_STATUS: %s\n", pigpio_strerror(result));
        pigpio_close(i2c_fd);
        return 1;
    }

    int16_t distance = (result[10] << 8) | result[11];
    if (pigpio_write_byte(i2c_fd, VL53L0X_ADDR, 0x0B) != 1) {
        fprintf(stderr, "Failed to clear SYSTEM_INTERRUPT_CLEAR: %s\n", pigpio_strerror(result));
        pigpio_close(i2c_fd);
        return 1;
    }

    log_distance(ctime(NULL), distance);

    pigpio_close(i2c_fd);
    return 0;
}

