#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ULTRASONIC_ADDR 0x45
#define SAMPLE_INTERVAL 200
#define LOG_FILE "distance_log.txt"
#define BUFFER_SIZE 20

void handle_interrupt(int sig) {
    printf("\nStopping distance measurement...\n");
    pigpio_stop();
    close(pigpio_get_i2c_handle());
    close(fildes);
    exit(0);
}

int main() {
    int i2c_fd, pigpio_fd;
    struct timeval tv;
    char buffer[BUFFER_SIZE];

    signal(SIGINT, handle_interrupt);

    pigpio_init(I2C_BUS);
    if (pigpio_open_i2c(pigpio_get_i2c_handle()) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (pigpio_write_byte(pigpio_get_i2c_handle(), 0x01) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }

    while (1) {
        gettimeofday(&tv, NULL);
        strftime(buffer, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        fprintf(fildes, "%s, ", buffer);
        fflush(fildes);

        if (pigpio_write_byte(pigpio_get_i2c_handle(), 0x02) < 0) {
            perror("Failed to write to I2C device");
            continue;
        }

        usleep(SAMPLE_INTERVAL * 1000 / 1000); // Convert ms to microseconds

        if (pigpio_read_byte(pigpio_get_i2c_handle(), &distance) < 0) {
            perror("Failed to read from I2C device");
            continue;
        }

        fprintf(fildes, "%d\n", distance);
        fflush(fildes);

        if (pigpio_write_byte(pigpio_get_i2c_handle(), 0x00) < 0) {
            perror("Failed to write to I2C device");
            continue;
        }
    }

    pigpio_close(pigpio_get_i2c_handle());
    close(fildes);
    return 0;
}

