#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_GPIO_17 17
#define SENSOR_GPIO_18 18
#define POLL_INTERVAL 100
#define LOG_FILE "obstacle_log.txt"

void log_reading(int sensor_reading) {
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }
    fprintf(log_file, "%s: %d\n", timestamp, sensor_reading);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    pigpio_init(5); // Initialize pigpio with 5 seconds timeout

    if (pigpio_init(5) != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int gpio_17 = SENSOR_GPIO_17, gpio_18 = SENSOR_GPIO_18;
    if (gpio_setmode(gpio_17, PI_OUTPUT) != 0 ||
        gpio_setmode(gpio_18, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", gpio_17);
        return EXIT_FAILURE;
    }

    if (gpio_write(gpio_17, 0) != 0 ||
        gpio_write(gpio_18, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", gpio_17);
        return EXIT_FAILURE;
    }

    while (1) {
        int sensor1_reading = gpio_read(gpio_17);
        int sensor2_reading = gpio_read(gpio_18);

        log_reading(sensor1_reading);
        log_reading(sensor2_reading);

        usleep(POLL_INTERVAL * 1000 / 1000); // Sleep for 100ms
    }

    pigpio_terminate(1000); // Terminate pigpio with 1 second timeout

    pigpio_cleanup(); // Clean up pigpio resources

    fprintf(stderr, "Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

