int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd;
    struct i2c_client *client;
    int sensor_present = 0;
    int led_state = 0;

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    client = i2c_client_new(i2c_fd, I2C_BUS);
    if (!client) {
        perror("Failed to create I2C client");
        close(i2c_fd);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    // Check if sensor is present
    sensor_present = i2c_mem_read_byte_data(client, I2C_ADDR, 0x00);
    if (sensor_present == 0xFF) {
        printf("Sensor not found\n");
        close(i2c_fd);
        i2c_client_free(client);
        piGPIO_shutdown();
        return EXIT_SUCCESS;
    }

    // Set up GPIO
    gpio_fd = open("/dev/gpio*, O_RDWR | O_NOCTTY | O_NDELAY;
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        close(i2c_fd);
        i2c_client_free(client);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        close(gpio_fd);
        i2c_client_free(client);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    piGPIO_set_mode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (1) {
        // Read distance
        int distance;
        if (i2c_mem_read_byte_data(client, I2C_ADDR, 0x00) == 0x00) {
            distance = i2c_mem_read_byte_data(client, I2C_ADDR, 0x01);
            if (distance == 0xFF) {
                printf("Sensor error\n");
                break;
            }
        } else {
            printf("Sensor error reading distance\n");
            break;
        }

        // Log distance with timestamp
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
        log_timestamp(timestamp);

        // Check if distance is below 20 cm
        if (distance < 20) {
            led_state = 1;
        } else {
            led_state = 0;
        }

        // Turn on LED if distance is below 20 cm
        if (led_state) {
            piGPIO_write(LED_PIN, 1);
        } else {
            piGPIO_write(LED_PIN, 0);
        }

        // Wait for next interval
        usleep(LOG_INTERVAL * 1000 / 1000);
    }

    // Clean up
    piGPIO_shutdown();
    close(gpio_fd);
    i2c_client_free(client);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

