#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define SIL1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_LIGHT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3

void log_reading(const char *timestamp, uint16_t proximity, uint16_t ambient_light) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s, Proximity: %04X, Ambient Light: %04X\n",
            timestamp, proximity, ambient_light);
    fclose(file);
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    int ret;
    uint16_t proximity, ambient_light;

    pigpio_init(1); // Initialize pigpio with I2C bus 1

    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd == -1) {
        perror("Failed to open log file");
        pigpio_terminate(1);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = pigpio_begin_i2c(i2c_fd, SIL1182_ADDR);
        if (ret < 0) {
            fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_strerror(ret));
            continue;
        }

        for (int retry = 0; retry < RETRY_COUNT; retry++) {
            ret = pigpio_i2c_write_byte(i2c_fd, SIL1182_ADDR, PROXIMITY_REG);
            if (ret < 0) {
                fprintf(stderr, "Failed to write to proximity register: %s\n", pigpio_strerror(ret));
                continue;
            }

            ret = pigpio_i2c_read_byte(i2c_fd, SIL1182_ADDR, PROXIMITY_REG);
            if (ret < 0) {
                fprintf(stderr, "Failed to read from proximity register: %s\n", pigpio_strerror(ret));
                continue;
            }

            proximity = ret;
            break;
        }

        if (ret < 0) {
            fprintf(stderr, "Failed to read proximity data after retries\n");
            continue;
        }

        ret = pigpio_i2c_write_byte(i2c_fd, SIL1182_ADDR, AMBIENT_LIGHT_REG);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to ambient light register: %s\n", pigpio_strerror(ret));
            continue;
        }

        for (int retry = 0; retry < RETRY_COUNT; retry++) {
            ret = pigpio_i2c_read_byte(i2c_fd, SIL1182_ADDR, AMBIENT_LIGHT_REG);
            if (ret < 0) {
                fprintf(stderr, "Failed to read from ambient light register: %s\n", pigpio_strerror(ret));
                continue;
            }

            ambient_light = ret;
            break;
        }

        if (ret < 0) {
            fprintf(stderr, "Failed to read ambient light data after retries\n");
            continue;
        }

        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        log_reading(timestamp, proximity, ambient_light);

        usleep(500000); // Wait for 500 ms
    }

    pigpio_terminate(1); // Terminate pigpio
    close(i2c_fd); // Close the log file
    printf("Program terminated.\n");
    exit(EXIT_SUCCESS);
}

