#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 100

void log_tof_reading(const char *timestamp, int distance);
void handle_sensor_absent(const char *msg);
void handle_bus_error(const char *msg);
void setup_gpio(void);
void read_sensor_who_am_i(void);
void read_distance(int *distance);
void write_to_i2c(unsigned char *buffer, int length);

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd, gpio_number;
    int distance;
    char timestamp[32];

    setup_gpio();

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }
    DISTANCE_THRESHOLD = atoi(argv[1]);

    read_sensor_who_am_i();

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd == -1) {
        perror("open /dev/gpiochip0");
        close(i2c_fd);
        return 1;
    }

    gpio_number = fileno(gpio_fd);
    gpioConfig(gpio_number, GPIO_OUTPUT);
    gpioWrite(gpio_number, 1); // Turn on LED

    while (1) {
        read_distance(&distance);

        if (distance < DISTANCE_THRESHOLD) {
            log_tof_reading(timestamp, distance);
            gpioWrite(gpio_number, 0); // Turn off LED
        }

        sprintf(timestamp, "%s", ctime(NULL));
        log_tof_reading(timestamp, distance);

        usleep(50000);
    }

    close(i2c_fd);
    close(gpio_fd);
    pigpio_terminate(NULL);

    return 0;
}

void log_tof_reading(const char *timestamp, int distance) {
    FILE *file = fopen("tof_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Failed to open tof_log.txt for appending.\n");
        return;
    }
    fprintf(file, "%s: %d\n", timestamp, distance);
    fclose(file);
}

void handle_sensor_absent(const char *msg) {
    fprintf(stderr, "Error: Sensor not found. %s\n", msg);
    pigpio_terminate(NULL);
}

void handle_bus_error(const char *msg) {
    fprintf(stderr, "Error: Bus error detected. %s\n", msg);
    pigpio_terminate(NULL);
}

void setup_gpio(void) {
    gpio_set_mode(GPIO_OUTPUT, GPIO_NUM(LED_GPIO));
}

void read_sensor_who_am_i(void) {
    unsigned char who_am_i[2];
    write_to_i2c(who_am_i, 2);

    if (read_i2c(i2c_fd, who_am_i, 2) == -1) {
        handle_bus_error("Failed to read WHO_AM_I register");
    }

    if (who_am_i[0] != 0x6A || who_am_i[1] != 0x20) {
        handle_sensor_absent("Sensor not found or WHO_AM_I mismatch");
    }
}

void read_distance(int *distance) {
    unsigned char buffer[2];
    *distance = 0;

    write_to_i2c(buffer, 2);

    if (read_i2c(i2c_fd, buffer, 2) == -1) {
        handle_bus_error("Failed to read distance register");
        return;
    }

    *distance = buffer[0] << 8 | buffer[1];
}

void write_to_i2c(unsigned char *buffer, int length) {
    if (write(i2c_fd, buffer, length) == -1) {
        perror("write to i2c");
    }
}

int read_i2c(int fd, unsigned char *buffer, int length) {
    if (read(fd, buffer, length) == -1) {
        perror("read from i2c");
        return -1;
    }
    return 0;
}

