    if (read_i2c(i2c_fd, buffer, 2) == -1) {
        handle_bus_error("Failed to read distance register");
        return;
    }

    *distance = buffer[0] << 8 | buffer[1];
}

void write_to_i2c(unsigned char *buffer, int length) {
    if (write(i2c_fd, buffer, length) == -1) {
        perror("write to i2c");
    }
}

