#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x50
#define COMMAND_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESPONSE_HEADER_CHECK 0x50
#define SAMPLE_RATE 10
#define LOG_FILE "intrusion_log.txt"
#define DELAY_MS 100

int i2c_fd;

void log_event(const char *timestamp, uint16_t avg_distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s: Average distance: %d mm\n", ctime(&now), avg_distance);
    fclose(log_file);
}

int main() {
    int result;
    struct i2c_client *client;

    i2c_fd = open(I2C_BUS, O_RDWR | O_SYNC);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc_client(i2c_fd, I2C_ADDR);
    if (!client) {
        perror("Failed to allocate I2C client");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    result = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (result < 0) {
        perror("Failed to set I2C slave address");
        i2c_free_client(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    result = ioctl(i2c_fd, I2C_SMBUS_WRITE, &COMMAND_FRAME);
    if (result < 0) {
        perror("Failed to write command frame");
        i2c_free_client(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    usleep(100000); // Wait for at least 10 ms

    result = ioctl(i2c_fd, I2C_SMBUS_READ, &client->regs[0]);
    if (result < 0) {
        perror("Failed to read response");
        i2c_free_client(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (client->regs[0] != RESPONSE_HEADER_CHECK) {
        fprintf(stderr, "Invalid response header\n");
        i2c_free_client(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint16_t distance = (client->regs[11] << 8) | client->regs[12];
    int avg_distance = distance;

    for (int i = 0; i < SAMPLE_RATE - 1; i++) {
        // Perform another measurement and update avg_distance
        result = ioctl(i2c_fd, I2C_SMBUS_WRITE, &COMMAND_FRAME);
        if (result < 0) {
            perror("Failed to write command frame");
            i2c_free_client(client);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
        usleep(DELAY_MS * 1000); // 100 ms delay
        result = ioctl(i2c_fd, I2C_SMBUS_READ, &client->regs[0]);
        if (result < 0) {
            perror("Failed to read response");
            i2c_free_client(client);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
        if (client->regs[0] != RESPONSE_HEADER_CHECK) {
            fprintf(stderr, "Invalid response header\n");
            i2c_free_client(client);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
        distance = (client->regs[11] << 8) | client->regs[12];
        avg_distance += distance;
    }
    avg_distance /= SAMPLE_RATE;

    if (avg_distance < 1000) {
        log_event(ctime(NULL), avg_distance);
    }

    i2c_free_client(client);
    close(i2c_fd);

    return 0;
}

