#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define MODEL_ID 0xC0

void signal_handler(int signum) {
    pigpio_terminate(NULL);
    printf("Received signal %d, exiting gracefully.\n", signum);
    exit(0);
}

int main() {
    pigpio_t *pi;
    int i2c_fd;
    char buffer[6];

    pi = pigpio_init(I2C_BUS);
    if (pi == NULL) {
        fprintf(stderr, "pigpio_init() failed: %s\n", strerror(errno));
        exit(1);
    }

    i2c_fd = open_i2c(I2C_BUS, VL53L0X_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open_i2c() failed: %s\n", strerror(errno));
        pigpio_terminate(pi);
        exit(1);
    }

    if (read_register(i2c_fd, SYSRANGE_START) != 0xEE) {
        fprintf(stderr, "Failed to read model ID, exiting.\n");
        pigpio_terminate(pi);
        close(i2c_fd);
        exit(1);
    }

    while (1) {
        write_register(i2c_fd, SYSRANGE_START, 0x01);
        int timeout = 100000; // 100 ms
        int start_time = millis();

        while ((read_register(i2c_fd, RESULT_INTERRUPT_STATUS) & (1 << 0)) == 0) {
            if (millis() - start_time > timeout) {
                fprintf(stderr, "Timeout reading interrupt status.\n");
                break;
            }
            usleep(10000); // Sleep for 10 ms
        }

        if (read_register(i2c_fd, RESULT_RANGE_STATUS) == 0xFFFF) {
            fprintf(stderr, "Failed to read distance, exiting.\n");
            break;
        }

        int distance = (read_register(i2c_fd, RESULT_RANGE_STATUS) << 8) | read_register(i2c_fd, RESULT_RANGE_STATUS + 1);
        printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %d mm\n",
                (int)(distance / 1000000) % 100,
                (int)(distance / 100000) % 100,
                (int)(distance / 1000) % 100,
                (int)distance % 100,
                (int)(millis() / 1000) % 60,
                (int)(millis() % 1000) % 60);

        usleep(500000); // Sleep for 500 ms
    }

    close(i2c_fd);
    pigpio_terminate(pi);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

int open_i2c(int bus, int addr) {
    int fd;
    fd = open("/dev/i2c-" bus, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        return -1;
    }

    struct i2c_rdwr_t wr;
    wr.addr = addr;
    wr.data = (void *)0x00;
    wr.len = 1;
    if (ioctl(fd, I2C_RDWR, &wr) < 0) {
        close(fd);
        return -1;
    }

    return fd;
}

int write_register(int fd, uint16_t reg, uint8_t value) {
    struct i2c_rdwr_t wr;
    wr.addr = 0x29;
    wr.data = &reg, wr.len = 2;
    wr.len += value.length();
    memcpy(wr.data + wr.len - value.length(), &value, value.length());
    return ioctl(fd, I2C_WR_REG, &wr);
}

int read_register(int fd, uint16_t reg) {
    struct i2c_rdwr_t rd;
    rd.addr = 0x29;
    rd.data = &reg, rd.len = 2;
    return ioctl(fd, I2C_RD_REG, &rd);
}

