#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define CONFIG_REG 0x18
#define IRQ_STATUS_REG 0x25
#define PROXIMITY_DATA_L 0x2A
#define PROXIMITY_DATA_H 0x2B

void handle_sensor_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    gpioTerminate();
    exit(EXIT_FAILURE);
}

int main() {
    int i2c_fd, ret;
    struct i2c_client *client;
    long proximity_data;

    // Initialize pigpio
    if (piGPIOInit() < 0) {
        handle_sensor_error("Failed to initialize pigpio");
    }

    // Open I2C bus
    i2c_fd = i2cOpenChannel(I2C_BUS);
    if (i2c_fd < 0) {
        handle_sensor_error("Failed to open I2C bus");
    }

    // Initialize client
    client = i2cClientNew(i2c_fd, I2C_ADDR);
    if (!client) {
        handle_sensor_error("Failed to create I2C client");
    }

    // Write to CONFIG register to enable proximity mode
    ret = i2cWriteByte(client, I2C_ADDR, CONFIG_REG) == 0x01;
    if (ret != 0x01) {
        handle_sensor_error("Failed to write to CONFIG register");
    }

    // Set up SIGINT handler for graceful cleanup
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Poll for data-ready
        ret = i2cReadByte(client, I2C_ADDR, IRQ_STATUS_REG);
        if (ret & 0x01) { // Check if bit 0 is set (data-ready)
            ret = i2cReadByte(client, I2C_ADDR, PROXIMITY_DATA_L);
            proximity_data = ret << 8;
            proximity_data |= i2cReadByte(client, I2C_ADDR, PROXIMITY_DATA_H);

            // Print proximity data
            printf("Proximity: %lx\n", proximity_data);
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close I2C resources and terminate pigpio
    i2cClientFree(client);
    i2cClose(i2c_fd);
    piGPIOTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Cleanly close I2C handle and terminate pigpio
    i2cClientFree(client);
    i2cClose(i2c_fd);
    piGPIOTerminate();
    exit(0);
}

