#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/time.h>

#define I2C_BUS 1
#define I2C_SLAVE 0x4C
#define REG_DISTANCE 0x00
#define DISTANCE_FACTOR 0.125

int main() {
    int file;
    struct i2c_client *client;
    u8 distance[2];
    int ret;

    // Initialize I2C bus
    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        exit(1);
    }

    // Set I2C client structure
    client = i2c_alloc(file);
    if (!client) {
        perror("i2c_alloc");
        close(file);
        exit(1);
    }

    // Set slave address via ioctl
    if (ioctl(file, I2C_SLAVE, I2C_SLAVE) == -1) {
        perror("ioctl I2C_SLAVE");
        i2c_free(client);
        close(file);
        exit(1);
    }

    // Verify device response
    ret = read(client->handle, distance, sizeof(distance));
    if (ret < 0) {
        perror("read from I2C");
        i2c_free(client);
        close(file);
        exit(1);
    }

