#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3101_ADDR 0x44
#define LOG_INTERVAL 500

void handle_sigint(int sig) {
    printf("\nProgram received SIGINT, exiting gracefully...\n");
    pigpio_stop();
    exit(0);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(I2C_BUS);
    if (pi < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    if (pi_init(pi, I2C_BUS) < 0) {
        perror("Failed to initialize I2C bus");
        pigpio_stop(pi);
        return 1;
    }

    if (opt3101_init(pi, OPT3101_ADDR) < 0) {
        perror("Failed to initialize OPT3101 sensor");
        pigpio_stop(pi);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        opt3101_read_channel(pi, OPT3101_ADDR, 0, &distance, &ambient_light, &error_flag);

        if (error_flag & OPT3101_ERROR_NONE) {
            printf("Distance: %.2f cm\n", distance);
            printf("Ambient Light: %d\n", ambient_light);
        } else {
            printf("Error: %d\n", error_flag);
        }

        usleep(LOG_INTERVAL * 1000);
    }

    pigpio_stop(pi);
    return 0;
}

int opt3101_init(pigpio *pi, int addr) {
    int result = pi_set_mode(pi, I2C_BUS, addr, PI_OUTPUT);
    if (result < 0) {
        perror("Failed to set I2C address mode");
        return result;
    }

    result = pi_write_byte(pi, I2C_BUS, addr, 0x00); // Command to start measurement
    if (result < 0) {
        perror("Failed to write command byte");
        return result;
    }

    return 0;
}

int opt3101_read_channel(pigpio *pi, int addr, int channel, double *distance, int *ambient_light, int *error_flag) {
    int result = pi_read_i2c_byte(pi, I2C_BUS, addr, channel);
    if (result < 0) {
        perror("Failed to read I2C data");
        *error_flag = OPT3101_ERROR_BUS_ERROR;
        return -1;
    }

    // Convert I2C byte to distance (requires specific conversion factor from OPT3101 datasheet)
    *distance = (double)result / 100.0; // Assuming conversion factor of 100

    result = pi_read_i2c_byte(pi, I2C_BUS, addr, channel + 1);
    if (result < 0) {
        perror("Failed to read ambient light data");
        *error_flag = OPT3101_ERROR_BUS_ERROR;
        return -1;
    }

    *ambient_light = (int)result;

    return 0;
}

