#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_INTERVAL 1000 // 1 second
#define MAX_TIMEOUT 200

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signum) {
    printf("Exiting...\n");
    gpioTerminate();
    exit(0);
}

// Initialize pigpio
int init_pigpio() {
    if (pigpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return -1;
    }
    return 0;
}

// Function to read distance using HC-SR04
double read_distance() {
    uint32_t trigger, echo;
    int timeout = MAX_TIMEOUT;

    // Send a 10 microsecond pulse
    trigger = 1;
    gpioOutput(TRIGGER_PIN, 1);
    usleep(10000);
    gpioOutput(TRIGGER_PIN, 0);

    // Measure echo pulse
    echo = gpioRead(ECHO_PIN);

    // Check for echo timeout
    while (timeout > 0 && echo == 0) {
        echo = gpioRead(ECHO_PIN);
        timeout--;
        usleep(10000);
    }

    // Ensure valid pulse duration
    if (echo == 0 || echo > 38 || echo <= 0) {
        printf("Invalid pulse duration, skipping reading.\n");
        return -1;
    }

    // Calculate distance in cm
    double distance = (echo * 0.0343) / 2;
    return distance;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_pigpio() < 0) {
        return -1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double last_timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    while (1) {
        double distance = read_distance();
        if (distance < 0) {
            break;
        }

        // Log the reading with a timestamp
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        long long current_micros = (now.tv_sec * 1000000000) + now.tv_nsec / 1000;
        printf("Distance: %.2f cm, Timestamp: %lld us\n", distance, current_micros);

        // Wait for the next reading
        usleep(LOG_INTERVAL * 1000000);
    }

    gpioTerminate();
    return 0;
}

