#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>

#define SERIAL_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0
#define LOG_FILE "intrusion_log.csv"

void log_intrusion(const char *timestamp, double distance) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s,%f\n", time_str, distance);
        fclose(log_file);
    }
}

void alert_intrusion(double distance) {
    syslog(LOG_ALERT, "Intrusion detected at %f meters!", distance);
    // Here you would typically activate an LED or perform other actions
    // For this example, we'll just log the alert.
}

int main(int argc, char *argv[]) {
    int uart_fd, ret;
    termios options;
    pigpio pi;

    // Initialize pigpio
    if (pi_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    // Open UART
    uart_fd = open(SERIAL_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        syslog(LOG_ERR, "Failed to open UART");
        pi_shutdown();
        return 1;
    }

    // Set up UART
    tcflush(uart_fd, TCIFLUSH);
    tcgetattr(uart_fd, &options);
    options.c_cflag &= ~(CSIZE | CS8);
    options.c_cflag = B9600 | CS8;
    options.c_lflag &= ~(ICANON | ECHO);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    tcsetattr(uart_fd, TCSANOW, &options);

    // Initialize GPIO for LED
    if (pi_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        close(uart_fd);
        return 1;
    }
    pi_set_mode(GPIO_LED, PI_OUTPUT);

    // Read data from the sensor
    char magic_word[8] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    unsigned char data_header[8];
    unsigned char range_data[128 / 2];
    int data_len = 0;

    while (1) {
        ret = read(uart_fd, data_header, 8);
        if (ret != 8) {
            syslog(LOG_ERR, "Failed to read magic word");
            break;
        }

        if (data_header[0] != 0x02 || data_header[1] != 0x01 ||
            data_header[2] != 0x04 || data_header[3] != 0x03 ||
            data_header[4] != 0x06 || data_header[5] != 0x05 ||
            data_header[6] != 0x08 || data_header[7] != 0x07) {
            syslog(LOG_ERR, "Invalid magic word");
            break;
        }

        ret = read(uart_fd, range_data, 128);
        if (ret != 128) {
            syslog(LOG_ERR, "Failed to read range data");
            break;
        }

        // Process range data
        for (int i = 0; i < 64; i++) {
            double range = (double)range_data[i] << 16 / 256 + (double)range_data[i + 64];
            if (range < INTRUSION_THRESHOLD) {
                alert_intrusion(range);
                log_intrusion(time(NULL) == 0 ? "" : strftime("%Y-%m-%d %H:%M:%S", NULL), range);
            }
        }
    }

    // Clean up
    pi_shutdown();
    close(uart_fd);

    return 0;
}

