#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x69
#define LOG_FILE "distance_log.txt"
#define GPIO_ALERT 17
#define SAMPLE_INTERVAL_MS 100
#define MIN_DISTANCE 10.0

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up and exiting.\n");
    pigpio_stop();
    close(GPIO_ALERT);
    close(i2c_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(I2C_BUS);
    if (pigpio_init(I2C_BUS) == -1) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    int i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd == -1) {
        perror("Failed to open log file");
        pigpio_stop();
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
    char ts_str[32];
    sprintf(ts_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timestamp / 3600, timestamp % 3600 / 60, timestamp % 60,
            timestamp % 60, 0, 0);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        int read_result = pigpio_i2c_write_byte(pi, SENSOR_ADDRESS, 0x31);
        if (read_result == -1) {
            perror("Failed to write to sensor register 0x31");
            continue;
        }

        read_result = pigpio_i2c_read_byte(pi, SENSOR_ADDRESS, 0x32);
        if (read_result == -1) {
            perror("Failed to read from sensor register 0x32");
            continue;
        }

        uint16_t distance = (uint16_t)(read_result << 8) | pigpio_i2c_read_byte(pi, SENSOR_ADDRESS, 0x31);

        if (distance < MIN_DISTANCE) {
            printf("Alert: Distance below threshold\n");
            pigpio_set_mode(GPIO_ALERT, PIGIO_OUTPUT);
            pigpio_write(GPIO_ALERT, 1);
            usleep(100000); // Short pulse for alert
            pigpio_set_mode(GPIO_ALERT, PIGIO_INPUT);
        }

        char log_entry[64];
        sprintf(log_entry, "Time: %s, Distance: %.2f m\n", ts_str, (float)distance / 100.0);
        if (write(i2c_fd, log_entry, strlen(log_entry)) == -1) {
            perror("Failed to write to log file");
            continue;
        }

        usleep(SAMPLE_INTERVAL_MS / 1000.0); // Convert ms to seconds
    }

    pigpio_stop();
    close(i2c_fd);
    close(GPIO_ALERT);
    return 0;
}

