#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_ADDR 0x29
#define MODEL_ID_REG 0x010F
#define SYSTEM_RESET_REG 0x0000
#define SYSTEM_MODE_START 0x01
#define SYSRANGE_START_REG 0x007
#define RESULT_INTERRUPT_STATUS 0x013
#define RESULT_RANGE_STATUS 0x078
#define SYSTEM_INTERRUPT_CLEAR 0x014

#define DISTANCE_LOG_FILE "distance_log.csv"
#define LOG_HEADER "timestamp,distance_mm"
#define LOG_INTERVAL 100
#define THRESHOLD_STOP 300
#define THRESHOLD_APPROACH 600
#define THRESHOLD_SLOW 1200
#define THRESHOLD_CLEAR 1200

int main() {
    int i2c_fd, sensor_present = 0;
    struct i2c_client *client;
    char distance_log_str[100];
    FILE *distance_log_file;
    char *header = LOG_HEADER;

    if (pigpio_init() < 0) {
        perror("pigpio_init");
        exit(EXIT_FAILURE);
    }

    client = i2c_open(I2C_ADDR, 0);
    if (client == NULL) {
        perror("i2c_open");
        pigpio_shutdown();
        exit(EXIT_FAILURE);
    }

    if (i2c_write_byte(client, I2C_ADDR, MODEL_ID_REG) != 0xEA) {
        i2c_close(client);
        pigpio_shutdown();
        exit(EXIT_FAILURE);
    }

    if (i2c_write_byte(client, I2C_ADDR, SYSTEM_RESET_REG) != 0x00) {
        i2c_close(client);
        pigpio_shutdown();
        exit(EXIT_FAILURE);
    }

    if (i2c_write_byte(client, I2C_ADDR, SYSTEM_MODE_START) != 0x01) {
        i2c_close(client);
        pigpio_shutdown();
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (i2c_read_byte(client, I2C_ADDR, SYSRANGE_START_REG) & (1 << 0)) {
            usleep(100000);
            continue;
        }

        if (i2c_read_byte(client, I2C_ADDR, RESULT_INTERRUPT_STATUS) & (1 << 0)) {
            distance_log_str[strlen(distance_log_str) - 1] = '\0';
            time_t now = time(NULL);
            sprintf(distance_log_str, "%lu,%d", now, i2c_read_byte(client, I2C_ADDR, RESULT_RANGE_STATUS) << 8 | i2c_read_byte(client, I2C_ADDR, RESULT_RANGE_STATUS) >> 8);
            FILE *log_file = fopen(DISTANCE_LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open distance_log.csv\n");
                continue;
            }
            fprintf(log_file, "%s\n", header);
            fclose(log_file);

            if (strcmp(header, distance_log_str) == 0) {
                printf("New log file created.\n");
            }

            char *data_ready = strstr(distance_log_str, ",distance_mm");
            if (data_ready != NULL) {
                data_ready += strlen(",distance_mm");
                char *timestamp = data_ready;
                char *distance = strchr(data_ready, ',');
                *distance = '\0';
                printf("Parking guidance: %s\n", timestamp);
                if (strcmp(timestamp, "timestamp,distance_mm") == 0) {
                    printf("New timestamp recorded.\n");
                }
            }
        }

        pigpio_write_register(client, I2C_ADDR, SYSTEM_INTERRUPT_CLEAR, 0x01);

        usleep(LOG_INTERVAL * 1000);
    }

    i2c_close(client);
    pigpio_shutdown();
    return 0;
}

