void setup_pigpio() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", pigpioErrorString());
        exit(1);
    }
}

void setup_i2c() {
    int i2c_fd = -1;
    int retries = 3;
    int delay_ms = 10;

    for (int attempt = 0; attempt < retries; attempt++) {
        i2c_fd = open(pigpioI2CDeviceString(I2C_BUS), O_RDWR | O_NOCTTY | O_NDELAY);
        if (i2c_fd >= 0) {
            break;
        }
        usleep(delay_ms * attempt);
    }

    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d, attempt %d of %d: %s\n", I2C_BUS, attempt + 1, retries, pigpioErrorString());
        exit(1);
    }
}

void setup_sensor() {
    if (pigpioBegin(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to start I2C communication: %s\n", pigpioErrorString());
        exit(1);
    }

    if (pigpioWrite(i2c_fd, CH201_ADDR, 0x60, 2) < 0) {
        fprintf(stderr, "Failed to read from CH201: %s\n", pigpioErrorString());
        exit(1);
    }

    if (pigpioRead(i2c_fd, CH201_ADDR, 0x60, 2) == 0xFF) {
        fprintf(stderr, "CH201 sensor not found on I2C bus %d.\n", I2C_BUS);
        exit(1);
    }
}

void blink_led(int frequency) {
    gpioSetMode(LED_PIN, PIGO_OUTPUT);
    while (1) {
        int distance = pigpioI2CReadByteData(i2c_fd, CH201_ADDR, 0x60);
        if (distance == 0xFF) {
            printf("Sensor absent, exiting.\n");
            break;
        }

        int distance_in_mm = (distance << 8) | pigpioI2CReadByteData(i2c_fd, CH201_ADDR, 0x61);
        int frequency_hz = (distance_in_mm / 100.0) * MAX_FREQUENCY + MIN_FREQUENCY;
        if (frequency_hz > MAX_FREQUENCY) {
            frequency_hz = MAX_FREQUENCY;
        } else if (frequency_hz < MIN_FREQUENCY) {
            frequency_hz = MIN_FREQUENCY;
        }

        for (int i = 0; i < 1000000 / frequency_hz; i++) {
            gpioToggle(LED_PIN);
            usleep(100000 / frequency_hz);
        }
    }
}

