#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x53
#define LOG_FILE "distance_log.csv"
#define SAMPLE_INTERVAL 100000  // 100 ms in microseconds

void log_to_file(const char *timestamp, int distance) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening file for writing\n");
        return;
    }
    fprintf(file, "%s,%d\n", time_str, distance);
    fclose(file);
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    int ret;
    int distance;

    pigpio_init(1);  // Initialize pigpio with I2C bus 1

    while (1) {
        ret = pigpio_set_mode(I2C_BUS, PIGIO_OUTPUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to set I2C mode: %s\n", strerror(errno));
            continue;
        }

        ret = pigpio_write_i2c_bus(I2C_BUS, SENSOR_ADDRESS, 0x00, 0x01);  // Trigger measurement
        if (ret < 0) {
            fprintf(stderr, "Failed to write to sensor: %s\n", strerror(errno));
            continue;
        }

        usleep(SAMPLE_INTERVAL / 100000);  // Delay for 100 ms

        ret = pigpio_read_i2c_bus(I2C_BUS, SENSOR_ADDRESS, 0x00, 0x02, &distance);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            continue;
        }

        log_to_file(time(NULL), distance);
    }

    pigpio_stop();  // Stop pigpio
    pigpio_cleanup();  // Clean up pigpio resources

    return 0;
}

