#define SENSOR_PIN_1 17
#define SENSOR_PIN_2 27
#define DEBOUNCE_MS 50
#define POLL_MS 10

#define LOG_FILE "proximity_log.txt"

void sigint_handler(int signum) {
    printf("Received SIGINT, shutting down...\n");
    gpioTerminate();
    close(fildes);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, shutting down...\n");
    gpioTerminate();
    close(fildes);
    exit(0);
}

int main(int argc, char *argv[]) {
    int sensor_pins[] = {SENSOR_PIN_1, SENSOR_PIN_2};
    int gpio_files[2];
    int gpio_mode = PIGO_OUTPUT;
    int debounce_count = 0;
    int state_transition = 0;
    char timestamp[38];
    char event_type[10];
    FILE *log_file;

    if (signal(SIGINT, sigint_handler) == SIG_IGN || signal(SIGTERM, sigterm_handler) == SIG_IGN) {
        perror("Failed to register signal handlers");
        exit(1);
    }

    gpio_files[0] = gpioInitialise();
    if (gpio_files[0] == -1) {
        perror("Failed to initialise pigpio");
        exit(1);
    }

    for (int i = 0; i < 2; i++) {
        gpioSetMode(sensor_pins[i], gpio_mode);
        if (gpio_files[i] == -1) {
            perror("Failed to set mode for sensor pin");
            exit(1);
        }
    }

    while (1) {
        for (int i = 0; i < 2; i++) {
            int sensor_state = gpioRead(sensor_pins[i]);
            if (sensor_state != gpio_files[i]) {
                debounce_count = 0;
                state_transition = 0;
            } else {
                debounce_count++;
                if (debounce_count >= DEBOUNCE_MS / 1000) {
                    state_transition = (sensor_state == gpio_files[i]) ? 1 : 2;
                    debounce_count = 0;
                }
            }
        }

        if (state_transition == 1) {
            sprintf(timestamp, "%s",gmtime(&timestamp[0]));
            sprintf(event_type, "DETECTED", LOG_FILE);
            fprintf(log_file, "%s %d %s\n", timestamp, sensor_pins[0], event_type);
        } else if (state_transition == 2) {
            sprintf(timestamp, "%s",gmtime(&timestamp[0]));
            sprintf(event_type, "CLEARED", LOG_FILE);
            fprintf(log_file, "%s %d %s\n", timestamp, sensor_pins[0], event_type);
        }

        state_transition = 0;
        debounce_count = 0;

        usleep(POLL_MS * 1000 / 1000);
    }

    gpioTerminate();
    close(fildes);
    fclose(log_file);
    return 0;
}

