#include <sys/time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

#define LOG_FILE "distance_log.csv"
#define LOG_INTERVAL 500

void log_data(const char *timestamp, int distance_mm) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char *time_str = ctime(&tv.tv_sec);
    strcat(time_str, ".");
    strcat(time_str, ctime(&tv.tv_usec));
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fprintf(file, "%s,%.2f\n", time_str, (double)distance_mm / 1000.0);
    fclose(file);
}

int i2c_write_then_read(int fd, unsigned char write_reg, unsigned char *read_buf) {
    struct i2c_rdwr_cmd cmd = {
        .addr = I2C_ADDR,
        .flags = I2C_M_BRIDGE | I2C_M_READ,
        .len = 2,
        .buf = {write_reg, 0x00} // Assuming no data to read, just trigger
    };
    int ret = ioctl(fd, I2C_SLAVE, I2C_DEVICE(fd, I2C_BUS, I2C_ADDR));
    if (ret < 0) {
        perror("ioctl(I2C_SLAVE)");
        return ret;
    }
    ret = ioctl(fd, I2C_RDWR, &cmd);
    if (ret < 0) {
        perror("ioctl(I2C_RDWR)");
        return ret;
    }
    ret = read(fd, read_buf, 2);
    if (ret != 2) {
        perror("read");
        return errno;
    }
    return 0;
}

int main() {
    int fd, ret;
    unsigned char trigger_reg = MEAS_TRIGGER, status_reg[2], distance_reg[2];

    fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        perror("open(LOG_FILE)");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, TIOCMGET, &termios);
    if (ret < 0) {
        perror("TIOCGET);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, I2C_SETUP, &cmd);
    if (ret < 0) {
        perror("ioctl(I2C_SETUP)");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = i2c_write_then_read(fd, trigger_reg, status_reg);
        if (ret != 0) {
            fprintf(stderr, "I2C write-then-read failed: %s\n", strerror(errno));
            log_data(get_time_str(), -1);
            continue;
        }

        ret = i2c_write_then_read(fd, DIST_HIGH, distance_reg);
        if (ret != 0) {
            fprintf(stderr, "I2C write-then-read failed: %s\n", strerror(errno));
            log_data(get_time_str(), -1);
            continue;
        }

        int distance_mm = (distance_reg[0] << 8) | distance_reg[1];
        log_data(get_time_str(), distance_mm);

        usleep(LOG_INTERVAL * 1000); // Sleep for LOG_INTERVAL ms
    }

    close(fd);
    fclose(stdout);
    return 0;
}

