#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define LOG_INTERVAL 100

void i2c_retry(int cmd, int retries) {
    for (int i = 0; i < retries; ++i) {
        if (pigpio_i2c_transfer(MLX75030_ADDR, 0x00, 1, 0, cmd, 0, 1000) == 0) {
            return;
        }
        usleep(10000); // 10 ms delay
    }
    fprintf(stderr, "Failed to communicate with MLX75030 after %d retries.\n", retries);
    exit(EXIT_FAILURE);
}

int main() {
    pigpio_init(I2C_BUS);

    if (pigpio_setup_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        return EXIT_FAILURE;
    }

    struct i2c_client *client;
    client = pigpio_i2c_client_new(I2C_BUS, MLX75030_ADDR);
    if (!client) {
        fprintf(stderr, "Failed to create I2C client.\n");
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int distance;
        i2c_retry(pigpio_i2c_read_byte(client, 0x00), 3); // Read status byte (0x00)

        if (pigpio_error()) {
            fprintf(stderr, "Error reading from MLX75030: %s\n", pigpio_strerror());
            continue;
        }

        distance = pigpio_i2c_read_byte(client, 0x01);

        if (pigpio_error()) {
            fprintf(stderr, "Error reading from MLX75030: %s\n", pigpio_strerror());
            continue;
        }

        printf("Distance: %d mm\n", distance);
        usleep(LOG_INTERVAL * 1000); // Wait for next log interval
    }

    pigpio_i2c_client_free(client);
    pigpio_cleanup();

    return EXIT_SUCCESS;
}

// Handle SIGINT (Ctrl+C) to gracefully shut down
signal(SIGINT, signal_handler);

void signal_handler(int signum) {
    printf("Exiting gracefully...\n");
    pigpio_cleanup();
    exit(0);
}

