#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L4CX_ADDR 0x29
#define START_REGISTER 0x7FFF
#define RANGE_START_REGISTER 0x0009
#define INTERRUPT_STATUS_REGISTER 0x0046
#define DISTANCE_HIGH_REGISTER 0x0096
#define DISTANCE_LOW_REGISTER 0x0097

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_fd, ret;
    struct i2c_rdwr_t wr_cmd;
    struct i2c_rdwr_t rd_cmd;
    time_t now;
    struct tm *t;
    char timestamp[32];

    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        perror("pigpioInitialise");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    if (i2cOpen(I2C_BUS, &i2c_fd) < 0) {
        perror("i2cOpen");
        return EXIT_FAILURE;
    }

    // Initialize VL53L4CX sensor
    wr_cmd.address = VL53L4CX_ADDR;
    wr_cmd.len = 1;
    wr_cmd.data = &START_REGISTER;
    ret = i2cWrite(&wr_cmd);
    if (ret < 0) {
        perror("i2cWrite");
        return EXIT_FAILURE;
    }

    usleep(10000); // Wait 10 ms

    wr_cmd.address = VL53L4CX_ADDR;
    wr_cmd.len = 1;
    wr_cmd.data = &RANGE_START_REGISTER;
    ret = i2cWrite(&wr_cmd);
    if (ret < 0) {
        perror("i2cWrite");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        now = time(NULL);
        t = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        // Read interrupt status
        rd_cmd.address = VL53L4CX_ADDR;
        rd_cmd.len = 1;
        rd_cmd.data = &INTERRUPT_STATUS_REGISTER;
        ret = i2cRead(&rd_cmd, (void *)&ret);
        if (ret < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        if (ret & (1 << 0)) { // Bit 0 is set, ranging completed
            // Read distance
            ret = i2cRead(&rd_cmd, (void *)&(ret & 0xFF));
            if (ret < 0) {
                fprintf(stderr, "I2C read failed\n");
                continue;
            }
            ret = i2cRead(&rd_cmd, (void *)&(ret >> 8));
            if (ret < 0) {
                fprintf(stderr, "I2C read failed\n");
                continue;
            }

            printf("Timestamp: %s, Distance: %d mm\n", timestamp, (int)ret);
        }

        usleep(500000); // Wait 500 ms
    }

    // Clean up and exit
    i2cClose(i2c_fd);
    pigpioTerminate();
    return EXIT_SUCCESS;
}

