#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define BUZZER_GPIO 22
#define I2C_BUS 1
#define I2C_ADDR 0x29
#define RANGE_MODE_CONFIG_REG 0x0001
#define DEVICE_ADDR_REG 0x0001
#define SYSTEM_MODE_REG 0x0007
#define RESULT_DISTANCE_REG 0x0096
#define RANGE_INTERVAL 500
#define BUZZER_THRESHOLD 100

void buzzer_on(void) {
    gpioSetup(BUZZER_GPIO, GPIO_OUTPUT);
    gpioWrite(BUZZER_GPIO, 1);
}

void buzzer_off(void) {
    gpioSetup(BUZZER_GPIO, GPIO_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);
}

int main(int argc, char *argv[]) {
    int buzzer_state = 0;
    int sensor_present = 0;
    int i2c_result;

    pigioInit();

    while (1) {
        if (pigoi2cInit(I2C_BUS, I2C_ADDR) < 0) {
            fprintf(stderr, "I2C initialization failed: %s\n", pigoi2cGetErrorString());
            continue;
        }

        if (pigoi2cWrite(I2C_BUS, RANGE_MODE_CONFIG_REG, RANGE_MODE_CONFIG_REG) < 0) {
            fprintf(stderr, "Failed to write to SOFT_RESET register\n");
            continue;
        }

        if (pigoi2cWrite(I2C_BUS, DEVICE_ADDR_REG, DEVICE_ADDR_REG) < 0) {
            fprintf(stderr, "Failed to write to I2C_SLAVE__DEVICE_ADDRESS register\n");
            continue;
        }

        if (pigoi2cWrite(I2C_BUS, SYSTEM_MODE_REG, SYSTEM_MODE_REG) < 0) {
            fprintf(stderr, "Failed to write to SYSTEM__MODE_START register\n");
            continue;
        }

        if (pigoi2cWrite(I2C_BUS, RESULT_DISTANCE_REG, RESULT_DISTANCE_REG) < 0) {
            fprintf(stderr, "Failed to write to RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM register\n");
            continue;
        }

        i2c_result = pigoi2cRead(I2C_BUS, RESULT_DISTANCE_REG);
        if (i2c_result < 0) {
            fprintf(stderr, "Failed to read from RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM register\n");
            continue;
        }

        double distance = (double)(i2c_result >> 8) * 0.0254; // Convert to inches, then to mm

        if (distance < BUZZER_THRESHOLD) {
            buzzer_on();
        } else {
            buzzer_off();
        }

        sleep(RANGE_INTERVAL / 1000.0); // Convert 500 ms to seconds
    }

    pigioFinalize();
    return 0;
}

