#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 17
#define LOG_INTERVAL 200
#define SENS_TIMEOUT 50
#define SPEED_OF_SOUND 343

#define LOG_FILE "sensor_data.log"

void log_reading(const char *timestamp, int distance) {
    time_t now = time(NULL);
    char time_str[80];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s, %d\n", time_str, distance);
        fclose(file);
    }
}

int main(int argc, char *argv[]) {
    pigpio_init(5);

    if (pigpio_init(5) != 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(TRIGGER_GPIO, PIGO_OUTPUT);
    gpioSetMode(ECHO_GPIO, PIGO_INPUT);

    int servo_angle = -90;
    double distance = 0.0;

    while (1) {
        // Servo control
        int servo_pulse = 0;
        if (distance < 2) {
            servo_angle = -90;
        } else if (distance > 400) {
            servo_angle = 90;
        } else {
            double time_taken = 0.0;
            gpioSetMode(SERVO_GPIO, PIGO_OUTPUT);
            gpioWrite(SERVO_GPIO, servo_angle);
            time_taken = gpioRead(ECHO_GPIO) * 0.000001;
            gpioWrite(SERVO_GPIO, 0);

            if (time_taken < 1e-6) {
                servo_angle = -90;
            } else if (time_taken > 2e-6) {
                servo_angle = 90;
            } else {
                double distance_cm = (SPEED_OF_SOUND * time_taken) / 2;
                log_reading(ctime(NULL), distance_cm);
                distance = distance_cm;
            }
        }

        // Sensor timeout check
        if (gpioRead(ECHO_GPIO) == 0) {
            fprintf(stderr, "Echo stuck low, returning sentinel error\n");
            distance = -1;
            break;
        } else if (gpioRead(ECHO_GPIO) == 1) {
            fprintf(stderr, "Echo stuck high, returning sentinel error\n");
            distance = -1;
            break;
        }

        // Wait for log interval
        usleep(LOG_INTERVAL * 1000 / 1000);
    }

    // Graceful shutdown
    gpioTerminate();
    fprintf(stderr, "Shutting down...\n");
    exit(0);
}

