                log_reading(ctime(NULL), distance_cm);
                distance = distance_cm;
            }
        }

        // Sensor timeout check
        if (gpioRead(ECHO_GPIO) == 0) {
            fprintf(stderr, "Echo stuck low, returning sentinel error\n");
            distance = -1;
            break;
        } else if (gpioRead(ECHO_GPIO) == 1) {
            fprintf(stderr, "Echo stuck high, returning sentinel error\n");
            distance = -1;
            break;
        }

        // Wait for log interval
        usleep(LOG_INTERVAL * 1000 / 1000);
    }

    // Graceful shutdown
    gpioTerminate();
    fprintf(stderr, "Shutting down...\n");
    exit(0);
}
