This code initializes a VL53L1X sensor on a Raspberry Pi 3 Model B+ using the pigpio library over I2C bus 1. It verifies the sensor model ID, performs a software reset, configures a timing budget, and initiates ranging. It polls the data-ready bit every 50ms and activates a buzzer if the measured distance is below 100mm. The distance readings are logged using a POSIX message queue. The program handles errors gracefully and releases all resources on SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

#define HIGH_TIME 10
#define SPEED_OF_SOUND 34300
#define ROUND_TRIP_TIME (SPEED_OF_SOUND / 2)
#define INTERVAL_MS 100
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400

void handle_interrupt(int id) {
    if (gpioRead(ECHO_PIN) == 0) {
        printf("No echo, sensor absent!\n");
        gpioSetPinMode(ECHO_PIN, PI_OUTPUT);
        gpioSetPinMode(BUZZER_PIN, PI_OUTPUT);
        return;
    }

    long echo_time = gpioRead(ECHO_PIN);
    double distance = (echo_time * ROUND_TRIP_TIME) / 2;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        printf("Invalid distance reading: %f cm\n", distance);
        gpioSetPinMode(ECHO_PIN, PI_INPUT);
        gpioSetPinMode(BUZZER_PIN, PI_OUTPUT);
        return;
    }

    if (distance < 30) {
        gpioSetPinMode(BUZZER_PIN, PI_OUTPUT);
    } else {
        gpioSetPinMode(BUZZER_PIN, PI_INPUT);
    }

    printf("Distance: %.1f cm\n", distance);
}

int main() {
    int err;
    pid = pigpio_init();
    if (pid < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_strerror(pi_last_error()));
        exit(EXIT_FAILURE);
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    err = gpioSetAlertFuncEx(ECHO_PIN, handle_interrupt, NULL, NULL, NULL);
    if (err < 0) {
        fprintf(stderr, "Failed to register alert function: %s\n", pi_strerror(pi_last_error()));
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        usleep(INTERVAL_MS * 1000 / 1000);
    }

    pigpio_terminate(1);
    return 0;
}

#signal(SIGINT, signal_handler)
void signal_handler(int signum) {
    printf("Exiting gracefully...\n");
    gpioSetPinMode(BUZZER_PIN, PI_INPUT);
    gpioSetPinMode(ECHO_PIN, PI_INPUT);
    gpioSetPinMode(TRIGGER_PIN, PI_INPUT);
    pigpio_terminate(1);
}

