#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIG_DURATION 10
#define MEASURE_INTERVAL 200
#define TIMEOUT_INTERVAL 60
#define MAX_REJECTED_COUNT 1000
#define MAX_TIMEOUT_COUNT 30000

#define LOG_FILE "distance_log.txt"

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    close(LOG_FILE);
    gpioTerminate();
    exit(0);
}

void register_signals(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
}

void log_distance(const char *timestamp, double distance) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1,
            local_time->tm_mday, local_time->tm_hour, local_time->tm_min, local_time->tm_sec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }

    fprintf(log_file, "%s, %f\n", time_str, distance);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    register_signals();

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PIGO_OUTPUT);
    gpioSetMode(ECHO_PIN, PIGO_INPUT);
    gpioSetPullUp(ECHO_PIN);

    gpioSetTimerOutput(TRIG_PIN, TRIG_DURATION, NULL);

    double rising_edge_tick = 0, falling_edge_tick = 0;
    int echo_count = 0;
    int rejected_count = 0;
    int timeout_count = 0;

    while (1) {
        gpioTrigPulse(TRIG_PIN);
        rising_edge_tick = pigget(ECHO_PIN);
        falling_edge_tick = pigget(ECHO_PIN);

        double pulse_duration = (falling_edge_tick - rising_edge_tick) * 1e6 / 0.0343;
        double distance = pulse_duration / 2;

        if (pulse_duration < 100 || pulse_duration > MAX_TIMEOUT_COUNT) {
            rejected_count++;
            printf("Rejected reading: pulse duration %f us, out of range\n", pulse_duration);
            log_distance(get_iso8601_timestamp(), -1); // Log as invalid
        } else {
            echo_count++;
            log_distance(get_iso8601_timestamp(), distance);
        }

        if (timeout_count++ > 60) {
            timeout_count = 0;
            printf("Timeout after 60 ms, logging timeout warning\n");
            log_distance(get_iso8601_timestamp(), -1); // Log as timeout
        }

        usleep(MEASURE_INTERVAL * 1000 / 1000); // Adjust for 10 microsecond trigger
    }

    gpioTerminate();
    close(LOG_FILE);
    return 0;
}

