#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SERVO_PIN 18
#define VL53L1X_SHUTDOWN 23
#define VL53L1X_INTERRUPT 24
#define LOG_FILE "parking_log.txt"

void log_gate_state(const char *timestamp, double distance) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: Distance = %.2f cm, Gate State: %s\n",
                time_str, distance, (distance <= 50) ? "Open" : "Closed");
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int i2c_fd, servo_pin, vl53l1x_shutdown, vl53l1x_interrupt;
    int sensor_model_id;
    pigpio_init(5);

    if (pigpio_init(5) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    servo_pin = 18;
    vl53l1x_shutdown = 23;
    vl53l1x_interrupt = 24;

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        pigpio_terminate(5);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        pigpio_terminate(5);
        return EXIT_FAILURE;
    }

    // Read sensor model ID
    if (read(i2c_fd, &sensor_model_id, 1) != 1) {
        fprintf(stderr, "Failed to read sensor model ID: %s\n", strerror(errno));
        close(i2c_fd);
        pigpio_terminate(5);
        return EXIT_FAILURE;
    }

    if (sensor_model_id != 0x01) { // Assuming VL53L1X model ID is 0x01
        fprintf(stderr, "Invalid sensor model ID: %d\n", sensor_model_id);
        close(i2c_fd);
        pigpio_terminate(5);
        return EXIT_FAILURE;
    }

    // Configure VL53L1X shutdown pin as output
    if (write(i2c_fd, 0x00, 1) != 1) {
        fprintf(stderr, "Failed to configure VL53L1X shutdown pin: %s\n", strerror(errno));
        close(i2c_fd);
        pigpio_terminate(5);
        return EXIT_FAILURE;
    }

    // Configure VL53L1X interrupt pin as input with edge detection
    if (write(i2c_fd, 0x01, 1) != 1) {
        fprintf(stderr, "Failed to configure VL53L1X interrupt pin: %s\n", strerror(errno));
        close(i2c_fd);
        pigpio_terminate(5);
        return EXIT_FAILURE;
    }

    // Configure servo motor
    if (write(i2c_fd, 0x00, 1) != 1) {
        fprintf(stderr, "Failed to configure servo motor: %s\n", strerror(errno));
        close(i2c_fd);
        pigpio_terminate(5);
        return EXIT_FAILURE;
    }

    // Main loop
    double last_distance = -1;
    int gate_state = 0; // 0: Closed, 1: Open

    while (1) {
        // Read distance from VL53L1X
        if (read(i2c_fd, &sensor_model_id, 1) != 1) {
            fprintf(stderr, "Failed to read distance from VL53L1X: %s\n", strerror(errno));
            break;
        }

        if (sensor_model_id == 0x01) {
            double distance;
            if (read(i2c_fd, &distance, 8) != 8) {
                fprintf(stderr, "Failed to read distance from VL53L1X: %s\n", strerror(errno));
                break;
            }

            if (last_distance == -1) {
                last_distance = distance;
                log_gate_state(get_timestamp(), distance);
                gate_state = (distance <= 50) ? 1 : 0;
            } else {
                double delta_distance = distance - last_distance;
                if (delta_distance > 0 && gate_state == 0) {
                    gate_state = 1;
                    log_gate_state(get_timestamp(), distance);
                } else if (delta_distance < 0 && gate_state == 1) {
                    gate_state = 0;
                    log_gate_state(get_timestamp(), distance);
                }
            }

            last_distance = distance;
        }

        // Control servo motor
        if (gate_state == 1) {
            // Open gate
            pigpio_set_servo_pulsewidth(servo_pin, 1000);
        } else {
            // Close gate
            pigpio_set_servo_pulsewidth(servo_pin, 500);
        }

        usleep(100000); // Sleep for 100ms
    }

    // Clean up and exit
    pigpio_terminate(5);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

