#define I2C_DEVICE "/dev/i2c-1"
#define GPIO_LED_17 17
#define GPIO_LED_18 18
#define GPIO_LED_27 27
#define GPIO_LED_22 22

#define ELE_CONFIG0 0x80
#define ELE_CONFIG1 0x81
#define MHDR 0x00
#define NHDR 0x01
#define NCLR 0x0E
#define FDLR 0x00
#define REG_BASELINE 0x5A
#define REG_AUTOCONFIG 0x5B
#define REG_THRESHOLDS 0x5C
#define REG_RUNMODE 0x5D
#define REG_STATUS 0x5E

#define TOUCH_STATUS_REGISTER_0 0x00
#define TOUCH_STATUS_REGISTER_1 0x01

#define LED_PATTERN_0 0b0000
#define LED_PATTERN_1 0b0001
#define LED_PATTERN_2 0b0010
#define LED_PATTERN_3 0b0011
#define LED_PATTERN_4 0b0100
#define LED_PATTERN_5 0b0101
#define LED_PATTERN_6 0b0110
#define LED_PATTERN_7 0b0111
#define LED_PATTERN_8 0b1000
#define LED_PATTERN_9 0b1001
#define LED_PATTERN_10 0b1010
#define LED_PATTERN_11 0b1011
#define LED_PATTERN_12 0b1100
#define LED_PATTERN_13 0b1101
#define LED_PATTERN_14 0b1110
#define LED_PATTERN_15 0b1111

#define LOG_FILE "proximity_events.log"

void log_event(const char *event) {
    time_t now = time(NULL);
    char timestamp[20];
    sprintf(timestamp, "%s %d", ctime(&now), (int)now);
    fprintf(LOG_FILE, "%s: %s\n", timestamp, event);
}

int main() {
    int i2c_fd, gpio_led_17, gpio_led_18, gpio_led_27, gpio_led_22;
    gpiod_context_t ctx;
    gpio_set_dir(GPIO_LED_17, GPIO_OUTPUT);
    gpio_set_dir(GPIO_LED_18, GPIO_OUTPUT);
    gpio_set_dir(GPIO_LED_27, GPIO_OUTPUT);
    gpio_set_dir(GPIO_LED_22, GPIO_OUTPUT);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    gpio_init(&ctx, 4); // Initialize GPIO context for 4 lines

    // Soft reset
    write(i2c_fd, &0x63, 1);
    read(i2c_fd, &status, 1);
    if (status != 0x63) {
        log_event("Soft reset failed");
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    read(i2c_fd, &status, 1);
    if (status != 0x0B) {
        log_event("Sensor not present");
        return EXIT_FAILURE;
    }

    // Initialize sensor
    write(i2c_fd, &0x00, 1); // Stop mode
    write(i2c_fd, &0x01, 1); // Baseline filtering
    write(i2c_fd, &0x0E, 1); // NCLR
    write(i2c_fd, &0x00, 1); // FDLR
    write(i2c_fd, &0x0B, 1); // Auto-configuration thresholds
    write(i2c_fd, &0xC8, 1); // ELECONFIG0
    write(i2c_fd, &0x82, 1); // ELECONFIG1
    write(i2c_fd, &0x82, 1); // ELECONFIG2
    write(i2c_fd, &0xB4, 1); // ELECONFIG3
    write(i2c_fd, &0x0C, 1); // Run mode

    // Initialize electrodes
    for (int i = 0; i < 12; i++) {
        write(i2c_fd, &0x00, 1); // Enable electrode
        read(i2c_fd, &status, 1);
        if (status != 0x00) {
            log_event("Failed to enable electrode");
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (1) {
        struct i2c_rdwr_cmd cmd = {
            .addr = 0x5A,
            .flags = I2C_M_READ | I2C_M_RST,
            .len = 2,
            .data = {TOUCH_STATUS_REGISTER_0, 0x00}
        };
        int rc = ioctl(i2c_fd, I2C_RDWR, &cmd);
        if (rc < 0) {
            perror("I2C read failed");
            log_event("I2C read failed");
            return EXIT_FAILURE;
        }
        int status_reg0 = cmd.data[1];

        cmd.len = 2;
        cmd.data = {TOUCH_STATUS_REGISTER_1, 0x00};
        rc = ioctl(i2c_fd, I2C_RDWR, &cmd);
        if (rc < 0) {
            perror("I2C read failed");
            log_event("I2C read failed");
            return EXIT_FAILURE;
        }
        int status_reg1 = cmd.data[1];

        // Map touch status to LED pattern
        int active_electrode = -1;
        for (int i = 0; i < 12; i++) {
            if (status_reg0 & (1 << i)) {
                active_electrode = i;
                break;
            }
        }
        if (active_electrode == -1) {
            log_event("No electrode detected");
            gpio_set_level(GPIO_LED_17, 0);
            gpio_set_level(GPIO_LED_18, 0);
            gpio_set_level(GPIO_LED_27, 0);
            gpio_set_level(GPIO_LED_22, 0);
        } else {
            gpio_set_level(GPIO_LED_17, active_electrode < 6 ? LED_PATTERN_0 : LED_PATTERN_1);
            gpio_set_level(GPIO_LED_18, active_electrode < 6 ? LED_PATTERN_2 : LED_PATTERN_3);
            gpio_set_level(GPIO_LED_27, active_electrode < 6 ? LED_PATTERN_4 : LED_PATTERN_5);
            gpio_set_level(GPIO_LED_22, active_electrode < 6 ? LED_PATTERN_6 : LED_PATTERN_7);
        }

        // Log proximity event
        log_event("Proximity detected on electrode: %d", active_electrode);

        usleep(50000); // Wait for 50 ms
    }

    close(i2c_fd);
    gpiod_context_destroy(&ctx);

    return 0;
}

