#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define TIMEOUT_MS 30000
#define PULSE_US 10
#define HOLD_US 5
#define SPEED_CM_PER_US 0.0343
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2

volatile sig_atomic_t exit_cleanup = 0;

void signal_handler(int signum) {
    exit_cleanup = 1;
}

int main() {
    gpiod_context ctx;
    gpiod_channel trig_channel, echo_channel;
    gpiod_line_request_output(TRIGGER_GPIO, &trig_channel);
    gpiod_line_request_input(ECHO_GPIO, &echo_channel);

    if (gpiod_channel_is_requestable(&trig_channel) == -1 ||
        gpiod_channel_is_requestable(&echo_channel) == -1) {
        perror("Failed to request GPIO lines");
        return 1;
    }

    gpiod_set_driven(trig_channel, false);
    gpiod_set_driven(echo_channel, true);

    while (!exit_cleanup) {
        // Trigger sequence
        gpiod_output_p(TRIGGER_GPIO, 0);
        gpiod_output_p(TRIGGER_GPIO, 1);
        gpiod_output_p(TRIGGER_GPIO, 0);

        // Wait for echo rising edge
        gpiod_wait_for_signal(echo_channel, GPIOD_EVENT_RISING, TIMEOUT_MS);

        // Measure echo pulse width
        uint32_t echo_start = gpiod_get_last_value(echo_channel);
        gpiod_wait_for_signal(echo_channel, GPIOD_EVENT_FALLING, TIMEOUT_MS);
        uint32_t echo_end = gpiod_get_last_value(echo_channel);
        uint32_t pulse_width = echo_end - echo_start;

        // Calculate distance
        double distance = (pulse_width * SPEED_CM_PER_US) / 2.0;

        // Check distance bounds
        if (distance < MIN_DISTANCE_CM) {
            printf("Distance out of bounds: %f cm\n", distance);
        } else if (distance > MAX_DISTANCE_CM) {
            printf("Distance out of bounds: %f cm\n", distance);
        } else {
            // Log distance with ISO 8601 timestamp
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(NULL));
            FILE *log_file = fopen("distance_log.txt", "a");
            if (log_file == NULL) {
                perror("Failed to open distance log file");
                exit(1);
            }
            fprintf(log_file, "%s, %f\n", timestamp, distance);
            fclose(log_file);
        }

        // Sleep for a second
        usleep(1000000);
    }

    // Clean up libgpiod resources
    gpiod_channel_free(&trig_channel);
    gpiod_channel_free(&echo_channel);
    gpiod_context_free(&ctx);

    // Handle SIGINT to clean up resources
    signal(SIGINT, signal_handler);

    return 0;
}

