#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>
#include <signal.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define VOLTAGE_DIVIDER 1000
#define TRIG_PULSE_US 2
#define MAX_PULSE_WIDTH_US 50000
#define MIN_PULSE_WIDTH_US 58
#define LOG_FILE "distance_log.txt"
#define TRIG_INTERVAL_US 10000

#define ISR_FUNC gpioSetISRFuncEx

void log_distance(double distance) {
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fp, "%s: %f m\n", timestamp, distance);
    fclose(fp);
}

ISR_FUNC echo_isr(void) {
    static unsigned long last_echo = 0;
    unsigned long current_echo = gpioGetEcho(ECHO_GPIO);
    unsigned long pulse_width_us = current_echo - last_echo;
    last_echo = current_echo;

    if (pulse_width_us > 0 && pulse_width_us < MAX_PULSE_WIDTH_US && pulse_width_us > MIN_PULSE_WIDTH_US) {
        double distance = pulse_width_us * 343 / 2e6;
        log_distance(distance);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        return 1;
    }

    if (pigpioInitialise() < 0) {
        perror("Failed to initialise pigpio");
        return 1;
    }

    gpioSetMode(TRIG_GPIO, PIGO_OUTPUT);
    gpioSetMode(ECHO_GPIO, PIGO_INPUT);
    gpioSetISR(TRIG_GPIO, PULSE_ISR, echo_isr);

    if (gpioSetISRFuncEx(TRIG_GPIO, echo_isr, NULL) < 0) {
        perror("Failed to set ISR function");
        pigpioTerminate();
        return 1;
    }

    gpioSetPulseInAttenuation(ECHO_GPIO, 1000); // 1 kOhm divider

    if (gpioTriggerPulse(TRIG_GPIO, TRIG_PULSE_US) < 0) {
        perror("Failed to trigger GPIO");
        pigpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    if (sigaddset(&sa.sa_mask, SIGINT) != 0 || sigaddset(&sa.sa_mask, SIGTERM) != 0) {
        perror("Failed to set signal handlers");
        pigpioTerminate();
        return 1;
    }
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        pigpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install SIGTERM handler");
        pigpioTerminate();
        return 1;
    }

    while (1) {
        usleep(TRIG_INTERVAL_US / 2);
    }

    pigpioTerminate();
    fclose(stdout);
    return 0;
}

