#define I2C_BUS 1
#define I2C_ADDR 0x29
#define TRIGGER_GPIO 27

void log_info(const char *format, ...) {
    char buffer[256];
    vasprintf(buffer, format, args);
    syslog(LOG_INFO, "%s", buffer);
}

void log_err(const char *format, ...) {
    char buffer[256];
    vasprintf(buffer, format, args);
    syslog(LOG_ERR, "%s", buffer);
}

int main() {
    int i2c_fd;
    int ret;

    // Initialize pigpio
    if ((ret = pigpio_init()) != 0) {
        log_err("Failed to initialize pigpio: %s", pi_strerror());
        return -1;
    }

    // Configure GPIO27 as output
    if (piSetupOutput(TRIGGER_GPIO) != 0) {
        log_err("Failed to configure GPIO27 as output");
        return -1;
    }

    // Set active-low trigger
    piWrite(TRIGGER_GPIO, 0);

    // Open I2C device
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        log_err("Failed to open I2C device: %s", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_err("Failed to set I2C slave address");
        return -1;
    }

    // Configure VL53L1X sensor
    if (piWrite(i2c_fd, 0x00, 2) != 2) {
        log_err("Failed to write to sensor register 0x0018");
        return -1;
    }
    if (piWrite(i2c_fd, 0x00, 2) != 2) {
        log_err("Failed to write to sensor register 0x0019");
        return -1;
    }
    if (piWrite(i2c_fd, 0x01, 1) != 1) {
        log_err("Failed to write to sensor register 0x0020");
        return -1;
    }

    // Main loop
    while (1) {
        // Read distance and status
        uint8_t status;
        uint16_t distance;
        if (piRead(i2c_fd, 0x00, 2, &distance) != 2) {
            log_err("Failed to read distance");
            usleep(100000); // Wait 100 ms
            continue;
        }
