#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>
#include <fcntl.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 18
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define SAMPLE_SIZE 5
#define LOG_INTERVAL 100
#define LOG_FILE "distance_log.csv"
#define BUFFER_SIZE 1024

volatile sig_atomic_t stop_servo = 0;

void signal_handler(int signum) {
    stop_servo = 1;
}

void init_pigpio() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(TRIGGER_GPIO, PIGIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set %s as output\n", TRIGGER_GPIO);
        pigpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(ECHO_GPIO, PIGIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set %s as input\n", ECHO_GPIO);
        pigpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(SERVO_GPIO, PIGIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set %s as output\n", SERVO_GPIO);
        pigpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void register_alert_callback(void (*callback)(uint32_t)) {
    if (gpioAlertRegister(ECHO_GPIO, callback) < 0) {
        fprintf(stderr, "Failed to register alert callback\n");
        pigpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void gpioServo(int pin, int duty) {
    if (gpioWrite(pin, duty) < 0) {
        fprintf(stderr, "Failed to set servo pin\n");
        pigpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void distance_callback(uint32_t timestamp, uint32_t pulse_width) {
    static uint32_t pulse_widths[SAMPLE_SIZE] = {0};
    static int count = 0;
    static double distance = 0.0;
    static int servo_angle = 0;

    if (count >= SAMPLE_SIZE) {
        pulse_widths[0] = pulse_widths[count - SAMPLE_SIZE];
        count = 0;
    }

    pulse_widths[count++] = pulse_width;

    if (count == SAMPLE_SIZE) {
        double sum = 0;
        for (int i = 0; i < SAMPLE_SIZE; i++) {
            sum += pulse_widths[i];
        }
        distance = (34300.0 * sum) / (4.0 * SAMPLE_SIZE);

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %f, defaulting to 90 degrees\n", distance);
            distance = 90.0;
        }

        servo_angle = map(distance, 2.0, MAX_DISTANCE, 0.0, 180.0);

        if (pulse_widths[0] == 0) {
            fprintf(stderr, "No echo received, logging -1.0 and defaulting to 90 degrees\n");
            distance = -1.0;
            servo_angle = 90;
        }

        if (write_log(timestamp, distance, servo_angle) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }
    }
}

int write_log(uint64_t timestamp, double distance, int servo_angle) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        return -1;
    }

    fprintf(file, "%lu,%f,%d\n", (unsigned long)timestamp, distance, servo_angle);
    fclose(file);
    return 0;
}

int main() {
    init_pigpio();
    register_alert_callback(distance_callback);

    signal(SIGINT, signal_handler);

    while (!stop_servo) {
        gpioDelay(100);
        gpioWrite(TRIGGER_GPIO, 0);
        gpioDelay(10);
        gpioWrite(TRIGGER_GPIO, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_GPIO, 0);

        uint32_t pulse_width = 0;
        if (gpioRead(ECHO_GPIO) == PIGIO_INPUT_HIGH) {
            pulse_width = pigpioGetTick() - gpioGetInput(ECHO_GPIO);
        }

        if (pulse_width == 0) {
            fprintf(stderr, "No echo received, logging -1.0 and defaulting to 90 degrees\n");
            distance_callback(pigpioGetTick(), -1.0);
            gpioServo(SERVO_GPIO, 90);
            continue;
        }

        distance_callback(pigpioGetTick(), pulse_width);
        usleep(LOG_INTERVAL * 1000);
    }

    gpioTerminate();
    fclose(stdout);
    return 0;
}

