#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <pigpio.h>
#include <i2c-dev.h>
#include <sys/epoll.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PROXIMITY_REG_HIGH 0x08
#define PROXIMITY_REG_LOW 0x09
#define THRESHOLD 1000

#define LOG_FILE "proximity.log"

volatile int threshold_set = 0;
volatile int interrupt_flag = 0;

void *interrupt_handler(void *arg) {
    int proximity_high, proximity_low;
    int16_t proximity_value;

    if (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, PROXIMITY_REG_HIGH) == -1) {
        perror("Error reading high byte");
        return NULL;
    }
    proximity_high = pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, PROXIMITY_REG_LOW);
    if (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, PROXIMITY_REG_LOW) == -1) {
        perror("Error reading low byte");
        return NULL;
    }
    proximity_low = pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, PROXIMITY_REG_LOW);

    proximity_value = (proximity_high << 8) | proximity_low;

    if (proximity_value > threshold_set) {
        if (pthread_mutex_lock(&mutex) == -1) {
            perror("Mutex lock failed");
            return NULL;
        }
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %d: ALERT\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec, proximity_value);
        fclose(log_file);
        pthread_mutex_unlock(&mutex);
    } else {
        if (pthread_mutex_lock(&mutex) == -1) {
            perror("Mutex lock failed");
            return NULL;
        }
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %d: SAFE\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec, proximity_value);
        fclose(log_file);
        pthread_mutex_unlock(&mutex);
    }

    interrupt_flag = 1;
    return NULL;
}

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd;
    int i2c_address = 0;
    int threshold = THRESHOLD;

    if (argc > 1) {
        if (strcmp(argv[1], "-a") == 0) {
            if (argc > 2) {
                i2c_address = strtol(argv[2], NULL, 10);
            } else {
                i2c_address = strtol(argv[2], NULL, 16);
            }
        }
    }

    if (argc > 2) {
        if (strcmp(argv[2], "-t") == 0) {
            threshold = strtol(argv[3], NULL, 10);
        } else {
            threshold = strtol(argv[2], NULL, 10);
        }
    }

    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (i2c_fd = open("/dev/i2c-1", O_RDWR) == -1) {
        perror("Failed to open I2C bus 1");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (setmode(i2c_fd, IC_500K) == -1) {
        perror("Failed to set I2C mode");
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (i2c_address == 0) {
        if (pigpio_write_i2c_byte(i2c_fd, I2C_ADDR, 0x60) == -1) {
            perror("Failed to write I2C address");
            close(i2c_fd);
            pigpio_terminate();
            return EXIT_FAILURE;
        }
    } else if (i2c_address == 1) {
        if (pigpio_write_i2c_byte(i2c_fd, I2C_ADDR, i2c_address) == -1) {
            perror("Failed to write I2C address");
            close(i2c_fd);
            pigpio_terminate();
            return EXIT_FAILURE;
        }
    } else {
        fprintf(stderr, "Invalid I2C address format\n");
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (gpio_fd = open(PIG_GPIO, O_WRONLY | O_NOCTTY) == -1) {
        perror("Failed to open GPIO file descriptor");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (pigpio_set_mode(gpio_fd, PIG_OUTPUT) == -1) {
        perror("Failed to set GPIO mode");
        close(gpio_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (pigpio_write_i2c_byte(i2c_fd, I2C_ADDR, PROXIMITY_REG_HIGH) == -1) {
        perror("Failed to write to proximity high byte register");
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (pigpio_write_i2c_byte(i2c_fd, I2C_ADDR, PROXIMITY_REG_LOW) == -1) {
        perror("Failed to write to proximity low byte register");
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (pigpio_write_i2c_byte(i2c_fd, I2C_ADDR, 0x01) == -1) {
        perror("Failed to enable interrupt on rising edge");
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (pigpio_enable_irq(i2c_fd, 1) == -1) {
        perror("Failed to enable interrupt");
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (epoll_create1(&epoll_fd) == -1) {
        perror("Failed to create epoll instance");
        pthread_mutex_destroy(&mutex);
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (epoll_ctl(epoll_fd, EPOLLIN, i2c_fd, {0}) == -1) {
        perror("Failed to add I2C file descriptor to epoll");
        epoll_destroy(epoll_fd);
        pthread_mutex_destroy(&mutex);
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (pthread_create(&thread_id, NULL, interrupt_handler, NULL) != 0) {
        perror("Failed to create interrupt handler thread");
        epoll_destroy(epoll_fd);
        pthread_mutex_destroy(&mutex);
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    printf("Proximity sensor initialized. Press Ctrl+C to exit.\n");

    if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
    }

    if (pthread_join(thread_id, NULL) != 0) {
        perror("Failed to join interrupt handler thread");
    }

    if (close(epoll_fd) == -1) {
        perror("Failed to close epoll instance");
    }

    if (close(i2c_fd) == -1) {
        perror("Failed to close I2C bus 1");
    }

    if (close(gpio_fd) == -1) {
        perror("Failed to close GPIO file descriptor");
    }

    pigpio_terminate();

    return EXIT_SUCCESS;
}

