#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define GPIO_SPEAKER 18
#define GPIO_TRIGGER 23
#define GPIO_ECHO 24
#define MIN_DISTANCE 2
#define MAX_DISTANCE 200
#define FREQ_MIN 200
#define FREQ_MAX 2000
#define DUTY_CYCLE 50

int speaker_gpio = GPIO_SPEAKER;
int trigger_gpio = GPIO_TRIGGER;
int echo_gpio = GPIO_ECHO;

double map_distance_to_frequency(double distance) {
    return 200 * exp((distance - MIN_DISTANCE) / 50);
}

void handle_interrupt(int sig) {
    pigpio_stop(speaker_gpio);
    pigpio_cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    if (signal(SIGINT, handle_interrupt) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, handle_interrupt) < 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    while (1) {
        double distance = -1;
        int trigger_time = 0;

        // Trigger the HC-SR04 sensor
        gpioTrigger(trigger_gpio);
        usleep(10); // 10 us trigger pulse
        gpioWaveTxBusy(echo_gpio);
        trigger_time = gpioWaveRxBusy(echo_gpio);
        gpioTrigger(trigger_gpio);

        if (trigger_time < 100) {
            // Timeout, use previous distance
            distance = -1;
        } else {
            // Calculate distance in cm
            distance = 100.0 * US_PER_MICROSECOND / (2 * trigger_time * 1e6);

            // Map distance to frequency
            double frequency = map_distance_to_frequency(distance);

            // Ensure frequency is within the range
            frequency = fmin(frequency, FREQ_MAX);
            frequency = fmax(frequency, FREQ_MIN);

            // Generate PWM tone
            pigpio_set_PWM_range(speaker_gpio, 0, 255);
            pigpio_set_PWM_duty(speaker_gpio, DUTY_CYCLE);
            pigpio_set_PWM_frequency(speaker_gpio, frequency);
            usleep(100000 / frequency); // Pulse width modulation period
            pigpio_set_PWM_duty(speaker_gpio, 0);
        }

        // Sleep for a short duration to avoid CPU overload
        usleep(100000);
    }

    pigpio_stop(speaker_gpio);
    pigpio_cleanup();
    return 0;
}

