This code sets up a theremin-like instrument using a Raspberry Pi 3 Model B+ and an HC-SR04 ultrasonic sensor. It uses the pigpio library for PWM control and reads the distance from the sensor to adjust the tone's frequency. The code includes error handling, a SIGINT handler for clean termination, and a 10 ms delay between readings. The ultrasonic sensor's range is linearly mapped to a PWM frequency range, and the tone changes smoothly and continuously.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT 50
#define TIME_BETWEEN_READINGS 500
#define SPEED_OF_SOUND 29.1

int main(int argc, char *argv[]) {
    int pin_echo, pin_trigger, distance, invalid_reading = 0;
    struct sigaction sa;

    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins
    pin_echo = ECHO_PIN;
    pin_trigger = TRIGGER_PIN;
    gpioOutput(pin_trigger, 0); // Set trigger pin as output (initially low)

    // Set up signal handler for SIGINT
    sa.sa_handler = sigintHandler;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        // Send a 10 us pulse on the trigger pin
        gpioOutput(pin_trigger, 1);
        usleep(10000); // 10 us
        gpioOutput(pin_trigger, 0);

        // Measure the echo pulse width
        int echo_pulse_width = pigget(pin_echo, TIMEOUT);

        // Check for timeout
        if (echo_pulse_width == -1) {
            invalid_reading = 1;
            continue;
        }

        // Calculate distance
        double pulse_width = (double)echo_pulse_width * 58.0 / 18000000.0; // Convert to microseconds
        distance = pulse_width * SPEED_OF_SOUND / 2;

        // Check for invalid readings
        if (distance < 2 || distance > 400) {
            printf("Invalid reading: %f cm\n", distance);
            invalid_reading = 1;
        }

        // Print distance
        if (distance < 10) {
            printf("Too close! %f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        // Sleep before next reading
        usleep(TIME_BETWEEN_READINGS * 1000000);
    }

    // Clean up and exit
    pigcancel(echo_pulse_width); // Cancel any pending echo pulses
    pigpioTerminate(); // Terminate pigpio
    return 0;
}

// Signal handler for SIGINT
void sigintHandler(int signum) {
    invalid_reading = 1;
}

