#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#define SPI_CS_GPIO 8
#define SPI_CLOCK_HZ 1000000
#define SPI_MODE 0
#define SPI_DATA_BITS 8

#define LOG_FILE "distance_log.csv"
#define LOG_INTERVAL 100

void spiInit(void);
void spiWriteRead(uint8_t *data, size_t len);
void spiError(const char *msg);
void logEntry(const char *timestamp, int distance);
void handleSignals(int sig);

int main(int argc, char *argv[]) {
    pid_t pid;
    int fd;
    struct stat sb;

    spiInit();

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    pid = fork();
    if (pid == 0) {
        // Child process
        while (1) {
            spiWriteRead((uint8_t *){"0x01", 1}, 1); // Set continuous mode
            spiWriteRead((uint8_t *){"0x00", 1}, 1); // Set 5m range
            spiWriteRead((uint8_t *){"0x01", 1}, 1); // Trigger measurement

            spiError(NULL); // Simulate SPI error
            if (errno == EIO) {
                continue;
            }

            spiWriteRead((uint8_t *){"0x00", 1}, 1); // Read distance
            int distance = ((uint16_t)spiRead(2)) << 8 | spiRead(1);
            logEntry(ctime(NULL), distance);

            usleep(LOG_INTERVAL * 1000 / 1000);
        }
    } else {
        // Parent process
        waitpid(pid, NULL, 0);
    }

    close(fd);
    spiTerminate();
    exit(EXIT_SUCCESS);
}

void spiInit(void) {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    if (ioctl(SPI_CS_GPIO, SPI_SETCS, 1) < 0) {
        fprintf(stderr, "Failed to set CE0 as output: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void spiWriteRead(uint8_t *data, size_t len) {
    if (spiXfer(data, len) < 0) {
        spiError("SPI write/read error");
    }
}

void spiError(const char *msg) {
    fprintf(stderr, "SPI Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void logEntry(const char *timestamp, int distance) {
    static char *logFormat = "timestamp,distance\n";
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s for appending: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    fprintf(fp, "%s,%d\n", timestamp, distance);
    fclose(fp);
}

void handleSignals(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        spiTerminate();
        close(1); // Close stdout
        logEntry(ctime(NULL), -1); // Log an error
        exit(EXIT_SUCCESS);
    }
}

void spiTerminate(void) {
    if (pigpio_terminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio: %s\n", pigpio_error());
    }
}

