#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define REG_LOW 0x22
#define REG_HIGH 0x23
#define LOG_FILE "proximity_log.csv"
#define LOG_HEADER "timestamp,als_visible"

#define BUFFER_SIZE 10
char buffer[BUFFER_SIZE];

void log_to_file(const char *timestamp, uint16_t light_value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }
    fprintf(file, "%s,%u\n", timestamp, light_value);
    fclose(file);
}

int main() {
    int fd;
    struct i2c_client *client;
    uint16_t light_value;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(fd);
    if (!client) {
        perror("Failed to allocate i2c client");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        if (errno == EOPERNOTFOUND) {
            printf("Sensor not found at address 0x%02x\n", I2C_ADDR);
        } else if (errno != EBADF) {
            perror("Failed to set slave device");
        }
        i2c_free(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        light_value = 0;
        if (read(client->fd, buffer, sizeof(buffer)) < sizeof(buffer)) {
            perror("Failed to read from I2C device");
            continue;
        }

        light_value = (uint16_t)(buffer[0] << 8 | buffer[1]);

        if (write(client->fd, &light_value, sizeof(light_value)) != sizeof(light_value)) {
            perror("Failed to write to I2C device");
            continue;
        }

        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(&now));
        log_to_file(timestamp, light_value);

        usleep(5000000); // 5 seconds delay
    }

    i2c_free(client);
    close(fd);

    return 0;
}

