#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define RESET_REG 0x30
#define PART_ID_REG 0x00
#define ALS_LOW_REG 0x22
#define ALS_HIGH_REG 0x23
#define PROX_LOW_REG 0x18
#define PROX_HIGH_REG 0x19
#define LOG_FILE "si1120_log.txt"
#define SAMPLE_INTERVAL 500
#define MAX_RETRIES 3
#define DELAY_BETWEEN_RETRIES 10

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_client *client;
    pigpio pi;
    struct timeval tv;
    char log_msg[100];

    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_strerror(pi_last_error()));
        return 1;
    }

    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpio_terminate();
        return 1;
    }

    client = i2c_client_new(I2C_BUS, I2C_ADDR);
    if (!client) {
        fprintf(stderr, "Failed to create I2C client: %s\n", strerror(errno));
        close(i2c_fd);
        pigpio_terminate();
        return 1;
    }

    while (1) {
        ret = pigpio_set_mode(0, PI_OUTPUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to set output mode: %s\n");
            close(i2c_fd);
            pigpio_terminate();
            return 1;
        }

        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            tv.tv_sec = 0;
            tv.tv_usec = SAMPLE_INTERVAL * 1000;

            ret = i2c_transfer(client, I2C_READ, RESET_REG, 1, &tv);
            if (ret < 0) {
                fprintf(stderr, "I2C read reset failed: %s\n");
                continue;
            }

            if (client->regs[RESET_REG] != 0x01) {
                fprintf(stderr, "Failed to reset sensor, retrying...\n");
                usleep(DELAY_BETWEEN_RETRIES * 1000);
                continue;
            }

            ret = i2c_transfer(client, I2C_READ, PART_ID_REG, 1, &tv);
            if (ret < 0) {
                fprintf(stderr, "I2C read part ID failed: %s\n");
                continue;
            }

            if (client->regs[PART_ID_REG] != 0x41) {
                fprintf(stderr, "Part ID mismatch, retrying...\n");
                usleep(DELAY_BETWEEN_RETRIES * 1000);
                continue;
            }

            ret = i2c_transfer(client, I2C_READ, ALS_LOW_REG, 1, &tv);
            if (ret < 0) {
                fprintf(stderr, "I2C read ALS low byte failed: %s\n");
                continue;
            }

            ret = i2c_transfer(client, I2C_READ, ALS_HIGH_REG, 1, &tv);
            if (ret < 0) {
                fprintf(stderr, "I2C read ALS high byte failed: %s\n");
                continue;
            }

            ret = i2c_transfer(client, I2C_READ, PROX_LOW_REG, 1, &tv);
            if (ret < 0) {
                fprintf(stderr, "I2C read proximity low byte failed: %s\n");
                continue;
            }

            ret = i2c_transfer(client, I2C_READ, PROX_HIGH_REG, 1, &tv);
            if (ret < 0) {
                fprintf(stderr, "I2C read proximity high byte failed: %s\n");
                continue;
            }

            int16_t al_value = (client->regs[ALS_LOW_REG] << 8) | client->regs[ALS_HIGH_REG];
            int16_t pr_value = (client->regs[PROX_LOW_REG] << 8) | client->regs[PROX_HIGH_REG];

            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            sprintf(log_msg, "%04d-%02d-%02d %02d:%02d:%02d: ALS = %d, Proximity = %d\n",
                    tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec);
            if (write(i2c_fd, log_msg, strlen(log_msg)) < 0) {
                fprintf(stderr, "Failed to write to log file: %s\n");
                close(i2c_fd);
                pigpio_terminate();
                return 1;
            }

            close(i2c_fd);
            pigpio_terminate();
            return 0;
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

