#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define REG_PART_ID 0x00
#define REG_MEAS_RATE 0x08
#define REG_AMBIENT_LIGHT 0x22
#define REG_PROXIMITY 0x24

#define LOG_FILE "biometric_log.txt"

void log_reading(const char *timestamp, int lux, int proximity) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[32];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S.%03d", timeinfo);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s,%d,%d\n", buffer, lux, proximity);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_client *client;
    unsigned char part_id[2];
    unsigned short meas_rate;
    unsigned short ambient_light, proximity;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(i2c_fd, I2C_ADDR);
    if (!client) {
        perror("Failed to create I2C client");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_client_free(client);
        exit(EXIT_FAILURE);
    }

    ret = i2c_client_request(client, 2);
    if (ret < 0) {
        perror("Failed to request I2C operations");
        close(i2c_fd);
        i2c_client_free(client);
        exit(EXIT_FAILURE);
    }

    ret = i2c_client_write_reg(client, REG_PART_ID, part_id);
    if (ret < 0) {
        perror("Failed to read part ID");
        close(i2c_fd);
        i2c_client_free(client);
        exit(EXIT_FAILURE);
    }

    if (part_id[0] != 0x11 && part_id[1] != 0x82) {
        fprintf(stderr, "Sensor part ID mismatch, exiting.\n");
        close(i2c_fd);
        i2c_client_free(client);
        exit(EXIT_FAILURE);
    }

    ret = i2c_client_write_reg(client, REG_MEAS_RATE, &meas_rate);
    if (ret < 0) {
        perror("Failed to write measurement rate");
        close(i2c_fd);
        i2c_client_free(client);
        exit(EXIT_FAILURE);
    }

    ret = i2c_client_write_reg(client, REG_AMBIENT_LIGHT, &ambient_light);
    if (ret < 0) {
        perror("Failed to read ambient light");
        close(i2c_fd);
        i2c_client_free(client);
        exit(EXIT_FAILURE);
    }

    ret = i2c_client_write_reg(client, REG_PROXIMITY, &proximity);
    if (ret < 0) {
        perror("Failed to read proximity");
        close(i2c_fd);
        i2c_client_free(client);
        exit(EXIT_FAILURE);
    }

    lux = ambient_light * 0.1;
    log_reading(get_timestamp(), lux, proximity);
    printf("lux: %.2f, proximity: %d\n", lux, proximity);

    close(i2c_fd);
    i2c_client_free(client);

    return 0;
}

int get_timestamp() {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[32];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S.%03d", timeinfo);
    return buffer;
}

void install_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;

    sigfillset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0)
        perror("sigaction(SIGINT)");

    if (sigaction(SIGTERM, &sa, NULL) < 0)
        perror("sigaction(SIGTERM)");
}

int main(int argc, char *argv[]) {
    install_signal_handlers();

    int ret;
    ret = main(argc, argv);

    if (ret != 0) {
        fprintf(stderr, "Program exited with error.\n");
    }

    return 0;
}

