    struct i2c_client *client;
    char timestamp[20];
    time_t now;
    struct tm *local_time;
    int retries = 0;
    FILE *proximity_log = fopen(PROXIMITY_LOG_FILE, "a");

    if (proximity_log == NULL) {
        perror("Failed to open proximity log file");
        return 1;
    }

    gpioInitialise();
    ret = pigpio_init(1);
    if (ret != 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", pigpio_strerror(ret));
        return 1;
    }

    client = i2c_open(I2C_ADDRESS, 0);
    if (client == NULL) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x\n", I2C_ADDRESS);
        return 1;
    }

    // Initialise the sensor
    ret = i2cWriteByteData(client, 0x03, 0x07);
    if (ret != 2) {
        fprintf(stderr, "Failed to write to register 0x07\n");
        return 1;
    }

    ret = i2cWriteByteData(client, 0x02, 0x06);
    if (ret != 2) {
        fprintf(stderr, "Failed to write to register 0x06\n");
        return 1;
    }

    ret = i2cWriteByteData(client, 0x00, 0x1A);
    if (ret != 2) {
        fprintf(stderr, "Failed to write to register 0x1A\n");
        return 1;
    }

    ret = i2cWriteByteData(client, 0x0B, 0x21);
    if (ret != 2) {
        fprintf(stderr, "Failed to write to register 0x21\n");
        return 1;
    }

    ret = i2cWriteByteData(client, 0x00, 0x24);
    if (ret != 2) {
        fprintf(stderr, "Failed to write to register 0x24\n");
        return 1;
    }

    ret = i2cWriteByteData(client, 0x49, 0x22);
    if (ret != 2) {
        fprintf(stderr, "Failed to write to register 0x22\n");
        return 1;
    }

    ret = i2cWriteByteData(client, 0x03, 0x0C);
    if (ret != 2) {
        fprintf(stderr, "Failed to write to register 0x0C\n");
        return 1;
    }

    ret = i2cWriteByteData(client, 0x0F, 0x0F);
    if (ret != 2) {
        fprintf(stderr, "Failed to write to register 0x0F\n");
        return 1;
