    if (ret != 2) {
        fprintf(stderr, "Failed to write to register 0x0D\n");
        return 1;
    }

    ret = i2cWriteByteData(client, 0x03, 0x80);
    if (ret != 2) {
        fprintf(stderr, "Failed to write to register 0x80\n");
        return 1;
    }

