        ret = i2cReadByteData(client, 0x17, &proximity_data_high);
        if (ret != 1) {
            fprintf(stderr, "Failed to read from register 0x17\n");
            if (retries < MAX_RETRIES) {
                retries++;
                printf("Retrying... (Attempt %d of %d)\n", retries, MAX_RETRIES);
                usleep(100000); // Wait for 100ms before retry
            } else {
                fprintf(stderr, "Failed after %d retries. Exiting.\n", MAX_RETRIES);
                break;
            }
        }

        proximity_data = (proximity_data_high << 8) | proximity_data_low;

        // Append timestamp and reading to log file
        time(&now);
        local_time = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);
        fprintf(proximity_log, "%s: %04X\n", timestamp, proximity_data);

        // Sleep for a short period before the next reading
        usleep(100000); // 100ms
    }

    i2cClose(client);
    gpioTerminate();
    fclose(proximity_log);

    return 0;
}
