#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define TRIG_PULSE_WIDTH 10
#define DISTANCE_THRESHOLD 20
#define SOUND_SPEED 0.0343

void signal_handler(int signum) {
    pigpio_terminate(1);
    exit(0);
}

void setup_gpio(void) {
    if (pigpio_init() != 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    gpioSetMode(TRIGGER_PIN, PIGO_OUTPUT);
    gpioSetMode(ECHO_PIN, PIGO_INPUT);
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);
    gpioSetMode(BUZZER_PIN, PIGO_OUTPUT);
}

void echo_callback(void *data) {
    static unsigned long rising_edge_time, falling_edge_time;
    unsigned long now;

    now = pigpio_get_time();
    if (now - rising_edge_time > 10e-9) {
        falling_edge_time = now;
        rising_edge_time = now;
    }

    unsigned long pulse_width = falling_edge_time - rising_edge_time;
    double distance = pulse_width * SOUND_SPEED / 2;

    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, PIGO_HIGH);
    } else {
        gpioWrite(BUZZER_PIN, PIGO_LOW);
    }
}

int main(int argc, char *argv[]) {
    setup_gpio();

    while (1) {
        gpioDelay(100e-6);
        gpioWrite(TRIGGER_PIN, PIGO_HIGH);
        gpioDelay(TRIG_PULSE_WIDTH);
        gpioWrite(TRIGGER_PIN, PIGO_LOW);
        gpioDelay(100e-6);

        double distance = 0;
        if (echo_callback == NULL) {
            distance = 0;
        } else {
            distance = echo_callback(NULL);
        }

        printf("Distance: %.2f cm\n", distance);
        usleep(1000000);
    }

    pigpio_terminate(0);
    return 0;
}

