#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define UPDATE_INTERVAL 100

double distance = 0.0;

void handle_sigint(int sig) {
    printf("\nExiting gracefully...\n");
    pigpio_stop();
    exit(0);
}

void setup_gpio() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(TRIGGER_PIN, PIGIO_OUTPUT);
    gpioSetMode(ECHO_PIN, PIGIO_INPUT);
    gpioSetMode(SERVO_PIN, PIGIO_OUTPUT);

    gpioSetup(TRIGGER_PIN, 0);
    gpioSetup(ECHO_PIN, PIGIO_INPUT);
    gpioSetup(SERVO_PIN, PIGIO_OUTPUT);
}

double measure_distance() {
    uint32_t start_time = gpioGet(ECHO_PIN);
    gpioPulseIn(ECHO_PIN, 1000000, 2); // 5 usec pulse
    uint32_t duration = gpioGet(ECHO_PIN) - start_time;
    double frequency = (duration * 1000000) / 2; // convert to nanoseconds
    double time_of_flight = frequency / 2; // time taken for sound to travel back
    double distance_cm = time_of_flight * 34300; // speed of sound in cm/s

    if (distance_cm < 0) {
        return -1.0;
    }

    return distance_cm;
}

void control_servo(double angle) {
    double pulse_length = (angle / 180.0) * 1500.0;
    int pulse_us = (int)(pulse_length * 400000);
    gpioWrite(SERVO_PIN, PIGIO_OUTPUT, pulse_us);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_sigint);

    setup_gpio();

    while (1) {
        double new_distance = measure_distance();
        if (new_distance < 0) {
            printf("Failed to measure distance, retrying...\n");
            continue;
        }

        distance = new_distance;
        printf("Distance: %.1f cm\n", distance);

        control_servo(0); // 0 degrees (500 us pulse) at 200 cm
        usleep(UPDATE_INTERVAL * 1000 / 1000); // 100 ms delay

        control_servo(90); // 90 degrees (1500 us pulse) at 110 cm
        usleep(UPDATE_INTERVAL * 1000 / 1000);

        control_servo(180); // 180 degrees (2500 us pulse) at 20 cm
        usleep(UPDATE_INTERVAL * 1000 / 1000);
    }

    pigpioTerminate();
    return 0;
}

