This code sets up a Raspberry Pi Zero W to use the pigpio library for controlling an HC-SR04 ultrasonic sensor and an SG90 servo motor. It measures distance in centimeters and adjusts the servo's position proportionally to the distance. The program runs in a loop, updating the servo every 100 ms, and handles SIGINT (Ctrl+C) for a clean exit. It also includes error handling for pigpio initialization and echo timeout.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SERVO_GPIO 18
#define TIMING_BUDGET 10000
#define OPEN_THRESHOLD 200
#define CLOSE_THRESHOLD 250
#define OPEN_PW 1000
#define CLOSE_PW 2000
#define LOG_FILE "gate_log.txt"

void log_event(const char *event) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s: %s\n", timestamp, event);
        fclose(file);
    }
}

int main() {
    int i2c_fd, servo_gpio;
    pigpio pi;

    // Initialize pigpio
    if (pi_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open the servo GPIO
    servo_gpio = GPIO_SET_MODE(SERVO_GPIO, PI_OUTPUT);
    if (servo_gpio < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SERVO_GPIO);
        pi_terminate();
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(log_file, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (i2c_fd < 0) {
        perror("Failed to open log file");
        pi_terminate();
        return EXIT_FAILURE;
    }

    // Initialize VL53L1X sensor
    uint8_t sensor_id[2];
    if (pigpio_i2c_write(i2c_fd, I2C_ADDR, 0x01, 0x0F, sensor_id) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        close(i2c_fd);
        pi_terminate();
        return EXIT_FAILURE;
    }
    if (sensor_id[0] != 0xEA) {
        fprintf(stderr, "Sensor model ID mismatch\n");
        close(i2c_fd);
        pi_terminate();
        return EXIT_FAILURE;
    }

    if (pigpio_i2c_write(i2c_fd, I2C_ADDR, 0x00, 0x01, &TIMING_BUDGET) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        close(i2c_fd);
        pi_terminate();
        return EXIT_FAILURE;
    }

    if (pigpio_i2c_write(i2c_fd, I2C_ADDR, 0x00, 0x02, &1) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        close(i2c_fd);
        pi_terminate();
        return EXIT_FAILURE;
    }

    // Read distance from the sensor
    uint16_t distance;
    if (pigpio_i2c_read(i2c_fd, I2C_ADDR, 0x00, 0x01, &distance) < 0) {
        fprintf(stderr, "Failed to read distance\n");
        close(i2c_fd);
        pi_terminate();
        return EXIT_FAILURE;
    }

    // Control the servo gate
    if (distance < OPEN_THRESHOLD) {
        log_event("Gate opened");
        GPIO_SET_PWM_RANGE(SERVO_GPIO, 0, 1000); // 1000 us (closed)
    } else if (distance > CLOSE_THRESHOLD) {
        log_event("Gate closed");
        GPIO_SET_PWM_RANGE(SERVO_GPIO, 2000, 2000); // 2000 us (open)
    }

    // Smooth transition between open and close
    if (distance > OPEN_THRESHOLD && distance < CLOSE_THRESHOLD) {
        int t = (int)(distance - OPEN_THRESHOLD) * 1000 / (CLOSE_THRESHOLD - OPEN_THRESHOLD);
        GPIO_SET_PWM_RANGE(SERVO_GPIO, t, 2000); // Smooth transition
    }

    // Clean up and exit
    pi_terminate();
    close(i2c_fd);
    return EXIT_SUCCESS;
}

