#define REG_HUMID 0x02

void sigint_handler(int signum) {
    printf("\nReceived SIGINT, shutting down...\n");
    pigpio_stop();
    exit(0);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_begin(I2C_BUS);
    if (!pi) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    if (pigpio_init(pi) != 0) {
        printf("Failed to initialize pigpio\n");
        pigpio_stop();
        return 1;
    }

    if (pigpio_open_i2c(pi, I2C_BUS, I2C_ADDR) < 0) {
        printf("Failed to open I2C bus\n");
        pigpio_stop();
        return 1;
    }

    if (pigpio_write_i2c_mem(pi, I2C_BUS, REG_CONFIG, 0x00) < 0) {
        printf("Failed to write to CONFIG register\n");
        pigpio_close_i2c(pi);
        pigpio_stop();
        return 1;
    }

    printf("Wrote 0x00 to CONFIG register\n");
    usleep(10000); // Wait 10 ms

    if (pigpio_read_i2c_mem(pi, I2C_BUS, REG_TEMP) < 0) {
        printf("Failed to read from TEMP register\n");
        pigpio_close_i2c(pi);
        pigpio_stop();
        return 1;
    }

