    if (pigpio_read_i2c_mem(pi, I2C_BUS, REG_HUMID) < 0) {
        printf("Failed to read from HUMID register\n");
        pigpio_close_i2c(pi);
        pigpio_stop();
        return 1;
    }

    float humidity = (125.0 * (float)pigpio_read_i2c_mem(pi, I2C_BUS, REG_HUMID)) / 65536.0 - 6.0;
    printf("Humidity: %.2f %%\n", humidity);

    while (1) {
        usleep(2000000); // Wait 2 seconds
        printf("Logging readings...\n");
    }

    pigpio_close_i2c(pi);
    pigpio_stop();

    signal(SIGINT, sigint_handler);

    return 0;
}

