#define I2C_BUS 1
#define I2C_ADDR 0x68
#define REG_WHO_AM_I 0x2A
#define REG_PWR_MGMT_1 0x6B
#define REG_SAMPLE_RATE_DIV 0x19
#define REG_ACCEL_CONFIG 0x1C
#define REG_GYRO_CONFIG 0x1B
#define REG_STATUS 0x3B

void handle_sigint(int sig) {
    printf("\nShutting down...\n");
    gpioTerminate();
    exit(0);
}

void handle_sigterm(int sig) {
    printf("\nShutting down...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_fd, status;
    struct i2c_rdwr_t wr_reg;
    uint8_t reg_read[2];
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    printf("Starting MPU-6050 data logger...\n");

    pigpio_init(1); // Initialize pigpio with I2C bus 1

    wr_reg.reg = REG_WHO_AM_I;
    wr_reg.data = (uint8_t[]){0x68};
    status = pigpio_i2c_write(&wr_reg);
    if (status < 0) {
        perror("Failed to read WHO_AM_I register");
        return -1;
    }

    if (reg_read[0] != 0x68) {
        printf("MPU-6050 not found.\n");
        gpioTerminate();
        return -1;
    }

    wr_reg.reg = REG_PWR_MGMT_1;
    wr_reg.data = (uint8_t[]){0x6B};
    status = pigpio_i2c_write(&wr_reg);
    if (status < 0) {
        perror("Failed to reset MPU-6050");
        return -1;
    }

    sleep(1); // Wait for the device to stabilize

    wr_reg.reg = REG_SAMPLE_RATE_DIV;
    wr_reg.data = (uint8_t[]){0x19};
    status = pigpio_i2c_write(&wr_reg);
    if (status < 0) {
        perror("Failed to set sample rate divider");
        return -1;
    }

    wr_reg.reg = REG_ACCEL_CONFIG;
    wr_reg.data = (uint8_t[]){0x1C};
    status = pigpio_i2c_write(&wr_reg);
    if (status < 0) {
        perror("Failed to set accelerometer range");
        return -1;
    }

    wr_reg.reg = REG_GYRO_CONFIG;
    wr_reg.data = (uint8_t[]){0x1B};
    status = pigpio_i2c_write(&wr_reg);
    if (status < 0) {
        perror("Failed to set gyroscope range");
        return -1;
    }

    while (1) {
        wr_reg.reg = REG_STATUS;
        pigpio_i2c_read(&wr_reg, 14);

        if (wr_reg.status & 0x01) { // Check for error
            printf("I2C read error\n");
            continue;
        }

        accel_x = (int16_t)ntohl(wr_reg.data[2]);
        accel_y = (int16_t)ntohl(wr_reg.data[3]);
        accel_z = (int16_t)ntohl(wr_reg.data[4]);
        gyro_x = (int16_t)ntohl(wr_reg.data[6]);
        gyro_y = (int16_t)ntohl(wr_reg.data[7]);
        gyro_z = (int16_t)ntohl(wr_reg.data[8]);

        printf("Accel: X=%d, Y=%d, Z=%d, Temp=%d\n", accel_x, accel_y, accel_z, wr_reg.data[0]);
        printf("Gyro: X=%d, Y=%d, Z=%d\n", gyro_x, gyro_y, gyro_z);

        usleep(100000); // Wait for 100 ms
    }

    gpioTerminate();
    return 0;
}

