#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define READ_INTERVAL_SEC 5.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define MAX_READ_ATTEMPTS 3

void i2c_error_handler(const char *cmd) {
    fprintf(stderr, "I2C error: %s\n", cmd);
    pigpio_exitall();
}

int read_sht40_data(int channel) {
    int ret;
    unsigned char cmd[1] = {0xFD};
    unsigned char data[8];

    ret = pigpio_i2c_transfer(SHT40_ADDR, cmd, 1, channel, data, 6, 10);
    if (ret < 0) {
        fprintf(stderr, "I2C read failed: %s\n", pigpio_strerror(ret));
        return -1;
    }

    // Validate CRC-8 checksums
    unsigned char crc_temp = 0xFF;
    unsigned char crc_humidity = 0xFF;

    for (int i = 0; i < 2; i++) {
        crc_temp = (crc_temp << 8) ^ data[i];
    }

    for (int i = 0; i < 2; i++) {
        crc_humidity = (crc_humidity << 8) ^ data[i + 2];
    }

    if (crc_temp != CRC_INIT) {
        fprintf(stderr, "CRC-temp failed\n");
        return -1;
    }

    if (crc_humidity != CRC_INIT) {
        fprintf(stderr, "CRC-humidity failed\n");
        return -1;
    }

    // Convert raw values
    int raw_temp = ((data[0] << 8) | data[1]) * 175 / 65535 - 45;
    int raw_humidity = ((data[2] << 8) | data[3]) * 125 / 65535 - 6;

    // Clamp values to 0-100%
    raw_temp = (raw_temp < 0) ? 0 : (raw_temp > 100) ? 100 : raw_temp;
    raw_humidity = (raw_humidity < 0) ? 0 : (raw_humidity > 100) ? 100 : raw_humidity;

    return raw_temp;
}

void read_sensor(int channel) {
    int attempts = 0;
    int raw_temp;

    while (attempts < MAX_READ_ATTEMPTS) {
        raw_temp = read_sht40_data(channel);
        if (raw_temp != -1) {
            printf("Temperature: %d°C, Humidity: %d%%\n", raw_temp, raw_temp);
            attempts = MAX_READ_ATTEMPTS;
        } else {
            attempts++;
            usleep(100000); // Wait 100 ms before retry
        }
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, i2c_error_handler);
    signal(SIGTERM, i2c_error_handler);

    int i2c_channel = pigpio_i2c_init(I2C_BUS);
    if (i2c_channel < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return EXIT_FAILURE;
    }

    while (1) {
        read_sensor(i2c_channel);
        usleep(50000000); // Sleep for 5 seconds
    }

    pigpio_i2c_cleanup(i2c_channel);
    return EXIT_SUCCESS;
}

