#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MLX90614_ADDRESS 0x5A
#define AMBIENT_REG 0x06
#define OBJECT_REG 0x07
#define LOG_FILE "temperature_log.csv"

#define BUFFER_SIZE 1024
char buffer[BUFFER_SIZE];

void log_reading(const char *timestamp, int ambient, int object) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s,%.1f,%.1f\n", timestamp, ambient, object);
    fclose(file);
}

void* read_sensor(void *arg) {
    int fd;
    struct i2c_client *client;
    int ambient_temp, object_temp;

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return NULL;
    }

    client = i2c_alloc(fd);
    if (!client) {
        close(fd);
        perror("Failed to allocate i2c client");
        return NULL;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDRESS) < 0) {
        i2c_free(client);
        close(fd);
        perror("Failed to set I2C slave address");
        return NULL;
    }

    ambient_temp = 0;
    object_temp = 0;

    if (read(client, buffer, 2) != 2) {
        i2c_free(client);
        close(fd);
        perror("Failed to read from sensor");
        return NULL;
    }

    ambient_temp = (buffer[0] << 8) | buffer[1];
    object_temp = (buffer[2] << 8) | buffer[3];

    log_reading(get_timestamp(), ambient_temp, object_temp);

    i2c_free(client);
    close(fd);

    return NULL;
}

int main(int argc, char *argv[]) {
    pthread_t thread;
    int ret;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interval_seconds>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    ret = pthread_create(&thread, NULL, read_sensor, NULL);
    if (ret != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    while (1) {
        usleep(1000000 * atoi(argv[1]));
    }

    pthread_join(thread, NULL);

    log_reading(get_timestamp(), 0, 0); // Log final reading

    return 0;
}

int get_timestamp(char *timestamp, int len) {
    time_t now = time(NULL);
    strftime(timestamp, len, "%Y-%m-%d %H:%M:%S", localtime(&now));
    return 0;
}

