#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"

void handle_signal(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    close(logfd_temp);
    close(logfd_error);
    pigpio_terminate(1);
    exit(signum);
}

int main() {
    int logfd_temp, logfd_error;
    char log_temp_msg[100], log_error_msg[100];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    logfd_temp = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd_temp == -1) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    logfd_error = open(ERROR_LOG, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd_error == -1) {
        perror("Error opening error log file");
        close(logfd_temp);
        return EXIT_FAILURE;
    }

    pigpio_init(1); // Initialize pigpio with 1 as the number of available pins (I2C bus 1)

    while (1) {
        int status = pigpio_begin_i2c(I2C_BUS, I2C_ADDR);
        if (status < 0) {
            snprintf(log_error_msg, sizeof(log_error_msg), "I2C communication error: %s", pigpio_strerror(status));
            write(logfd_error, log_error_msg, strlen(log_error_msg));
            continue;
        }

        int status_temp = pigpio_i2c_transfer2(logfd_temp, 0, 1, 0, 0x4A, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
        if (status_temp < 0) {
            snprintf(log_error_msg, sizeof(log_error_msg), "Error reading temperature from STS30-DIS: %s", pigpio_strerror(status_temp));
            write(logfd_error, log_error_msg, strlen(log_error_msg));
            continue;
        }

        // Assuming the temperature is returned in the first byte of the response
        int temp_raw = read(logfd_temp, &status_temp, 1);
        if (temp_raw != 1) {
            snprintf(log_error_msg, sizeof(log_error_msg), "Error reading temperature: Invalid data received");
            write(logfd_error, log_error_msg, strlen(log_error_msg));
            continue;
        }

        // Convert raw temperature to Celsius (assuming the sensor returns temperature in LSB)
        int temp_c = temp_raw * 0.029; // Conversion factor based on sensor datasheet

        // Log temperature and timestamp
        time_t now = time(NULL);
        strftime(log_temp_msg, sizeof(log_temp_msg), "%Y-%m-%d %H:%M:%S", localtime(&now));
        write(logfd_temp, log_temp_msg, strlen(log_temp_msg));
        write(logfd_temp, &temp_c, sizeof(int));
        write(logfd_temp, "\n", 1);

        usleep(5000000); // Wait for 5 seconds
    }

    close(logfd_temp);
    close(logfd_error);
    pigpio_terminate(1);
    return EXIT_SUCCESS;
}

