#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define SENSOR_ADDRESS 0x25
#define I2C_BUS 1
#define LOG_FILE "pressure_log.csv"
#define CHECK_INTERVAL_SECS 1.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

void log_to_csv(const char *timestamp, double pressure, double temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(file);
}

void send_command(int pin, uint8_t command) {
    if (pigpio_write_i2c_data(SENSOR_ADDRESS, I2C_BUS, 0x01, command) < 0) {
        perror("Failed to send command");
        exit(EXIT_FAILURE);
    }
}

void read_data(uint8_t *data) {
    if (pigpio_read_i2c_data(SENSOR_ADDRESS, I2C_BUS, 0x02, data, 9) < 0) {
        perror("Failed to read data");
        exit(EXIT_FAILURE);
    }
}

int validate_crc(uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc = (crc << 8) ^ data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc = crc << 1;
            }
        }
    }
    return crc == CRC_INIT;
}

int main(int argc, char *argv[]) {
    int sensor_pin = 0;
    pigpio_init(1); // Initialize pigpio with I2C bus 1

    if (pigpio_setup_i2c(SENSOR_ADDRESS, I2C_BUS) < 0) {
        perror("Failed to setup I2C bus");
        exit(EXIT_FAILURE);
    }

    send_command(sensor_pin, 0x36); // Send command to start continuous measurement
    usleep(100000); // Wait at least 1 ms

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_file = fopen(LOG_FILE, "w");
        if (!log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(&ts.tv_sec));
    log_to_csv(timestamp, 0.0, 0.0); // Write header if file is new

    while (1) {
        uint8_t data[9];
        read_data(data);

        if (!validate_crc(data, 9)) {
            fprintf(stderr, "CRC validation failed, sensor may be absent or there's a bus error.\n");
            break;
        }

        double pressure = (data[2] << 8) | data[3];
        double temperature = (data[4] << 8) | data[5];
        double scale_factor = (data[6] << 8) | data[7];

        pressure *= scale_factor / 1000.0; // Convert to Pa
        temperature = (data[8] << 8) | data[9];
        temperature /= 10.0; // Convert to °C

        log_to_csv(timestamp, pressure, temperature);

        usleep(CHECK_INTERVAL_SECS * 1e6); // Sleep for CHECK_INTERVAL_SECS ms
    }

    pigpio_terminate(1); // Terminate pigpio
    fclose(log_file);
    remove(LOG_FILE); // Clean up log file on exit

    return 0;
}

