#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/epoll.h>
#include <time.h>

#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define TRIG_COMMAND 0x21
#define TRIG_COMMAND_LEN 2
#define DATA_SIZE 6
#define LOG_FILE "airflow.log"
#define RETRY_ATTEMPTS 3
#define INITIAL_BACKOFF_MS 100
#define BACKOFF_FACTOR 2

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    global_data.exit_flag = 1;
}

void sigterm_handler(int sig) {
    global_data.exit_flag = 1;
}

void sig_handler(int sig) {
    global_data.exit_flag = 1;
}

void init_pigpio() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }
}

void terminate_pigpio() {
    pigpioTerminate();
}

void init_i2c() {
    global_data.i2c_fd = i2cOpen(I2C_BUS, SDP31_ADDR);
    if (global_data.i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return;
    }
}

void close_i2c() {
    i2cClose(global_data.i2c_fd);
}

void log_sample(const char *timestamp, double pressure_pa, double temperature_c) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp_str[80];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", local_time);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp_str, pressure_pa, temperature_c);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    global_data.exit_flag = 0;
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);
    signal(SIGUSR1, sig_handler);

    init_pigpio();
    init_i2c();

    while (!global_data.exit_flag) {
        int retries = 0;
        uint8_t command[TRIG_COMMAND_LEN] = {TRIG_COMMAND, 0x96};
        uint8_t data[DATA_SIZE];

        while (retries < RETRY_ATTEMPTS) {
            if (i2cWrite(global_data.i2c_fd, command, TRIG_COMMAND_LEN) < 0) {
                int delay_ms = INITIAL_BACKOFF_MS * pow(BACKOFF_FACTOR, retries);
                usleep(delay_ms * 1000);
                retries++;
            } else {
                if (i2cRead(global_data.i2c_fd, data, DATA_SIZE) < 0) {
                    int delay_ms = INITIAL_BACKOFF_MS * pow(BACKOFF_FACTOR, retries);
                    usleep(delay_ms * 1000);
                    retries++;
                } else {
                    break;
                }
            }
        }

        if (retries == RETRY_ATTEMPTS) {
            fprintf(stderr, "Failed to communicate with SDP31 after %d retries\n", RETRY_ATTEMPTS);
            continue;
        }

        double raw_pressure = (data[0] << 8) | data[1];
        double raw_temperature = (data[2] << 8) | data[3];
        double crc = (data[4] << 8) | data[5];

        double pressure_pa = (raw_pressure / 60.0);
        double temperature_c = (raw_temperature / 200.0);

        log_sample(ctime(NULL), pressure_pa, temperature_c);

        usleep(100000); // Sleep for 100 ms
    }

    close_i2c();
    terminate_pigpio();
    return 0;
}

