#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define SAMPLE_INTERVAL 5000 // 5 seconds

void log_and_print_reading(double temperature, double humidity) {
    time_t now = time(NULL);
    char timestamp[80];
    sprintf(timestamp, "%0.2f %0.2f", now, (double)now / 3600.0); // HH:MM:SS
    FILE *file = fopen("sensor_data.txt", "a");
    if (file) {
        fprintf(file, "%s: %f °C, %f %%RH\n", timestamp, temperature, humidity);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open sensor_data.txt for appending.\n");
    }
    printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n", temperature, humidity);
}

int main() {
    int i2c_fd;
    int ret;

    // Initialize pigpio
    if ((ret = pigpio_init()) != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return 1;
    }

    // Open I2C bus
    if ((ret = pigpio_i2c_open(I2C_BUS, I2C_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        pigpio_terminate();
        return 1;
    }

    // Read temperature
    double temperature = 0.0;
    ret = pigpio_i2c_write_byte(i2c_fd, 0xF3);
    if (ret < 0) {
        fprintf(stderr, "Failed to write command byte: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_fd);
        pigpio_terminate();
        return 1;
    }

    while (pigpio_i2c_poll(i2c_fd, 2) < 0) {
        if (pigpio_error()) {
            fprintf(stderr, "I2C poll failed: %s\n", pigpio_error());
            pigpio_i2c_close(i2c_fd);
            pigpio_terminate();
            return 1;
        }
        // Retry on transient I2C failures
    }

    ret = pigpio_i2c_read_byte(i2c_fd);
    if (ret < 0) {
        fprintf(stderr, "Failed to read temperature data: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_fd);
        pigpio_terminate();
        return 1;
    }

    temperature = ((double)ret * 175.72) / 65536.0 - 46.85;
    log_and_print_reading(temperature, 0.0);

    // Read humidity
    double humidity = 0.0;
    ret = pigpio_i2c_write_byte(i2c_fd, 0xF5);
    if (ret < 0) {
        fprintf(stderr, "Failed to write command byte: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_fd);
        pigpio_terminate();
        return 1;
    }

    while (pigpio_i2c_poll(i2c_fd, 2) < 0) {
        if (pigpio_error()) {
            fprintf(stderr, "I2C poll failed: %s\n", pigpio_error());
            pigpio_i2c_close(i2c_fd);
            pigpio_terminate();
            return 1;
        }
        // Retry on transient I2C failures
    }

    ret = pigpio_i2c_read_byte(i2c_fd);
    if (ret < 0) {
        fprintf(stderr, "Failed to read humidity data: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_fd);
        pigpio_terminate();
        return 1;
    }

    humidity = ((double)ret * 125.0) / 65536.0 - 6.0;
    log_and_print_reading(temperature, humidity);

    // Wait for next sample
    usleep(SAMPLE_INTERVAL * 1000000 / 1000);

    // Handle SIGINT (Ctrl+C)
    if (SIGINT == signal(SIGINT)) {
        fprintf(stderr, "Received SIGINT, closing I2C handle and terminating.\n");
        pigpio_i2c_close(i2c_fd);
        pigpio_terminate();
        return 0;
    }

    return 0;
}

