#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <time.h>

#define SENSOR_ADDRESS 0x25
#define I2C_BUS_NUMBER 1
#define LOG_FILE "airflow_data.txt"
#define LOG_INTERVAL_MS 100
#define LOG_HEADER "timestamp,pressure(Pa),temperature(°C)"

#define CRC_CHECK_SIZE 1

static int open_i2c_device(const char *path) {
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        perror("open_i2c_device");
        return -1;
    }
    return fd;
}

static int close_i2c_device(int fd) {
    close(fd);
    return 0;
}

static int write_i2c_device(int fd, const void *buf, size_t count, unsigned long flags) {
    return write(fd, buf, count, flags);
}

static int read_i2c_device(int fd, void *buf, size_t count, unsigned long flags) {
    return read(fd, buf, count, flags);
}

static int read_pressure_temperature_scale(int fd) {
    unsigned char command[1];
    command[0] = 0x36;
    write_i2c_device(fd, command, 1);

    unsigned char buffer[9];
    memset(buffer, 0, sizeof(buffer));

    write_i2c_device(fd, "00000000", 1); // Trigger measurement
    usleep(45000); // Wait approximately 45 ms

    read_i2c_device(fd, buffer, 9, 0);

    // Validate CRC-8 checksums
    if (buffer[0] & 0x01) {
        printf("Pressure CRC failed\n");
        return -1;
    }
    if (buffer[3] & 0x01) {
        printf("Temperature CRC failed\n");
        return -1;
    }
    if (buffer[6] & 0x01) {
        printf("Scale factor CRC failed\n");
        return -1;
    }

    // Convert raw pressure to Pa
    long pressure = (long)buffer[1] << 8 | buffer[2];
    long scale_factor = (long)buffer[4] << 8 | buffer[5];
    long pressure_pa = pressure / scale_factor;

    // Convert raw temperature to °C
    long temperature = (long)buffer[7] << 8 | buffer[8];
    double celsius = (temperature / 200.0) - 45.0;

    // Log data
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return -1;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%.1f,%.1f\n", now, pressure_pa, celsius);
    fclose(log_file);

    return 0;
}

int main() {
    int i2c_fd = open_i2c_device("/dev/i2c-1");
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        int result = read_pressure_temperature_scale(i2c_fd);
        if (result < 0) {
            break;
        }
    }

    close_i2c_device(i2c_fd);
    return EXIT_SUCCESS;
}

