#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define SHT40_ADDRESS 0x44
#define SHT40_COMMAND 0xFD
#define SHT40_READ_DELAY 8500
#define SHT40_LOG_INTERVAL 5000

#define LOG_FILE "sht40_log.txt"

void log_reading(int temperature, int humidity) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%d:%02d:%02d  T=%d, H=%d\n",
        now / 3600, (now % 3600) / 60, now % 60, temperature, humidity);
    fclose(log_file);
}

int read_sht40(int fd) {
    char buffer[7];
    ssize_t bytes_read = read(fd, buffer, 6);
    if (bytes_read != 6) {
        perror("Failed to read from I2C device");
        return -1;
    }

    uint8_t t_msb = buffer[0];
    uint8_t t_lsb = buffer[1];
    uint8_t t_crc = buffer[2];
    uint8_t r_msb = buffer[3];
    uint8_t r_lsb = buffer[4];
    uint8_t r_crc = buffer[5];

    uint16_t raw_temp = (t_msb << 8) | t_lsb;
    uint8_t crc_temp = t_crc ^ (raw_temp >> 8);
    uint16_t raw_humidity = (r_msb << 8) | r_lsb;
    uint8_t crc_humidity = r_crc ^ (raw_humidity >> 8);

    if (crc32(buffer, 6) != crc_temp) {
        fprintf(stderr, "CRC-8 failed for temperature\n");
        return -1;
    }

    if (crc32(buffer + 6, 2) != crc_humidity) {
        fprintf(stderr, "CRC-8 failed for humidity\n");
        return -1;
    }

    int temperature = -45 + 175 * (raw_temp / 65535);
    int humidity = 100 * (raw_humidity / 65535);

    log_reading(temperature, humidity);

    return 0;
}

int main() {
    int fd, ret;
    char buffer[256];

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, I2C_SLAVE, SHT40_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = read(fd, buffer, sizeof(buffer));
        if (ret < 0) {
            perror("Failed to read from I2C device");
            break;
        }

        if (ret == 0) {
            fprintf(stderr, "No device found at address 0x%02x\n", SHT40_ADDRESS);
            break;
        }

        read_sht40(fd);

        usleep(SHT40_READ_DELAY * 1000);
    }

    close(fd);
    fclose(stdout);

    return 0;
}

