#define CONTINUOUS_COMMAND 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "airflow_data.txt"
#define BUFFER_SIZE 1024

int open_i2c_device(const char *bus, int device) {
    int fd;
    char *buf = (char *)malloc(BUFFER_SIZE);
    if (buf == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    fd = open(bus, O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        free(buf);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, device) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        free(buf);
        return -1;
    }

    return fd;
}

int write_i2c_command(int fd, uint8_t *command, size_t len) {
    return write(fd, command, len);
}

int read_i2c_data(int fd, uint8_t *buffer, size_t len) {
    return read(fd, buffer, len);
}

int validate_crc(const uint16_t *data, const uint8_t *crc_init) {
    uint16_t crc = crc_init;
    for (int i = 0; i < 2; ++i) {
        crc = (crc << 8) ^ data[i];
    }
    return crc == 0;
}

int main(int argc, char *argv[]) {
    int fd, ret;
    uint8_t command[1];
    uint16_t pressure_msb, pressure_lsb, temperature_msb, temperature_lsb;
    uint16_t raw_pressure, raw_temperature;
    struct timespec start_time, end_time;
    char timestamp[32];

    fd = open_i2c_device("/dev/i2c-1", SENSOR_ADDRESS);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    command[0] = CONTINUOUS_COMMAND;
    ret = write_i2c_command(fd, command, 1);
    if (ret < 0) {
        perror("Failed to write command");
        close(fd);
        return EXIT_FAILURE;
    }

    ret = read_i2c_data(fd, buffer, 6);
    if (ret < 0) {
        perror("Failed to read data");
        close(fd);
        return EXIT_FAILURE;
    }

    raw_pressure = (buffer[0] << 8) | buffer[1];
    raw_temperature = (buffer[2] << 8) | buffer[3];

    if (!validate_crc((uint16_t*)&raw_pressure, CRC_INIT)) {
        fprintf(stderr, "CRC validation failed for pressure\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!validate_crc((uint16_t*)&raw_temperature, CRC_INIT)) {
        fprintf(stderr, "CRC validation failed for temperature\n");
        close(fd);
        return EXIT_FAILURE;
    }

    raw_pressure *= 240;
    raw_temperature += 200 - 45;

    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now.tv_sec));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "%s, %d, %d\n", timestamp, raw_pressure, raw_temperature);
    fclose(log_file);

    close(fd);

    return EXIT_SUCCESS;
}

