    for (i = 0; i < log_index; i++) {
        fprintf(stdout, "Timestamp: %ld, Temperature: %.2f °C, Humidity: %.2f %%\n",
                log_buffer[i].timestamp, log_buffer[i].temperature, log_buffer[i].humidity);
    }
}

int init_pigpio() {
    int fd = pigpio_open();
    if (fd < 0) {
        fprintf(stderr, "Failed to open pigpio: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

int setup_i2c() {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpio_close(fd);
        return -1;
    }

    fdpiod_set_i2c_bus(fd, I2C_BUS);
    fdpiod_set_i2c_address(fd, I2C_ADDR);

    if (pigpio_i2c_setup(fd) < 0) {
        fprintf(stderr, "Failed to setup I2C: %s\n", strerror(errno));
        close(fd);
        pigpio_close(fdpiod_get_fd());
        return -1;
    }

    return fd;
}

int setup_fan() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO: %s\n", strerror(errno));
        return -1;
    }
    gpioSetMode(FAN_GPIO, GPIO_OUTPUT);
    gpioWrite(FAN_GPIO, FAN_OFF);
    return 0;
}

int read_sensor_data(int fd, int cmd, int *raw_temp, int *raw_humidity) {
    int retries = 3;
    int response_size = 2;
    unsigned char command[2] = {cmd, 0};
    unsigned char response[response_size];

    for (int i = 0; i < retries; i++) {
        if (pigpio_i2c_write(fd, command, 2) < 0) {
            fprintf(stderr, "Failed to write to I2C: %s\n", strerror(errno));
            continue;
        }

        if (pigpio_i2c_read(fd, response, response_size) < 0) {
            fprintf(stderr, "Failed to read from I2C: %s\n", strerror(errno));
            continue;
        }

        *raw_temp = response[0];
        *raw_humidity = response[1];

        if (response[0] == 0x7F && response[1] == 0x00) {
            return 1; // Sensor detected
        }

        usleep(10000); // Wait 10 ms
    }

    fprintf(stderr, "Failed to read from sensor after %d retries\n", retries);
    return 0;
}

int process_sensor_data(int raw_temp, int raw_humidity) {
    float temperature = 175.72 * raw_temp / 65536.0 - 46.85;
    float humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, FAN_ON);
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, FAN_OFF);
    }

    log_entry(temperature, humidity);
    return 1;
}

