    int i2c_fd = setup_i2c();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    int gpio_fd = init_pigpio();
    if (gpio_fd < 0) {
        pigpio_close(i2c_fd);
        return EXIT_FAILURE;
    }

    int gpio_result = setup_fan();
    if (gpio_result < 0) {
        pigpio_close(i2c_fd);
        pigpio_close(gpio_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int raw_temp, raw_humidity;
        if (read_sensor_data(i2c_fd, I2C_CMD_TEMP, &raw_temp, &raw_humidity) == 1) {
            process_sensor_data(raw_temp, raw_humidity);
        }

        usleep(LOG_INTERVAL_SEC * 1000000); // Wait for LOG_INTERVAL_SEC seconds
    }

    print_log();

    gpioTerminate();
    pigpio_close(gpio_fd);
    pigpio_close(i2c_fd);

    return EXIT_SUCCESS;
}

