#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>

#define SCD_ADDR 0x62
#define I2C_BUS 1
#define I2C_FREQ 100000
#define START_PERIODIC_COMMAND 0x21B1
#define DATA_READY_FLAG 0xE4B8
#define READ_DATA_COMMAND 0xEC05
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "air_quality.log"

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_client *client;
    char log_msg[100];

    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(I2C_BUS, 0);
    if (!client) {
        fprintf(stderr, "Failed to create I2C client: %s\n", strerror(errno));
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    ret = i2c_open_device(client, SCD_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to open SCD40: %s\n", strerror(errno));
        i2c_client_free(client);
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    // Send Start Periodic Measurement command
    ret = i2c_write_byte(client, START_PERIODIC_COMMAND);
    if (ret < 0) {
        fprintf(stderr, "Failed to send Start Periodic Measurement command: %s\n", strerror(errno));
        i2c_close(client);
        i2c_client_free(client);
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    // Wait at least 1 second
    usleep(1000000);

    // Poll the data-ready flag
    ret = i2c_read_byte(client, DATA_READY_FLAG);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data-ready flag: %s\n", strerror(errno));
        i2c_close(client);
        i2c_client_free(client);
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    while (ret & (1 << DATA_READY_FLAG)) {
        ret = i2c_read_byte(client, READ_DATA_COMMAND);
        if (ret < 0) {
            fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
            i2c_close(client);
            i2c_client_free(client);
            close(i2c_fd);
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }

        for (int i = 0; i < 9; i++) {
            int data_word = (ret & 0x3F) << 8 | (ret & 0x3F);
            if (i2c_read_byte(client, data_word) < 0) {
                fprintf(stderr, "Failed to read data word: %s\n", strerror(errno));
                i2c_close(client);
                i2c_client_free(client);
                close(i2c_fd);
                pigpio_terminate();
                exit(EXIT_FAILURE);
            }

            int crc = 0;
            for (int j = 0; j < 8; j++) {
                crc = (crc << 1) ^ (data_word & 1);
                data_word >>= 1;
            }

            if (crc != (data_word & CRC_INIT)) {
                fprintf(stderr, "CRC check failed for data word: %d\n", data_word);
                i2c_close(client);
                i2c_client_free(client);
                close(i2c_fd);
                pigpio_terminate();
                exit(EXIT_FAILURE);
            }

            int raw_value = data_word & 0x3F;
            int temperature = -45 + 175 * raw_value / (2147483647 - 1);
            int humidity = 100 * raw_value / (2147483647 - 1);

            // Log data
            time_t now = time(NULL);
            sprintf(log_msg, ",%d,%.2f,%.1f,%.1f\n", now, raw_value, temperature, humidity);
            write(i2c_fd, log_msg, strlen(log_msg));
        }
    }

    // Stop Periodic Measurement command
    ret = i2c_write_byte(client, 0x3F86);
    if (ret < 0) {
        fprintf(stderr, "Failed to send Stop Periodic Measurement command: %s\n", strerror(errno));
        i2c_close(client);
        i2c_client_free(client);
        close(i2c_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    i2c_close(client);
    i2c_client_free(client);
    close(i2c_fd);
    pigpio_terminate();

    return 0;
}

