#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define BUFFER_SIZE 20
#define CO2_THRESHOLD 1000
#define INTERVAL_SEC 5

typedef struct {
    uint8_t data[9];
    int index;
} SensorData;

SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;

void init_pigpio() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }
}

int init_i2c() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        pigpioInitialise();
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, 0x62) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(file);
        pigpioInitialise();
        exit(EXIT_FAILURE);
    }

    return file;
}

void stop_sensor() {
    write(1, "stop_periodic_measurement\n", 26);
}

void log_data(SensorData data) {
    if (buffer_index < BUFFER_SIZE) {
        memcpy(buffer[buffer_index].data, data.data, 9);
        buffer_index++;
    } else {
        printf("Buffer full, discarding old data\n");
    }
}

void print_data() {
    for (int i = 0; i < buffer_index; i++) {
        if (buffer[i].index != -1) {
            printf("CO2: %d, Temp: %d, Humidity: %d\n",
                    buffer[i].data[0], buffer[i].data[1], buffer[i].data[2]);
            free(buffer[i].data);
            buffer[i].index = -1;
        }
    }
}

void check_sensor_status() {
    if (write(1, "start_periodic_measurement\n", 26) < 0) {
        fprintf(stderr, "Failed to send start command\n");
        return;
    }

    while (1) {
        if (read(1, &buffer[buffer_index - 1].index, 1) < 1) {
            fprintf(stderr, "Failed to read index\n");
            break;
        }

        if (buffer[buffer_index - 1].index == 0) {
            continue;
        }

        if (read(1, buffer[buffer_index].data, 9) < 9) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        for (int i = 0; i < 9; i += 2) {
            if (buffer[buffer_index - 1].data[i] & 0x80) {
                break;
            }

            if (buffer[buffer_index - 1].data[i] & 0x40) {
                fprintf(stderr, "CRC error in data word\n");
                break;
            }

            if (buffer[buffer_index - 1].data[i] & 0x20) {
                fprintf(stderr, "Temperature error in data word\n");
                break;
            }

            if (buffer[buffer_index - 1].data[i] & 0x10) {
                fprintf(stderr, "Humidity error in data word\n");
                break;
            }

            if (buffer[buffer_index - 1].data[i] & 0x08) {
                fprintf(stderr, "CO2 error in data word\n");
                break;
            }
        }

        if (buffer[buffer_index - 1].data[8] & 0x80) {
            break;
        }

        log_data(buffer[buffer_index - 1]);
        print_data();

        if (buffer[buffer_index - 1].data[0] > CO2_THRESHOLD) {
            digitalWrite(17, HIGH);
        }

        buffer[buffer_index - 1].index = -1;
        buffer_index--;
    }
}

int main() {
    init_pigpio();
    int i2c_file = init_i2c();

    if (i2c_file < 0) {
        pigpioInitialise();
        return EXIT_FAILURE;
    }

    start_periodic_measurement(0x21B1);
    while (1) {
        check_sensor_status();
        usleep(INTERVAL_SEC * 1000000);
    }

    stop_sensor();
    close(i2c_file);
    pigpioTerminate();

    return EXIT_SUCCESS;
}
```

This code initializes pigpio and I2C, sets up a circular buffer for logging sensor data, and continuously reads data from the SCD40 sensor. It validates CRC-8 checksums, handles sensor-absent or bus-error paths, and turns on an LED when CO2 exceeds the threshold. The measurement interval is 5 seconds, and the program gracefully shuts down on SIGINT/SIGTERM signals.

