#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 7
#define SAMPLE_INTERVAL_MS 5000
#define MAX_READINGS 100
#define ERROR_THRESHOLD 3

typedef struct {
    time_t timestamp;
    float temperature;
} LogEntry;

static LogEntry logEntries[MAX_READINGS];
static int logFileHandle = -1;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(logFileHandle);
        pigpio_terminate();
        exit(0);
    }
}

void init_pigpio() {
    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void setup_gpio(int pin) {
    if (gpioSetup(pin, PIGGPIO_OUTPUT) < 0) {
        perror("Failed to set GPIO pin as output");
        exit(EXIT_FAILURE);
    }
}

float read_temperature() {
    static int high_count = 0;
    static time_t last_timestamp = 0;
    static bool is_valid_reading = false;

    time_t current_timestamp = millis();
    double elapsed_ms = (current_timestamp - last_timestamp) * 1000;

    if (elapsed_ms >= SAMPLE_INTERVAL_MS) {
        last_timestamp = current_timestamp;
        high_count = 0;
        is_valid_reading = true;

        // Wait for a transition on GPIO4
        int transition_detected = gpioWaitTransition(GPIO_PIN);
        if (transition_detected == -1) {
            return -1.0; // Sensor absent or stuck line
        }

        // Measure high pulse width (TH) and total cycle width (TL)
        int tl = elapsed_ms;
        int th = tl - high_count;

        // Convert to temperature
        float temperature = 4215 - (2143 * th / tl);

        // Check for errors
        if (temperature < -40.0 || temperature > 150.0) {
            printf("Error: Temperature out of range\n");
            return -1.0;
        }

        // Log the reading
        LogEntry entry;
        entry.timestamp = current_timestamp;
        entry.temperature = temperature;
        if (logFileHandle == -1) {
            logFileHandle = open("temperature_log.txt", "a");
            if (logFileHandle == -1) {
                perror("Failed to open log file");
                exit(EXIT_FAILURE);
            }
        }
        fprintf(logFileHandle, "%s,%f\n", iso8601(current_timestamp), temperature);

        // Check for sensor malfunction
        if (is_valid_reading && high_count >= ERROR_THRESHOLD) {
            LogEntry errorEntry;
            errorEntry.timestamp = current_timestamp;
            errorEntry.temperature = -1.0;
            fprintf(logFileHandle, "%s,%f\n", iso8601(current_timestamp), errorEntry.temperature);
            is_valid_reading = false;
            high_count = 0;
        }

        return temperature;
    }
    return -1.0;
}

int main() {
    init_pigpio();
    setup_gpio(GPIO_PIN);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        float temp = read_temperature();
        if (temp == -1.0) {
            break;
        }
    }

    pigpio_terminate();
    close(logFileHandle);
    return 0;
}

