#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define READ_CMD 0x24
#define WRITE_CMD 0x00
#define CRC_CHECK 1
#define RETRY_COUNT 3
#define RETRY_DELAY 1000000  // 1 second in microseconds
#define LOG_INTERVAL 5000000  // 5 seconds in microseconds
#define LOG_FILE "environmental_data.txt"

#define TEMP_OFFSET 2.0
#define RH_OFFSET 5.0

void log_data(double temperature, double rh) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02dT%02d:%02d:%02dZ",
            time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, %f, %f\n", time_str, temperature, rh);
    fclose(log_file);
}

int read_sht35_data(int *temperature, int *rh) {
    int ret = 0;
    int i = 0;

    while (ret == 0 && i < RETRY_COUNT) {
        *temperature = 0;
        *rh = 0;

        pigpio_init(I2C_BUS);
        if (pigpio_open_i2c(SHT35_ADDR) < 0) {
            perror("Failed to open I2C bus");
            ret = -1;
            continue;
        }

        pigpio_write_byte_range(SHT35_ADDR, WRITE_CMD, 0x00);
        pigpio_write_byte_range(SHT35_ADDR, READ_CMD, 0x24);
        pigpio_delay_us(15000);

        ret = pigpio_read_byte_range(SHT35_ADDR, 6, *temperature, *rh);
        if (ret < 0) {
            perror("I2C read failed");
            ret = -1;
            continue;
        }

        if (crc32(*temperature, 0) != 0xFFFF) {
            fprintf(stderr, "CRC check failed for temperature\n");
            ret = -1;
            continue;
        }

        if (crc32(*rh, 0) != 0xFFFF) {
            fprintf(stderr, "CRC check failed for humidity\n");
            ret = -1;
            continue;
        }

        *temperature = (*temperature * 100) / 1000.0;
        *rh = (*rh * 100) / 100.0;

        // Simulate sinusoidal offset
        *temperature += TEMP_OFFSET * sin((double)i / 3600.0);
        *rh += RH_OFFSET * sin((double)i / 3600.0);

        i++;
    }

    pigpio_close_i2c();
    pigpio_terminate();

    return ret;
}

int main(int argc, char *argv[]) {
    int temperature, rh;

    while (1) {
        int ret = read_sht35_data(&temperature, &rh);
        if (ret == -1) {
            log_data(NAN, NAN);
        } else {
            log_data(temperature, rh);
        }

        usleep(LOG_INTERVAL);
    }

    return 0;
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    pigpio_terminate();
    fclose(stdout);
    fclose(stderr);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    exit(0);
}

int main_signal_handler(int signum) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    return main(argc, argv);
}

int main(int argc, char *argv[]) {
    return main_signal_handler(argc, argv);
}

