This code sets up a Raspberry Pi 4 Model B to read temperature and humidity from a Sensirion SHT35-DIS-B sensor using the pigpio library over I2C bus 1 at address 0x44. It uses the high-repeatability, clock-stretching-disabled measurement command (0x24, 0x00) and waits 15 ms before reading the 6-byte result. It validates the 8-bit CRC for both the temperature and humidity words, retrying up to 3 times with a 1-second delay if the CRC fails or the I2C read/write fails. If all retries fail, it logs NaN values. The raw values are converted to degrees Celsius and %RH using the standard Sensirion formulas, and a simulated sinusoidal offset (±2 °C, ±5 %RH) is added over a 1-hour period to the actual readings. Data is logged in ISO-8601 UTC format to 'environmental_data.txt' every 5 seconds. The code includes robust error handling for pigpio initialization, I2C open/read/write, and file open. It also handles SIGINT and SIGTERM for graceful shutdown, closing the I2C handle, flushing and closing the log file, and terminating pigpio cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define COMMAND 0x362F
#define CONVERSION_TIME 45000 // 45 ms in microseconds
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

#define LOG_FILE "airflow.csv"

typedef struct {
    int fd;
    struct i2c_client *client;
} I2C_Context;

void *read_sensor_data(void *arg) {
    I2C_Context *ctx = (I2C_Context *)arg;
    unsigned char data[9];
    int crc, pressure, temperature;
    long timestamp;

    // Open I2C bus
    ctx->fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (ctx->fd == -1) {
        perror("Error opening log file");
        return NULL;
    }

    ctx->client = i2c_open(ctx->fd, I2C_BUS);
    if (ctx->client == NULL) {
        perror("Error opening I2C bus");
        close(ctx->fd);
        return NULL;
    }

    // Send command and wait for conversion
    if (ioctl(ctx->fd, I2C_SLAVE, SDP810_ADDR) == -1 ||
        ioctl(ctx->fd, I2C_MEM_READ, &COMMAND) == -1 ||
        ioctl(ctx->fd, I2C_MEM_READ, data) == -1) {
        perror("Error communicating with sensor");
        close(ctx->fd);
        return NULL;
    }

    // Calculate CRC
    crc = 0xFF;
    for (int i = 0; i < 9; i++) {
        crc = crc ^ data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) & 0x3F;
            if ((crc & 0x01) == 1 && data[i] >> j & 0x01) {
                crc ^= CRC_POLYNOMIAL;
            }
        }
    }

    // Validate CRC
    if (crc != CRC_INIT) {
        fprintf(ctx->fd, "CRC check failed\n");
        close(ctx->fd);
        return NULL;
    }

    // Convert raw data to pressure and temperature
    pressure = (data[0] << 8) | data[1];
    temperature = (data[2] << 8) | data[3];

    // Convert to Pa and °C
    pressure /= 100.0; // Convert to hPa
    temperature = (temperature - 17.27) * 10; // Convert to °C

    // Log data
    timestamp = time(NULL);
    fprintf(ctx->fd, "%ld,%.1f,%.1f\n", timestamp, pressure, temperature);

    // Close I2C bus
    i2c_close(ctx->client);
    close(ctx->fd);

    return NULL;
}

int main(int argc, char *argv[]) {
    I2C_Context ctx;
    ctx.fd = -1;
    ctx.client = NULL;

    // Initialize I2C context
    if (i2c_init(LOG_FILE, I2C_BUS) == -1) {
        perror("Error initializing I2C");
        return EXIT_FAILURE;
    }

    // Start reading sensor data in a separate thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, read_sensor_data, &ctx) != 0) {
        perror("Error creating thread");
        i2c_close(ctx.client);
        close(ctx.fd);
        return EXIT_FAILURE;
    }

    // Main loop, sleep for 1 second between reads
    while (1) {
        usleep(1000000);
    }

    // Graceful shutdown
    if (pthread_join(thread_id, NULL) != 0) {
        perror("Error joining thread");
    }

    // Close I2C bus and log file
    i2c_close(ctx.client);
    close(ctx.fd);

    return EXIT_SUCCESS;
}

