    if (ioctl(ctx->fd, I2C_SLAVE, SDP810_ADDR) == -1 ||
        ioctl(ctx->fd, I2C_MEM_READ, &COMMAND) == -1 ||
        ioctl(ctx->fd, I2C_MEM_READ, data) == -1) {
        perror("Error communicating with sensor");
        close(ctx->fd);
        return NULL;
    }

    // Calculate CRC
    crc = 0xFF;
    for (int i = 0; i < 9; i++) {
        crc = crc ^ data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) & 0x3F;
            if ((crc & 0x01) == 1 && data[i] >> j & 0x01) {
                crc ^= CRC_POLYNOMIAL;
            }
        }
    }

    // Validate CRC
    if (crc != CRC_INIT) {
        fprintf(ctx->fd, "CRC check failed\n");
        close(ctx->fd);
        return NULL;
    }

    // Convert raw data to pressure and temperature
    pressure = (data[0] << 8) | data[1];
    temperature = (data[2] << 8) | data[3];

    // Convert to Pa and °C
    pressure /= 100.0; // Convert to hPa
    temperature = (temperature - 17.27) * 10; // Convert to °C

    // Log data
    timestamp = time(NULL);
    fprintf(ctx->fd, "%ld,%.1f,%.1f\n", timestamp, pressure, temperature);

    // Close I2C bus
    i2c_close(ctx->client);
    close(ctx->fd);

    return NULL;
}

int main(int argc, char *argv[]) {
    I2C_Context ctx;
    ctx.fd = -1;
    ctx.client = NULL;

    // Initialize I2C context
    if (i2c_init(LOG_FILE, I2C_BUS) == -1) {
        perror("Error initializing I2C");
        return EXIT_FAILURE;
    }

    // Start reading sensor data in a separate thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, read_sensor_data, &ctx) != 0) {
        perror("Error creating thread");
        i2c_close(ctx.client);
        close(ctx.fd);
        return EXIT_FAILURE;
    }

    // Main loop, sleep for 1 second between reads
    while (1) {
        usleep(1000000);
    }

    // Graceful shutdown
    if (pthread_join(thread_id, NULL) != 0) {
        perror("Error joining thread");
    }

    // Close I2C bus and log file
    i2c_close(ctx.client);
    close(ctx.fd);

    return EXIT_SUCCESS;
}
