#define I2C_BUS 1
#define I2C_ADDR 0x40
#define POLL_TIMEOUT_MS 100
#define LOG_INTERVAL_SEC 5

#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00

#define TEMP_SCALE 175.72
#define HUMID_SCALE 125.0

#define LOG_FILE "environment.log"

void log_to_csv(const char *timestamp, double temperature, double humidity) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char iso_timestamp[32];
    strftime(iso_timestamp, sizeof(iso_timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&tv.tv_sec));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s,%f,%f\n", iso_timestamp, temperature, humidity);
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_client *client;
    unsigned char read_buf[3];
    unsigned int raw_temp, raw_hum;
    int crc;
    unsigned char reset_cmd = 0xFE;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(i2c_fd, I2C_BUS);
    if (!client) {
        perror("i2c_client_new");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
        if (ret < 0) {
            perror("I2C_SLAVE");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        ret = ioctl(i2c_fd, I2C_MEM_READ, client, 0x00, &reset_cmd, 1);
        if (ret < 0) {
            perror("I2C_MEM_READ");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        ret = ioctl(i2c_fd, I2C_MEM_READ, client, 0x01, &raw_hum, 1);
        if (ret < 0) {
            perror("I2C_MEM_READ");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        ret = ioctl(i2c_fd, I2C_MEM_READ, client, 0x02, &raw_temp, 1);
        if (ret < 0) {
            perror("I2C_MEM_READ");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        crc = (raw_temp << 8) | (raw_hum >> 8);
        for (int i = 0; i < 3; i++) {
            crc ^= read_buf[i];
            for (int j = 0; j < 8; j++) {
                if ((crc & 0x80) != 0) {
                    crc <<= 1;
                    if (crc > 0xFF) {
                        crc = crc << 1 ^ 0x31;
                    } else {
                        crc <<= 1;
                    }
                } else {
                    crc <<= 1;
                }
            }
        }

        if (crc != 0x00) {
            fprintf(stderr, "CRC error, skipping data\n");
            log_to_csv(get_iso_timestamp(), -1, -1);
            continue;
        }

        double temp = TEMP_SCALE * (raw_temp / 65536.0) - 46.85;
        double humid = HUMID_SCALE * (raw_hum / 65536.0) - 6.0;

        log_to_csv(get_iso_timestamp(), temp, humid);

        usleep(POLL_TIMEOUT_MS * 1000 / 1000);

        if (ret < 0) {
            perror("I2C operation failed");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        close(i2c_fd);
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (!client) {
            perror("i2c_client_new");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
    }

    return 0;
}

