#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x25
#define SAMPLE_INTERVAL 1000 // Sample once per second

#define LOG_FILE "airflow.dat"

void handle_sigint(int sig) {
    printf("Received SIGINT, shutting down...\n");
    pigpio_terminate();
    close(LOG_FILE);
    exit(0);
}

void handle_sigterm(int sig) {
    printf("Received SIGTERM, shutting down...\n");
    pigpio_terminate();
    close(LOG_FILE);
    exit(0);
}

int main() {
    int log_fd;
    pigpio pi;
    int i2c_fd;
    struct i2c_client *client;
    uint8_t command[9];
    uint16_t pressure_raw, temperature_raw;
    float pressure, temperature;
    time_t last_sample_time;

    pi_init(PIG_OUT);
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        pi_terminate();
        return -1;
    }

    client = i2c_alloc(I2C_BUS, SENSOR_ADDRESS);
    if (!client) {
        perror("i2c_alloc");
        pi_terminate();
        close(log_fd);
        return -1;
    }

    command[0] = 0x36;
    command[1] = 0x2F;
    command[2] = 0x01; // Conversion time (ms)
    command[3] = 0x00; // Not used
    command[4] = 0x00; // Not used
    command[5] = 0x00; // Not used
    command[6] = 0x00; // Not used
    command[7] = 0x00; // Not used
    command[8] = 0x00; // CRC
    command[9] = 0x00; // Scale factor

    while (1) {
        if (i2c_write_byte(client, command[0]) == -1) {
            perror("i2c_write_byte");
            break;
        }

        usleep(SAMPLE_INTERVAL * 1000000 / 2); // Wait for conversion

        if (i2c_read_byte(client, &pressure_raw) == -1) {
            perror("i2c_read_byte");
            break;
        }

        if (i2c_read_byte(client, &temperature_raw) == -1) {
            perror("i2c_read_byte");
            break;
        }

        if (i2c_read_byte(client, &pressure_raw) != 0x00 ||
            i2c_read_byte(client, &temperature_raw) != 0x00) {
            printf("CRC validation failed\n");
            break;
        }

        pressure = (float)pressure_raw / 200.0 - 1000;
        temperature = (float)temperature_raw / 200.0 - 45.0;

        time(&last_sample_time);
        char timestamp[20];
        sprintf(timestamp, "%llu", last_sample_time);

        if (fwrite(&timestamp, sizeof(timestamp), 1, log_fd) == -1) {
            perror("fwrite");
            break;
        }

        if (fwrite(&pressure, sizeof(float), 1, log_fd) == -1) {
            perror("fwrite");
            break;
        }

        if (fwrite(&temperature, sizeof(float), 1, log_fd) == -1) {
            perror("fwrite");
            break;
        }
    }

    i2c_free(client);
    pigpio_terminate();
    close(log_fd);
    return 0;
}

