#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x25
#define COMMAND 0x3603
#define CONVERSION_TIME 45000  // 45 ms in microseconds
#define LOG_INTERVAL 5000000  // 5 seconds in microseconds
#define LOG_FILE "pressure_log.txt"
#define SCALE_FACTOR 60.0

void log_reading(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s", timestamp);
    fprintf(log_file, " %f Pa\n", get_pressure());
    fclose(log_file);
}

double get_pressure() {
    int i2c_fd;
    int bytes_read;
    uint8_t data[9];

    i2c_fd = open(LOG_FILE, O_RDWR | O_SYNC);
    if (i2c_fd == -1) {
        perror("Failed to open log file for I2C communication");
        return -1.0;
    }

    // Send continuous measurement command
    if (write(i2c_fd, &COMMAND, 1) != 1) {
        perror("Failed to write command to I2C bus");
        close(i2c_fd);
        return -1.0;
    }

    // Wait for conversion
    usleep(CONVERSION_TIME * 1000000 / 1000);

    // Read 9 bytes (3 words + 3 CRC bytes)
    bytes_read = read(i2c_fd, data, 9);
    if (bytes_read != 9) {
        perror("Failed to read from I2C bus");
        close(i2c_fd);
        return -1.0;
    }

    // Validate CRC
    if (!validate_crc(data, 9)) {
        fprintf(stderr, "CRC validation failed\n");
        close(i2c_fd);
        return -1.0;
    }

    // Convert raw pressure to Pa
    double pressure = (double)bytes_read * SCALE_FACTOR;

    // Log reading
    log_reading(get_timestamp());

    // Close I2C handle
    close(i2c_fd);

    return pressure;
}

int validate_crc(const uint8_t *data, int length) {
    uint32_t crc = 0;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x01) != 0) {
                crc >>= 1;
            } else {
                crc >>= 1;
                crc ^= 0x31;
            }
        }
    }
    return crc == 0;
}

