        if (pressure < 0) {
            perror("Failed to read pressure");
            break;
        }
        usleep(LOG_INTERVAL * 1000000 / 1000);  // Sleep for log interval
    }

    pigpio_terminate(1);  // Terminate pigpio cleanly
    close(i2c_fd);  // Close I2C handle
    fclose(log_file);  // Close log file
    return 0;
}

