#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL 100
#define SLPM_OFFSET 1638
#define SLPM_MAX 14745

void read_sensor(uint16_t *raw_flow) {
    int i2c_fd;
    struct i2c_rdwr_t wr_cmd;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open i2c bus");
        return;
    }

    wr_cmd.addr = I2C_ADDR;
    wr_cmd.len = 2;
    wr_cmd.data = {0x00, 0x28}; // Start and address

    if (write(i2c_fd, &wr_cmd, sizeof(wr_cmd)) != sizeof(wr_cmd)) {
        perror("Failed to write to I2C bus");
        close(i2c_fd);
        return;
    }

    if (i2c_read(i2c_fd, raw_flow) < 0) {
        perror("Failed to read from I2C bus");
        close(i2c_fd);
        return;
    }

    close(i2c_fd);
}

void compute_flow_rate(uint16_t raw_flow, float *flow_rate) {
    *flow_rate = (float)(raw_flow - SLPM_OFFSET) / (SLPM_MAX - SLPM_OFFSET) * 10;
}

void set_fan_duty_cycle(float flow_rate) {
    int duty_cycle = (int)((flow_rate / 10.0) * 100);
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfreq(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, duty_cycle, 100);
}

void log_reading(const char *timestamp) {
    time_t rawtime;
    struct tm * timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,0\n", timestamp);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    uint16_t raw_flow;
    float flow_rate;
    int fan_duty_cycle;

    gpioInit();

    while (1) {
        read_sensor(&raw_flow);
        compute_flow_rate(&raw_flow, &flow_rate);
        set_fan_duty_cycle(&flow_rate);
        log_reading(strftime(NULL, 0, "%Y-%m-%d %H:%M:%S", localtime(NULL)));

        usleep(SAMPLE_INTERVAL * 1000000 / PWM_FREQ);
    }

    gpioExit();
    return 0;
}

