#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define BUFFER_SIZE 10
#define LED_GPIO 17

#define AVERAGE_THRESHOLD 28.0

typedef struct {
    long timestamp;
    float temperature;
} TemperatureReading;

TemperatureReading temperatureBuffer[BUFFER_SIZE];
int bufferIndex = 0;

float runningAverage = 0.0;

void i2c_init() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("i2c_ioctl");
        close(file);
        exit(EXIT_FAILURE);
    }
}

int i2c_read(int file, unsigned short reg, unsigned char *buffer) {
    return ioctl(file, I2C_READ, reg, buffer);
}

long i2c_get_time() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return tv.tv_sec * 1000000 + tv.tv_usec;
}

float calculateTemperature(unsigned short value) {
    unsigned int high, low;
    high = (value >> 8) & 0xFF;
    low = value & 0xFF;

    unsigned int temp = (high << 8) | low;
    temp = (temp >> 7) << 7; // Convert to 9-bit resolution
    return (float)temp / 128.0;
}

void processTemperatureReading(long timestamp) {
    unsigned short value;
    if (i2c_read(1, I2C_ADDR, &value) == -1) {
        printf("I2C read failed\n");
        return;
    }

    float temp = calculateTemperature(value);
    temperatureBuffer[bufferIndex].timestamp = timestamp;
    temperatureBuffer[bufferIndex].temperature = temp;
    bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;

    runningAverage = (runningAverage * (bufferIndex - 1) + temperatureBuffer[0].temperature) / bufferIndex;

    if (runningAverage > AVERAGE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main() {
    pigpio_init(1); // Initialize pigpio with 1 as the PID
    i2c_init();

    while (1) {
        long current_time = i2c_get_time();
        processTemperatureReading(current_time);
        usleep(1000000); // Sleep for 1 second
    }

    gpioTerminate(); // Terminate GPIO
    close(1); // Close I2C file descriptor
    return 0;
}

void signalHandler(int signum) {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    close(1); // Close I2C handle
    pigpio_terminate(1); // Terminate pigpio
    exit(signum == SIGINT || signum == SIGTERM ? 0 : EXIT_FAILURE);
}

int main() {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    pigpio_init(1);
    i2c_init();

    while (1) {
        long current_time = i2c_get_time();
        processTemperatureReading(current_time);
        usleep(1000000);
    }

    pigpio_terminate(1);
    close(1);
    return 0;
}

