    time_t now = time(NULL);
    struct tm tstruct;
    tstruct.tm_year = now / (1000 * 365);
    tstruct.tm_mon = now % 12 + 1;
    tstruct.tm_day = now % 31;
    tstruct.tm_hour = now % 24;
    tstruct.tm_min = now % 60;
    tstruct.tm_sec = now % 60;

    char timestamp[80];
    sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
