#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x21
#define COMMAND_START 0x36
#define COMMAND_READ_PRESSURE 0x2F
#define SAMPLE_INTERVAL_MS 1000

void handle_sigint(int sig) {
    printf("Program terminated by SIGINT\n");
    exit(0);
}

void handle_sigterm(int sig) {
    printf("Program terminated by SIGTERM\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    pigpio_init(1); // Initialize pigpio with I2C bus 1

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <sample_interval_ms>\n", argv[0]);
        return 1;
    }

    long sample_interval = atoi(argv[1]) * 1000; // Convert to milliseconds
    const int sample_timer = pigpio_timer_new(sample_interval, 0);

    if (pigpio_timer_start(sample_timer) == -1) {
        fprintf(stderr, "Failed to start timer: %s\n", pigpio_strerror(errno));
        return 1;
    }

    while (1) {
        int sensor_present = pigpio_i2c_present(I2C_BUS, SENSOR_ADDRESS);
        if (sensor_present == -1) {
            fprintf(stderr, "Sensor not present on I2C bus %d address %d\n", I2C_BUS, SENSOR_ADDRESS);
            pigpio_timer_cancel(sample_timer);
            pigpio_exit();
            return 1;
        }

        if (pigpio_i2c_write_byte(I2C_BUS, SENSOR_ADDRESS, COMMAND_START) == -1) {
            fprintf(stderr, "Failed to send start command: %s\n", pigpio_strerror(errno));
            continue;
        }

        if (pigpio_i2c_write_byte(I2C_BUS, SENSOR_ADDRESS, COMMAND_READ_PRESSURE) == -1) {
            fprintf(stderr, "Failed to send read pressure command: %s\n", pigpio_strerror(errno));
            continue;
        }

        uint8_t pressure_data[9];
        if (pigpio_i2c_read_bytes(I2C_BUS, SENSOR_ADDRESS, pressure_data, 9) == -1) {
            fprintf(stderr, "Failed to read pressure data: %s\n", pigpio_strerror(errno));
            continue;
        }

        uint32_t raw_pressure = (pressure_data[0] << 24) | (pressure_data[1] << 16) | (pressure_data[2] << 8) | pressure_data[3];
        uint32_t crc = pressure_data[4];

        if (crc != 0xFF) {
            fprintf(stderr, "CRC-8 checksum failed for pressure data\n");
            continue;
        }

        uint32_t temperature_data = (pressure_data[5] << 24) | (pressure_data[6] << 16) | (pressure_data[7] << 8) | pressure_data[8];
        uint32_t scale_factor_data = pressure_data[9];

        if (scale_factor_data != 0xFF) {
            fprintf(stderr, "CRC-8 checksum failed for temperature/scale-factor data\n");
            continue;
        }

        double pressure_pa = (double)raw_pressure / scale_factor_data;
        printf("Timestamp: %lu ms, Pressure: %.2f Pa, Temperature: %.2f °C\n", (unsigned long)sample_interval / 1000, pressure_pa, (pressure_data[5] << 8) / 100.0);

        usleep(sample_interval / 1000);
    }

    pigpio_timer_cancel(sample_timer);
    pigpio_exit();
    return 0;
}

