#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define SDP810_ADDR 0x25
#define COMMAND 0x3615
#define CONVERSION_DELAY 45000  // 45 ms in microseconds
#define LOG_INTERVAL 1000000  // 1 second

#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

typedef struct {
    uint8_t raw_pressure;
    uint8_t raw_temperature;
    uint8_t scale_factor_pressure;
    uint8_t scale_factor_temperature;
} SDP810_DATA;

void handle_signal(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    pigpio_terminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init();
    if (pi == NULL) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    if (pi_init(pi, I2C_BUS) < 0) {
        perror("Failed to initialize I2C bus");
        pigpio_terminate();
        return 1;
    }

    SDP810_DATA data;
    uint8_t crc = CRC_INIT;

    while (1) {
        // Send continuous-measurement command
        pi_write_i2c_block_data(pi, SDP810_ADDR, COMMAND);

        // Wait for conversion
        sleep((unsigned int)CONVERSION_DELAY / 1000);

        // Read 9 bytes from the sensor
        pi_read_i2c_block_data(pi, SDP810_ADDR, &data, 9);

        // Validate CRC-8
        for (int i = 0; i < 3; i++) {
            crc = (crc << 1) ^ data[i];
            for (int j = 0; j < 8; j++) {
                if ((crc & 0x80) != 0) {
                    printf("CRC mismatch detected, sensor may be absent or there's a bus error.\n");
                    pi_write_i2c_block_data(pi, SDP810_ADDR, 0x00); // Reset command
                    break;
                }
            }
        }

        // Convert raw pressure and temperature values
        if (crc == CRC_INIT) {
            data.raw_pressure /= data.scale_factor_pressure;
            data.raw_temperature /= 200.0;

            // Log the results
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", data.raw_pressure, data.raw_temperature);
        } else {
            printf("CRC mismatch, skipping data.\n");
        }

        // Sleep before the next reading
        usleep(LOG_INTERVAL * 1000000);
    }

    // Handle SIGINT and SIGTERM for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    pigpio_terminate();
    return 0;
}

