#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00

#define LOG_INTERVAL 5000 // 5 seconds

// Function prototypes
int i2c_open(int fd, const char *device);
int i2c_write(int fd, unsigned char reg, unsigned char data);
int i2c_read(int fd, unsigned char reg, unsigned char *buffer);
int i2c_close(int fd);
double convert_temperature(unsigned short raw_temp);
double convert_humidity(unsigned short raw_humidity);

int main() {
    int i2c_fd, ret;
    unsigned char config_reg, temp_reg, data[4];
    double temp, humidity;

    i2c_fd = i2c_open(open("/dev/i2c-1", O_RDWR), "i2c-1");
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    config_reg = i2c_read(i2c_fd, CONFIG_REG, &config_reg);
    if (config_reg != 4) {
        perror("Failed to read CONFIG_REG");
        i2c_close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    config_reg |= (1 << 12); // Enable combined measurement
    ret = i2c_write(i2c_fd, CONFIG_REG, config_reg);
    if (ret != 4) {
        perror("Failed to write CONFIG_REG");
        i2c_close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = i2c_write(i2c_fd, TEMP_REG, 0x00);
        if (ret != 4) {
            fprintf(stderr, "Failed to write TEMP_REG\n");
            continue;
        }

        // Wait for 20 ms
        usleep(20000000);

        ret = i2c_read(i2c_fd, TEMP_REG, data);
        if (ret != 4) {
            fprintf(stderr, "Failed to read TEMP_REG\n");
            continue;
        }

        temp = convert_temperature(data[0]);
        humidity = convert_humidity(data[1]);

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humidity);

        usleep(LOG_INTERVAL * 1000000); // Sleep for LOG_INTERVAL ms
    }

    i2c_close(i2c_fd);
    return 0;
}

int i2c_open(int fd, const char *device) {
    int ret;
    ret = open(device, O_RDWR | O_SYNC);
    if (ret < 0) {
        perror("open");
        return -1;
    }
    return ret;
}

int i2c_write(int fd, unsigned char reg, unsigned char data) {
    int ret;
    ret = write(fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return -1;
    }
    ret = write(fd, &data, 1);
    if (ret != 1) {
        perror("write");
        close(fd);
        return -1;
    }
    return 0;
}

int i2c_read(int fd, unsigned char reg, unsigned char *buffer) {
    int ret;
    ret = read(fd, buffer, 2);
    if (ret != 2) {
        perror("read");
        return -1;
    }
    return 0;
}

int i2c_close(int fd) {
    int ret;
    ret = close(fd);
    if (ret < 0) {
        perror("close");
        return -1;
    }
    return 0;
}

double convert_temperature(unsigned short raw_temp) {
    return (double)(raw_temp / 65536.0) * 165.0 - 40.0;
}

double convert_humidity(unsigned short raw_humidity) {
    return (double)(raw_humidity / 65536.0) * 100.0;
}

// Signal handlers for SIGINT and SIGTERM
void sigint_handler(int sig) {
    fprintf(stderr, "SIGINT received, cleaning up and exiting...\n");
