void read_calibration_coefficients(int i2c_handle) {
    uint8_t buffer[8];
    if (pigpio_i2c_transfer(i2c_handle, SENSOR_ADDRESS, COMMAND_READ_OTP, 8, buffer) < 8) {
        fprintf(stderr, "Error reading calibration coefficients\n");
        exit(EXIT_FAILURE);
