void high_precision_measurement(int i2c_handle) {
    uint8_t buffer[6];
    if (pigpio_i2c_transfer(i2c_handle, SENSOR_ADDRESS, COMMAND_MEASURE, 0, buffer) < 6) {
        fprintf(stderr, "Error performing high-precision measurement\n");
        return;
    }

    int16_t temp = 0;
    int32_t pressure = 0;

    temp = (buffer[0] << 8) | buffer[1];
    pressure = ((buffer[2] << 16) | buffer[3]) | (buffer[4] << 8) | buffer[5];

