#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX90819_ADDR 0x60
#define SCALING_FACTOR 0.1

#define LOG_FORMAT "%d: %f kPa\n"

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    int file_descriptor;
    struct i2c_client *client;
    long raw_value;
    double kPa;

    if (argc != 2) {
        handle_error("Usage: ./mlx90819_reader <log_file>");
        return EXIT_FAILURE;
    }

    file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (file_descriptor < 0) {
        handle_error("Failed to open /dev/i2c-1");
    }

    client = i2c_alloc(file_descriptor);
    if (!client) {
        handle_error("Failed to allocate i2c_client");
    }

    if (ioctl(file_descriptor, I2C_SLAVE, MLX90819_ADDR) < 0) {
        handle_error("Failed to set I2C slave address");
    }

    while (1) {
        kPa = (double)client->regread(client, 0xAA) * SCALING_FACTOR +
               (double)client->regread(client, 0xAB) / 1000.0;

        if (write(file_descriptor, LOG_FORMAT, strlen(LOG_FORMAT)) < 0) {
            handle_error("Failed to write timestamp");
        }
        if (write(file_descriptor, &kPa, sizeof(kPa)) < 0) {
            handle_error("Failed to write pressure value");
        }
        if (write(file_descriptor, '\n', 1) < 0) {
            handle_error("Failed to write newline");
        }

        usleep(1000000); // Sleep for 1 second
    }

    i2c_free(client);
    close(file_descriptor);

    return EXIT_SUCCESS;
}

