#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define SDP800_ADDR 0x25
#define COMMAND 0x362F
#define WAIT_MS 45
#define LOG_FILE "pressure_log.txt"

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

unsigned char read_crc8(unsigned char crc, unsigned char data) {
    unsigned char i;
    for (i = 0; i < 8; i++) {
        crc = (crc << 1) ^ data;
        data = crc & 0x01 ? 0x01 : 0x80;
    }
    return crc;
}

int validate_crc(unsigned char crc, unsigned char *data) {
    return read_crc8(crc, data[0]) == data[0] &&
           read_crc8(crc, data[1]) == data[1] &&
           read_crc8(crc, data[2]) == data[2];
}

int main() {
    int file;
    struct i2c_client *client;
    unsigned char command[1], data[9];
    unsigned int raw_pressure, raw_temperature;
    unsigned char crc[3];

    file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file == -1) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    client = i2c_open(I2C_BUS, SDA_PIN);
    if (client == NULL) {
        perror("Error opening I2C bus");
        close(file);
        return EXIT_FAILURE;
    }

    if (ioctl(client->fd, I2C_SLAVE, SDP800_ADDR) == -1) {
        perror("Error setting I2C slave address");
        i2c_close(client, 0);
        close(file);
