#define COMMAND_BYTES 0x36, 0x2F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "airflow_log.csv"
#define LOG_INTERVAL 1000

void log_entry(const char *timestamp, double pressure) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing\n");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s,%f\n", time_str, pressure);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(I2C_BUS);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int file_exists = access(LOG_FILE, F_OK) != 0;
    if (!file_exists) {
        fopen(LOG_FILE, "w");
    }

    while (1) {
        int result = pigpio_i2c_write(pi, I2C_ADDR, sizeof(COMMAND_BYTES), COMMAND_BYTES);
        if (result < 0) {
            fprintf(stderr, "Failed to send command bytes: %s\n", pi_strerror(pi, result));
            continue;
        }

        sleep(LOG_INTERVAL / 1000.0); // Wait for 1 second

        result = pigpio_i2c_read(pi, I2C_ADDR, sizeof(COMMAND_BYTES) + 3, NULL);
        if (result < 0) {
            fprintf(stderr, "Failed to read data bytes: %s\n", pi_strerror(pi, result));
            continue;
        }

        uint8_t data[3];
        memcpy(data, COMMAND_BYTES, sizeof(COMMAND_BYTES));
        memcpy(data + sizeof(COMMAND_BYTES), result, 3);

        // Verify CRC
        uint8_t crc = CRC_INIT;
        for (int i = 0; i < sizeof(data); i++) {
            crc = (crc << 8) ^ data[i];
        }
        if (crc != 0xFF) {
            fprintf(stderr, "CRC verification failed\n");
            continue;
        }

        // Convert raw value to pressure
        int16_t raw_value = ntohl(*((int16_t *)data));
        double pressure = raw_value / 60.0;
        log_entry(time_str, pressure);

        pigpio_i2c_write(pi, I2C_ADDR, sizeof(COMMAND_BYTES), COMMAND_BYTES);
    }

    pigpio_terminate(pi);
    fclose(log_file);
    return 0;
}

