code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define SCALE_FACTOR 0.01
#define SAFE_RANGE_MIN 200
#define SAFE_RANGE_MAX 250
#define LOG_FILE "pressure_log.csv"

void sigint_handler(int signum) {
    fprintf(stderr, "\nExiting due to SIGINT...\n");
    gpioTerminate();
    close(logfd);
    exit(0);
}

void sigterm_handler(int signum) {
    fprintf(stderr, "\nExiting due to SIGTERM...\n");
    gpioTerminate();
    close(logfd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int logfd;
    pigpio pi = pigpio_init(I2C_BUS);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (i2cOpen(pi, MLX90821_ADDR, 0x00) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return 1;
    }

    if (file_exists(LOG_FILE)) {
        logfd = open(LOG_FILE, "a");
        if (logfd < 0) {
            fprintf(stderr, "Failed to open log file.\n");
            return 1;
        }
    } else {
        logfd = open(LOG_FILE, "w");
        if (logfd < 0) {
            fprintf(stderr, "Failed to create log file.\n");
            return 1;
        }
    }

    fprintf(logfd, "timestamp,pressure_kPa\n");

    while (1) {
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        uint16_t raw_pressure;
        if (i2cReadI2CBlockData(pi, MLX90821_ADDR, 0x00, &raw_pressure, 2) < 0) {
            fprintf(stderr, "Failed to read pressure register.\n");
            continue;
        }

        double pressure_kPa = raw_pressure * SCALE_FACTOR;

        if (pressure_kPa < SAFE_RANGE_MIN || pressure_kPa > SAFE_RANGE_MAX) {
            fprintf(stderr, "Warning: Pressure out of safe range: %f kPa\n", pressure_kPa);
        }

        if (write(logfd, timestamp, strlen(timestamp)) < 0) {
            fprintf(stderr, "Failed to write timestamp to log file.\n");
            continue;
        }
        if (write(logfd, ",", 1) < 0) {
            fprintf(stderr, "Failed to write comma to log file.\n");
            continue;
        }
        if (write(logfd, (char)pressure_kPa, 10) < 0) {
            fprintf(stderr, "Failed to write pressure to log file.\n");
            continue;
        }
        fprintf(logfd, "%s,%.2f\n", timestamp, pressure_kPa);

        usleep(1000000); // Sleep for 1 second
    }

    close(logfd);
    i2cClose(pi);
    pigpio_terminate(pi);

    return 0;
}

int file_exists(const char *filename) {
    struct stat sb;
    return (stat(filename, &sb) == 0);
}

