                 (double)(read_hih6130_data(I2C_ADDR, I2C_BUS)) * 100.0 / 16383.0);
        log_entry(entry);

        usleep((uint64_t)(SAMPLE_INTERVAL_SEC * 1000000));  // Convert seconds to microseconds
    }

    fclose(log_file);
