    if (status_bits != 0x00) {
        return -1;  // Sensor not present or bus error
    }

    uint16_t raw_T = (pigpio_i2c_transfer(bus, address, 0x01, 2, 0) << 8) | pigpio_i2c_transfer(bus, address, 0x02, 2, 0);
    uint16_t raw_H = (pigpio_i2c_transfer(bus, address, 0x03, 2, 0) << 8) | pigpio_i2c_transfer(bus, address, 0x04, 2, 0);

    if (raw_T == 0xFFFF || raw_H == 0xFFFF) {
        return -1;  // Invalid raw data
    }

    double temperature = raw_T * 165.0 / 16383.0 - 40.0;
    double humidity = raw_H * 100.0 / 16383.0;

    return 0;
}

