#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SIZE 2
#define TEMP_FILE "greenhouse_temps.dat"
#define TEMP_UPDATE_INTERVAL 60

int main(int argc, char *argv[]) {
    int i2c_fd, file_fd;
    struct i2c_client *client;
    pigpio_handle pi;
    FILE *temp_file;
    int temp_data[4];
    char *end_of_file;
    long file_size;
    int i;

    // Initialize pigpio
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Initialize I2C
    client = i2c_client_new(I2C_BUS, 0x48);
    if (!client) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_terminate();
        return 1;
    }

    // Check if device ID matches
    if (i2c_transfer(client, TMP117_ADDR, 0x01, 0x17, 1, 1000) != 2) {
        fprintf(stderr, "Device ID mismatch\n");
        i2c_client_free(client);
        pigpio_terminate();
        return 1;
    }

    // Open the binary file for writing
    temp_file = fopen(TEMP_FILE, "wb");
    if (!temp_file) {
        perror("Failed to open file");
        i2c_client_free(client);
        pigpio_terminate();
        return 1;
    }

    // Initialize file stream
    end_of_file = (char *)fmemopen(NULL, 0, "w");
    if (!end_of_file) {
        perror("Failed to initialize file stream");
        fclose(temp_file);
        i2c_client_free(client);
        pigpio_terminate();
        return 1;
    }

    // Start a timer for periodic updates
    struct itimerspec update_interval;
    update_interval.it_value.tv_sec = TEMP_UPDATE_INTERVAL;
    update_interval.it_value.tv_nsec = 0;
    struct sigaction sa;
    sa.sa_handler = SIGALRM;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGALRM, &sa, NULL) < 0) {
        perror("Failed to set SIGALRM handler");
        fclose(end_of_file);
        i2c_client_free(client);
        pigpio_terminate();
        return 1;
    }
    alarm(TEMP_UPDATE_INTERVAL);

    // Main loop
    while (1) {
        // Read temperature from TMP117
        if (i2c_transfer(client, TMP117_ADDR, TEMP_REG, 0, 2, 1000) != 2) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        // Convert temperature to float and append to file
        temp_data[0] = (float)(i2c_transfer(client, TMP117_ADDR, TEMP_REG, 0, 1, 1000)[0] << 8) | i2c_transfer(client, TMP117_ADDR, TEMP_REG, 0, 1, 1000)[1];
        temp_data[1] = (float)(i2c_transfer(client, TMP117_ADDR, TEMP_REG, 0, 2, 1000)[0] << 8) | i2c_transfer(client, TMP117_ADDR, TEMP_REG, 0, 2, 1000)[1];

        // Write to file
        if (fwrite(temp_data, sizeof(float), 1, temp_file) != 1) {
            perror("Failed to write to file");
            continue;
        }

        // Reset file stream
        end_of_file = fmemopen(NULL, 0, "w");
        if (!end_of_file) {
            perror("Failed to initialize file stream");
            fclose(temp_file);
            i2c_client_free(client);
            pigpio_terminate();
            return 1;
        }
    }

    // Clean up resources
    fclose(temp_file);
    i2c_client_free(client);
    pigpio_terminate();

    return 0;
}

