#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define COMMAND 0xFD
#define CONVERSION_DELAY 8500
#define LOG_FILE "environmental_data.txt"

void sigint_handler(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    pigpio_stop();
    close(logfd);
    exit(0);
}

int main() {
    int logfd;
    pigpio pi;
    struct i2c_rdwr_t i2c_wr;
    int i2c_fd;
    uint8_t command[1] = {COMMAND};
    uint8_t raw_temp[2];
    uint8_t raw_hum[2];
    uint8_t crc_temp[1];
    uint8_t crc_hum[1];
    int16_t temp, humidity;

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sigint_handler) == SIG_IGN) {
        perror("Error setting signal handler");
        return EXIT_FAILURE;
    }

    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (pi_setup_i2c(i2c_fd, I2C_BUS) < 0) {
        perror("Failed to setup I2C");
        return EXIT_FAILURE;
    }

    if (pi_write_i2c_block_data(i2c_fd, SHT40_ADDR, command, 1) < 0) {
        perror("Failed to write command to SHT40");
        return EXIT_FAILURE;
    }

    usleep(CONVERSION_DELAY * 1000000 / 2); // Wait for conversion

    if (pi_read_i2c_block_data(i2c_fd, SHT40_ADDR, raw_temp, 2) < 0) {
        perror("Failed to read raw temperature data");
        return EXIT_FAILURE;
    }
    if (pi_read_i2c_block_data(i2c_fd, SHT40_ADDR, raw_hum, 2) < 0) {
        perror("Failed to read raw humidity data");
        return EXIT_FAILURE;
    }

    crc_temp[0] = raw_temp[0] ^ raw_temp[1];
    crc_hum[0] = raw_hum[0] ^ raw_hum[1];

    if (crc_temp[0] != 0xFF) {
        printf("CRC-8 temperature check failed\n");
        return EXIT_FAILURE;
    }
    if (crc_hum[0] != 0xFF) {
        printf("CRC-8 humidity check failed\n");
        return EXIT_FAILURE;
    }

    temp = -45 + 175 * (raw_temp[0] / 65535.0);
    humidity = -6 + 125 * (raw_hum[0] / 65535.0);

    if (pi_write_i2c_block_data(i2c_fd, SHT40_ADDR, crc_temp, 1) < 0) {
        perror("Failed to write CRC-8 temperature");
        return EXIT_FAILURE;
    }
    if (pi_write_i2c_block_data(i2c_fd, SHT40_ADDR, crc_hum, 1) < 0) {
        perror("Failed to write CRC-8 humidity");
        return EXIT_FAILURE;
    }

    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    if (write(logfd, "Timestamp: " timestamp "\n", 20) < 0) {
        perror("Error writing timestamp");
        return EXIT_FAILURE;
    }

    if (write(logfd, "Temperature: " sprintf(timestamp, "%.1f °C\n", temp) 20) < 0) {
        perror("Error writing temperature");
        return EXIT_FAILURE;
    }

    if (write(logfd, "Humidity: " sprintf(timestamp, "%.1f %%RH\n", humidity) 20) < 0) {
        perror("Error writing humidity");
        return EXIT_FAILURE;
    }

    sleep(5);
}

