    if (write(logfd, "Timestamp: " timestamp "\n", 20) < 0) {
        perror("Error writing timestamp");
        return EXIT_FAILURE;
    }

    if (write(logfd, "Temperature: " sprintf(timestamp, "%.1f °C\n", temp) 20) < 0) {
        perror("Error writing temperature");
        return EXIT_FAILURE;
    }

    if (write(logfd, "Humidity: " sprintf(timestamp, "%.1f %%RH\n", humidity) 20) < 0) {
        perror("Error writing humidity");
        return EXIT_FAILURE;
    }

    sleep(5);
