#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define I2C_BUS 1
#define TMP117_ADDRESS 0x48
#define SAMPLE_INTERVAL 5

typedef struct {
    long timestamp;
    float temperature;
} TemperatureReading;

typedef struct {
    TemperatureReading *buffer;
    int head;
    int tail;
    int count;
    int file_fd;
} CircularBuffer;

static CircularBuffer buffer;

void init_pigpio();
void setup_i2c();
void read_temperature();
void save_to_file();
void cleanup();

int main(int argc, char *argv[]) {
    if (argc != 1) {
        fprintf(stderr, "Usage: %s <path_to_log_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    buffer.buffer = malloc(BUFFER_SIZE * sizeof(TemperatureReading));
    if (!buffer.buffer) {
        perror("Failed to allocate memory for circular buffer");
        exit(EXIT_FAILURE);
    }

    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    init_pigpio();
    setup_i2c();

    while (1) {
        read_temperature();
        save_to_file();
        usleep(SAMPLE_INTERVAL * 1000000); // Convert 5 seconds to microseconds
    }

    cleanup();
    return 0;
}

void init_pigpio() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus 1");
        exit(EXIT_FAILURE);
    }

    if (piGPIO_init(i2c_fd) < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    if (piGPIO_setup(I2C_BUS, TMP117_ADDRESS) < 0) {
        perror("Failed to setup I2C handle");
        exit(EXIT_FAILURE);
    }
}

void read_temperature() {
    long temp_reg;
    int result = piGPIO_i2c_mem_read(I2C_BUS, TMP117_ADDRESS, 0x00, &temp_reg, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read temperature register: %s\n", strerror(errno));
        return;
    }

    float temperature = (float)temp_reg * 0.0078125;
    buffer.buffer[buffer.tail * 2] = buffer.timestamp;
    buffer.buffer[buffer.tail * 2 + 1] = temperature;

    buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
    buffer.count++;

    if (buffer.count == BUFFER_SIZE) {
        save_to_file();
    }
}

void save_to_file() {
    int file_fd = open(buffer.buffer.timestamp, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (file_fd < 0) {
        perror("Failed to open file for writing");
        return;
    }

    if (ftruncate(file_fd, buffer.count * sizeof(TemperatureReading)) < 0) {
        perror("Failed to truncate file");
        close(file_fd);
        return;
    }

    char *ptr = (char *)&buffer.buffer[0];
    size_t nwritten = write(file_fd, ptr, buffer.count * sizeof(TemperatureReading));
    if (nwritten < 0) {
        perror("Failed to write to file");
        close(file_fd);
        return;
    }

    close(file_fd);
}

void cleanup() {
    piGPIO_teardown(I2C_BUS);
    close(buffer.file_fd);
    free(buffer.buffer);
}

void handle_sigint_sigterm(int sig) {
    fprintf(stderr, "Shutting down...\n");
    save_to_file();
    piGPIO_teardown(I2C_BUS);
    close(buffer.file_fd);
    free(buffer.buffer);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_sigint_sigterm);
    signal(SIGTERM, handle_sigint_sigterm);

    // ... (rest of the main function remains the same)
}

