#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>

#define SHTC3_I2C_ADDR 0x70
#define SHTC3_CMD_NORMAL 0x7866
#define SHTC3_CRC_POLY 0x31
#define SHTC3_CRC_INIT 0xFF
#define LOG_FILE "shtc3_environment.log"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,Temperature(%.1f),Humidity(%.1f)"

int main() {
    int i2c_fd, ret;
    struct i2c_client *client;
    char log_msg[100];
    time_t now;
    struct tm *time_info;

    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        perror("pigpioInitialise");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Create I2C client
    client = i2c_client_new(i2c_fd, SHTC3_I2C_ADDR);
    if (!client) {
        perror("i2c_client_new");
        close(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize SHTC3
    ret = i2c_transfer(client, SHTC3_CMD_NORMAL, 1, 1);
    if (ret < 0) {
        perror("i2c_transfer");
        i2c_client_free(client);
        close(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Wait for conversion
    usleep(12400000);

    // Read 6 bytes from SHTC3
    ret = i2c_transfer(client, NULL, 6, NULL);
    if (ret < 0) {
        perror("i2c_transfer");
        i2c_client_free(client);
        close(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Validate CRC
    uint8_t crc = 0xFF;
    for (int i = 0; i < 6; i++) {
        crc = (crc << 8) ^ client->data[i];
    }
    if (crc != SHTC3_CRC_INIT) {
        fprintf(stderr, "CRC validation failed\n");
        i2c_client_free(client);
        close(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temp = (client->data[0] << 8) | client->data[1];
    uint16_t raw_humi = (client->data[2] << 8) | client->data[3];

    double temp = (175.0 * raw_temp / 65535.0 - 45.0);
    double humi = (100.0 * raw_humi / 65535.0);

    if (temp < -40.0 || temp > 125.0 || humi < 0.0 || humi > 100.0) {
        fprintf(stderr, "Out-of-range reading: %f, %f\n", temp, humi);
        i2c_client_free(client);
        close(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Log valid reading
    time(&now);
    time_info = localtime(&now);
    sprintf(log_msg, LOG_FORMAT, now->tm_year + 1900,
            now->tm_mon + 1, now->tm_mday,
            now->tm_hour, now->tm_min, now->tm_sec);
    ret = fopen(LOG_FILE, "a");
    if (ret != NULL) {
        fprintf(ret, log_msg);
        fclose(ret);
    }

    // Print valid reading
    printf(LOG_FORMAT, temp, humi);
    printf("\n");

    // Close I2C client and file
    i2c_client_free(client);
    close(i2c_fd);

    // Handle SIGINT
    atexit(close_i2c_fd);
    return EXIT_SUCCESS;

close_i2c_fd:
    close(i2c_fd);
    pigpioTerminate();
    return EXIT_SUCCESS;
}

