#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"

void log_entry(double mag, double temp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%f,%f\n", mag, temp);
    fclose(fp);
}

int main() {
    int i2c_fd, ret;
    struct i2c_client *client;
    double raw_value, mag, temp_celsius;

    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioErrorText());
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = i2cOpenChannel(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpioErrorText());
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Create I2C client
    client = i2cTranslateChannel(i2c_fd, I2C_ADDR);
    if (!client) {
        fprintf(stderr, "Failed to create I2C client: %s\n", pigpioErrorText());
        i2cClose(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    FILE *fp = fopen(LOG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Write header if file is newly created
    if (fseek(fp, 0, SEEK_END) == 0) {
        long file_size = ftell(fp);
        if (file_size == 0) {
            fprintf(fp, "mag,temp\n");
        }
    }

    // Main loop
    while (1) {
        ret = i2cTransfer(client, 0, 0, 1, &raw_value, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from I2C sensor: %s\n", pigpioErrorText());
            log_entry(NAN, NAN);
            continue;
        }

        mag = raw_value * 0.1;
        temp_celsius = raw_value * 0.01 - 25.0;

        // Log the values
        log_entry(mag, temp_celsius);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C client and file
    i2cClose(i2c_fd);
    fclose(fp);

    // Terminate pigpio
    pigpioTerminate();

    return EXIT_SUCCESS;
}

