#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3

void sigint_handler(int signum) {
    printf("\nExiting gracefully...\n");
    pigpio_terminate();
    exit(0);
}

int main() {
    int i2c_fd, ret;
