#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define DHT11_PIN 4
#define CHECKSUM_LENGTH 5
#define START_LOW_TIME 18000
#define RESPONSE_LOW 80
#define RESPONSE_HIGH 80
#define BIT_LOW_TIME 50
#define BIT_HIGH_TIME 26
#define BIT_HIGH_TIME_1 70

#define LOG_FILE "dht11_readings.txt"

void log_error(const char *msg, int status) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s [%ld] Error: %s (Status: %d)\n",
            ctime(&now), (long)now, msg, status);
    fclose(log_file);
}

int main() {
    int gpio_dht11 = DHT11_PIN;
    int gpio_tick = 0;
    pigpio_init(1);

    if (pigpio_gpioSetMode(gpio_dht11, PIGPIO_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode for DHT11", -1);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    while (1) {
        // Start signal (pull low for at least 18 ms)
        gpioWrite(gpio_dht11, 0);
        usleep(START_LOW_TIME * 1000000 / 1000);

        // Release the line
        gpioWrite(gpio_dht11, 1);
        usleep(RESPONSE_HIGH * 1000000 / 1000);

        // Read the response
        int response = gpioRead(gpio_dht11);
        if (response == 0) {
            log_error("DHT11 sensor not detected", -2);
            break;
        }

        // Extract data bits
        int data_bits[CHECKSUM_LENGTH];
        int bit_index = 0;
        while (bit_index < CHECKSUM_LENGTH) {
            gpioWrite(gpio_dht11, 0);
            usleep(BIT_LOW_TIME * 1000000 / 1000);
            int bit = gpioRead(gpio_dht11);
            if (bit == 0) {
                data_bits[bit_index++] = BIT_LOW_TIME;
            } else {
                data_bits[bit_index++] = BIT_HIGH_TIME;
            }
            usleep(BIT_HIGH_TIME_1 * 1000000 / 1000);
        }

        // Checksum validation
        int checksum = 0;
        for (int i = 0; i < 4; i++) {
            checksum += data_bits[i];
        }
        if (checksum % 256 != data_bits[4]) {
            log_error("Checksum validation failed", -3);
            break;
        }

        // Extract humidity and temperature
        int humidity = data_bits[0];
        int temperature = data_bits[2];

        // Log reading
        time_t now = time(NULL);
        char timestamp[32];
        sprintf(timestamp, "%04d-%02d-%02dT%02d:%02d:%02dZ",
                now / 3600000, now % 3600000 / 3600, now % 3600 / 60,
                now % 60, 0);
        FILE *log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            break;
        }
        fprintf(log_file, "%s [%s] Temperature: %d, Humidity: %d\n",
                ctime(&now), timestamp, temperature, humidity);
        fclose(log_file);

        // Wait for 2 seconds
        usleep(2000000000);
    }

    pigpio_terminate();
    return EXIT_SUCCESS;
}

