#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/time.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define SHT31D_ADDR 0x44
#define COMMAND_0x2C06 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "sht31d_data.log"
#define LOG_INTERVAL 5000 // 5 seconds
#define MAX_RETRIES 3

void log_reading(const char *timestamp, float temperature, float humidity) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }
    fprintf(log_file, "%s,%f,%f\n", time_str, temperature, humidity);
    fclose(log_file);
}

int read_sht31d_data() {
    int i2c_fd, ret;
    char command[3];
    unsigned char data[6];
    unsigned int crc;

    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (i2c_fd == -1) {
        perror("Failed to open log file");
        return -1;
    }

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        command[0] = 0x2C;
        command[1] = 0x06;
        ret = pigpio_writei2c(i2c_fd, SHT31D_ADDR, COMMAND_0x2C06, 2);
        if (ret < 0) {
            perror("Failed to write command to I2C bus");
            continue;
        }

        ret = pigpio_wait_for_bit(i2c_fd, 1);
        if (ret < 0) {
            perror("Failed to wait for I2C bus release");
            continue;
        }

        ret = pigpio_readi2c(i2c_fd, SHT31D_ADDR, data, 6);
        if (ret < 0) {
            perror("Failed to read from I2C bus");
            continue;
        }

        crc = (crc << 8) | data[5];
        for (int i = 0; i < 5; i++) {
            crc ^= data[i];
            for (int j = 0; j < 8; j++) {
                if ((crc & 0x80) != 0) {
                    crc = crc << 1 ^ CRC_POLYNOMIAL;
                } else {
                    crc <<= 1;
                }
            }
        }

        if (crc != CRC_INIT) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            continue;
        }

        float temperature = -45 + 175.0 * (float)(data[0] << 8 / 256.0) / 65535.0;
        float humidity = 100.0 * (float)(data[1] << 8 / 256.0) / 65535.0;

        log_reading(time_str, temperature, humidity);
        return 0;
    }

    fprintf(stderr, "Failed to read from SHT31D sensor after %d retries.\n", MAX_RETRIES);
    return -1;
}

int main() {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (open(LOG_FILE, O_WRONLY | O_CREAT, 0644) == -1) {
        perror("Failed to open log file");
        pigpio_terminate();
        return 1;
    }

    while (1) {
        if (read_sht31d_data() < 0) {
            usleep(LOG_INTERVAL * 1000000); // Sleep for LOG_INTERVAL milliseconds
        }
        usleep(LOG_INTERVAL * 1000000); // Sleep for LOG_INTERVAL milliseconds
    }

    pigpio_terminate();
    fclose(open(LOG_FILE, "r"));
    remove(LOG_FILE);
    return 0;
}

