#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define SENSOR_ADDR_1 0x64
#define SENSOR_ADDR_2 0x65
#define DEVICE_ID_REG 0x00
#define RED_DATA_REG 0x64
#define GREEN_DATA_REG 0x66
#define BLUE_DATA_REG 0x68

#define LOG_FILE "cct_log.csv"
#define LOG_INTERVAL 1000 // 1 second in milliseconds

double calculate_cct(int red, int green, int blue) {
    // McCamy's formula for CCT calculation
    double r = red / 100.0;
    double g = green / 100.0;
    double b = blue / 100.0;
    double cct = 116.0 * pow((g / 95.0), 1/3) - 16.0;
    if (r > 0.008856) {
        cct = 9.2 * pow((g / 5.07) + 1.055, 3) - 1.4;
    } else {
        cct = 1.7 * pow((g / 5.07) + 1.055) - 0.2;
    }
    cct += 16.0;
    return cct;
}

int main(int argc, char *argv[]) {
    int i2c_fd, sensor_fd;
    pigpio pi;
    FILE *log_file;
    struct i2c_client *client;
    struct i2c_msg msg;
    double avg_cct = 0.0;
    double red, green, blue;
    time_t timestamp;
    struct tm *tm_info;

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    pigpio_init(1); // Initialize pigpio for I2C bus 1
    if (!pigpio_init()) {
        perror("pigpio_init");
        exit(EXIT_FAILURE);
    }

    client = i2c_open(I2C_BUS, SENSOR_ADDR_1);
    if (!client) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    i2c_write_byte(client, SENSOR_ADDR_1, DEVICE_ID_REG);
    i2c_read_byte(client, SENSOR_ADDR_1, RED_DATA_REG);
    red = i2c_read_byte(client, SENSOR_ADDR_1) << 8 | i2c_read_byte(client, SENSOR_ADDR_1);

    i2c_write_byte(client, SENSOR_ADDR_1, DEVICE_ID_REG);
    i2c_read_byte(client, SENSOR_ADDR_1, GREEN_DATA_REG);
    green = i2c_read_byte(client, SENSOR_ADDR_1) << 8 | i2c_read_byte(client, SENSOR_ADDR_1);

    i2c_write_byte(client, SENSOR_ADDR_1, DEVICE_ID_REG);
    i2c_read_byte(client, SENSOR_ADDR_1, BLUE_DATA_REG);
    blue = i2c_read_byte(client, SENSOR_ADDR_1) << 8 | i2c_read_byte(client, SENSOR_ADDR_1);

    avg_cct += calculate_cct(red, green, blue);

    i2c_close(client);
    client = i2c_open(I2C_BUS, SENSOR_ADDR_2);
    if (!client) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    i2c_write_byte(client, SENSOR_ADDR_2, DEVICE_ID_REG);
    i2c_read_byte(client, SENSOR_ADDR_2, RED_DATA_REG);
    red = i2c_read_byte(client, SENSOR_ADDR_2) << 8 | i2c_read_byte(client, SENSOR_ADDR_2);

    i2c_write_byte(client, SENSOR_ADDR_2, DEVICE_ID_REG);
    i2c_read_byte(client, SENSOR_ADDR_2, GREEN_DATA_REG);
