#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define RAW_PRESSURE_REGISTER 0x0A2C
#define RAW_TEMPERATURE_REGISTER 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN 0
#define PMAX 800

void log_error(const char *msg) {
    FILE *log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening pressure_log.txt for error logging.\n");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s %llu %s\n",
            ctime(&now), (long long)errno, msg);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        return 1;
    }

    pigpio_init(I2C_BUS);
    if (pigpio_init(I2C_BUS) < 0) {
        log_error("Failed to initialize pigpio for I2C bus 1");
        return 1;
    }

    const char *i2c_address = "0x" MLX90824_ADDR;
    const char *read_pressure_register = "0x" RAW_PRESSURE_REGISTER;
    const char *read_temperature_register = "0x" RAW_TEMPERATURE_REGISTER;

    while (1) {
        int pressure_raw, temperature_raw;
        if (pigpio_i2c_write(i2c_address, read_pressure_register, 2, &pressure_raw) < 0) {
            log_error("Failed to read RAW pressure register");
            continue;
        }
        if (pigpio_i2c_write(i2c_address, read_temperature_register, 2, &temperature_raw) < 0) {
            log_error("Failed to read RAW temperature register");
            continue;
        }

        uint16_t pressure = (pressure_raw << 8) | pressure_raw;
        uint16_t temperature = (temperature_raw << 8) | temperature_raw;

        double pressure_kPa = ((double)pressure - OUTPUT_MIN) * (PMAX - PMIN) / (OUTPUT_MAX - OUTPUT_MIN);
        double temperature_C = temperature * 0.01 - 40;

        time_t now = time(NULL);
        char timestamp[32];
        sprintf(timestamp, "%s", ctime(&now));

        FILE *log_file = fopen("pressure_log.txt", "a");
        if (!log_file) {
            log_error("Failed to open pressure_log.txt for logging");
            continue;
        }
        fprintf(log_file, "%s %llu %f %f\n", timestamp, (long long)now, pressure_kPa, temperature_C);
        fclose(log_file);

        usleep(2000000); // Wait for 2 seconds
    }

    pigpio_terminate(1000); // Terminate pigpio with a 1 second timeout
    fclose(NULL); // Close the log file (no need to explicitly close it)

    return 0;
}

