#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LM75B_ADDRESS 0x48
#define BUFFER_SIZE 60
#define FAN_GPIO 18
#define FAN_ON 1
#define FAN_OFF 0
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0

#define BUFFER_INDEX 0

int i2c_fd;
int fan_gpio;
int fan_state;

struct {
    int temperature;
    int timestamp;
} buffer[BUFFER_SIZE];
int buffer_index = BUFFER_INDEX;

double running_average = 0.0;

void i2c_init_error(const char *msg) {
    fprintf(stderr, "I2C initialization failed: %s\n", msg);
    exit(EXIT_FAILURE);
}

void gpio_init_error(const char *msg) {
    fprintf(stderr, "GPIO initialization failed: %s\n", msg);
    exit(EXIT_FAILURE);
}

void i2c_read_error(const char *msg) {
    fprintf(stderr, "I2C read failed: %s\n", msg);
}

void gpio_write_error(const char *msg) {
    fprintf(stderr, "GPIO write failed: %s\n", msg);
}

void sigint_handler(int sig) {
    printf("Received SIGINT, stopping...\n");
    fan_state = FAN_OFF;
    pigpio_stop();
    close(i2c_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Received SIGTERM, stopping...\n");
    fan_state = FAN_OFF;
    pigpio_stop();
    close(i2c_fd);
    exit(0);
}

void setup_i2c() {
    i2c_fd = pigpio_open(I2C_BUS, 0x48);
    if (i2c_fd < 0) {
        i2c_init_error("pigpio_open failed");
    }
}

void setup_fan() {
    fan_state = FAN_OFF;
    pigpio_set_mode(fan_gpio, PIGIO_OUTPUT);
}

void read_temperature() {
    int temperature_reg;
    if (pigpio_i2c_write(i2c_fd, LM75B_ADDRESS, 0x00, 2, &temperature_reg) < 0) {
        i2c_read_error("pigpio_i2c_write failed");
        return;
    }

    // Convert signed 9-bit value to Celsius
    int temp_celsius = (temperature_reg >> 8) * 0.5 + temperature_reg & 0x07;

    // Store in buffer and compute running average
    buffer[buffer_index].temperature = temp_celsius;
    buffer[buffer_index].timestamp = millis();
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    // Compute running average
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i].temperature;
    }
    running_average = sum / BUFFER_SIZE;

    // Check for hysteresis
    if (running_average > TEMP_THRESHOLD_HIGH) {
        fan_state = FAN_ON;
    } else if (running_average < TEMP_THRESHOLD_LOW) {
        fan_state = FAN_OFF;
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    setup_i2c();
    setup_fan();

    while (1) {
        read_temperature();
        usleep(1000000); // Sleep for 1 second
    }

    pigpio_stop();
    close(i2c_fd);
    return 0;
}

