#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#define SENSOR_ADDRESS 0x25
#define I2C_BUS 1
#define COMMAND 0x362F
#define WAIT_TIME_MS 45
#define LOG_FILE "airflow.log"
#define CRYPTO_POLYNOMIAL 0x31

void log_measurement(const char *timestamp, int16_t pressure, int16_t temperature) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_day,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }
    fprintf(log_file, "%s,%d,%d\n", time_str, pressure, temperature);
    fclose(log_file);
}

int main() {
    int i2c_fd;
    int16_t pressure, temperature;
    uint8_t crc;
    int status;

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open(fmt("i2c-%d", I2C_BUS), O_RDWR | O_NOCTTY | O_NDELAY);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address.\n");
        close(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &COMMAND, sizeof(COMMAND)) != sizeof(COMMAND)) {
        fprintf(stderr, "Failed to send command.\n");
        close(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    sleep(WAIT_TIME_MS / 1000.0);

    if (read(i2c_fd, &pressure, 2) != 2 ||
        read(i2c_fd, &temperature, 2) != 2 ||
        read(i2c_fd, &crc, 1) != 1) {
        fprintf(stderr, "Failed to read data from sensor.\n");
        close(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    crc = crc8(crc, pressure, temperature);
    if (crc != crc) {
        fprintf(stderr, "CRC mismatch detected.\n");
        close(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    pressure *= 60;
    temperature *= 200;

    log_measurement(ctime(NULL), pressure, temperature);

    if (pressure > 5.0) {
        fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa.\n");
    }

    close(i2c_fd);
    pigpioTerminate();

    return EXIT_SUCCESS;
}

