#define TEMP_SENSOR_ADDR 0x4A
#define TEMP_REGISTER 0x00
#define HYS_LOW_THRESHOLD 27
#define HYS_HIGH_THRESHOLD 28

int main(int argc, char *argv[]) {
    int i2c_fd, led_gpio;
    struct i2c_client *client;
    int16_t temp_value;
    int temp_celsius;

    // Initialize libgpiod
    if (gpio_init() < 0) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    client = i2c_client_new(i2c_fd, 0x20);
    if (!client) {
        perror("Failed to create I2C client");
        return EXIT_FAILURE;
    }

    // Read temperature from STTS2004 sensor
    if (i2c_mem_read_byte_data(client, TEMP_SENSOR_ADDR, TEMP_REGISTER, &temp_value) < 0) {
        perror("Failed to read from I2C sensor");
        return EXIT_FAILURE;
    }

    // Combine MSB and LSB, right-shift by 4 bits
    temp_celsius = (temp_value >> 4) * 0.0625;

    // Log temperature
    printf("Temperature: %.2f °C\n", temp_celsius);

    // Check hysteresis band
    if (temp_celsius > HYS_HIGH_THRESHOLD) {
        gpio_line_set_value(led_gpio, GPINO_HIGH);
    } else if (temp_celsius < HYS_LOW_THRESHOLD) {
        gpio_line_set_value(led_gpio, GPINO_LOW);
    }

    // Sleep for 1 second
    sleep(1);

    // Clean up I2C client
    i2c_client_free(client);
    close(i2c_fd);

    // Handle SIGINT/SIGTERM
    if (gpio_exit_requested()) {
        gpio_cleanup();
        return EXIT_SUCCESS;
    }

    return EXIT_SUCCESS;
}

