#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x25
#define COMMAND 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define SCALE_FACTOR_LEN 3

void sigint_handler(int signum) {
    printf("Exiting...\n");
    pigpio_stop();
    exit(0);
}

int main() {
    pigpio_initialize(I2C_BUS);
    signal(SIGINT, sigint_handler);

    piI2C_init(SENSOR_ADDR);

    while (1) {
        int result = piI2C_transfer(SENSOR_ADDR, &COMMAND, 1, 0);
        if (result < 0) {
            perror("piI2C_transfer");
            continue;
        }

        usleep(45000); // Wait for at least 45 ms

        int pressure_data[9];
        int temperature_data[9];
        int scale_factor_data[SCALE_FACTOR_LEN];

        result = piI2C_transfer(SENSOR_ADDR, pressure_data, 2, 0);
        if (result < 0) {
            perror("piI2C_transfer");
            continue;
        }
        pressure_data[2] = piI2C_read_byte(SENSOR_ADDR); // CRC byte
        result = piI2C_transfer(SENSOR_ADDR, temperature_data, 2, 0);
        if (result < 0) {
            perror("piI2C_transfer");
            continue;
        }
        temperature_data[2] = piI2C_read_byte(SENSOR_ADDR); // CRC byte
        result = piI2C_transfer(SENSOR_ADDR, scale_factor_data, SCALE_FACTOR_LEN, 0);
        if (result < 0) {
            perror("piI2C_transfer");
            continue;
        }

        // Validate CRC-8
        int crc_pressure = 0;
        for (int i = 0; i < 2; i++) {
            crc_pressure = (crc_pressure << 1) ^ pressure_data[i];
        }
        if (crc_pressure != 0xFF) {
            printf("CRC-8 failed for pressure data\n");
            continue;
        }

        int crc_temperature = 0;
        for (int i = 0; i < 2; i++) {
            crc_temperature = (crc_temperature << 1) ^ temperature_data[i];
        }
        if (crc_temperature != 0xFF) {
            printf("CRC-8 failed for temperature data\n");
            continue;
        }

        // Convert raw pressure and temperature
        int raw_pressure = (pressure_data[0] << 8) | pressure_data[1];
        int scale_factor = (int)(pressure_data[3] << 8) | pressure_data[4];
        int converted_pressure = raw_pressure / scale_factor;

        int raw_temperature = (temperature_data[0] << 8) | temperature_data[1];
        int temperature = raw_temperature / 200;

        // Log the reading with a timestamp
        FILE *fp = fopen("flow_data.txt", "a");
        if (!fp) {
            perror("fopen");
            continue;
        }
        time_t now = time(NULL);
        fprintf(fp, "%llu %d %d\n", (long long)now, converted_pressure, temperature);
        fclose(fp);
    }

    pigpio_stop();
    return 0;
}

