#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define SI7021_ADDRESS 0x40
#define MAX_RETRIES 3

void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm = *localtime(&now);
    char timestamp[8];
    sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec);
    fprintf(stderr, "[%s] %s\n", timestamp, msg);
}

void log_to_file(const char *data) {
    FILE *file = fopen("environment.log", "a");
    if (file) {
        fprintf(file, "%s", data);
        fclose(file);
    }
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    int ret;
    char command[3] = {0xF5, 0xF3, 0xE0};
    int raw_humidity, raw_temp;
    double temperature, humidity;

    if (pigpio_init() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (i2c_init(I2C_BUS, SDA_PIN, SCL_PIN) < 0) {
        log_error("Failed to initialize I2C");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (check_sensor_presence()) {
        log_error("Si7021 sensor detected.");
    } else {
        log_error("Si7021 sensor not detected. Exiting.");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    while (1) {
        ret = i2c_write_device(i2c_fd, command);
        if (ret < 0) {
            log_error("Failed to write command to Si7021");
            continue;
        }

        for (int i = 0; i < MAX_RETRIES; i++) {
            ret = i2c_read_device(i2c_fd, &raw_temp, 1);
            if (ret < 0) {
                log_error("Failed to read temperature");
                continue;
            }

            ret = i2c_read_device(i2c_fd, &raw_humidity, 1);
            if (ret < 0) {
                log_error("Failed to read humidity");
                continue;
            }

            temperature = (double)raw_temp * 175.72 / 65536 - 46.85;
            humidity = (double)raw_humidity * 125 / 65536 - 6;
            humidity = (humidity < 0) ? 0 : (humidity > 100) ? 100 : humidity;

            char log_data[100];
            sprintf(log_data, "%s,%.1f,%.1f",
                    get_iso8601_timestamp(), temperature, humidity);
            log_to_file(log_data);
            printf("%s", log_data);

            usleep(60000000); // Wait for 60 seconds
        }
    }

    pigpio_terminate();
    return EXIT_SUCCESS;
}

int i2c_init(int bus, int sda, int scl) {
    int fd;
    fd = open("/dev/i2c-" BUS, O_RDWR | O_NOCTTY);
    if (fd < 0) {
        log_error("Failed to open i2c device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDRESS)) {
        log_error("Failed to set I2C address");
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_M_READ, sda) < 0) {
        log_error("Failed to set SDA");
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_M_WRITE, scl) < 0) {
        log_error("Failed to set SCL");
        close(fd);
        return -1;
    }

    close(fd);
    return fd;
}

int i2c_write_device(int fd, const unsigned char *data) {
    return write(fd, data, sizeof(data));
}

int i2c_read_device(int fd, unsigned char *data, int len) {
    return read(fd, data, len);
}

int check_sensor_presence() {
    unsigned char id_reg[1];
    int ret = i2c_read_device(i2c_fd, id_reg, 1);
    if (ret == 1) {
        return 1; // Sensor present
    } else {
        return 0; // Sensor not present
    }
}

