        return 1;
    }

    if (write(pigpioGetI2CHandle(I2C_BUS), &TEMP_REG, 1) != 1) {
        perror("Failed to write to TEMP_REG");
        return 1;
    }

    if (write(pigpioGetI2CHandle(I2C_BUS), &TEMP_RES, 1) != 1) {
