#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSIRON_ADDR 0x44
#define SENSIRON_CMD_HIGH_REPETIBILTY 0x2C
#define SENSIRON_CMD_SET_MODE 0xE0
#define CRC_POLYNOMIAL 0x31

void log_temperature(const char *timestamp, float temperature) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_day,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open temperature log file.\n");
        return;
    }
    fprintf(log_file, "%s, %f\n", time_str, temperature);
    fclose(log_file);
}

int main() {
    int i2c_fd;
    unsigned char command[2];
    unsigned char data[3];
    unsigned int raw_ticks;
    float temperature;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSIRON_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    command[0] = SENSIRON_CMD_HIGH_REPETIBILITY;
    command[1] = SENSIRON_CMD_SET_MODE;

    if (write(i2c_fd, command, 2) != 2) {
        perror("Failed to write command bytes");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    usleep(10000); // Wait for 10 ms

    if (read(i2c_fd, data, 3) != 3) {
        perror("Failed to read data bytes");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    unsigned int crc = 0;
    for (int i = 0; i < 8; i++) {
        crc = (crc << 1) ^ data[i];
    }
    if (crc != (crc_poly << (8 * (sizeof(data) - 1)))) {
        fprintf(stderr, "CRC mismatch, invalid data received.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    raw_ticks = (data[0] << 8) | data[1];
    temperature = -45 + 175.0 * raw_ticks / 65535.0;

    log_temperature(get_iso8601_timestamp(), temperature);

    while (1) {
        sleep(5);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

// Helper function to get ISO-8601 timestamp
char *get_iso8601_timestamp() {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_day,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    return time_str;
}

