#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define COMMAND 0x3615
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL 1000000  // 1 second

void crc8(unsigned char *crc, const unsigned char *data) {
    unsigned char i, j, k, temp;
    for (i = 0; i < 8; i++) {
        temp = *crc ^ *data++;
        for (j = 0; j < 8; j++) {
            k = temp & 0x01;
            temp >>= 1;
            if (temp & 0x80) k ^= 0x81;
            *crc = *crc >> 1;
        }
    }
}

int main() {
    int i2c_fd, log_fd;
    struct i2c_client i2c_client;
    unsigned char pressure[9], temperature[3], scale_factor[3];
    unsigned char crc[2];
    struct timespec ts;
    char log_line[100];

    gpioInitialise();
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_client.device = I2C_BUS;
    i2c_client.address = SDP810_ADDR;
    i2c_fd = i2cOpen(&i2c_client, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        unsigned long now = ts.tv_sec * 1000000 + ts.tv_nsec;

        // Send command and wait
        if (i2cWriteByte(i2c_fd, COMMAND) != 1) {
            fprintf(stderr, "Failed to send command\n");
            continue;
        }
        if (i2cReadBytes(i2c_fd, pressure, 9) != 9) {
            fprintf(stderr, "Failed to read data from I2C\n");
            continue;
        }

        // Validate CRC
        crc8(crc, pressure + 2);
        if (crc[0] != 0xFF || crc[1] != 0x00) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Extract pressure and temperature
        unsigned int raw_pressure = (pressure[0] << 8) | pressure[1];
        unsigned int raw_temperature = (pressure[2] << 8) | pressure[3];

        // Scale factor extraction (assuming it's the 4th byte)
        scale_factor[0] = pressure[4];
        scale_factor[1] = pressure[5];
        scale_factor[2] = pressure[6];

        // Convert to Pa and C
        double pressure_pa = raw_pressure / scale_factor[0];
        double temperature_c = (raw_temperature - scale_factor[2]) * 5.0 / 9.0;

        // Log valid reading
        snprintf(log_line, sizeof(log_line), "%ld,%.1f,%.1f\n", now, pressure_pa, temperature_c);
        log_fd = fopen(LOG_FILE, "a");
        if (log_fd == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            continue;
        }
        fwrite(log_line, strlen(log_line), 1, log_fd);
        fclose(log_fd);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Close I2C handle and log file
    i2cClose(i2c_fd);
    fclose(log_fd);

    // Handle SIGINT gracefully
    if (signal(SIGINT, handle_sigint) == SIG_IGN) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
    }

    pigpioTerminate();
    return EXIT_SUCCESS;

handle_sigint:
{
    fprintf(stderr, "Received SIGINT, cleaning up...\n");
    close(i2c_fd);
    fclose(log_fd);
    pigpioTerminate();
    return 0;
}
}

