#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <sigaction.h>
#include <time.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define BUFFER_SIZE 100
#define CSV_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG "/var/log/scd40_error.log"
#define I2C_BUS 1
#define I2C_ADDR 0x62
#define START_COMMAND 0x21B1
#define READ_COMMAND 0xE000
#define STOP_COMMAND 0x3F86
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} Reading;

typedef struct {
    Reading readings[BUFFER_SIZE];
    int head;
    int tail;
} CircularBuffer;

CircularBuffer buffer;
volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    printf("Received SIGINT, stopping...\n");
    running = 0;
}

void* logging_thread(void* arg) {
    while (running) {
        time_t now = time(NULL);
        FILE* csv_file = fopen(CSV_FILE, "a");
        if (!csv_file) {
            fprintf(ERROR_LOG, "Failed to open %s: %s\n", CSV_FILE, strerror(errno));
            continue;
        }

        fprintf(csv_file, "%d,%f,%f,%f\n", now, buffer.readings[buffer.head].co2, buffer.readings[buffer.head].temperature, buffer.readings[buffer.head].humidity);
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;

        fclose(csv_file);
        usleep(60000000); // 60 seconds delay
    }
    fclose(csv_file);
    pthread_join(pthread_self(), NULL);
    close(buffer.head);
    close(buffer.tail);
    free(buffer.readings);
    pigpio_terminate(NULL);
}

int main() {
    sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int i2c_fd, ret;
    ret = pigpio_init();
    if (ret < 0) {
        fprintf(ERROR_LOG, "Failed to initialize pigpio: %s\n", pigpio_strerror(ret));
        return 1;
    }

    ret = i2c_open_device(I2C_BUS, I2C_ADDR);
    if (ret < 0) {
        fprintf(ERROR_LOG, "Failed to open I2C device: %s\n", pigpio_strerror(ret));
        pigpio_terminate(NULL);
        return 1;
    }

    ret = pigpio_write_i2c_mem(I2C_FD, START_COMMAND, 1, 0);
    if (ret < 0) {
        fprintf(ERROR_LOG, "Failed to send start command: %s\n", pigpio_strerror(ret));
        i2c_close(I2C_FD);
        pigpio_terminate(NULL);
        return 1;
    }

    usleep(1000000); // wait at least 1 second

    pthread_t logging_thread_id;
    pthread_create(&logging_thread_id, NULL, logging_thread, NULL);

    while (running) {
        Reading read;
        ret = pigpio_write_i2c_mem(I2C_FD, READ_COMMAND, 1, 0);
        if (ret < 0) {
            fprintf(ERROR_LOG, "Failed to send read command: %s\n", pigpio_strerror(ret));
            continue;
        }

        ret = pigpio_read_i2c_mem(I2C_FD, &read.co2, 2);
        if (ret < 0) {
            fprintf(ERROR_LOG, "Failed to read CO2: %s\n", pigpio_strerror(ret));
            continue;
        }

        ret = pigpio_read_i2c_mem(I2C_FD, &read.temperature, 2);
        if (ret < 0) {
            fprintf(ERROR_LOG, "Failed to read temperature: %s\n", pigpio_strerror(ret));
            continue;
        }

        ret = pigpio_read_i2c_mem(I2C_FD, &read.humidity, 2);
        if (ret < 0) {
            fprintf(ERROR_LOG, "Failed to read humidity: %s\n", pigpio_strerror(ret));
            continue;
        }

        if (ret != 3) {
            fprintf(ERROR_LOG, "CRC check failed for reading %d\n", read.timestamp);
            continue;
        }

        read.timestamp = time(NULL);
        buffer.readings[buffer.tail].timestamp = read.timestamp;
        buffer.readings[buffer.tail].co2 = read.co2;
        buffer.readings[buffer.tail].temperature = (float) (read.temperature - 175 * read.co2 / 65535);
        buffer.readings[buffer.tail].humidity = (float) (read.humidity * 100 / 65535);
