    }
    fprintf(log_file, "%s,%.2f,%.2f\n", time_str, pressure_Pa, temperature_C);
    fclose(log_file);
}

int main() {
    int i2c_fd;
    int raw_pressure[2];
    int raw_temp[2];
    int scale_factor;
    uint8_t crc[3];

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open log file.\n");
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        if (write(i2c_fd, &COMMAND, sizeof(COMMAND)) < 0) {
            fprintf(stderr, "Failed to write command to I2C.\n");
            continue;
        }

        usleep(45000000); // Wait for 45 ms

        if (read(i2c_fd, raw_pressure, 2) != 2 ||
            read(i2c_fd, raw_temp, 2) != 2 ||
            read(i2c_fd, &scale_factor, 1) != 1 ||
            read(i2c_fd, crc, 3) != 3) {
            fprintf(stderr, "I2C read error.\n");
            continue;
        }

        // Validate CRC
        uint32_t crc_calculated = 0;
        for (int i = 0; i < 3; i++) {
            crc_calculated = (crc_calculated << 8) | raw_pressure[i];
            crc_calculated = (crc_calculated << 8) | raw_temp[i];
            crc_calculated = (crc_calculated << 8) | scale_factor;
        }
        for (int i = 0; i < 3; i++) {
            if (crc_calculated != crc[i]) {
                fprintf(stderr, "CRC validation failed.\n");
                continue;
            }
        }

        // Convert pressure and temperature
        double pressure_Pa = (double)raw_pressure[0] * scale_factor / 1000;
        double temperature_C = -45 + 175 * (double)raw_temp[0] / 65535;

        log_reading(time(NULL), pressure_Pa, temperature_C);

        // Close I2C handle on SIGINT
        if (signal(SIGINT, close_i2c_fd) == SIG_IGN) {
            fprintf(stderr, "Failed to set SIGINT handler for I2C.\n");
        }
    }

    close(i2c_fd);
    pigpioTerminate();
    fclose(i2c_fd);
    return EXIT_SUCCESS;
}

int close_i2c_fd(int signum) {
    close(i2c_fd);
    return 0;
}

