#define I2C_ADDR 0x63
#define OTP_REG 0x66
#define HIGH_ACC_CMD 0x4011
#define DELAY_MS 20
#define LED_PIN 17
#define BLINK_FREQ_NORMAL 1000
#define BLINK_FREQ_WARNING 500

#define CRC_CHECK(data, size) { \
    unsigned int crc = 0; \
    for (int i = 0; i < size; i++) { \
        crc ^= data[i]; \
        for (int j = 0; j < 8; j++) { \
            if ((crc & 1) != (data[i] & 0x01)) { \
                crc >>= 1; \
            } else { \
                crc <<= 1; \
            } \
        } \
    } \
    crc >> 8; \
    return crc == 0; \
}

void read_sensor_data(unsigned char *pressure, unsigned char *temperature, unsigned char *crc) {
    struct i2c_rdwr_ctx ctx;
    ctx.addr = I2C_ADDR;
    ctx.flags = I2C_M_BRIGHT;
    ctx.len = 6;
    ctx.buf = (void *)0;

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, ctx.addr) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_MEMREAD, &ctx) < 0) {
        perror("ioctl I2C_MEMREAD");
        close(fd);
        exit(EXIT_FAILURE);
    }

    *pressure = ctx.buf[0];
    *temperature = ctx.buf[1];
    *crc = ctx.buf[2];

    if (!CRC_CHECK(ctx.buf + 3, 2)) {
        perror("CRC check failed");
        exit(EXIT_FAILURE);
    }

    close(fd);
}

void set_led_state(int state) {
    int line = gp_led_get_line(LED_PIN);
