#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define TEMP_REG_AMB 0x06
#define TEMP_REG_OBJ 0x07
#define FAN_GPIO 18
#define FAN_ON 1
#define FAN_OFF 0
#define HYS_LOW 28
#define HYS_HIGH 30
#define LOG_INTERVAL 2000 // 2 seconds
#define MAX_RETRIES 3
#define DELAY_MS 10

int i2c_fd;
int fan_state = FAN_OFF;

void log_temperature(const char *timestamp, double temp) {
    FILE *file = fopen("temperature_log.txt", "a");
    if (file) {
        fprintf(file, "%s, %f\n", timestamp, temp);
        fclose(file);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Exiting...\n");
        fan_state = FAN_OFF;
        close(i2c_fd);
        pigpio_terminate(NULL);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        pigpio_terminate(NULL);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        pigpio_terminate(NULL);
        return EXIT_FAILURE;
    }

    while (1) {
        int retries = 0;
        long amb_temp = 0;
        long obj_temp = 0;

        do {
            amb_temp = read_register(i2c_fd, TEMP_REG_AMB);
            obj_temp = read_register(i2c_fd, TEMP_REG_OBJ);

            if (amb_temp == -1 || obj_temp == -1) {
                retries++;
                if (retries > MAX_RETRIES) {
                    printf("Failed to read temperature after %d retries.\n", MAX_RETRIES);
                    continue;
                }
                usleep(DELAY_MS * 1000); // 1 ms delay
            } else {
                break;
            }
        } while (amb_temp == -1 || obj_temp == -1);

        double amb_c = (amb_temp * 0.02 - 273.15);
        double obj_c = (obj_temp * 0.02 - 273.15);

        if (obj_c > HYS_HIGH) {
            fan_state = FAN_ON;
        } else if (obj_c < HYS_LOW) {
            fan_state = FAN_OFF;
        }

        if (amb_c >= 0 && obj_c >= 0) {
            log_temperature(ctime(NULL), amb_c);
        }

        usleep(LOG_INTERVAL * 1000 / 2); // Sleep for half the interval
    }

    close(i2c_fd);
    pigpio_terminate(NULL);
    return EXIT_SUCCESS;
}

int read_register(int fd, int reg) {
    unsigned char data[2];
    int ret = read(fd, data, 2);
    if (ret == -1) {
        perror("Failed to read from I2C bus");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

