#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "temperature_log.csv"

void log_temperature(const char *timestamp, double temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return;
    }
    fprintf(file, "%s,%.2f\n", timestamp, temperature);
    fclose(file);
}

int main() {
    int i2c_fd;
    int register_address = 0x00;
    double temperature;

    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((i2c_fd = i2pi_open(I2C_BUS, I2C_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (pigpio_set_mode(i2c_fd, PIGIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C mode: %s\n", strerror(errno));
        i2pi_close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    while (true) {
        struct timespec write_timeout;
        write_timeout.tv_sec = 5;
        write_timeout.tv_nsec = 0;

        if (clock_gettime(CLOCK_REALTIME, &write_timeout) < 0) {
            fprintf(stderr, "Failed to get current time: %s\n");
            continue;
        }

        clock_nanosleep(CLOCK_REALTIME, 0, &write_timeout, NULL);

        if (i2pi_read_i2c_block_cold(i2c_fd, register_address, 2, &temperature) < 0) {
            fprintf(stderr, "Failed to read from TMP102: %s\n");
            continue;
        }

        temperature = (double)temperature / 4095.0 * 0.0625;
        log_temperature(ctime(NULL), temperature);
    }

    pigpio_terminate();
    return EXIT_SUCCESS;
}

