#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <signal.h>

#define I2C_BUS 1
#define HDC2010_ADDR 0x40
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define TEMP_REG 0x00
#define TEMP_REG_2 0x01
#define HUMIDITY_REG 0x02
#define HUMIDITY_REG_2 0x03

volatile sig_atomic_t quit = 0;

void signal_handler(int signum) {
    gpioTerminate();
    quit = 1;
}

int main() {
    int i2c_fd;
    int ret;

    // Initialize pigpio
    if (piGPIOInit() < 0) {
        perror("pigpio initialization failed");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C mode
    if (ioctl(i2c_fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Initialize HDC2010 sensor
    ret = pigpio_write(i2c_fd, MEASUREMENT_CONFIG);
    if (ret < 0) {
        perror("Failed to write MEASUREMENT_CONFIG");
        return 1;
    }

    // Wait for measurement to complete
    ret = pigpio_read(i2c_fd, CONFIG);
    if (ret < 0) {
        perror("Failed to read CONFIG");
        return 1;
    }

    while (!quit) {
        ret = pigpio_read(i2c_fd, TEMP_REG);
        if (ret < 0) {
            perror("Failed to read temperature register");
            return 1;
        }

        ret = pigpio_read(i2c_fd, TEMP_REG_2);
        if (ret < 0) {
            perror("Failed to read temperature register 2");
            return 1;
        }

        ret = pigpio_read(i2c_fd, HUMIDITY_REG);
        if (ret < 0) {
            perror("Failed to read humidity register");
            return 1;
        }

        ret = pigpio_read(i2c_fd, HUMIDITY_REG_2);
        if (ret < 0) {
            perror("Failed to read humidity register 2");
            return 1;
        }

        // Convert raw values to temperature and humidity
        float temperature = (float)(ret & 0xFF) / 65536.0 * 165 - 40;
        float humidity = (float)(ret & 0xFF) / 65536.0 * 100;

        printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);

        // Wait for 5 seconds before next reading
        usleep(50000000);
    }

    // Close I2C bus and terminate pigpio
    close(i2c_fd);
    pigpioTerminate();

    return 0;
}

