This code initializes the pigpio library, sets up a signal handler for Ctrl+C, opens the I2C bus, and configures the HDC2010 sensor. It then enters a loop where it reads the temperature and humidity values from the sensor, converts them, and prints them to the console every 5 seconds. The code handles errors for I2C operations and gracefully shuts down when a Ctrl+C is detected.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_COMMAND 0x362F
#define LOG_INTERVAL 500

void handle_sigint(int sig) {
    printf("\nExiting on signal...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_fd;
    int error;
    uint8_t pressure_raw[3];
    uint8_t temperature_raw[3];
    uint8_t crc_pressure, crc_temperature;

    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if ((error = i2cSetup(I2C_BUS, SDP800_ADDR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Start continuous reading
    while (1) {
        // Send continuous measurement command
        if (i2cWrite(i2c_fd, CONTINUOUS_COMMAND) < 0) {
            perror("Failed to send continuous command");
            continue;
        }

        // Wait for measurement to complete (approx. 45 ms)
        usleep(100000);

        // Read 6 bytes: 2 bytes pressure + 1 CRC, 2 bytes temperature + 1 CRC
        if (i2cRead(i2c_fd, pressure_raw, 2) < 0 ||
            i2cRead(i2c_fd, temperature_raw, 2) < 0) {
            perror("Failed to read data from sensor");
            continue;
        }

        // Verify CRC-8 checksums
        crc_pressure = 0xFF;
        crc_temperature = 0xFF;
        for (int i = 0; i < 2; i++) {
            crc_pressure = (crc_pressure << 1) ^ pressure_raw[i];
            crc_temperature = (crc_temperature << 1) ^ temperature_raw[i];
        }
        if (crc_pressure != 0x31) {
            printf("Pressure CRC failed\n");
            continue;
        }
        if (crc_temperature != 0x31) {
            printf("Temperature CRC failed\n");
            continue;
        }

        // Log raw pressure and temperature values
        printf("Pressure: %d, Temperature: %d\n", (int)pressure_raw[0] << 8 | pressure_raw[1],
               (int)temperature_raw[0] << 8 | temperature_raw[1]);

        // Wait for next log interval
        usleep(LOG_INTERVAL * 1000);
    }

    // Close I2C handle and terminate pigpio
    i2cClose(i2c_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

