#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <libgpiod.h>
#include <w1.h>
#include <w1_master.h>

#define TEMP_SENSOR_PIN 7
#define RELAY_PIN 11
#define PWM_PIN 12
#define LOG_FILE "greenhouse.log"
#define SETPOINT_ARG 1
#define KP_ARG 2
#define KI_ARG 3
#define KD_ARG 4
#define LOG_INTERVAL 5000

int main(int argc, char *argv[]) {
    gpiod_context_t ctx;
    w1_slave *slave;
    float setpoint, kp, ki, kd, last_error, temperature, pwm_duty;
    pid_t pid;

    pid = fork();
    if (pid == 0) { // Child process
        if (gpiod_init(&ctx) != 0) {
            fprintf(stderr, "Failed to initialize gpiod\n");
            exit(EXIT_FAILURE);
        }

        if (w1_init() != 0) {
            fprintf(stderr, "Failed to initialize w1-gpio\n");
            exit(EXIT_FAILURE);
        }

        slave = w1_slave_new_first_available();
        if (!slave) {
            fprintf(stderr, "Failed to get slave device\n");
            exit(EXIT_FAILURE);
        }

        if (w1_device_address(slave, 0) == -1) {
            fprintf(stderr, "Failed to get device address\n");
            exit(EXIT_FAILURE);
        }

        if (w1_read_cold_cold_raw(slave, 0) == -1) {
            fprintf(stderr, "Failed to read temperature\n");
            exit(EXIT_FAILURE);
        }

        last_error = w1_get_error(slave);
        if (last_error != W1_NO_ERROR) {
            fprintf(stderr, "CRC error reading temperature\n");
            exit(EXIT_FAILURE);
        }

        temperature = w1_parse_temperature_c(w1_read_temp_raw(slave, 0));

        setpoint = atof(argv[SESETPOINT_ARG]);
        kp = atof(argv[KP_ARG]);
        ki = atof(argv[KI_ARG]);
        kd = atof(argv[KD_ARG]);

        while (1) {
            pwm_duty = kp * (setpoint - temperature) + ki * temperature + kd * (temperature - last_output);
            last_output = pwm_duty;

            // Control relay and PWM
            if (gpio_set_value(RELAY_PIN, 1) == -1) {
                fprintf(stderr, "Failed to enable heater\n");
                exit(EXIT_FAILURE);
            }

            gpio_set_pwm_duty(PWM_PIN, pwm_duty);

            // Log data
            char log_msg[1024];
            sprintf(log_msg, "Timestamp: %lu, Temp: %.2f, Set: %.2f, PID: %.2f, PWM: %.2f\n",
                    (unsigned long)time(NULL), temperature, setpoint, pwm_duty, pwm_duty);
            write(fileno(LOG_FILE), log_msg, strlen(log_msg));

            // Wait for log interval
            usleep(LOG_INTERVAL * 1000);
        }

        // Clean up
        gpio_set_value(RELAY_PIN, 0);
        gpio_set_pwm_duty(PWM_PIN, 0);
        gpiod_destroy(&ctx);
        w1_free(slave);
        close(fileno(LOG_FILE));
    } else { // Parent process
        if (pidof("greenhouse") != NULL) {
            fprintf(stderr, "Greenhouse process already running\n");
            exit(EXIT_FAILURE);
        }

        // Fork child process
        if (fork() == 0) {
            main(argc, argv);
            exit(0);
        }

        // Wait for child process
        wait(NULL);
    }

    return 0;
}

