#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>
#include <libgpiod/i2c.h>

#define I2C_DEVICE "/dev/i2c-1"
#define AHT20_ADDRESS 0x38
#define DEHUMIDIFIER_GPIO 17
#define LOG_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_gpio_set_dir(GPIO_ANY, DEHUMIDIFIER_GPIO, GPIOD_OUT);
        close(fildes_i2c);
        exit(0);
    }
}

int main() {
    int fildes_i2c;
    int ret;
    struct i2c_rdwr_t wr_cmd;
    int aht20_address;
    uint8_t aht20_init_seq[] = {0xBE, 0x08, 0x00};
    uint8_t aht20_trigger_cmd[] = {0xAC, 0x33, 0x00};
    uint8_t status_byte;
    int retries = 0;
    unsigned long last_read_time = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    aht20_address = AHT20_ADDRESS;

    // Initialize I2C
    fildes_i2c = open(I2C_DEVICE, O_RDWR);
    if (fildes_i2c == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // AHT20 initialization
    ret = libgpiod_i2c_transfer(fildes_i2c, aht20_address, aht20_init_seq, 3, 1000);
    if (ret < 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        unsigned long now = millis();
        if (now - last_read_time > LOG_INTERVAL_SEC) {
            last_read_time = now;

            // Send trigger command
            ret = libgpiod_i2c_transfer(fildes_i2c, aht20_address, aht20_trigger_cmd, 3, 1000);
            if (ret < 0) {
                fprintf(stderr, "Failed to send trigger command, retrying...\n");
                retries++;
                if (retries > MAX_RETRIES) {
                    fprintf(stderr, "Failed after %d retries\n", MAX_RETRIES);
                    continue;
                }
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }

            // Read 6 bytes of data
            ret = libgpiod_i2c_transfer(fildes_i2c, aht20_address, NULL, 0, 1000);
            if (ret < 0) {
                fprintf(stderr, "Failed to read data, retrying...\n");
                retries++;
                if (retries > MAX_RETRIES) {
                    fprintf(stderr, "Failed after %d retries\n", MAX_RETRIES);
                    continue;
                }
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }

            // Verify status byte
            status_byte = read_byte(fildes_i2c, 5);
            if (status_byte != 0x00) {
                fprintf(stderr, "Sensor not calibrated or busy\n");
                continue;
            }

            // Read humidity
            uint16_t humidity = read_16bit_word(fildes_i2c, 6);

            // Check dehumidifier state
            if (humidity > 60) {
                fprintf(stdout, "[%lu] Humidity: %d%, Activating dehumidifier...\n", now, humidity);
                gpiod_gpio_set_level(GPIO_ANY, DEHUMIDIFIER_GPIO, 1);
            } else if (humidity < 55) {
                fprintf(stdout, "[%lu] Humidity: %d%, Deactivating dehumidifier...\n", now, humidity);
                gpiod_gpio_set_level(GPIO_ANY, DEHUMIDIFIER_GPIO, 0);
            }
        }
    }

    close(fildes_i2c);
    return 0;
}

// Helper functions for reading bytes
uint8_t read_byte(int fd, int count) {
    uint8_t buf[1];
    int ret = read(fd, buf, count);
    if (ret < 0) {
        perror("Failed to read byte");
        return 0;
    }
    return buf[0];
}

uint16_t read_16bit_word(int fd, int count) {
    uint16_t word;
    int ret = read(fd, &word, count);
    if (ret < 0) {
        perror("Failed to read 16-bit word");
        return 0;
    }
    return word;
}

