            ret = libgpiod_i2c_transfer(fildes_i2c, aht20_address, NULL, 0, 1000);
            if (ret < 0) {
                fprintf(stderr, "Failed to read data, retrying...\n");
                retries++;
                if (retries > MAX_RETRIES) {
                    fprintf(stderr, "Failed after %d retries\n", MAX_RETRIES);
                    continue;
                }
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }

            // Verify status byte
            status_byte = read_byte(fildes_i2c, 5);
            if (status_byte != 0x00) {
                fprintf(stderr, "Sensor not calibrated or busy\n");
                continue;
            }

            // Read humidity
            uint16_t humidity = read_16bit_word(fildes_i2c, 6);

            // Check dehumidifier state
            if (humidity > 60) {
                fprintf(stdout, "[%lu] Humidity: %d%, Activating dehumidifier...\n", now, humidity);
                gpiod_gpio_set_level(GPIO_ANY, DEHUMIDIFIER_GPIO, 1);
            } else if (humidity < 55) {
                fprintf(stdout, "[%lu] Humidity: %d%, Deactivating dehumidifier...\n", now, humidity);
                gpiod_gpio_set_level(GPIO_ANY, DEHUMIDIFIER_GPIO, 0);
            }
        }
    }

    close(fildes_i2c);
    return 0;
}

// Helper functions for reading bytes
uint8_t read_byte(int fd, int count) {
    uint8_t buf[1];
    int ret = read(fd, buf, count);
    if (ret < 0) {
        perror("Failed to read byte");
        return 0;
    }
    return buf[0];
}

uint16_t read_16bit_word(int fd, int count) {
    uint16_t word;
    int ret = read(fd, &word, count);
    if (ret < 0) {
        perror("Failed to read 16-bit word");
        return 0;
    }
    return word;
}
```

