#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <syslog.h>
#include <pthread.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define UPDATE_INTERVAL 60

#define HTTP_HOST "http://api.example.com/humidity"
#define HTTP_PORT 80

#define LOG_FACILITY "prog"
#define LOG_PRIORITY syslog(LOG_FACILITY)

struct htu21d_data {
    uint16_t temperature;
    uint16_t humidity;
};

void *read_sensor(void *arg) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        LOG_ERR("Failed to open /dev/i2c-1\n");
        return NULL;
    }

    struct i2c_rdwr_ctx ctx;
    ctx.ctl = (u32) I2C_BUS;
    ctx.address = (u8) I2C_ADDR;
    ctx.len = 2;
    ctx.buf = (u8 *) &temperature, ctx.buf[1] = 0x00;

    if (ioctl(fd, I2C_SLAVE, ctx.address) < 0) {
        close(fd);
        LOG_ERR("Failed to acquire bus access\n");
        return NULL;
    }

    if (read(fd, ctx.buf, ctx.len) != ctx.len) {
        close(fd);
        LOG_ERR("Failed to read from sensor\n");
        return NULL;
    }

    close(fd);

    struct htu21d_data data;
    data.temperature = ntohs(ctx.buf[0]);
    data.humidity = ntohs(ctx.buf[1]);

    LOG_INFO("Temperature: %d C, Humidity: %d%%\n", data.temperature, data.humidity);

    return NULL;
}

void *http_post(void *arg) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        LOG_ERR("Failed to create socket\n");
        return NULL;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(HTTP_PORT);
    server_addr.sin_addr.s_addr = inet_addr(HTTP_HOST);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        close(sock);
        LOG_ERR("Failed to connect to server\n");
        return NULL;
    }

    char http_request[] = "POST /humidity HTTP/1.1\r\n"
                          "Host: " HTTP_HOST "\r\n"
                          "Content-Type: application/json\r\n"
                          "Content-Length: " sizeof(struct htu21d_data) "\r\n\r\n"
                          "[{\"temperature\": " STRFMT(data.temperature, "%d", 0) ", "
                          "  \"humidity\": " STRFMT(data.humidity, "%d", 0) "}]\r\n\r\n";

    if (write(sock, http_request, strlen(http_request)) != strlen(http_request)) {
        close(sock);
        LOG_ERR("Failed to send HTTP request\n");
        return NULL;
    }

    close(sock);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        LOG_ERR("Usage: %s <interval_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    update_interval = atoi(argv[1]) * 1000; // Convert to milliseconds
    pthread_t sensor_thread, http_thread;

    if (pthread_create(&sensor_thread, NULL, read_sensor, NULL) != 0) {
        LOG_ERR("Failed to create sensor reading thread\n");
        return EXIT_FAILURE;
    }

    if (pthread_create(&http_thread, NULL, http_post, NULL) != 0) {
        LOG_ERR("Failed to create HTTP posting thread\n");
        return EXIT_FAILURE;
    }

    while (1) {
        usleep(update_interval / 1000);
    }

    pthread_join(sensor_thread, NULL);
    pthread_join(http_thread, NULL);

    return EXIT_SUCCESS;
}

