#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x76
#define REG_CALIBRATION 0x88
#define REG_CTRL_MEAS 0xF4
#define REG_RAW_DATA 0xF7
#define THRESHOLD_HIGH 1020
#define THRESHOLD_LOW 980
#define LOG_FILE "pressure_log.txt"
#define LOG_INTERVAL 2000000  // 2 seconds in microseconds

void sigint_handler(int sig) {
    printf("Received SIGINT, shutting down...\n");
    gpioTerminate();
    close(i2c_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Received SIGTERM, shutting down...\n");
    gpioTerminate();
    close(i2c_fd);
    exit(0);
}

int main() {
    int i2c_fd, ret;
    struct i2c_client *client;
    int retries = 3;
    unsigned char chip_id, calib[24], raw_data[6];

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY | O_NDELAY);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return -1;
    }

    client = i2c_client_new(i2c_fd, I2C_BUS);
    if (!client) {
        perror("i2c_client_new");
        close(i2c_fd);
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl I2C_SLAVE");
        i2c_client_free(client);
        close(i2c_fd);
        return -1;
    }

    for (int attempt = 0; attempt < retries; attempt++) {
        ret = read(i2c_fd, &calib[0], 24);
        if (ret == 24) {
            if (calib[0] == 0x58) {
                break;
            }
            printf("Chip ID verification failed, attempt %d of %d\n", attempt + 1, retries);
        } else {
            perror("read from I2C");
            break;
        }
    }

    if (attempt == retries) {
        printf("Failed to verify chip ID after %d attempts, exiting.\n", retries);
        goto cleanup;
    }

    ret = write(i2c_fd, &client->reg_write_buf[0], 1);
    if (ret != 1) {
        perror("write to I2C");
        goto cleanup;
    }

    ret = read(i2c_fd, raw_data, 6);
    if (ret != 6) {
        perror("read from I2C");
        goto cleanup;
    }

    double pressure = (raw_data[0] << 8) | raw_data[1];
    pressure *= 0.01; // Convert to hPa

    if (pressure > THRESHOLD_HIGH || pressure < THRESHOLD_LOW) {
        FILE *log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("fopen");
            goto cleanup;
        }
        time_t now = time(NULL);
        fprintf(log_file, "%llu %f\n", (long long)now, pressure);
        fclose(log_file);
    }

cleanup:
    i2c_client_free(client);
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

