#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <time.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define LOG_FILE_PREFIX "sensor_log_"
#define LOG_FILE_FORMAT "sensor_log_%Y_%m_%d_%H_%M_%S.csv"
#define SAMPLE_INTERVAL 1000000  // 1 second in microseconds

#define I2C_DEVICE "/dev/i2c-1"

static int gpio_fd;
static int i2c_fd;
static struct i2c_client *i2c_client;

void gpio_init(void) {
    gpio_fd = open("/dev/gpiochip4", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open /dev/gpiochip4");
        exit(EXIT_FAILURE);
    }
    if (gpio_setup(gpio_fd, GPIO_MODE_INPUT) < 0) {
        perror("Failed to set up GPIO 17");
        exit(EXIT_FAILURE);
    }
}

int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    struct i2c_client *client;
    client = i2c_client_new(i2c_fd, 0x20);
    if (!client) {
        perror("Failed to create i2c client");
        close(i2c_fd);
        return -1;
    }

    return client;
}

void i2c_write(struct i2c_client *client, uint8_t reg, uint8_t *data) {
    if (ioctl(i2c_fd, I2C_SLAVE, client->addr) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }
    if (write(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        i2c_client_free(client);
        return;
    }
}

int i2c_read(struct i2c_client *client, uint8_t reg, uint8_t *data) {
    if (ioctl(i2c_fd, I2C_SLAVE, client->addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read from I2C device");
        close(i2c_fd);
        i2c_client_free(client);
        return -1;
    }
    return 0;
}

void gpio_read(void) {
    int value = read(gpio_fd, &gpio_state, 1);
    if (value == -1) {
        perror("Failed to read GPIO state");
        exit(EXIT_FAILURE);
    }
    gpio_motion_detected = gpio_state[0] == 0;
}

void log_data(const char *timestamp, int temperature, int humidity, int motion_detected) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char log_entry[1024];
    sprintf(log_entry, "%d,%d,%d,%d", now, temperature, humidity, motion_detected);
    FILE *log_file = fopen(LOG_FILE_PREFIX log_file_name(local_time), "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s", log_entry);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int ret;
    gpio_fd = open("/dev/gpiochip4", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open /dev/gpiochip4");
        exit(EXIT_FAILURE);
    }
    gpio_setup(gpio_fd, GPIO_MODE_INPUT);

    ret = i2c_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        gpio_read();

        int temperature, humidity, motion_detected;
        ret = i2c_read(i2c_client, TMP117_ADDR, (uint8_t *)&temperature);
        if (ret < 0) {
            fprintf(stderr, "Failed to read TMP117 temperature\n");
            continue;
        }

        ret = i2c_read(i2c_client, AHT20_ADDR, (uint8_t *)&humidity);
        if (ret < 0) {
            fprintf(stderr, "Failed to read AHT20 humidity\n");
            continue;
        }

        ret = i2c_read(i2c_client, AHT20_ADDR, (uint8_t *)&humidity);
        if (ret < 0) {
            fprintf(stderr, "Failed to read AHT20 humidity (retry)\n");
            usleep(10000);
            continue;
        }

        ret = i2c_read(i2c_client, AHT20_ADDR, (uint8_t *)&humidity);
        if (ret < 0) {
            fprintf(stderr, "Failed to read AHT20 humidity (3rd retry)\n");
            usleep(10000);
            continue;
        }

        motion_detected = gpio_motion_detected;

        log_data(get_timestamp(), temperature, humidity, motion_detected);

        usleep(SAMPLE_INTERVAL / 1000000);
    }

    gpio_client_free(i2c_client);
    close(i2c_fd);
    close(gpio_fd);

    return 0;
}

char *log_file_name(const struct tm *local_time) {
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y_%m_%d_%H_%M_%S", local_time);
    return LOG_FILE_PREFIX timestamp;
}

