#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/gpio.h>

#define GPIO_RAIN_SENSOR 17
#define GPIO_MOTOR_ENA 22
#define GPIO_MOTOR_IN1 23
#define GPIO_MOTOR_IN2 24
#define POLL_INTERVAL 2000 // in milliseconds
#define RUN_TIME 5000 // in milliseconds

void handle_sigint(int sig) {
    printf("Exiting gracefully\n");
    libgpiod_disable();
    exit(0);
}

void handle_sigterm(int sig) {
    printf("Exiting gracefully\n");
    libgpiod_disable();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = handle_sigterm;
    sigaction(SIGTERM, &sa, NULL);

    int ret;
    ret = libgpiod_init();
    if (ret < 0) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    int rainsensor_fd = libgpiod_gpio_get_fd(GPIO_RAIN_SENSOR);
    if (rainsensor_fd < 0) {
        perror("Failed to open GPIO17");
        libgpiod_disable();
        return EXIT_FAILURE;
    }

    while (1) {
        int rain_detected = libgpiod_gpio_get_value(rainsensor_fd);
        if (rain_detected == 0) {
            printf("Rain detected at %lu ms\n", (unsigned long)clock_gettime(CLOCK_REALTIME, NULL));
            libgpiod_gpio_set_drive(rainsensor_fd, 0);

            // Enable motor
            libgpiod_gpio_set_value(GPIO_MOTOR_ENA, 1);
            libgpiod_gpio_set_value(GPIO_MOTOR_IN1, 0);
            libgpiod_gpio_set_value(GPIO_MOTOR_IN2, 0);

            // Start motor forward
            usleep(RUN_TIME / 1000);

            // Stop motor
            libgpiod_gpio_set_value(GPIO_MOTOR_ENA, 0);
        }

        usleep(POLL_INTERVAL / 1000);
    }

    libgpiod_disable();
    return EXIT_SUCCESS;
}

