#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

void signal_handler(int signum) {
    gpioOutput(RED_PIN, 0);
    gpioOutput(GREEN_PIN, 0);
    gpioOutput(BLUE_PIN, 0);
    gpioTerminate();
    exit(0);
}

void setup_gpio() {
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
}

void update_led_color(int cpu_load) {
    int r, g, b;

    if (cpu_load < 0) {
        r = 0;
        g = 0;
        b = 255; // 0% load
    } else if (cpu_load < 10) {
        r = 0;
        g = cpu_load * 255 / 10;
        b = 255; // 50% load
    } else if (cpu_load < 100) {
        r = (100 - cpu_load) * 255 / (100 - 50);
        g = 255;
        b = 0; // 100% load
    } else {
        r = 255;
        g = 0;
        b = 0; // Error case, should never happen
    }

    r = (r > 255) ? 255 : r;
    g = (g > 255) ? 255 : g;
    b = (b > 255) ? 255 : b;

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWM(RED_PIN, 0, r);
    gpioSetPWM(GREEN_PIN, 0, g);
    gpioSetPWM(BLUE_PIN, 0, b);
}

void read_cpu_load() {
    FILE *fp;
    char line[65];

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("Failed to open /proc/stat");
        return;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Failed to read from /proc/stat");
        return;
    }

    char *load_str = strtok(line, " ");
    if (load_str == NULL) {
        perror("Failed to parse CPU load from /proc/stat");
        return;
    }

    double load = strtod(load_str, NULL);
    fclose(fp);

    // Map CPU load to 0-255 range
    int cpu_load = (int)((load / 100.0) * 255);

    // Update LED color
    update_led_color(cpu_load);
}

int main() {
    setup_gpio();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        read_cpu_load();
        usleep(500000); // Update every 500 ms
    }

    gpioTerminate();
    return 0;
}

