int main(int argc, char *argv[]) {
    int fd;
    struct spidev_dev *dev;
    gpio_ad_t ad;
    gpio_req_t req;
    int error;

    init_gpio();
    init_spi();

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_temp(&error);
        if (error) {
            log_temp(error);
            sleep(TEMP_LOG_INTERVAL);
            continue;
        }

        log_temp(error);
        usleep(TEMP_LOG_INTERVAL * 1000);
    }

    shutdown();
    close(fd);
    return 0;
}

void init_gpio(void) {
    ad = GPIO_AD_8;
    gpio_request(CE_PIN, "max31865_ce");
    gpio_direction_output_fast(CE_PIN);
    gpio_request(8, "max31865_cs");
    gpio_direction_output_fast(8);
    gpio_request(0, "spidev0.0");
    gpio_direction_output_fast(0);
}

void init_spi(void) {
    dev = spidev_open(0, 0);
    if (!dev) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }
