    if (reg_data[0] & 0x02) {
        error_handler("Sensor fault");
        return;
    }

    *temp = (float)reg_data[1] * 0.01;
}

void log_temp(float temp) {
    char time_str[20];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);

    sprintf(time_str, "%02d-%02d-%04d %02d:%02d:%02d",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s, %f\n", time_str, temp);
    fclose(log_file);
}

