void log_data(const char *timestamp, float temp, float humid, float press) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%.1f,%.1f,%.1f\n", timestamp, temp, humid, press);
    fclose(file);
}

int init_bme280() {
    int file;
    char cmd[10];

    file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file == -1) {
        perror("Failed to open log file");
        return -1;
    }

    snprintf(cmd, sizeof(cmd), "echo -n '%s' > /dev/i2c-%d/%d", "0\n", I2C_BUS, I2C_ADDR);
    if (write(file, cmd, strlen(cmd)) == -1) {
        perror("Failed to write to log file");
        close(file);
        return -1;
    }

    close(file);

    // Initialize BME280
    if (ioctl(file, I2C_SLAVE, I2C_ADDR) == -1) {
        if (errno == ENODEV || errno == EBUSY || errno == EACCES) {
            fprintf(stderr, "BME280 sensor not found or bus busy\n");
            return -1;
        }
        perror("Failed to initialize BME280");
        return -1;
    }

    // Read chip ID
    if (ioctl(file, I2C_READ_I2C_BLOCK, 0x00) == -1) {
        perror("Failed to read chip ID");
        close(file);
        return -1;
    }

    if (ioctl(file, I2C_READ_I2C_BLOCK, 0x60) == -1) {
        perror("Failed to read chip ID");
        close(file);
        return -1;
    }

    if (ioctl(file, I2C_READ_I2C_BLOCK, 0x60) != 0x60) {
        fprintf(stderr, "BME280 chip ID mismatch\n");
        close(file);
        return -1;
    }

    return 0;
}

void read_bme280_data() {
    int file;
    char buffer[12];

    file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file == -1) {
        perror("Failed to open log file");
        return;
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Failed to write to log file");
        close(file);
        return;
    }

    if (ioctl(file, I2C_READ_BYTE_RANGE, 0x00, 1) == -1) {
        perror("Failed to read BME280 data");
        close(file);
        return;
    }

    if (ioctl(file, I2C_READ_BYTE_RANGE, 0x01, 1) == -1) {
        perror("Failed to read BME280 data");
        close(file);
        return;
    }

    if (ioctl(file, I2C_READ_BYTE_RANGE, 0x02, 1) == -1) {
        perror("Failed to read BME280 data");
        close(file);
        return;
    }

    // Convert raw data to temperature, humidity, and pressure
    float temp = ((buffer[0] << 8) | buffer[1]) * 0.02 - 46.875;
    float humid = ((buffer[2] << 8) | buffer[3]) / 65535.0 * 100.0;
    float press = ((buffer[4] << 8) | buffer[5]) / 100.0;

