#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define BUFFER_SIZE 60 * 8  // 60 seconds * 8 bytes per reading
#define SAMPLE_INTERVAL_MS 50
#define OSS 0
#define CALIBRATION_START_REG 0xAA
#define CALIBRATION_COEFFICIENTS_START 0x00
#define CALIBRATION_COEFFICIENTS_LENGTH 11
#define PRESSURE_CONVERSION_REG 0xF4
#define PRESSURE_CONVERSION_VALUE 0x34
#define ALERT_GPIO 24

typedef struct {
    uint16_t timestamp;
    float pressure;
} PressureReading;

PressureReading pressureBuffer[BUFFER_SIZE];
int bufferIndex = 0;

void i2c_error_handler(const char *cmd, int err) {
    fprintf(stderr, "I2C Error: %s, Error Code: %d\n", cmd, err);
}

void timer_callback(int timer_id) {
    static uint64_t last_timestamp = 0;
    uint64_t current_timestamp = micros();

    if (current_timestamp - last_timestamp > SAMPLE_INTERVAL_MS / 1000) {
        // Read pressure from BMP180
        int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to open I2C bus\n");
            return;
        }

        uint8_t reg_addr = CALIBRATION_START_REG;
        uint8_t cal_coeffs_start_addr = CALIBRATION_COEFFICIENTS_START;
        uint8_t cal_coeffs_length = CALIBRATION_COEFFICIENTS_LENGTH;

        if (i2cReadByteData(i2c_fd, reg_addr) != cal_coeffs_start_addr) {
            fprintf(stderr, "BMP180 sensor not found or I2C communication failed\n");
            i2cClose(i2c_fd);
            return;
        }

        if (i2cWriteByteData(i2c_fd, PRESSURE_CONVERSION_REG) != PRESSURE_CONVERSION_VALUE) {
            fprintf(stderr, "Failed to set pressure conversion register\n");
            i2cClose(i2c_fd);
            return;
        }

        if (i2cWriteByteData(i2c_fd, 0x00) != 0x00) {
            fprintf(stderr, "Failed to write calibration coefficients\n");
            i2cClose(i2c_fd);
            return;
        }

        uint16_t pressure_raw;
        if (i2cReadByteData(i2c_fd, 0x00) == 0x00) {
            fprintf(stderr, "Failed to read pressure data\n");
            i2cClose(i2c_fd);
            return;
        }

        pressureBuffer[bufferIndex].timestamp = current_timestamp;
        pressureBuffer[bufferIndex].pressure = (float)pressure_raw / 100.0f; // Convert raw to hPa

        last_timestamp = current_timestamp;
        bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;

        // Check for alert condition
        float rolling_avg = 0.0f;
        for (int i = bufferIndex - 60; i < bufferIndex; i++) {
            rolling_avg += pressureBuffer[i].pressure;
        }
        rolling_avg /= 60.0f;

        if (fabs(pressureBuffer[bufferIndex].pressure - rolling_avg) > 5.0f) {
            gpioSetPinState(ALERT_GPIO, 1);
        } else {
            gpioSetPinState(ALERT_GPIO, 0);
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);

    pigpioInit();

    int timer_id = gpioSetTimerFuncEx(timer_callback, SAMPLE_INTERVAL_MS / 1000, OSS);
    if (timer_id < 0) {
        fprintf(stderr, "Failed to set hardware timer\n");
        pigpioExit();
        return -1;
    }

    gpioSetup(ALERT_GPIO, PIGIO_OUTPUT);

    while (1) {
        usleep(100000);
    }

    pigpioExit();
    return 0;

signal_handler:
    fprintf(stderr, "Received SIGINT, resetting GPIO and exiting\n");
    gpioSetPinState(ALERT_GPIO, 0);
    pigpioInit();
    return 0;
}

