#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define OSS_SETTING 0
#define LOG_FILE "bmp180_log.txt"
#define SAMPLE_INTERVAL 500

void sigint_handler(int signum) {
    printf("Received SIGINT, exiting gracefully...\n");
    pigpio_stop();
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, exiting gracefully...\n");
    pigpio_stop();
    exit(0);
}

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_client *client;
    char log_msg[100];

    // Initialize pigpio
    if (pigpio_init() < 0) {
        perror("pigpio_init");
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY | O_NDELAY);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        pigpio_stop();
        exit(EXIT_FAILURE);
    }

    // Initialize I2C client
    client = i2c_client_new(i2c_fd, BMP180_ADDR);
    if (!client) {
        perror("i2c_client_new");
        pigpio_stop();
        exit(EXIT_FAILURE);
    }

    // Validate BMP180 calibration data
    uint8_t calibration_data[16];
    ret = read(client->fd, calibration_data, sizeof(calibration_data));
    if (ret != sizeof(calibration_data)) {
        perror("read calibration data");
        i2c_client_free(client);
        pigpio_stop();
        exit(EXIT_FAILURE);
    }

    // Check calibration data
    if (calibration_data[0] != 0xAA || calibration_data[1] != 0xBF) {
        printf("Invalid calibration data, exiting...\n");
        i2c_client_free(client);
        pigpio_stop();
        exit(EXIT_FAILURE);
    }

    // Start timer interrupt
    struct itimerval timer;
    timer.it_interval.tv_sec = 0.05;
    timer.it_value.tv_sec = 0;
    timer.it_interval.tv_sec = 0;
    timer.it_value.tv_usec = SAMPLE_INTERVAL * 1000;
    timer.it_interval.tv_usec = SAMPLE_INTERVAL * 1000;

    if (setitimer(ITIMERS_FLAG, &timer, NULL) < 0) {
        perror("setitimer");
        i2c_client_free(client);
        pigpio_stop();
        exit(EXIT_FAILURE);
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        i2c_client_free(client);
        pigpio_stop();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read temperature and pressure
        int16_t temp, press;
        ret = pigpio_i2c_mem_read(client, BMP180_ADDR, 0x00, 2, &temp, 1);
        if (ret < 0) {
            perror("pigpio_i2c_mem_read");
            fclose(log_file);
            i2c_client_free(client);
            pigpio_stop();
            exit(EXIT_FAILURE);
        }

        ret = pigpio_i2c_mem_read(client, BMP180_ADDR, 0x01, 2, &press, 1);
        if (ret < 0) {
            perror("pigpio_i2c_mem_read");
            fclose(log_file);
            i2c_client_free(client);
            pigpio_stop();
            exit(EXIT_FAILURE);
        }

        // Validate readings
        if (temp < -10000 || temp > 50000 || press < -1013200 || press > 1100000) {
            fprintf(log_file, "Invalid reading: %d, %d\n", temp, press);
            fclose(log_file);
            i2c_client_free(client);
            pigpio_stop();
            exit(EXIT_FAILURE);
        }

        // Log readings
        sprintf(log_msg, "%d, %d\n", temp, press);
        fprintf(log_file, log_msg);
        fflush(log_file);

        // Sleep
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    i2c_client_free(client);
    pigpio_stop();
    close(i2c_fd);
    return 0;
}

