#define FAN_GPIO 18
#define PWM_FREQ 25000
#define TEMP_THRESHOLD_LOW 40
#define TEMP_THRESHOLD_HIGH 70
#define LOG_INTERVAL 5000

void log_to_file(const char *timestamp, int temp, int duty) {
    int log_fd = open("fan_log.txt", O_APPEND | O_CREAT, S_IRUSR | S_IWUSR);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return;
    }
    char log_msg[1024];
    sprintf(log_msg, "%s: Temp: %d, Duty: %d\n", timestamp, temp, duty);
    write(log_fd, log_msg, strlen(log_msg));
    close(log_fd);
}

int main(int argc, char *argv[]) {
    int fan_gpio = FAN_GPIO;
    int pwm_freq = PWM_FREQ;
    int temp_threshold_low = TEMP_THRESHOLD_LOW;
    int temp_threshold_high = TEMP_THRESHOLD_HIGH;
    int log_interval = LOG_INTERVAL;

    if (init_pigpio() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int temp_file_path = "/sys/class/thermal/thermal_zone0/temp";
        int temp;
        if ((temp = read(temp_file_path, &temp, sizeof(temp)) != sizeof(temp)) < 0) {
            fprintf(stderr, "Failed to read CPU temperature.\n");
            continue;
        }

        if (temp < temp_threshold_low) {
