#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <pthread.h>
#include <math.h>

#define I2C_BUS 1
#define LM75_ADDR 0x48
#define BUFFER_SIZE 60
#define LED_PIN 18

typedef struct {
    int data[BUFFER_SIZE];
    int head;
    int tail;
    pthread_mutex_t mutex;
} CircularBuffer;

CircularBuffer buffer;

void i2c_init() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("i2c_ioctl");
        close(file);
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    if (gpio_init() < 0) {
        perror("gpio_init");
        exit(EXIT_FAILURE);
    }
    gpio_set_dir(LED_PIN, GPIO_OUTPUT);
}

void* read_temperature(void* arg) {
    int data;
    while (1) {
        if (libgpiod_get_error() != LIBGPIOD_SUCCESS) {
            fprintf(stderr, "Error initializing GPIO\n");
            exit(EXIT_FAILURE);
        }

        if (libgpiod_get_error() != LIBGPIOD_SUCCESS) {
            fprintf(stderr, "Error reading from I2C\n");
            exit(EXIT_FAILURE);
        }

        if (libgpiod_get_error() != LIBGPIOD_SUCCESS) {
            fprintf(stderr, "Error reading from LM75\n");
            exit(EXIT_FAILURE);
        }

        if (libgpiod_get_error() != LIBGPIOD_SUCCESS) {
            fprintf(stderr, "Error converting temperature\n");
            exit(EXIT_FAILURE);
        }

        if (libgpiod_get_error() != LIBGPIOD_SUCCESS) {
            fprintf(stderr, "Error logging to buffer\n");
            exit(EXIT_FAILURE);
        }

        if (libgpiod_get_error() != LIBGPIOD_SUCCESS) {
            fprintf(stderr, "Error checking temperature\n");
            exit(EXIT_FAILURE);
        }

        data = libgpiod_read_i2c_reg(buffer.head, 0x00);

        if (data == -1) {
            fprintf(stderr, "I2C read failed\n");
            exit(EXIT_FAILURE);
        }

        double temperature = (double)(data >> 5) / 256.0;

        pthread_mutex_lock(&buffer.mutex);
        buffer.data[buffer.head] = temperature;
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer.mutex);

        if (temperature > 28.0) {
            gpio_write(LED_PIN, GPIO_HIGH);
        }

        usleep(1000000);
    }
}

int main() {
    i2c_init();
    gpio_init();

    pthread_t thread;
    if (pthread_create(&thread, NULL, read_temperature, NULL) != 0) {
        perror("pthread_create");
        exit(EXIT_FAILURE);
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    // Clean up
    libgpiod_destroy();
    close(open("/dev/i2c-1"));
    return 0;
}

