#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define BREACH_TEMP 30.0
#define BREACH_PRESSURE 950.0
#define LOG_FILE "breach_log.txt"
#define RETRY_COUNT 3

typedef struct {
    int fd;
    struct i2c_client *client;
    int temperature;
    int pressure;
} BMP180_context;

static void log_breach(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s\n", message);
    fclose(file);
}

static void write_to_i2c(int fd, unsigned char *read_buf, size_t read_len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }
    if (write(fd, read_buf, read_len) != read_len) {
        perror("Failed to write to I2C device");
        return;
    }
}

static int read_from_i2c(int fd, unsigned char *read_buf, size_t read_len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (read(fd, read_buf, read_len) != read_len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

static int bmp180_read_data(BMP180_context *ctx) {
    int ret = 0;
    unsigned char buf[6];

    ret = read_from_i2c(ctx->fd, buf, sizeof(buf));
    if (ret < 0) {
        log_breach("Failed to read from BMP180 sensor");
        return ret;
    }

    ctx->temperature = (buf[0] << 8) | buf[1];
    ctx->pressure = buf[2];

    return ret;
}

static void calibrate_temp(int *temp, int *cal) {
    // BMP180 calibration formula (integer arithmetic)
    *temp = (*cal * (*temp / 1000.0) + 0.004) * 100;
}

static void calibrate_press(int *press, int *cal) {
    // BMP180 calibration formula (integer arithmetic)
    *press = (*cal * (*press / 1000.0) + 0.006) * 100;
}

static void check_breaches(BMP180_context *ctx) {
    int temp = ctx->temperature;
    int press = ctx->pressure;

    if (temp > BREACH_TEMP) {
        log_breach("Temperature breach: %d°C", temp);
    }
    if (press < BREACH_PRESSURE) {
        log_breach("Pressure breach: %d hPa", press);
    }
}

int main(int argc, char *argv[]) {
    pthread_t thread;
    BMP180_context ctx;
    ctx.fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (ctx.fd < 0) {
        perror("Failed to open log file");
        return 1;
    }

    ctx.client = i2c_alloc(I2C_BUS);
    if (!ctx.client) {
        perror("Failed to allocate i2c client");
        close(ctx.fd);
        return 1;
    }

    if (ioctl(ctx.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        i2c_free(&ctx.client);
        close(ctx.fd);
        return 1;
    }

    for (int retry = 0; retry < RETRY_COUNT; retry++) {
        bmp180_read_data(&ctx);
        calibrate_temp(&ctx.temperature, 13); // Example calibration factor
        calibrate_press(&ctx.pressure, 253); // Example calibration factor

        check_breaches(&ctx);

        usleep(1000000); // Sleep for 1 second
    }

    i2c_free(&ctx.client);
    close(ctx.fd);
    return 0;
}

