#define BMP180_ADDR 0x77
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_MS 500
#define FAN_GPIO 18

#define BMP180_CALIB_REG 0xAA
#define BMP180_TEMP_REG 0x3B
#define BMP180_PRESS_REG 0x4B
#define BMP180_STATUS_REG 0x00
#define BMP180_DATA_REG 0x2D

typedef struct {
    unsigned char timestamp;
    float temperature;
    float pressure;
} BMPReading;

BMPReading buffer[BUFFER_SIZE];
int head = 0, tail = 0;

void i2c_init() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("i2c_ioctl");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_write(unsigned short address, unsigned char *data, unsigned int len) {
    if (len > 0) {
        if (write(fd, data, len) != len) {
            perror("i2c_write");
            exit(EXIT_FAILURE);
        }
    }
}

unsigned char i2c_read(unsigned short address, unsigned short reg) {
    unsigned char data;
    if (read(fd, &data, 1) != 1) {
        perror("i2c_read");
        exit(EXIT_FAILURE);
    }
    return data;
}

void bmp180_read_calibration_table() {
    unsigned char calibration_table[11];
    i2c_write(BMP180_ADDR, &calibration_table, sizeof(calibration_table));

    if (i2c_read(BMP180_ADDR, BMP180_CALIB_REG) != 11) {
        perror("bmp180_read_calibration_table");
        exit(EXIT_FAILURE);
    }

    // Validate calibration table (check for valid values)
    for (int i = 0; i < 11; i++) {
        if (calibration_table[i] < 0x01 || calibration_table[i] > 0x7F) {
            perror("Invalid calibration table value");
            exit(EXIT_FAILURE);
        }
    }
}

void bmp180_read_temperature_and_pressure() {
    unsigned char temp_reg_data, press_reg_data;

    i2c_write(BMP180_ADDR, &temp_reg_data, 1);
    i2c_write(BMP180_ADDR, &press_reg_data, 1);

    if (i2c_read(BMP180_ADDR, BMP180_TEMP_REG) != 2) {
        perror("bmp180_read_temperature_and_pressure");
        exit(EXIT_FAILURE);
    }

    unsigned int temp_reg_value = temp_reg_data;
    unsigned int press_reg_value = press_reg_data;

    // Apply compensation (not inside pressure function)
    float compensated_temp = (temp_reg_value >> 3) & 0x07;
    float compensated_press = (press_reg_value >> 3) & 0x0F;

    // Convert to °C and Pa
    float temperature = compensated_temp * 0.01;
    float pressure = compensated_press * 100.0;

    // Check if temperature exceeds 30°C
    if (temperature > 30.0) {
        gpioOutput(FAN_GPIO, 1);
    } else {
        gpioOutput(FAN_GPIO, 0);
    }
}

void timer_callback(int timer_id) {
    static unsigned long last_update = 0;
    unsigned long current_time = micros();

    if (current_time - last_update > SAMPLE_INTERVAL_MS / 1000) {
        last_update = current_time;

        // Read from BMP180
        unsigned char read_buffer[2];
        i2c_write(BMP180_ADDR, read_buffer, 1);

        if (i2c_read(BMP180_ADDR, BMP180_DATA_REG) != 2) {
            perror("bmp180_read_data");
            return;
        }

        // Read calibration table
        bmp180_read_calibration_table();

        // Read temperature and pressure
        bmp180_read_temperature_and_pressure();

        // Store reading in buffer
        buffer[tail] = (BMPReading){current_time, temperature, pressure};
        tail = (tail + 1) % BUFFER_SIZE;

        // Print new reading
        printf("Timestamp: %lu °C, Pressure: %f Pa\n", buffer[head].temperature, buffer[head].pressure);
        head = (head + 1) % BUFFER_SIZE;
    }
}

int main() {
    i2c_init();

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("pigpio_initialise");
        exit(EXIT_FAILURE);
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, GPIO_OUTPUT);

    // Start timer callback
    timer_id_t timer_id = timerAdd(SAMPLE_INTERVAL_MS / 1000, timer_callback, NULL);
    if (timer_id < 0) {
        perror("timer_add");
        exit(EXIT_FAILURE);
    }

    // Keep the program running
    while (1) {
        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

