#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_ADDRESS 0x77
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_TIME 200000  // 200 ms in microseconds
#define LOG_INTERVAL 2000000  // 2 seconds in microseconds

#define GPIO27 27

void toggle_logging(int flag) {
    if (flag) {
        printf("Logging enabled\n");
    } else {
        printf("Logging disabled\n");
    }
}

void debounced_edge_detected(int pin) {
    static unsigned long last_edge_time = 0;
    unsigned long current_time = microtime_us();

    if (current_time - last_edge_time > DEBOUNCE_TIME) {
        last_edge_time = current_time;
        toggle_logging(1);
    }
}

void read_bmp180(int *pressure) {
    int i2c_fd, ret;
    struct i2c_client i2c_handle;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        return;
    }

    memset(&i2c_handle, 0, sizeof(i2c_handle));
    i2c_handle.file = i2c_fd;
    i2c_handle.address = I2C_ADDRESS;

    ret = pigpio_i2c_transaction(&i2c_handle, 0x77, 0x6B, 2, (uint8_t *)pressure, 4);
    if (ret < 0) {
        perror("I2C communication error");
        return;
    }

    close(i2c_fd);
}

void log_pressure(int pressure) {
    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s: %d Pa\n", timestamp, pressure);
    fclose(file);
}

void periodic_logging() {
    while (1) {
        int pressure;
        read_bmp180(&pressure);
        log_pressure(pressure);
        usleep(LOG_INTERVAL / 1000);  // Convert microseconds to seconds
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up resources...\n", signum);
    pigpio_terminate();
    close(GPIO27);
    unlink(LOG_FILE);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int gpio_fd, ret;
    ret = pigpio_init(1);
    if (ret < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    ret = pigpio_set_mode(GPIO27, PIGIO_OUTPUT);
    if (ret < 0) {
        perror("Failed to set GPIO27 as output");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    debounced_edge_detected(GPIO27);

    periodic_logging();

    pigpio_terminate();
    close(GPIO27);
    unlink(LOG_FILE);

    return EXIT_SUCCESS;
}

