This code sets up a Raspberry Pi 4 Model B to read pressure data from a BMP180 sensor connected via I2C, logging the readings to a file named `pressure_log.txt`. The logging is toggled by detecting a falling edge on GPIO27, with a debouncing mechanism to prevent multiple readings from a single press. The program runs in a loop, periodically reading the sensor and logging the pressure data every 2 seconds. It handles I2C communication errors and pigpio initialization failures gracefully, ensuring a clean exit upon receiving a SIGINT or SIGTERM signal.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>

#define MAX_TEMP_ERROR_COUNT 10
#define MAX_TEMP_ERROR_TIME (60 * 60) // 1 hour
#define MAX_DUTY_CYCLE 80
#define TARGET_TEMPERATURE 25.0

#define SPI_CS_PIN 8
#define SPI_MISO_PIN 9
#define SPI_MOSI_PIN 10
#define SPI_SCLK_PIN 11
#define MAX31855_ADDRESS 0x48

#define LOG_FILE "heater_log.csv"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S,%f,%.2f,%.2f"

void spi_init();
void pigpio_init();
void pigpio_deinit();
void spi_read_max31855();
void log_temperature_and_duty_cycle(float temp, int duty_cycle);
void pi_controller(float setpoint, float actual, float &output);
void handle_error(const char *msg);
void handle_shutdown();

int main(int argc, char *argv[]) {
    int rpi_gpio_pin = 17;
    int pigpio_fd;
    int spi_fd;
    int max31855_cs_pin;
    float target_temp = TARGET_TEMPERATURE;
    float current_temp = 0.0;
    int duty_cycle = 0;
    time_t last_error_time = 0;
    int error_count = 0;

    spi_init();
    pigpio_init();

    while (1) {
        // Read temperature from MAX31855
        spi_read_max31855();

        // PI controller
        pi_controller(target_temp, current_temp, duty_cycle);

        // Log temperature and duty cycle
        log_temperature_and_duty_cycle(current_temp, duty_cycle);

        // Check for errors
        if (error_count > MAX_TEMP_ERROR_COUNT) {
            handle_error("Too many temperature errors in the last hour.");
            break;
        }

        // Check for SPI read failure or MAX31855 fault
        if (errno == EIO || (current_temp < 100 || current_temp > 500)) {
            handle_error("MAX31855 fault or SPI read failure. Setting duty cycle to 0%.");
            duty_cycle = 0;
            error_count++;
            last_error_time = time(NULL);
        }

        // Apply duty cycle to heater
        gpioSetup(rpi_gpio_pin, PI_OUTPUT);
        gpioWrite(rpi_gpio_pin, duty_cycle);

        // Sleep for a short period to avoid CPU overload
        usleep(10000);
    }

    pigpio_deinit();
    close(pigpio_fd);
    close(spi_fd);
    remove(LOG_FILE);
    exit(0);
}

void spi_init() {
    max31855_cs_pin = 8;
    spi_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (spi_fd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }
}

void pigpio_init() {
    pigpio_fd = pigpio_open(0);
    if (pigpio_fd == -1) {
        perror("Error opening pigpio");
        exit(EXIT_FAILURE);
    }
}

void pigpio_deinit() {
    pigpio_close(pigpio_fd);
    close(pigpio_fd);
}

void spi_read_max31855() {
    uint16_t data;
    int ret = spiTransfer(pigpio_fd, MAX31855_ADDRESS, 0x49, &data, 2);
    if (ret < 0) {
        handle_error("SPI read error from MAX31855.");
        return;
    }

    current_temp = (data >> 8) * 0.025; // Convert to Celsius
}

void log_temperature_and_duty_cycle(float temp, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp[32];
    sprintf(timestamp, LOG_FORMAT, time_info->tm_year + 1900,
            time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
            (int)duty_cycle);

    FILE* log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("Error opening log file for writing.");
        return;
    }
    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

void pi_controller(float setpoint, float actual, float &output) {
    float error = setpoint - actual;
    float integral = error;
    float derivative = 0;

    if (error > 0) {
        derivative = error;
    } else {
        derivative = 0;
    }

    output = error + integral + derivative;

    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    }

    if (output < 0) {
        output = 0;
    }
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    error_count++;
    last_error_time = time(NULL);
}

void handle_shutdown() {
    log_temperature_and_duty_cycle(current_temp, duty_cycle);
    gpioWrite(rpi_gpio_pin, 0);
    spi_close();
    pigpio_close(pigpio_fd);
    remove(LOG_FILE);
    exit(0);
}

void spi_close() {
    close(spi_fd);
}

