            handle_error("MAX31855 fault or SPI read failure. Setting duty cycle to 0%.");
            duty_cycle = 0;
            error_count++;
            last_error_time = time(NULL);
        }

        // Apply duty cycle to heater
        gpioSetup(rpi_gpio_pin, PI_OUTPUT);
        gpioWrite(rpi_gpio_pin, duty_cycle);

        // Sleep for a short period to avoid CPU overload
        usleep(10000);
    }

    pigpio_deinit();
    close(pigpio_fd);
    close(spi_fd);
    remove(LOG_FILE);
    exit(0);
}

void spi_init() {
    max31855_cs_pin = 8;
    spi_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (spi_fd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }
}

void pigpio_init() {
    pigpio_fd = pigpio_open(0);
    if (pigpio_fd == -1) {
        perror("Error opening pigpio");
        exit(EXIT_FAILURE);
    }
}

void pigpio_deinit() {
    pigpio_close(pigpio_fd);
    close(pigpio_fd);
}

void spi_read_max31855() {
    uint16_t data;
    int ret = spiTransfer(pigpio_fd, MAX31855_ADDRESS, 0x49, &data, 2);
    if (ret < 0) {
        handle_error("SPI read error from MAX31855.");
        return;
    }

    current_temp = (data >> 8) * 0.025; // Convert to Celsius
}

void log_temperature_and_duty_cycle(float temp, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp[32];
    sprintf(timestamp, LOG_FORMAT, time_info->tm_year + 1900,
            time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
            (int)duty_cycle);

    FILE* log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("Error opening log file for writing.");
        return;
    }
    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

void pi_controller(float setpoint, float actual, float &output) {
    float error = setpoint - actual;
    float integral = error;
    float derivative = 0;

    if (error > 0) {
        derivative = error;
    } else {
        derivative = 0;
    }

    output = error + integral + derivative;

    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    }

    if (output < 0) {
        output = 0;
    }
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    error_count++;
    last_error_time = time(NULL);
}

void handle_shutdown() {
    log_temperature_and_duty_cycle(current_temp, duty_cycle);
    gpioWrite(rpi_gpio_pin, 0);
    spi_close();
    pigpio_close(pigpio_fd);
    remove(LOG_FILE);
    exit(0);
}

void spi_close() {
    close(spi_fd);
}

