#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define LOG_FILE "pressure_log.txt"
#define BUTTON_GPIO 4
#define DEBOUNCE_US 200000
#define OSS 3
#define CONVERSION_DELAY (26 * 1000) // 26 ms

#define BMP180_CAL_REG_START 0xAA
#define BMP180_CAL_REG_END 0xBE

int logging_enabled = 0;

void bmp180_init() {
    int file;
    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_REQUEST) == -1) {
        perror("ioctl I2C_REQUEST");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SMC_ENABLE) == -1) {
        perror("ioctl I2C_SMC_ENABLE");
        close(file);
        exit(EXIT_FAILURE);
    }
}

void bmp180_read_calibration_coefficients() {
    int reg_start, reg_end;
    if (ioctl(file, I2C_READ_REG, BMP180_CAL_REG_START) == -1) {
        perror("I2C_READ_REG");
        return;
    }
    reg_start = read(file, &reg_start, 2);
    if (reg_start != 2) {
        perror("I2C_READ_REG");
        return;
    }

    if (ioctl(file, I2C_READ_REG, BMP180_CAL_REG_END) == -1) {
        perror("I2C_READ_REG");
        return;
    }
    reg_end = read(file, &reg_end, 2);
    if (reg_end != 2) {
        perror("I2C_READ_REG");
        return;
    }

    if (reg_start != 0xAA || reg_end != 0xBE) {
        fprintf(stderr, "BMP180 sensor not found or invalid calibration data.\n");
        exit(EXIT_FAILURE);
    }
}

void bmp180_read_pressure() {
    int reg_start, reg_end;
    if (ioctl(file, I2C_READ_REG, 0x68) == -1) {
        perror("I2C_READ_REG");
        return;
    }
    reg_start = read(file, &reg_start, 2);
    if (reg_start != 2) {
        perror("I2C_READ_REG");
        return;
    }

    if (ioctl(file, I2C_READ_REG, 0x69) == -1) {
        perror("I2C_READ_REG");
        return;
    }
    reg_end = read(file, &reg_end, 2);
    if (reg_end != 2) {
        perror("I2C_READ_REG");
        return;
    }

    int pressure_raw = reg_start | (reg_end << 8);
    int pressure_hpa = (pressure_raw >> 16) * 100;

    // Bosch BMP180 compensation algorithm
    int temp_raw = reg_start & 0x3F;
    int temp_celsius = (temp_raw >> 5) - 40; // Convert to Celsius
    int temp_kelvin = temp_celsius + 273.15;

    int alt_raw = reg_end & 0x3F;
    int alt_hpa = (alt_raw >> 5) * 100;

    // Apply compensation
    int compensated_pressure = pressure_hpa * (1.001015 - 0.000005 * temp_kelvin);
    int compensated_altitude = alt_hpa * (1.000005 + 0.00000005 * temp_kelvin);

    // Timestamp
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[32];
    sprintf(timestamp, "%0.6f", (double)tv.tv_sec);
    strcat(timestamp, ".");
    strcat(timestamp, "000000");

    // Write to log file
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    fprintf(fp, "%s %d\n", timestamp, compensated_pressure);
    fclose(fp);
}

void button_isr(int event, int gpio) {
    if (event & PI_READ) {
        if (gpio == BUTTON_GPIO && gpio == LOW) {
            logging_enabled = !logging_enabled;
            if (logging_enabled) {
                printf("Logging enabled\n");
            } else {
                printf("Logging disabled\n");
            }
        }
    }
}

int main() {
    bmp180_init();
