    int pressure_hpa = (pressure_raw >> 16) * 100;

    // Bosch BMP180 compensation algorithm
    int temp_raw = reg_start & 0x3F;
    int temp_celsius = (temp_raw >> 5) - 40; // Convert to Celsius
    int temp_kelvin = temp_celsius + 273.15;

    int alt_raw = reg_end & 0x3F;
    int alt_hpa = (alt_raw >> 5) * 100;

