#define DHT22_PIN 7
#define SENS_TIMEOUT 10000  // 10 seconds
#define RETRY_COUNT 3
#define BACKOFF_SEC 2
#define DEFAULT_URL "http://your-server.com/api/humidity"

#define JSON_CONTENT_TYPE "application/json"

void dht22_read(int pin) {
    gpioInitialise();
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);

    gpioTimingStart(pin, 1000);  // Pull low for 1 ms
    gpioWrite(pin, 0);
    sleep_us(20000);  // Wait for 20 µs
    gpioWrite(pin, 1);
    sleep_us(1000);  // Wait for 1 ms
    gpioWrite(pin, 0);

    int data[6];
    gpioRead(pin, 4, 4096);
    for (int i = 0; i < 6; i++) {
        data[i] = gpioRead(pin, 1);
    }

    // Checksum validation (simplified, actual DHT22 checksum calculation)
    int checksum = data[5] + (data[4] << 8) + (data[3] << 16) + (data[2] << 24) + (data[1] << 32) + data[0];
    if (checksum != 0x3F) {
        syslog(LOG_ERR, "DHT22 checksum failed, retrying...");
        return;
    }

    // DHT22 response parsing (simplified, actual parsing)
    int humidity = (data[0] << 8) | data[1];
    syslog(LOG_INFO, "DHT22 humidity: %d%%", humidity);
}

int curl_init_http_post(const char* url, const char* json_data) {
    CURL *curl;
    CURLcode res;
    char error_buf[128];

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, (const char*)JSON_CONTENT_TYPE);
        headers = curl_slist_append(headers, (const char*)"Content-Length: 1");
        headers = curl_slist_append(headers, (const char*)"Content-Type: application/json");
        headers = curl_slist_append(headers, (const char*)"Connection: close");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "HTTP POST failed: %s", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
            return 1;
        }
        curl_slist_free_all(headers);
    }
    curl_global_cleanup();
    return 0;
}

int main(int argc, char *argv[]) {
    int pin = DHT22_PIN;
    char url[1024];
    int retries = RETRY_COUNT;
    int backoff_seconds = BACKOFF_SEC;

    if (argc > 1) {
        snprintf(url, sizeof(url), DEFAULT_URL);
        strncpy(url + strlen(url), argv[1], sizeof(url) - strlen(url));
    }

    while (1) {
        dht22_read(pin);
        if (retries == 0) {
            syslog(LOG_ERR, "DHT22 sensor not present, exiting.");
            break;
        }
        retries--;
        sleep(SENS_TIMEOUT);
    }

    if (retries > 0) {
        char json_data[1024];
        snprintf(json_data, sizeof(json_data), "{\"humidity\": %d}", (int)humidity);
        int success = curl_init_http_post(url, json_data);
        if (success) {
            syslog(LOG_INFO, "Humidity data posted successfully.");
        } else {
            syslog(LOG_ERR, "Failed to post humidity data, retrying in %d seconds...", backoff_seconds);
            usleep(backoff_seconds * 1000000);
        }
    }

    gpioTerminate();
    return 0;
}

