#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <time.h>

#define LOG_FILE "/var/log/fan_control.log"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_CONTROL_FILE "/sys/class/thermal/cooling_device0/cur_state"

enum FanState {
    OFF = 0,
    LOW = 1,
    MEDIUM = 2,
    HIGH = 3
};

enum FanState getFanState(int temp) {
    if (temp < 45) return OFF;
    else if (temp < 55) return LOW;
    else if (temp < 65) return MEDIUM;
    else return HIGH;
}

int setFanState(int state) {
    int max_state = 0;
    int ret = readlink("/sys/class/thermal/cooling_device0/max_state", NULL, 256);
    if (ret == -1) {
        perror("readlink");
        return -1;
    }
    max_state = atoi(strtok(NULL, ":"));

    if (state > max_state) {
        return -1; // Requested state is higher than max
    }

    ret = write(open(FAN_CONTROL_FILE, "w"), &state, sizeof(state));
    if (ret == -1) {
        perror("write");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int fan_state = OFF;
    int retry_count = 0;
    int temp_read_count = 0;

    while (1) {
        int temp;
        do {
            temp = read_temp(TEMP_FILE);
            if (temp == -1) {
                retry_count++;
                if (retry_count > 5) {
                    fprintf(LOG_FILE, "Error reading temperature from %s\n", TEMP_FILE);
                    break;
                }
                usleep(5000000); // Wait for 5 seconds
            }
        } while (temp == -1);

        fan_state = getFanState(temp);
        int ret = setFanState(fan_state);
        if (ret == -1) {
            fprintf(LOG_FILE, "Failed to set fan state, retrying...\n");
        } else {
            fprintf(LOG_FILE, "Fan state set to %d at %llu ms\n", fan_state, (long long)temp);
        }

        usleep(5000000); // Wait for 5 seconds
    }

    return 0;
}

int read_temp(const char *path) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        close(fd);
        perror("fstat");
        return -1;
    }

    char buffer[10];
    ssize_t read_bytes = read(fd, buffer, sizeof(buffer));
    close(fd);

    if (read_bytes == -1) {
        perror("read");
        return -1;
    }

    buffer[read_bytes] = '\0';
    temp_t temp = strtol(buffer, NULL, 10);
    if (temp_t_to_millidegrees(temp) == -1) {
        fprintf(stderr, "Failed to convert temperature to millidegrees\n");
        return -1;
    }

    return temp;
}

int temp_t_to_millidegrees(temp_t t) {
    return t * 1000;
}

