#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define FAN_PIN 12
#define PWM_FREQUENCY 25000
#define TEMP_FILE_PATH "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

void handle_signal(int signum) {
    printf("Received signal %d, shutting down fan.\n", signum);
    gpioOutput(FAN_GPIO, 0);
    close(logfd);
    exit(0);
}

int main() {
    int logfd;
    struct stat st;

    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Open log file for writing
    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("Failed to open log file");
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up PWM frequency
    gpioFrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set up signal handler for SIGINT/SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Read initial temperature
    FILE *temp_file = fopen(TEMP_FILE_PATH, "r");
    if (!temp_file) {
        perror("Failed to open temperature file");
        close(logfd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }
    long temp_value;
    fscanf(temp_file, "%ld", &temp_value);
    fclose(temp_file);

    // Main loop
    while (1) {
        // Read current temperature
        temp_file = fopen(TEMP_FILE_PATH, "r");
        if (!temp_file) {
            perror("Failed to open temperature file");
            break;
        }
        long temp_value_new;
        fscanf(temp_file, "%ld", &temp_value_new);
        fclose(temp_file);

        // Calculate PWM duty cycle
        double temp_c = temp_value_new - 40;
        double duty_cycle = 100.0 * (temp_c / 20.0);

        // Set PWM duty cycle
        gpioPWM(FAN_GPIO, 0, duty_cycle);

        // Log data
        char timestamp[20], temp_str[10], duty_str[10];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        sprintf(temp_str, "%.1f", temp_value_new / 1000.0);
        sprintf(duty_str, "%.0f", duty_cycle);
        fprintf(logfd, "%s,%.1f,%.0f\n", timestamp, temp_value_new, duty_cycle);

        // Sleep for 5 seconds
        usleep(50000000);
    }

    // Close log file
    fclose(logfd);
    close(logfd);

    // Terminate pigpio
    pigpioTerminate();

    return EXIT_SUCCESS;
}

