#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENS_ADDR_SLF3S_1 0x08
#define SENS_ADDR_SLF3S_2 0x09
#define COMMAND 0x3608
#define DATA_BYTES 3
#define CRC_BYTES 1
#define LOG_FILE "flow_log.txt"

void log_flow_rate(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }
    fprintf(log_file, "%s,%.2f,%.2f\n", time_str, flow1, flow2);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    int ret;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    log_flow_rate(0.0, 0.0); // Initial log entry

    pigpio_init(I2C_BUS);

    i2c_fd = pigpio_open_bus(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        pigpio_close_bus(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ret = pigpio_setup_i2c(i2c_fd);
    if (ret < 0) {
        fprintf(stderr, "Failed to setup I2C bus.\n");
        pigpio_close_bus(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ret = pigpio_write_i2c_reg(i2c_fd, SENS_ADDR_SLF3S_1, COMMAND);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to sensor 1.\n");
        pigpio_close_bus(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ret = pigpio_write_i2c_reg(i2c_fd, SENS_ADDR_SLF3S_2, COMMAND);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to sensor 2.\n");
        pigpio_close_bus(i2c_fd);
        exit(EXIT_FAILURE);
    }

    for (int retry = 0; retry < 3; ++retry) {
        ret = pigpio_read_i2c_byte(i2c_fd, SENS_ADDR_SLF3S_1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from sensor 1.\n");
            continue;
        }

        uint8_t crc = pigpio_read_i2c_byte(i2c_fd, SENS_ADDR_SLF3S_1 + 1);
        if (crc < 0) {
            fprintf(stderr, "Failed to read CRC from sensor 1.\n");
            continue;
        }

        uint16_t data1 = pigpio_read_i2c_byte(i2c_fd, SENS_ADDR_SLF3S_1 + 2);
        uint16_t data2 = pigpio_read_i2c_byte(i2c_fd, SENS_ADDR_SLF3S_1 + 3);

        if (crc != (data1 | (data2 << 8))) {
            fprintf(stderr, "CRC check failed for sensor 1.\n");
            continue;
        }

        float flow1 = (float)data1 * 0.01;
        log_flow_rate(flow1, 0.0);

        ret = pigpio_read_i2c_byte(i2c_fd, SENS_ADDR_SLF3S_2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from sensor 2.\n");
            continue;
        }

        crc = pigpio_read_i2c_byte(i2c_fd, SENS_ADDR_SLF3S_2 + 1);
        if (crc < 0) {
            fprintf(stderr, "Failed to read CRC from sensor 2.\n");
            continue;
        }

        uint16_t data3 = pigpio_read_i2c_byte(i2c_fd, SENS_ADDR_SLF3S_2 + 2);
        uint16_t data4 = pigpio_read_i2c_byte(i2c_fd, SENS_ADDR_SLF3S_2 + 3);

        if (crc != (data3 | (data4 << 8))) {
            fprintf(stderr, "CRC check failed for sensor 2.\n");
            continue;
        }

        float flow2 = (float)data3 * 0.01;
        log_flow_rate(0.0, flow2);

        usleep(1000000); // Sleep for 1 second
    }

    pigpio_close_bus(i2c_fd);
    pigpio_terminate();

    return 0;
}

