#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 18
#define ENCODER_LOG "encoder_log.txt"
#define MAX_ENTRIES 1000
#define SAMPLE_INTERVAL 100

typedef struct {
    int timestamp;
    double angular_position;
} LogEntry;

static LogEntry log_entries[MAX_ENTRIES];
int log_entries_count = 0;

void handle_interrupt(int sig) {
    pigpio_stop();
    fclose(stdout);
    fclose(stderr);
    fclose(encoder_log);
    printf("Exiting...\n");
    exit(0);
}

void setup_encoder() {
    if (pigpio_init(5) != 0) {
        perror("Failed to initialize pigpio");
        exit(1);
    }

    gpioSetMode(GPIO_A, PI_OUTPUT);
    gpioSetMode(GPIO_B, PI_OUTPUT);

    gpioSetPullUp(GPIO_A);
    gpioSetPullUp(GPIO_B);

    gpioWrite(GPIO_A, 0);
    gpioWrite(GPIO_B, 0);
}

void read_encoder_state() {
    static int state_a = 0;
    static int state_b = 0;

    state_a = gpioRead(GPIO_A);
    state_b = gpioRead(GPIO_B);

    if (state_a != state_a_prev) {
        log_entry(state_a, state_b);
        state_a_prev = state_a;
    }

    if (state_entries_count < MAX_ENTRIES) {
        log_entries[state_entries_count].timestamp = micros();
        log_entries[state_entries_count].angular_position = (double)state_a * 3.141592653589793 / 180.0;
        state_entries_count++;
    }
}

void log_entry(int state_a, int state_b) {
    FILE *fp = fopen(ENCODER_LOG, "a");
    if (!fp) {
        perror("Failed to open encoder_log.txt");
        return;
    }

    fprintf(fp, "%d %d\n", state_a, state_b);
    fclose(fp);
}

int main() {
    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    setup_encoder();

    while (1) {
        read_encoder_state();
        usleep(SAMPLE_INTERVAL);
    }

    pigpio_stop();
    fclose(stdout);
    fclose(stderr);
    fclose(encoder_log);
    return 0;
}
```

This code initializes the pigpio library, configures GPIO pins for open-drain output with internal pull-ups, and sets up a 2-bit quadrature state machine to track encoder rotation. It logs every state change with a timestamp and normalized angular position to `encoder_log.txt`. The program handles errors during initialization and resource release on SIGINT/SIGTERM.

