#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define FIFO_REG 0x60
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL 100
#define RED_THRESHOLD 2000

int i2c_fd;
int gpio_led = 17;

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

int setup_gpio() {
    int ret;

    ret = gpio_request(gpio_led, "adpd17_led");
    if (ret < 0)
        handle_error("Failed to request GPIO 17");

    ret = gpio_set_direction(gpio_led, GPIO_OUTPUT);
    if (ret < 0)
        handle_error("Failed to set GPIO 17 as output");

    return ret == 0;
}

int setup_i2c() {
    int ret;

    i2c_fd = i2c_open(I2C_BUS, "i2c-dev");
    if (i2c_fd < 0)
        handle_error("Failed to open I2C bus");

    return ret == 0;
}

void read_adpd144ri() {
    uint16_t red, ir;
    struct i2c_msg msg;

    msg.addr = ADPD144RI_ADDR;
    msg.len = 2;
    msg.data = &red;

    i2c_transfer(i2c_fd, &msg, sizeof(msg.data));

    if (msg.status != I2C_MSG_OK)
        handle_error("I2C read failed");

    msg.addr = ADPD144RI_ADDR;
    msg.len = 2;
    msg.data = &ir;

    i2c_transfer(i2c_fd, &msg, sizeof(msg.data));

    if (msg.status != I2C_MSG_OK)
        handle_error("I2C read failed");

    if (ir > RED_THRESHOLD) {
        gpio_set_level(gpio_led, 1);
    }
}

void log_reading(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("Failed to open log file for writing");
        return;
    }

    fprintf(log_file, "%s, %d, %d\n", timestamp, red, ir);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        fprintf(stderr, "Usage: %s <command> [options]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int cmd = atoi(argv[1]);

    if (cmd == 0) {
        if (!setup_gpio() || !setup_i2c()) {
            return EXIT_FAILURE;
        }

        while (1) {
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            read_adpd144ri();
            log_reading(timestamp);

            usleep(SAMPLE_INTERVAL * 1000 / 1000);
        }
    } else if (cmd == 1) {
        // Handle shutdown command
        // Clean up resources and exit
        // ...
    }

    return EXIT_SUCCESS;
}

