#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define MAX_RPM_VALUE 1000000

typedef struct {
    pthread_mutex_t mutex;
    int pulse_count;
    time_t last_timestamp;
} rpm_data;

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    pigpio_terminate();
    fclose(stdout);
    fclose(stderr);
    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    exit(0);
}

void setup_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void log_rpm(double rpm) {
    time_t current_time = time(NULL);
    fprintf(log_file, "%.6f\t%d\n", rpm, current_time);
    fclose(log_file);
}

void* read_rpm(void* arg) {
    rpm_data data;
    pthread_mutex_init(&data.mutex, NULL);
    data.pulse_count = 0;
    data.last_timestamp = time(NULL);

    while (1) {
        int pulse_count = pigpio_get_input(GPIO_PIN);
        pthread_mutex_lock(&data.mutex);
        data.pulse_count += pulse_count - data.last_timestamp;
        data.last_timestamp = time(NULL);
        pthread_mutex_unlock(&data.mutex);

        if (data.pulse_count > 0) {
            double rpm = (double)data.pulse_count / (double)(1000.0 / 60.0);
            log_rpm(rpm);
            data.pulse_count = 0;
        }

        usleep(100000); // Sleep for 100ms
    }

    pthread_mutex_destroy(&data.mutex);
    return NULL;
}

int main(int argc, char* argv[]) {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_logging();

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, read_rpm, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");
    getchar();

    pigpio_terminate();
    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    return 0;
}

