#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define RED_DATA_REG 0x01
#define IR_DATA_REG 0x02
#define LED_GPIO 17
#define LOG_FILE "adpd144ri_log.txt"
#define LOG_INTERVAL 100
#define THRESHOLD 2000

void log_reading(const char *timestamp, int red, int ir) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s,Red:%d,IR:%d\n", timestamp, red, ir);
    fclose(file);
}

int main() {
    int fd;
    struct i2c_client *client;
    int red_data, ir_data;
    char timestamp[32];
    time_t now;

    gpiod_init();
    gpiod_channel_t gpio_channel;
    gpiod_channel_add_output(&gpio_channel, LED_GPIO);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc_clienttobus(fd, ADPD144RI_ADDR);
    if (!client) {
        perror("Failed to allocate I2C client");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        i2c_free_client(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_channel_output_enable(&gpio_channel) < 0) {
        perror("Failed to enable GPIO channel");
        i2c_free_client(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        time_t now_copy = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now_copy));

        if (read(client, &red_data, 1) != 1 ||
            read(client, &ir_data, 1) != 1) {
            perror("Failed to read from I2C device");
            log_reading(timestamp, 0, 0);
            continue;
        }

        if (read(client, &red_data, 1) != 1 ||
            read(client, &ir_data, 1) != 1) {
            perror("Failed to read from I2C device");
            log_reading(timestamp, 0, 0);
            continue;
        }

        if (red_data == 0xFF && ir_data == 0xFF) {
            log_reading(timestamp, 0, 0);
            continue;
        }

        if (ir_data > THRESHOLD) {
            gpio_set_level(LED_GPIO, 1);
        } else {
            gpio_set_level(LED_GPIO, 0);
        }

        log_reading(timestamp, red_data, ir_data);

        usleep(LOG_INTERVAL * 1000 / 1000);
    }

    gpiod_channel_output_disable(&gpio_channel);
    i2c_free_client(client);
    close(fd);
    gpiod_destroy();

    return 0;
}

