#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_IN 17
#define GPIO_OUT 18
#define GAIN_LEVEL 60
#define SAMPLE_INTERVAL 10
#define LOG_FILE "audio_log.txt"

void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    gpiod_exit();
    exit(0);
}

int main() {
    gpiod_context ctx;
    gpiod_config cfg;
    gpiod_result res;

    // Initialize libgpiod
    res = gpiod_init(&ctx);
    if (res != GPIOD_OK) {
        perror("Failed to initialize libgpiod");
        return 1;
    }

    // Configure GPIO 17 as input
    res = gpiod_gpio_export(ctx, GPIO_IN, 0);
    if (res != GPIOD_OK) {
        perror("Failed to export GPIO 17 as input");
        gpiod_exit();
        return 1;
    }

    // Configure GPIO 18 as output, setting GAIN to 60dB
    res = gpiod_gpio_direction_output(ctx, GPIO_OUT, 0);
    if (res != GPIOD_OK) {
        perror("Failed to configure GPIO 18 as output");
        gpiod_exit();
        return 1;
    }

    res = gpiod_gpio_write(ctx, GPIO_OUT, 0);
    if (res != GPIOD_OK) {
        perror("Failed to set GPIO 18 to 60dB gain");
        gpiod_exit();
        return 1;
    }

    // Set up signal handling for SIGINT/SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open audio_log.txt for appending");
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the state of GPIO 17 (input)
        int state = gpiod_get_value(ctx, GPIO_IN);

        // Check for rising edge (logic HIGH)
        if (state == GPIO_INPUT_HIGH) {
            // Get current timestamp
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[80];
            sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec);

            // Log the peak event
            fprintf(log_file, "%s LEVEL\n", timestamp);

            // Reset the state for the next sample
            gpiod_set_value(ctx, GPIO_IN, 0);
        }

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL * 1000000);
    }

    // Clean up and exit
    gpiod_exit();
    fclose(log_file);
    return 0;
}
