#define I2C_BUS 1
#define SENSIRION_ADDR 0x36
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF
#define LOG_FILE "flow_log.csv"
#define LOG_FORMAT "YYYY-MM-DD HH:MM:SS,flow_rate_uL_min"
#define LOG_WRITE_INTERVAL 1000

void log_flow_rate(int flow_rate_uL_min) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fprintf(log_file, "%s,%.2f\n", strftime(NULL, 0, NULL, LOG_FORMAT), flow_rate_uL_min);
    fclose(log_file);
}

int validate_crc(uint16_t raw_value) {
    uint8_t crc = CRC_INIT_VALUE;
    for (int i = 16; i > 0; i--) {
        crc = (crc << 1) ^ (raw_value & 0x01 ? 0x31 : 0x00);
        raw_value >>= 1;
    }
    return crc == 0xFF;
}

int main() {
    int i2c_fd;
    int sensor_address = SENSIRION_ADDR;
    uint16_t command = 0x3608;
    uint16_t raw_value;
    uint8_t crc;

    if (init_pigpio() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = i2c_open(I2C_BUS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_exit();
        return EXIT_FAILURE;
    }

    if (setmode(i2c_fd, I2C_MODE_7BIT) < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        i2c_close(i2c_fd);
        pigpio_exit();
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &command, 2) != 2) {
        fprintf(stderr, "Failed to write command to sensor\n");
        i2c_close(i2c_fd);
        pigpio_exit();
        return EXIT_FAILURE;
    }

    while (1) {
        if (i2c_read(i2c_fd, &raw_value, 3) != 3) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        if (!validate_crc(raw_value)) {
            fprintf(stderr, "CRC validation failed for raw value: 0x%04X\n", raw_value);
            continue;
        }

        float flow_rate_uL_min = (float)raw_value / 1000.0;
        log_flow_rate(flow_rate_uL_min);
    }

    i2c_close(i2c_fd);
    pigpio_terminate();
    return EXIT_SUCCESS;
}

