void log_air_quality(double iaq, double tvoc, double eco2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(fp, "%s, %f, %f, %f\n", timestamp, iaq, tvoc, eco2);
    fclose(fp);
}

