#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <time.h>

#define CHIP_NAME "gpiochip0"
#define LINE_ID 17
#define CONSUMER_LABEL "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_SEC 5

void intrusion_alert(void) {
    fprintf(stdout, "Intrusion detected!\n");
}

void signal_handler(int signum) {
    intrusion_alert();
    gpiod_line_delete(LINE_ID);
    gpiod_chip_delete(CHIP_NAME);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    int fd;
    gpiod_chip_handle_t chip_handle;
    gpiod_line_handle_t line_handle;
    timespec start_time, end_time;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open(CHIP_NAME, O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    gpiod_chip_init(CHIP_NAME, &chip_handle);
    if (gpiod_chip_open(chip_handle, 0) == -1) {
        perror("gpiod_chip_open");
        close(fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_init(chip_handle, LINE_ID, CONSUMER_LABEL);
    if (gpiod_line_output_init(line_handle, LINE_ID) == -1) {
        perror("gpiod_line_output_init");
        gpiod_chip_delete(chip_handle);
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        if (gpiod_line_read(line_handle) == -1) {
            perror("gpiod_line_read");
            break;
        }

        if (gpiod_line_get_value(line_handle) == 1) {
            if (start_time.tv_sec >= INTRUSION_THRESHOLD_SEC) {
                intrusion_alert();
                start_time = clock_gettime(CLOCK_MONOTONIC, NULL);
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &end_time);
