#include <sys/stat.h>
#include <sys/wait.h>
#include <signal.h>

#define PIPE_NAME "/dev/snd/pcmC0D0c"
#define GPIO_ID 17
#define SAMPLE_RATE 44100
#define BUF_SIZE 1024
#define CHUNK_SIZE 2

void handle_sigint(int sig) {
    printf("Capturing audio stopped by user.\n");
    exit(0);
}

int main() {
    pid_t child;
    child = fork();

    if (child) {
        // Parent process
        if (sigset_t sigset) {
            sigset_t sigset_copy;
            sigfillset(&sigset);
            sigprocmask(SIG_BLOCK, &sigset, &sigset_copy);

            // Initialize libgpiod
            gpiod_handle_t handle;
            gpiod_arg_t arg = {GPIO_ID};
            gpiod_channel_t channel;
            gpiod_channel_init(&channel, arg);
            gpiod_channel_output_enable(&channel, GPIOD_OUTPUT);

            // Open ALSA device
            int fd = open(PIPE_NAME, O_RDWR);
            if (fd < 0) {
                perror("Failed to open ALSA device");
                exit(EXIT_FAILURE);
            }

            // Configure I2S settings
            struct alsa_pcm_hw_params params;
            memset(&params, 0, sizeof(params));
            params.format = ALSA_FORMAT_S16_LE;
            params.rate = SAMPLE_RATE;
            params.channels = 1;
            params.period_size = BUF_SIZE;
            params.period_count = (SAMPLE_RATE / params.rate) / CHUNK_SIZE;

            if (alsa_pcm_hw_params_any(fd, &params) < 0) {
                perror("Failed to set ALSA PCM parameters");
                close(fd);
                gpiod_channel_output_disable(&channel);
                exit(EXIT_FAILURE);
            }

            // Open the output file
            FILE *file = fopen("audio_capture.pcm", "wb");
            if (!file) {
                perror("Failed to open output file");
                close(fd);
                gpiod_channel_output_disable(&channel);
                exit(EXIT_FAILURE);
            }

            // Start audio capture in a separate thread
            if (pthread_create(&audio_thread, NULL, audio_capture_thread, (void *)fd) != 0) {
                perror("Failed to create audio capture thread");
                close(fd);
                gpiod_channel_output_disable(&channel);
                exit(EXIT_FAILURE);
            }

            // Wait for SIGINT
            sigset_t sigset_child;
            sigaddset(&sigset_child, SIGINT);
            if (sigprocmask(SIG_BLOCK, &sigset_child, NULL) == -1) {
                perror("Failed to block signals in child");
                exit(EXIT_FAILURE);
            }

            // Wait for the child to finish
            waitpid(child, NULL, 0);

            // Clean up
            fclose(file);
            gpiod_channel_output_disable(&channel);
            close(fd);
        } else {
            // Child process
            sigset_t sigset;
            sigaddset(&sigset, SIGINT);
            sigprocmask(SIG_BLOCK, &sigset, NULL);

            // Initialize libgpiod
            gpiod_handle_t handle;
            gpiod_arg_t arg = {GPIO_ID};
            gpiod_channel_t channel;
            gpiod_channel_init(&channel, arg);
            gpiod_channel_output_enable(&channel, GPIOD_OUTPUT);

            // Open ALSA device
            int fd = open(PIPE_NAME, O_RDWR);
            if (fd < 0) {
                perror("Failed to open ALSA device");
                exit(EXIT_FAILURE);
            }

            // Configure I2S settings
            struct alsa_pcm_hw_params params;
            memset(&params, 0, sizeof(params));
            params.format = ALSA_FORMAT_S16_LE;
            params.rate = SAMPLE_RATE;
            params.channels = 1;
            params.period_size = BUF_SIZE;
            params.period_count = (SAMPLE_RATE / params.rate) / CHUNK_SIZE;

            if (alsa_pcm_hw_params_any(fd, &params) < 0) {
                perror("Failed to set ALSA PCM parameters");
                close(fd);
                gpiod_channel_output_disable(&channel);
                exit(EXIT_FAILURE);
            }

            // Open the output file
            FILE *file = fopen("audio_capture.pcm", "ab");
            if (!file) {
                perror("Failed to open output file");
                close(fd);
                gpiod_channel_output_disable(&channel);
                exit(EXIT_FAILURE);
            }

            // Audio capture loop
            int samples_per_frame = BUF_SIZE / CHUNK_SIZE;
            int samples = 0;
            int left_channel = 0;

            while (1) {
                // Read I2S data
                ssize_t bytes_read = read(fd, &left_channel, samples_per_frame * CHUNK_SIZE);
                if (bytes_read < 0) {
                    perror("Failed to read from ALSA device");
                    break;
                } else if (bytes_read == 0) {
                    break;
                }

                // Extract 16-bit PCM samples
                for (int i = 0; i < samples_per_frame; i++) {
                    int16_t sample = (left_channel[i] << 8) | left_channel[i + samples_per_frame];
                    sample = (sample >> 16) & 0x00ff; // Right-shift to get 16-bit PCM

                    // Write to file
                    fwrite(&sample, sizeof(int16_t), 1, file);
                    samples++;
                }
            }

            // Clean up
            fclose(file);
            gpiod_channel_output_disable(&channel);
            close(fd);
        }
    } else {
        // Child process
        printf("Child process already running.\n");
    }

    return 0;
}

void *audio_capture_thread(void *arg) {
    int fd = *(int *)arg;
    // Same as the main function, but within the child process
    // ...
    return NULL;
}

