#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_SENSOR 4
#define GPIO_FAN 18
#define POLL_INTERVAL_MS 50
#define DEBOUNCE_MS 50
#define FAN_PWM_FREQ_HZ 100
#define FAN_MIN_DUTY 0
#define FAN_MAX_DUTY 80

void log_event(const char *event) {
    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    FILE *fp = fopen("flame_log.txt", "a");
    if (fp) {
        fprintf(fp, "%s: %s\n", timestamp, event);
        fclose(fp);
    }
}

void handle_signal(int signum) {
    log_event("Received SIGINT/SIGTERM, exiting...");
    pigpio_terminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(5);
    if (pi < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    pi_setup();

    gpioSetMode(GPIO_SENSOR, PI_OUTPUT);
    gpioSetMode(GPIO_FAN, PI_OUTPUT);

    gpioWrite(GPIO_SENSOR, 0); // Initially, sensor is off
    gpioWrite(GPIO_FAN, 0);

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int flame_detected = 0;
    int flame_duration = 0;
    int last_read = 0;

    while (1) {
        int sensor_state = gpioRead(GPIO_SENSOR);
        if (sensor_state != last_read) {
            last_read = sensor_state;
            if (sensor_state == PI_IN) {
                flame_detected = 1;
                flame_duration = 0;
                gpioWrite(GPIO_FAN, FAN_MIN_DUTY);
            } else {
                flame_detected = 0;
                flame_duration++;
                if (flame_duration >= 100) { // Debounce delay
                    flame_duration = 0;
                    gpioWrite(GPIO_FAN, 0);
                }
            }
        }

        if (flame_detected) {
            int duty_cycle = FAN_MIN_DUTY + (FAN_MAX_DUTY - FAN_MIN_DUTY) * (flame_duration / 100.0);
            gpioSetPWMfrequency(GPIO_FAN, FAN_PWM_FREQ_HZ);
            gpioSetPWM(GPIO_FAN, duty_cycle);
        }

        log_event("Flame detected, duration: " + std::to_string(flame_duration));
        usleep(POLL_INTERVAL_MS / 1000); // Convert to microseconds
    }

    pigpio_terminate();
    return 0;
}

