#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/epoll.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/epoll.h>
#include <sys/select.h>

#define SPI_CHANNEL 0
#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24

typedef struct {
    float start_freq;
    float end_freq;
    int chirps;
    int samples;
    int frame_period_ms;
} radar_config_t;

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_begin(NULL);
    if (!pi) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int spi_fd = pigpio_spiflashopen(SPI_CHANNEL, 1000000, 0);
    if (!spi_fd) {
        fprintf(stderr, "Failed to open SPI channel\n");
        pigpio_terminate(pi);
        return 1;
    }

    radar_config_t config = {
        77.0f,
        79.0f,
        64,
        256,
        100
    };

    FILE *log_file = fopen("radar_data.bin", "wb");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_terminate(pi);
        return 1;
    }

    unsigned char magic_number[] = {0x52, 0x44, 0x41, 0x44};
    unsigned long timestamp = get_timestamp();
    fwrite(magic_number, sizeof(magic_number), 1, log_file);
    fwrite(&timestamp, sizeof(unsigned long), 1, log_file);

    radar_config_t *config_ptr = (radar_config_t *)malloc(sizeof(radar_config_t));
    if (!config_ptr) {
        fprintf(stderr, "Failed to allocate memory for configuration\n");
        pigpio_terminate(pi);
        return 1;
    }
    *config_ptr = config;

    while (1) {
        pi_set_mode(GPIO_TRIGGER, PIGIO_OUTPUT);
        pi_set_mode(GPIO_DATA_READY, PIGIO_INPUT);

        pi_gpio_write(GPIO_TRIGGER, 1);
        sleep(0.001);
        pi_gpio_write(GPIO_TRIGGER, 0);

        epoll_event event;
        event.events = EPOLLIN;
        event.data.fd = spi_fd;

        int n = epoll_wait([&] (int fd, struct epoll_event *event, int max) {
            if (fd == spi_fd && event.events & EPOLLIN) {
                unsigned char data[32768];
                int bytes_read = pi_spirx8_read(spi_fd, data, 32768);
                if (bytes_read < 0) {
                    fprintf(stderr, "Error reading from SPI\n");
                    return 0;
                }
                if (bytes_read == 0) {
                    fprintf(stderr, "No data available\n");
                    break;
                }

                fwrite(data, bytes_read, 1, log_file);
                fprintf(log_file, "Frame %d\n", (int)event.data.u64);
            }
            return 0;
        }, 1, 10);

        pi_gpio_write(GPIO_DATA_READY, 0);

        free(config_ptr);
    }

    pigpio_terminate(pi);
    fclose(log_file);
    pigpio_spiflashclose(spi_fd);
    return 0;
}

unsigned long get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (unsigned long)(ts.tv_sec * 1000000000 + ts.tv_nsec / 1000);
}

