#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 20
#define POLL_INTERVAL_MS 100
#define LOG_FILE "flame_log.txt"

void log_state_transition(const char *state) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    fprintf(file, "%s,%llu,%s\n", gmtime(time_struct), (long long)now, state);
    fclose(file);
}

void signal_handler(int signum) {
    log_state_transition("SIGINT/SIGTERM received, exiting gracefully");
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpiod_context ctx;
    gpiod_config cfg;
    gpiod_config_init(&cfg);
    gpiod_config_ch_input(&cfg, GPIO_PIN);
    gpiod_channel_init(&ctx, GPIO_PIN, &cfg);

    if (gpiod_channel_get_state(&ctx) == GPIOD_STATE_LOW) {
        log_state_transition("Flame detected");
    } else {
        log_state_transition("Flame cleared");
    }

    while (1) {
        int state = gpiod_channel_get_value(&ctx);
        if (state != gpiod_channel_get_last_value(&ctx)) {
            log_state_transition(state ? "Flame detected" : "Flame cleared");
        }
        usleep(POLL_INTERVAL_MS * 1000 / 1000);
    }

    return 0;
}

