#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define CONVERSION_TIME_MS 100
#define FULL_SCALE_RANGE

void log_reading(const char *timestamp, float lux) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char dt_str[80];
    sprintf(dt_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1, local_time->tm_mday,
            local_time->tm_hour, local_time->tm_min, local_time->tm_sec);
    FILE *file = fopen("light_data.txt", "a");
    if (file) {
        fprintf(file, "%s, %f\n", dt_str, lux);
        fclose(file);
    }
}

int main() {
    int i2c_fd;
    int result_register = 0x00;
    int exponent, mantissa;
    float lux;

    pigpio_init(I2C_BUS);

    while (1) {
        i2c_fd = pigpio_open_i2c(I2C_BUS);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            continue;
        }

        // Read sensor data
        pigpio_write_i2c_mem_bw(i2c_fd, I2C_ADDR, result_register, 1);
        pigpio_read_i2c_mem_bw(i2c_fd, I2C_ADDR, result_register, 2);
        lux = (float)((pigpio_read_i2c_mem_bw(i2c_fd, I2C_ADDR, result_register, 2) & 0x7F) << 11) / 1024.0;

        // Extract exponent and mantissa
        exponent = (pigpio_read_i2c_mem_bw(i2c_fd, I2C_ADDR, result_register + 1) >> 7) & 0x07;
        mantissa = (pigpio_read_i2c_mem_bw(i2c_fd, I2C_ADDR, result_register + 1) & 0x7F);

        // Compute lux
        lux = 0.01 * pow(2, exponent) * mantissa;

        // Log reading
        log_reading(get_iso8601_timestamp(), lux);

        pigpio_close_i2c(i2c_fd);
    }

    pigpio_cleanup();
    return 0;
}

// Function to get ISO-8601 timestamp
char *get_iso8601_timestamp() {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char dt_str[80];
    sprintf(dt_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1, local_time->tm_mday,
            local_time->tm_hour, local_time->tm_min, local_time->tm_sec);
    return dt_str;
}

