#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <gpiod/gpiod.h>

#define GPIO_LINE 17
#define FLAME_DETECTED_THRESHOLD 0

volatile sig_atomic_t graceful_exit = 0;

void signal_handler(int signum) {
    graceful_exit = 1;
}

int main() {
    struct gpiod_line_request line_request;
    struct gpiod_chip chip;
    struct gpiod_settings settings;
    struct gpiod_line_config line_config;
    int fd;

    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    if (gpiod_chip_open(&chip, NULL) < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Configure the line as input with bias pulled up
    line_config.line = GPIO_LINE;
    line_config.mode = GPIOD_LINE_IN;
    line_config.bias = GPIOD_BIAS_PULL_UP;
    line_config.edge_edge = GPIOD_EDGE_FALLING;

    if (gpiod_request_config(&chip.line, &line_config, &settings) < 0) {
        fprintf(stderr, "Failed to request line configuration\n");
        return EXIT_FAILURE;
    }

    // Request the line
    if (gpiod_chip_request_lines(&chip, &line_request) < 0) {
        fprintf(stderr, "Failed to request the line\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!graceful_exit) {
        int line_value;
        if (gpiod_line_request_get_value(&line_request, &line_value) < 0) {
            fprintf(stderr, "Failed to get line value\n");
            continue;
        }

        if (line_value == FLAME_DETECTED_THRESHOLD) {
            printf("%s: Flame Detected: YES\n", ctime(&time(NULL)));
        } else {
            printf("%s: Flame Detected: NO\n", ctime(&time(NULL)));
        }

        usleep(1000000); // Sleep for 1 second
    }

    // Release resources
    gpiod_line_request_put(&line_request);
    gpiod_chip_release(&chip);

    // Clean up
    gpiod_shutdown();

    return EXIT_SUCCESS;
}

