#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define NUM_CHANNELS 8
#define GPIO_PINS {2, 3, 4, 5, 6, 7, 8, 9}

void signal_handler(int signum) {
    printf("Received SIGINT, shutting down...\n");
    gpiod_line_free(lines[0]);
    gpiod_chip_free(chip);
    exit(0);
}

int main(int argc, char *argv[]) {
    int ret;
    struct gpiod_line *line;
    struct gpiod_chip *chip;

    // Initialize signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO line
    ret = gpiod_chip_new(&chip, NULL, NULL);
    if (ret < 0) {
        perror("Failed to open GPIO line");
        exit(EXIT_FAILURE);
    }

    // Configure GPIO lines for output
    for (int i = 0; i < NUM_CHANNELS; i++) {
        line = gpiod_line_new_from_gpio(chip, GPIO_PINS[i], GPIOD_OUT);
        if (line == NULL) {
            perror("Failed to create GPIO line");
            gpiod_chip_free(chip);
            exit(EXIT_FAILURE);
        }
        gpiod_line_set_drive(line, 1); // Set as output high
        gpiod_line_set_drive_level(line, 1); // Set initial state to high
    }

    // Set up a periodic timer for reading the sensors
    ret = gpiod_line_new_timer(chip, &timer, 100);
    if (ret < 0) {
        perror("Failed to create timer");
        gpiod_chip_free(chip);
        exit(EXIT_FAILURE);
    }

    // Start the timer
    gpiod_line_start(timer);

    // Main loop to read sensor states
    while (1) {
        ret = gpiod_line_read(timer, NULL);
        if (ret < 0) {
            perror("Failed to read from timer");
            break;
        }

        // Process sensor states
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int state = gpiod_line_get_value(line[i]);
            printf("Channel %d: %d\n", i + 1, state);
        }
    }

    // Stop the timer
    gpiod_line_stop(timer);

