    signal(SIGINT, signal_handler);

    // Open the GPIO line
    ret = gpiod_chip_new(&chip, NULL, NULL);
    if (ret < 0) {
        perror("Failed to open GPIO line");
        exit(EXIT_FAILURE);
    }

