    ret = gpiod_line_new_timer(chip, &timer, 100);
    if (ret < 0) {
        perror("Failed to create timer");
        gpiod_chip_free(chip);
        exit(EXIT_FAILURE);
    }

    // Start the timer
    gpiod_line_start(timer);

    // Main loop to read sensor states
    while (1) {
        ret = gpiod_line_read(timer, NULL);
        if (ret < 0) {
            perror("Failed to read from timer");
            break;
        }

        // Process sensor states
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int state = gpiod_line_get_value(line[i]);
            printf("Channel %d: %d\n", i + 1, state);
        }
    }

    // Stop the timer
    gpiod_line_stop(timer);

    // Wait for the timer to finish
    gpiod_line_join(timer);

    // Free resources
    gpiod_line_free_all(timer);
    gpiod_chip_free(chip);

    return 0;
}
