#include <string.h>
#include <pigpio.h>

#define GPIO_PINS {2, 3, 4, 5, 6, 7, 8, 9}
#define SAMPLE_INTERVAL_MS 100

void signal_handler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    gpioTerminate();
    exit(0);
}

int main() {
    int ret;
    int num_gpins = sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0]);

    // Initialize pigpio
    ret = pigpioInit(5); // 5 is the number of available GPIOs on Raspberry Pi 3
    if (ret) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_strerror(ret));
        return 1;
    }

    // Configure GPIOs as inputs with pull-down resistors
    for (int i = 0; i < num_gpins; i++) {
        ret = gpioSetMode(GPIO_PINS[i], PI_INPUT);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PINS[i], pi_strerror(ret));
            return 1;
        }
        ret = gpioSetPull(GPIO_PINS[i], PI_PULLDOWN);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO %d pull-up/down: %s\n", GPIO_PINS[i], pi_strerror(ret));
            return 1;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main sampling loop
    while (1) {
        for (int i = 0; i < num_gpins; i++) {
            int state = gpioGet(GPIO_PINS[i]);
            printf("[%d ms] CH%d=%d\n", (int)SAMPLE_INTERVAL_MS, i + 1, state);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100 ms
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

