void sigint_handler(int sig) {
    printf("\nGracefully exiting...\n");
    gpiod_chip_free(chip);
    exit(0);
}

int main() {
    int ret;
    struct sigaction sa;

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize libgpiod
    ret = gpiod_chip_create(&chip);
    if (ret < 0) {
        perror("Failed to create gpio chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < sizeof(GPIO_PINS) / sizeof(int); i++) {
        ret = gpiod_chip_line_request(chip, GPIO_PINS[i], GPIOD_BIAS_OFF);
        if (ret < 0) {
            perror("Failed to request GPIO line");
            exit(EXIT_FAILURE);
        }
    }

    while (1) {
        // Poll all lines
        ret = gpiod_chip_poll(chip, 1);
        if (ret < 0) {
            perror("Failed to poll gpio chip");
            exit(EXIT_FAILURE);
        }

        // Process the state of each line
        for (int i = 0; i < sizeof(GPIO_PINS) / sizeof(int); i++) {
            int state = gpiod_line_get_value(chip, GPIO_PINS[i]);
            printf("%s %d\n", gpiod_get_timestamp(), state ? '1' : '0');
        }

        usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    return 0;
}

