#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PART_ID 0x45
#define HW_KEY 0x17
#define CHLIST 0x01
#define ALS_FORCE 0x06

#define LOG_FILE "uv_als_log.csv"
#define LOG_FORMAT "%s,%d,%d\n"

void sigint_handler(int sig) {
    printf("Received SIGINT, exiting gracefully...\n");
    pigpio_stop();
    close(logfd);
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Received SIGTERM, exiting gracefully...\n");
    pigpio_stop();
    close(logfd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int logfd;
    pigpio_init(I2C_BUS);

    if (pigpio_begin(I2C_BUS) < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (pigpio_setup_i2c(I2C_BUS) < 0) {
        perror("Failed to set up I2C bus");
        return EXIT_FAILURE;
    }

    if (pigpio_write_i2c_reg(I2C_ADDR, HW_KEY) != PART_ID) {
        perror("Failed to write HW_KEY to sensor");
        return EXIT_FAILURE;
    }

    if (pigpio_write_i2c_reg(I2C_ADDR, CHLIST) != 0x01) {
        perror("Failed to configure CHLIST register");
        return EXIT_FAILURE;
    }

    if (pigpio_write_i2c_reg(I2C_ADDR, ALS_FORCE) < 0) {
        perror("Failed to trigger ALS_FORCE command");
        return EXIT_FAILURE;
    }

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        int uv_index, als_visible;

        if (pigpio_read_i2c_byte(I2C_ADDR, 0x00) == uv_index) {
            if (pigpio_read_i2c_byte(I2C_ADDR, 0x01) == als_visible) {
                printf("UV Index: %d, Visible ALS: %d\n", uv_index, als_visible);
                fprintf(logfd, LOG_FORMAT,
                        (const char*)ctime(NULL), uv_index, als_visible);
            } else {
                printf("Warning: ALS_VIS is not enabled\n");
            }
        } else {
            printf("Warning: UV index is not available\n");
        }

        usleep(1000000); // Sleep for 1 second
    }

    pigpio_stop();
    close(logfd);
    return EXIT_SUCCESS;
}

int signalHandler(int signum) {
    switch (signum) {
        case SIGINT:
            sigint_handler(signum);
            break;
        case SIGTERM:
            sigterm_handler(signum);
            break;
        default:
            break;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Rest of the main function as shown above

    return EXIT_SUCCESS;
}

