static int read_i2c_byte(int file_descriptor, unsigned short reg_addr) {
    unsigned char data[2];
    ssize_t ret = read(file_descriptor, data, 2);
    if (ret != 2) {
        perror("read_i2c_byte");
        return -1;
    }
    return data[0];
}

static int write_i2c_byte(int file_descriptor, unsigned char data, unsigned short reg_addr) {
    return write(file_descriptor, &data, 1);
}

static int start_measurement(int file_descriptor, unsigned short reg_addr) {
    return write_i2c_byte(file_descriptor, I2C_CMD_START, reg_addr);
}

static int stop_measurement(int file_descriptor, unsigned short reg_addr) {
    return write_i2c_byte(file_descriptor, 0x00, reg_addr);
}

static int read_flow_data(int file_descriptor, unsigned short reg_addr) {
    unsigned char data[3];
    ssize_t ret = read(file_descriptor, data, 3);
    if (ret != 3) {
        perror("read_flow_data");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

static int validate_flow_data(unsigned int raw_flow) {
    unsigned int crc = 0;
    for (int i = 0; i < 3; i++) {
        crc ^= raw_flow >> (8 * i);
        for (int j = 0; j < 8; j++) {
            crc ^= (crc & 1) ? CRC_POLYNOMIAL : 0;
        }
    }
    return crc == CRC_INIT;
}

static int convert_flow_to_ml_min(int raw_flow) {
    return raw_flow * SCALE_FACTOR;
}

static int log_flow_average(int avg_flow) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return -1;
    }
    fprintf(log_file, "%f\n", avg_flow);
    fclose(log_file);
    return 0;
}

static int set_alarm(int gpio_value) {
    if (gpio_value) {
        return gpio_set_level(ALARM_GPIO, 1);
    } else {
        return gpio_set_level(ALARM_GPIO, 0);
    }
}

static int main_loop() {
    while (1) {
        int sensor_1_result = start_measurement(i2c_fd, SENS_ADDR_0);
        if (sensor_1_result < 0) {
            fprintf(stderr, "Failed to start measurement for sensor 0\n");
            continue;
        }
        int sensor_1_flow = read_flow_data(i2c_fd, MEASUREMENT_REG);
        if (sensor_1_flow < 0) {
            fprintf(stderr, "Failed to read flow data for sensor 0\n");
            continue;
        }
        if (!validate_flow_data(sensor_1_flow)) {
            fprintf(stderr, "CRC validation failed for sensor 0\n");
            continue;
        }
        int sensor_1_avg_flow = convert_flow_to_ml_min(sensor_1_flow);
        log_flow_average(sensor_1_avg_flow);

        int sensor_2_result = start_measurement(i2c_fd, SENS_ADDR_1);
        if (sensor_2_result < 0) {
            fprintf(stderr, "Failed to start measurement for sensor 1\n");
            continue;
        }
        int sensor_2_flow = read_flow_data(i2c_fd, MEASUREMENT_REG);
        if (sensor_2_flow < 0) {
            fprintf(stderr, "Failed to read flow data for sensor 1\n");
            continue;
        }
        if (!validate_flow_data(sensor_2_flow)) {
            fprintf(stderr, "CRC validation failed for sensor 1\n");
            continue;
        }
        int sensor_2_avg_flow = convert_flow_to_ml_min(sensor_2_flow);
        log_flow_average(sensor_2_avg_flow);

        int avg_flow = (sensor_1_avg_flow + sensor_2_avg_flow) / 2;
        if (avg_flow < 0.5) {
            set_alarm(1);
        } else {
            set_alarm(0);
        }

        usleep(1000000); // 1 second delay
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    i2c_client = i2c_client_new(i2c_fd, 0x20);
    if (!i2c_client) {
        perror("i2c_client_new");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    alarm_gpio = gpiod_create_digital_out_pin(0, "flow_alarm");
    if (!alarm_gpio) {
        perror("gpiod_create_digital_out_pin");
        i2c_client_free(i2c_client);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpio_init(alarm_gpio) < 0) {
        perror("gpio_init");
        gpiod_digital_out_t_free(alarm_gpio);
        i2c_client_free(i2c_client);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (libgpiod_set_polling_mode(LIBGPIOD_POLLING_MODE_PREEMPT) < 0) {
        perror("libgpiod_set_polling_mode");
        gpiod_digital_out_t_free(alarm_gpio);
        i2c_client_free(i2c_client);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (libgpiod_set_output_level(alarm_gpio, 0) < 0) {
        perror("libgpiod_set_output_level");
        gpiod_digital_out_t_free(alarm_gpio);
        i2c_client_free(i2c_client);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (main_loop() < 0) {
        fprintf(stderr, "Main loop failed\n");
        gpiod_digital_out_t_free(alarm_gpio);
        i2c_client_free(i2c_client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_digital_out_t_free(alarm_gpio);
    i2c_client_free(i2c_client);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

