#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define POLL_INTERVAL_MS 50
#define SENSOR_PIN 4

typedef struct {
    time_t timestamp;
    int reading;
} BufferEntry;

BufferEntry buffer[BUFFER_SIZE];
int head = 0;
int tail = 0;

void signal_handler(int signum) {
    printf("\nBuffer contents:\n");
    for (int i = 0; i < tail; ++i) {
        printf("%s: %d\n", asctime(gmtime(&buffer[i].timestamp)), buffer[i].reading);
    }
    pigpio_terminate(1);
    exit(0);
}

void init_pigpio() {
    if (pigpio_init() != 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
}

void setup_gpio(int pin) {
    if (gpioSetup(pin, PI_OUTPUT, PI_PULLUP) != 0) {
        fprintf(stderr, "Failed to configure GPIO %d\n", pin);
        pigpio_terminate(1);
        exit(1);
    }
}

void configure_input(int pin) {
    if (gpioInput(pin, PI_PULLUP) != 0) {
        fprintf(stderr, "Failed to configure GPIO %d as input\n", pin);
        pigpio_terminate(1);
        exit(1);
    }
}

void poll_sensor() {
    int reading = gpioRead(SENSOR_PIN);
    if (reading == 0) {
        time_t now = time(NULL);
        buffer[tail].timestamp = now;
        buffer[tail].reading = reading;
        tail = (tail + 1) % BUFFER_SIZE;
    }
}

int main() {
    init_pigpio();
    setup_gpio(SENSOR_PIN);
    configure_input(SENSOR_PIN);

    signal(SIGINT, signal_handler);

    while (1) {
        poll_sensor();
        usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    pigpio_terminate(0);
    return 0;
}

