#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x55
#define REG_MODE_CONTROL 0x1D
#define REG_OPERATING_STATUS 0x1B
#define REG_X_ACCEL 0x2A
#define REG_Y_ACCEL 0x2B
#define REG_Z_ACCEL 0x2C
#define REG_X_ACCEL_LOW 0x2D
#define REG_Y_ACCEL_LOW 0x2E
#define REG_Z_ACCEL_LOW 0x2F
#define SCALING_FACTOR 0.0009765625
#define LOG_INTERVAL 500
#define MAX_LOG_ENTRIES 10000
#define FAN_HEALTH_FILE "fan_health.csv"

#define BUFFER_SIZE 1024

static int i2c_fd;
static struct i2c_client *i2c_client;
static time_t last_status_check = 0;

static long get_timestamp() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return tv.tv_sec * 1000000 + tv.tv_usec;
}

static void log_entry(const char *entry) {
    FILE *file = fopen(FAN_HEALTH_FILE, "a");
    if (!file) {
        perror("Failed to open fan health file");
        return;
    }
    fprintf(file, "%s", entry);
    fclose(file);
}

static void init_i2c() {
    i2c_fd = open(FAN_HEALTH_FILE, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR | 0644);
    if (i2c_fd == -1) {
        perror("Failed to open fan health file");
        exit(EXIT_FAILURE);
    }

    i2c_client = i2c_client_new(i2c_fd, I2C_BUS);
    if (!i2c_client) {
        perror("Failed to create i2c client");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void write_mode_control(uint8_t value) {
    if (write(i2c_client->fd, &value, 1) == -1) {
        perror("Failed to write to mode control register");
        exit(EXIT_FAILURE);
    }
}

static uint16_t read_operating_status() {
    static uint16_t status = 0;
    static time_t last_check = get_timestamp();

    if (get_timestamp() - last_check > 1000) {
        last_check = get_timestamp();
        status = read(i2c_client->fd, &reg_operating_status, 2);
        if (status < 2) {
            perror("Failed to read operating status");
            exit(EXIT_FAILURE);
        }
    }

    return status & 0x01;
}

static uint16_t read_acceleration(uint8_t reg) {
    static uint16_t values[4];
    static int index = 0;

    if (index < 4) {
        if (read(i2c_client->fd, &values[index], 2) == -1) {
            perror("Failed to read acceleration register");
            exit(EXIT_FAILURE);
        }
        index++;
    }

    return (values[0] << 8) | values[1];
}

static void log_sample() {
    uint16_t x = read_acceleration(REG_X_ACCEL);
    uint16_t y = read_acceleration(REG_Y_ACCEL);
    uint16_t z = read_acceleration(REG_Z_ACCEL);

    double g_x = (double)(x & 0xFF) * SCALING_FACTOR;
    double g_y = (double)(y & 0xFF) * SCALING_FACTOR;
    double g_z = (double)(z & 0xFF) * SCALING_FACTOR;

    char entry[BUFFER_SIZE];
    sprintf(entry, "%lu,%lu,%lu", g_x, g_y, g_z);
    log_entry(entry);
}

int main(int argc, char *argv[]) {
    init_i2c();

    write_mode_control(0x10);

    while (1) {
        if (!read_operating_status()) {
            fprintf(stderr, "Sensor did not become active within 1 second.\n");
            exit(EXIT_FAILURE);
        }

        log_sample();
        usleep(LOG_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    close(i2c_fd);
    fclose(stdout);
    return 0;
}

