static uint16_t read_operating_status() {
    static uint16_t status = 0;
    static time_t last_check = get_timestamp();

    if (get_timestamp() - last_check > 1000) {
        last_check = get_timestamp();
        status = read(i2c_client->fd, &reg_operating_status, 2);
        if (status < 2) {
            perror("Failed to read operating status");
            exit(EXIT_FAILURE);
        }
    }

    return status & 0x01;
}

static uint16_t read_acceleration(uint8_t reg) {
    static uint16_t values[4];
    static int index = 0;

    if (index < 4) {
        if (read(i2c_client->fd, &values[index], 2) == -1) {
            perror("Failed to read acceleration register");
            exit(EXIT_FAILURE);
        }
        index++;
    }

    return (values[0] << 8) | values[1];
}

static void log_sample() {
    uint16_t x = read_acceleration(REG_X_ACCEL);
    uint16_t y = read_acceleration(REG_Y_ACCEL);
    uint16_t z = read_acceleration(REG_Z_ACCEL);

    double g_x = (double)(x & 0xFF) * SCALING_FACTOR;
    double g_y = (double)(y & 0xFF) * SCALING_FACTOR;
    double g_z = (double)(z & 0xFF) * SCALING_FACTOR;

    char entry[BUFFER_SIZE];
    sprintf(entry, "%lu,%lu,%lu", g_x, g_y, g_z);
    log_entry(entry);
}

int main(int argc, char *argv[]) {
    init_i2c();

    write_mode_control(0x10);

    while (1) {
        if (!read_operating_status()) {
            fprintf(stderr, "Sensor did not become active within 1 second.\n");
            exit(EXIT_FAILURE);
        }

        log_sample();
        usleep(LOG_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    close(i2c_fd);
    fclose(stdout);
    return 0;
}
