#include <pigpio.h>

#define SENSOR_PIN_1 17
#define SENSOR_PIN_2 18
#define STALL_TIMEOUT_SEC 2
#define LOG_FILE "stall_log.txt"

int stall_count = 0;

void log_stall(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

void signal_handler(int signum) {
    log_stall(get_current_time());
    exit(0);
}

int main(int argc, char *argv[]) {
    if (pigpioInitialise() < 0) {
        perror("Failed to initialise pigpio");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_PIN_1, PI_OUTPUT);
    gpioSetMode(SENSOR_PIN_2, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int sensor1 = gpioRead(SENSOR_PIN_1);
        int sensor2 = gpioRead(SENSOR_PIN_2);

        if (sensor1 == 0 && sensor2 == 0) {
            // Both sensors detected an obstacle, check for stall
            if (stall_count == 0) {
                // Start stall timer
                stall_start_time = get_current_time();
            } else {
                // Stall detected, log the event
                char timestamp[64];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                log_stall(timestamp);
                stall_count++;
            }
        } else {
            // Reset stall count and timer on clear
            stall_count = 0;
            if (stall_start_time != 0) {
                // Stall ended, check if it's a duplicate
                time_t now = time(NULL);
                if (get_time_diff(stall_start_time, now) >= STALL_TIMEOUT_SEC) {
                    log_stall(get_current_time());
                    stall_count = 1;
                    stall_start_time = 0;
                }
            }
        }
        usleep(100000); // Check every second
    }

    piggpioTerminate();
    return EXIT_SUCCESS;
}

// Helper functions
time_t get_current_time() {
    return time(NULL);
}

time_t get_time_diff(time_t start, time_t end) {
    return (end - start) / 1000000;
}

char *get_current_time_str(time_t time) {
    time_t sec = time;
    time_t min = sec / 60;
    time_t hour = min / 60;
    char buffer[80];
    sprintf(buffer, "%02d:%02d:%02d", hour % 24, min % 60, sec % 60);
    return strdup(buffer);
}

void exit_with_log(const char *timestamp) {
    log_stall(timestamp);
    exit(0);
}

