#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x0E
#define SCALE_FACTOR 50
#define MAG_LOG_FILE "magnetic_log.csv"

void sigint_handler(int sig) {
    printf("SIGINT received, cleaning up resources...\n");
    gpioTerminate();
    close(mag_fd);
    remove(MAG_LOG_FILE);
    exit(0);
}

void sigterm_handler(int sig) {
    printf("SIGTERM received, cleaning up resources...\n");
    gpioTerminate();
    close(mag_fd);
    remove(MAG_LOG_FILE);
    exit(0);
}

int main(int argc, char *argv[]) {
    int mag_fd, ret;
    struct i2c_rdwr_t wr_reg, rd_reg;
    int sensor_present = 0;
    char header[64];

    mag_fd = open(MAG_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (mag_fd == -1) {
        perror("Error opening magnetic_log.csv");
        exit(EXIT_FAILURE);
    }

    gpioInitialise();

    wr_reg.reg = 0x00;
    rd_reg.reg = 0x00;
    ret = pigpio_i2cWriteRegister(I2C_BUS, I2C_ADDR, &wr_reg);
    if (ret < 0) {
        perror("Error writing to device ID register");
        exit(EXIT_FAILURE);
    }

    ret = pigpio_i2cReadRegister(I2C_BUS, I2C_ADDR, &rd_reg);
    if (ret < 0) {
        perror("Error reading device ID register");
        exit(EXIT_FAILURE);
    }

    if (rd_reg.value == 0x8D) {
        sensor_present = 1;
    } else {
        fprintf(stderr, "Sensor not present, expected value 0x8D\n");
        exit(EXIT_FAILURE);
    }

    if (!sensor_present) {
        fprintf(stderr, "Sensor absent, exiting...\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = pigpio_i2cWriteByte(I2C_BUS, I2C_ADDR, 0x01); // Read all axes
        if (ret < 0) {
            perror("Error reading all axes");
            fprintf(stderr, "I2C read error, exiting...\n");
            exit(EXIT_FAILURE);
        }

        ret = pigpio_i2cReadByte(I2C_BUS, I2C_ADDR);
        if (ret < 0) {
            perror("Error reading raw data");
            fprintf(stderr, "I2C read error, exiting...\n");
            exit(EXIT_FAILURE);
        }

        int raw_data = (ret << 8) | (ret & 0xFF);

        // Convert raw data to mT
        int mT = raw_data * SCALE_FACTOR / 1024;

        // Write to CSV
        fprintf(mag_fd, "%s%s", header, "%f,%f,%f\n",
                (double)mT / 1000, (double)mT / 1000, (double)mT / 1000);

        usleep(100000); // Wait for 100 ms
    }

    sigset_t sigset;
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    while (1) {
        int sig = peekssignal(SIGINT | SIGTERM);
        if (sig != -1) {
            siginterrupt(SIG_IGN, 1);
            sigset_t temp;
            sigaddset(&temp, SIGINT);
            sigaddset(&temp, SIGTERM);
            sigprocmask(SIG_BLOCK, &temp, NULL);
            break;
        }
    }

    gpioTerminate();
    close(mag_fd);
    remove(MAG_LOG_FILE);
    exit(0);
}

