#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_GPIO 23
#define POLL_INTERVAL_SEC 2.0
#define LOG_FILE "flood_log.txt"
#define ERROR_LOG_INTERVAL_SEC 60.0

void log_error(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%s\n", msg);
    fclose(fp);
}

void handle_signal(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    pigpio_terminate();
    exit(0);
}

int main() {
    pigpio_initialize(1); // Initialize pigpio with 1 as the number of available pins
    if (pigpio_init_thread(1) < 0) {
        log_error("Failed to initialize pigpio thread");
        return 1;
    }

    pid_t pid = fork();
    if (pid == 0) { // Child process
        pigpio_set_mode(SENSOR_GPIO, PIGIO_OUTPUT);
        while (1) {
            int sensor_state = pigpio_get_gpio_value(SENSOR_GPIO);
            if (sensor_state == PIGIO_INPUT) {
                printf("ALERT: Water detected at %s\n", localtime(NULL));
                log_error("ALERT: Water detected at %s", localtime(NULL));
                // Append timestamped entry to log file
                FILE *fp = fopen(LOG_FILE, "a");
                if (!fp) {
                    log_error("Error opening log file: %s", strerror(errno));
                    continue;
                }
                fprintf(fp, "%s\n", "ALERT: Water detected at %s", localtime(NULL));
                fclose(fp);
            }
            usleep(POLL_INTERVAL_SEC * 1000000); // Sleep for the specified interval
        }
    } else { // Parent process
        signal(SIGINT, handle_signal);
        signal(SIGTERM, handle_signal);
        while (1) {
            usleep(ERROR_LOG_INTERVAL_SEC * 1000000); // Sleep for the specified interval
        }
    }

    pigpio_terminate();
    return 0;
}

