#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 1000  // 1 second in milliseconds

int main(int argc, char *argv[]) {
    int gpio = SENSOR_PIN;
    int pulse_count = 0;
    long long pulse_time = 0;
    pigpio pi = pigpio_init(1);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pistrerror(pi));
        exit(EXIT_FAILURE);
    }

    // Enable interrupt on rising edge
    piSetMode(gpio, PI_OUTPUT);
    piEdgeDetect(gpio, PI_RISING);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        piTerminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Read sensor state
        int sensor_state = piRead(gpio);

        // Check for rising edge
        if (sensor_state == 1) {
            // Increment pulse counter
            pulse_count++;
            pulse_time = piGetTimestamp();
        }

        // Check for sample interval
        if (pulse_time > SAMPLE_INTERVAL) {
            // Calculate RPM
            double rpm = pulse_count * 60.0 / SAMPLE_INTERVAL;

            // Log RPM
            fprintf(log_file, "%s %d\n", localtime(NULL), (int)rpm);
            fprintf(stdout, "%s %d\n", localtime(NULL), (int)rpm);

            // Reset pulse counter and time
            pulse_count = 0;
            pulse_time = 0;
        }

        // Sleep for a short duration to avoid busy-waiting
        usleep(10000);
    }

    // Clean up and exit
    piTerminate();
    fclose(log_file);
    return 0;

signal_handler:
{
    piDisableAllInterrupts();
    piSetMode(gpio, PI_INPUT);
    piEdgeDetect(gpio, PI_FALLING);
    piSetEdgeDetectCallback(gpio, NULL);
    piTerminate();
    exit(EXIT_SUCCESS);
}
}

