#include <pigpio.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>

#define SENSOR_A 17
#define SENSOR_B 27
#define PULL_UP_ENABLE 1

typedef struct {
    pthread_mutex_t mutex;
    time_t last_rotation_time;
} RotationLogger;

RotationLogger logger;

void rotation_handler(int gpio) {
    static bool first_rotation = true;
    static bool current_direction = false;

    int state = gpioRead(gpio);

    if (state != gpioPullUp) {
        if (first_rotation) {
            logger.last_rotation_time = time(NULL);
            first_rotation = false;
            current_direction = state;
        } else {
            if (current_direction) {
                if (state == gpioPullUp) {
                    current_direction = false;
                    logger.last_rotation_time = time(NULL);
                    printf("CCW detected at %s\n", ctime(&logger.last_rotation_time));
                }
            } else {
                if (state == gpioPullUp) {
                    current_direction = true;
                    logger.last_rotation_time = time(NULL);
                    printf("CW detected at %s\n", ctime(&logger.last_rotation_time));
                }
            }
        }
    }
}

void init_pigpio() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(1);
    }

    gpioSetAlertFunc(SENSOR_A, rotation_handler, PULL_UP_ENABLE);
    gpioSetAlertFunc(SENSOR_B, rotation_handler, PULL_UP_ENABLE);

    if (gpioSetPullUpDown(SENSOR_A, PULL_UP_ENABLE) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor for Sensor A\n");
        exit(1);
    }

    if (gpioSetPullUpDown(SENSOR_B, PULL_UP_ENABLE) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor for Sensor B\n");
        exit(1);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    pthread_mutex_lock(&logger.mutex);
    logger.last_rotation_time = time(NULL);
    pthread_mutex_unlock(&logger.mutex);
    pigpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_pigpio();

    // Initialize mutex
    pthread_mutex_init(&logger.mutex, NULL);

    // Start a thread to log rotations
    pthread_t log_thread;
    pthread_create(&log_thread, NULL, log_rotation_events, NULL);

    // Main loop
    while (1) {
        // Sleep to avoid busy-spin
        sleep(1);
    }

    pthread_join(log_thread, NULL);

    pigpioTerminate();
    return 0;
}

void *log_rotation_events(void *arg) {
    while (1) {
        // Wait for new rotation event
        pthread_cond_wait(&logger.mutex, &logger.mutex);

        // Log rotation event
        printf("Rotation detected at %s\n", ctime(&logger.last_rotation_time));

        // Flush and close the log file
        FILE *log_file = fopen("rotation_log.txt", "a");
        if (log_file != NULL) {
            fprintf(log_file, "%s", ctime(&logger.last_rotation_time));
            fclose(log_file);
        }
    }

    return NULL;
}

