#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>
#include <syslog.h>

#define TOUCH_PIN 16
#define LED_PIN 12
#define POLL_INTERVAL 50

static int fd;
static struct gpiod_line_request line_request;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_INFO, format, args);
    va_end(args);
}

void setup_gpio(void) {
    fd = open("/dev/gpioctl", O_RDWR);
    if (fd < 0) {
        log_message("Failed to open /dev/gpioctl: %m");
        exit(EXIT_FAILURE);
    }

    line_request.chip = gpiod_chip_open(fd, "touch_sensor");
    if (line_request.chip < 0) {
        log_message("Failed to open GPIO line: %m");
        close(fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_config_t config = {
        .line = TOUCH_PIN,
        .direction = gpiod_line_direction_in,
        .edge_edge = gpiod_line_edge_rising,
        .edge_active = gpiod_line_edge_active_high,
        .line_request_callback = touch_event_handler,
        .user_data = NULL
    };

    if (gpiod_line_request_init(line_request.chip, &config) < 0) {
        log_message("Failed to configure GPIO line: %m");
        gpiod_line_request_destroy(line_request.chip);
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void teardown_gpio(void) {
    if (line_request.chip != -1) {
        gpiod_line_request_destroy(line_request.chip);
        line_request.chip = -1;
    }
    if (fd != -1) {
        close(fd);
        fd = -1;
    }
}

void touch_event_handler(void *user_data) {
    log_message("Touch event detected on GPIO %d\n", TOUCH_PIN);
    // Turn on the LED here if needed
}

int main(int argc, char *argv[]) {
    log_message("Starting touch sensor and LED control program\n");

    setup_gpio();

    while (1) {
        int result = libgpiod_line_request_read(&line_request);
        if (result < 0) {
            log_message("Error reading from GPIO line: %m");
            break;
        }

        if (line_request.line_value) {
            log_message("Sensor touched\n");
            // Turn on the LED here if needed
        }

        usleep(POLL_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    teardown_gpio();
    log_message("Exiting program\n");
    return 0;
}

void signal_handler(int signum) {
    log_message("Received signal %d, shutting down gracefully\n", signum);
    // Turn off the LED here if needed
    teardown_gpio();
    exit(signum == SIGINT || signum == SIGTERM ? 0 : EXIT_FAILURE);
}

int main_signal_handler(int signum) {
    signal(signum, signal_handler);
    return main(argc, argv);
}

int main(int argc, char *argv[]) {
    return main_signal_handler(getopt(argc, argv, "h:"));
}

