#include <stdio.h>
#include <stdlib.h>
#include <libgpiod/gpio.h>
#include <unistd.h>
#include <signal.h>

#define TOUCH_PIN 17
#define LED_PIN 18
#define DEBOUNCE_MILLIS 50

void touch_handler(const struct gpio_event *event) {
    if (event->event_mask & GPIO_EVENT_EDGE_RISING) {
        gpio_edge_detected(LED_PIN, GPIO_EDGE_RISING);
    }
}

int main(int argc, char *argv[]) {
    int ret;
    struct gpio_desc *gpio_desc;
    struct gpio_event event;
    struct sigaction sa;

    // Initialize GPIO
    ret = gpio_init();
    if (ret < 0) {
        perror("gpio_init");
        exit(EXIT_FAILURE);
    }

    gpio_desc = gpio_describe(TOUCH_PIN);
    if (!gpio_desc) {
        perror("gpio_describe");
        exit(EXIT_FAILURE);
    }

    gpio_event_init(&event, &touch_handler, GPIO_EVENT_RISING);
    ret = gpio_event_add(gpio_desc, &event);
    if (ret < 0) {
        perror("gpio_event_add");
        exit(EXIT_FAILURE);
    }

    // Initialize LED
    ret = gpio_describe(LED_PIN);
    if (!ret) {
        gpio_output_set(LED_PIN, 0); // Drive LED LOW at startup
    } else {
        perror("gpio_describe");
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    sa.sa_handler = handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        usleep(DEBOUNCE_MILLIS * 1000 / 1000); // Debounce delay
    }

    // Clean up and exit
    gpio_event_del(&event);
    gpio_event_del(gpio_desc);
    gpio_cleanup(TOUCH_PIN);
    gpio_cleanup(LED_PIN);
    return 0;
}

void handler(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    gpio_event_del(&event);
    gpio_event_del(gpio_desc);
    gpio_cleanup(TOUCH_PIN);
    gpio_cleanup(LED_PIN);
    exit(EXIT_SUCCESS);
}

