void log_event(const char *event_type) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    sprintf(timestamp, "%s", ctime(&now));

    fprintf(log_file, "%s - %s\n", timestamp, event_type);
    fclose(log_file);
}

