        perror("Failed to set signal handlers");
        return 1;
    }

    if (pigpio_init() != 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    gpioSetup(SENSOR_GPIO, PI_OUTPUT, PI_NOPULL);

    while (1) {
        int sensor_state = gpioRead(SENSOR_GPIO);
        if (sensor_state == 0) {
            log_event("Rain Detected");
        } else {
            log_event("No Rain");
        }
        usleep(POLL_INTERVAL * 1000 / 1000); // Convert microseconds to seconds
    }

    pigpio_terminate();
    return 0;
}

