#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_18 18
#define DEBOUNCE_TIME 5000 // 5 ms

int sensor_state[2] = {0};
int last_state[2] = {0};
int pulse_count = 0;
int revolutions = 0;

void signal_handler(int signum) {
    printf("Received SIGINT, exiting gracefully...\n");
    pigpio_stop();
    exit(0);
}

void setup_gpio() {
    if (pigpio_init() == -1) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    if (gpioEdgeDetect(GPIO_17, PI_INPUT) == -1 ||
        gpioEdgeDetect(GPIO_18, PI_INPUT) == -1) {
        perror("Failed to set edge detection for GPIO pins");
        pigpio_stop();
        exit(EXIT_FAILURE);
    }
}

void read_sensors() {
    sensor_state[0] = gpioRead(GPIO_17);
    sensor_state[1] = gpioRead(GPIO_18);
}

void debounce_read() {
    static unsigned long last_debounce_time = 0;

    unsigned long current_time = microtime();
    if (current_time - last_debounce_time > DEBOUNCE_TIME) {
        last_debounce_time = current_time;
        read_sensors();
    }
}

void calculate_rpm() {
    if (pulse_count > 0) {
        revolutions++;
        pulse_count = 0;
    }

    pulse_count += (sensor_state[0] != sensor_state[1]);
}

void log_to_csv(const char *timestamp, int state1, int state2) {
    FILE *file = fopen("shaft_log.txt", "a");
    if (!file) {
        perror("Failed to open file for appending");
        return;
    }

    fprintf(file, "%s,%d,%d\n", timestamp, state1, state2);
    fclose(file);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    setup_gpio();

    while (1) {
        debounce_read();
        calculate_rpm();
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
        log_to_csv(timestamp, sensor_state[0], sensor_state[1]);

        usleep(100000); // Adjust as needed for desired sampling rate
    }

    pigpio_stop();
    return 0;
}

