#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define REG_PART_ID 0x00
#define REG_CONFIG 0x30
#define REG_HEART_RATE 0x02
#define REG_SP_O2 0x04

void log_reading(const char *timestamp, int heart_rate, int sp_o2) {
    FILE *fp = fopen("biometric_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening file for writing\n");
        return;
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec);
    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", time_str, heart_rate, sp_o2);
    fclose(fp);
}

int main() {
    pigpio_init(I2C_BUS);

    if (pigpio_begin(I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_range(I2C_ADDR, REG_PART_ID, 0) != 2) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        return EXIT_FAILURE;
    }

    if (pigpio_read_byte_range(I2C_ADDR, REG_CONFIG) != 0) {
        fprintf(stderr, "Failed to read CONFIG register\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int heart_rate, sp_o2;

        if (pigpio_read_byte_range(I2C_ADDR, REG_HEART_RATE) == 0) {
            heart_rate = pigpio_read_byte_range(I2C_ADDR, REG_HEART_RATE);
        }

        if (pigpio_read_byte_range(I2C_ADDR, REG_SP_O2) == 0) {
            sp_o2 = pigpio_read_byte_range(I2C_ADDR, REG_SP_O2);
        }

        if (heart_rate == -1 || sp_o2 == -1) {
            fprintf(stderr, "Failed to read heart rate or SpO2 data\n");
            continue;
        }

        log_reading(
                pigpio_get_time_as_string(),
                heart_rate,
                sp_o2
        );

        usleep(1000000); // Wait for 1 second
    }

    pigpio_end();
    fclose("biometric_log.txt"); // Close the log file
    return EXIT_SUCCESS;
}

