#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN_1 17
#define SENSOR_PIN_2 18
#define ALARM_PIN 27
#define LOG_FILE "bridge_integrity.log"
#define POLL_INTERVAL_MS 100
#define THRESHOLD_TIME_SEC 2

void log_event(const char *event_type, const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s, %s, %s\n", timestamp, event_type, strftime("%Y-%m-%dT%H:%M:%S", NULL, localtime(&now)));
    fclose(log_file);
}

void handle_sensor_event(int pin) {
    static int last_state = 0;
    int current_state = gpioRead(pin);
    if (current_state != last_state) {
        if (current_state == HIGH) {
            log_event("threshold_exceeded", get_iso8601_timestamp());
            gpioWrite(ALARM_PIN, HIGH);
        } else {
            log_event("tilt_end", get_iso8601_timestamp());
            gpioWrite(ALARM_PIN, LOW);
        }
        last_state = current_state;
    }
}

void handle_timeout(int sig) {
    gpioTerminate();
    fclose(stdout);
    printf("Clean shutdown initiated.\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    if (piGPIOInit() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(SENSOR_PIN_1, PI_OUTPUT);
    gpioSetMode(SENSOR_PIN_2, PI_OUTPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    gpioWrite(SENSOR_PIN_1, 1);
    gpioWrite(SENSOR_PIN_2, 1);
    gpioWrite(ALARM_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = handle_timeout;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        gpioDelay(POLL_INTERVAL_MS);
        handle_sensor_event(SENSOR_PIN_1);
        handle_sensor_event(SENSOR_PIN_2);
    }

    return 0;
}

// Helper function to get current ISO-8601 timestamp
const char *get_iso8601_timestamp() {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", local_time);
    return timestamp;
}

