#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define SEISMIC_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_START 0x28
#define ACCEL_END 0x2D
#define LOG_FILE "seismic_events.log"
#define THRESHOLD 500
#define LED_PIN 17
#define RETRIES 3

#define LOG_FORMAT "%Y-%m-%dT%H:%M:%SZ"

void log_event(const char* event) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp[80];
    sprintf(timestamp, LOG_FORMAT, local_time->tm_year + 1900,
            local_time->tm_mon + 1, local_time->tm_day,
            local_time->tm_hour, local_time->tm_min, local_time->tm_sec);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", event);
        fclose(log_file);
    }
}

void seismic_sensor_init() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus 1: %m");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SEISMIC_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %m");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (pigpio_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library: %m");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(LED_PIN, GPIO_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output: %m", LED_PIN);
        pigpioCloseAll();
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void clear_power_down_bit(void) {
    uint8_t ctrl1_reg[2];
    for (int i = 0; i < RETRIES; ++i) {
        if (readRegister(CTRL1_REG, sizeof(ctrl1_reg)) == 0x1D) {
            break;
        }
        syslog(LOG_ERR, "Sensor power-down bit not cleared after %d attempts.", i);
    }
}

void read_acceleration(void) {
    uint8_t accel_reg[6];
    for (int i = 0; i < RETRIES; ++i) {
        if (readRegister(accel_reg, sizeof(accel_reg)) == 0) {
            break;
        }
        syslog(LOG_ERR, "Failed to read acceleration data after %d attempts.", i);
    }

    uint32_t acceleration[3];
    for (int j = 0; j < 3; ++j) {
        acceleration[j] = (accel_reg[j * 2 + 1] << 8) | accel_reg[j * 2];
    }

    double magnitude = sqrt(acceleration[0] * acceleration[0] +
                            acceleration[1] * acceleration[1] +
                            acceleration[2] * acceleration[2]);

    if (magnitude > THRESHOLD) {
        log_event("Vibration magnitude exceeded threshold: %f", magnitude);
        gpioWrite(LED_PIN, HIGH);
        sleep(1);
        gpioWrite(LED_PIN, LOW);
    }
}

int main(int argc, char *argv[]) {
    seismic_sensor_init();
    clear_power_down_bit();

    while (1) {
        read_acceleration();
        usleep(100000);
    }

    pigpioCloseAll();
    close(i2c_fd);
    syslog(LOG_INFO, "Exiting seismic sensor program.");
    return 0;
}

