#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_IN_PINS {4, 17, 27, 22}
#define LED_PIN 18
#define POLL_INTERVAL_MS 50

int main(int argc, char *argv[]) {
    gpiod_context_t ctx;
    gpiod_button_t buttons[4];
    int led_state = 0;

    gpiod_init();

    if (gpiod_button_init(GPIO_IN_PINS, 4, buttons) != 0) {
        perror("gpiod_button_init failed");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int sensor_detected = 0;

        for (int i = 0; i < 4; i++) {
            sensor_detected |= buttons[i].value;
        }

        if (!sensor_detected) {
            led_state = 0;
        } else {
            led_state = 1;
        }

        if (led_state) {
            gpiod_output_t led_output;
            if (gpiod_output_init(LED_PIN, &led_output) != 0) {
                perror("gpiod_output_init failed");
                exit(EXIT_FAILURE);
            }
            gpiod_output(LED_PIN, led_state);
        }

        usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    gpiod_output_destroy(LED_PIN);
    gpiod_button_destroy(buttons, 4);
    gpiod_cleanup();

    return 0;

signal_handler:
    printf("Received signal, exiting gracefully.\n");
    led_state = 0;
    gpiod_output_destroy(LED_PIN);
    gpiod_button_destroy(buttons, 4);
    gpiod_cleanup();
    exit(0);
}

