#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <libgpiod.h>
#include <errno.h>

#define CHIP_ID 0
#define GPIO_COUNT 5
#define PIN_MAP {2, 3, 4, 17, 27}
#define DEBOUNCE_MS 50

#define LOG_FACILITY LOG_USER
#define LOG_IDENT "flame_monitor"

#define LOG_FILE "/var/log/flame_events.log"

volatile sig_atomic_t shutdown_requested = 0;

void sigint_handler(int sig) {
    global_flag_t flag = SIG_DFL;
    sigatomic_bool volatile *volatile_flag = &flag;
    *volatile_flag = 1;
}

void sigterm_handler(int sig) {
    global_flag_t flag = SIG_DFL;
    sigatomic_bool volatile *volatile_flag = &flag;
    *volatile_flag = 1;
}

void log_event(const char *timestamp, const char *sensor_id, int gpio_pin, int state) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp_str[80];
    sprintf(timestamp_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1,
            local_time->tm_mday, local_time->tm_hour, local_time->tm_min, local_time->tm_sec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file %s", LOG_FILE);
        return;
    }
    fprintf(log_file, "%s - Sensor ID: %s (GPIO %d) - Flame Detected\n",
            timestamp_str, sensor_id, gpio_pin);
    fclose(log_file);
    syslog(LOG_INFO, "Event logged successfully.");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[GPIO_COUNT];
    int sensor_ids[GPIO_COUNT];
    int gpio_pins[GPIO_COUNT] = {2, 3, 4, 17, 27};

    if (gpiod_chip_open(CHIP_ID, &chip) != 0) {
        syslog(LOG_ERR, "Failed to open gpiod chip.");
        return 1;
    }

    for (int i = 0; i < GPIO_COUNT; i++) {
        lines[i] = gpiod_line_new_from_gpio(chip, gpio_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to create line for GPIO %d", gpio_pins[i]);
            gpiod_chip_close(chip);
            return 1;
        }
        sensor_ids[i] = i + 1;
    }

    while (!shutdown_requested) {
        for (int i = 0; i < GPIO_COUNT; i++) {
            int state = gpiod_line_get_value(lines[i]);
            if (state == 0) {
                // No flame detected, start debounce timer
                struct timespec start_time = {0, 0};
                clock_gettime(CLOCK_REALTIME, &start_time);
            } else {
                // Flame detected, check for debounce
                int current_time = clock_gettime(CLOCK_REALTIME, NULL);
                struct timespec elapsed_time = {0, 0};
                clock_subtract(&elapsed_time, &current_time, &start_time);
                if (elapsed_time.tv_sec >= DEBOUNCE_MS / 1000) {
                    log_event(NULL, sensor_ids[i] == 1 ? "Sensor 1" : "Sensor " + (sensor_ids[i] - 1), gpio_pins[i], 1);
                }
            }
        }
        usleep(1000000); // Sleep for 1 second
    }

    gpiod_chip_close(chip);
    syslog(LOG_INFO, "Chip closed.");

    shutdown_requested = 1;
    for (int i = 0; i < GPIO_COUNT; i++) {
        gpiod_line_put(lines[i]);
    }
    for (int i = 0; i < GPIO_COUNT; i++) {
        free(lines[i]);
    }

    closelog();
    return 0;
}

