#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define LED_GPIO 18
#define ALS_REG 0x04
#define CONFIG_REG 0x00
#define I2C_BUS 1
#define I2C_ADDR 0x10
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

#define LOG_FORMAT "%d %d %d %d\n"

int main(int argc, char *argv[]) {
    int led_gpio, i2c_fd, error_code;
    struct i2c_client *client;
    struct i2c_msg msg;
    long config_value, ambient_light;
    time_t now;
    struct tm *time_info;
    char log_msg[100];

    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    client = i2c_open(I2C_BUS, I2C_ADDR);
    if (client == NULL) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    config_value = 0x0000; // ALS gain 1/8, integration time 100 ms
    if (i2c_transfer(client, NULL, (void *)&config_value, 2, CONFIG_REG) < 0) {
        fprintf(stderr, "Failed to write sensor configuration\n");
        i2c_close(client);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    while (1) {
        i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to open I2C bus\n");
            pigpio_terminate();
            return EXIT_FAILURE;
        }

        ambient_light = i2c_read_i2c_byte_checked(client, ALS_REG);
        if (ambient_light == -1) {
            fprintf(stderr, "I2C read failed\n");
            i2c_close(i2c_fd);
            pigpio_terminate();
            return EXIT_FAILURE;
        }

        double lux = (double)ambient_light * 0.0576;

        if (lux < 100) {
            pigpio_set_pwm_range(LED_GPIO, 0, PWM_RANGE);
            pigpio_set_duty_cycle(LED_GPIO, PWM_RANGE);
        } else if (lux < 500) {
            pigpio_set_pwm_range(LED_GPIO, 0, 75);
            pigpio_set_duty_cycle(LED_GPIO, 75);
        } else if (lux < 1000) {
            pigpio_set_pwm_range(LED_GPIO, 0, 50);
            pigpio_set_duty_cycle(LED_GPIO, 50);
        } else {
            pigpio_set_pwm_range(LED_GPIO, 0, 25);
            pigpio_set_duty_cycle(LED_GPIO, 25);
        }

        now = time(NULL);
        time_info = localtime(&now);
        strftime(log_msg, sizeof(log_msg), LOG_FORMAT, time_info);
        write(STDOUT_FILENO, log_msg, strlen(log_msg));

        if (fwrite(log_msg, sizeof(int), 1, LOG_FILE) == -1) {
            perror("Failed to write to log file");
            break;
        }

        log_msg[strlen(log_msg) - 1] = '\0'; // Ensure null termination

        usleep(1000000); // Wait for 1 second
    }

    pigpio_terminate();
    i2c_close(i2c_fd);
    close(LOG_FILE);

    return EXIT_SUCCESS;
}

