#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <pigpio.h>

#define GPIO_TTOUCH_PINS {2, 3, 4, 5, 6, 7, 8, 9}
#define LED_PIN 17
#define TOUCH_LOG_FILE "touch_log.txt"

void signal_handler(int signum) {
    printf("Received signal %d, turning off LED and releasing resources.\n", signum);
    pigpio_stop();
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    exit(0);
}

void debounce_channel(int pin) {
    static unsigned long last_change_time = 0;
    unsigned long current_time = microtime(NULL);
    if (current_time - last_change_time > 50) {
        last_change_time = current_time;
        // No change, so do nothing.
    } else {
        // Touch detected, log the event and turn on the LED.
        FILE *touch_log = fopen(TOUCH_LOG_FILE, "a");
        if (!touch_log) {
            fprintf(stderr, "Error opening touch_log.txt\n");
            return;
        }
        fprintf(touch_log, "%s - Channel %d Touched\n", get_current_time(), pin);
        fclose(touch_log);
        gpioOutput(LED_PIN, 1); // Turn on LED
    }
}

int main() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    for (int pin : GPIO_TTOUCH_PINS) {
        gpioSetMode(pin, PI_INPUT);
        gpioPullUp(pin);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        for (int pin : GPIO_TTOUCH_PINS) {
            if (gpioRead(pin) == PI_INPUT_HIGH) {
                debounce_channel(pin);
            }
        }

        // Turn off LED if all channels are released.
        int all_released = 1;
        for (int pin : GPIO_TTOUCH_PINS) {
            if (gpioRead(pin) == PI_INPUT_HIGH) {
                all_released = 0;
                break;
            }
        }
        if (all_released) {
            gpioOutput(LED_PIN, 0);
        }

        usleep(50000); // Sleep for 50 ms
    }

    pigpioTerminate();
    return 0;
}

