#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3001_ADDRESS 0x44
#define CONFIG_REGISTER 0x01
#define RESULT_REGISTER 0x00
#define CONFIG_WORD 0xC810
#define CONVERSION_TIME 100

void sigint_handler(int signum) {
    gpioTerminate();
    close(piGPIO_I2C_HANDLE);
    fprintf(stderr, "Cleaning up...\n");
    exit(0);
}

int main() {
    int piGPIO_I2C_HANDLE;
    int ret;

    // Initialize pigpio
    ret = pigpioInit(I2C_BUS);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", piGPIO_strerror(ret));
        return EXIT_FAILURE;
    }

    // Open I2C bus
    piGPIO_I2C_HANDLE = i2cOpen(I2C_BUS, OPT3001_ADDRESS);
    if (piGPIO_I2C_HANDLE < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpioStrerror(piGPIO_I2C_HANDLE));
        return EXIT_FAILURE;
    }

    // Configure the sensor
    uint16_t configWord = CONFIG_WORD;
    ret = i2cWriteWordData(piGPIO_I2C_HANDLE, OPT3001_ADDRESS, &configWord, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to write configuration word: %s\n", pigpioStrerror(ret));
        return EXIT_FAILURE;
    }

    // Wait for the first conversion
    sleep(CONVERSION_TIME / 1000);

    // Read the result register
    uint16_t result;
    ret = i2cReadWordData(piGPIO_I2C_HANDLE, OPT3001_ADDRESS, &result, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read result register: %s\n", pigpioStrerror(ret));
        return EXIT_FAILURE;
    }

    // Convert to lux
    float lux = (float)result / (1 << 16);

    // Log to file and stdout
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *logFile = fopen("light_data.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open light_data.txt for appending\n");
        return EXIT_FAILURE;
    }
    fprintf(logFile, "%s, %f\n", timestamp, lux);
    fprintf(stdout, "%f\n", lux);
    fclose(logFile);

    // Print lux value
    printf("Live Lux: %.2f\n", lux);

    // Clean up
    i2cClose(piGPIO_I2C_HANDLE);
    gpioTerminate();

    return EXIT_SUCCESS;
}

// Install SIGINT handler
signal(SIGINT, sigint_handler);

