#define SENSOR_GPIO 4
#define ALERT_GPIO 17
#define POLL_INTERVAL_MS 500
#define LOG_FILE "fire_events.log"

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up resources...\n");
    pigpio_terminate();
    close(1); // Assuming standard input is a pipe for signal handling
    fclose(stdout);
