    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        int sensor_state = pigpio_get_gpio(pi, SENSOR_GPIO);

        if (sensor_state == -1) {
            fprintf(log_file, "Error reading sensor state: %s\n", strerror(errno));
