#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define TOUCH_PIN 7
#define DEBOUNCE_INTERVAL 50
#define LOG_FILE "touch_log.txt"

void signal_handler(int signum) {
    printf("Received signal %d, releasing touch line...\n", signum);
    gpiod_edge_output_enable(TOUCH_PIN, GPIOD_OUTPUT_ENABLE_DISABLE_OUTPUT);
    close(fildes);
    exit(0);
}

int main(int argc, char *argv[]) {
    int fildes;
    gpiod_context ctx;
    gpiod_chip_t chip;
    gpiod_edge_t edge;
    gpiod_edge_out_t out;

    if (signal(SIGINT, signal_handler) == SIG_IGN || signal(SIGTERM, signal_handler) == SIG_IGN) {
        perror("Failed to register signal handlers");
        exit(EXIT_FAILURE);
    }

    ctx = gpiod_new_context();
    if (!ctx) {
        perror("Failed to create gpiod context");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_add_pin(ctx, TOUCH_PIN, GPIOD_IN_PULLDOWN);
    if (!chip) {
        perror("Failed to add pin to chip");
        exit(EXIT_FAILURE);
    }

    edge = GPIOD_EDGE_RISING;
    out = GPIOD_OUTPUT_ENABLE_OUTPUT;

    if (gpiod_edge_output_enable(ctx, chip, edge, out) < 0) {
        perror("Failed to configure edge output");
        exit(EXIT_FAILURE);
    }

    gpiod_chip_enable(ctx, chip);

    while (1) {
        int state = gpiod_get_value(ctx, chip);
        if (state != 0) {
            if (state == GPIOD_INPUT_HIGH) {
                FILE *log_file = fopen(LOG_FILE, "a");
                if (!log_file) {
                    perror("Failed to open touch_log.txt");
                    gpiod_chip_disable(ctx, chip);
                    gpiod_context_destroy(&ctx);
                    exit(EXIT_FAILURE);
                }
                fprintf(log_file, "%s: Touch Detected\n", gmtime(&current_time()));
                fclose(log_file);
            } else {
                fprintf(log_file, "%s: Touch Released\n", gmtime(&current_time()));
                fclose(log_file);
            }
        }
        usleep(DEBOUNCE_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    gpiod_chip_disable(ctx, chip);
    gpiod_context_destroy(&ctx);
    close(fildes);
    return 0;
}

int current_time() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return asctime((localtime(&tv.tv_sec)));
}

