#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08
#define COMMAND 0x36
#define COMMAND_LENGTH 2
#define READ_LENGTH 3
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

#define LOG_FILE "cooling_log.csv"

void log_entry(const char *status) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(file, "%s,%f,%s\n", "Timestamp", (double)time(NULL), status);
    fclose(file);
}

int validate_crc(uint16_t raw_value, uint8_t crc) {
    uint16_t calculated_crc = 0;
    for (int i = 0; i < 8; i++) {
        calculated_crc = (calculated_crc << 1) ^ (raw_value & 0x80 ? 0x31 : 0x00);
        raw_value <<= 1;
    }
    return calculated_crc == crc;
}

int main() {
    int i2c_fd;
    int ret;

    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        perror("pigpioInitialise");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    ret = i2cSetup(I2C_BUS, 100000);
    if (ret < 0) {
        perror("i2cSetup");
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Send command to start reading
    if (pigpioWriteByte(0, COMMAND) < 0) {
        perror("pigpioWriteByte");
        i2cClose(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Wait at least 2 ms
    usleep(200000);

    // Read data from I2C
    uint16_t raw_value;
    uint8_t crc;
    ret = i2cRead(i2c_fd, &raw_value, 1);
    if (ret < 0) {
        perror("i2cRead");
        i2cClose(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }
    ret = i2cRead(i2c_fd, &crc, 1);
    if (ret < 0) {
        perror("i2cRead");
        i2cClose(i2c_fd);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Validate CRC
    if (!validate_crc(raw_value, crc)) {
        log_entry("ERROR");
        pigpioWriteByte(0, COMMAND); // Retry command
        return main();
    }

    // Convert raw value to ml/min
    double flow_rate = (double)raw_value / 90.0;

    // Check if flow rate is within plausible range
    if (flow_rate < 0.0 || flow_rate > 100.0) {
        log_entry("INVALID");
    }

    // Log the entry
    log_entry("OK");

    // Close I2C handle
    i2cClose(i2c_fd);

    // Check for file creation and log header
    if (access(LOG_FILE, F_OK) == 0) {
        FILE *file = fopen(LOG_FILE, "r");
        if (file) {
            fseek(file, 0, SEEK_END);
            long file_size = ftell(file);
            fclose(file);

            if (file_size == 0) {
                log_entry("Timestamp,Flow Rate (ml/min),Status");
            }
        }
    }

    // Handle SIGINT for graceful shutdown
    signal(SIGINT, signal_handler);

    // Run in a loop
    while (1) {
        usleep(1000000); // Sleep for 1 second
    }

    // Terminate pigpio
    pigpioTerminate();

    return EXIT_SUCCESS;

signal_handler:
    log_entry("SIGINT");
    close(i2c_fd);
    pigpioTerminate();
    return EXIT_SUCCESS;
}

