#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>
#include <libgpiod.h>

#define GPIO_LEFT 17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT 22
#define POLL_INTERVAL_MS 50
#define LOG_FILE "path_log.csv"

bool init_gpio_chip(int *chip_fd) {
    *chip_fd = gpiod_chip_open(GPIOD_BOARD_0, NULL);
    if (*chip_fd < 0) {
        perror("Failed to open GPIO chip");
        return false;
    }
    return true;
}

bool setup_gpio_lines(int chip_fd) {
    int left_gpio = GPIO_LEFT;
    int middle_gpio = GPIO_MIDDLE;
    int right_gpio = GPIO_RIGHT;

    if (gpiod_chip_line_request(chip_fd, left_gpio, GPIOD_MODE_INPUT) < 0) {
        perror("Failed to request GPIO line for left sensor");
        return false;
    }

    if (gpiod_chip_line_request(chip_fd, middle_gpio, GPIOD_MODE_INPUT) < 0) {
        perror("Failed to request GPIO line for middle sensor");
        return false;
    }

    if (gpiod_chip_line_request(chip_fd, right_gpio, GPIOD_MODE_INPUT) < 0) {
        perror("Failed to request GPIO line for right sensor");
        return false;
    }

    return true;
}

void release_gpio_lines(int chip_fd) {
    int left_gpio = GPIO_LEFT;
    int middle_gpio = GPIO_MIDDLE;
    int right_gpio = GPIO_RIGHT;

    gpiod_chip_line_release(chip_fd, left_gpio);
    gpiod_chip_line_release(chip_fd, middle_gpio);
    gpiod_chip_line_release(chip_fd, right_gpio);
}

void log_sensor_readings(int chip_fd) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    while (true) {
        int left_reading = gpiod_get_line_value(chip_fd, left_gpio);
        int middle_reading = gpiod_get_line_value(chip_fd, middle_gpio);
        int right_reading = gpiod_get_line_value(chip_fd, right_gpio);

        char timestamp[32];
        time_strftime(timestamp, "%Y-%m-%T", current_time());

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_reading, middle_reading, right_reading);
        fflush(log_file);

        usleep(POLL_INTERVAL_MS * 1000 / 1000);
    }

    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int chip_fd;
    bool success = init_gpio_chip(&chip_fd);
    if (!success) {
        return EXIT_FAILURE;
    }

    if (!setup_gpio_lines(chip_fd)) {
        release_gpio_lines(chip_fd);
        return EXIT_FAILURE;
    }

    log_sensor_readings(chip_fd);

    // Handle SIGINT cleanly
    atexit(release_gpio_lines);

    return EXIT_SUCCESS;
}

