#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO_TTP223 23
#define GPIO_LED 24
#define LOG_FILE "touch_log.txt"

void log_touch_event(const char *timestamp, int led_state) {
    time_t now = time(NULL);
    char time_str[80];
    strftime(time_str, sizeof(time_str), "%Y-%m-%T", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s, LED state: %d\n", time_str, led_state);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int chip_fd, line_fd;
    gpiod_context ctx;
    gpiod_chip_t *chip;
    gpiod_line_t *line;
    gpiod_event_t event;

    if (pi4js_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return EXIT_FAILURE;
    }

    chip_fd = pi4js_chip_open(GPIO_CHIP);
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        pi4js_close(chip_fd);
        return EXIT_FAILURE;
    }

    chip = pi4js_chip_line_request(chip_fd, GPIO_TTP223);
    if (!chip) {
        fprintf(stderr, "Failed to request line from GPIO chip\n");
        pi4js_close(chip_fd);
        return EXIT_FAILURE;
    }

    line_fd = pi4js_line_open(chip, PI4JS_MODE_INPUT_ACTIVE_HIGH);
    if (line_fd < 0) {
        fprintf(stderr, "Failed to open line for TTP223\n");
        pi4js_close_line(chip, line_fd);
        pi4js_chip_close(chip);
        pi4js_close(chip_fd);
        return EXIT_FAILURE;
    }

    gpiod_event_init(&event, &ctx);

    while (1) {
        pi4js_event_wait(line_fd, &event, PI4JS_EVENT_RISING, 1000);
        if (event.value) {
            log_touch_event(pi4js_time_iso8601(), 1);
            pi4js_line_write(line_fd, 1);
        } else {
            log_touch_event(pi4js_time_iso8601(), 0);
            pi4js_line_write(line_fd, 0);
        }
    }

    pi4js_line_close(line_fd);
    pi4js_chip_close(chip);
    pi4js_close(chip_fd);

    return 0;
}

