#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_MS 2000
#define BUZZER_SLICE_MS 100

#define LOG_FILE "alert_log.txt"

void log_event(const char *event_str) {
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, event_str);
        fclose(log_file);
    }
}

void buzzer_activation(void) {
    // Activate buzzer for 2 seconds
    for (int i = 0; i < BUZZER_DURATION_MS / BUZZER_SLICE_MS; i++) {
        gpio_line_set_value(gpiod_chip_open_by_name("gpiochip0"), BUZZER_PIN, 1);
        usleep(BUZZER_SLICE_MS * 1000);
    }
}

void buzzer_deactivation(void) {
    // Deactivate buzzer
    gpio_line_set_value(gpiod_chip_open_by_name("gpiochip0"), BUZZER_PIN, 0);
}

void signal_handler(int signum) {
    buzzer_deactivation();
    close(gpiod_chip_open_by_name("gpiochip0"));
    fclose(LOG_FILE);
    exit(0);
}

int main(int argc, char *argv[]) {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    log_event("System started");

    gpiod_chip chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    gpiod_line *flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    gpiod_line *buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);

    if (!flame_sensor || !buzzer) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int flame_state = gpiod_line_get_value(flame_sensor);
        if (flame_state == 0 && gpiod_line_request_input(flame_sensor)) {
            log_event("Flame detected");
            buzzer_activation();
        }

        usleep(POLL_INTERVAL_MS / 1000);
    }

    return 0;
}

