#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_TOUCH 4
#define GPIO_LED 17
#define DEBOUNCE_DELAY 200
#define LOG_FILE "touch_log.txt"
#define POLL_INTERVAL 10

void debounce_handler(int signal) {
    // No action needed for debounce handling in this case, as we're using a software debounce.
}

void log_touch_event(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        exit(EXIT_FAILURE);
    }

    if (fputs(timestamp, log_file) == EOF) {
        fprintf(stderr, "Warning: Failed to write to log file.\n");
    } else {
        fclose(log_file);
    }
}

void setup_gpio(void) {
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Error initializing pigpio.\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_TOUCH, PI_OUTPUT);
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Turn off the LED initially

    if (piGPIO_set_debounce_handler(debounce_handler, DEBOUNCE_DELAY) < 0) {
        fprintf(stderr, "Error setting software debounce.\n");
        exit(EXIT_FAILURE);
    }
}

void touch_event_handler(void) {
    static unsigned long last_change_time = 0;
    unsigned long current_time = microtime_ms();

    if (current_time - last_change_time > DEBOUNCE_DELAY) {
        last_change_time = current_time;
        gpioRead(GPIO_TOUCH, &gpioState);

        if (gpioState == PI_INPUT_HIGH) {
            gpioWrite(GPIO_LED, !gpioState); // Toggle the LED
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
            log_touch_event(timestamp);
        }
    }
}

void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        gpioWrite(GPIO_LED, 0); // Turn off the LED
        fclose(stdout);
        fclose(stderr);
        piGPIO_terminate();
        remove(LOG_FILE);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    while (1) {
        touch_event_handler();
        usleep(POLL_INTERVAL * 1000 / HRTIM_PER_SEC);
    }

    return 0;
}

