    if (pigpio_setup_gpio(4) != 0 ||
        pigpio_setup_gpio(17) != 0 ||
        pigpio_setup_gpio(27) != 0) {
        fprintf(stderr, "Failed to set GPIO modes and pull-ups\n");
        return 1;
    }

    // Enable internal pull-up resistors
    pigpio_set_mode(4, PIGIO_OUTPUT);
    pigpio_set_pullup(4, 1);

    pigpio_set_mode(17, PIGIO_INPUT);
    pigpio_set_pullup(17, 1);

    pigpio_set_mode(27, PIGIO_INPUT);
    pigpio_set_pullup(27, 1);

