        for (int i = 0; i < 3; i++) {
            sensor_states_read[i] = pigpio_get_gpio(sensor_states[i] ? 1 : 0);
            if (sensor_states_read[i] == -1) {
                fprintf(stderr, "Error reading sensor %d\n", i + 1);
                continue;
