        // Log state changes
        time_t now = time(NULL);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(&now));
        fprintf(log_file, "%s,Sensor %d: %s\n", timestamp, 1 + i, sensor_states_read[i] ? "high" : "low");

        // Record initial state if this is the first read
        if (sensor_states_read[0] == -1) {
            sensor_states[0] = sensor_states_read[0];
        }

        // Wait for 100 ms
        gpioDelay(100);
    }

    // Clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Terminate pigpio
    gpioTerminate();

    fclose(log_file);
    return 0;
}

