#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/epoll.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-dev-v2.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define HEART_RATE_REG 0x2A
#define LED_CURRENT_REG 0x00
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01

#define LOG_FILE "heart_rate.csv"
#define SAMPLE_COUNT 5

int i2c_fd;

void log_heart_rate(const char *timestamp, int bpm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fp, "%s,%d\n", timestamp, bpm);
    fclose(fp);
}

int main() {
    int ret;
    struct i2c_client *client;

    // Initialize pigpio
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    ret = i2c_open(I2C_BUS, &client);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_terminate();
        return 1;
    }

    // Check sensor presence
    ret = i2c_write_reg(client, I2C_ADDR, LED_CURRENT_REG, 0x3F);
    if (ret < 0) {
        fprintf(stderr, "Failed to write LED current register\n");
        i2c_close(client);
        pigpio_terminate();
        return 1;
    }

    ret = i2c_write_reg(client, I2C_ADDR, AVERAGING_REG, 0x04);
    if (ret < 0) {
        fprintf(stderr, "Failed to write averaging register\n");
        i2c_close(client);
        pigpio_terminate();
        return 1;
    }

    ret = i2c_write_reg(client, I2C_ADDR, ENABLE_REG, 0x01);
    if (ret < 0) {
        fprintf(stderr, "Failed to write enable register\n");
        i2c_close(client);
        pigpio_terminate();
        return 1;
    }

    // Read heart rate
    unsigned int raw_bpm;
    ret = i2c_read_word_data(client, I2C_ADDR, HEART_RATE_REG, &raw_bpm, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read heart rate\n");
        i2c_close(client);
        pigpio_terminate();
        return 1;
    }

    // Convert to BPM
    int bpm_value = raw_bpm * 0.5;

    // Apply moving average
    int filtered_bpm = 0;
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        filtered_bpm += bpm_value;
    }
    filtered_bpm /= SAMPLE_COUNT;

    // Validate filtered BPM
    if (filtered_bpm < 30 || filtered_bpm > 220) {
        fprintf(stderr, "Invalid heart rate: %d\n", filtered_bpm);
        i2c_close(client);
        pigpio_terminate();
        return 1;
    }

    // Log valid reading
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    log_heart_rate(timestamp, filtered_bpm);

    // Sleep for one second
    usleep(1000000);

    // Clean up on SIGINT
    atexit(cleanup);

    return 0;

cleanup:
    i2c_close(client);
    pigpio_terminate();
    fclose(stdout);
    return 0;
}

int i2c_read_word_data(struct i2c_client *client, int addr, unsigned int reg, unsigned int *data, int len) {
    unsigned char buf[2];
    int ret = i2c_transfer(client, addr, reg, I2C_READ, buf, len, data);
    if (ret < 0) {
        fprintf(stderr, "i2c_read_word_data failed: %s\n", strerror(errno));
        return ret;
    }
    return 0;
}

int i2c_transfer(struct i2c_client *client, int addr, unsigned int reg, int type, unsigned char *buf, int len, void *data) {
    int ret;
    if (type == I2C_READ) {
        ret = i2c_read_byte_data(client, addr, reg, buf, len);
    } else {
        ret = i2c_write_byte_data(client, addr, reg, buf, len);
    }
    if (ret < 0) {
        fprintf(stderr, "i2c_transfer failed: %s\n", strerror(errno));
        return ret;
    }
    return 0;
}

int i2c_read_byte_data(struct i2c_client *client, int addr, unsigned int reg, unsigned char *buf, int len) {
    int ret = i2c_read_block_data(client, addr, reg, buf, len);
    if (ret < 0) {
        fprintf(stderr, "i2c_read_byte_data failed: %s\n", strerror(errno));
        return ret;
    }
    return 0;
}

int i2c_write_byte_data(struct i2c_client *client, int addr, unsigned int reg, unsigned char *buf, int len) {
    int ret = i2c_write_byte_data(client, addr, reg, buf, len);
    if (ret < 0) {
        fprintf(stderr, "i2c_write_byte_data failed: %s\n", strerror(errno));
        return ret;
    }
    return 0;
}

int i2c_read_reg(struct i2c_client *client, int addr, unsigned int reg) {
    unsigned char data;
    int ret = i2c_read_byte_data(client, addr, reg, &data, 1);
    if (ret < 0) {
        fprintf(stderr, "i2c_read_reg failed: %s\n", strerror(errno));
        return ret;
    }
    return data;
}

int i2c_write_reg(struct i2c_client *client, int addr, unsigned int reg, unsigned char data) {
    int ret = i2c_write_byte_data(client, addr, reg, &data, 1);
    if (ret < 0) {
        fprintf(stderr, "i2c_write_reg failed: %s\n", strerror(errno));
        return ret;
    }
    return 0;
}

