#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define POLL_INTERVAL 100
#define LOG_FILE "flame_log.txt"

void handle_signal(int signum) {
    gpiod_chip_t *chip;
    gpiod_debounce_t debounce;
    gpiod_direction_t direction;
    gpiod_output_t output;
    gpiod_output_init(&output, GPIO_PIN);

    // Release GPIO line
    gpiod_deinit(GPIOD_CHIP(0));
    chip = GPIOD_CHIP(0);
    gpiod_output_free(&output);

    // Close log file
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    close(fd);

    // Terminate
    exit(signum);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpiod_chip_t *chip;
    gpiod_debounce_t debounce;
    gpiod_direction_t direction;
    gpiod_output_t output;
    gpiod_output_init(&output, GPIO_PIN);

    // Initialize GPIO chip
    if (gpiod_chip_init(GPIOD_CHIP(0), &chip) != 0) {
        perror("Failed to initialize GPIO chip");
        return EXIT_FAILURE;
    }

    // Set GPIO pin as input with internal pull-up
    if (gpiod_config_direction(chip, GPIO_PIN, GPIOD_DIR_IN) != 0) {
        perror("Failed to configure GPIO pin direction");
        return EXIT_FAILURE;
    }

    // Enable internal pull-up
    if (gpiod_config_edge_up(chip, GPIO_PIN) != 0) {
        perror("Failed to enable internal pull-up");
        return EXIT_FAILURE;
    }

    // Set debounce time
    debounce.period = 10;
    debounce.edge_rise_time = 1;
    debounce.edge_fall_time = 1;
    debounce.samples = 1;

    // Configure GPIO line with debounce
    if (gpiod_config_debounce(chip, GPIO_PIN, &debounce) != 0) {
        perror("Failed to configure debounce");
        return EXIT_FAILURE;
    }

    // Poll the GPIO line every 100 ms
    while (1) {
        int value = gpiod_get_level(chip, GPIO_PIN);

        if (value == GPIOD_LEVEL_FALLING) {
            // Falling edge detected, print and log
            printf("FLAME DETECTED\n");
            FILE *log_fd = fopen(LOG_FILE, "a");
            if (log_fd == NULL) {
                perror("Failed to open log file");
                return EXIT_FAILURE;
            }
            fprintf(log_fd, "%sFLAME DETECTED\n", current_time());
            fclose(log_fd);
        }

        // Sleep for the specified interval
        usleep(POLL_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

// Helper function to get current timestamp
static char *current_time(void) {
    static char timestamp[64];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    return timestamp;
}

