#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <libgpiod.h>

#define TOUCH_SENSOR_PINS {5, 6, 7, 8, 9, 10, 11, 12}
#define DISPLAY_PIN {17, 24}
#define LOG_FILE "touch_log.txt"
#define STABILIZATION_DELAY 200000
#define POLL_INTERVAL 10000

int main() {
    int ret;
    gpiod_chip_t chip;
    gpiod_line_t lines[8];
    gpiod_line_config_t config;
    gpiod_line_settings_t settings;
    gpiod_line_settings_t *prev_settings;
    int counter = 0;
    int touch_log_fd;
    char log_msg[100];

    ret = gpiod_chip_open(&chip, NULL);
    if (ret < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_request_lines(chip, TOUCH_SENSOR_PINS, 8, NULL);
    if (ret < 0) {
        perror("gpiod_chip_request_lines");
        gpiod_chip_release(chip);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 8; i++) {
        lines[i] = i;
    }

    prev_settings = NULL;

    // Stabilization delay
    usleep(STABILIZATION_DELAY);

    // Open log file
    touch_log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (touch_log_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = gpiod_line_request_get_value(chip, lines, 1, &config, &settings);
        if (ret < 0) {
            perror("gpiod_line_request_get_value");
            gpiod_line_release(chip, lines, 1);
            continue;
        }

        int rising_edge = 0;
        for (int i = 0; i < 8; i++) {
            if (settings.settings.value & (1 << i)) {
                if (!prev_settings[i].settings.value) {
                    rising_edge = i;
                    break;
                }
            }
            prev_settings[i] = config;
        }

        if (rising_edge != -1) {
            counter++;
            if (counter >= 256) {
                counter = 0;
            }

            // Update GPIO outputs
            for (int i = 0; i < 8; i++) {
                if (rising_edge == i) {
                    gpiod_line_settings_set_direction(&settings, GPIOD_OUTPUT);
                    gpiod_line_request_set_value(chip, lines[i], 1);
                } else {
                    gpiod_line_request_set_value(chip, lines[i], 0);
                }
            }

            // Display counter on GPIO24
            int bit_index = counter % 8;
            gpiod_line_request_set_value(chip, DISPLAY_PIN[1], (counter >> bit_index) & 1);

            // Log touch event
            snprintf(log_msg, sizeof(log_msg), "YYYY-MM-DDTHH:MM:SSZ, Channel: %d, Counter: %d\n",
                    getdate(), rising_edge, counter);
            write(touch_log_fd, log_msg, strlen(log_msg));
            printf("Touch on channel %d | Counter: %d\n\n", rising_edge, counter);
        }

        // Release lines
        for (int i = 0; i < 8; i++) {
            gpiod_line_release(chip, lines[i]);
        }

        // Sleep before next poll
        usleep(POLL_INTERVAL * 1000 / 1000);
    }

    // Graceful shutdown
    for (int i = 0; i < 8; i++) {
        gpiod_line_release(chip, lines[i]);
    }
    gpiod_chip_release(chip);

    close(touch_log_fd);
    exit(EXIT_SUCCESS);
}

