#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PINS {17, 18, 27, 22}
#define POLL_INTERVAL_MS 100
#define LOG_FILE "tracking_log.csv"

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    gpiod_line_request_input_all_off();
    fclose(stdout);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd_log = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd_log < 0) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    gpiod_context ctx;
    gpiod_init(&ctx);

    if (gpiod_context_init(&ctx) != 0) {
        perror("Failed to initialize gpiod context");
        close(fd_log);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_input_all(GPIO_PINS, GPIOD_MODE_INPUT, GPIOD_OUT_DISABLE);

    if (gpiod_line_request_input_all(GPIO_PINS, GPIOD_MODE_INPUT, GPIOD_OUT_DISABLE) != 0) {
        perror("Failed to set GPIO pins as inputs");
        gpiod_context_destroy(&ctx);
        close(fd_log);
        exit(EXIT_FAILURE);
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
    fprintf(stdout, "%s,0,0,0,0\n", timestamp); // Header row

    while (1) {
        int values[4];
        if (gpiod_line_get_value(GPIO_PINS, values) != 0) {
            perror("Failed to read GPIO values");
            continue;
        }

        fprintf(stdout, "%s, %d, %d, %d, %d\n", timestamp, values[0], values[1], values[2], values[3]);
    }

    gpiod_context_destroy(&ctx);
    close(fd_log);
    return 0;
}

