void log_tilt_event(const char *sensor_id, const char *timestamp) {
    char log_msg[100];
    sprintf(log_msg, "%s%s\n", timestamp, sensor_id);
    int log_fd = open("/var/log/tilt_events.log", O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return;
    }
    write(log_fd, log_msg, strlen(log_msg));
    close(log_fd);
}

int main(int argc, char *argv[]) {
    gpiod_context ctx;
    gpiod_chip_t chip;
    gpiod_direction_t dir;
    gpiod_edge_t edge;
    gpiod_edge_event_t edgetype;
    gpiod_edge_event_t *edge_events = NULL;
    gpiod_edge_event_t *edge_event;
    gpiod_error_t err;

    err = gpiod_chip_init(&ctx, &chip, NULL);
    if (err != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to initialize gpiod chip\n");
        return EXIT_FAILURE;
    }

    err = gpiod_chip_request(chip, &dir, GPIO_LINE_17, GPIOD_OUT_ACTIVE_LOW);
    if (err != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to set GPIO17 as input with active-low pull-up\n");
        return EXIT_FAILURE;
    }

    err = gpiod_chip_request(chip, &dir, GPIO_LINE_18, GPIOD_OUT_ACTIVE_LOW);
    if (err != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to set GPIO18 as input with active-low pull-up\n");
        return EXIT_FAILURE;
    }

    err = gpiod_edge_init(&ctx, &edge, GPIOD_EDGE_BOTH, DEBOUNCE_WINDOW_MS);
    if (err != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to initialize edge detection\n");
        return EXIT_FAILURE;
    }

    err = gpiod_edge_event_add(&ctx, edge, GPIO_LINE_17, GPIOD_INPUT, NULL, 0, &edge_events);
    if (err != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to add edge event for GPIO17\n");
        return EXIT_FAILURE;
    }

    err = gpiod_edge_event_add(&ctx, edge, GPIO_LINE_18, GPIOD_INPUT, NULL, 0, &edge_events);
    if (err != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to add edge event for GPIO18\n");
        return EXIT_FAILURE;
    }

    while (1) {
        for (edge_event = edge_events; *edge_event; edge_event++) {
            if (edge_event->line == GPIO_LINE_17) {
                log_tilt_event("1", gmtime(&current_time()));
            } else if (edge_event->line == GPIO_LINE_18) {
                log_tilt_event("2", gmtime(&current_time()));
            }
        }

        usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    gpiod_edge_event_del(&ctx, edge_events);
    gpiod_chip_release(chip);
    gpiod_context_destroy(&ctx);

    return EXIT_SUCCESS;
}

