            perror("Failed to write newline to log file");
            exit(EXIT_FAILURE);
        }

        usleep(SAMPLE_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    gpiod_button_del(&button1);
    gpiod_button_del(&button2);
    gpiod_chip_del(&chip);
    gpiod_ctx_destroy(&ctx);

    close(sensor1_fd);
    close(sensor2_fd);
    close(led_fd);

    if (fseek(sensor1_fd, 0, SEEK_SET) == 0) {
        if (fclose(sensor1_fd) == 0) {
            printf("Log file closed successfully.\n");
        }
    } else {
        perror("Failed to seek to the beginning of the log file");
        exit(EXIT_FAILURE);
    }

    printf("Exiting gracefully...\n");
    gpiod_exit();

    return 0;
}

