#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define MIC_PIN 7
#define LED_PIN 11
#define SAMPLE_PERIOD_US 125
#define SAMPLE_RATE_HZ 8000

volatile sig_atomic_t quit = false;

void signal_handler(int signum) {
    quit = true;
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init();
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_strerror(pi));
        exit(EXIT_FAILURE);
    }

    if (sigset_t sigset = sigset_t_create()) {
        sigemptyset(&sigset);
        sigaddset(&sigset, SIGINT);
        if (sigprocmask(SIG_BLOCK, &sigset, NULL) == -1) {
            fprintf(stderr, "Failed to block signals: %s\n", strerror(errno));
            pi_terminate();
            exit(EXIT_FAILURE);
        }
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetup(MIC_PIN, PI_ACTIVE_HIGH);

    while (!quit) {
        int mic_state = gpioRead(MIC_PIN);
        if (mic_state == PI_INPUT_HIGH) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            double timestamp_ns = (ts.tv_sec * 1e9) + ts.tv_nsec;
            printf("%.3f\n", timestamp_ns / 1e6); // millisecond precision

            gpioWrite(LED_PIN, PI_OUTPUT);
            usleep(SAMPLE_PERIOD_US / 2); // half period for LED control
            gpioWrite(LED_PIN, PI_INPUT);

            clock_usleep(SAMPLE_PERIOD_US / 2);
        }
        usleep(SAMPLE_PERIOD_US / 2);
    }

    gpioTerminate();
    pi_shutdown();
    return 0;
}

