#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_LEFT 17
#define GPIO_CENTER 27
#define GPIO_RIGHT 22

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    gpiod_exit();
    exit(0);
}

int main() {
    struct sigset_t sigset;
    sigset_t mask;

    // Initialize signal handlers
    sigset_init(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    // Configure GPIO pins as active-low with pull-up
    if (gpiod_gpio_config_default(GPIO_LEFT, GPIOD_OUTPUT_ACTIVE_LOW, GPIOD_PULL_UP) < 0) {
        perror("Failed to configure GPIO17");
        return EXIT_FAILURE;
    }
    if (gpiod_gpio_config_default(GPIO_CENTER, GPIOD_OUTPUT_ACTIVE_LOW, GPIOD_PULL_UP) < 0) {
        perror("Failed to configure GPIO27");
        return EXIT_FAILURE;
    }
    if (gpiod_gpio_config_default(GPIO_RIGHT, GPIOD_OUTPUT_ACTIVE_LOW, GPIOD_PULL_UP) < 0) {
        perror("Failed to configure GPIO22");
        return EXIT_FAILURE;
    }

    // Request lines for reading
    if (gpiod_line_request(GPIO_LEFT, 1, &line_left) < 0) {
        perror("Failed to request line for GPIO17");
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(GPIO_CENTER, 1, &line_center) < 0) {
        perror("Failed to request line for GPIO27");
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(GPIO_RIGHT, 1, &line_right) < 0) {
        perror("Failed to request line for GPIO22");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int left_state = gpiod_line_get_value(&line_left);
        int center_state = gpiod_line_get_value(&line_center);
        int right_state = gpiod_line_get_value(&line_right);

        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        usleep(100000); // Sleep for 100 ms
    }

    // Clean up resources
    gpiod_line_free(&line_left);
    gpiod_line_free(&line_center);
    gpiod_line_free(&line_right);
    gpiod_exit();

    return EXIT_SUCCESS;
}

