#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define REG_LSB 0x24
#define REG_MSB 0x25
#define INTERVAL 100

int i2c_fd;

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int i2c_open(const char *bus_name) {
    int fd = open(bus_name, O_RDWR | O_SYNC);
    if (fd < 0) {
        handle_error("open() failed");
    }
    return fd;
}

int i2c_close(int fd) {
    close(fd);
    return 0;
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    return write(fd, buf, 2);
}

int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buf[2];
    int ret = read(fd, buf, 2);
    if (ret != 2) {
        handle_error("read() failed");
    }
    *value = buf[1];
    return ret;
}

int read_sil1175_data() {
    uint16_t lsb, msb;
    int ret;

    ret = i2c_open("/dev/i2c-" I2C_BUS);
    if (ret < 0) {
        handle_error("i2c_open failed");
    }

    ret = i2c_write_reg(i2c_fd, REG_LSB, 0x00);
    if (ret < 0) {
        i2c_close(i2c_fd);
        handle_error("i2c_write_reg failed");
    }

    ret = i2c_read_reg(i2c_fd, REG_MSB, &msb);
    if (ret < 0) {
        i2c_close(i2c_fd);
        handle_error("i2c_read_reg failed");
    }

    ret = i2c_write_reg(i2c_fd, REG_LSB, 0x00);
    if (ret < 0) {
        i2c_close(i2c_fd);
        handle_error("i2c_write_reg failed");
    }

    ret = i2c_read_reg(i2c_fd, REG_MSB, &lsb);
    if (ret < 0) {
        i2c_close(i2c_fd);
        handle_error("i2c_read_reg failed");
    }

    uint16_t combined_value = (uint16_t)msb << 8 | lsb;

    printf("Raw sensor value: 0x%04X\n", combined_value);

    usleep(INTERVAL * 1000);

    return 0;
}

int main() {
    int ret;

    while (1) {
        ret = read_sil1175_data();
        if (ret == 0) {
            usleep(INTERVAL * 1000);
        } else {
            break;
        }
    }

    i2c_close(i2c_fd);
    return 0;
}

