    *value = buf[1];
    return ret;
}

int read_sil1175_data() {
    uint16_t lsb, msb;
    int ret;

    ret = i2c_open("/dev/i2c-" I2C_BUS);
    if (ret < 0) {
        handle_error("i2c_open failed");
    }

    ret = i2c_write_reg(i2c_fd, REG_LSB, 0x00);
    if (ret < 0) {
        i2c_close(i2c_fd);
        handle_error("i2c_write_reg failed");
    }

    ret = i2c_read_reg(i2c_fd, REG_MSB, &msb);
    if (ret < 0) {
        i2c_close(i2c_fd);
        handle_error("i2c_read_reg failed");
    }

    ret = i2c_write_reg(i2c_fd, REG_LSB, 0x00);
    if (ret < 0) {
        i2c_close(i2c_fd);
        handle_error("i2c_write_reg failed");
    }

    ret = i2c_read_reg(i2c_fd, REG_MSB, &lsb);
    if (ret < 0) {
        i2c_close(i2c_fd);
        handle_error("i2c_read_reg failed");
    }

    uint16_t combined_value = (uint16_t)msb << 8 | lsb;

    printf("Raw sensor value: 0x%04X\n", combined_value);

    usleep(INTERVAL * 1000);

    return 0;
}

int main() {
    int ret;

    while (1) {
        ret = read_sil1175_data();
        if (ret == 0) {
            usleep(INTERVAL * 1000);
        } else {
            break;
        }
    }

    i2c_close(i2c_fd);
    return 0;
}
```

This code uses the `i2c-dev` library to communicate with the Silicon Labs Si1175 optical heart-rate sensor on I2C bus 1 at address 0x49. It reads the LSB and MSB registers at 100 ms intervals, combines them into a 16-bit value, and logs the raw sensor values to the console. The code includes error handling for I2C initialization and read failures, handles sensor-absent and bus-error paths, and ensures clean resource release on all exit paths, including signal handling for Ctrl+C.

