#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN_LEFT 2
#define GPIO_PIN_MIDDLE 3
#define GPIO_PIN_RIGHT 4
#define POLL_INTERVAL 100

void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    gpiod_chip_t *chip;
    gpiod_deinit(GPIO_CHIP_DEFAULT);
    exit(0);
}

int main() {
    struct sigaction sa;

    // Set up signal handler for SIGINT
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize libgpiod
    gpiod_init();

    // Open the default GPIO chip
    gpiod_chip_t *chip = gpiod_chip_open(GPIO_CHIP_DEFAULT);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for each GPIO pin
    gpiod_line_t *lines[3];
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_line_request_input(chip, GPIO_PIN_LEFT + i);
        if (!lines[i]) {
            perror("Failed to request line for GPIO pin");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Main polling loop
    while (1) {
        // Read sensor values
        int values[3];
        for (int i = 0; i < 3; i++) {
            values[i] = gpiod_line_read(lines[i]) ? 1 : 0;
        }

        // Log sensor values
        printf("L:%d M:%d R:%d\n", values[0], values[1], values[2]);

        // Sleep before next poll
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up resources
    for (int i = 0; i < 3; i++) {
        gpiod_line_free(lines[i]);
    }
    gpiod_chip_close(chip);
    gpiod_shutdown();

    return 0;
}

