#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod/gpiod.h>

#define CH_PINS {5, 6, 13, 19, 26, 12, 16, 20}
#define POLL_INTERVAL_MS 200

void signal_handler(int signum) {
    gpiod_chip_t *chip;
    int i;

    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < 8; i++) {
        gpiod_line_t *line = gpiod_chip_line_get(chip, i);
        if (!line) {
            perror("Failed to get line %d from gpiochip0", i);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        gpiod_line_free(line);
    }

    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpiod_chip_t *chip;
    int i;

    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 8; i++) {
        gpiod_line_t *line = gpiod_chip_line_get(chip, i);
        if (!line) {
            perror("Failed to get line %d from gpiochip0", i);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        gpiod_line_set_direction(line, GPIOD_DIR_INPUT);
    }

    while (1) {
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        for (i = 0; i < 8; i++) {
            int state = gpiod_line_get_value(line[i]);
            printf("[%s] CH%d=%d\n", timestamp, i + 1, state);
        }

        usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    return EXIT_SUCCESS;
}

