#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define LED_RED 17
#define LED_GREEN 18
#define LED_BLUE 27
#define PWM_FREQ 1000
#define INTERVAL_MS 5000
#define STEPS 50

void random_hue(int *hue);
void hsv_to_rgb(int hue, int saturation, int value, int *r, int *g, int *b);
void invert_rgb(int *rgb);
void set_led_color(int red, int green, int blue);

int main() {
    int ret;
    gpioSetup(LED_RED, GPIO_OUTPUT);
    gpioSetup(LED_GREEN, GPIO_OUTPUT);
    gpioSetup(LED_BLUE, GPIO_OUTPUT);

    pigpio_init(1);

    syslog(LOG_INFO, "Mood lamp started.");

    while (1) {
        int hue = 0;
        random_hue(&hue);
        hsv_to_rgb(hue, 1.0, 1.0, &ret);
        if (ret) {
            syslog(LOG_ERR, "Error converting hue to RGB.");
            continue;
        }
        invert_rgb(&ret);
        set_led_color(ret[0], ret[1], ret[2]);
        usleep(INTERVAL_MS / 1000);
    }

    pigpio_cleanup(1);
    syslog(LOG_INFO, "Mood lamp shutting down.");
    set_led_color(0, 0, 0);
    sleep(1);
    syslog(LOG_INFO, "Mood lamp shut down.");

    return 0;
}

void random_hue(int *hue) {
    *hue = rand() % 360;
    syslog(LOG_INFO, "Random hue: %d", *hue);
}

void hsv_to_rgb(int hue, float saturation, float value, int *r, int *g, int *b) {
    float c = value * saturation;
    float h = hue / 360.0;
    float f = 1.0 - c;
    *r = (c * (1.0 - fabs(h % 2 - 1.0)));
    *g = (c * (1.0 - fabs((h + 1.0) % 2 - 1.0)));
    *b = (c * (1.0 - fabs((h + 2.0) % 2 - 1.0)));

    *r = (int)(*r * 255);
    *g = (int)(*g * 255);
    *b = (int)(*b * 255);

    if (*r > 255 || *g > 255 || *b > 255) {
        syslog(LOG_ERR, "RGB value out of range.");
        *r = 255;
        *g = 255;
        *b = 255;
    }
}

void invert_rgb(int *rgb) {
    *rgb[0] = 255 - *rgb[0];
    *rgb[1] = 255 - *rgb[1];
    *rgb[2] = 255 - *rgb[2];
}

void set_led_color(int red, int green, int blue) {
    gpioWrite(LED_RED, red);
    gpioWrite(LED_GREEN, green);
    gpioWrite(LED_BLUE, blue);
}

