#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define GPIO_LED 18
#define BH1750_ADDR 0x23
#define I2C_BUS_NUM 1

#define MAX_RETRIES 3

int led_gpio;
int bh1750_fd;
int lux;

void init_pigpio() {
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    bh1750_fd = open("/dev/i2c-" I2C_BUS_NUM, O_RDWR | O_NOCTTY);
    if (bh1750_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(bh1750_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        exit(EXIT_FAILURE);
    }
}

int read_lux() {
    uint8_t buffer[2];
    int ret = read(bh1750_fd, buffer, 2);
    if (ret != 2) {
        fprintf(stderr, "Failed to read from BH1750\n");
        return -1;
    }

    lux = (buffer[0] << 8) | buffer[1];
    return lux;
}

void set_led_brightness(int brightness) {
    int value = map_lux_to_brightness(read_lux());
    int step = brightness - value;
    int range = 255 - value;
    int new_value = value + step;

    if (new_value > 255) {
        new_value = 255;
    } else if (new_value < 0) {
        new_value = 0;
    }

    int delta = new_value - piGPIO_get_gpio_value(led_gpio);
    piGPIO_set_gpio_pattern(led_gpio, delta);
}

int map_lux_to_brightness(int lux) {
    // Non-linear mapping from lux to LED brightness (0-100)
    // This is a simple logarithmic mapping for demonstration purposes
    return (int)((lux / 1000.0) * 100);
}

int main(int argc, char *argv[]) {
    led_gpio = GPIO_LED;

    init_pigpio();
    init_i2c();

    int retries = 0;
    while (retries < MAX_RETRIES) {
        lux = read_lux();
        if (lux != -1) {
            set_led_brightness(lux);
        } else {
            fprintf(stderr, "BH1750 sensor failed to respond, retrying...\n");
            retries++;
            usleep(180000); // Wait 180 ms before retry
        }
    }

    fprintf(stderr, "Failed to read from BH1750 after %d retries\n", MAX_RETRIES);

    piGPIO_cleanup();
    close(bh1750_fd);
    return 0;
}

