#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <spidev.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define APA102_DEV "/dev/spidev0.0"
#define SPI_CLOCK 1000000

#define BH1750_REG_CONFIG 0x00
#define BH1750_REG_STATUS 0x01
#define BH1750_REG_DATA 0x02
#define BH1750_REG_LUX_LOW 0x03
#define BH1750_REG_LUX_HIGH 0x04

#define APA102_START_FRAME 0xE0
#define APA102_LED_FRAME 0x00
#define APA102_END_FRAME 0xFF

#define APA102_BRIGHTNESS_MAP_MIN 10
#define APA102_BRIGHTNESS_MAP_MAX 31

int bh1750_init(int fd) {
    unsigned char config = 0x20;
    unsigned char status;

    // Initialize BH1750 in One-Time High-Resolution mode
    write(fd, &config, 1);
    read(fd, &status, 1);

    if (status & 0x04) {
        perror("Failed to write to BH1750");
        return -1;
    }

    return 0;
}

int bh1750_read_lux(int fd) {
    unsigned char lux_low, lux_high;

    // Wait for conversion to complete
    read(fd, &lux_low, 1);
    read(fd, &lux_high, 1);

    // Calculate lux
    unsigned int lux = (lux_low << 8) | lux_high;
    lux /= 1.2;

    return lux;
}

int apa102_set_brightness(int fd, int brightness) {
    unsigned char frame[4];

    // Map brightness to 5-bit range [0, 31]
    if (brightness < APA102_BRIGHTNESS_MAP_MIN)
        brightness = APA102_BRIGHTNESS_MAP_MIN;
    else if (brightness > APA102_BRIGHTNESS_MAP_MAX)
        brightness = APA102_BRIGHTNESS_MAP_MAX;

    frame[0] = APA102_START_FRAME;
    frame[1] = (brightness >> 8) & 0x3F;
    frame[2] = brightness & 0x3F;
    frame[3] = 0xFF;

    // Send frame to APA102
    write(fd, frame, 4);

    return 0;
}

int main() {
    int bh1750_fd, apa102_fd;
    int lux;

    bh1150_fd = open("/dev/i2c-1", O_RDWR);
    if (bh1750_fd == -1) {
        perror("Failed to open BH1750");
        return 1;
    }

    apa102_fd = open(APA102_DEV, O_RDWR);
    if (apa102_fd == -1) {
        perror("Failed to open APA102");
        close(bh1750_fd);
        return 1;
    }

    if (ioctl(bh1750_fd, I2C_SLAVE, BH1750_ADDR) == -1) {
        perror("Failed to set BH1750 slave address");
        close(bh1750_fd);
        close(apa102_fd);
        return 1;
    }

    if (ioctl(bh1750_fd, WHO_AM_I) == -1) {
        perror("Failed to get BH1750 ID");
        close(bh1750_fd);
        close(apa102_fd);
        return 1;
    }

    if (bh1750_init(bh1750_fd) != 0) {
        close(bh1750_fd);
        close(apa102_fd);
        return 1;
    }

    lux = bh1750_read_lux(bh1750_fd);

    // Map lux to APA102 brightness
    int apa102_brightness = lux / 100.0; // Assuming 100 lux as reference

    if (apa102_set_brightness(apa102_fd, (int)(apa102_brightness * 31)) != 0) {
        perror("Failed to set APA102 brightness");
        close(bh1750_fd);
        close(apa102_fd);
        return 1;
    }

    close(bh1750_fd);
    close(apa102_fd);

    return 0;
}

