#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define APA102_MOSI 10
#define APA102_SCLK 11

#define BH1750_ONE_TIME_MODE 0x21
#define BH1750_READ_TIME 180  // ms
#define BH1750_READ_DATA_LEN 2
#define APA102_BRIGHTNESS_LEVELS 32
#define APA102_FADE_TIME 500  // ms
#define APA102_FADE_DELAY 100  // ms

int bh1750_i2c_handles[2];
int apa102_spi_handle;

void sigint_handler(int signum) {
    pigpio_stop();
    for (int i = 0; i < 2; i++) {
        if (bh1750_i2c_handles[i] != -1) {
            pigpio_free_i2c(bh1750_i2c_handles[i]);
            bh1750_i2c_handles[i] = -1;
        }
    }
    apa102_spi_handle = -1;
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    pigpio_init(1);

    int bh1750_i2c_handle_low, bh1750_i2c_handle_high;
    int apa102_spi_handle;

    // Initialize I2C bus 1
    bh1750_i2c_handle_low = pigpio_i2c_open(1, BH1750_ADDR_LOW);
    if (bh1750_i2c_handle_low == -1) {
        fprintf(stderr, "Failed to open I2C bus 1 for BH1750 (low address)\n");
        return EXIT_FAILURE;
    }

    bh1750_i2c_handle_high = pigpio_i2c_open(1, BH1750_ADDR_HIGH);
    if (bh1750_i2c_handle_high == -1) {
        fprintf(stderr, "Failed to open I2C bus 1 for BH1750 (high address)\n");
        return EXIT_FAILURE;
    }

    // Initialize APA102 strip
    apa102_spi_handle = pigpio_spi_open(0, 0, 0);
    if (apa102_spi_handle == -1) {
        fprintf(stderr, "Failed to open SPI handle for APA102\n");
        return EXIT_FAILURE;
    }

    // Read BH1750 lux data
    uint16_t lux_data_low[BH1750_READ_DATA_LEN];
    uint16_t lux_data_high[BH1750_READ_DATA_LEN];

    int lux_low, lux_high;
    for (int i = 0; i < 2; i++) {
        lux_low = pigpio_i2c_read(bh1750_i2c_handles[i], BH1750_ONE_TIME_MODE);
        if (lux_low == -1) {
            fprintf(stderr, "Failed to read from BH1750 (address %d)\n", i == 0 ? BH1750_ADDR_LOW : BH1750_ADDR_HIGH);
            continue;
        }

        lux_data_low[i] = lux_low;
        pigpio_i2c_delay(bh1750_i2c_handles[i], BH1750_READ_TIME);

        lux_high = pigpio_i2c_read(bh1750_i2c_handles[i], BH1750_ONE_TIME_MODE);
        if (lux_high == -1) {
            fprintf(stderr, "Failed to read from BH1750 (address %d)\n", i == 0 ? BH1750_ADDR_LOW : BH1750_ADDR_HIGH);
            continue;
        }

        lux_data_high[i] = lux_high;
    }

    // Calculate average lux
    int total_lux = 0;
    int count = 0;
    for (int i = 0; i < 2; i++) {
        if (lux_data_low[i] == 0 && lux_data_high[i] == 0) {
            continue;
        }
        total_lux += lux_data_low[i] + lux_data_high[i];
        count++;
    }

    double avg_lux = total_lux / count;

    // Map lux to brightness level
    int brightness = (int)(avg_lux * 31.0 / 10000.0);

    // Fade brightness to target
    for (int i = 0; i < brightness; i++) {
        pigpio_spi_write_byte(apa102_spi_handle, 0b00000001); // Set all pixels to full brightness
        usleep(APA102_FADE_DELAY * 1000);
    }

    for (int i = brightness; i < 32; i++) {
        pigpio_spi_write_byte(apa102_spi_handle, 0b00000000); // Set all pixels to off
        usleep(APA102_FADE_DELAY * 1000);
    }

    // Main loop
    while (1) {
        usleep(APA102_FADE_TIME * 1000);
    }

    pigpio_spi_close(apa102_spi_handle);
    pigpio_i2c_close(bh1750_i2c_handles[0]);
    pigpio_i2c_close(bh1750_i2c_handles[1]);
    pigpio_exit();

    return EXIT_SUCCESS;
}

