#define I2C_DEVICE 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define BRIGHTNESS_BITS 8
#define BIT_BANGING_FREQ 800000

#define LED_PIN 18

void sigint_handler(int sig) {
    gpiod_disable(LED_PIN);
    close(i2c_fd);
    exit(0);
}

