    int i2c_fd, ret;
    struct i2c_client *client;
    gpiopin_t led_pin;
    uint16_t raw_lux, lux, brightness;
    uint32_t gain = 0x0001;
    uint32_t integration_time = 0x0000;
    uint32_t config_reg = 0x0000;
    uint32_t al_reg = 0x0004;
    int retries = 3, delay = 100;

    led_pin = LED_PIN;

    for (int i = 0; i < retries; i++) {
        client = i2c_open(I2C_DEVICE, 0);
        if (client == NULL) {
            if (errno == EBUSY) {
                usleep(delay * 1000000);
                delay *= 2;
            } else {
                perror("i2c_open");
                exit(EXIT_FAILURE);
            }
        } else {
            break;
        }
    }
    if (client == NULL) {
        fprintf(stderr, "Failed to open I2C device after %d retries.\n", retries);
        exit(EXIT_FAILURE);
    }

    i2c_set_address(client, I2C_DEVICE);

    ret = i2c_mem_read(client, I2C_DEVICE, CONFIG_REG, &config_reg, 4, 100 * 1000, 1);
    if (ret < 0) {
        perror("i2c_mem_read");
        i2c_close(client);
        exit(EXIT_FAILURE);
    }

    ret = i2c_mem_read(client, I2C_DEVICE, ALS_REG, &raw_lux, 2, 0, 0);
    if (ret < 0) {
        perror("i2c_mem_read");
        i2c_close(client);
        exit(EXIT_FAILURE);
    }

    lux = raw_lux * 0.0288; // Convert raw ALS value to lux

    gain = 1 / 8; // Default gain for VEML7700
    lux *= gain; // Convert lux to raw ALS value

    brightness = 255 * pow(lux / 120000.0, 1.0 / 2.2); // Gamma correction

    gpiod_direction_output(led_pin, GPIOD_OUTPUT);

    while (1) {
        for (int j = 0; j < BIT_BANGING_FREQ / 2; j++) {
            gpiod_output_set(led_pin, 1);
            usleep(100000 / BIT_BANGING_FREQ);
            gpiod_output_set(led_pin, 0);
            usleep(100000 / BIT_BANGING_FREQ);
        }

        printf("Lux: %d, Brightness: %d\n", lux, brightness);
        usleep(200000);
    }

    i2c_close(client);
    return 0;
}

