#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 17
#define LED_GPIO 18
#define SELF_TEST_INTERVAL 100
#define SENSOR_READ_INTERVAL 500
#define FAULT_PATTERN_BUZZER "short-short-long-short"
#define FAULT_PATTERN_BUZZER_LENGTH 4
#define FAULT_PATTERN_BUZZER_TOTAL_MS 600
#define FAULT_PATTERN_REPEATS 3

void self_test(void);
void sensor_read_and_check(void);
void buzzer_led_control(int buzzer_state, int led_state);
void log_event(const char *event);
void signal_handler(int signum);

int main(int argc, char *argv[]) {
    int buzzer_state, led_state;
    gpiod_context_t line_flame_sensor, line_buzzer, line_led;
    gpiod_result_t result;
    time_t start_time, end_time;
    int i, fault_detected = 0;

    gpiod_init();

    start_time = time(NULL);

    // Initialize GPIO pins
    result = gpiod_setup(FLAME_SENSOR_GPIO, GPIO_OUT);
    if (result != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to initialize GPIO4: %s\n", gpiod_strerror(result));
        exit(1);
    }

    result = gpiod_setup(BUZZER_GPIO, GPIO_OUTPUT);
    if (result != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to initialize GPIO17: %s\n", gpiod_strerror(result));
        exit(1);
    }

    result = gpiod_setup(LED_GPIO, GPIO_OUTPUT);
    if (result != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to initialize GPIO18: %s\n", gpiod_strerror(result));
        exit(1);
    }

    // Self-test
    self_test();

    // Main loop
    while (1) {
        sensor_read_and_check();
        usleep(SENSOR_READ_INTERVAL / 2);
    }

    // Clean up
    gpiod_del_gpio_line(&line_flame_sensor);
    gpiod_del_gpio_line(&line_buzzer);
    gpiod_del_gpio_line(&line_led);

    log_event("System shutdown");
    exit(0);
}

void self_test(void) {
    buzzer_state = 0;
    led_state = 0;

    log_event("Starting self-test...");

    for (i = 0; i < 2; i++) {
        buzzer_led_control(1, 0); // LED on, buzzer off
        usleep(500000);
        buzzer_led_control(0, 0); // LED off, buzzer off
        usleep(500000);
    }

    for (i = 0; i < 5; i++) {
        result = gpiod_get_value(FLAME_SENSOR_GPIO);
        if (result == GPIOD_VALUE_LOW) {
            log_event("Flame sensor consistently LOW, treating as sensor fault.");
            fault_detected = 1;
            break;
        }
        usleep(SELF_TEST_INTERVAL * 1000);
    }

    if (!fault_detected) {
        log_event("Self-test passed.");
    }
}

void sensor_read_and_check(void) {
    int sensor_value;
    int flame_detected = 0;

    sensor_value = gpiod_get_value(FLAME_SENSOR_GPIO);
    flame_detected = (sensor_value == GPIOD_VALUE_LOW);

    if (flame_detected) {
        buzzer_led_control(1, 1); // Buzzer on, LED on
        log_event("Flame detected, activating buzzer and LED.");
    } else {
        buzzer_led_control(0, 0); // Buzzer off, LED off
        log_event("Flame gone, deactivating buzzer and LED.");
    }
}

void buzzer_led_control(int buzzer_state, int led_state) {
    gpiod_set_value(BUZZER_GPIO, buzzer_state);
    gpiod_set_value(LED_GPIO, led_state);
}

void log_event(const char *event) {
    time_t current_time = time(NULL);
    char timestamp[20];
    sprintf(timestamp, "%s %d", ctime(&current_time), current_time);
    printf("%s: %s\n", timestamp, event);
}

void signal_handler(int signum) {
    log_event("Received SIGINT, exiting...");
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    // ... rest of the main function ...
}

