#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x23
#define BUF_SIZE 60
#define BLINK_RATE_MIN 0.5
#define BLINK_RATE_MAX 5.0

typedef struct {
    long file_descriptor;
    unsigned char raw_value;
} i2c_data;

typedef struct {
    i2c_data data;
    int lux_buffer[BUF_SIZE];
    int buffer_index;
    int rate;
} lux_reader;

static int i2c_open(const char *path, int mode) {
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        perror("open");
        return -1;
    }
    ioctl(fd, I2C_SLAVE, I2C_ADDR);
    return fd;
}

static int i2c_close(int fd) {
    close(fd);
    return 0;
}

static int i2c_read(int fd, unsigned char *buffer, size_t size) {
    return read(fd, buffer, size);
}

static int i2c_write(int fd, const unsigned char *buffer, size_t size) {
    return write(fd, buffer, size);
}

static int lux_from_raw(int raw_value) {
    return (int)(raw_value / 1.2);
}

static int lux_rate(int avg_lux) {
    return BLINK_RATE_MIN + (avg_lux / 1000) * 4.5;
    if (lux_rate(avg_lux) > BLINK_RATE_MAX) {
        return BLINK_RATE_MAX;
    }
    return lux_rate(avg_lux);
}

static void lux_blink(int rate) {
    struct timespec req, rem;
    double elapsed;

    while (1) {
        nanosleep(&req, &rem);
        elapsed = (double)rem.tv_sec + rem.tv_nsec / 1e9;
        if (lux_rate(lux_from_raw(0)) > rate) {
            // Blink on
            printf("Blinking\n");
            // Implement LED control here
        } else {
            // Blink off
            printf("Not blinking\n");
        }
    }
}

void *read_lux(void *arg) {
    lux_reader *lux_reader_ptr = (lux_reader *)arg;
    int i2c_fd, ret;
    unsigned char raw_value;

    lux_reader_ptr->buffer_index = 0;

    while (1) {
        i2c_fd = i2c_open(I2C_DEVICE, 0);
        if (i2c_fd < 0) {
            perror("i2c_open");
            continue;
        }

        ret = i2c_read(i2c_fd, &lux_reader_ptr->data.raw_value, sizeof(lux_reader_ptr->data.raw_value));
        if (ret < 0) {
            perror("i2c_read");
            continue;
        }

        lux_reader_ptr->data.raw_value = ntohl(lux_reader_ptr->data.raw_value);
        lux_reader_ptr->lux_buffer[lux_reader_ptr->buffer_index] = lux_from_raw(lux_reader_ptr->data.raw_value);
        lux_reader_ptr->buffer_index = (lux_reader_ptr->buffer_index + 1) % BUF_SIZE;

        // Compute average lux
        int sum = 0;
        for (int i = 0; i < BUF_SIZE; i++) {
            sum += lux_reader_ptr->lux_buffer[i];
        }
        double avg_lux = sum / BUF_SIZE;

        // Blink LED
        int rate = lux_rate(avg_lux);
        lux_blink(rate);

        usleep(1000000 / lux_rate(avg_lux));
    }

    i2c_close(i2c_fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    pthread_t thread;
    lux_reader lux_reader;
    lux_reader.data.file_descriptor = -1;
    lux_reader.buffer_index = 0;

    if (pthread_create(&thread, NULL, (void *(*)(void *))read_lux, &lux_reader) != 0) {
        perror("pthread_create");
        return EXIT_FAILURE;
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    return EXIT_SUCCESS;
}

static void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    pthread_t thread;
    lux_reader lux_reader;
    lux_reader.data.file_descriptor = -1;
    lux_reader.buffer_index = 0;

    if (pthread_create(&thread, NULL, (void *(*)(void *))read_lux, &lux_reader) != 0) {
        perror("pthread_create");
        return;
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    // Clean up
    i2c_close(lux_reader.data.file_descriptor);
    return;
}

