#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEGMENT_A 0
#define SEGMENT_B 1
#define SEGMENT_C 2
#define SEGMENT_D 3
#define SEGMENT_E 4
#define SEGMENT_F 5
#define SEGMENT_G 6
#define SEGMENT_DP 7

#define BLINK_ON_TIME 500
#define BLINK_OFF_TIME 500

void setup_gpio(void) {
    int ret;

    // Request GPIO lines
    ret = gpiod_request_pin(DATA_PIN, GPIOD_MODE_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d as output\n", DATA_PIN);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_pin(CLOCK_PIN, GPIOD_MODE_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d as output\n", CLOCK_PIN);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_pin(LATCH_PIN, GPIOD_MODE_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d as output\n", LATCH_PIN);
        exit(EXIT_FAILURE);
    }
}

void shift_out(unsigned char data) {
    int i;
    for (i = 7; i >= 0; i--) {
        gpiod_output_set(CLOCK_PIN, 1);
        gpiod_output_set(DATA_PIN, data & 0x80);
        data <<= 1;
        gpiod_output_set(DATA_PIN, data & 0x80);
        gpiod_output_set(CLOCK_PIN, 0);
        gpiod_output_set(LATCH_PIN, 1);
        gpiod_output_set(LATCH_PIN, 0);
    }
}

void display_digit(void) {
    unsigned char digit_data = 0b00000001; // 5 in 8-bit binary

    shift_out(digit_data);
    gpiod_output_set(LATCH_PIN, 0);
    gpiod_output_set(DATA_PIN, 0);

    // Blink the digit
    for (int i = 0; i < 2; i++) {
        gpiod_output_set(DATA_PIN, 0b00000001); // On
        sleep(BLINK_ON_TIME / 1000.0);
        gpiod_output_set(DATA_PIN, 0); // Off
        sleep(BLINK_OFF_TIME / 1000.0);
    }
}

int main(void) {
    setup_gpio();

    while (1) {
        display_digit();
    }

    // Cleanup
    gpiod_disable(DATA_PIN);
    gpiod_disable(CLOCK_PIN);
    gpiod_disable(LATCH_PIN);
    gpiod_free_pin(DATA_PIN);
    gpiod_free_pin(CLOCK_PIN);
    gpiod_free_pin(LATCH_PIN);

    return 0;
}

