#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define LED_PIN 11
#define BUTTON_PIN 12
#define BLINK_PERIOD_MS 1000

void handle_signal(int signum) {
    printf("Received SIGINT, exiting gracefully...\n");
    gpiod_line_set_dir(chip0, LED_PIN, GPIOD_DIR_OUT);
    gpiod_line_set_level(chip0, LED_PIN, GPIOD_LEVEL_LOW);
    gpiod_line_set_dir(chip0, BUTTON_PIN, GPIOD_DIR_IN);
    gpiod_line_pull_up_en(chip0, BUTTON_PIN);
    exit(0);
}

int main() {
    int ret;
    sigset_t sigset;
    struct sigaction sa;

    // Initialize signal handler
    sigaction(SIGINT, &sa, NULL);
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, sa, NULL);

    // Initialize libgpiod
    ret = gpiod_init(NULL);
    if (ret < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip 0
    ret = gpiod_chip_open(0, &chip0);
    if (ret < 0) {
        perror("Failed to open GPIO chip 0");
        exit(EXIT_FAILURE);
    }

    // Request LED line as output initially low
    ret = gpiod_line_request(chip0, LED_PIN, GPIOD_MODE_OUTPUT, GPIOD_DIR_OUT);
    if (ret < 0) {
        perror("Failed to request LED line");
        gpiod_chip_close(chip0, NULL);
        exit(EXIT_FAILURE);
    }

    // Request button line as input with internal pull-up
    ret = gpiod_line_request(chip0, BUTTON_PIN, GPIOD_MODE_INPUT, GPIOD_DIR_IN, GPIOD_PULL_UP);
    if (ret < 0) {
        perror("Failed to request button line");
        gpiod_line_release(chip0, LED_PIN);
        gpiod_chip_close(chip0, NULL);
        exit(EXIT_FAILURE);
    }

    // Set initial state for the LED
    ret = gpiod_line_set_level(chip0, LED_PIN, GPIOD_LEVEL_LOW);
    if (ret < 0) {
        perror("Failed to set initial LED level");
        gpiod_line_release(chip0, BUTTON_PIN);
        gpiod_chip_close(chip0, NULL);
        exit(EXIT_FAILURE);
    }

    // Blink LED and monitor button
    while (1) {
        // Toggle LED
        ret = gpiod_line_toggle(chip0, LED_PIN);
        if (ret < 0) {
            perror("Failed to toggle LED");
            gpiod_line_release(chip0, BUTTON_PIN);
            gpiod_chip_close(chip0, NULL);
            exit(EXIT_FAILURE);
        }

        // Wait for button event
        ret = gpiod_line_event_wait(chip0, BUTTON_PIN, GPIOD_EVENT_FALLING, BLINK_PERIOD_MS / 1000, NULL);
        if (ret == 0) {
            printf("Button pressed, exiting...\n");
            gpiod_line_set_level(chip0, LED_PIN, GPIOD_LEVEL_LOW);
            gpiod_line_release(chip0, LED_PIN);
            gpiod_line_release(chip0, BUTTON_PIN);
            gpiod_chip_close(chip0, NULL);
            exit(0);
        }
    }
}

