#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 18
#define BUTTON_PIN 15

int main(int argc, char *argv[]) {
    int ret;
    gpiod_chip_t chip;
    gpiod_line_t lines[2];
    gpiod_line_direction_t line_directions[2];
    gpiod_line_value_t line_values[2];

    ret = gpiod_chip_create(&chip, GPIOD_CHIP_VERSION_1);
    if (ret < 0) {
        fprintf(stderr, "Failed to create gpio chip: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    lines[0] = GPIOD_LINE(LED_PIN);
    lines[1] = GPIOD_LINE(BUTTON_PIN);

    line_directions[0] = GPIOD_DIR_OUT;
    line_directions[1] = GPIOD_DIR_IN;

    line_values[0] = 0; // Initially low for LED
    line_values[1] = GPIOD_READ_HIGH; // Button is open

    ret = gpiod_chip_line_direction_set(chip, lines[0], line_directions[0]);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line direction for LED: %s\n", gpiod_strerror(ret));
        gpiod_chip_destroy(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_line_direction_set(chip, lines[1], line_directions[1]);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line direction for button: %s\n", gpiod_strerror(ret));
        gpiod_chip_destroy(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_write(lines[0], line_values[0]);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to LED line: %s\n", gpiod_strerror(ret));
        gpiod_chip_destroy(chip);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = gpiod_line_read(lines[1], &line_values[1]);
        if (ret < 0) {
            fprintf(stderr, "Failed to read button line: %s\n", gpiod_strerror(ret));
            continue;
        }

        if (line_values[1] == GPIOD_READ_HIGH) {
            gpiod_line_write(lines[0], 1); // Turn LED on
            while (1) {
                gpiod_line_write(lines[0], 0); // Turn LED off
                usleep(500000); // 500ms delay
            }
        } else {
            gpiod_line_write(lines[0], 0); // Turn LED off
            break;
        }
    }

    gpiod_chip_destroy(chip);
    return 0;
}

