#include <signal.h>
#include <errno.h>

#define GPIO_RED 24
#define GPIO_GREEN 23
#define GPIO_BLUE 18

void signal_handler(int signum) {
    gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    sigset_t sigset;
    int sig;

    // Initialize signal handler
    sigaddset(&sigset, SIGINT);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Initialize libgpiod
    gpiod_chip_t *chip;
    gpiod_status_t status;
    gpiod_init();

    // Open GPIO chip
    status = gpiod_chip_open_by_number(&chip, 0);
    if (status != GPIOD_OK) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(status));
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    gpiod_line_t *red, *green, *blue;
    status = gpiod_chip_get_line(chip, GPIO_RED, &red);
    if (status != GPIOD_OK) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_RED, gpiod_strerror(status));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    status = gpiod_line_request_output(red);
    if (status != GPIOD_OK) {
        fprintf(stderr, "Failed to request output on GPIO %d: %s\n", GPIO_RED, gpiod_strerror(status));
        gpiod_line_close(red);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    status = gpiod_chip_get_line(chip, GPIO_GREEN, &green);
    if (status != GPIOD_OK) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_GREEN, gpiod_strerror(status));
        gpiod_line_close(red);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    status = gpiod_line_request_output(green);
    if (status != GPIOD_OK) {
        fprintf(stderr, "Failed to request output on GPIO %d: %s\n", GPIO_GREEN, gpiod_strerror(status));
        gpiod_line_close(green);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    status = gpiod_chip_get_line(chip, GPIO_BLUE, &blue);
    if (status != GPIOD_OK) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_BLUE, gpiod_strerror(status));
        gpiod_line_close(green);
        gpiod_line_close(red);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    status = gpiod_line_request_output(blue);
    if (status != GPIOD_OK) {
        fprintf(stderr, "Failed to request output on GPIO %d: %s\n", GPIO_BLUE, gpiod_strerror(status));
