#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define G_THRESHOLD 2.0
#define POLL_INTERVAL 10000  // 10 Hz
#define LOG_FILE "impact_log.txt"
#define GPIO_PIN 17

void handle_command_line_args(int argc, char *argv[]);
void configure_sensor();
void read_accelerometer();
void log_impact(const char *timestamp);
void pulse_gpio(int pin);
void release_resources();

int main(int argc, char *argv[]) {
    handle_command_line_args(argc, argv);

    pigpio_init(I2C_BUS);
    configure_sensor();

    while (1) {
        read_accelerometer();
        usleep(POLL_INTERVAL * 1000 / 10000);
    }

    release_resources();
    return 0;
}

void handle_command_line_args(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [-t <threshold>]\n", argv[0]);
        exit(1);
    }

    if (argc > 2) {
        G_THRESHOLD = atof(argv[2]);
    }
}

void configure_sensor() {
    if (i2c_master(I2C_BUS, I2C_ADDR, 0x28, 0x27, 0x00, 1000000000) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        exit(1);
    }

    if (i2c_master(I2C_BUS, I2C_ADDR, 0x28, 0x00, 0x00, 1) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        exit(1);
    }

    if (i2c_master(I2C_BUS, I2C_ADDR, 0x28, 0x40, 0x00, 1) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        exit(1);
    }
}

void read_accelerometer() {
    int data[6];
    int total_g = 0;

    for (int i = 0; i < 6; i++) {
        if (i2c_master(I2C_BUS, I2C_ADDR, 0x28, 0x80 | (i << 7), 0, 1) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            return;
        }
        total_g += data[i];
    }

    float g_magnitude = total_g / 1000000.0;

    if (g_magnitude > G_THRESHOLD) {
        pulse_gpio(GPIO_PIN);
        log_impact(strftime(NULL, 0, "%Y-%m-%d %H:%M:%S", localtime(NULL)));
    }
}

void pulse_gpio(int pin) {
    if (gpioSetup(GPIO_PIN, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin as output\n");
        exit(1);
    }
    gpioWrite(GPIO_PIN, HIGH);
    usleep(50000);
    gpioWrite(GPIO_PIN, LOW);
}

void log_impact(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }
    fprintf(log_file, "%s: %f\n", timestamp, atof(g_threshold_str));
    fclose(log_file);
}

void release_resources() {
    pigpio_terminate(1);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    handle_command_line_args(argc, argv);
    main(argc, argv);

    return 0;
}

void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT, exiting gracefully...\n");
    release_resources();
    exit(0);
}

void sigterm_handler(int signum) {
    fprintf(stderr, "Received SIGTERM, exiting gracefully...\n");
    release_resources();
    exit(0);
}

