#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RGB_RED_REG 0x66
#define RGB_GREEN_REG 0x68
#define RGB_BLUE_REG 0x6A
#define LED_GPIO 18
#define SAMPLE_INTERVAL 500

void i2c_error_handler(const char *msg, int err) {
    fprintf(stderr, "I2C Error: %s - %d\n", msg, err);
}

void sigint_handler(int sig) {
    printf("Exiting...\n");
    close(pi_fd);
    close(csv_fd);
    pigpio_stop();
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
}

int main() {
    int pi_fd, csv_fd;
    struct i2c_fd i2c_fd;
    pigpio pi;
    FILE *csv_file = fopen("color_log.csv", "w");
    if (!csv_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    pi_fd = pigpio_open(NULL, I2C_BUS, i2c_error_handler);
    if (pi_fd == -1) {
        perror("pigpio_open");
        exit(EXIT_FAILURE);
    }

    pigpio_set_mode(pi_fd, PIGIO_OUTPUT, LED_GPIO);
    pigpio_write(pi_fd, LED_GPIO, 0); // Turn off LED

    while (1) {
        struct i2c_msg msg;
        msg.address = I2C_ADDR;
        msg.write = 1;
        msg.len = 1;
        msg.data[0] = MODE_REG;

        if (pigpio_i2c_transfer(pi_fd, &msg, sizeof(msg)) < 0) {
            fprintf(stderr, "I2C write failed: %s\n", pigpio_strerror(errno));
            usleep(100000); // Wait for 100 ms before retry
            continue;
        }

        msg.address = I2C_ADDR;
        msg.read = 1;
        msg.len = 2;
        msg.data[0] = ALS_LSB_REG;
        msg.data[1] = ALS_MSB_REG;

        if (pigpio_i2c_transfer(pi_fd, &msg, sizeof(msg)) < 0) {
            fprintf(stderr, "I2C read failed: %s\n", pigpio_strerror(errno));
            usleep(100000); // Wait for 100 ms before retry
            continue;
        }

        uint16_t als = ((uint16_t)msg.data[0] << 8) | msg.data[1];

        msg.address = I2C_ADDR;
        msg.read = 3;
        msg.len = 3;
        msg.data[0] = RGB_RED_REG;
        msg.data[1] = RGB_GREEN_REG;
        msg.data[2] = RGB_BLUE_REG;

        if (pigpio_i2c_transfer(pi_fd, &msg, sizeof(msg)) < 0) {
            fprintf(stderr, "I2C read failed: %s\n", pigpio_strerror(errno));
            usleep(100000); // Wait for 100 ms before retry
            continue;
        }

        uint16_t rgb = ((uint16_t)msg.data[0] << 16) | ((uint16_t)msg.data[1] << 8) | msg.data[2];

        uint16_t duty_cycle = als * 255 / 65535;
        pigpio_set_pwm_range(pi_fd, LED_GPIO, 0, 255);
        pigpio_set_pwm_duty(pi_fd, LED_GPIO, duty_cycle);

        fprintf(csv_file, "%lu,%lu,%lu,%lu\n", als, rgb >> 8, rgb & 0xFF, duty_cycle);

        usleep(SAMPLE_INTERVAL * 1000 / 1000); // Adjust for 500 ms sampling
    }

    pigpio_close(pi_fd);
    fclose(csv_file);
    pigpio_exit();
    return 0;
}

