#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1F
#define SAMPLE_INTERVAL_MS 50

#define SENSITIVITY 4096
#define GRAVITY 9.81
#define IMPACT_THRESHOLD 19.62

int main() {
    int i2c_fd, ret;
    struct i2c_client *client;
    int data[6];

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        piGPIO_terminate();
        return 1;
    }

    // Set I2C mode
    ioctl(i2c_fd, I2C_SET_MODE, &0x01);

    // Initialize client
    client = i2c_client_new(i2c_fd, I2C_BUS);
    if (!client) {
        fprintf(stderr, "Failed to create I2C client\n");
        piGPIO_terminate();
        return 1;
    }

    // WHO_AM_I check
    ret = pigpio_i2c_write(client, I2C_ADDR, 0x0D, 1, NULL);
    if (ret != 0x0C7) {
        fprintf(stderr, "WHO_AM_I check failed, aborting\n");
        piGPIO_i2c_client_free(client);
        close(i2c_fd);
        piGPIO_terminate();
        return 1;
    }

    // Initialize sensor
    ret = pigpio_i2c_write(client, I2C_ADDR, 0x0E, 1, NULL);
    if (ret != 0x00) {
        fprintf(stderr, "Failed to set XYZ_DATA_CFG\n");
        piGPIO_i2c_client_free(client);
        close(i2c_fd);
        piGPIO_terminate();
        return 1;
    }

    ret = pigpio_i2c_write(client, I2C_ADDR, 0x2A, 1, NULL);
    if (ret != 0x00) {
        fprintf(stderr, "Failed to activate sensor\n");
        piGPIO_i2c_client_free(client);
        close(i2c_fd);
        piGPIO_terminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read 6 bytes of acceleration
        ret = pigpio_i2c_read(client, I2C_ADDR, 0x01, 6, data);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from sensor, continuing\n");
            continue;
        }

        // Compute acceleration magnitude
        int x = (data[0] << 8) | data[1];
