#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_BUS 1
#define ADXL345_ADDRESS 0x53
#define LOG_FILE "accel_log.txt"
#define LED_PIN 17

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd, log_fd;
    struct i2c_client *client;
    int led_state = 0;
    double x, y, z;
    time_t now;
    struct tm *tm_info;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <led_pin>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    led_pin = atoi(argv[1]);

    if ((i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    client = i2c_open(I2C_BUS, 0x20);
    if (!client) {
        perror("i2c_open");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (setjmp(NULL) == 0) {
        pigpio_init(1); // Initialize pigpio with 1 as the number of available ports (GPIO)

        while (1) {
            now = time(NULL);
            tm_info = localtime(&now);

            // Read ADXL345 DEVID register
            if (i2c_transfer(client, ADXL345_ADDRESS, 0x00, 1, 0) < 0) {
                fprintf(stderr, "Failed to read DEVID register\n");
                continue;
            }
            if (i2c_transfer(client, ADXL345_ADDRESS, 0x00, 1, 0) < 0) {
                fprintf(stderr, "Failed to read DEVID register\n");
                continue;
            }
            if (i2c_transfer(client, ADXL345_ADDRESS, 0x32, 6, 0) < 0) {
                fprintf(stderr, "Failed to read X/Y/Z data\n");
                continue;
            }

            x = (double)i2c_transfer(client, ADXL345_ADDRESS, 0x32, 6, 0) / 16.0;
            y = (double)i2c_transfer(client, ADXL345_ADDRESS, 0x34, 6, 0) / 16.0;
            z = (double)i2c_transfer(client, ADXL345_ADDRESS, 0x36, 6, 0) / 16.0;

            // Log the acceleration data
            if (write(i2c_fd, "timestamp,", 10) < 0) {
                perror("write timestamp");
                continue;
            }
            strcat(write(i2c_fd, (char *)&now, sizeof(time_t)), ",");
            strcat(write(i2c_fd, (char *)&x, 10), ",");
            strcat(write(i2c_fd, (char *)&y, 10), ",");
            strcat(write(i2c_fd, (char *)&z, 10), "\n");

            // Check for acceleration above 2g
            if (fabs(x) > 2.0 || fabs(y) > 2.0 || fabs(z) > 2.0) {
                led_state = 1;
            } else {
                led_state = 0;
            }

            // Turn LED on/off
            if (led_state) {
                if (pigpio_write_i2c_mem_addr(client, ADXL345_ADDRESS, 0x01, 0xFF) < 0) {
                    fprintf(stderr, "Failed to turn LED on\n");
                }
            } else {
                if (pigpio_write_i2c_mem_addr(client, ADXL345_ADDRESS, 0x01, 0x00) < 0) {
                    fprintf(stderr, "Failed to turn LED off\n");
                }
            }

            usleep(100000); // Wait for 100ms
        }

        pigpio_terminate(NULL);
        close(client);
        close(i2c_fd);
    }

    return 0;
}

