#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E
#define CTRL_REG1_A 0x20
#define MR_REG_M 0x02
#define OUT_X_L_A 0x28
#define OUT_X_H_M 0x03
#define LOG_FILE "compass_log.txt"
#define SAMPLE_INTERVAL 100

void sigint_handler(int signum) {
    printf("Exiting gracefully...\n");
    pigpio_stop();
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Exiting gracefully...\n");
    pigpio_stop();
    exit(0);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(I2C_BUS);
    if (pi < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    if (signal(SIGINT, sigint_handler) == SIG_IGN || signal(SIGTERM, sigterm_handler) == SIG_IGN) {
        perror("Failed to set signal handlers");
        return 1;
    }

    if (pigpio_setup_i2c(pi, I2C_BUS) < 0) {
        perror("Failed to set up I2C bus");
        return 1;
    }

    if (pigpio_write_i2c_addr(pi, ACCEL_ADDR, CTRL_REG1_A) < 0) {
        perror("Failed to write accelerometer control register");
        return 1;
    }
    if (pigpio_write_i2c_data(pi, ACCEL_ADDR, CTRL_REG1_A, 0x27) < 0) {
        perror("Failed to write accelerometer control register value");
        return 1;
    }

    if (pigpio_write_i2c_addr(pi, MAG_ADDR, MR_REG_M) < 0) {
        perror("Failed to write magnetometer control register");
    }
    if (pigpio_write_i2c_data(pi, MAG_ADDR, MR_REG_M, 0x00) < 0) {
        perror("Failed to write magnetometer control register value");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
