#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL6180X_ADDR 0x29
#define SAMPLE_INTERVAL 100
#define LOG_FILE "distance_log.txt"

void init_pigpio();
void log_distance(const char *status);
void read_vl6180x();
void handle_error(const char *msg);

int main(int argc, char *argv[]) {
    init_pigpio();

    while (1) {
        read_vl6180x();
        usleep(SAMPLE_INTERVAL * 1000 / 1000); // Convert 100 ms to microseconds
    }

    pigpio_stop();
    close(LOG_FILE);
    exit(0);
}

void init_pigpio() {
    int s = pigpio_init(I2C_BUS);
    if (s < 0) {
        handle_error("Failed to initialize pigpio: " + std::string(errno.strerror()));
        exit(EXIT_FAILURE);
    }
}

void log_distance(const char *status) {
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("Failed to open log file for writing.");
        return;
    }

    fprintf(log_file, "%s: %s\n", timestamp, status);
    fclose(log_file);
}

void read_vl6180x() {
    int sensor_present = pigpio_is_present(VL6180X_ADDR);
    if (!sensor_present) {
        log_distance("Sensor not found");
        return;
    }

    int result = pigpio_write_i2c_reg(I2C_BUS, VL6180X_ADDR, 0x01, 0x0207);
    if (result < 0) {
        handle_error("Failed to write to VL6180X register 0x000.");
        return;
    }

    result = pigpio_read_i2c_byte(I2C_BUS, VL6180X_ADDR, 0x04d);
    if (result < 0) {
        handle_error("Failed to read from VL6180X range status register 0x04d.");
        return;
    }

    if (result & 0x01) {
        log_distance("DOOR_OPEN");
    } else {
        log_distance("DOOR_CLOSED");
    }
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

