#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "audio_log.dat"

void sigint_handler(int signum) {
    printf("Exiting...\n");
    pigpio_terminate();
    close(logfd);
    exit(0);
}

int main() {
    int logfd;
    pigpio pi = pigpio_init(I2C_BUS);
    if (pi < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    if (pi_init(pi) < 0) {
        perror("Failed to initialize I2C bus");
        pigpio_terminate(pi);
        return 1;
    }

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd < 0) {
        perror("Failed to open log file");
        pigpio_terminate(pi);
        return 1;
    }

    const char *control_reg = "0x80";
    const char *sensor1_reg = "0x01";
    const char *sensor2_reg = "0x01";

    while (1) {
        time_t now = time(NULL);
        long long sec = now / (long long)CLOCKS_PER_SEC;
        long long nsec = (now % (long long)CLOCKS_PER_SEC) * 1000000;

        char buffer[16];
        int sensor1_data, sensor2_data;
        int result1 = pi_write_i2c_block_data(pi, 0x68, control_reg, 1);
        int result2 = pi_write_i2c_block_data(pi, 0x69, control_reg, 1);

        if (result1 < 0 || result2 < 0) {
            printf("Error writing control register\n");
            continue;
        }

        result1 = pi_read_i2c_block_data(pi, 0x68, sensor1_reg, 2, &sensor1_data);
        result2 = pi_read_i2c_block_data(pi, 0x69, sensor2_reg, 2, &sensor2_data);

        if (result1 < 0 || result2 < 0) {
            printf("Error reading sensor data\n");
            continue;
        }

        if (result1 < 0 || result2 < 0) {
            printf("Sensor not found or I2C bus failure\n");
            continue;
        }

        if (sensor1_data < 0 || sensor2_data < 0) {
            printf("Invalid sensor data\n");
            continue;
        }

        pi_write_i2c_block_data(pi, 0x68, control_reg, 0);
        pi_write_i2c_block_data(pi, 0x69, control_reg, 0);

        char tdoa_str[20];
        sprintf(tdoa_str, "%ld", (sensor2_data - sensor1_data));

        char log_entry[128];
        sprintf(log_entry, "%ld,%ld,%d,%d,%s\n", sec, nsec, sensor1_data, sensor2_data, tdoa_str);
        write(logfd, log_entry, strlen(log_entry));

        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
    }

    pigpio_terminate(pi);
    close(logfd);
    return 0;
}

