#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/time.h>

#define SPI_CHANNEL 0
#define CE_PIN 8
#define SPI_MODE 3
#define CPOL 1
#define CPHA 1
#define SPI_FLAGS 0b11000000000
#define REG_SIZE 16
#define GYRO_X_REG 0x04
#define GYRO_Y_REG 0x06
#define GYRO_Z_REG 0x08
#define ACCEL_X_REG 0x0A
#define ACCEL_Y_REG 0x0C
#define ACCEL_Z_REG 0x0E
#define SENSITIVITY_GYRO 0.005
#define SENSITIVITY_ACCEL 0.00025
#define LOG_INTERVAL 100
#define LOG_FILE "imu_data.csv"

void dummy_stall(void) {
    sleep_ms(40);
}

void spiXfer(int spi, const void *src, size_t len) {
    int ret = spi_xfer(spi, src, len);
    if (ret < 0) {
        fprintf(stderr, "Error in spi_xfer: %s\n", strerror(errno));
        return;
    }
}

void read_imu(int spi) {
    uint16_t reg_addr, data;
    uint8_t dummy_reg[2];

    // Request gyro registers
    reg_addr = GYRO_X_REG;
    spiXfer(spi, &reg_addr, 2);
    dummy_stall();
    spiXfer(spi, dummy_reg, 1);
    data = spi_xfer(spi, dummy_reg, 1);
    uint8_t gyro_x = (data >> 8) & 0x7F;
    uint8_t gyro_y = data & 0x7F;
    uint8_t gyro_z = 0; // Placeholder for future use

    // Request accelerometer registers
    reg_addr = ACCEL_X_REG;
    spiXfer(spi, &reg_addr, 2);
    dummy_stall();
    spiXfer(spi, dummy_reg, 1);
    data = spi_xfer(spi, dummy_reg, 1);
    uint8_t accel_x = (data >> 8) & 0x7F;
    uint8_t accel_y = data & 0x7F;
    uint8_t accel_z = 0; // Placeholder for future use

    // Convert to degrees/sec and g
    float gyro_deg_per_s = gyro_x * SENSITIVITY_GYRO;
    float accel_g = accel_x * SENSITY_ACCEL;

    // Log the data
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%f,%f,%f,%f,%f,%f\n", now, gyro_deg_per_s, accel_g, gyro_deg_per_s, accel_g, accel_g);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <gpio_pin>\n", argv[0]);
        return 1;
    }

    int gpio_pin = atoi(argv[1]);
    if (gpio_initialise(gpio_pin) < 0) {
        fprintf(stderr, "Failed to initialise GPIO.\n");
        return 1;
    }

    int spi_handle = spi_init(SPI_CHANNEL, CE_PIN, SPI_MODE, CPOL, CPHA, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI interface.\n");
        return 1;
    }

    while (1) {
        read_imu(spi_handle);
        usleep(LOG_INTERVAL * 1000 / 1000);
    }

    spi_close(spi_handle);
    pigpio_terminate(NULL);

    return 0;
}

void cleanup(void) {
    spi_close(spi_handle);
    pigpio_terminate(NULL);
}

atexit(cleanup);

