#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GYRO_REG_X 0x04
#define GYRO_REG_Y 0x06
#define GYRO_REG_Z 0x08
#define ACCEL_REG_X 0x0A
#define ACCEL_REG_Y 0x0C
#define ACCEL_REG_Z 0x0E
#define SCALE_GYRO 0.05
#define SCALE_ACCEL 0.00025

void read_imu(void) {
    int spi_transfer[2];
    int dummy_data;
    int gyro_x, gyro_y, gyro_z;
    int accel_x, accel_y, accel_z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Open SPI channel
    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Send read command
    spiTransfer(spi, 0x00, 0x01, 1); // Register address with bit 15 set

    // Wait for stall time
    usleep(40000);

    // Send dummy data
    spiTransfer(spi, 0x0000, 0x00, 1);

    // Read 16-bit data
    spiTransfer(spi, 0, spi_transfer, 2);

    // Extract gyroscope data
    gyro_x = (spi_transfer[0] << 8) | spi_transfer[1];
    gyro_y = (spi_transfer[2] << 8) | spi_transfer[3];
    gyro_z = (spi_transfer[4] << 8) | spi_transfer[5];

    // Extract accelerometer data
    accel_x = (spi_transfer[6] << 8) | spi_transfer[7];
    accel_y = (spi_transfer[8] << 8) | spi_transfer[9];
    accel_z = (spi_transfer[10] << 8) | spi_transfer[11];

    // Scale and print values
    printf("Gyroscope: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n", gyro_x * SCALE_GYRO, gyro_y * SCALE_GYRO, gyro_z * SCALE_GYRO);
    printf("Accelerometer: X=%.3f m/s^2, Y=%.3f m/s^2, Z=%.3f m/s^2\n", accel_x * SCALE_ACCEL, accel_y * SCALE_ACCEL, accel_z * SCALE_ACCEL);

    // Sleep for 100 ms
    usleep(100000);
}

int main(int argc, char *argv[]) {
    read_imu();
    return 0;
}

