#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_DATA_START 0x3B
#define ACCEL_DATA_END 0x40
#define GYRO_DATA_START 0x43
#define GYRO_DATA_END 0x48
#define READ_INTERVAL_MS 50

int i2c_fd;

int check_sensor_presence() {
    uint8_t who_am_i;
    ssize_t ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret == -1) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }

    ret = read(i2c_fd, &who_am_i, 1);
    if (ret == -1) {
        perror("read(I2C_SLAVE)");
        return -1;
    }

    if (who_am_i != 0x86) {
        fprintf(stderr, "Sensor not present, returning -1\n");
        return -1;
    }

    return 0;
}

int initialize_imu() {
    uint8_t pwr_mgmt_1 = PWR_MGMT_1;
    uint8_t accel_config = ACCEL_CONFIG;
    uint8_t gyro_config = GYRO_CONFIG;

    ssize_t ret = ioctl(i2c_fd, I2C_WRITE, I2C_ADDR);
    if (ret == -1) {
        perror("ioctl(I2C_WRITE)");
        return -1;
    }

    ret = write(i2c_fd, &pwr_mgmt_1, 1);
    if (ret == -1) {
        perror("write(I2C_WRITE)");
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_WRITE, I2C_ADDR);
    if (ret == -1) {
        perror("ioctl(I2C_WRITE)");
        return -1;
    }

    ret = write(i2c_fd, &accel_config, 1);
    if (ret == -1) {
        perror("write(I2C_WRITE)");
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_WRITE, I2C_ADDR);
    if (ret == -1) {
        perror("ioctl(I2C_WRITE)");
        return -1;
    }

    ret = write(i2c_fd, &gyro_config, 1);
    if (ret == -1) {
        perror("write(I2C_WRITE)");
        return -1;
    }

    return 0;
}

int read_imu_data() {
    uint16_t accel_data[6];
    uint16_t gyro_data[6];

    ssize_t ret = ioctl(i2c_fd, I2C_READ, I2C_ADDR);
    if (ret == -1) {
        perror("ioctl(I2C_READ)");
        return -1;
    }

    ret = read(i2c_fd, accel_data, sizeof(accel_data));
    if (ret == -1) {
        perror("read(I2C_READ)");
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_READ, I2C_ADDR);
    if (ret == -1) {
        perror("ioctl(I2C_READ)");
        return -1;
    }

    ret = read(i2c_fd, gyro_data, sizeof(gyro_data));
    if (ret == -1) {
        perror("read(I2C_READ)");
        return -1;
    }

    return 0;
}

int main() {
    int ret;

    ret = check_sensor_presence();
    if (ret != 0) {
        fprintf(stderr, "Failed to check sensor presence, exiting\n");
        return ret;
    }

    ret = initialize_imu();
    if (ret != 0) {
        fprintf(stderr, "Failed to initialize IMU, exiting\n");
        return ret;
    }

    while (1) {
        ret = read_imu_data();
        if (ret != 0) {
            fprintf(stderr, "Failed to read IMU data, exiting\n");
            return ret;
