#define THRESHOLD_MAG 2.5

int main(int argc, char *argv[]) {
    int i2c_fd, led_fd, log_fd;
    struct i2c_client *client;
    int adxl_id;
    float x, y, z, mag;
    struct timespec ts;
    char log_entry[100];

    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (i2c_fd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(I2C_BUS, ADXL345_ADDR);
    if (!client) {
        perror("Failed to create I2C client");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_write_byte(client, 0x2A) != 0xE5) {
        fprintf(stderr, "ADXL345 not found or not responding\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ts.tv_sec = 0;
        ts.tv_nsec = 0;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Read acceleration data
        if (i2c_read_byte(client, 0x32) == 0x80) {
            adxl_id = i2c_read_byte(client, 0x2A);
            if (adxl_id != 0xE5) {
                fprintf(stderr, "ADXL345 ID mismatch\n");
                break;
            }

            x = i2c_read_byte_buf(client, 0x2B);
            y = i2c_read_byte_buf(client, 0x2C);
            z = i2c_read_byte_buf(client, 0x2D);
            mag = sqrt(x*x + y*y + z*z);

            if (mag > THRESHOLD_MAG) {
                // Turn on LED
                if (write(LED_PIN, HIGH) == -1) {
                    perror("Error turning on LED");
                    break;
                }
                printf("Impact detected! Magnitude: %f g, X: %f, Y: %f, Z: %f\n", mag, x, y, z);

                // Append to log file
                snprintf(log_entry, sizeof(log_entry), "%ld.%09ld %f %f %f\n",
                         (long)ts.tv_sec, (long)ts.tv_nsec / 1000000000, mag, x, y, z);
                write(i2c_fd, log_entry, strlen(log_entry));

                // Delay for 500 ms
                usleep(500000);
            }
        }

        usleep(POLL_INTERVAL_MS / 1000);
    }

    i2c_client_free(client);
    close(i2c_fd);
    close(log_fd);
    return 0;
}

