#define ACCEL_CONFIG 0x00
#define GYRO_CONFIG 0x00
#define ACCEL_WHO_AM_I 0x3B
#define GYRO_WHO_AM_I 0x43

#define LOG_INTERVAL 10000  // 10 Hz

void sigint_handler(int signum) {
    piGPIO_stop();
    close(piGPIO_getI2CFile());
    fclose(stdout);
    exit(0);
}

int main() {
    int i2c_fd;
    int ret;

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Wake up the ICM-20602 from sleep
    ret = i2cWrite(i2c_fd, I2C_ADDR, PWR_MGMT_1);
    if (ret != 2) {
        fprintf(stderr, "Failed to wake up ICM-20602\n");
        piGPIO_stop();
        close(i2c_fd);
        return 1;
    }

    // Set accelerometer and gyroscope configurations
    ret = i2cWrite(i2c_fd, I2C_ADDR, ACCEL_CONFIG);
    if (ret != 2) {
        fprintf(stderr, "Failed to set accelerometer configuration\n");
        piGPIO_stop();
        close(i2c_fd);
        return 1;
    }

    ret = i2cWrite(i2c_fd, I2C_ADDR, GYRO_CONFIG);
    if (ret != 2) {
        fprintf(stderr, "Failed to set gyroscope configuration\n");
        piGPIO_stop();
        close(i2c_fd);
        return 1;
    }

    // Verify sensor presence
    uint8_t whoAmI;
    ret = i2cReadI2CBlockData(i2c_fd, I2C_ADDR, 1, &whoAmI, sizeof(whoAmI));
    if (ret != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        piGPIO_stop();
        close(i2c_fd);
        return 1;
    }

    if (whoAmI != 0x12) {
        fprintf(stderr, "Sensor not present, expected 0x12\n");
        piGPIO_stop();
        close(i2c_fd);
        return 1;
    }

    FILE *csv_file = fopen("imu_log.csv", "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        piGPIO_stop();
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read accelerometer data
        ret = i2cReadI2CBlockData(i2c_fd, I2C_ADDR, 6, (uint8_t *)&accel_data[0], 6);
        if (ret != 6) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }

        // Read gyroscope data
        ret = i2cReadI2CBlockData(i2c_fd, I2C_ADDR, 6, (uint8_t *)&gyro_data[0], 6);
        if (ret != 6) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            break;
        }

        // Log data to CSV
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(csv_file, "%s,%f,%f,%f,%f,%f\n", timestamp, accel_data[0], accel_data[1], accel_data[2], gyro_data[0], gyro_data[1]);

        // Sleep for the desired interval
        usleep(LOG_INTERVAL * 100000);
    }

    // Handle Ctrl+C gracefully
    signal(SIGINT, sigint_handler);

    // Close I2C handle and pigpio
    piGPIO_stop();
    close(i2c_fd);

    // Close CSV file
    fclose(csv_file);

    return 0;
}

