#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/epoll.h>
#include <sys/poll.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I 0x0D
#define MAGNITUDE_THRESHOLD 2000
#define LED_GPIO 17

#define BUFFER_SIZE 6

int i2c_fd;
int led_fd;

int is_valid_response(unsigned char *data) {
    return (data[0] == 0x1A);
}

int read_who_am_i(unsigned char *buffer) {
    unsigned char read_buf[1];
    return ioctl(i2c_fd, I2C_READ_REG, I2C_ADDR | WHO_AM_I);
}

int write_reg(unsigned char *data, size_t len) {
    return ioctl(i2c_fd, I2C_WRITE_REG, I2C_ADDR, data, len);
}

int read_data(unsigned char *buffer) {
    return ioctl(i2c_fd, I2C_READ_REG, I2C_ADDR);
}

int main(int argc, char *argv[]) {
    int ret;
    struct timespec ts;
    char log_msg[100];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    led_fd = open(LED_GPIO, O_WRLCK | O_CREAT, 0666);
    if (led_fd < 0) {
        perror("Failed to open LED GPIO");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    if (read_who_am_i(NULL) != 0x1A) {
        fprintf(stderr, "Sensor is not responding, exiting.\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        unsigned char buffer[BUFFER_SIZE];
        ret = read_data(buffer);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            exit(EXIT_FAILURE);
        }

        if (ret == BUFFER_SIZE) {
            unsigned char who_am_i[1];
            read_who_am_i(who_am_i);
            if (who_am_i[0] != 0x1A) {
                fprintf(stderr, "Sensor identity check failed, exiting.\n");
                exit(EXIT_FAILURE);
            }

            unsigned char x[2];
            unsigned char y[2];
            unsigned char z[2];

            memcpy(x, buffer + 1, 1);
            memcpy(y, buffer + 2, 1);
            memcpy(z, buffer + 3, 1);

            int x_acc = x[0] << 8 | x[1];
            int y_acc = y[0] << 8 | y[1];
            int z_acc = z[0] << 8 | z[1];

            int magnitude = (int)((x_acc * x_acc + y_acc * y_acc + z_acc * z_acc) * 1024 / 2);

            if (magnitude > MAGNITUDE_THRESHOLD) {
                ts.tv_sec = time(NULL) / 1000;
                ts.tv_nsec = (time(NULL) % 1) * 1000000000;
                strftime(log_msg, sizeof(log_msg), "Impact detected at %d:%02d:%02d",
                        ts.tv_sec, ts.tv_usec / 1000000 % 60, ts.tv_usec / 100000000 % 60);
                write(LED_GPIO, "1", 1);
                usleep(500000);
                write(LED_GPIO, "0", 1);
                write(LED_GPIO, log_msg, strlen(log_msg));
                write(LED_GPIO, "\n", 1);
            }
        }

        usleep(100000);
    }

    close(led_fd);
    close(i2c_fd);

    return 0;

signal_handler:
    fprintf(stderr, "Received signal, exiting gracefully.\n");
    exit(EXIT_SUCCESS);
}

