#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#define I2C_BUS 1
#define I2C_ADDR 0x35
#define REG_X 0x10
#define REG_Y 0x11
#define REG_Z 0x12
#define LOG_FILE "magnetic_field_log.csv"
#define SAMPLE_RATE 1

void sigint_handler(int sig) {
    close(fd_i2c);
    close(fd_log);
    fprintf(stderr, "SIGINT/SIGTERM received, exiting...\n");
    exit(0);
}

void sigterm_handler(int sig) {
    close(fd_i2c);
    close(fd_log);
    fprintf(stderr, "SIGTERM received, exiting...\n");
    exit(0);
}

int main() {
    int fd_i2c, fd_log;
    struct i2c_client *client;
    char buffer[6];
    long long x, y, z;
    struct stat sb;

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open I2C bus
    fd_i2c = open("/dev/i2c-1", O_RDWR);
    if (fd_i2c < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C mode
    ioctl(fd_i2c, I2C_SET_ADDRESS, &I2C_ADDR);

    // Open the sensor log file
    fd_log = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd_log < 0) {
        perror("Failed to open magnetic_field_log.csv");
        close(fd_i2c);
        exit(EXIT_FAILURE);
    }

    // Initialize the i2c client
    client = i2c_alloc(fd_i2c);
    if (!client) {
        perror("Failed to allocate i2c client");
        close(fd_log);
        close(fd_i2c);
        exit(EXIT_FAILURE);
