void handle_error(const char *msg);

int main(int argc, char *argv[]) {
    int ret;
    struct i2c_client *client;
    struct timeval tv;

    init_i2c();
    init_gpio();

    while (1) {
        ret = libgpiod_poll_event(0);
        if (ret < 0) {
            handle_error("Error polling GPIO events");
            break;
        }
        if (ret == GPIO_EVENT_SET) {
            freefall_event();
        }
    }

    close(i2c_fd);
    gpiod_disable(adxl_gpio);
    close(adxl_gpio);
    close(i2c_fd);

    return 0;
}

void init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        handle_error("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        handle_error("Failed to acquire bus access");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio(void) {
    ret = gpiod_ad_add_dt_single(INT_PIN, GP_OUTPUT, &adxl_gpio);
    if (ret < 0) {
        handle_error("Failed to add GPIO pin");
        exit(EXIT_FAILURE);
    }
}

