    int int_status;
    struct i2c_msg msg;

    msg.len = sizeof(int_status);
    msg.type = I2C_MSG_READ_BYTE;
    msg.data = &int_status;

    ret = libgpiod_poll_event(0);
    if (ret == GPIO_EVENT_SET) {
        ret = ioctl(i2c_fd, I2C_MASTER, &msg);
        if (ret < 0) {
            handle_error("Failed to read INT_SOURCE");
            return;
        }

        if (int_status & (1 << 2)) {
            log_data(get_timestamp(), read_acceleration());
        }
    }
}

