    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        handle_error("Failed to open log file");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

int read_acceleration(void) {
    int data[6];
    struct i2c_msg msg;

    msg.len = sizeof(data);
    msg.type = I2C_MSG_READ_BYTE;
    msg.data = &data[0];

    ret = libgpiod_poll_event(0);
    if (ret < 0) {
        handle_error("Failed to read DATAX0");
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_MASTER, &msg);
    if (ret < 0) {
        handle_error("Failed to read DATAX0");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

