#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define SDA_PIN 2
#define SCL_PIN 3
#define LOG_FILE "motion_log.txt"
#define FALL_THRESHOLD_G 0.2
#define IMPACT_THRESHOLD_G 2.5
#define FALL_WINDOW_S 1.0

typedef struct {
    long timestamp;
    float ax, ay, az, gx, gy, gz;
} IMUData;

void log_data(IMUData data) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%ld,%.3f,%.3f,%.3f,%.3f,%.3f\n", data.timestamp, data.ax, data.ay, data.az, data.gx, data.gy);
    fclose(file);
}

void init_pigpio() {
    if (pigpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    if (i2cSetup(I2C_BUS, I2C_ADDR) < 0) {
        perror("Failed to setup I2C bus");
        exit(EXIT_FAILURE);
    }
}

void write_i2c(uint8_t cmd) {
    if (i2cWrite(SDA_PIN, SCL_PIN, cmd) < 0) {
        perror("Failed to write to I2C");
        exit(EXIT_FAILURE);
    }
}

int read_i2c(uint8_t cmd) {
    uint8_t response[2];
    if (i2cRead(SDA_PIN, SCL_PIN, cmd, response) < 0) {
        perror("Failed to read from I2C");
        exit(EXIT_FAILURE);
    }
    return response[0];
}

void configure_imu() {
    write_i2c(0x3B); // Set full range (+-2g)
    write_i2c(0x20); // Set 104 Hz ODR
    write_i2c(0x2A); // Enable gyro and accel
    write_i2c(0x00); // Start self-test
}

void read_imu_data() {
    uint8_t status = read_i2c(0x19);
    if (status & 0x04) {
        printf("Sensor present\n");
    } else {
        printf("Sensor absent\n");
        return;
    }

    IMUData data;
    data.timestamp = get_timestamp();
    data.ax = read_i2c(0x1A) << 8 | read_i2c(0x1B);
    data.ay = read_i2c(0x1C) << 8 | read_i2c(0x1D);
    data.az = read_i2c(0x1E) << 8 | read_i2c(0x1F);
    data.gx = read_i2c(0x26) << 8 | read_i2c(0x27);
    data.gy = read_i2c(0x28) << 8 | read_i2c(0x29);
    data.gz = read_i2c(0x2A);

    log_data(data);
}

long get_timestamp() {
    return (long)time(NULL);
}

void fall_detection_state_machine() {
    static IMUData last_data = {0, 0, 0, 0, 0, 0};
    IMUData current_data = {get_timestamp(), 0, 0, 0, 0, 0};

    if (current_data.ax < FALL_THRESHOLD_G && current_data.ay < FALL_THRESHOLD_G && current_data.az < FALL_THRESHOLD_G) {
        printf("Freefall detected\n");
        // Add logic for freefall handling
    } else if (current_data.ax > IMPACT_THRESHOLD_G || current_data.ay > IMPACT_THRESHOLD_G || current_data.az > IMPACT_THRESHOLD_G) {
        printf("Impact detected\n");
        // Add logic for impact handling
    }
}

int main() {
    init_pigpio();
    setup_i2c();
    configure_imu();

    while (1) {
        read_imu_data();
        fall_detection_state_machine();
    }

    pigiosync(); // Keep the program synchronized with the I2C bus
    pigioTerminate(); // Terminate pigpio

    return 0;
}

