#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define CPOL 1
#define CPHA 1
#define BAUD_RATE 1000000
#define REG_SIZE 2
#define REG_ADDR 0x14
#define SCALE 0.0305

#define LOG_FILE "gyro_log.csv"

void spi_init() {
    int spi_handle = piSpiOpen(SPI_CHANNEL, 0);
    if (spi_handle == -1) {
        fprintf(stderr, "Failed to open SPI channel\n");
        exit(EXIT_FAILURE);
    }
    printf("SPI channel opened successfully\n");
}

void check_who_am_i() {
    int who_am_i = piSpiRead(spi_handle, 0);
    if (who_am_i != 0x3F5A) {
        fprintf(stderr, "Device ID mismatch, expected 0x3F5A\n");
        piSpiClose(spi_handle);
        exit(EXIT_FAILURE);
    }
    printf("Device ID is correct\n");
}

void read_gyro_data() {
    int data;
    piSpiRead(spi_handle, REG_ADDR | 0x80); // Send register address with bit 7 set
    data = piSpiRead(spi_handle, REG_SIZE);
    printf("Angular rate: %.6f deg/s\n", (data * SCALE));
}

void log_to_csv(double rate) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    fprintf(log_file, "%.10f,%.6f\n", (double)rate, rate * SCALE);
    fclose(log_file);
}

void signal_handler(int signum) {
    piSpiClose(spi_handle);
    pigpio_exit();
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);

    spi_init();
    check_who_am_i();

    while (1) {
        read_gyro_data();
        log_to_csv(piSpiRead(spi_handle, REG_ADDR | 0x80) / 256.0);
        usleep(10000); // 10 ms delay
    }

    return 0;
}
