    gpioTerminate();
    close(logfd);
    exit(0);
}

int main() {
    int logfd;
    signal(SIGINT, sigint_handler);

    pigpio_init(I2C_BUS);

    if (pigpio_init(I2C_BUS) < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (pigpio_setup_i2c(I2C_BUS, I2C_ADDR) < 0) {
        perror("Failed to setup I2C");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x6B, 0x0F) < 0) {
        perror("Failed to write CTRL_REG1");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x24, 0x00) < 0) {
        perror("Failed to write CTRL_REG4");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x2C, 0x00) < 0) {
        perror("Failed to write OUT_X_L");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x2A, 0x00) < 0) {
        perror("Failed to write OUT_Y_L");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x2B, 0x00) < 0) {
        perror("Failed to write OUT_Z_L");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x28, 0x00) < 0) {
        perror("Failed to write OUT_X_H");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x2A, 0x00) < 0) {
        perror("Failed to write OUT_Y_H");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x2B, 0x00) < 0) {
        perror("Failed to write OUT_Z_H");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x0F, 0x00) < 0) {
        perror("Failed to write WHO_AM_I");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x00, 0x00) < 0) {
        perror("Failed to write WHO_AM_I (retry)");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x00, 0x00) < 0) {
        perror("Failed to write WHO_AM_I (retry)");
        return EXIT_FAILURE;
    }

    if (pigpio_write_byte_data(I2C_BUS, I2C_ADDR, 0x00, 0x00) < 0) {
        perror("Failed to write WHO_AM_I (retry)");
        return EXIT_FAILURE;
    }

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    char timestamp[32];
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(timestamp, sizeof(timestamp), "%f", clock_gettime(CLOCK_REALTIME, NULL));

    for (int i = 0; i < MAX_SAMPLES; i++) {
        if (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x28) < 0) {
            perror("Failed to read OUT_X_L");
            return EXIT_FAILURE;
        }
        if (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x29) < 0) {
            perror("Failed to read OUT_Y_L");
            return EXIT_FAILURE;
        }
        if (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x2A) < 0) {
            perror("Failed to read OUT_Z_L");
            return EXIT_FAILURE;
        }
        if (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x2B) < 0) {
            perror("Failed to read OUT_X_H");
            return EXIT_FAILURE;
        }
        if (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x2C) < 0) {
            perror("Failed to read OUT_Y_H");
            return EXIT_FAILURE;
        }
        if (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x2D) < 0) {
            perror("Failed to read OUT_Z_H");
            return EXIT_FAILURE;
        }

        int x = (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x28) << 8) | pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x29);
        int y = (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x2A) << 8) | pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x2B);
        int z = (pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x2C) << 8) | pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR, 0x2D);

        double vx = (x * SENSITIVITY) / 114.285;
        double vy = (y * SENSITIVITY) / 114.285;
        double vz = (z * SENSITIVITY) / 114.285;

        char line[128];
        sprintf(line, "%s,%.3f,%.3f,%.3f", timestamp, vx, vy, vz);
        write(logfd, line, strlen(line));
    }

    close(logfd);
    pigpio_terminate();
    return EXIT_SUCCESS;
}

