#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define POLL_INTERVAL 500

void flame_alarm(int signum) {
    global_flame_detected = 1;
}

int main(int argc, char *argv[]) {
    int gpio_pin = GPIO_PIN;
    int gpio_mode = PI_OUTPUT_ACTIVE_LOW;
    int gpio_pullup = 1;
    int log_file = open("flame_events.log", "a");
    if (log_file == -1) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (pigpio_init() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetup(gpio_pin, gpio_mode, gpio_pullup) == -1) {
        fprintf(stderr, "Failed to configure GPIO%d\n", gpio_pin);
        return EXIT_FAILURE;
    }

    signal(SIGINT, flame_alarm);

    while (1) {
        int sensor_state = gpioRead(gpio_pin);
        if (sensor_state == PI_INPUT_LOW) {
            global_flame_detected = 1;
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s - Flame detected: YES\n", timestamp);
            fprintf(log_file, "%s", "\n");
            flush(log_file);
            printf("FLAME DETECTED!\n");
        } else {
            global_flame_detected = 0;
        }

        usleep(POLL_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    pigpio_terminate();
    close(log_file);
    return EXIT_SUCCESS;
}

