#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SLAVE_ADDRESS 0x53
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D

#define LOG_FILE "vibration_log.csv"
#define LOG_HEADER "Timestamp,X,Y,Z"
#define LOG_TIMESTAMP "%Y-%m-%dT%H:%M:%SZ"

void log_to_csv(const char *timestamp, int x, int y, int z) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fclose(file);
}

int main() {
    int file_descriptor;
    struct i2c_client *client;
    long value;

    file_descriptor = open(I2C_BUS, O_RDWR);
    if (file_descriptor < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(file_descriptor);
    if (!client) {
        perror("Failed to allocate I2C client");
        close(file_descriptor);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file_descriptor, I2C_SLAVE, SLAVE_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        i2c_free(client);
        close(file_descriptor);
        exit(EXIT_FAILURE);
    }

    while (1) {
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), LOG_TIMESTAMP, localtime(&now));
        log_to_csv(timestamp, 0, 0, 0);

        value = i2c_read_byte_md(client, REG_X_LSB);
        if (value == 0xFF) {
            fprintf(stderr, "Sensor absent, skipping sample\n");
            continue;
        }

        value = i2c_read_byte_md(client, REG_X_MSB);
        x = (value << 8) | (value >> 24);

        value = i2c_read_byte_md(client, REG_Y_LSB);
        if (value == 0xFF) {
            fprintf(stderr, "Sensor absent, skipping sample\n");
            continue;
        }

        value = i2c_read_byte_md(client, REG_Y_MSB);
        y = (value << 8) | (value >> 24);

        value = i2c_read_byte_md(client, REG_Z_LSB);
        if (value == 0xFF) {
            fprintf(stderr, "Sensor absent, skipping sample\n");
            continue;
        }

        value = i2c_read_byte_md(client, REG_Z_MSB);
        z = (value << 8) | (value >> 24);

        log_to_csv(timestamp, x, y, z);

        usleep(100000); // Sleep for 100 ms
    }

    i2c_free(client);
    close(file_descriptor);

    return 0;
}

// Install SIGINT handler to cleanly close files on Ctrl+C
void sigint_handler(int sig) {
    fprintf(stderr, "SIGINT received, cleaning up and exiting...\n");
    log_to_csv(time(NULL), 0, 0, 0);
    fclose(NULL); // Close the CSV file
    close(file_descriptor);
    i2c_free(client);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    // Rest of the main function code...
}

