    printf("Conveyor halted.\n");
}

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    gpiod_resource_release(GPIO_RESOURCE_PIN(SENSOR_GPIO17));
    gpiod_resource_release(GPIO_RESOURCE_PIN(SENSOR_GPIO27));
    fclose(stdout);
    exit(0);
}

int main() {
    gpiod_resource_t *gpio_resources[2];

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    gpio_resources[0] = gpiod_resource_create_group(&gpio_resources[1]);
    if (!gpio_resources[0]) {
        perror("Failed to create GPIO resource group");
        return EXIT_FAILURE;
    }

    if (gpiod_resource_add_pin(gpio_resources[0], SENSOR_GPIO17, GPIOD_IN, GPIOD_PIN_PULLUP) < 0) {
        perror("Failed to add GPIO17 as input with pull-up");
        return EXIT_FAILURE;
    }

    if (gpiod_resource_add_pin(gpio_resources[0], SENSOR_GPIO27, GPIOD_IN, GPIOD_PIN_PULLUP) < 0) {
        perror("Failed to add GPIO27 as input with pull-up");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int sensor1_state = gpiod_get_value(gpio_resources[0], SENSOR_GPIO17);
        int sensor2_state = gpiod_get_value(gpio_resources[0], SENSOR_GPIO27);

        if (sensor1_state && sensor2_state) {
            halt_conveyor();
        }

        // Log entry with timestamp and sensor states
        log_entry(f"Sensor 1: %d, Sensor 2: %d");

        // Wait for the specified interval
        usleep(LOG_INTERVAL * 1000);
    }

    // Clean up and release resources
    for (int i = 0; i < 2; ++i) {
        gpiod_resource_destroy(gpio_resources[i]);
    }
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

