#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1D
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define DATA_RATE 0x010
#define ACTIVE_MODE 0x001
#define TILT_THRESHOLD 45

int fall_fd;
FILE *fall_log = fopen("fall_log.txt", "a");

void init_i2c() {
    fall_fd = open(I2C_BUS, O_RDWR | O_SYNC);
    if (fall_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fall_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fall_fd, I2C_QUERY_REGISTER, WHO_AM_I) == -1) {
        perror("Failed to query WHO_AM_I register");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fall_fd, I2C_READ_BYTE_RANGE, 0, 1, (uint8_t *)&0x2A) == -1) {
        perror("Failed to read WHO_AM_I register");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fall_fd, I2C_WRITE_BYTE_RANGE, 0, 1, (uint8_t *)&0x2A) == -1) {
        perror("Failed to write WHO_AM_I register");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fall_fd, I2C_READ_BYTE_RANGE, CTRL_REG1, 1, (uint8_t *)&0x00) == -1) {
        perror("Failed to read CTRL_REG1 register");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fall_fd, I2C_WRITE_BYTE_RANGE, CTRL_REG1, 1, (uint8_t *)&(0x00 & ~0x01)) == -1) {
        perror("Failed to clear standby mode bit");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fall_fd, I2C_WRITE_BYTE_RANGE, CTRL_REG1, 1, (uint8_t *)&(DATA_RATE & ~0x07)) == -1) {
        perror("Failed to set data rate");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fall_fd, I2C_WRITE_BYTE_RANGE, CTRL_REG1, 1, (uint8_t *)&(ACTIVE_MODE & ~0x01)) == -1) {
        perror("Failed to switch to active mode");
        exit(EXIT_FAILURE);
    }
}

void read_accel_data() {
    uint16_t data[6];
    ssize_t bytes_read = read(fall_fd, data, sizeof(data));
    if (bytes_read < 0) {
        perror("Failed to read accelerometer data");
        exit(EXIT_FAILURE);
    }

    if (bytes_read == 0) {
        return;
    }

    float x = (float)(data[0] << 8 | data[1]) / 32768.0f;
    float y = (float)(data[2] << 8 | data[3]) / 32768.0f;
    float z = (float)(data[4] << 8 | data[5]) / 32768.0f;

    float magnitude = sqrt(y * y + z * z);
    float tilt_angle = atan2(x, magnitude);

    if (fabs(tilt_angle) > TILT_THRESHOLD) {
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(fall_log, "%s: X=%d, Y=%d, Z=%d\n", timestamp, (int)x, (int)y, (int)z);
    }
}

void sigint_handler(int sig) {
    close(fall_fd);
    fclose(fall_log);
    exit(0);
}

int main() {
    init_i2c();

    if (signal(SIGINT, sigint_handler) == SIG_IGN) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_accel_data();
        usleep(100000); // 100 ms interval
    }

    return 0;
}

