#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define LIS3MDL_ADDR 0x1E
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x24
#define CTRL_REG3 0x28
#define MAG_REG 0x2C
#define SENS_REG 0x2D
#define MAG_LSB 0x2E
#define MAG_MSB 0x2F
#define CALIB_X 0.000146
#define CALIB_Y 0.000146
#define CALIB_Z 0.000146
#define THRESHOLD 800.0
#define LOG_FILE "magnetic_log.txt"
#define LOG_INTERVAL 10

int main() {
    int file_descriptor, ret;
    char buffer[6];
    long mag_value;
    long calibration_factor;
    int i, j;

    for (i = 0; i < 3; i++) {
        file_descriptor = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (file_descriptor < 0) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }

        for (j = 0; j < 10; j++) {
            ret = ioctl(file_descriptor, I2C_SLAVE, LIS3MDL_ADDR);
            if (ret < 0) {
                perror("Failed to set I2C slave address");
                close(file_descriptor);
                exit(EXIT_FAILURE);
            }

            ret = ioctl(file_descriptor, I2C_MEM_READ, LIS3MDL_ADDR | CTRL_REG1 | CTRL_REG4 | CTRL_REG3);
            if (ret < 0) {
                perror("Failed to read control register values");
                close(file_descriptor);
                exit(EXIT_FAILURE);
            }

            ret = ioctl(file_descriptor, I2C_MEM_READ, LIS3MDL_ADDR | MAG_REG);
            if (ret < 0) {
                perror("Failed to read magnetic field data");
                close(file_descriptor);
                exit(EXIT_FAILURE);
            }

            mag_value = ((long)buffer[5] << 24) | ((long)buffer[4] << 16) | ((long)buffer[3] << 8) | (long)buffer[2];
            calibration_factor = mag_value * CALIB_X;

            mag_value = ((long)buffer[15] << 24) | ((long)buffer[14] << 16) | ((long)buffer[13] << 8) | (long)buffer[12];
            calibration_factor += mag_value * CALIB_Y;

            calibration_factor += (long)buffer[11] << 24 | (long)buffer[10] << 16 | (long)buffer[9] << 8 | (long)buffer[8];
            calibration_factor += mag_value * CALIB_Z;

            mag_value = calibration_factor / 0.146;

            if (mag_value > THRESHOLD) {
                fprintf(stderr, "Metal detector threshold exceeded: %.2f mG\n", mag_value);
            }

            ret = ioctl(file_descriptor, I2C_MEM_WRITE, LIS3MDL_ADDR | MAG_REG, &mag_value);
            if (ret < 0) {
                perror("Failed to write magnetic field data");
                close(file_descriptor);
                exit(EXIT_FAILURE);
            }

            ret = ioctl(file_descriptor, I2C_MEM_WRITE, LIS3MDL_ADDR | WHO_AM_I);
            if (ret < 0) {
                perror("Failed to read WHO_AM_I");
                close(file_descriptor);
                exit(EXIT_FAILURE);
            }

            if (ret == 0x3D) {
                break;
            }
        }

        close(file_descriptor);
        usleep(LOG_INTERVAL * 1000000);
    }

    return 0;
}

