#define SPI_CHANNEL 0
#define SPI_CLOCK_FREQ 1000000
#define SPI_MODE 0
#define ADXL354B_RESET_ADDR 0x1F
#define ADXL354B_POWER_CTL_ADDR 0x2D
#define ADXL354B_STATUS_ADDR 0x04
#define ADXL354B_PARTID_ADDR 0x01
#define LOG_FILE "vibration_log.txt"
#define RETRY_COUNT 3
#define READ_INTERVAL 100

void spi_init(void) {
    int ret;
    ret = pigpio_init(SPI_CHANNEL);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize SPI: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    ret = pigpio_set_mode(SPI_CHANNEL, PIGIO_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    ret = pigpio_set_special_function(SPI_CHANNEL, PIGIO_SPI);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI function: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    ret = pigpio_set_clock_freq(SPI_CHANNEL, SPI_CLOCK_FREQ);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI clock frequency: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    ret = pigpio_set_mode(SPI_CHANNEL, PIGIO_SPI);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    ret = pigpio_set_bits_per_word(SPI_CHANNEL, 24);
    if (ret < 0) {
        fprintf(stderr, "Failed to set bits per word: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

void spi_write_byte(int channel, uint8_t data) {
    pigpio_write_byte(channel, data);
}

void spi_write_word(int channel, uint16_t data) {
    pigpio_write_word(channel, data);
}

uint16_t spi_read_word(int channel) {
    return pigpio_read_word(channel);
}

void spi_read_reset(int channel) {
    spi_write_byte(channel, ADXL354B_RESET_ADDR);
    usleep(1000);
    spi_write_byte(channel, 0x52);
    usleep(1000);
}

void spi_set_measurement_mode(int channel) {
    spi_write_byte(channel, ADXL354B_POWER_CTL_ADDR);
    spi_write_byte(channel, 0x00); // Clear RUN bit
    while (!(spi_read_word(channel) & 0x08)) {
        usleep(1000);
    }
    spi_write_byte(channel, ADXL354B_POWER_CTL_ADDR);
    spi_write_byte(channel, 0x01); // Set RUN bit
}

void spi_read_acceleration(int channel) {
    uint16_t x, y, z;
    spi_write_byte(channel, ADXL354B_PARTID_ADDR);
    x = spi_read_word(channel) & 0x00FF;
    y = spi_read_word(channel) & 0x00FF;
    z = spi_read_word(channel) & 0x00FF;
    spi_write_byte(channel, 0x2D); // Set STABLE bit
    while (!(spi_read_word(channel) & 0x04)) {
        usleep(1000);
    }
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
}

void log_to_file(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return;
    }
    fprintf(file, "%s", message);
    fclose(file);
}

void signal_handler(int signum) {
    spi_close();
    log_to_file("Shutting down...\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();

    while (1) {
        spi_read_reset(SPI_CHANNEL);
        spi_set_measurement_mode(SPI_CHANNEL);
        spi_read_acceleration(SPI_CHANNEL);
        usleep(READ_INTERVAL * 1000);
    }

    spi_close();
    log_to_file("Exiting...\n");
    return 0;
}

