#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define BAUD_RATE 1000000
#define SPI_MODE 3
#define GYRO_ADDR_X 0x04
#define GYRO_ADDR_Y 0x06
#define GYRO_ADDR_Z 0x08
#define ACCEL_ADDR_X 0x0A
#define ACCEL_ADDR_Y 0x0C
#define ACCEL_ADDR_Z 0x0E
#define SCALING_GYRO 0.05
#define SCALING_ACCEL 0.0025
#define SAMPLE_DELAY 100000000  // 10 ms

void spiError(const char *msg) {
    fprintf(stderr, "SPI error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void sigintHandler(int sig) {
    spiTerminate();
    fclose("imu_log.csv");
    exit(EXIT_SUCCESS);
}

int main() {
    int spi_handle, log_file;
    struct sigaction sa;

    spi_init(-1);
    if (spi_error()) {
        spiError("Failed to initialize SPI");
        return 1;
    }

    spi_open(SPI_CHANNEL, BAUD_RATE, SPI_MODE);
    if (spi_error()) {
        spiError("Failed to open SPI channel");
        return 1;
    }

    sa.sa_handler = sigintHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    log_file = open("imu_log.csv", "w");
    if (log_file == -1) {
        spiError("Failed to open log file");
        spiTerminate();
        return 1;
    }

    while (1) {
        uint16_t gyro_data, accel_data;
        struct timespec ts;
        char timestamp[32];

        clock_gettime(CLOCK_REALTIME, &ts);
        int64_t seconds = ts.tv_sec;
        int32_t nanos = ts.tv_nsec / 1000000000;
        int64_t timestamp_ns = seconds * 1000000000 + nanos;

        // Write timestamp
        sprintf(timestamp, "%lld.%09d", (int64_t)seconds, (int32_t)(nanos % 1000000000));
        fputs(timestamp, log_file);
        fputs(",", log_file);

        // Read gyroscope data
        spiXfer(spi_handle, GYRO_ADDR_X | 0x80, 1);
        spiXfer(spi_handle, 0x00, 1);
        spiXfer(spi_handle, GYRO_ADDR_X, 2);
        gyro_data = spiXfer(spi_handle, 0x00, 2);

        // Read accelerometer data
        spiXfer(spi_handle, ACCEL_ADDR_X | 0x80, 1);
        spiXfer(spi_handle, 0x00, 1);
        spiXfer(spi_handle, ACCEL_ADDR_X, 2);
        accel_data = spiXfer(spi_handle, 0x00, 2);

        // Scale and format data
        int16_t gyro_x = (int16_t)(gyro_data * SCALING_GYRO);
        int16_t gyro_y = (int16_t)(gyro_data >> 8 * SCALING_GYRO);
        int16_t gyro_z = (int16_t)(gyro_data >> 16 * SCALING_GYRO);

        int16_t accel_x = (int16_t)(accel_data * SCALING_ACCEL);
        int16_t accel_y = (int16_t)(accel_data >> 8 * SCALING_ACCEL);
        int16_t accel_z = (int16_t)(accel_data >> 16 * SCALING_ACCEL);

        // Log data
        fputs("1,", log_file);
        fputs(timestamp, log_file);
        fputs(";", log_file);
        fputs(std::to_string(gyro_x).c_str(), log_file);
        fputs(",", log_file);
        fputs(std::to_string(gyro_y).c_str(), log_file);
        fputs(",", log_file);
        fputs(std::to_string(gyro_z).c_str(), log_file);
        fputs(",", log_file);
        fputs(std::to_string(accel_x).c_str(), log_file);
        fputs(",", log_file);
        fputs(std::to_string(accel_y).c_str(), log_file);
        fputs(",", log_file);
        fputs(std::to_string(accel_z).c_str(), log_file);
        fputs("\n", log_file);

        usleep(SAMPLE_DELAY * 1000000 / 100); // Adjust delay for 100 Hz
    }

    spiTerminate();
    fclose(log_file);
    return 0;
}

