#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP_ID 0
#define GPIO_PIN_A 11
#define GPIO_PIN_B 13

#define POLL_INTERVAL_MS 100

void handle_interrupt(int sig) {
    printf("Collision avoidance system shutting down...\n");
    // Add cleanup code if needed
    exit(0);
}

int main() {
    struct gpiod_line_request request_a, request_b;
    int ret;

    // Initialize libgpiod
    ret = gpiod_chip_init(GPIO_CHIP_ID, 1);
    if (ret < 0) {
        perror("Failed to initialize gpio chip");
        exit(EXIT_FAILURE);
    }

    // Request GPIO pins A and B for input
    ret = gpiod_line_request_init(GPIO_CHIP_ID, GPIO_PIN_A, GPIOD_IN, &request_a);
    if (ret < 0) {
        perror("Failed to request GPIO_PIN_A");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_init(GPIO_CHIP_ID, GPIO_PIN_B, GPIOD_IN, &request_b);
    if (ret < 0) {
        perror("Failed to request GPIO_PIN_B");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_interrupt);

    while (1) {
        // Poll both sensors
        ret = gpiod_line_request_get_values(request_a, &request_b);
        if (ret < 0) {
            perror("Failed to get values from GPIO lines");
            continue;
        }

        int sensor_a = request_a.value;
        int sensor_b = request_b.value;

        // Log obstacle detection status
        if (sensor_a == 0 || sensor_b == 0) {
