            printf("Path clear at %d ms\n", (int)uscale());
        }

        // Sleep before next poll
        usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    // Release resources
    gpiod_line_request_destroy(&request_a);
    gpiod_line_request_destroy(&request_b);
    gpiod_chip_destroy(GPIO_CHIP_ID);

