        perror("Failed to set SPI number of channels");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_CHANNEL, 0) < 0) {
        perror("Failed to set SPI channel");
        exit(EXIT_FAILURE);
    }

