            perror("Failed to start SPI transfer");
            exit(EXIT_FAILURE);
        }

        if (ioctl(fd, SPI_IOC_RTS_CONT, &spi_data) < 0) {
            perror("Failed to continue SPI transfer");
            exit(EXIT_FAILURE);
        }

        if (ioctl(fd, SPI_IOC_RTS_STOP, &spi_data) < 0) {
            perror("Failed to stop SPI transfer");
            exit(EXIT_FAILURE);
        }

        x_rate = spi_data.data[0] << 8 | spi_data.data[1];
        y_rate = spi_data.data[2] << 8 | spi_data.data[3];
        z_rate = spi_data.data[4] << 8 | spi_data.data[5];

        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n",
               SCALE_FACTOR * (double)x_rate / 1000000,
               SCALE_FACTOR * (double)y_rate / 1000000,
               SCALE_FACTOR * (double)z_rate / 1000000);

        usleep(100000);
    }

    close(fd);
    gpio_ad9c94_deinit(CS_PIN);
    return 0;
}

