#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6B
#define GYRO_START 0x22
#define ACCEL_START 0x23
#define CTRL1_XL 0x42
#define CTRL2_G 0x42
#define SENSITIVITY_GYRO 8.75
#define SENSITIVITY_ACCEL 0.061

void sigint_handler(int signum) {
    printf("\nSIGINT received. Clean shutdown...\n");
    pigpio_terminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    int result;

    // Initialize pigpio
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    result = pigpio_i2c_open(I2C_BUS, &i2c_fd);
    if (result < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_terminate();
        return 1;
    }

    // Verify sensor presence
    uint8_t who_am_i;
    result = pigpio_i2c_write(i2c_fd, I2C_ADDR, 0x01, 1, &who_am_i);
    if (result < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        pigpio_i2c_close(i2c_fd);
        pigpio_terminate();
        return 1;
    }
    if (who_am_i != I2C_ADDR) {
        fprintf(stderr, "Sensor not present at address 0x%02x\n", I2C_ADDR);
        pigpio_i2c_close(i2c_fd);
        pigpio_terminate();
        return 1;
    }

    // Configure sensor
    result = pigpio_i2c_write(i2c_fd, I2C_ADDR, CTRL1_XL, 1, 0x42);
    if (result < 0) {
        fprintf(stderr, "Failed to configure accelerometer\n");
        pigpio_i2c_close(i2c_fd);
        pigpio_terminate();
        return 1;
    }

    result = pigpio_i2c_write(i2c_fd, I2C_ADDR, CTRL2_G, 1, 0x42);
    if (result < 0) {
        fprintf(stderr, "Failed to configure gyroscope\n");
        pigpio_i2c_close(i2c_fd);
        pigpio_terminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Burst read 12 bytes starting at OUTX_L_G (0x22)
        uint8_t gyro_data[12];
        result = pigpio_i2c_read_bulk(i2c_fd, I2C_ADDR, GYRO_START, gyro_data, 12);
        if (result < 0) {
            fprintf(stderr, "Failed to burst read gyroscope data\n");
            break;
        }

        uint8_t accel_data[12];
        result = pigpio_i2c_read_bulk(i2c_fd, I2C_ADDR, ACCEL_START, accel_data, 12);
        if (result < 0) {
            fprintf(stderr, "Failed to burst read accelerometer data\n");
            break;
        }

        // Convert to physical units
        float gyro_x = (float)gyro_data[0] * SENSITIVITY_GYRO / 16.0;
        float gyro_y = (float)gyro_data[1] * SENSITIVITY_GYRO / 16.0;
        float gyro_z = (float)gyro_data[2] * SENSITIVITY_GYRO / 16.0;

        float accel_x = (float)accel_data[0] * SENSITIVITY_ACCEL / 16.0;
        float accel_y = (float)accel_data[1] * SENSITIVITY_ACCEL / 16.0;
        float accel_z = (float)accel_data[2] * SENSITIVITY_ACCEL / 16.0;

        // Print data
        printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f g, Acc: X=%.2f, Y=%.2f, Z=%.2f g\n", gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean shutdown
    pigpio_i2c_close(i2c_fd);
    pigpio_terminate();

    return 0;
}

