#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define REG_CTRL1 0x2A
#define REG_CTRL2 0x2B
#define REG_M_CTRL1 0x5B
#define REG_M_CTRL2 0x5C
#define REG_OUT_X_MSB 0x01
#define WHO_AM_I 0x0D

void read_accel_mag(void) {
    int i2c_fd;
    int status;
    uint8_t reg_data[2];

    // Initialize pigpio
    if (piGPIOInit(I2C_BUS) < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    // Check if sensor is present
    if ((status = pigpioI2CRead(I2C_BUS, I2C_ADDR, WHO_AM_I, 1, reg_data)) != 2) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        pigpioClose(I2C_BUS);
        exit(EXIT_FAILURE);
    }

    if (reg_data[0] != 0xC7) {
        fprintf(stderr, "Sensor not present, exiting\n");
        pigpioClose(I2C_BUS);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    if ((status = pigpioI2CWrite(I2C_BUS, I2C_ADDR, REG_CTRL1, 1, &0x2A)) != 1) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        pigpioClose(I2C_BUS);
        exit(EXIT_FAILURE);
    }

    if ((status = pigpioI2CWrite(I2C_BUS, I2C_ADDR, REG_CTRL2, 1, &0x2B)) != 1) {
        fprintf(stderr, "Failed to write CTRL_REG2\n");
        pigpioClose(I2C_BUS);
        exit(EXIT_FAILURE);
    }

    if ((status = pigpioI2CWrite(I2C_BUS, I2C_ADDR, REG_M_CTRL1, 1, &0x5B)) != 1) {
        fprintf(stderr, "Failed to write M_CTRL_REG1\n");
        pigpioClose(I2C_BUS);
        exit(EXIT_FAILURE);
    }

    if ((status = pigpioI2CWrite(I2C_BUS, I2C_ADDR, REG_M_CTRL2, 1, &0x5C)) != 1) {
        fprintf(stderr, "Failed to write M_CTRL_REG2\n");
        pigpioClose(I2C_BUS);
        exit(EXIT_FAILURE);
    }

    // Read data
    if ((status = pigpioI2CRead(I2C_BUS, I2C_ADDR, REG_OUT_X_MSB, 1, reg_data)) != 2) {
        fprintf(stderr, "Failed to read OUT_X_MSB\n");
        pigpioClose(I2C_BUS);
        exit(EXIT_FAILURE);
    }

    // Extract raw accelerometer and magnetometer data
    uint16_t accel_x = (reg_data[1] << 8) | reg_data[0];
    uint16_t accel_y = (reg_data[3] << 8) | reg_data[2];
    uint16_t accel_z = (reg_data[5] << 8) | reg_data[4];

