    printf("Mag: X=%d, Y=%d, Z=%d\n", mag_x, mag_y, mag_z);

    // Sleep for 100 ms
    usleep(100000);
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    pigpioClose(I2C_BUS);
    exit(EXIT_SUCCESS);
}

