#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDRESS 0x53
#define REG_X 0x32
#define REG_Y 0x33
#define REG_Z 0x34
#define TILT_THRESHOLD 30.0

void log_tilt_event(const char *message) {
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *file = fopen("/var/log/tilt_events.log", "a");
    if (file) {
        fprintf(file, "%s: %s\n", timestamp, message);
        fclose(file);
    }
}

int main() {
    int file_fd;
    int i2c_fd;
    long result;

    file_fd = open("/var/log/tilt_events.log", O_APPEND | O_CREAT | O_WRONLY, 0644);
    if (file_fd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open(I2C_BUS, O_RDWR | O_SYNC);
    if (i2c_fd == -1) {
        perror("Error opening I2C bus");
        close(file_fd);
        exit(EXIT_FAILURE);
    }

    result = ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS);
    if (result == -1) {
        if (errno == EOPERNOTFOUND) {
            printf("ADXL345 not found at address 0x53\n");
        } else if (errno == EIO) {
            printf("I2C bus error\n");
        } else {
            perror("Error setting I2C slave address");
        }
        close(i2c_fd);
        close(file_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t x, y, z;
    result = read(i2c_fd, &x, 1);
    if (result == -1) {
        perror("Error reading X register");
        close(i2c_fd);
        close(file_fd);
        exit(EXIT_FAILURE);
    }

    result = read(i2c_fd, &y, 1);
    if (result == -1) {
        perror("Error reading Y register");
        close(i2c_fd);
        close(file_fd);
        exit(EXIT_FAILURE);
    }

    result = read(i2c_fd, &z, 1);
    if (result == -1) {
        perror("Error reading Z register");
        close(i2c_fd);
        close(file_fd);
        exit(EXIT_FAILURE);
    }

    double x_rad = x * (1.0 / 16384.0) * M_PI;
    double y_rad = y * (1.0 / 16384.0) * M_PI;
    double z_rad = z * (1.0 / 16384.0) * M_PI;

    double tilt_x = atan2(y_rad, x_rad);
    double tilt_y = atan2(z_rad, sqrt(x_rad * x_rad + y_rad * y_rad));

    if (fabs(tilt_x) > TILT_THRESHOLD || fabs(tilt_y) > TILT_THRESHOLD) {
        log_tilt_event("Tilt detected: X = %.2f, Y = %.2f, Z = %.2f degrees", x_rad, y_rad, z_rad);
    }

    close(i2c_fd);
    close(file_fd);

    return 0;
}

