#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_SECONDS 5
#define ALERT_THRESHOLD 10

int high_count = 0;
int window_start = 0;

void signal_handler(int signum) {
    printf("Received signal %d, terminating...\n", signum);
    gpioFinal();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 1;
    }

    gpioInitialise();

    gpioSetMode(GPIO_PIN, PIGO_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize pin as output low

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int now = (int)(clock() * 1000.0 / CLOCKS_PER_SEC);
        if (now - window_start >= WINDOW_SECONDS * SAMPLE_INTERVAL_MS) {
            int readings = 0;
            for (int i = window_start; i < now; i += SAMPLE_INTERVAL_MS) {
                int reading = gpioRead(GPIO_PIN);
                if (reading == PIGO_INPUT_HIGH) {
                    high_count++;
                }
                readings++;
            }

            if (high_count / (float)readings >= threshold) {
                printf("%.2f: ALERT - Sound level exceeded threshold!\n", now / 1000.0);
            } else {
                printf("%.2f: Normal - Sound level within threshold.\n", now / 1000.0);
            }

            window_start = now;
            high_count = 0;
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpioFinal();
    return 0;
}

