#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#define GPIO_A GPIO17
#define GPIO_B GPIO27
#define MAX_CODE_LENGTH 7
#define ACCESS_LOG "access_log.txt"

volatile sig_atomic_t exit_on_signal = 0;

void signal_handler(int signum) {
    exit_on_signal = 1;
}

int main() {
    pid_t pid;
    struct sigaction sa;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIOs as outputs
    if (gpiod_chip_open(&chip, 0) < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_open(&line_a, chip, GPIO_A) < 0) {
        fprintf(stderr, "Failed to open GPIO line %d\n", GPIO_A);
        return EXIT_FAILURE;
    }

    if (gpiod_line_open(&line_b, chip, GPIO_B) < 0) {
        fprintf(stderr, "Failed to open GPIO line %d\n", GPIO_B);
        return EXIT_FAILURE;
    }

    // Generate a random 6-digit code
    srand(time(NULL));
    int code[MAX_CODE_LENGTH];
    for (int i = 0; i < MAX_CODE_LENGTH; i++) {
        code[i] = rand() % 10;
    }

    // Print the code
    printf("Access code: ");
    for (int i = 0; i < MAX_CODE_LENGTH; i++) {
        printf("%d", code[i]);
        if ((i + 1) % 2 == 0) {
            printf(" ");
        }
    }
    printf("\n");

    // Read user input
    char user_code[MAX_CODE_LENGTH + 1];
    fgets(user_code, sizeof(user_code), stdin);
    user_code[strcspn(user_code, "\n")] = 0; // Remove newline character

    // Validate input
    if (sscanf(user_code, "%d%*c%d%*c%d%*c%d%*c%d", &code[0], &code[1], &code[2], &code[3], &code[4], &code[5]) != 6) {
        fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
        return EXIT_FAILURE;
    }

    // Check the code
    if (code[0] == 1 && code[1] == 0 && code[2] == 0 && code[3] == 0 && code[4] == 0 && code[5] == 9) {
        // Unlock Door A
        if (gpiod_line_write(&line_a, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to HIGH\n", GPIO_A);
            return EXIT_FAILURE;
        }

        // Wait for 5 seconds
        sleep(5);

        // Lock Door A
        if (gpiod_line_write(&line_a, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to LOW\n", GPIO_A);
            return EXIT_FAILURE;
        }

        // Log successful entry
        FILE *fp = fopen(ACCESS_LOG, "a");
        if (!fp) {
            fprintf(stderr, "Failed to open access log file\n");
            return EXIT_FAILURE;
        }
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %d\n", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
        fclose(fp);

        // Generate a new random code
        for (int i = 0; i < MAX_CODE_LENGTH; i++) {
            code[i] = rand() % 10;
        }
    } else {
        printf("Access denied\n");
    }

    // Clean up
    gpiod_line_close(&line_a);
    gpiod_line_close(&line_b);
    gpiod_chip_close(&chip);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Wait for SIGINT or SIGTERM
    waitpid(pid, NULL, 0);

    // Release resources on exit
    if (exit_on_signal) {
        gpiod_chip_close(&chip);
        gpiod_line_close(&line_a);
        gpiod_line_close(&line_b);
    }

    // Close any open file handles
    if (fp) fclose(fp);

    return EXIT_SUCCESS;
}

