            fprintf(stderr, "Failed to open access log file\n");
            return EXIT_FAILURE;
        }
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %d\n", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
        fclose(fp);

        // Generate a new random code
        for (int i = 0; i < MAX_CODE_LENGTH; i++) {
            code[i] = rand() % 10;
        }
    } else {
        printf("Access denied\n");
    }

    // Clean up
    gpiod_line_close(&line_a);
    gpiod_line_close(&line_b);
    gpiod_chip_close(&chip);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Wait for SIGINT or SIGTERM
    waitpid(pid, NULL, 0);

    // Release resources on exit
    if (exit_on_signal) {
        gpiod_chip_close(&chip);
        gpiod_line_close(&line_a);
        gpiod_line_close(&line_b);
    }

    // Close any open file handles
    if (fp) fclose(fp);

    return EXIT_SUCCESS;
}
```

This code initializes libgpiod, sets up GPIO17 and GPIO27 as outputs, generates a random 6-digit code, prompts the user for input, validates the input, checks the code, and logs successful entries to 'access_log.txt'. It handles errors, cleans up resources on exit, and exits cleanly on signal handling. Compile with `gcc -Wall -o door_access door_access.c -lgpiod`.

