#include <errno.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define MAX_READ_ATTEMPTS 10
#define LOG_FILE "light_log.txt"

int open_i2c_bus(const char *bus_name) {
    int fd = open(bus_name, O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t cmd, size_t len) {
    uint8_t buf[2];
    buf[0] = cmd;
    buf[1] = 0;
    return write(fd, buf, 2);
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    return read(fd, buf, len);
}

int bh1750_read_lux(int fd) {
    uint8_t command[2] = {0x21, 0x00}; // One-Time High-Resolution Mode 2 command
    int ret = i2c_write(fd, command[0], 1);
    if (ret < 0) {
        perror("Failed to write command");
        return -1;
    }

    ret = i2c_write(fd, command[1], 1);
    if (ret < 0) {
        perror("Failed to write command");
        return -1;
    }

    ret = ioctl(fd, I2C_SM_SET_ADDRESS, (unsigned long)I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    ret = ioctl(fd, I2C_SM_SET_BAUDRATE, 100000); // 100kHz
    if (ret < 0) {
        perror("Failed to set I2C baud rate");
        return -1;
    }

    ret = ioctl(fd, I2C_SM_ENABLE);
    if (ret < 0) {
        perror("Failed to enable I2C master");
        return -1;
    }

    ret = ioctl(fd, I2C_SM_WAIT_UNTIL_DONE);
    if (ret < 0) {
        perror("Failed to wait for I2C transfer to complete");
        return -1;
    }

    ret = ioctl(fd, I2C_MASTER_SEND, (unsigned long)command[0]);
    if (ret < 0) {
        perror("Failed to send command");
        return -1;
    }

    ret = ioctl(fd, I2C_MASTER_SEND, (unsigned long)command[1]);
    if (ret < 0) {
        perror("Failed to send command");
        return -1;
    }

    ret = ioctl(fd, I2C_MASTER_READ, (unsigned long)buf);
    if (ret < 0) {
        perror("Failed to read data");
        return -1;
    }

    uint16_t raw_value = (buf[0] << 8) | buf[1];

    ret = ioctl(fd, I2C_MASTER_READ, (unsigned long)&raw_value);
    if (ret < 0) {
        perror("Failed to read raw value");
        return -1;
    }

    uint16_t lux = (raw_value * 5) / 6;

    ret = ioctl(fd, I2C_MASTER_READ, (unsigned long)&lux);
    if (ret < 0) {
        perror("Failed to read lux value");
        return -1;
    }

    close(fd);
    return lux;
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    struct itimerspec timers;
    time_t last_read = 0;

    i2c_fd = open_i2c_bus(NULL);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    timers.timers_sec = 5;
    timers.timers_nsec = 0;

    while (1) {
        time(NULL) & last_read;
        if (last_read > timers.timers_sec) {
            int lux = bh1750_read_lux(i2c_fd);
            if (lux == -1) {
                perror("Failed to read lux value");
                continue;
            }

            FILE *file = fopen(LOG_FILE, "a");
            if (!file) {
                perror("Failed to open log file");
                continue;
            }

            time_t now = time(NULL);
            fprintf(file, "Timestamp: %ld, Lux: %d\n", now, lux);
            fclose(file);
        }
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

