#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_ADDR 0x5A
#define PWM_GPIO 18
#define LOG_FILE "frequency_log.txt"
#define PORT 12345
#define SECRET "MySecretKey"
#define SAMPLE_INTERVAL 20
#define PLAY_DURATION 5000

void theremin_tone(int frequency) {
    int duty_cycle = 127;
    int period = 1000000 / frequency;
    int duration = period / SAMPLE_INTERVAL;
    for (int i = 0; i < duration; i++) {
        pigpio_set_PWM_dutycycle(PWM_GPIO, duty_cycle);
        usleep(period * SAMPLE_INTERVAL);
        pigpio_set_PWM_dutycycle(PWM_GPIO, 0);
        usleep(SAMPLE_INTERVAL);
    }
}

int main(int argc, char *argv[]) {
    int i2c_fd, pwm_fd, server_fd;
    struct sockaddr_in addr;
    int addrlen = sizeof(addr);

    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    if (i2c_fd = i2c_open(I2C_ADDR, 0) < 0) {
        perror("i2c_open");
        return 1;
    }

    if (pigpio_set_mode(PWM_GPIO, PIGPIO_OUTPUT) < 0) {
        perror("pigpio_set_mode");
        return 1;
    }

    if (pigpio_write(PWM_GPIO, 0) < 0) {
        perror("pigpio_write");
        return 1;
    }

    if (pigpio_set_PWM_range(PWM_GPIO, 0, 127) < 0) {
        perror("pigpio_set_PWM_range");
        return 1;
    }

    if (pigpio_set_PWM_range(PWM_GPIO, 128, 255) < 0) {
        perror("pigpio_set_PWM_range");
        return 1;
    }

    if (pigpio_write(PWM_GPIO, 128) < 0) {
        perror("pigpio_write");
        return 1;
    }

    if (pigpio_write(PWM_GPIO, 0) < 0) {
        perror("pigpio_write");
        return 1;
    }

    if (pigpio_close(PWM_GPIO) < 0) {
        perror("pigpio_close");
        return 1;
    }

    if (pigpio_init_sysfs() < 0) {
        perror("pigpio_init_sysfs");
        return 1;
    }

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket");
        return 1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(PORT);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        return 1;
    }

    if (listen(server_fd, 5) < 0) {
        perror("listen");
        return 1;
    }

    if ((client_fd = accept(server_fd, (struct sockaddr *)&addr, (socklen_t*)&addrlen)) < 0) {
        perror("accept");
        return 1;
    }

    char buffer[1024];
    int secret_len = 0;
    int frequency_len = 0;

    while (1) {
        int bytes_read = read(client_fd, buffer, 1024);
        if (bytes_read == 0) {
            break;
        }

        if (buffer[0] == 'M' && buffer[1] == 'O' && buffer[2] == 'T' && buffer[3] == 'I' &&
            buffer[4] == 'O' && buffer[5] == 'N' && buffer[6] == 'D' && buffer[7] == ':' &&
            strncmp(buffer + 8, SECRET, strlen(SECRET)) == 0) {

            for (int i = 8; i < bytes_read; i++) {
                if (buffer[i] == ' ') {
                    theremin_tone(frequency_len);
                    frequency_len = 0;
                } else {
                    frequency_len = frequency_len * 10 + (buffer[i] - '0');
                }
            }

            if (frequency_len > 0) {
                theremin_tone(frequency_len);
            }
        }
    }

    close(client_fd);
    close(server_fd);
    close(i2c_fd);

    pigpio_terminate();
    return 0;
}

