This code sets up a Raspberry Pi 4 Model B as a TCP server using pigpio for I2C and hardware PWM on GPIO18 to create a theremin-like effect using an MPR121 capacitive touch sensor. The server listens for incoming messages starting with 'MOTION_DETECTED:' and containing 'MySecretKey'. When such a message is received, it plays tones based on capacitive touch readings for 5 seconds. The maximum electrode filtered data value is mapped to a frequency in the range 220-880 Hz using a logarithmic scale, sampling touch values every 20 ms. The frequencies are logged to 'frequency_log.txt'. The program handles errors for pigpio initialization, I2C open/read, and socket/bind/listen/accept, and cleans up resources on SIGINT/SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define SDA1 "/dev/i2c-1"
#define GPIO17 17
#define PWM_CHANNEL 0

#define MAGNETOMETER_ADDRESS 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define SAMPLE_INTERVAL_MS 100

static int magnetometer_fd;
static gpiod_t pwm_channel;

static int magnetometer_read_data(void) {
    int ret;
    char buffer[6];
    ret = ioctl(magnetometer_fd, I2C_SLAVE, MAGNETOMETER_ADDRESS);
    if (ret < 0) {
        perror("ioctl I2C_SLAVE");
        return ret;
    }

    ret = read(magnetometer_fd, buffer, 6);
    if (ret != 6) {
        perror("read from I2C");
        return ret;
    }

    // Process the 6 bytes of data (X, Y, Z, X, Y, Z)
    // For simplicity, we'll just return the number of bytes read
    return ret;
}

static void magnetometer_init(void) {
    magnetometer_fd = open(SDA1, O_RDWR);
    if (magnetometer_fd < 0) {
        perror("open i2c-1");
        exit(EXIT_FAILURE);
    }

    // Initialize the magnetometer
    ret = ioctl(magnetometer_fd, I2C_SM_SET_ADDRESS, MAGNETOMETER_ADDRESS);
    if (ret < 0) {
        perror("ioctl I2C_SM_SET_ADDRESS");
        close(magnetometer_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(magnetometer_fd, I2C_MASTER_WRITE, CTRL_REG1_M);
    if (ret < 0) {
        perror("ioctl I2C_MASTER_WRITE");
        close(magnetometer_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(magnetometer_fd, I2C_MASTER_WRITE, 0x18);
    if (ret < 0) {
        perror("ioctl I2C_MASTER_WRITE");
        close(magnetometer_fd);
        exit(EXIT_FAILURE);
    }
}

static void magnetometer_read_data_and_pwm(void) {
    int data_bytes;
    float x, y, z, magnitude;

    data_bytes = magnetometer_read_data();
    if (data_bytes < 6) {
        fprintf(stderr, "Error reading from magnetometer\n");
        return;
    }

    // Extract X, Y, Z from the first 3 bytes
    float x_val = (float)data_bytes >> 16 & 0xFF;
    float y_val = (float)data_bytes >> 8 & 0xFF;
    float z_val = data_bytes & 0xFF;

    // Compute magnitude
    magnitude = sqrt(x_val * x_val + y_val * y_val + z_val * z_val);

    // Adjust PWM based on magnitude
    gpiod_set_value(pwm_channel, (int)(magnitude * 255 / 1000));
}

int main(void) {
    int ret;

    // Initialize GPIO and PWM
    ret = gpiod_add_pwm_output(PWM_CHANNEL, 0);
    if (ret < 0) {
        perror("gpiod_add_pwm_output");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_initial_value(PWM_CHANNEL, 0);
    if (ret < 0) {
        perror("gpiod_set_initial_value");
        exit(EXIT_FAILURE);
    }

    magnetometer_init();

    while (1) {
        magnetometer_read_data_and_pwm();
        usleep(SAMPLE_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    // Clean up resources on SIGINT/SIGTERM
    gpiod_set_initial_value(PWM_CHANNEL, 0);
    close(magnetometer_fd);
    gpiod_remove_pwm_output(PWM_CHANNEL);

    return 0;
}

