    // Process the 6 bytes of data (X, Y, Z, X, Y, Z)
    // For simplicity, we'll just return the number of bytes read
    return ret;
}

static void magnetometer_init(void) {
    magnetometer_fd = open(SDA1, O_RDWR);
    if (magnetometer_fd < 0) {
        perror("open i2c-1");
        exit(EXIT_FAILURE);
    }

    // Initialize the magnetometer
    ret = ioctl(magnetometer_fd, I2C_SM_SET_ADDRESS, MAGNETOMETER_ADDRESS);
    if (ret < 0) {
        perror("ioctl I2C_SM_SET_ADDRESS");
        close(magnetometer_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(magnetometer_fd, I2C_MASTER_WRITE, CTRL_REG1_M);
    if (ret < 0) {
        perror("ioctl I2C_MASTER_WRITE");
        close(magnetometer_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(magnetometer_fd, I2C_MASTER_WRITE, 0x18);
    if (ret < 0) {
        perror("ioctl I2C_MASTER_WRITE");
        close(magnetometer_fd);
        exit(EXIT_FAILURE);
    }
}

static void magnetometer_read_data_and_pwm(void) {
    int data_bytes;
    float x, y, z, magnitude;

    data_bytes = magnetometer_read_data();
    if (data_bytes < 6) {
        fprintf(stderr, "Error reading from magnetometer\n");
        return;
    }

    // Extract X, Y, Z from the first 3 bytes
    float x_val = (float)data_bytes >> 16 & 0xFF;
    float y_val = (float)data_bytes >> 8 & 0xFF;
    float z_val = data_bytes & 0xFF;

    // Compute magnitude
    magnitude = sqrt(x_val * x_val + y_val * y_val + z_val * z_val);

    // Adjust PWM based on magnitude
    gpiod_set_value(pwm_channel, (int)(magnitude * 255 / 1000));
}

int main(void) {
    int ret;

    // Initialize GPIO and PWM
    ret = gpiod_add_pwm_output(PWM_CHANNEL, 0);
    if (ret < 0) {
        perror("gpiod_add_pwm_output");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_initial_value(PWM_CHANNEL, 0);
    if (ret < 0) {
        perror("gpiod_set_initial_value");
        exit(EXIT_FAILURE);
    }

    magnetometer_init();

    while (1) {
        magnetometer_read_data_and_pwm();
        usleep(SAMPLE_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    // Clean up resources on SIGINT/SIGTERM
    gpiod_set_initial_value(PWM_CHANNEL, 0);
    close(magnetometer_fd);
    gpiod_remove_pwm_output(PWM_CHANNEL);

    return 0;
}
