#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define SAMPLE_WINDOW 100
#define CORRECTION_INTERVAL 500

#define HMC5883L_CONFIG_REG_A 0x70
#define HMC5883L_CONFIG_REG_B 0x20
#define HMC5883L_MODE_REG 0x00
#define HMC5883L_X_OUT_H 0x2A
#define HMC5883L_Y_OUT_H 0x2C
#define HMC5883L_Z_OUT_H 0x2E

#define HARD_IRON_OFFSET_WINDOW_SIZE SAMPLE_WINDOW

void handle_interrupt(int sig) {
    pigpio_stop();
    printf("Program terminated by signal %d\n", sig);
    exit(0);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(I2C_BUS);
    if (pi == NULL) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    if (pi_init(pi, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        pigpio_stop(pi);
        return 1;
    }

    // Configure HMC5883L
    pi_write(pi, HMC5883L_CONFIG_REG_A, 0x70);
    pi_write(pi, HMC5883L_CONFIG_REG_B, 0x20);
    pi_write(pi, HMC5883L_MODE_REG, 0x00);

    // Initialize offset array
    float offsets_x[HARD_IRON_OFFSET_WINDOW_SIZE] = {0.0};
    float offsets_y[HARD_IRON_OFFSET_WINDOW_SIZE] = {0.0};
    float offsets_z[HARD_IRON_OFFSET_WINDOW_SIZE] = {0.0};

    // Main loop
    while (1) {
        // Read raw magnetometer data
        int raw_x = pi_read(pi, HMC5883L_X_OUT_H);
        int raw_y = pi_read(pi, HMC5883L_Y_OUT_H);
        int raw_z = pi_read(pi, HMC5883L_Z_OUT_H);

        // Update offsets
        for (int i = 0; i < HARD_IRON_OFFSET_WINDOW_SIZE; i++) {
            offsets_x[i] = (offsets_x[i - 1] * (i - 1) + raw_x) / i;
            offsets_y[i] = (offsets_y[i - 1] * (i - 1) + raw_y) / i;
            offsets_z[i] = (offsets_z[i - 1] * (i - 1) + raw_z) / i;
        }

        // Apply offsets
        float x_corrected = raw_x - offsets_x[0];
        float y_corrected = raw_y - offsets_y[0];
        float z_corrected = raw_z - offsets_z[0];

        // Print corrected values
        printf("X: %.2f, Y: %.2f, Z: %.2f\n", x_corrected, y_corrected, z_corrected);

        // Wait for correction interval
        usleep(CORRECTION_INTERVAL * 1000);
    }

    // Clean up and exit
    pigpio_stop(pi);
    return 0;
}

// Register signal handlers
signal(SIGINT, handle_interrupt);
signal(SIGTERM, handle_interrupt);

