#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/epoll.h>
#include <sys/poll.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define LSM303D_ADDR 0x1D
#define INT1_GPIO 23
#define BUFFER_SIZE 64
#define POLL_INTERVAL 10000  // 10 ms

#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x21
#define INT1_CFG 0x22
#define OUT_X_L_A 0x28

#define BUFFER_INDEX 0

int i2c_fd;
int int_enabled = 1;
int buffer_index = 0;
struct timeval tv;

void int_handler(int signum) {
    int_enabled = 0;
    printf("Interrupt detected, printing last 10 samples...\n");
    print_samples();
}

void init_i2c() {
    int file;
    char args[10];

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    args[0] = 'z';
    args[1] = 'a';
    args[2] = 'w';
    args[3] = 'i';
    args[4] = '2';
    args[5] = 'c';

    if (ioctl(file, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_BM_READ, &lsm303d_read_reg) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (lsm303d_read_reg[WHO_AM_I] != 0x49) {
        fprintf(stderr, "LSM303D is not recognized.\n");
        exit(EXIT_FAILURE);
    }

    lsm303d_read_reg[CTRL_REG1] = 0x57;  // 50 Hz ODR, all axes enabled
    lsm303d_read_reg[CTRL_REG4] = 0x00;  // Full-scale +-2g
    lsm303d_read_reg[INT1_CFG] = 0x2A;   // Threshold interrupt, 2000 mg
    lsm303d_read_reg[0x2B] = 0x7D;        // Threshold value 2000 mg

    if (ioctl(file, I2C_MEM_READ, LSM303D_ADDR | OUT_X_L_A | 0x80) < 0) {
        fprintf(stderr, "Failed to read OUT_X_L_A register: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void read_accel_data() {
    struct i2c_msg msg;
    int bytes_read;

    msg.len = 6;
    msg.addr = i2c_fd;
    msg.flags = I2C_M_BRIGHT;
    memcpy(msg.buf, &lsm303d_read_reg[OUT_X_L_A], 6);
    bytes_read = ioctl(i2c_fd, I2C_MSG_READ, &msg);

    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read OUT_X_L_A register: %s\n", strerror(errno));
        return;
    }

    lsm303d_read_reg[BUFFER_INDEX] = msg.buf[0];
    lsm303d_read_reg[BUFFER_INDEX + 1] = msg.buf[1];
    lsm303d_read_reg[BUFFER_INDEX + 2] = msg.buf[2];
    lsm303d_read_reg[BUFFER_INDEX + 3] = msg.buf[3];
    lsm303d_read_reg[BUFFER_INDEX + 4] = msg.buf[4];
    lsm303d_read_reg[BUFFER_INDEX + 5] = msg.buf[5];

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void print_samples() {
    int i;
    printf("Last 10 samples:\n");
    for (i = 0; i < 10; i++) {
        printf("%d ", lsm303d_read_reg[BUFFER_INDEX - i]);
    }
    printf("\n");
}

int main() {
    init_i2c();

    gpiod_t gpiod_int_pin;
    int ret = gpiod_request_output_pin(&gpiod_int_pin, INT1_GPIO);
    if (ret < 0) {
        fprintf(stderr, "Failed to request INT1 GPIO pin: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, int_handler);

    epoll_event event;
    event.events = EPOLLIN;
    event.data.fd = i2c_fd;

    while (1) {
        ret = poll(&event, 1, POLL_INTERVAL);
        if (ret == -1) {
            perror("poll");
            exit(EXIT_FAILURE);
        }

        if (event.data.fd == i2c_fd && ret == EPOLLIN) {
            read_accel_data();
        }

        if (int_enabled) {
            // No need to check here, as the interrupt handler will handle it.
        }
    }

    close(i2c_fd);
    gpiod_release_output_pin(&gpiod_int_pin);

    return 0;
}

