#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_17 17
#define GPIO_27 27

static int gpiochip_17 = -1;
static int gpiochip_27 = -1;

void solenoid_init(void) {
    int ret;

    // Initialize GPIO chip for GPIO17
    gpiochip_17 = gpiod_chip_create_by_number(1);
    if (gpiochip_17 < 0) {
        perror("Failed to create GPIO chip for GPIO17");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_configure_pin(gpiochip_17, 17, GPIOD_OUTPUT);
    if (ret < 0) {
        perror("Failed to configure GPIO17 as output");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO chip for GPIO27
    gpiochip_27 = gpiod_chip_create_by_number(1);
    if (gpiochip_27 < 0) {
        perror("Failed to create GPIO chip for GPIO27");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_configure_pin(gpiochip_27, 27, GPIOD_OUTPUT);
    if (ret < 0) {
        perror("Failed to configure GPIO27 as output");
        exit(EXIT_FAILURE);
    }
}

void solenoid_deinit(void) {
    if (gpiochip_17 != -1) {
        gpiod_chip_destroy(gpiochip_17);
        gpiochip_17 = -1;
    }

    if (gpiochip_27 != -1) {
        gpiod_chip_destroy(gpiochip_27);
        gpiochip_27 = -1;
    }
}

void solenoid_control(int pin, int state) {
    int ret;

    if (state == -1) {
        // De-energize
        ret = gpiod_pin_set_dir(pin, GPIOD_OUTPUT);
        if (ret < 0) {
            perror("Failed to set GPIO pin direction");
            exit(EXIT_FAILURE);
        }
        ret = gpiod_pin_set_level(pin, GPIOD_LEVEL_LOW);
        if (ret < 0) {
            perror("Failed to set GPIO pin level");
            exit(EXIT_FAILURE);
        }
    } else {
        // Energize
        ret = gpiod_pin_set_dir(pin, GPIOD_OUTPUT);
        if (ret < 0) {
            perror("Failed to set GPIO pin direction");
            exit(EXIT_FAILURE);
        }
        ret = gpiod_pin_set_level(pin, GPIOD_LEVEL_HIGH);
        if (ret < 0) {
            perror("Failed to set GPIO pin level");
            exit(EXIT_FAILURE);
        }
    }
}

void solenoid_sequence(void) {
    int solenoid1_pin = gpiochip_17;
    int solenoid2_pin = gpiochip_27;

    while (1) {
        // Energize solenoid 1 for 500 ms
        solenoid_control(solenoid1_pin, 1);
        usleep(500000); // 500 ms

        // De-energize solenoid 1
        solenoid_control(solenoid1_pin, -1);

        // Energize solenoid 2 for 500 ms
        solenoid_control(solenoid2_pin, 1);
        usleep(500000); // 500 ms

        // De-energize solenoid 2
        solenoid_control(solenoid2_pin, -1);

        // Wait for a short interval before the next cycle
        usleep(1000000); // 1 ms
    }
}

void signal_handler(int signum) {
    solenoid_deinit();
    printf("Exiting cleanly...\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    solenoid_init();
    solenoid_sequence();
    return 0;
}

