#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_LOCK1 17
#define GPIO_LOCK2 27
#define UART_PRIMARY 14
#define UART_SECONDARY 15
#define BAUD_RATE 9600
#define FRAMING 8
#define TIMEOUT 5000
#define EXPECTED_CODE "123456"

void read_serial(int port, char *buffer, int max_length) {
    struct termios options;
    tcgetattr(port, &options);
    options.c_cflag &= ~(CSIZE | CS8);
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    tcsetattr(port, TCSANOW, &options);

    char ch;
    int bytes_read = 0;
    while ((bytes_read = read(port, &ch, 1)) > 0) {
        if (ch == '\n') {
            buffer[bytes_read] = '\0';
            break;
        }
    }
    if (bytes_read == 0) {
        fprintf(stderr, "Timeout reading from UART\n");
        return;
    }

    tcsetattr(port, TCSANOW, &options);
}

int compare_strings(const char *str1, const char *str2) {
    return strcmp(str1, str2);
}

int main() {
    int gpio_lock1, gpio_lock2, serial_primary, serial_secondary;
    char code1[6], code2[6];

    gpio_lock1 = gpioInitialise();
    gpio_lock2 = gpioInitialise();
    if (gpio_lock1 < 0 || gpio_lock2 < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(gpio_lock1, GPIO_OUTPUT);
    gpioSetMode(gpio_lock2, GPIO_OUTPUT);
    gpioWrite(gpio_lock1, 0);
    gpioWrite(gpio_lock2, 0);

    serial_primary = open(UART_PRIMARY, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_primary < 0) {
        perror("Failed to open primary UART");
        return EXIT_FAILURE;
    }

    serial_secondary = open(UART_SECONDARY, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_secondary < 0) {
        perror("Failed to open secondary UART");
        return EXIT_FAILURE;
    }

    while (1) {
        read_serial(serial_primary, code1, 6);
        read_serial(serial_secondary, code2, 6);

        if (compare_strings(code1, EXPECTED_CODE) == 0 &&
            compare_strings(code2, EXPECTED_CODE) == 0) {
            gpioWrite(gpio_lock1, 1);
            gpioWrite(gpio_lock2, 1);
            usleep(2000000);
            gpioWrite(gpio_lock1, 0);
            gpioWrite(gpio_lock2, 0);
        } else {
            gpioWrite(gpio_lock1, 0);
            gpioWrite(gpio_lock2, 0);
        }
    }

    close(serial_primary);
    close(serial_secondary);
    gpioTerminate();

    return EXIT_SUCCESS;
}

