#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <libgpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define POLLING_INTERVAL 50
#define STRIKE_DURATION 1000
#define FAILSAFE_THRESHOLD 10000

int main(int argc, char *argv[]) {
    gpiod_chip_t chip;
    gpiod_line_t pir_line, relay_line;
    gpiod_line_direction_t line_direction;
    gpiod_line_request_attr_t request_attr;
    gpiod_line_request_result_t result;
    gpiod_line_value_t pir_value, relay_value;
    gpiod_line_get_value_result_t get_value_result;
    gpiod_line_set_value_result_t set_value_result;
    gpiod_error_t error;
    gpiod_chip_init_result_t chip_init_result;
    gpiod_line_t *pir_line_ptr, *relay_line_ptr;

    // Initialize libgpiod
    error = gpiod_chip_init(&chip, NULL, NULL);
    if (error != GPIOD_SUCCESS) {
        syslog(LOG_ERR, "Failed to initialize libgpiod chip");
        exit(EXIT_FAILURE);
    }

    pir_line_ptr = gpiod_line_request(chip, PIR_PIN, GPIOD_IN, &request_attr);
    if (pir_line_ptr == NULL) {
        syslog(LOG_ERR, "Failed to request PIR line");
        exit(EXIT_FAILURE);
    }

    relay_line_ptr = gpiod_line_request(chip, RELAY_PIN, GPIOD_OUT, &request_attr);
    if (relay_line_ptr == NULL) {
        syslog(LOG_ERR, "Failed to request relay line");
        exit(EXIT_FAILURE);
    }

    // Set PIR line direction to input
    line_direction = GPIOD_IN;
    error = gpiod_line_set_direction(pir_line_ptr, line_direction);
    if (error != GPIOD_SUCCESS) {
        syslog(LOG_ERR, "Failed to set PIR line direction");
        exit(EXIT_FAILURE);
    }

    // Set relay line direction to output
    line_direction = GPIOD_OUT;
    error = gpiod_line_set_direction(relay_line_ptr, line_direction);
    if (error != GPIOD_SUCCESS) {
        syslog(LOG_ERR, "Failed to set relay line direction");
        exit(EXIT_FAILURE);
    }

    // Start logging
    openlog("door_strike_controller", LOG_PID | LOG_PERR, LOG_DAEMON);

    while (1) {
        // Poll PIR sensor
        get_value_result = gpiod_line_get_value(pir_line_ptr);
        if (get_value_result.value != pir_value) {
            pir_value = get_value_result.value;
            if (pir_value) {
                // Motion detected, start strike
                relay_value = GPIOD_HIGH;
                error = gpiod_line_set_value(relay_line_ptr, relay_value);
                if (error != GPIOD_SUCCESS) {
                    syslog(LOG_ERR, "Failed to set relay value");
                }
                syslog(LOG_INFO, "Motion detected, energizing relay");
            } else {
                // PIR remains HIGH, potential malfunction
                relay_value = GPIOD_LOW;
                error = gpiod_line_set_value(relay_line_ptr, relay_value);
                if (error != GPIOD_SUCCESS) {
                    syslog(LOG_ERR, "Failed to set relay value");
                }
                syslog(LOG_WARNING, "Potential malfunction: PIR remains HIGH");
            }
        }

        // Poll PIR sensor every 50 ms
        usleep(POLLING_INTERVAL * 1000);

        // Check for strike duration
        if (get_value_result.value == pir_value) {
            // Strike duration elapsed, de-energize relay
            relay_value = GPIOD_LOW;
            error = gpiod_line_set_value(relay_line_ptr, relay_value);
            if (error != GPIOD_SUCCESS) {
                syslog(LOG_ERR, "Failed to set relay value");
            }
            syslog(LOG_INFO, "Strike duration elapsed, de-energizing relay");
        }

        // Check for failsafe trigger
        if (get_value_result.value == pir_value && pir_value == GPIOD_HIGH) {
            // Failsafe triggered, de-energize relay
            relay_value = GPIOD_LOW;
            error = gpiod_line_set_value(relay_line_ptr, relay_value);
            if (error != GPIOD_SUCCESS) {
                syslog(LOG_ERR, "Failed to set relay value");
            }
            syslog(LOG_INFO, "Failsafe triggered, de-energizing relay");
        }
    }

    // Clean shutdown
    error = gpiod_line_set_value(relay_line_ptr, GPIOD_LOW);
    if (error != GPIOD_SUCCESS) {
        syslog(LOG_ERR, "Failed to de-energize relay");
    }

    // Release GPIO lines
    gpiod_line_free(relay_line_ptr);
    gpiod_line_free(pir_line_ptr);

    // Close the chip
    error = gpiod_chip_destroy(chip);
    if (error != GPIOD_SUCCESS) {
        syslog(LOG_ERR, "Failed to close the libgpiod chip");
    }

    // Close syslog
    closelog();

    return 0;
}

