#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <syslog.h>
#include <pigpio.h>
#include <stdbool.h>

#define RELAY_PINS {4, 17, 27, 22}
#define PAUSE_TIME 60000  // 1 minute in milliseconds
#define ACTIVATION_TIME 300000  // 5 minutes in milliseconds
#define TIMER_INTERVAL 60000  // 60 seconds in milliseconds

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    syslog(LOG_INFO, format, args);
    va_end(args);
}

void log_relay_state_change(int pin, bool state) {
    log_message("Relay %d state changed: %s\n", pin, state ? "ON" : "OFF");
}

void setup_gpio() {
    if (pigpioInitialise() < 0) {
        log_message("Failed to initialise pigpio. Exiting.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        if (gpioInitialise(RELAY_PINS[i]) < 0) {
            log_message("Failed to initialise GPIO %d. Exiting.\n", RELAY_PINS[i]);
            pigpioTerminate();
            exit(EXIT_FAILURE);
        }
        gpioSetMode(RELAY_PINS[i], PIGPIO_OUTPUT);
        gpioWrite(RELAY_PINS[i], 1); // Set initial state to HIGH
    }

    if (gpioSetTimerFuncEx(0, timer_callback, NULL) < 0) {
        log_message("Failed to set timer function. Exiting.\n");
        pigpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void timer_callback(int timer_id) {
    volatile sig_atomic_t pause = 0;

    while (1) {
        if (pause) {
            log_relay_state_change(RELAY_PINS[0], 0);
            pause = 0;
            usleep(TIMER_INTERVAL * 1000000);
            continue;
        }

        for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
            if (i == 3) {
                pause = 1;
                log_relay_state_change(RELAY_PINS[i], 0);
                usleep(ACTIVATION_TIME * 1000000);
                pause = 0;
                log_relay_state_change(RELAY_PINS[i], 1);
            } else {
                log_relay_state_change(RELAY_PINS[i], 0);
                usleep(PAUSE_TIME * 1000000);
                log_relay_state_change(RELAY_PINS[i], 1);
            }
        }
    }
}

void cleanup() {
    pigpioTerminate();
    close(STDLIB_FILE);
    syslog(LOG_CLOSE, "Closing syslog");
}

int main(int argc, char *argv[]) {
    log_message("Starting irrigation system...\n");

    setup_gpio();

    sigset_t sigset;
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);

    if (sigprocmask(SIG_BLOCK, &sigset, NULL) < 0) {
        log_message("Failed to block signals. Exiting.\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        sleep(1);
    }
}

