#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/epoll.h>
#include <sys/timerfd.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_CONFIG 0x00
#define PWR_MGMT_1 0x00
#define ACCEL_RANGE_2G 0x00
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F

#define BUFFER_SIZE 100
#define TIMER_SECS 0.01

typedef struct {
    int fd;
    struct i2c_rdwr_ctx ctx;
    struct timer_fd timer;
    char buffer[BUFFER_SIZE];
    int head, tail;
    int size;
} mpu6050_context;

static int mpu6050_open(const char *path) {
    int fd = open(path, O_RDWR);
    if (fd < 0)
        return -1;

    struct i2c_rdwr_hdr hdr;
    memset(&hdr, 0, sizeof(hdr));
    hdr.cmd = S_I2C_RD;
    hdr.len = 6;
    hdr.data = (void *)ACCEL_XOUT_H;

    ioctl(fd, I2C_RD, &hdr);
    return fd;
}

static int mpu6050_ioctl(int fd, unsigned long cmd, void *buf) {
    switch (cmd) {
        case S_I2C_WR:
            struct i2c_rdwr_hdr *hdr = (struct i2c_rdwr_hdr *)buf;
            hdr->cmd = S_I2C_WR;
            hdr->len = 6;
            hdr->data = (void *)ACCEL_CONFIG | ACCEL_RANGE_2G;
            ioctl(fd, I2C_WR, hdr);
            break;
        case S_I2C_RD:
            struct i2c_rdwr_hdr *hdr = (struct i2c_rdwr_hdr *)buf;
            hdr->cmd = S_I2C_RD;
            hdr->len = 6;
            ioctl(fd, I2C_RD, hdr);
            break;
        default:
            return -1;
    }
    return 0;
}

static int mpu6050_read_data(int fd) {
    unsigned char data[6];
    ssize_t ret = read(fd, data, 6);
    if (ret != 6) {
        perror("Failed to read from MPU6050");
        return -1;
    }

    // Scale raw values to g
    data[0] = (data[0] << 8) / 16384.0;
    data[1] = (data[1] << 8) / 16384.0;
    data[2] = (data[2] << 8) / 16384.0;

    // Store in circular buffer
    int i = head;
    if (tail == head)
        tail = (tail + 1) % BUFFER_SIZE;
    buffer[tail] = data[0];
    buffer[tail + 1] = data[1];
    buffer[tail + 2] = data[2];
    head = (head + 1) % BUFFER_SIZE;
    size++;

    return 0;
}

static void mpu6050_close(int fd) {
    close(fd);
}

static void mpu6050_timer_cb(int signum, siginfo_t *info, void *context) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Clean up resources
        close(fd);
        mpu6050_close(fd);
        epoll_ctl(epoll_fd, EPOLL_CTL_DEL, fd, NULL);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    int fd, timer_fd;
    mpu6050_context context;

    fd = mpu6050_open(I2C_BUS);
    if (fd < 0) {
        perror("Failed to open MPU6050");
        return 1;
    }

    context.fd = fd;
    context.ctx.write_reg = mpu6050_ioctl;
    context.ctx.read_reg = mpu6050_read_data;
    context.head = 0;
    context.tail = 0;
    context.size = 0;

    // Initialize epoll for timer
    epoll_ctl(epoll_fd, EPOLL_CREATE, fd, &context.timer);

    // Start timer
    timer_settimer(&context.timer, TIMER_SECS * 1000000, 0);

    // Register signal handler
    signal(SIGINT, mpu6050_timer_cb);
    signal(SIGTERM, mpu6050_timer_cb);

    // Read data from MPU6050
    while (1) {
        int ret = context.ctx.read_reg(&context);
        if (ret < 0) {
            perror("Failed to read from MPU6050");
            break;
        }
    }

    // Clean up resources
    mpu6050_close(fd);
    epoll_ctl(epoll_fd, EPOLL_CTL_DEL, context.timer, NULL);
    close(epoll_fd);

    return 0;
}

