#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define RELAY_PINS {18, 23, 24, 25}
#define NUM_RELAYS 4
#define INTERVALS {2000000, 3000000, 5000000, 7000000} // 2, 3, 5, 7 seconds in nanoseconds

void signal_handler(int signum) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_output_t output = gpiod_output_new(RELAY_PINS[i]);
        if (output) {
            gpiod_output_free(output);
        }
    }
}

int main(int argc, char *argv[]) {
    struct timespec start, end;
    long long int intervals[NUM_RELAYS];

    if (signal(SIGINT, signal_handler) == SIG_IGN || signal(SIGTERM, signal_handler) == SIG_IGN) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    gpiod_init();

    for (int i = 0; i < NUM_RELAYS; i++) {
        intervals[i] = INTERVALS[i];
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_output_t output = gpiod_output_new(RELAY_PINS[i]);
        if (!output) {
            perror("Failed to create GPIO output");
            return EXIT_FAILURE;
        }

        gpiod_output_enable(output, GPIOD_OUTPUT_ENABLE_ON);
    }

    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_output_t output = gpiod_output_get(RELAY_PINS[i]);
            if (!output) {
                perror("Failed to get GPIO output");
                return EXIT_FAILURE;
            }

            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long long int elapsed = (now.tv_sec - start.tv_sec) * 1000000000 + (now.tv_nsec - start.tv_nsec);

            if (elapsed >= intervals[i]) {
                gpiod_output_toggle(output);
                printf("Relay %d toggled after %lld ns\n", RELAY_PINS[i], intervals[i]);
            }
        }

        usleep((intervals[0] / 1000000)); // Convert nanoseconds to microseconds
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_output_t output = gpiod_output_get(RELAY_PINS[i]);
        if (!output) {
            perror("Failed to get GPIO output");
            return EXIT_FAILURE;
        }

        gpiod_output_disable(output, GPIOD_OUTPUT_DISABLE_OFF);
    }

    gpiod_cleanup();

    return EXIT_SUCCESS;
}

