#define RELAY_PIN 27
#define SENSOR_PIN 17
#define THRESHOLD_LEVEL 100
#define DEBOUNCE_TIME 500
#define LOG_FILE "alarm_log.txt"
#define POLL_INTERVAL 100

void log_event(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s", message);
    fclose(file);
}

void signal_handler(int signum) {
    log_event("Received SIGINT or SIGTERM, shutting down...");
    pigpio_stop();
    exit(0);
}

int main() {
    pigpio_initialize();

    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_strerror());
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pigpio_set_mode(RELAY_PIN, PIGIO_OUTPUT);
    pigpio_set_deadtime(RELAY_PIN, 10); // Debounce time

    while (1) {
        int sensor_state = pigpio_get_digital_in(SENSOR_PIN);

        if (sensor_state > THRESHOLD_LEVEL) {
            log_event("Sound detected, activating alarm...");
            pigpio_write(RELAY_PIN, 1);
            usleep(300000); // 3 seconds
            pigpio_write(RELAY_PIN, 0);
            log_event("Alarm deactivated.\n");
        }

        // Debounce mechanism
        if (pigpio_get_digital_in(RELAY_PIN) == 1) {
            usleep(DEBOUNCE_TIME);
        }
    }

    pigpio_stop();
    fclose(LOG_FILE);
    return EXIT_SUCCESS;
}

