#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define SERIAL_PORT "/dev/serial0"
#define BAUD_RATE 9600
#define TXD_PIN 14
#define RXD_PIN 15
#define COMMAND_SIZE 9
#define CHECKSUM_OFFSET 7
#define CO2_OFFSET 16
#define LOG_INTERVAL 5000 // 5 seconds
#define LOG_FILE "co2_log.json"
#define ERROR_LOG "co2_error.log"

int main(int argc, char *argv[]) {
    int serfd;
    struct timeval tv;
    pid_t pid;
    char command[COMMAND_SIZE] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char response[COMMAND_SIZE];
    unsigned int checksum, response_sum = 0;
    int pigpio_error, serial_error, file_error;
    struct timespec ts;

    pigpioInit();

    // Open serial port
    serfd = serOpen(SERIAL_PORT, BAUD_RATE);
    if (serfd < 0) {
        fprintf(stderr, "Failed to open serial port: %s\n", strerror(errno));
        return 1;
    }

    // Send read command
    if (serWrite(serfd, command, COMMAND_SIZE) != COMMAND_SIZE) {
        fprintf(stderr, "Failed to write command to serial port\n");
        return 1;
    }

    // Wait for response
    ts.tv_sec = 0;
    ts.tv_usec = 0;
    while (serDataAvailable(serfd) == 0) {
        usleep(10000); // Wait for 10 ms
    }

    // Read response
    if (serRead(serfd, response, COMMAND_SIZE) != COMMAND_SIZE) {
        fprintf(stderr, "Failed to read response from serial port\n");
        return 1;
    }

    // Validate checksum
    checksum = 0;
    for (int i = 0; i < 7; i++) {
        checksum += response[i];
    }
    checksum = ~checksum + 1;
    if (checksum != response[7]) {
        fprintf(stderr, "Checksum mismatch, skipping reading\n");
        return 1;
    }

    // Extract CO2 value
    int ppm = (response[2] << 8) | response[3];

    // Log to file and stdout
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp[8];
    sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1,
            local_time->tm_mday, local_time->tm_hour, local_time->tm_min, local_time->tm_sec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    fprintf(log_file, "{\"timestamp\": \"%s\", \"ppm\": %d, \"error\": false}\n", timestamp, ppm);
    fclose(log_file);

    // Print to stdout
    printf("%s", timestamp);
    printf(",%d\n", ppm);

    // Flush stdout
    fflush(stdout);

    // Log errors
    if (pigpio_error) {
        fprintf(stderr, "Pigpio error: %s\n", pi_strerror(pigpio_error));
        fprintf(ERROR_LOG, "%s", ctime(NULL));
    }

    if (serial_error) {
        fprintf(stderr, "Serial error: %s\n", strerror(serial_error));
        fprintf(ERROR_LOG, "%s", ctime(NULL));
    }

    if (file_error) {
        fprintf(stderr, "File error: %s\n", strerror(file_error));
        fprintf(ERROR_LOG, "%s", ctime(NULL));
    }

    // Exit on SIGINT or SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_IGN || signal(SIGTERM, signal_handler) == SIG_IGN) {
        fprintf(stderr, "Signal handler not set\n");
        return 1;
    }

    // Clean up
    serClose(serfd);
    pigpioTerminate();

    return 0;

signal_handler:
{
    fprintf(stderr, "Received signal, cleaning up and exiting...\n");
    close_files_and_pi();
    return 1;
}

