#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 100
#define TARGET_HEADING 90.0
#define X_OFFSET 100
#define Y_OFFSET -50

typedef struct {
    int headings[BUFFER_SIZE];
    int head_index = 0;
} HeadingBuffer;

HeadingBuffer buffer;

void i2c_init() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("i2c_ioctl");
        exit(EXIT_FAILURE);
    }
}

void i2c_write_register_burst(int file, int reg, unsigned char *data, int len) {
    if (len > 6) {
        fprintf(stderr, "Error: Burst write too long\n");
        exit(EXIT_FAILURE);
    }
    write(file, &reg, 1);
    for (int i = 0; i < len; i++) {
        write(file, data + i, 1);
    }
}

void i2c_read_register_burst(int file, int reg, unsigned char *data, int len) {
    if (len > 6) {
        fprintf(stderr, "Error: Burst read too long\n");
        exit(EXIT_FAILURE);
    }
    read(file, &reg, 1);
    for (int i = 0; i < len; i++) {
        data[i] = read(file, NULL, 1);
    }
}

void configure_hmc5883l() {
    unsigned char config_a = 0x70;
    unsigned char config_b = 0x20;
    unsigned char mode = 0x00;

    i2c_write_register_burst(1, 0x00, &config_a, 1);
    i2c_write_register_burst(1, 0x01, &config_b, 1);
    i2c_write_register_burst(1, 0x02, &mode, 1);
}

void read_magnetometer_data() {
    unsigned char data[6];
    i2c_read_register_burst(1, 0x03, data, 6);

    // Apply hard-iron distortion
    data[0] -= X_OFFSET;
    data[2] += Y_OFFSET;

    // Convert to heading (rad)
    float heading_rad = (data[0] << 8) | data[1];
    heading_rad += (data[2] << 16) / 1000.0f;

    // Convert to heading (deg)
    float heading_deg = heading_rad * 180.0f / M_PI;

    // Check if heading deviates more than 10 degrees from target
    if (fabs(heading_deg - TARGET_HEADING) > 10.0f) {
        gpioSetDirection(17, PIGO_OUTPUT);
        gpioWrite(17, HIGH);
    } else {
        gpioSetDirection(17, PIGO_INPUT);
        gpioWrite(17, LOW);
    }

    // Log the compensated heading
    buffer.headings[buffer.head_index] = (int)(heading_deg * 100);
    buffer.head_index = (buffer.head_index + 1) % BUFFER_SIZE;
}

int main() {
    i2c_init();

    while (1) {
        read_magnetometer_data();
        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
    }

    return 0;
}

