#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define RELAY_GPIO17 17
#define RELAY_GPIO27 27
#define RELAY_GPIO22 22
#define BH1750_ADDR 0x23
#define BH1750_REG_CONFIG 0x00
#define BH1750_REG_STATUS 0x10
#define BH1750_REG_LUX_DATA 0x12

#define RELAY_RED 1
#define RELAY_GREEN 2
#define RELAY_BLUE 4

int main(int argc, char *argv[]) {
    int relay_gpio17, relay_gpio27, relay_gpio22;
    int i2c_fd, lux_raw;
    float lux;
    struct i2c_client *client;
    struct i2c_msg msg;
    gpiod_context_t gpio_ctx;
    gpiod_button_t button;

    // Initialize GPIO
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        return EXIT_FAILURE;
    }

    relay_gpio17 = GPIO_SET_DIR(GPIO_OUTPUT_ACTIVE);
    relay_gpio27 = GPIO_SET_DIR(GPIO_OUTPUT_ACTIVE);
    relay_gpio22 = GPIO_SET_DIR(GPIO_OUTPUT_ACTIVE);

    if (gpiod_button_init(&gpio_ctx, RELAY_RED, 1) < 0) {
        perror("gpiod_button_init");
        return EXIT_FAILURE;
    }
    if (gpiod_button_init(&gpio_ctx, RELAY_GREEN, 1) < 0) {
        perror("gpiod_button_init");
        return EXIT_FAILURE;
    }
    if (gpiod_button_init(&gpio_ctx, RELAY_BLUE, 1) < 0) {
        perror("gpiod_button_init");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if ((i2c_fd = i2c_open(NULL, "i2c-1")) < 0) {
        perror("i2c_open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure BH1750
    msg.len = 1;
    msg.data = &BH1750_REG_CONFIG;
    if (i2c_mem_read(i2c_fd, &msg) < 0) {
        perror("i2c_mem_read");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }
    msg.data[0] = 0x10;
    if (i2c_mem_write(i2c_fd, &msg) < 0) {
        perror("i2c_mem_write");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wait for conversion
    usleep(120000);

    // Read lux value
    msg.len = 2;
    msg.data = &BH1750_REG_LUX_DATA;
    if (i2c_mem_read(i2c_fd, &msg) < 0) {
        perror("i2c_mem_read");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }
    lux_raw = msg.data[0] | (msg.data[1] << 8);

    // Convert lux to physical value
    lux = (float)lux_raw / 1.2;

    // Drive relays based on lux thresholds
    if (lux < 50.0) {
        gpiod_button_set(&gpio_ctx, RELAY_RED);
    } else if (lux >= 50.0 && lux <= 150.0) {
        gpiod_button_set(&gpio_ctx, RELAY_GREEN);
    } else if (lux >= 150.0 && lux <= 300.0) {
        gpiod_button_set(&gpio_ctx, RELAY_BLUE);
    } else {
        gpiod_button_set(&gpio_ctx, RELAY_RED);
        gpiod_button_set(&gpio_ctx, RELAY_GREEN);
        gpiod_button_set(&gpio_ctx, RELAY_BLUE);
    }

    // Log to file
    FILE *log_file = fopen("lighting_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp: %ld, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            (long)time(NULL), lux, gpiod_button_get(&gpio_ctx, RELAY_RED),
            gpiod_button_get(&gpio_ctx, RELAY_GREEN), gpiod_button_get(&gpio_ctx, RELAY_BLUE));
    fclose(log_file);

    // Sleep before next iteration
    usleep(1000000);

    // Clean up
    gpiod_button_del(&gpio_ctx, RELAY_RED);
    gpiod_button_del(&gpio_ctx, RELAY_GREEN);
    gpiod_button_del(&gpio_ctx, RELAY_BLUE);
    gpiod_context_destroy(&gpio_ctx);
    i2c_close(i2c_fd);

    return EXIT_SUCCESS;
}

