    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure BH1750
    msg.len = 1;
    msg.data = &BH1750_REG_CONFIG;
    if (i2c_mem_read(i2c_fd, &msg) < 0) {
        perror("i2c_mem_read");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }
    msg.data[0] = 0x10;
    if (i2c_mem_write(i2c_fd, &msg) < 0) {
        perror("i2c_mem_write");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wait for conversion
    usleep(120000);

    // Read lux value
    msg.len = 2;
    msg.data = &BH1750_REG_LUX_DATA;
    if (i2c_mem_read(i2c_fd, &msg) < 0) {
        perror("i2c_mem_read");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }
    lux_raw = msg.data[0] | (msg.data[1] << 8);

    // Convert lux to physical value
    lux = (float)lux_raw / 1.2;

    // Drive relays based on lux thresholds
    if (lux < 50.0) {
        gpiod_button_set(&gpio_ctx, RELAY_RED);
    } else if (lux >= 50.0 && lux <= 150.0) {
        gpiod_button_set(&gpio_ctx, RELAY_GREEN);
    } else if (lux >= 150.0 && lux <= 300.0) {
        gpiod_button_set(&gpio_ctx, RELAY_BLUE);
    } else {
        gpiod_button_set(&gpio_ctx, RELAY_RED);
        gpiod_button_set(&gpio_ctx, RELAY_GREEN);
        gpiod_button_set(&gpio_ctx, RELAY_BLUE);
    }

    // Log to file
    FILE *log_file = fopen("lighting_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp: %ld, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            (long)time(NULL), lux, gpiod_button_get(&gpio_ctx, RELAY_RED),
            gpiod_button_get(&gpio_ctx, RELAY_GREEN), gpiod_button_get(&gpio_ctx, RELAY_BLUE));
    fclose(log_file);

    // Sleep before next iteration
    usleep(1000000);

    // Clean up
    gpiod_button_del(&gpio_ctx, RELAY_RED);
    gpiod_button_del(&gpio_ctx, RELAY_GREEN);
    gpiod_button_del(&gpio_ctx, RELAY_BLUE);
    gpiod_context_destroy(&gpio_ctx);
    i2c_close(i2c_fd);

    return EXIT_SUCCESS;
}
