#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define STEP_DELAY 2000  // 2 ms
#define STEPS_PER_QUARTER_TURN 512
#define GPIO_IN1 17
#define GPIO_IN2 18
#define GPIO_IN3 27
#define GPIO_IN4 22
#define BUTTON_LOCK 24
#define BUTTON_UNLOCK 23

int main() {
    int ret;
    int gpio_map[4];
    int motor_coils[2];

    // Initialize pigpio
    ret = piGPIOinit();
    if (ret != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", piGPIOgeterror());
        exit(EXIT_FAILURE);
    }

    // Map GPIO pins
    gpio_map[0] = GPIO_IN1;
    gpio_map[1] = GPIO_IN2;
    gpio_map[2] = GPIO_IN3;
    gpio_map[3] = GPIO_IN4;

    motor_coils[0] = gpio_map[0];
    motor_coils[1] = gpio_map[1];

    // Configure GPIO pins as outputs
    if (piGPIOsetmode(motor_coils[0], PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", motor_coils[0]);
        ret = -1;
        goto exit_with_error;
    }
    if (piGPIOsetmode(motor_coils[1], PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", motor_coils[1]);
        ret = -1;
        goto exit_with_error;
    }

    // Configure GPIO pins as inputs with pull-up
    if (piGPIOsetpullup(gpio_map[2]) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input with pull-up\n", gpio_map[2]);
        ret = -1;
        goto exit_with_error;
    }
    if (piGPIOsetpullup(gpio_map[3]) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input with pull-up\n", gpio_map[3]);
        ret = -1;
        goto exit_with_error;
    }

    // Full-step sequence
    void step_motor(int direction) {
        int coil1 = motor_coils[direction];
        int coil2 = motor_coils[1 - direction];

        piGPIOoutput(coil1, 1);
        piGPIOoutput(coil2, 1);

        // L293D IN1, IN2 for clockwise
        if (direction == 0) {
            piGPIOoutput(gpio_map[0], 0);
            piGPIOoutput(gpio_map[1], 1);
        }
        // L293D IN3, IN4 for counter-clockwise
        else {
            piGPIOoutput(gpio_map[0], 1);
            piGPIOoutput(gpio_map[1], 0);
        }

        usleep(STEP_DELAY * 1000 / 2); // Half-step delay
    }

    // Lock action
    void lock_door() {
        step_motor(0);
        for (int i = 0; i < STEPS_PER_QUARTER_TURN; i++) {
            step_motor(0);
        }
        piGPIOoutput(motor_coils[0], 0);
        piGPIOoutput(motor_coils[1], 0);
        printf("Door locked\n");
    }

    // Unlock action
    void unlock_door() {
        step_motor(1);
        for (int i = 0; i < STEPS_PER_QUARTER_TURN; i++) {
            step_motor(1);
        }
        piGPIOoutput(motor_coils[0], 0);
        piGPIOoutput(motor_coils[1], 0);
        printf("Door unlocked\n");
    }

    // Handle button press
    void handle_button_press(int gpio) {
        if (piGPIOget(gpio) == -1) {
            return;
        }
        if (piGPIOgetpull(gpio) == 0) {
            if (gpio == BUTTON_LOCK) {
                unlock_door();
            } else if (gpio == BUTTON_UNLOCK) {
                lock_door();
            }
        }
    }

    // Signal handler for SIGINT and SIGTERM
    void signal_handler(int signum) {
        printf("Exiting...\n");
        lock_door();
        piGPIOexit();
        exit(signum == SIGINT || signum == SIGTERM ? 0 : EXIT_FAILURE);
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        usleep(100000); // Check buttons every second
    }

exit_with_error:
    piGPIOexit();
    return ret;
}

