#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define BUZZER_GPIO 18
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 30.0
#define FREQ_MIN 200.0
#define FREQ_MAX 2000.0
#define MEASUREMENT_GAP_MS 60000
#define SAMPLE_RATE_HZ 50.0
#define SAMPLE_RATE_US 50000000

void sigint_handler(int signum) {
    pigpio_stop();
    printf("Program received SIGINT, silencing buzzer and exiting.\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(1);
    if (pi == -1) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(TRIGGER_GPIO, PIGO_OUTPUT);
    gpioSetMode(ECHO_GPIO, PIGO_INPUT);
    gpioSetMode(BUZZER_GPIO, PIGO_OUTPUT);

    if (pi == -1) {
        perror("Failed to set GPIO modes");
        pigpio_stop();
        exit(EXIT_FAILURE);
    }

    gpioWrite(TRIGGER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        int echo_time = gpioTick();
        int distance = 0;
        if (gpioRead(ECHO_GPIO) == 0) {
            distance = (echo_time * 1000000UL / 2UL) / 2UL;
            if (distance < MIN_DISTANCE) {
                distance = MIN_DISTANCE;
            }
            if (distance > MAX_DISTANCE) {
                distance = MAX_DISTANCE;
            }
        }

        double freq = FREQ_MIN + (distance * (FREQ_MAX - FREQ_MIN) / (MAX_DISTANCE - MIN_DISTANCE));
        freq = fmin(fmax(freq, FREQ_MIN), FREQ_MAX);

        int pulse_width = (int)(SAMPLE_RATE_US / freq);
        gpioPulse(BUZZER_GPIO, 0, pulse_width);

        usleep(SAMPLE_RATE_US / SAMPLE_RATE_HZ);

        if (gpioRead(ECHO_GPIO) == 0) {
            printf("Distance: %.1f cm, Frequency: %.1f Hz\n", distance, freq);
        }

        usleep(MEASUREMENT_GAP_MS / 1000);
    }

    pigpio_stop();
    return 0;
}

