#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define PWM_FREQUENCY 1000
#define LED_COUNT 3

void signal_handler(int signum) {
    gpioOutput(RED_PIN, 0);
    gpioOutput(GREEN_PIN, 0);
    gpioOutput(BLUE_PIN, 0);
    pigpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(1);
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    for (int i = 0; i < LED_COUNT; i++) {
        gpioWrite(RED_PIN, 0);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN, 0);
    }

    // Simulate proximity value (a simple sine wave for demonstration)
    double proximity = 0.5 * sin(1000.0 * 2.0 * M_PI * 0.01 * (time(NULL) % 1.0));

    // Map proximity to RGB values (0.0 to 1.0)
    int r = (int)(proximity * 255);
    int g = (int)((1.0 - proximity) * 255);
    int b = 0;

    // Set PWM duty cycles
    gpioSetPWM(RED_PIN, 0, r);
    gpioSetPWM(GREEN_PIN, 0, g);
    gpioSetPWM(BLUE_PIN, 0, b);

    // Handle SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    while (1) {
        usleep(100000); // Sleep for 100ms
    }

    pigpioTerminate();
    return 0;
}

