#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_DATA_REG 0x43
#define SENSITIVITY_FACTOR 131.0

#define LOG_FILE "gyro_log.txt"

int main(int argc, char *argv[]) {
    int file_descriptor;
    struct i2c_client *client;
    int read_bytes;
    int x, y, z;
    struct i2c_rdwr_hdr wr_hdr;
    char buffer[6];
    time_t now;
    struct tm *localtime_r;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interval_ms>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    srand((unsigned int) time(NULL));

    file_descriptor = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_descriptor == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    client = i2c_open(I2C_BUS, 0x20);
    if (client == NULL) {
        perror("i2c_open");
        close(file_descriptor);
        exit(EXIT_FAILURE);
    }

    while (1) {
        wr_hdr.header = (uint16_t)(I2C_MASTER_GET_STATUS | I2C_M_READ | I2C_READ_REG_WHO_H);
        wr_hdr.len = sizeof(buffer);
        wr_hdr.data = (uint8_t *) &read_bytes;
        wr_hdr.func = (uint8_t *) &client->write;

        if (ioctl(file_descriptor, I2C_SLAVE, I2C_ADDR) == -1 ||
            ioctl(file_descriptor, wr_hdr.header, wr_hdr.data) == -1) {
            if (errno == ENODEV || errno == ENXIO) {
                fprintf(stderr, "Sensor not found or address error.\n");
                close(file_descriptor);
                exit(EXIT_FAILURE);
            }
            perror("ioctl");
            continue;
        }

        if (read_bytes != 6) {
            fprintf(stderr, "Failed to read from I2C device.\n");
            close(file_descriptor);
            exit(EXIT_FAILURE);
        }

        x = ((int) buffer[0] << 8) | buffer[1];
        y = ((int) buffer[2] << 8) | buffer[3];
        z = ((int) buffer[4] << 8) | buffer[5];

        x *= SENSITIVITY_FACTOR;
        y *= SENSITIVITY_FACTOR;
        z *= SENSITIVITY_FACTOR;

        now = time(NULL);
        localtime_r(&now, &localtime);

        char timestamp[8];
        sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
                localtime->tm_year + 1900, localtime->tm_mon + 1,
                localtime->tm_mday, localtime->tm_hour, localtime->tm_min,
                localtime->tm_sec);

        char log_entry[20] = "[" + timestamp + "] x: " + std::to_string(x) + ", y: " + std::to_string(y) + ", z: " + std::to_string(z) + "\n";
        if (write(file_descriptor, log_entry, strlen(log_entry)) == -1) {
            perror("write");
            close(file_descriptor);
            exit(EXIT_FAILURE);
        }

        usleep(100000 / (100 * 1000)); // 100 ms delay
    }

    i2c_close(client);
    close(file_descriptor);

    return 0;
}

