#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO_PIN 11
#define POLL_TIMEOUT_MS (1000)
#define LOG_FILE "vibration_events.log"
#define SLIDE_WINDOW_SIZE 5

volatile sig_atomic_t quit_loop = 0;

void signal_handler(int signum) {
    global_signal_set->set(SIG_DFL);
    quit_loop = 1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        POLL_TIMEOUT_MS = 1000;
    }

    int fd_log;
    fd_log = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd_log == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    gpiod_line_config_t line_config = {
        .line_id = GPIO_PIN,
        .mode = GPIOD_LINE_MODE_INPUT,
        .edge_edge_rising = 1,
        .edge_edge_falling = 1,
        .poll_timeout_ms = POLL_TIMEOUT_MS
    };

    gpiod_line_request_input(GPIO_PIN, &line_config);

    while (!quit_loop) {
        gpiod_line_event_t event;
        int ret = gpiod_line_event_wait(GPIO_PIN, &event, POLL_TIMEOUT_MS);
        if (ret < 0) {
            perror("Failed to wait for event");
            exit(EXIT_FAILURE);
        }

        if (event.type == GPIOD_LINE_EVENT_TYPE_RISING) {
            time_t now = time(NULL);
            char timestamp[32];
            sprintf(timestamp, "%0.6f", (double)now / 1000);
            fprintf(fd_log, "%s %d\n", timestamp, event.value);
        } else if (event.type == GPIOD_LINE_EVENT_TYPE_FALLING) {
            time_t now = time(NULL);
            char timestamp[32];
            sprintf(timestamp, "%0.6f", (double)now / 1000);
            fprintf(fd_log, "%s %d\n", timestamp, event.value);
        }

        // Earthquake early-warning simulation
        static int event_count[SLIDE_WINDOW_SIZE] = {0};
        event_count[0] = event.value;

        for (int i = 1; i < SLIDE_WINDOW_SIZE; i++) {
            event_count[i] = event_count[i - 1];
        }

        if (event_count[SLIDE_WINDOW_SIZE - 1] == 1) {
            event_count[SLIDE_WINDOW_SIZE - 1] = 0;
            for (int i = 0; i < SLIDE_WINDOW_SIZE - 1; i++) {
                if (event_count[i] == 1) {
                    event_count[i] = 0;
                }
            }
        }

        if (event_count[SLIDE_WINDOW_SIZE - 5] == 3) {
            printf("EARTHQUAKE ALERT: %s\n", timestamp);
        }

        usleep(100000); // Adjust sleep time as needed
    }

    close(fd_log);
    gpiod_line_release(GPIO_PIN);
    return 0;
}

int main_signal_handler(int signum) {
    global_signal_set->set(SIG_DFL);
    quit_loop = 1;
    exit(EXIT_SUCCESS);
}

signal(SIGINT, signal_handler);
signal(SIGTERM, main_signal_handler);

// Initialize libgpiod
if (gpiod_init() < 0) {
    perror("Failed to initialize libgpiod");
    exit(EXIT_FAILURE);
}

// Run the main loop
main(argc, argv);

// Clean up libgpiod
gpiod_cleanup();

return 0;

