#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1E
#define SDA_PIN 3
#define SCL_PIN 5
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define COMPASS_DIRECTIONS_LEN 8
#define COMPASS_DIRECTION_MAP {
    "N", "NE", "E", "SE", "S", "SW", "W", "NW"
}

void calibrate_magnetometer(int *x, int *y, int *z) {
    *x -= X_OFFSET;
    *y += Y_OFFSET;
    *z -= Z_OFFSET;
}

float compute_heading(float x, float y) {
    return fmod(atan2f(y, x) * 180 / M_PI, 360);
}

void log_to_csv(const char *direction) {
    FILE *file = fopen("mag_log.csv", "a");
    if (!file) {
        perror("Failed to open mag_log.csv");
        return;
    }
    fprintf(file, "%d,%f,%f,%f,%f\n", (int)time(NULL), *x, *y, *z, compute_heading(*x, *y));
    fclose(file);
}

int main(int argc, char *argv[]) {
    int file;
    struct i2c_client *client;
    int i2c_fd;
    long timestamp;
    int x, y, z;
    char direction[10];

    client = i2c_open(I2C_BUS, 0x1E);
    if (!client) {
        perror("Failed to open I2C client");
        return 1;
    }

    i2c_fd = i2c_request(client, 0x02);
    if (i2c_write(client, 0x00) != 7) {
        perror("Failed to write MR_REG_M");
        i2c_close(client);
        return 1;
    }

    if (i2c_read(client, 0x03) != 2) {
        perror("Failed to read X MSB");
        i2c_close(client);
        return 1;
    }
    x = (int)i2c_read(client, 0x03) | (int)(i2c_read(client, 0x04) << 8);

    if (i2c_read(client, 0x05) != 2) {
        perror("Failed to read Z MSB");
        i2c_close(client);
        return 1;
    }
    z = (int)i2c_read(client, 0x05) | (int)(i2c_read(client, 0x06) << 8);

    if (i2c_read(client, 0x07) != 2) {
        perror("Failed to read Y MSB");
        i2c_close(client);
        return 1;
    }
    y = (int)i2c_read(client, 0x07) | (int)(i2c_read(client, 0x08) << 8);

    calibrate_magnetometer(&x, &y, &z);
    float heading = compute_heading(x, y);

    timestamp = time(NULL);
    strftime(direction, sizeof(direction), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

    log_to_csv(direction);

    i2c_close(client);
    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Exiting...\n");
        i2c_close(client);
        fcloseall();
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // ... (rest of the code as shown above)
}

