#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <json-c/json.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define MIN_TOUCH_GAP_MS 200000

#define RELAY_ON 1
#define RELAY_OFF 0

#define RELAY_LOG_FILE "relay_log.json"

static char *relay_log_entry = NULL;

void handle_interrupt(int sig) {
    gpioSetRelayState(RELAY_GPIO, RELAY_OFF);
    append_log_entry("OFF");
    gpioTerminate();
    exit(0);
}

void append_log_entry(const char *state) {
    json_object *log_entry = json_object_new();
    json_object_set_new(log_entry, "timestamp", json_object_from_iso8601(json_object_new()));
    json_object_set_new(log_entry, "relay_state", json_object_from_string(state));
    relay_log_entry = json_object_to_string(log_entry);
    FILE *fp = fopen(RELAY_LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s\n", relay_log_entry);
        fclose(fp);
        json_object_free(relay_log_entry);
    } else {
        fprintf(stderr, "Failed to open relay_log.json for appending.\n");
        json_object_free(log_entry);
    }
}

