#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/gpio.h>
#include <time.h>

#define RELAY_PINS {17, 23, 24, 25}
#define RELAY_OFF_DRIVE 1
#define RELAY_GAP_TIME 1000
#define LOG_FILE "irrigation_log.txt"

void log_activation(const char *timestamp, int relay_num, int moisture) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp_str[32];
    sprintf(timestamp_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1,
            local_time->tm_mday, local_time->tm_hour, local_time->tm_min, local_time->tm_sec);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing.\n");
