#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>
#include <pthread.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_WATER_VALVE 17
#define GPIO_NOZZLE 18
#define MOISTURE_READINGS {20, 40, 60, 80, 100}
#define WATERING_DURATION 2000 // 2 seconds
#define HOLD_DURATION 5000 // 5 seconds
#define SWEEP_STEPS 5
#define SWEEP_ANGLE_INCREMENT 45

#define MAX_RETRIES 3
#define BACKOFF_MS 100

void signal_handler(int signum) {
    printf("Received signal %d, stopping servos and exiting.\n", signum);
    gpioServo(GPIO_WATER_VALVE, 0);
    gpioServo(GPIO_NOZZLE, 0);
    gpioTerminate();
    exit(signum);
}

void* watering_thread(void* arg) {
    int ret;
    int moisture_reading = 0;
    int valve_open = 0;
    int nozzle_angle = 0;

    while (1) {
        moisture_reading = MOISTURE_READINGS[rand() % MOISTURE_READINGS.size()];
        if (moisture_reading < 50) {
            valve_open = 1;
            nozzle_angle = 0;
            for (int i = 0; i < SWEEP_STEPS; i++) {
                gpioServo(GPIO_NOZZLE, nozzle_angle);
                nozzle_angle += SWEEP_ANGLE_INCREMENT;
                usleep(WATERING_DURATION * 1000000 / SWEEP_STEPS);
                usleep(HOLD_DURATION * 1000000 / SWEEP_STEPS);
            }
            gpioServo(GPIO_NOZZLE, 0);
            gpioServo(GPIO_WATER_VALVE, 90);
            usleep(WATERING_DURATION * 1000000);
            gpioServo(GPIO_WATER_VALVE, 0);
            usleep(HOLD_DURATION * 1000000);
        }
        else {
            gpioServo(GPIO_WATER_VALVE, 0);
            gpioServo(GPIO_NOZZLE, 0);
        }
        sleep(1);
    }

    return NULL;
}

int main() {
    int ret;
    ret = gpioInitialise();
    if (ret != 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, watering_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create thread: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    sigset_t sigset;
    memset(&sigset, 0, sizeof(sigset));
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    while (1) {
        usleep(100000);
    }

    pthread_join(thread_id, NULL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

