#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B

#define SENSITIVITY 131.0

void handle_interrupt(int sig) {
    printf("Gyroscope data logging stopped.\n");
    close(fd);
    exit(0);
}

void read_mpu6050_gyro(void) {
    int file;
    char buffer[6];
    long long raw_data;

    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_BM_READ, GYRO_XOUT_H) == -1) {
        perror("ioctl I2C_BM_READ");
        close(file);
        exit(EXIT_FAILURE);
    }

    raw_data = read(file, buffer, 6);
    if (raw_data != 6) {
        perror("read from I2C");
        close(file);
        exit(EXIT_FAILURE);
    }

    uint16_t gyro_x = (buffer[0] << 8) | buffer[1];
    uint16_t gyro_y = (buffer[2] << 8) | buffer[3];
    uint16_t gyro_z = (buffer[4] << 8) | buffer[5];

    double x = (gyro_x * SENSITIVITY) / 32768.0;
    double y = (gyro_y * SENSITIVITY) / 32768.0;
    double z = (gyro_z * SENSITIVITY) / 32768.0;

    time_t now = time(NULL);
    char timestamp[20];
    sprintf(timestamp, "%ld", now);

    FILE *fp = fopen("gyro_log.txt", "a");
    if (!fp) {
        perror("fopen gyro_log.txt");
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "%s,%f,%f,%f\n", timestamp, x, y, z);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int fd;

    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_BM_WRITE, PWR_MGMT_1) == -1) {
        perror("ioctl I2C_BM_WRITE");
        close(fd);
        exit(EXIT_FAILURE);
    }

    read_mpu6050_gyro();
    close(fd);

    return 0;
}

