        gpioSetPullUpDown(COIL_B_PIN, PI_PULLDOWN);
    }
    printf("Clockwise rotation complete.\n");
}

void rotate_counter_clockwise() {
    int coil_a = 1, coil_b = 1;
    for (int i = 0; i < STEPS_PER_ROTATION; i++) {
        gpioWrite(COIL_A_PIN, coil_a);
        gpioWrite(COIL_B_PIN, coil_b);
        gpioSetMode(COIL_A_PIN, PI_OUTPUT);
        gpioSetMode(COIL_B_PIN, PI_OUTPUT);
        gpioSetPullUpDown(COIL_A_PIN, PI_NOPULL);
        gpioSetPullUpDown(COIL_B_PIN, PI_NOPULL);
        usleep(STEP_DELAY * 1000);
        gpioWrite(COIL_A_PIN, 0);
        gpioWrite(COIL_B_PIN, 0);
        gpioSetMode(COIL_A_PIN, PI_INPUT);
        gpioSetMode(COIL_B_PIN, PI_INPUT);
        gpioSetPullUpDown(COIL_A_PIN, PI_PULLDOWN);
        gpioSetPullUpDown(COIL_B_PIN, PI_PULLDOWN);
    }
    printf("Counter-clockwise rotation complete.\n");
}

int main() {
    signal(SIGINT, handle_sigint);

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUp(LOCK_BUTTON_PIN);
    gpioSetPullUp(UNLOCK_BUTTON_PIN);

    gpioSetMode(COIL_A_PIN, PI_OUTPUT);
    gpioSetMode(COIL_B_PIN, PI_OUTPUT);
    gpioSetPullUpDown(COIL_A_PIN, PI_NOPULL);
    gpioSetPullUpDown(COIL_B_PIN, PI_NOPULL);

    gpioSetMode(IN1_PIN, PI_INPUT);
    gpioSetMode(IN2_PIN, PI_INPUT);
    gpioSetPullUp(IN1_PIN);
    gpioSetPullUp(IN2_PIN);

    while (1) {
        button_debounce(LOCK_BUTTON_PIN);
        handle_button_press(LOCK_BUTTON_PIN);

        button_debounce(UNLOCK_BUTTON_PIN);
        handle_button_press(UNLOCK_BUTTON_PIN);

        usleep(100000);  // Small delay to debounce buttons
    }

    gpioTerminate();
    return 0;
}

void handle_sigint(int signum) {
    rotate_counter_clockwise();
    printf("Exiting...\n");
    gpioTerminate();
    exit(EXIT_SUCCESS);
}
```

This code initializes the pigpio library, sets up GPIO pins for the stepper motor coils and buttons, and implements a debounce mechanism for the buttons. It defines functions to rotate the motor clockwise and counter-clockwise, handling the inter-step delay and de-energizing the coils after each rotation. The main loop reads button presses, calls the appropriate rotation function, and includes a small delay to debounce the buttons. The SIGINT handler rotates the motor counter-clockwise and exits the program gracefully.

