void init_vl53l1x(void);
void setup_gpio(void);
void read_distance(void);
void handle_error(const char *msg, int err);
void handle_sigint(int sig);

int main(int argc, char *argv[]) {
    int i2c_fd;
    int ret;
    struct wiringPiI2C *i2c;

    setup_gpio();
    init_vl53l1x();

    while (1) {
        read_distance();
        usleep(100000); // 100 ms delay
    }

    return 0;
}

void init_vl53l1x(void) {
    ret = pigioInit();
    if (ret < 0) {
        handle_error("Failed to initialize pigpio", errno);
    }

    i2c_fd = pigopen(I2C_BUS, VL53L1X_ADDR);
    if (i2c_fd < 0) {
        handle_error("Failed to open I2C bus", errno);
    }

    ret = pigwrite(i2c_fd, 0x00, 0x00); // Software reset
    if (ret != 3) {
        handle_error("Failed to reset VL53L1X", errno);
    }

    ret = pigwrite(i2c_fd, 0x00, 0x01); // Set ranging mode and continuous ranging
    if (ret != 3) {
        handle_error("Failed to initialize VL53L1X", errno);
    }
}

void setup_gpio(void) {
    ret = pigioSetup(RELAY_GPIO, PI_OUTPUT);
    if (ret < 0) {
        handle_error("Failed to set up GPIO relay", errno);
    }
}

void read_distance(void) {
    uint16_t status, distance;

    ret = pigread(i2c_fd, 0x0044, &status);
    if (ret != 2) {
        handle_error("Failed to read interrupt status", errno);
    }

    if (status & 0x01) { // Data ready
        ret = pigread(i2c_fd, 0x0096, &distance);
        if (ret != 2) {
            handle_error("Failed to read distance MSB", errno);
        }

        ret = pigread(i2c_fd, 0x0097, &distance);
        if (ret != 2) {
            handle_error("Failed to read distance LSB", errno);
        }

        double distance_cm = (distance << 8) | distance;
        printf("Distance: %.2f cm\n", distance_cm);

        if (distance_cm < 50.0) {
            pigwrite(RELAY_GPIO, PI_HIGH);
        } else {
            pigwrite(RELAY_GPIO, PI_LOW);
        }
    }
}

void handle_error(const char *msg, int err) {
    fprintf(stderr, "Error: %s - %d\n", msg, err);
}

void handle_sigint(int sig) {
    close(i2c_fd);
    pigioExit();
    printf("SIGINT received, exiting...\n");
    exit(1);
}

