    signal(SIGINT, handle_sigint);

    int i2c_fd;
    int ret;
    struct wiringPiI2C *i2c;

    setup_gpio();
    init_vl53l1x();

    while (1) {
        read_distance();
        usleep(100000); // 100 ms delay
    }

    return 0;
}

