#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68
#define GYRO_CONFIG 0x1B
#define PWR_MGMT_1 0x6B
#define GYRO_DATA_START 0x43
#define SENSITIVITY 131

#define BUFFER_SIZE 6

int i2c_fd;
uint8_t read_buffer[BUFFER_SIZE];
uint8_t write_buffer[2];

void init_mpu6050(void) {
    write_buffer[0] = 0x6B; // PWR_MGMT_1
    write_buffer[1] = 0x00; // Wake up from sleep
    ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    ioctl(i2c_fd, I2C_WRITE, write_buffer);

    write_buffer[0] = 0x2A; // GYRO_CONFIG
    write_buffer[1] = 0x0F; // ±250 dps full-scale
    ioctl(i2c_fd, I2C_WRITE, write_buffer);
}

void read_mpu6050(void) {
    int bytes_read;
    ioctl(i2c_fd, I2C_READ, read_buffer);
    bytes_read = read(i2c_fd, read_buffer, BUFFER_SIZE);
    if (bytes_read != BUFFER_SIZE) {
        perror("Failed to read from MPU-6050");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        uint16_t raw_data = (read_buffer[i] << 8) | read_buffer[i + 1];
        float gyro_data = (raw_data * SENSITIVITY) / 32768.0; // Convert to dps
        printf("X: %.3f dps, Y: %.3f dps, Z: %.3f dps\n", gyro_data, -gyro_data, 0.0);
    }
}

int main(int argc, char *argv[]) {
    int ret;

    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    i2c_fd = open(I2C_BUS, O_RDWR | O_SYNC);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    init_mpu6050();

    while (1) {
        read_mpu6050();
        usleep(100000); // Sleep for 100ms between readings
    }

    close(i2c_fd);
    return 0;
}

