#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define RELAY_PINS {11, 12, 13, 15} // GPIO17, GPIO18, GPIO27, GPIO22
#define POLL_INTERVAL 60000 // 60 seconds
#define WATERING_INTERVAL 86400 // 24 hours in seconds

void signal_handler(int signum) {
    int i;
    for (i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        gpiod_pin_set_direction(gpiochip0, RELAY_PINS[i], GPIOD_OUT);
    }
    for (i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        gpiod_pin_set_drive(gpiochip0, RELAY_PINS[i], GPIOD_LOW);
    }
    close(gpiochip0);
}

int main() {
    int gpiochip0;
    gpiod_chip_t chip;
    gpiod_pin_t *pins[4];
    struct itimerspec interval;
    struct itimerspec watering_interval;
    char watering_log_path[256];
    char time_str[32];

    // Initialize GPIO chip
    gpiochip0 = gpiod_chip_open("gpiochip0", NULL, NULL);
    if (gpiochip0 < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Allocate pins
    pins = malloc(sizeof(gpiod_pin_t*) * 4);
    for (int i = 0; i < 4; i++) {
        pins[i] = gpiod_pin_new_from_gpio(gpiochip0, RELAY_PINS[i]);
        if (!pins[i]) {
            perror("Failed to create GPIO pin");
            gpiod_chip_close(gpiochip0);
            exit(EXIT_FAILURE);
        }
    }

    // Set all pins as outputs with active-low
    for (int i = 0; i < 4; i++) {
        gpiod_pin_set_direction(gpiochip0, pins[i], GPIOD_OUT);
        gpiod_pin_set_drive(gpiochip0, pins[i], GPIOD_LOW);
    }

    // Open watering_log file
    watering_log_path[0] = '\0';
    strncpy(watering_log_path, "/home/pi/watering_log.txt", 255);
    FILE *log_file = fopen(watering_log_path, "a");
    if (!log_file) {
        perror("Failed to open watering log file");
        gpiod_chip_close(gpiochip0);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize interval structure
    interval.it_value.tv_sec = 0;
    interval.it_value.tv_nsec = 0;
    interval.it_repeat.ns_value = WATERING_INTERVAL.tv_sec * 1e9 + WATERING_INTERVAL.tv_nsec;

    // Initialize watering interval
    watering_interval.it_value.tv_sec = 0;
    watering_interval.it_value.tv_nsec = 0;
    watering_interval.it_repeat.ns_value = WATERING_INTERVAL.tv_sec * 1e9 + WATERING_INTERVAL.tv_nsec;

    // Start watering loop
    while (1) {
        // Log start time
        time_str[0] = '\0';
        time(time_str);
