#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define RELAY_PINS {17, 18, 27, 22}
#define PWM_FREQUENCY 1000
#define DUTY_CYCLE_STEP 1
#define SIMULATION_DURATION 30 * 60  // 30 minutes in seconds

void log_event(const char *format, ...) {
    time_t now = time(NULL);
    char timestamp[100];
    snprintf(timestamp, sizeof(timestamp), "%s", ctime(&now));
    syslog(LOG_INFO, "%s: " format, timestamp, ##__VA_ARGS__);
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        log_event("Error: Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    int duration_seconds = atoi(argv[1]);
    if (duration_seconds <= 0) {
        log_event("Error: Duration must be a positive number.\n");
        return 1;
    }

    int ret;
    pigpio_init(5); // Initialize pigpio with 5 seconds timeout

    if (pigpio_init(5) < 0) {
        log_event("Error: Failed to initialize pigpio.\n");
        return 1;
    }

    log_event("pigpio initialized successfully.\n");

    for (int i = 0; i < 4; i++) {
        ret = gpioSetup(RELAY_PINS[i], PI_OUTPUT, 0);
        if (ret < 0) {
            log_event("Error setting up GPIO %d as output.\n", RELAY_PINS[i]);
            pigpio_terminate(1000); // Terminate pigpio on error
            return 1;
        }
    }

    log_event("GPIO pins set up successfully.\n");

    gpioSetPWMfrequency(0, PWM_FREQUENCY); // Set PWM frequency for all GPIOs

    log_event("PWM frequency set to %d Hz.\n", PWM_FREQUENCY);

    int duty_cycle = 0;
    for (int i = 0; i <= 255; i += DUTY_CYCLE_STEP) {
        for (int j = 0; j < 4; j++) {
            ret = gpioPWM(RELAY_PINS[j], 0, i);
            if (ret < 0) {
                log_event("Error setting PWM duty cycle for GPIO %d to %d.\n", RELAY_PINS[j], i);
                pigpio_terminate(1000); // Terminate pigpio on error
                return 1;
            }
        }
        usleep(100000); // Sleep for 100 milliseconds (100 steps of 1 ms)
        duty_cycle++;
    }

    log_event("Sunrise simulation completed.\n");

    pigpio_terminate(1000); // Terminate pigpio on exit

    syslog(LOG_INFO, "Program exited.\n");
    return 0;
}

