#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define GPIO_LED 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 20
#define SAMPLE_PERIOD_MS 50

#define GYRO_XOUT_H 0x43
#define SMPLRT_DIV 0x19
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define WHO_AM_I 0x75

int main() {
    int i2c_fd, led_fd;
    int buffer_size, buffer_index;
    struct i2c_client *client;
    int gyro_data[6];
    struct timespec start_time, end_time;
    double elapsed_time;
    int gyro_value, abs_gyro_value;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open i2c");
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(i2c_fd, I2C_BUS);
    if (!client) {
        perror("i2c_client_new");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        i2c_client_free(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_MEM_WRITE, (u32)(PWR_MGMT_1)) == -1) {
        perror("ioctl PWR_MGMT_1");
        i2c_client_free(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_MEM_WRITE, (u32)(SMPLRT_DIV)) == -1) {
        perror("ioctl SMPLRT_DIV");
        i2c_client_free(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_MEM_WRITE, (u32)(GYRO_CONFIG)) == -1) {
        perror("ioctl GYRO_CONFIG");
        i2c_client_free(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_MEM_READ, (u32)WHO_AM_I) == -1) {
        perror("ioctl WHO_AM_I");
        i2c_client_free(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_MEM_READ, gyro_data) == -1) {
        perror("ioctl WHO_AM_I");
        i2c_client_free(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gyro_data[0] != 0x68) {
        fprintf(stderr, "MPU-6050 not detected\n");
        i2c_client_free(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    buffer_size = BUFFER_SIZE;
    buffer_index = 0;
    led_fd = open("/dev/gpio17", O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (led_fd == -1) {
        perror("open gpio17");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpioSetMode(led_fd, PI_OUTPUT);

    while (1) {
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        elapsed_time = (now.tv_sec - start_time.tv_sec) * 1e9 + (now.tv_nsec - start_time.tv_nsec) / 1e6;

        if (elapsed_time >= SAMPLE_PERIOD_MS / 1000) {
            if (ioctl(i2c_fd, I2C_MEM_READ, gyro_data) == -1) {
                perror("ioctl gyro_data");
                i2c_client_free(client);
                close(i2c_fd);
                close(led_fd);
                exit(EXIT_FAILURE);
            }

            gyro_value = (gyro_data[5] << 8) | gyro_data[4];
            abs_gyro_value = (gyro_value > 0) ? gyro_value : -gyro_value;

            if (abs_gyro_value > 250) {
                gpioWrite(led_fd, 1);
            } else {
                gpioWrite(led_fd, 0);
            }

            for (int i = 0; i < buffer_size; i++) {
                if (buffer_index >= buffer_size) {
                    buffer_index = 0;
                }
                buffer[buffer_index++] = abs_gyro_value;
            }
        }

        start_time = now;
    }

    gpioSetMode(led_fd, PI_OUTPUT);
    gpioWrite(led_fd, 0);
    i2c_client_free(client);
    close(i2c_fd);
    close(led_fd);
    pigpioTerminate();

    return 0;
}

