#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 10000000  // 1 MHz
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_MSBFIRST 1
#define CHIP_SELECT_GPIO 8
#define CHIP_SELECT_GPIO_LINE 0
#define SCALE_FACTOR 131.0

#define LOG_FILE "gyro_log.txt"
#define LOG_INTERVAL_MS 10000  // 10 ms

void spi_init(int fd) {
    struct spi_fd *spi_fd = spi_open(SPI_DEVICE, 0, fd);
    if (!spi_fd) {
        perror("spi_open");
        exit(EXIT_FAILURE);
    }
}

void gpio_init(void) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("open /dev/gpiochip0");
        exit(EXIT_FAILURE);
    }

    struct gpio_desc *desc;
    for (int i = 0; i < 8; i++) {
        desc = gpio_describe(fd, i);
        if (!desc) {
            perror("gpio_describe");
            exit(EXIT_FAILURE);
        }
        if (desc->flags & GPIOF_OUTPUT) {
            gpio_set_dir(fd, i, GPIO_OUT);
        }
    }
}

void gpio_deinit(void) {
    for (int i = 0; i < 8; i++) {
        gpio_set_dir(fd, i, GPIO_IN);
    }
}

void spi_transfer(uint32_t addr, uint32_t *data) {
    struct spi_ioc_transfer spi_transfer = {
        .transfer_type = SPI_IOC_MESSAGE,
        .msg_len = sizeof(struct spi_ioc_transfer),
        .flags = SPI_IOC_RAW,
        .addr = (uint32_t)addr,
        .data = data
    };

    ssize_t ret = spi_async_transfer(spi_fd, &spi_transfer);
    if (ret < 0) {
        perror("spi_async_transfer");
        exit(EXIT_FAILURE);
    }
}

void read_gyro_data(uint16_t *x_rate, uint16_t *y_rate, uint16_t *z_rate) {
    uint32_t data[6];
    for (int i = 0; i < 3; i++) {
        spi_transfer(0x43 + i, data + i);
    }

    for (int i = 0; i < 3; i++) {
        *x_rate = ((data[i] >> 16) & 0xFF) * SCALE_FACTOR;
        *y_rate = ((data[i] >> 8) & 0xFF) * SCALE_FACTOR;
        *z_rate = (data[i] & 0xFF) * SCALE_FACTOR;
    }
}

void log_gyro_data(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s,%lu,%lu,%lu\n", timestamp, *x_rate, *y_rate, *z_rate);
    fclose(log_file);
}

