    spi_init(0);
    gpio_init();

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%T.%09z", localtime(&ts.tv_sec));

