            spi_transfer(0x01, NULL);  // CS low
            read_gyro_data(x_rate, y_rate, z_rate);
            gpio_set_dir(CHIP_SELECT_GPIO_LINE, 1);  // CS high

            log_gyro_data(timestamp);

            if (errno == EINTR || errno == EAGAIN) {
                break;
            }
        }

        if (errno != 0) {
            fprintf(stderr, "Error: %s\n", strerror(errno));
        }

        usleep(LOG_INTERVAL_MS / 1000);
    }

    gpio_deinit();
    spi_close(spi_fd);
    close(CHIP_SELECT_GPIO_LINE);
    return 0;
