#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>
#include <errno.h>

#define BUFFER_SIZE 64
#define SPI_DEVICE "/dev/spidev0.0"
#define CE_PIN 8
#define SPI_SPEED 39000000
#define SPI_MODE 0
#define SENSITIVITY_FACTOR 131

#define LED_PIN 11

typedef struct {
    uint16_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

static int spi_fd;
static int gpio_led_fd;
static gpio_request(const char *, int);
static void gpio_free(int fd);
static int gpio_set_direction(int fd, int direction);
static int gpio_set_level(int fd, int level);

static int spidev_open(const char *device, int mode);
static int spidev_close(int fd);
static int spidev_write(int fd, uint8_t *buf, size_t len);
static int spidev_read(int fd, uint8_t *buf, size_t len);

static gyro_data_t buffer[BUFFER_SIZE];
static int buffer_index = 0;

void init_spi_gpio() {
    spi_fd = spidev_open(SPI_DEVICE, 0);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    gpio_led_fd = gpio_request(LED_PIN, GPIOD_OUTPUT);
    if (gpio_led_fd < 0) {
        perror("Failed to request GPIO17");
        exit(EXIT_FAILURE);
    }

    gpio_set_direction(gpio_led_fd, GPIO_OUTPUT);

    gpio_set_level(gpio_led_fd, 0); // LED off by default
}

void release_resources() {
    spidev_close(spi_fd);
    gpio_free(gpio_led_fd);
}

void read_mpu6050() {
    uint8_t cs_low, data[3];
    int16_t x, y, z;

    cs_low = 1 << CE_PIN;
    gpio_set_level(gpio_led_fd, 1); // Assert CE0

    if (spidev_write(spi_fd, &cs_low, 1) != 1) {
        perror("Failed to write to CE0");
        return;
    }

    if (spidev_read(spi_fd, data, 3) != 3) {
        perror("Failed to read from MPU-6050");
        return;
    }

    x = (data[0] << 8) | data[1];
    y = (data[2] << 8) | data[3];
    z = (data[4] << 8) | data[5];

    if (x == 0 && y == 0 && z == 0) {
        printf("No data received, skipping...\n");
        return;
    }

    x = (x >> 8) & 0x7F;
    y = (y >> 8) & 0x7F;
    z = (z >> 8) & 0x7F;

    x *= SENSITIVITY_FACTOR;
    y *= SENSITIVITY_FACTOR;
    z *= SENSITY_FACTOR;

    buffer[buffer_index].timestamp = micros();
    buffer[buffer_index].x = x;
    buffer[buffer_index].y = y;
    buffer[buffer_index].z = z;
    buffer_index++;

    if (x > 200 || x < -200 || y > 200 || y < -200 || z > 200 || z < -200) {
        gpio_set_level(gpio_led_fd, !gpio_get_level(gpio_led_fd));
        sleep(0.5);
        gpio_set_level(gpio_led_fd, !gpio_get_level(gpio_led_fd));
    }
}

void print_buffer() {
    int i;
    printf("Timestamp,X,Y,Z\n");
    for (i = 0; i < buffer_index; i++) {
        printf("%d,%d,%d,%d\n", buffer[i].timestamp, buffer[i].x, buffer[i].y, buffer[i].z);
    }
}

int main(int argc, char *argv[]) {
    init_spi_gpio();

    while (1) {
        read_mpu6050();
        sleep(1);
    }

    print_buffer();
    release_resources();
    return 0;
}

