This code sets up a Raspberry Pi 3 Model B+ to read angular velocity data from an InvenSense MPU-6050 gyroscope using the spidev interface and libgpiod for chip-select control. It reads X, Y, and Z axis data, converts them to degrees per second, and stores them in a circular buffer. If any axis exceeds ±200 deg/s, it blinks an LED connected to GPIO17. On SIGINT (Ctrl+C), it prints the entire buffer as CSV before releasing resources.

Please note that this code assumes the necessary permissions and file existence for SPI and GPIO access. Also, the LED pin and sensitivity factor can be adjusted as needed.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define LED_GPIO 21
#define LOG_FILE "tilt_log.txt"
#define LOG_INTERVAL 100
#define MAX_ROLL_DEG 45
#define MAX_PITCH_DEG 45

void sigint_handler(int signum) {
    printf("\nSIGINT received. Turning off LED, closing I2C handle, and exiting.\n");
    gpioOutput(LED_GPIO, 0);
    pigioClose(0);
    exit(0);
}

void init_pigpio() {
    if (pigioInit() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    if (piI2COpen(I2C_BUS, I2C_ADDR) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void configure_sensor() {
    if (piI2CWriteByte(0, I2C_ADDR, 0x00) < 0) {
        perror("Failed to wake up the sensor");
        exit(EXIT_FAILURE);
    }

    if (piI2CWriteByte(0, I2C_ADDR, 0x1C) < 0) {
        perror("Failed to set full-scale range to ±2g");
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data() {
    struct i2c_msg msg;
    int data[6];

    if (piI2CReadBytes(0, I2C_ADDR, 0x3B, 6, data) < 0) {
        perror("Failed to read sensor data");
        return;
    }

    float x = (data[0] << 8) | data[1];
    float y = (data[2] << 8) | data[3];
    float z = (data[4] << 8) | data[5];

    float roll = atan2(y, z) * 180 / M_PI;
    float pitch = atan2(-x, sqrt(y * y + z * z)) * 180 / M_PI;

    if (abs(roll) > MAX_ROLL_DEG || abs(pitch) > MAX_PITCH_DEG) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }

    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%f,%f\n", timestamp, roll, pitch);
    fclose(file);

    printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
}

int main() {
    init_pigpio();
    setup_i2c();
    configure_sensor();

    while (1) {
        read_sensor_data();
        usleep(LOG_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    pigioClose(0);
    signal(SIGINT, sigint_handler);
    return 0;
}

