    uint8_t ambient_light, proximity;
    time_t now;
    struct tm *time_info;
    char log_entry[51];

    fd_i2c = open(I2C_DEVICE, O_RDWR);
    if (fd_i2c == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    fd_log = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd_log == -1) {
        perror("Failed to open log file");
        close(fd_i2c);
        exit(EXIT_FAILURE);
    }

    gpiod_init(NULL);
    result = gpiod_line_init(GPIO_LINE_17, "LED_GPIO");
    if (result != GPIOD_SUCCESS) {
        perror("Failed to initialize GPIO line");
        close(fd_i2c);
        close(fd_log);
        exit(EXIT_FAILURE);
    }

    client = i2c_open(fd_i2c, 0x5A);
    if (!client) {
        perror("Failed to open I2C client");
        close(fd_i2c);
        close(fd_log);
        exit(EXIT_FAILURE);
    }

    for (int retry = 0; retry < RETRY_COUNT; retry++) {
        result = i2c_transfer(client, REG_AMBIENT_LIGHT, 2, &ambient_light, 1);
        if (result == 0) {
            result = i2c_transfer(client, REG_PROXIMITY, 2, &proximity, 1);
            if (result == 0) {
                now = time(NULL);
                time_info = localtime(&now);
                sprintf(log_entry, "%04d-%02d-%02d %02d:%02d:%02d,AmbientLight:%02X,Proximity:%02X",
                        time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
                        time_info->tm_hour, time_info->tm_min, time_info->tm_sec);
                fprintf(fd_log, log_entry);

                if (proximity > 100) {
                    gpiod_line_write(GPIO_LINE_17, 1);
                } else {
                    gpiod_line_write(GPIO_LINE_17, 0);
                }

                sleep(READ_INTERVAL_MS / 1000.0);
            } else {
                printf("Failed to read proximity value, retrying...\n");
            }
        } else {
            printf("Failed to read ambient light value, retrying...\n");
        }
    }

    i2c_close(client);
    close(fd_i2c);
    close(fd_log);

    gpiod_line_destroy(&line_context);
    gpiod_ctx_unregister(&line_context);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return 0;
}
```

This code initializes the I2C device, GPIO line, and log file. It then enters a loop to read the ambient light and proximity values from the Si1145 sensor every 100 ms. If the proximity value exceeds 100, it sets the LED high; otherwise, it sets it low. The code handles I2C communication errors with up to 3 retries and a 10 ms delay between attempts. It also sets up signal handlers for SIGINT (Ctrl+C) and SIGTERM (kill) signals to ensure a clean exit, closing the I2C file descriptor, log file, and turning off the LED.

