void spi_error_handler(const char *cmd) {
    spiOpen(SPI_CHANNEL);
    spiXfer(SPI_CHANNEL, 0, 0, 0);
    spiClose(SPI_CHANNEL);
    pigpio_terminate(0);
    exit(1);
}

void sigint_handler(int sig) {
    spi_error_handler("SIGINT");
}

int main() {
    int spi_fd, ret;
    struct timespec ts;
    long long timestamp;

    signal(SIGINT, sigint_handler);

    // Initialize pigpio
    if ((ret = gpioInitialise()) != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_strerror(ret));
        return EXIT_FAILURE;
    }

    // Open SPI channel
    spi_fd = spiOpen(SPI_CHANNEL);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", pigpio_strerror(errno));
        spi_error_handler("Failed to open SPI channel");
        return EXIT_FAILURE;
    }

    // Configure SPI
    gpioSetMode(SPI_CHANNEL, PI_OUTPUT);
    gpioWrite(CE_PIN, 1); // Activate chip
    gpioWrite(SPI_CHANNEL, 0); // Set CPOL to 0
    gpioWrite(SPI_CHANNEL | 1, 0); // Set CPHA to 0
    gpioWrite(SPI_CHANNEL | 2, 0); // Set BCLK polarity
    gpioWrite(SPI_CHANNEL | 3, 0); // Set MSB first

    // Read sensitivity
    ret = spiXfer(SPI_CHANNEL, 0x00, 0x00, 0x00);
    if (ret != 2) {
        fprintf(stderr, "Failed to read sensitivity: %d\n", ret);
        spi_error_handler("Failed to read sensitivity");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        timestamp = clock() * CLOCK_PRI_US;

        // Read X and Y rates
        ret = spiXfer(SPI_CHANNEL, 0x02, 0x00, 0x00);
        if (ret != 2) {
            fprintf(stderr, "Failed to read X rate: %d\n", ret);
            spi_error_handler("Failed to read X rate");
            continue;
        }
        int16_t x_rate = (int16_t)(spiRead(SPI_CHANNEL) << 8) | spiRead(SPI_CHANNEL);
        x_rate *= SENSITIVITY;

        ret = spiXfer(SPI_CHANNEL, 0x04, 0x00, 0x00);
        if (ret != 2) {
            fprintf(stderr, "Failed to read Y rate: %d\n", ret);
            spi_error_handler("Failed to read Y rate");
            continue;
        }
        int16_t y_rate = (int16_t)(spiRead(SPI_CHANNEL) << 8) | spiRead(SPI_CHANNEL);
        y_rate *= SENSITIVITY;

        // Log data
        FILE *fp = fopen(LOG_FILE, "a");
        if (!fp) {
            fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
            continue;
        }
        fprintf(fp, "%ld,%d,%d\n", timestamp, x_rate, y_rate);
        fclose(fp);

        // Delay
        usleep(SAMPLE_DELAY_MS * 1000000);
    }

    // Clean up
    spiClose(SPI_CHANNEL);
    pigpio_terminate(0);
    return EXIT_SUCCESS;
}

