#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pthread.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CLOCK_HZ 1000000
#define SPI_MODE 0
#define SPI_CPOL 0
#define SPI_CPHA 0
#define LED_GPIO 17
#define BUFFER_CAPACITY 100
#define SENSITIVITY 200
#define READ_THRESHOLD 20.0

typedef struct {
    timespec timestamp;
    int angular_velocity;
} DataPoint;

typedef struct {
    DataPoint *buffer;
    pthread_mutex_t mutex;
    int head;
    int tail;
} CircularBuffer;

CircularBuffer buffer;

void spi_init(void) {
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_SET_MODE, SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_SET_CPOL, SPI_CPOL_0) < 0) {
        perror("Failed to set CPOL");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_SET_CPHA, SPI_CPHA_0) < 0) {
        perror("Failed to set CPHA");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    close(spi_fd);
}

void led_init(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialise GPIO");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(LED_GPIO, GPIO_OUTPUT);
}

void spi_read_data(int address, uint16_t *data) {
    if (ioctl(open("/dev/spidev0.0", O_RDWR), SPI_READ_REG, address) < 0) {
        perror("Failed to read from SPI");
        return;
    }

    if (ioctl(open("/dev/spidev0.0", O_RDWR), SPI_READ_DATA, data) < 0) {
        perror("Failed to read data from SPI");
        return;
    }
}

void *read_gyroscope(void *arg) {
    while (1) {
        uint16_t rate_xl, rate_xh;
        spi_read_data(0x02, &rate_xl);
        spi_read_data(0x03, &rate_xh);

        int angular_velocity = (rate_xl << 8) | rate_xh;
        angular_velocity *= SENSITIVITY / 200;

        timespec timestamp;
        clock_gettime(CLOCK_MONOTONIC, &timestamp);

        DataPoint dp = {timestamp, angular_velocity};
        pthread_mutex_lock(&buffer.mutex);
        if (buffer.head == buffer.tail) {
            buffer.tail++;
        }
        buffer.buffer[buffer.head] = dp;
        buffer.head++;
        pthread_mutex_unlock(&buffer.mutex);

        if (angular_velocity > READ_THRESHOLD) {
            gpioWrite(LED_GPIO, GPIO_HIGH);
        } else {
            gpioWrite(LED_GPIO, GPIO_LOW);
        }

        usleep(100000); // Adjust as needed
    }

    return NULL;
}

int main(void) {
    spi_init();
    led_init();

    CircularBuffer_init(&buffer, BUFFER_CAPACITY);

    pthread_t thread;
    if (pthread_create(&thread, NULL, read_gyroscope, NULL) != 0) {
        perror("Failed to create thread");
        spi_cleanup();
        led_cleanup();
        return EXIT_FAILURE;
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    spi_cleanup();
    led_cleanup();
    return EXIT_SUCCESS;
}

void spi_cleanup(void) {
    close(open("/dev/spidev0.0", O_RDWR)->fildes);
    pigpio_terminate(80);
}

void led_cleanup(void) {
    gpioNormalise();
    gpioWrite(LED_GPIO, GPIO_OFF);
}

void CircularBuffer_init(CircularBuffer *cb, int capacity) {
    cb->buffer = malloc(capacity * sizeof(DataPoint));
    cb->head = 0;
    cb->tail = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

void CircularBuffer_deinit(CircularBuffer *cb) {
    free(cb->buffer);
    pthread_mutex_destroy(&cb->mutex);
}

