#define LAMP_PINS {11, 12, 13} // GPIO17, GPIO18, GPIO27
#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define MAX_DURATION 3600

void signal_handler(int signum) {
    for (int i = 0; i < 3; i++) {
        piGPIOoutput(LAMP_PINS[i], 0);
    }
    pigpio_terminate(1000);
    exit(0);
