int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > MAX_DURATION) {
        fprintf(stderr, "Duration must be between 1 and %d seconds.\n", MAX_DURATION);
        return 1;
    }

    pigpio_init(1000); // Initialize pigpio with 1000 ms timeout

    for (int i = 0; i < 3; i++) {
        piGPIOoutput(LAMP_PINS[i], PWM_RANGE); // Set initial state to on
    }

    printf("Starting smart sunset simulator with duration: %d seconds\n", duration);

    for (int i = 0; i < 3; i++) {
        int lamp_pin = LAMP_PINS[i];
        int start_time = piPWMset(lamp_pin, 0); // Start with 0% duty cycle

        while (piPWMget(lamp_pin) != 0) {
            usleep(100000); // Sleep for 100 ms
            int current_duty_cycle = piPWMget(lamp_pin);
            printf("Lamp %d: %d%%\n", i, current_duty_cycle);
        }

        // Wait for the previous lamp to finish
        while (piGPIOoutput(LAMP_PINS[2-i], 0));

        // Fade lamp i to off
        int end_time = start_time + duration;
        while (piPWMget(lamp_pin) != 0 && piPWMget(lamp_pin) < PWM_RANGE * 2) {
            usleep(100000); // Sleep for 100 ms
            int current_duty_cycle = piPWMget(lamp_pin);
            printf("Lamp %d: %d%%\n", i, current_duty_cycle);
        }

        piPWMset(lamp_pin, 0); // Set to 0% duty cycle
    }

    printf("All lamps turned off. Exiting...\n");

    pigpio_terminate(1000); // Terminate pigpio
    signal(SIGINT, signal_handler); // Set signal handler
    signal(SIGTERM, signal_handler); // Set signal handler

    return 0;
}

