    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int ret;
    ret = libgpiod_init();
    if (ret < 0) {
        perror("libgpiod_init");
        return ret;
    }

    if (libgpiod_chip_open(GPIO_DEFAULT) < 0) {
        perror("libgpiod_chip_open");
        libgpiod_exit();
        return -1;
    }

    if (libgpiod_line_request(GPIO_DEFAULT) < 0) {
        perror("libgpiod_line_request");
        libgpiod_exit();
        return -1;
    }

    gpio_set_mode(RELAY_GPIO_17, GPIO_OUTPUT);
    gpio_set_mode(RELAY_GPIO_22, GPIO_OUTPUT);
    gpio_set_mode(RELAY_GPIO_23, GPIO_OUTPUT);
    gpio_set_mode(RELAY_GPIO_24, GPIO_OUTPUT);

    while (1) {
        printf("Red\n");
        gpio_write(RELAY_GPIO_17, 0);
        gpio_write(RELAY_GPIO_22, 0);
        gpio_write(RELAY_GPIO_23, 0);
        gpio_write(RELAY_GPIO_24, 0);
        usleep(RED_TIME * 1000000);

        printf("Red+Yellow\n");
        gpio_write(RELAY_GPIO_17, 0);
        gpio_write(RELAY_GPIO_22, 0);
        gpio_write(RELAY_GPIO_23, 0);
        gpio_write(RELAY_GPIO_24, 0);
        usleep(RED_YELLOW_TIME * 1000000);

