#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/time.h>

#define RELAY_GPIO 17
#define MPR121_I2C_BUS 1
#define MPR121_ADDR 0x5A

#define TOUCH_STATUS_REG 0x00
#define TOUCH_STATUS_MSB_REG 0x01
#define TOUCH_THRESHOLD 0x0A
#define TOUCH_RELEASE_THRESHOLD 0x08
#define TOUCH_DEBOUNCE 0x21
#define TOUCH_CHARGE_TIME 0x0D
#define TOUCH_RUN_MODE 0x0D

#define RELAY_ON 1
#define RELAY_OFF 0

#define LOG_FILE "touch_relay.log"

void log_error(const char *msg) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    sprintf(timestamp, "%s %ld.%03ld", ctime(&tv.tv_sec), tv.tv_usec / 1000, tv.tv_usec % 1000);
    fprintf(LOG_FILE, "%s: ERROR: %s\n", timestamp, msg);
}

int main(int argc, char *argv[]) {
    int rpi_gpio_fd, mp121_fd;
    int relay_state = RELAY_OFF;
    int touch_status_lsb, touch_status_msb;
    uint8_t config_data[10];

    if (pigpioInitialise() < 0) {
        log_error("Failed to initialise pigpio");
        return EXIT_FAILURE;
    }

    if ((rpi_gpio_fd = gpioSetup(RELAY_GPIO, RELAY_GPIO_OUTPUT)) < 0) {
        log_error("Failed to set GPIO17 as output");
        pigpiodown();
        return EXIT_FAILURE;
    }

    if ((rpi_gpio_fd = gpioWrite(rpi_gpio_fd, RELAY_OFF)) < 0) {
        log_error("Failed to set initial relay state");
        pigpiodown();
        return EXIT_FAILURE;
    }

    if ((mp121_fd = mp121Open(MPR121_I2C_BUS, MPR121_ADDR)) < 0) {
        log_error("Failed to open MPR121 I2C device");
        pigpiodown();
        return EXIT_FAILURE;
    }

    if (mp121Write(mp121_fd, 0x80, 0x63) < 0) {
        log_error("Failed to write reset register");
        mp121Close(mp121_fd);
        pigpiodown();
        return EXIT_FAILURE;
    }

    if (mp121Write(mp121_fd, 0x5E, 0x00) < 0) {
        log_error("Failed to write stop mode");
        mp121Close(mp121_fd);
        pigpiodown();
        return EXIT_FAILURE;
    }

    if (mp121Write(mp121_fd, 0x5D, 0x01) < 0) {
        log_error("Failed to write enable electrode 0");
        mp121Close(mp121_fd);
        pigpiodown();
        return EXIT_FAILURE;
    }

    if (mp121Write(mp121_fd, 0x41, TOUCH_THRESHOLD) < 0) {
        log_error("Failed to write touch threshold");
        mp121Close(mp121_fd);
        pigpiodown();
        return EXIT_FAILURE;
    }

    if (mp121Write(mp121_fd, 0x42, TOUCH_RELEASE_THRESHOLD) < 0) {
        log_error("Failed to write release threshold");
        mp121Close(mp121_fd);
        pigpiodown();
        return EXIT_FAILURE;
    }

    if (mp121Write(mp121_fd, 0x5B, TOUCH_DEBOUNCE) < 0) {
        log_error("Failed to write debounce");
        mp121Close(mp121_fd);
        pigpiodown();
        return EXIT_FAILURE;
    }

    if (mp121Write(mp121_fd, 0x5C, TOUCH_CHARGE_TIME) < 0) {
        log_error("Failed to write charge time");
        mp121Close(mp121_fd);
        pigpiodown();
        return EXIT_FAILURE;
    }

    if (mp121Write(mp121_fd, 0x5E, TOUCH_RUN_MODE) < 0) {
        log_error("Failed to write run mode");
        mp121Close(mp121_fd);
        pigpiodown();
        return EXIT_FAILURE;
    }

    while (1) {
        if (mp121Read(mp121_fd, TOUCH_STATUS_REG, &touch_status_lsb) < 0) {
            log_error("Failed to read touch status LSB");
            break;
        }

        if (mp121Read(mp121_fd, TOUCH_STATUS_MSB_REG, &touch_status_msb) < 0) {
            log_error("Failed to read touch status MSB");
            break;
        }

        uint8_t touch_status = (touch_status_msb << 8) | touch_status_lsb;

        if (touch_status & 0x01) {
            relay_state = RELAY_ON;
            log_error("Touch detected, relay ON");
        } else {
            relay_state = RELAY_OFF;
            log_error("Touch released, relay OFF");
        }

        usleep(10000); // 10 ms delay
    }

    pigpiodown();
    close(mp121_fd);
    close(rpi_gpio_fd);

    return EXIT_SUCCESS;
}

