    exit(0);
}

void sigterm_handler(int signum) {
    close(GPIO17);
    close(GPIO18);
    close(GPIO23);
    fclose(stdout);
    remove(LOG_FILE);
    exit(0);
}

int main(int argc, char *argv[]) {
    int fd_gpio = gpiod_get_default_filedesc();
    if (fd_gpio == -1) {
        perror("Failed to get default file descriptor");
        return EXIT_FAILURE;
    }

    gpiod_set_mode(fd_gpio, gpiod_mode_input);
    if (gpiod_try_set_edge_detect(fd_gpio, gpiod_edge_falling) == -1) {
        perror("Failed to set edge detection");
        return EXIT_FAILURE;
    }

    gpiod_edge_detect_enable(fd_gpio);

    gpiod_set_edge_detect_debounce_time(fd_gpio, DEBOUNCE_INTERVAL);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    char timestamp[20] = "Flame Detected at ";
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);
    fprintf(log_file, "%s%s\n", timestamp, "\n");

    while (1) {
        int sensor_state = gpiod_get_value(fd_gpio);
        if (sensor_state == 0) {
            // Flame detected
            fprintf(log_file, "%sFlame Detected\n", timestamp);
            gpiod_edge_detect_enable(fd_gpio, gpiod_edge_falling);
            gpiod_set_edge_detect_debounce_time(fd_gpio, DEBOUNCE_INTERVAL);

            // Activate buzzer and LED
            gpiod_set_value(fd_buzzer, 1);
            gpiod_set_value(fd_led, 1);

            while (1) {
                usleep(100000); // Keep the buzzer and LED on for 100ms
            }

            gpiod_set_value(fd_buzzer, 0);
            gpiod_set_value(fd_led, 0);
        }

        usleep(DEBOUNCE_INTERVAL / 2); // Debounce delay
    }

    fclose(log_file);
    gpiod_set_mode(fd_gpio, gpiod_mode_output);
    gpiod_edge_detect_disable(fd_gpio);
    gpiod_set_edge_detect_debounce_time(fd_gpio, 0);

    return EXIT_SUCCESS;
}
