#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <string.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENABLE_A 24
#define ENABLE_B 25

#define PID_Kp 1.0
#define PID_Ki 0.01
#define PID_Kd 0.1

#define LOG_FILE "balance_log.txt"

void pid_control(float tilt_error, float distance, float &motor_a_speed, float &motor_b_speed) {
    static float integral = 0.0;
    float derivative;

    integral += tilt_error;
    derivative = tilt_error - last_tilt_error;
    last_tilt_error = tilt_error;

    motor_a_speed = PID_Kp * tilt_error + PID_Ki * integral + PID_Kd * derivative;
    motor_b_speed = -motor_a_speed;

    if (distance < 20.0) {
        motor_a_speed = 0.0;
        motor_b_speed = 0.0;
    }
}

int main() {
    int ret;
    pid_t pid;
    struct tm now;
    FILE *log_file;

    pid = pigpioInit(5);
    if (pid < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioErrorText(pigpioGetError(pid)));
        return 1;
    }

    gpioSetMode(ENABLE_A, PIG_OUTPUT);
    gpioSetMode(ENABLE_B, PIG_OUTPUT);
    gpioSetMode(MOTOR_A_FORWARD, PIG_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PIG_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PIG_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PIG_OUTPUT);

    gpioWrite(ENABLE_A, 1);
    gpioWrite(ENABLE_B, 1);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpioTerminate();
        return 1;
    }

    srand(time(NULL));

    while (1) {
        float tilt_error = (float)rand() / RAND_MAX * 20.0 - 10.0;
        float distance = (float)rand() / RAND_MAX * 400.0 + 2.0;

        pid_control(tilt_error, distance, motor_a_speed, motor_b_speed);

        if (motor_a_speed != 0.0 || motor_b_speed != 0.0) {
            gpioPWM(MOTOR_A_FORWARD, 0, motor_a_speed);
            gpioPWM(MOTOR_A_BACKWARD, 0, motor_a_speed);
            gpioPWM(MOTOR_B_FORWARD, 0, motor_b_speed);
            gpioPWM(MOTOR_B_BACKWARD, 0, motor_b_speed);
        }

        time_t now_time = time(NULL);
        struct tm *now_tm = localtime(&now_time);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %f, %f, %f, %f\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_day,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, tilt_error, distance, motor_a_speed, motor_b_speed);

        usleep(50000);
    }

    fclose(log_file);
    pigpioTerminate();
    return 0;
}

