#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define RELAY_PIN 11
#define SENSOR_PIN 7
#define DEBOUNCE_DELAY 50

int main(int argc, char *argv[]) {
    int relay_state = 0;
    int sensor_state = 0;
    int last_state = 0;
    int debounce_timer = 0;
    int sigint_handler_installed = 0;

    pigpio_init(5); // Initialize pigpio with 5-10ms timeout

    if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
        perror("signal(SIGINT, SIG_IGN)");
        exit(1);
    }

    if (signal(SIGTERM, SIG_IGN) == SIG_ERR) {
        perror("signal(SIGTERM, SIG_IGN)");
        exit(1);
    }

    struct sigaction sa;
    sa.sa_handler = handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT, &sa, NULL)");
        exit(1);
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM, &sa, NULL)");
        exit(1);
    }

    while (1) {
        sensor_state = pigpio_get_digital_in(SENSOR_PIN);

        if (sensor_state != last_state) {
            if (sensor_state == 1) {
                relay_state = !relay_state;
                pigpio_set_digital_output(RELAY_PIN, relay_state);
            }

            last_state = sensor_state;
            debounce_timer = 0;
        }

        if (debounce_timer < DEBOUNCE_DELAY) {
            debounce_timer++;
        } else {
            relay_state = !relay_state;
            pigpio_set_digital_output(RELAY_PIN, relay_state);
            debounce_timer = 0;
        }
    }

    pigpio_stop();
    return 0;
}

void handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    pigpio_stop();
    exit(0);
}

