        int samples = 1;
        int period_size = period * samples;

        // Open ALSA device
        int pcm = snd_pcm_open(NULL, "default", SND_PCM_STREAM_INPUT, 0);
        if (pcm == -1) {
            perror("snd_pcm_open");
            return 1;
        }

        // Set ALSA parameters
        snd_pcm_set_format(pcm, format);
        snd_pcm_set_rate_nmips(pcm, rate);
        snd_pcm_set_params(pcm, 0);
        snd_pcm_set_period_size(pcm, period_size);
        snd_pcm_prepare(pcm);

        // Start ALSA stream
        int stream = snd_pcm_open_live(pcm, 0, 0, 0);
        if (stream == -1) {
            perror("snd_pcm_open_live");
            snd_pcm_close(pcm);
            return 1;
        }

        // Start ALSA stream
        snd_pcm_start(stream);

        // Main loop
        while (1) {
            // Capture audio sample
            int samples_read = snd_pcm_avail(stream);
            if (samples_read == 0) {
                if (errno == EPIPE) {
                    snd_pcm_prepare(stream);
                } else if (errno == ESTRPIPE) {
                    snd_pcm_resume(stream);
                }
                continue;
            }

            // Read sample and compute RMS
            double sample = 0;
            for (int i = 0; i < samples_read; i++) {
                sample += (double)snd_pcm_lseek(stream, i * 4, SND_PCM_SEEK_SET);
            }
            rms = sqrt(sample * sample / samples_read);

            // Map RMS to RGB PWM
            amplitude = rms * sensitivity;
            pwm_red = map_to_pwm(amplitude, 0, 1, 0, 255);
            pwm_green = map_to_pwm(amplitude, 0, 1, 0, 255);
            pwm_blue = map_to_pwm(amplitude, 0, 1, 0, 255);

            // Set PWM values
            gpioSetMode(GPIO_RED, PI_OUTPUT);
            gpioSetMode(GPIO_GREEN, PI_OUTPUT);
            gpioSetMode(GPIO_BLUE, PI_OUTPUT);
            gpioPWM(GPIO_RED, pwm_red);
            gpioPWM(GPIO_GREEN, pwm_green);
            gpioPWM(GPIO_BLUE, pwm_blue);

            // Delay
            usleep(10000);
        }
    } else {
        // Simulate ALSA input with sine wave amplitude
        double amplitude = 0.5;
        pwm_red = map_to_pwm(amplitude, 0, 1, 0, 255);
        pwm_green = map_to_pwm(amplitude, 0, 1, 0, 255);
        pwm_blue = map_to_pwm(amplitude, 0, 1, 0, 255);

        // Set PWM values
        gpioSetMode(GPIO_RED, PI_OUTPUT);
        gpioSetMode(GPIO_GREEN, PI_OUTPUT);
        gpioSetMode(GPIO_BLUE, PI_OUTPUT);
        gpioPWM(GPIO_RED, pwm_red);
        gpioPWM(GPIO_GREEN, pwm_green);
        gpioPWM(GPIO_BLUE, pwm_blue);

        // Main loop
        while (1) {
            usleep(10000);
        }
    }

    // Cleanup
    pigpio_terminate(1);
    alsa_close(pcm);
    alsa_stop(stream);
    alsa_suspend(NULL);

    return 0;
}

// Helper function to map a value to PWM
static inline int map_to_pwm(double value, double in_min, double in_max, double out_min, double out_max) {
    return (int)((value - in_min) * (out_max - out_min) / (in_max - in_min) + out_min);
}

// Helper function for pigpio GPIO control
void gpioSetMode(int pin, int mode) {
    if (pigpio_pinMode(pin, mode) == -1) {
        perror("pigpio_pinMode");
        exit(1);
    }
}

void gpioPWM(int pin, int value) {
    if (pigpio_setPWMformat(pin, PI_PWM, 0) == -1) {
        perror("pigpio_setPWMformat");
        exit(1);
    }
    if (pigpio_pwm(pin, value) == -1) {
        perror("pigpio_pwm");
        exit(1);
    }
}
