#define CLEAR_LOW_BYTE 0x14
#define RED_LOW_BYTE 0x15
#define GREEN_LOW_BYTE 0x16
#define BLUE_HIGH_BYTE 0x1A

#define LOG_INTERVAL 500
#define LOG_FILE "color_data.csv"

void sigint_handler(int sig) {
    pigpio_stop();
    printf("Program received SIGINT, exiting...\n");
    exit(0);
}

void sigterm_handler(int sig) {
    pigpio_stop();
    printf("Program received SIGTERM, exiting...\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    int error;
    struct timeval tv;
    time_t timestamp;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    pigpio_init(I2C_BUS);

    error = pigpio_setup(I2C_BUS);
    if (error) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", pigpio_strerror(error));
        return EXIT_FAILURE;
    }

    error = pigpio_setup(I2C_BUS, TCS34725_ADDRESS);
    if (error) {
        fprintf(stderr, "Failed to set up TCS34725: %s\n", pigpio_strerror(error));
        return EXIT_FAILURE;
    }

    error = pigpio_write(I2C_BUS, TCS34725_ADDRESS, 0x80, 0x03);
    if (error) {
        fprintf(stderr, "Failed to write to TCS34725 register 0x80: %s\n", pigpio_strerror(error));
        return EXIT_FAILURE;
    }

    error = pigpio_write(I2C_BUS, TCS34725_ADDRESS, 0x81, 0xD5);
    if (error) {
        fprintf(stderr, "Failed to write to TCS34725 register 0x81: %s\n", pigpio_strerror(error));
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open color_data.csv for appending: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (1) {
        timestamp = time(NULL);
        char timestamp_str[32];
        sprintf(timestamp_str, "%ld", timestamp);

        error = pigpio_read(I2C_BUS, TCS34725_ADDRESS, CLEAR_LOW_BYTE, (uint8_t *)&clear_low, 1);
        if (error) {
            fprintf(stderr, "Failed to read from TCS34725 register 0x14: %s\n", pigpio_strerror(error));
            clear_low = 0;
        } else {
            clear_low = ntohl(*clear_low);
        }

        error = pigpio_read(I2C_BUS, TCS34725_ADDRESS, RED_LOW_BYTE, (uint8_t *)&red_low, 1);
        if (error) {
            fprintf(stderr, "Failed to read from TCS34725 register 0x15: %s\n", pigpio_strerror(error));
            red_low = 0;
        } else {
            red_low = ntohl(*red_low);
        }

        error = pigpio_read(I2C_BUS, TCS34725_ADDRESS, GREEN_LOW_BYTE, (uint8_t *)&green_low, 1);
        if (error) {
            fprintf(stderr, "Failed to read from TCS34725 register 0x16: %s\n", pigpio_strerror(error));
            green_low = 0;
        } else {
            green_low = ntohl(*green_low);
        }

        error = pigpio_read(I2C_BUS, TCS34725_ADDRESS, BLUE_HIGH_BYTE, (uint8_t *)&blue_high, 1);
        if (error) {
            fprintf(stderr, "Failed to read from TCS34725 register 0x1A: %s\n", pigpio_strerror(error));
            blue_high = 0;
        } else {
            blue_high = ntohl(*blue_high);
        }

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, clear_low, red_low, green_low, blue_high);
    }

    fclose(log_file);
    pigpio_stop();
    return EXIT_SUCCESS;
}

