#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>

#define RELAY_PINS_11 11
#define RELAY_PINS_13 13
#define RELAY_PINS_15 15
#define RELAY_PINS_23 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 6 * 60 * 60
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 14.4 * 60 * 60

#define NUM_RELAYS 4

void signal_handler(int signum) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(gpiod_line_get(RELAY_PINS_11 + i), 0);
        gpiod_line_set_value(gpiod_line_get(RELAY_PINS_13 + i), 0);
        gpiod_line_set_value(gpiod_line_get(RELAY_PINS_15 + i), 0);
        gpiod_line_set_value(gpiod_line_get(RELAY_PINS_23 + i), 0);
    }
    gpiod_chip_close(gpiod_chip_open_by_name("gpio"));
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpiod_chip_t *chip;
    gpiod_error_t err;

    err = gpiod_chip_open_by_name("gpio", &chip);
    if (err != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(err));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_t *line;
        err = gpiod_chip_request_output(chip, RELAY_PINS_11 + i, &line);
        if (err != GPIOD_SUCCESS) {
            fprintf(stderr, "Failed to request output on line %d: %s\n",
                    RELAY_PINS_11 + i, gpiod_strerror(err));
            gpiod_line_release(line);
            exit(EXIT_FAILURE);
        }

        err = gpiod_line_set_value(line, 1);
        if (err != GPIOD_SUCCESS) {
            fprintf(stderr, "Failed to set line %d to output: %s\n",
                    RELAY_PINS_11 + i, gpiod_strerror(err));
            gpiod_line_release(line);
            exit(EXIT_FAILURE);
        }
    }

    int current_phase = 0;
    long long phase_duration[4] = {SUNRISE_DURATION, DAYTIME_DURATION,
                                    SUNSET_DURATION, NIGHTTIME_DURATION};
    long long phase_offset = 0;

    while (1) {
        switch (current_phase) {
            case 0: // Sunrise
                for (int i = 0; i < NUM_RELAYS; i++) {
                    long long duty_cycle = phase_offset + (SUNRISE_DURATION / phase_duration[0]) * (phase_offset / SUNRISE_DURATION);
                    duty_cycle = (duty_cycle > 100) ? 100 : duty_cycle;
                    gpiod_line_set_value(gpiod_line_get(RELAY_PINS_11 + i), 1 - duty_cycle / 100);
                }
                phase_offset += SUNRISE_DURATION;
                break;

            case 1: // Daytime
                for (int i = 0; i < NUM_RELAYS; i++) {
                    gpiod_line_set_value(gpiod_line_get(RELAY_PINS_11 + i), 100);
                }
                break;

            case 2: // Sunset
                for (int i = 0; i < NUM_RELAYS; i++) {
                    long long duty_cycle = phase_offset + (SUNSET_DURATION / phase_duration[2]) * (phase_offset / SUNSET_DURATION);
                    duty_cycle = (duty_cycle > 100) ? 100 : duty_cycle;
                    gpiod_line_set_value(gpiod_line_get(RELAY_PINS_11 + i), 1 - duty_cycle / 100);
                }
                phase_offset += SUNSET_DURATION;
                break;

            case 3: // Nighttime
                for (int i = 0; i < NUM_RELAYS; i++) {
                    gpiod_line_set_value(gpiod_line_get(RELAY_PINS_11 + i), 0);
                }
                break;
        }
        current_phase = (current_phase + 1) % 4;
        usleep(1000000); // Sleep for 1 second
    }

    gpiod_chip_close(chip);
    return 0;
}

