    close(LOG_FILE);
    exit(0);
}

void log_motion_event(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s", timestamp);
    fclose(log_file);
}

int main() {
    pigpio_initialize();
    if (!pigpio_init()) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    struct stat video_dir_stat;
    if (stat(VIDEO_DIR, &video_dir_stat) != 0) {
        if (mkdir(VIDEO_DIR, 0755) != 0) {
            perror("Failed to create video directory.");
            pigpio_terminate();
            return 1;
        }
    }

    while (1) {
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&now));
        char video_filename = strcat(VIDEO_DIR, VIDEO_FILENAME_FORMAT);
        char full_video_filename[256];
        sprintf(full_video_filename, "%s%s", video_filename, timestamp);

        if (access(full_video_filename, F_OK) == 0) {
            // File already exists, increment timestamp
            strcat(timestamp, ".1");
        }

        FILE *video_file = fopen(full_video_filename, "w");
        if (!video_file) {
            perror("Failed to open video file.");
            continue;
        }

        // Execute raspivid command
        char command[256];
        sprintf(command, "raspivid -o %s -t 5 -g 640x480", full_video_filename);
        system(command);

        fclose(video_file);
        printf("Motion detected, recording video: %s\n", full_video_filename);

        // Debouncing
        time_t last_debounce = time(NULL);
        while (time(NULL) - last_debounce < DEBOUNCE_INTERVAL) {
            usleep(100000); // 100 ms sleep
        }
        last_debounce = time(NULL);

        log_motion_event(timestamp);
        sleep(1); // Adjust debounce interval as needed
    }

    pigpio_terminate();
    signal(SIGINT, signal_handler);
    return 0;
}
```

This code initializes the pigpio library, sets up a debouncing mechanism, and continuously monitors the Keyes KY-033 sensor on GPIO 17. Upon detecting motion, it records a 5-second video with a timestamp-based filename, logs the event with an ISO 8601 timestamp, and handles errors gracefully. The program can be interrupted with a SIGINT signal (Ctrl+C) to cleanly shut down and terminate pigpio.

