        sleep(SAMPLE_INTERVAL / 1000.0);
    }

    i2c_close(i2c_fd);
    i2c_client_free(client);
    pigpio_terminate(1);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

