#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PINS {4, 17, 27, 22}
#define LOG_FILE "irrigation_log.txt"
#define MOISTURE_READING_INTERVAL 5000 // 5 seconds in milliseconds

void log_moisture_reading(int zone, int reading) {
    time_t now = time(NULL);
    char timestamp[80];
    sprintf(timestamp, "%ld:%02d:%02d", now / 3600, now % 3600, (int)(now % 60));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s: Zone %d - Moisture: %d - Relay: %d\n", timestamp, zone + 1, reading, (reading < 30) ? 0 : 1);
    fclose(log_file);
}

void signal_handler(int signum) {
    for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        piGPIOsetMode(RELAY_PINS[i], PI_OUTPUT);
    }
    for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        piGPIOwrite(RELAY_PINS[i], PI_HIGH);
    }
    fclose(stdout);
    pigpioTerminate();
    exit(0);
}

int main() {
    if (pigpioInit() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    signal(SIGINT, signal_handler);

    for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        piGPIOsetMode(RELAY_PINS[i], PI_OUTPUT);
    }

    while (1) {
        int moisture_reading = rand() % 101;
        log_moisture_reading(0, moisture_reading);
        for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
            piGPIOwrite(RELAY_PINS[i], (moisture_reading < 30) ? PI_LOW : PI_HIGH);
        }
        usleep(MOISTURE_READING_INTERVAL / 1000);
    }

    return 0;
}

