#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>

#define I2C_ADDR 0x53
#define DATA_FORMAT 0x0B
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define FREEFALL_THRESHOLD 0.2
#define DELAY_SECONDS 0.5
#define LOG_INTERVAL_MS 100
#define LOG_FILE "freefall.log"
#define LOG_FORMAT "YYYY-MM-DD HH:MM:SS,x,y,z\n"

#define GPIO_PIN 27

#define SCALE_FACTOR 256

void freefall_handler(int signum) {
    piGPIOsetMode(GPIO_PIN, PI_OUTPUT);
    piGPIOlow(GPIO_PIN);
    sleep(5);
    piGPIOlow(GPIO_PIN);
    printf("Freefall detected, exiting...\n");
    exit(0);
}

void init_pigpio() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (piI2Csetup(I2C_ADDR, 100000) < 0) {
        fprintf(stderr, "Failed to setup I2C\n");
        pigpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void read_accelerometer() {
    int data[6];
    int i;

    for (i = 0; i < 6; i++) {
        if (piI2Ctransfer(I2C_ADDR, DATAX0 + i, 2, data + i) < 0) {
            fprintf(stderr, "I2C transfer failed\n");
            return;
        }
    }

    int x = (data[0] << 8) | data[1];
    int y = (data[2] << 8) | data[3];
    int z = (data[4] << 8) | data[5];

    int g_force_x = x * SCALE_FACTOR;
    int g_force_y = y * SCALE_FACTOR;
    int g_force_z = z * SCALE_FACTOR;

    if (abs(g_force_x) < FREEFALL_THRESHOLD && abs(g_force_y) < FREEFALL_THRESHOLD && abs(g_force_z) < FREEFALL_THRESHOLD) {
        printf("%s", LOG_FORMAT + 12);
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        printf("%d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, g_force_x, g_force_y, g_force_z);
    }
}

int main() {
    signal(SIGINT, freefall_handler);

    init_pigpio();

    while (1) {
        read_accelerometer();
        usleep(LOG_INTERVAL_MS / 1000);
    }

    pigpioTerminate();
    return 0;
}

