    int g_force_x = x * SCALE_FACTOR;
    int g_force_y = y * SCALE_FACTOR;
    int g_force_z = z * SCALE_FACTOR;

    if (abs(g_force_x) < FREEFALL_THRESHOLD && abs(g_force_y) < FREEFALL_THRESHOLD && abs(g_force_z) < FREEFALL_THRESHOLD) {
        printf("%s", LOG_FORMAT + 12);
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        printf("%d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, g_force_x, g_force_y, g_force_z);
    }
}

int main() {
    signal(SIGINT, freefall_handler);

    init_pigpio();

    while (1) {
        read_accelerometer();
        usleep(LOG_INTERVAL_MS / 1000);
    }

    pigpioTerminate();
    return 0;
}
