#define MAX_DISTANCE_CM 4000
#define LOG_FILE "distance_log.txt"
#define MAX_LOG_SIZE 1000000

#define BUFFER_SIZE 1024

#define MAX_EVENTS 10

#define MAX_TIMEOUT_US 100000000

#define MAX_LOG_ENTRIES 1000

typedef struct {
    atomic_int count;
    atomic_int max_count;
    atomic_int current_count;
    atomic_int timestamp_ns;
    char timestamp_str[100];
    char distance_str[100];
} LogEntry;

static LogEntry log_entries[MAX_LOG_ENTRIES];
static int log_file_fd = -1;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static void log_entry(const char *timestamp_str, int distance_cm) {
    LogEntry *entry = &log_entries[log_entries.current_count];
    entry->count++;
    if (entry.count > MAX_LOG_ENTRIES) {
        entry.current_count = entry.max_count;
        entry.max_count++;
    }
    strncpy(entry.timestamp_str, timestamp_str, 100);
    snprintf(entry.distance_str, 100, "%d", distance_cm);
    if (log_file_fd < 0) {
        log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_file_fd < 0) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
    }
    write(log_file_fd, timestamp_str, strlen(timestamp_str));
    write(log_file_fd, "\n", 1);
    write(log_file_fd, distance_str, strlen(distance_str));
    write(log_file_fd, "\n", 1);
    if (log_file_fd < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (log_file_fd >= 0) {
        fsync(log_file_fd);
    }
}

static void signal_handler(int signum) {
    if (log_file_fd >= 0) {
        close(log_file_fd);
        log_file_fd = -1;
    }
    pigpio_terminate();
    pthread_mutex_destroy(&mutex);
    exit(signum == SIGINT ? 0 : EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <signal>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);

    pigpio_init(1);
    if (pigpio_init(1) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_strerror());
        exit(EXIT_FAILURE);
    }

    int log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = MAX_TIMEOUT_US / 1000000;

    int epoll_fd = epoll_create1(0);
    if (epoll_fd < 0) {
        fprintf(stderr, "Failed to create epoll instance: %s\n", strerror(errno));
        close(log_file_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    struct epoll_event event;
    event.events = EPOLLIN;
    event.data.fd = log_file_fd;

    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, log_file_fd, &event) < 0) {
        fprintf(stderr, "Failed to add log file to epoll: %s\n", strerror(errno));
        close(epoll_fd);
        close(log_file_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct timespec timeout;
        timeout.tv_sec = 0;
        timeout.tv_nsec = INTERVAL_MS / 1000;

        int events = epoll_wait(epoll_fd, &event, MAX_EVENTS, -1, &timeout);
        if (events == -1) {
            if (errno == EAGAIN || errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error in epoll_wait: %s\n", strerror(errno));
            break;
        }

        if (event.data.fd == log_file_fd) {
            char buffer[BUFFER_SIZE];
            ssize_t n = read(log_file_fd, buffer, BUFFER_SIZE);
            if (n <= 0) {
                fprintf(stderr, "Error reading from log file\n");
                break;
            }
            buffer[n] = '\0';
            log_entry(buffer, atoi(strtok(buffer, ",\n")));
        }
    }

    pigpio_terminate();
    close(log_file_fd);
    epoll_destroy(epoll_fd);
    pthread_mutex_destroy(&mutex);

    return 0;
}

