#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x18
#define BUZZER_GPIO 17
#define SENSITIVITY 16384
#define FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5

void fall_detection(int *fall_count, int *impact_count);
void read_acceleration(int *ax, int *ay, int *az);
void activate_buzzer(int duration);

int main(int argc, char *argv[]) {
    int i2c_fd, ret, buzzer_state, fall_count = 0, impact_count = 0;
    struct i2c_client *client;
    int ctrl_reg1, ctrl_reg4, out_x_l;
    int ax, ay, az;

    if (argc > 1) {
        fall_threshold = atoi(argv[1]);
        impact_threshold = atoi(argv[2]);
    }

    client = i2c_open(I2C_BUS, I2C_ADDR);
    if (client == NULL) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    ctrl_reg1 = 0x77;
    ctrl_reg4 = 0x00;
    out_x_l = 0x28;

    for (int i = 0; i < 3; i++) {
        ret = i2c_write_reg(client, I2C_ADDR, ctrl_reg1);
        if (ret == -1) {
            perror("i2c_write_reg");
            i2c_close(client);
            exit(EXIT_FAILURE);
        }

        ret = i2c_write_reg(client, I2C_ADDR, ctrl_reg4);
        if (ret == -1) {
            perror("i2c_write_reg");
            i2c_close(client);
            exit(EXIT_FAILURE);
        }

        ret = i2c_read_byte_range(client, I2C_ADDR, out_x_l, 2);
        if (ret == -1) {
            perror("i2c_read_byte_range");
            i2c_close(client);
            exit(EXIT_FAILURE);
        }

        ax = (int)(ret & 0xFF);
        ay = (int)((ret >> 8) & 0xFF);
        az = (int)((ret >> 16) & 0xFF);

        if (ret & 0x8000) {
            printf("I2C read error, retrying...\n");
            continue;
        }

        break;
    }

    if (ret == -1) {
        perror("i2c_read_byte_range");
        i2c_close(client);
        exit(EXIT_FAILURE);
    }

    activate_buzzer(1000); // Activate buzzer for 1 second

    while (1) {
        read_acceleration(&ax, &ay, &az);

        if (abs(ax) > FALL_THRESHOLD || abs(ay) > FALL_THRESHOLD || abs(az) > FALL_THRESHOLD) {
            fall_count++;
            printf("Fall detected! Count: %d\n", fall_count);
        }

        if (abs(ax) > IMPACT_THRESHOLD || abs(ay) > IMPACT_THRESHOLD || abs(az) > IMPACT_THRESHOLD) {
            impact_count++;
            printf("Impact detected! Count: %d\n", impact_count);
            activate_buzzer(1000); // Activate buzzer for 1 second
        }

        usleep(100000); // Sleep for 100ms
    }

    deactivate_buzzer();
    i2c_close(client);
    pigpio_terminate(1000);

    return 0;
}

void fall_detection(int *fall_count, int *impact_count) {
    (*fall_count)++;
    (*impact_count) = 0;
}

void read_acceleration(int *ax, int *ay, int *az) {
    int reg_out_x_l;
    reg_out_x_l = i2c_read_byte_range(client, I2C_ADDR, 0x28, 2);
    *ax = (int)(reg_out_x_l & 0xFF);
    *ay = (int)((reg_out_x_l >> 8) & 0xFF);
    *az = (int)((reg_out_x_l >> 16) & 0xFF);
}

void activate_buzzer(int duration) {
    buzzer_state = pigpio_getmode(BUZZER_GPIO);
    if (buzzer_state == PI_OUTPUT) {
        pigpio_putmode(BUZZER_GPIO, PI_OUTPUT);
        pigpio_write(BUZZER_GPIO, 1);
        usleep(duration * 100000);
        pigpio_write(BUZZER_GPIO, 0);
        pigpio_putmode(BUZZER_GPIO, buzzer_state);
    }
}

void deactivate_buzzer() {
    pigpio_putmode(BUZZER_GPIO, PI_OUTPUT);
    pigpio_write(BUZZER_GPIO, 0);
}

