#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_ADDR 0x18
#define DEFAULT_THRESHOLD 2.0f

void sigint_handler(int signum) {
    printf("SIGINT received, shutting down...\n");
    pigpio_stop();
    exit(0);
}

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_addr_t i2c_addr;
    pigpio_t *pi;
    float threshold = DEFAULT_THRESHOLD;

    // Signal handler setup
    signal(SIGINT, sigint_handler);

    // Validate I2C address and threshold
    if (argc < 2 || argc > 3) {
        fprintf(stderr, "Usage: %s [-a <I2C_ADDR>] [-t <THRESHOLD>]\n", argv[0]);
        return 1;
    }

    if (argc > 2) {
        threshold = atof(argv[2]);
        if (threshold <= 0.0) {
            fprintf(stderr, "Error: Threshold must be greater than 0.0\n");
            return 1;
        }
    }

    // Set I2C address
    if (sscanf(argv[1], "%x", &i2c_addr.reg) != 1 || i2c_addr.reg < 0x08 || i2c_addr.reg > 0x77) {
        fprintf(stderr, "Error: Invalid I2C address. Must be between 0x08 and 0x77.\n");
        return 1;
    }

    // Initialize pigpio
    pi = pigpio_init(1);
    if (!pi) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(pi, "i2c-1");
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        pigpio_stop();
        return 1;
    }

    // Write configuration to accelerometer
    if (i2cWriteByteData(i2c_fd, I2C_ADDR, 0x57) != 1) {
        perror("Failed to write CTRL_REG1");
        i2cClose(i2c_fd);
        pigpio_stop();
        return 1;
    }
    if (i2cWriteByteData(i2c_fd, I2C_ADDR, 0x88) != 1) {
        perror("Failed to write CTRL_REG4");
        i2cClose(i2c_fd);
        pigpio_stop();
        return 1;
    }

    // Read acceleration data
    float x, y, z;
    while (1) {
        ret = i2cReadI2CBlockData(i2c_fd, I2C_ADDR, 0x28, 2, &x, 1, 100);
        if (ret < 0) {
            perror("Failed to read acceleration data");
            continue;
        }

        // Convert raw data to g
        x *= 0.0009765625;
        y *= 0.0009765625;
        z *= 0.0009765625;

        // Check for high acceleration
        if (abs(x) > threshold || abs(y) > threshold || abs(z) > threshold) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            char log_msg[100];
            sprintf(log_msg, "High acceleration at %f, %f, %f\n", x, y, z);
            int log_fd = open("/var/log/high_acceleration.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
            if (log_fd < 0) {
                perror("Failed to open log file");
                continue;
            }
            write(log_fd, log_msg, strlen(log_msg));
            write(log_fd, "\n", 1);
            write(log_fd, "(Timestamp: ", 14);
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            double micros = (now.tv_sec * 1000000 + now.tv_nsec) / 1000;
            sprintf(log_msg + 14, "%lu", micros);
            write(log_fd, "\n", 1);
            write(log_fd, "\n", 1);
            write(log_fd, "  ", 2);
            write(log_fd, "g", 1);
            write(log_fd, " ", 1);
            write(log_fd, x, 8);
            write(log_fd, " ", 1);
            write(log_fd, y, 8);
            write(log_fd, " ", 1);
            write(log_fd, z, 8);
            write(log_fd, "\n", 1);
            write(log_fd, "\n", 1);
            write(log_fd, "Triggering shutdown...", 18);
            system("sudo shutdown -h now");
        }
    }

    // Close I2C and pigpio
    i2cClose(i2c_fd);
    pigpio_stop(pi);

    return 0;
}

