                break;
            }
            poll_attempts++;
            usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
        }

        if (poll_attempts >= MAX_POLL_ATTEMPTS) {
            log_event("Timeout reading conversion status", get_iso8601_timestamp(), relay_state);
            relay_state = 0;
            continue;
        }

        field_raw = i2cReadByteData(I2C_BUS, SILICON_LABS_ID, 0xC0);
        field_mT_x100 = (field_raw << 8) | (field_raw >> 8);
        field_mT_x100 *= 25 / 1000;

        if (field_mT_x100 >= THRESHOLD_mT * 100) {
            log_event("Field strength exceeded threshold", get_iso8601_timestamp(), relay_state);
            relay_state = 1;
            gpioWrite(RELAY_GPIO, 1);
        } else {
            log_event("Field strength below threshold", get_iso8601_timestamp(), relay_state);
            gpioWrite(RELAY_GPIO, 0);
        }

        i2cWriteByte(I2C_BUS, SILICON_LABS_ID, 0xC1);
        poll_attempts = 0;

        if (relay_state == 1) {
            log_event("Relay activated", get_iso8601_timestamp(), relay_state);
        } else {
            log_event("Relay deactivated", get_iso8601_timestamp(), relay_state);
        }
    }

    log_event("Exiting", get_iso8601_timestamp(), relay_state);
    gpioTerminate();
    i2cClose(I2C_BUS);
    pigpioTerminate();
    return EXIT_SUCCESS;
