void sigint_handler(int sig) {
    log_event("Received SIGINT, shutting down", get_iso8601_timestamp(), relay_state);
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(I2C_BUS);
    pigpioTerminate();
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    return main();
}

