#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>

#define PORT 5000
#define RELAY_GPIO 18
#define LOG_FILE "relay_log.txt"

void log_event(const char *event) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fclose(log_file);
    }
}

int main() {
    pigpio_init(5); // Initialize pigpio with 5 seconds timeout
    if (!pigpio_init(5)) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %s", pigpio_strerror(pigpio_last_error()));
        return 1;
    }

    int server_fd, new_socket;
    struct sockaddr_in address;
    socklen_t addr_len = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, addr_len) < 0) {
        perror("bind failed");
        return 1;
    }

    if (listen(server_fd, 5) < 0) {
        perror("listen failed");
        return 1;
    }

    syslog(LOG_INFO, "Server listening on port %d\n", PORT);

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, &addr_len)) < 0) {
            perror("accept failed");
            return 1;
        }

        char command[64];
        log_event("Client connected");
        read(new_socket, command, 64);
        command[strcspn(command, "\n")] = 0; // Remove trailing newline

        if (strcmp(command, "ON") == 0 || strcmp(command, "off") == 0) {
            command[strcspn(command, " off")] = 0; // Normalize "OFF" to "off"
            log_event("Received command: %s", command);

            if (strcmp(command, "OFF") == 0) {
                gpioSetMode(RELAY_GPIO, PI_OUTPUT);
            } else {
                gpioSetMode(RELAY_GPIO, PI_INPUT);
                gpioWrite(RELAY_GPIO, 1); // Turn on relay
            }

            log_event("Relay state changed: ON");
            write(new_socket, "OK\n", 4); // Acknowledge the command
        } else {
            log_event("Invalid command: %s", command);
            write(new_socket, "INVALID_COMMAND\n", 20); // Send error message
        }

        close(new_socket);
    }

    piggpio_terminate(); // Terminate pigpio
    syslog(LOG_INFO, "Pigpio terminated\n");

    close(server_fd);
    syslog(LOG_INFO, "Server closed\n");

    syslog(LOG_INFO, "Shutting down gracefully...");
    sleep(5); // Give a short delay to allow any pending operations to complete

    syslog(LOG_INFO, "Exiting...");
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    close(LOG_FILE); // Close log file
    return 0;
}

