#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define GPIO_PIN 18
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

#define LOG_FILE "flow_log.txt"

int main(int argc, char *argv[]) {
    int i2c_fd1, i2c_fd2, gpio_fd, ret;
    struct i2c_client *i2c_clients[2];
    struct timeval tv;
    char log_msg[1024];

    pigpio_init(1); // Initialize pigpio with I2C bus 1

    // Open I2C handles
    i2c_fd1 = i2c_open_channel(I2C_BUS);
    i2c_fd2 = i2c_open_channel(I2C_BUS);

    if (i2c_fd1 == -1 || i2c_fd2 == -1) {
        perror("Failed to open I2C bus");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    // Configure GPIO 18 as output
    ret = gpioSetup(GPIO_PIN, GPIO_OUTPUT);
    if (ret == -1) {
        perror("Failed to configure GPIO 18");
        pigpio_terminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0); // De-energize

    // Send start-measurement command to both sensors
    char start_cmd[3] = {0x36, 0x08, 0x00};
    ret = i2cWrite(i2c_fd1, start_cmd, 3);
    if (ret != 3) {
        fprintf(stderr, "Failed to send start command to sensor 1\n");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    ret = i2cWrite(i2c_fd2, start_cmd, 3);
    if (ret != 3) {
        fprintf(stderr, "Failed to send start command to sensor 2\n");
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    // Read data from both sensors
    while (1) {
        // Read 3 bytes from each sensor
        char data1[3], data2[3];
        ret = i2cRead(i2c_fd1, data1, 3);
        if (ret != 3) {
            fprintf(stderr, "Failed to read from sensor 1\n");
            continue;
        }

        ret = i2cRead(i2c_fd2, data2, 3);
        if (ret != 3) {
            fprintf(stderr, "Failed to read from sensor 2\n");
            continue;
        }

        // Validate CRC-8
        unsigned int crc1 = 0xFF;
        unsigned int crc2 = 0xFF;
        for (int i = 0; i < 3; i++) {
            crc1 = (crc1 << 8) ^ data1[i];
            crc2 = (crc2 << 8) ^ data2[i];
        }
        for (int i = 0; i < 2; i++) {
            crc1 = (crc1 << 1) ^ (crc1 >> 7);
            crc2 = (crc2 << 1) ^ (crc2 >> 7);
        }
        crc1 ^= crc2;
        if (crc1 != 0) {
            fprintf(stderr, "CRC mismatch detected\n");
            continue;
        }

        // Convert raw values to ml/min
        int raw1 = (data1[0] << 8) | data1[1];
        int raw2 = (data2[0] << 8) | data2[1];
        double flow1 = (raw1 * 1.0) / 1500.0;
        double flow2 = (raw2 * 1.0) / 1500.0;

        // Check if either flow is below 5.0 ml/min
        if (flow1 < 5.0 || flow2 < 5.0) {
            gpioWrite(GPIO_PIN, 1); // Energize relay
        } else {
            gpioWrite(GPIO_PIN, 0); // De-energize relay
        }

        // Log successful cycle
        time(NULL) & tv;
        strftime(log_msg, sizeof(log_msg), "%.3f\t%d\n", (double)flow1, tv.tv_sec);
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open flow_log.txt");
        } else {
            fwrite(log_msg, sizeof(char), strlen(log_msg), log_file);
            fclose(log_file);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up and exit
    pigpio_terminate();
    close(i2c_fd1);
    close(i2c_fd2);
    gpioTerminate();

    return EXIT_SUCCESS;
}

