#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define BUTTON_A_PIN 21
#define BUTTON_B_PIN 22
#define BUTTON_DEBOUNCE_DELAY 50

int servo_locked = 0;
int button_state_A = 0;
int button_state_B = 0;

void button_debounce(int pin) {
    static int last_time = 0;
    int current_time = millis();
    if (current_time - last_time > BUTTON_DEBOUNCE_DELAY) {
        last_time = current_time;
        button_state_A = gpioRead(pin);
        button_state_B = gpioRead(pin);
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpioServo(SERVO_PIN, 0); // Stop servo
        gpioTerminate();
        exit(0);
    }
}

int main() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(SERVO_PIN, PIGO_OUTPUT);
    gpioSetMode(BUTTON_A_PIN, PIGO_INPUT);
    gpioSetMode(BUTTON_B_PIN, PIGO_INPUT);
    gpioInstallSignalHandler(SIGINT, signal_handler);
    gpioInstallSignalHandler(SIGTERM, signal_handler);

    while (1) {
        button_debounce(BUTTON_A_PIN);
        button_debounce(BUTTON_B_PIN);

        if (button_state_A == 0) {
            gpioServo(SERVO_PIN, 2000); // Lock
            printf("Lock\n");
        } else if (button_state_B == 0) {
            gpioServo(SERVO_PIN, 1000); // Unlock
            printf("Unlock\n");
        } else {
            printf("No button pressed\n");
        }

        usleep(100000); // Poll every 100ms
    }

    gpioTerminate();
    return 0;
}

