#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PIR_PIN 7
#define RELAY_PIN 11
#define POLL_INTERVAL_MS 100
#define LOG_FILE "security_log.txt"

void log_event(const char *event_type, long timestamp) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp_str[80];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%T", local_time);
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }
    fprintf(file, "%s, %ld\n", event_type, (long)time(NULL));
    fclose(file);
}

void handle_pi_error(const char *msg) {
    fprintf(stderr, "PigPIO error: %s\n", msg);
    gpioRelease();
}

void signal_handler(int signum) {
    log_event("deactivate", time(NULL));
    gpioWrite(RELAY_PIN, 0);
    gpioRelease();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (signal(SIGINT, signal_handler) == SIG_IGN || signal(SIGTERM, signal_handler) == SIG_IGN) {
        fprintf(stderr, "Failed to set signal handler\n");
        return 1;
    }

    if (gpioInit() < 0) {
        handle_pi_error("Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    while (1) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state == PI_RISING_EDGE) {
            log_event("activate", time(NULL));
            gpioWrite(RELAY_PIN, 1);
            sleep(60);
            gpioWrite(RELAY_PIN, 0);
            log_event("deactivate", time(NULL));
        }

        usleep(POLL_INTERVAL_MS * 1000 / HRTOPS);
    }

    gpioRelease();
    return 0;
}

