#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define RELAY_GPIO 17
#define MPR121_I2C_BUS 1
#define MPR121_ADDR 0x5A

void init_pigpio(void) {
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

int init_i2c(void) {
    int file;
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        if (errno == ENODEV) {
            fprintf(stderr, "I2C device not found\n");
            return -1;
        }
        perror("open /dev/i2c-1");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, MPR121_ADDR) < 0) {
        close(file);
        perror("ioctl I2C_SLAVE");
        return -1;
    }

    return 0;
}

void release_resources(void) {
    piGPIO_terminate();
    close(piGPIO_fd);
}

int main(int argc, char *argv[]) {
    int relay_state = 0;
    int i2c_fd, i2c_result;
    int mp121_touch_status;
    uint8_t mp121_config_reg[2];
    uint16_t mp121_touch_status_reg;

    init_pigpio();
    init_i2c();

    if (relay_state != 0) {
        piDigitalWrite(RELAY_GPIO, relay_state);
    }

    while (1) {
        // Soft reset MPR121
        mp121_config_reg[0] = 0x00;
        mp121_config_reg[1] = 0x00;
        if (write(piI2C_fd, mp121_config_reg, 2) != 2) {
            fprintf(stderr, "Failed to write soft reset to MPR121\n");
            release_resources();
            exit(EXIT_FAILURE);
        }

        // Configure baseline filtering
        mp121_config_reg[0] = 0x01; // MHD
        mp121_config_reg[1] = 0x00;
        if (write(piI2C_fd, mp121_config_reg, 2) != 2) {
            fprintf(stderr, "Failed to configure baseline filtering\n");
            release_resources();
            exit(EXIT_FAILURE);
        }

        // Set debounce
        mp121_config_reg[0] = 0x00;
        mp121_config_reg[1] = 0x5B;
        if (write(piI2C_fd, mp121_config_reg, 2) != 2) {
            fprintf(stderr, "Failed to set debounce\n");
            release_resources();
            exit(EXIT_FAILURE);
        }

        // Set FFI/SFI/CDT
        mp121_config_reg[0] = 0x00;
        mp121_config_reg[1] = 0x2C;
        if (write(piI2C_fd, mp121_config_reg, 2) != 2) {
            fprintf(stderr, "Failed to set FFI/SFI/CDT\n");
            release_resources();
            exit(EXIT_FAILURE);
        }

        // Enable auto-config
        mp121_config_reg[0] = 0x00;
        mp121_config_reg[1] = 0x7B;
        if (write(piI2C_fd, mp121_config_reg, 2) != 2) {
            fprintf(stderr, "Failed to enable auto-config\n");
            release_resources();
            exit(EXIT_FAILURE);
        }

        // Enable 12 electrodes
        mp121_config_reg[0] = 0x00;
        mp121_config_reg[1] = 0x0C;
        if (write(piI2C_fd, mp121_config_reg, 2) != 2) {
            fprintf(stderr, "Failed to enable 12 electrodes\n");
            release_resources();
            exit(EXIT_FAILURE);
        }

        // Read touch status
        if (read(piI2C_fd, &mp121_touch_status_reg, 2) != 2) {
            fprintf(stderr, "Failed to read touch status\n");
            release_resources();
            exit(EXIT_FAILURE);
        }

        // Check for touch on electrode 0
        if (mp121_touch_status_reg & (1 << 0)) {
            // Touch detected, toggle relay
            relay_state = !relay_state;
            if (relay_state == 1) {
                piDigitalWrite(RELAY_GPIO, 1);
            } else {
                piDigitalWrite(RELAY_GPIO, 0);
            }
        }

        // 200 ms debounce
        usleep(200000);
    }

    release_resources();
    return 0;
}

