void log_message(const char *format, ...) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(&now));
    va_list args;
    va_start(args, format);
    vsnprintf(log_buffer, sizeof(log_buffer), format, args);
    va_end(args);
    syslog(LOG_USER, "%s - %s", timestamp, log_buffer);
    of_log_append(log_buffer);
}

void handle_servo_command(const char *command) {
    int angle;
    sscanf(command, "SERVO %d", &angle);
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        log_message("Invalid servo angle: %d\n", angle);
        return;
    }
    gpiod_line_set_value(SERVO_GPIO, angle / 2); // Convert to 0-1 range
    log_message("SERVO %d\n", angle);
}

void handle_pir_command(const char *command) {
    if (strcmp(command, "PIR") == 0) {
        int pir_state;
        pir_state = read(PIR_GPIO, &pir_state, 1);
        if (pir_state == 1) {
            log_message("PIR:1\n");
        } else {
            log_message("PIR:0\n");
        }
    } else {
        log_message("Invalid command: %s\n", command);
    }
}

