#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define RELAY_PIN 23
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL 2000000  // 2 seconds in microseconds
#define MAX_LOG_SIZE 1024

void log_entry(const char *entry) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open grow_log.txt");
        return;
    }
    fprintf(fp, "%s", entry);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int i2c_fd, relay_state;
    struct i2c_client i2c_client;
    struct timeval tv;
    double lux, timestamp;
    char log_entry[MAX_LOG_SIZE];

    gpioTerminate();
    if (pigpioSystemInit(I2C_BUS) < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    i2c_client.device = I2C_ADDR;
    if (i2cOpen(I2C_BUS, &i2c_client) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    while (1) {
        tv.tv_sec = 0;
        tv.tv_usec = SAMPLE_INTERVAL / 1000000;
        if (select(0, NULL, NULL, NULL, &tv) == -1) {
            perror("select failed");
            continue;
        }

        if (tv.tv_sec > 0) {
            // Read BH1750 data
            if (i2cWriteByte(i2c_fd, 0x20) < 0) {
                perror("Failed to write command to BH1750");
                log_entry("Failed to write command to BH1750");
                continue;
            }

            if (i2cReadDevice(i2c_fd, 0, 1) < 0) {
                perror("Failed to read BH1750 data");
                log_entry("Failed to read BH1750 data");
                continue;
            }

            lux = (double)(i2cReadByte(i2c_fd) << 8) / 1.2;
            timestamp = microtime_ms();

            if (lux < 150) {
                relay_state = GPIO_OUTPUT;
                gpioWrite(relay_state, RELAY_PIN);
                log_entry(fprintf(log_entry, "lux: %.2f, time: %lu\n", lux, timestamp));
            } else {
                relay_state = GPIO_INPUT;
                gpioWrite(relay_state, RELAY_PIN);
                log_entry(fprintf(log_entry, "lux: %.2f, time: %lu\n", lux, timestamp));
            }
        }
    }

    close(i2c_fd);
    gpioTerminate();
    log_entry("Program terminated.");
    return EXIT_SUCCESS;
}

