#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO23 16
#define GPIO24 18
#define GPIO25 22

#define TARE_READINGS 10
#define MAX_RETRIES 3
#define POLL_INTERVAL 500
#define THRESHOLD_ARG "--threshold"
#define SCALE_ARG "--scale"
#define DURATION_ARG "--duration"

int solenoid_gpio = 25;
int tare_gpio = 17; // Tare pin, if needed

void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
    fprintf(stderr, "%s", msg);
}

void log_info(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
    fprintf(stdout, "%s", msg);
}

int setup_gpio(const char *gpio_str) {
    int fd;
    int ret;

    fd = open(gpio_str, O_RDWR | O_CREATE | O_EXCL);
    if (fd == -1) {
        log_error("Failed to open GPIO file: %s", strerror(errno));
        return -1;
    }

    ret = gpio_set_mode(fd, GPIO_OUTPUT);
    if (ret == -1) {
        log_error("Failed to set GPIO mode: %s", strerror(errno));
        close(fd);
        return -1;
    }

    ret = gpio_set_drv(fd, gpio_get_driver(fd));
    if (ret == -1) {
        log_error("Failed to set GPIO driver: %s", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int read_hx711(int fd) {
    unsigned int data;
    int ret;

    ret = gpio_get_level(GPIO23);
    if (ret == -1) {
        log_error("Failed to read DOUT: %s", strerror(errno));
        return -1;
    }

    if (ret != LOW) {
        log_error("DOUT did not go LOW within 1 second");
        return -1;
    }

    ret = gpio_write(GPIO24, 0);
    if (ret == -1) {
        log_error("Failed to clock out data: %s", strerror(errno));
        return -1;
    }

    ret = gpio_write(GPIO24, 1);
    if (ret == -1) {
        log_error("Failed to clock out data: %s", strerror(errno));
        return -1;
    }

    ret = gpio_wait_for_bit(GPIO23, LOW);
    if (ret == -1) {
        log_error("DOUT did not go LOW within 1 second");
        return -1;
    }

    ret = gpio_write(GPIO24, 24);
    if (ret == -1) {
        log_error("Failed to send 24 bits: %s", strerror(errno));
        return -1;
    }

    ret = gpio_write(GPIO24, 1);
    if (ret == -1) {
        log_error("Failed to send clock pulse: %s", strerror(errno));
        return -1;
    }

    ret = gpio_read(GPIO23);
    if (ret == -1) {
        log_error("Failed to read data: %s", strerror(errno));
        return -1;
    }

    data = ret;
    return data;
}

int convert_hx711_to_weight(int raw_data) {
    int weight = (raw_data << 1) - 1024;
    return weight;
}

int average_readings(int *readings, int count, int *average) {
    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum += readings[i];
    }
    *average = sum / count;
    return 0;
}

int main(int argc, char *argv[]) {
    int threshold, scale, duration;
    int ret;
    int tare_readings[TARE_READINGS];
    int total_weight = 0;
    int average_weight;
    int retries = 0;

    while (1) {
        if (argc > 1 && strcmp(argv[1], THRESHOLD_ARG) == 0) {
            threshold = atoi(argv[2]);
        }
        if (argc > 2 && strcmp(argv[2], SCALE_ARG) == 0) {
            scale = atoi(argv[3]);
        }
        if (argc > 3 && strcmp(argv[3], DURATION_ARG) == 0) {
            duration = atoi(argv[4]);
        }

        ret = setup_gpio(GPIO23);
        if (ret != 0) {
            exit(EXIT_FAILURE);
        }

        ret = setup_gpio(GPIO24);
        if (ret != 0) {
            exit(EXIT_FAILURE);
        }

        ret = setup_gpio(GPIO25);
        if (ret != 0) {
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO23, LOW);
        if (ret == -1) {
            log_error("Failed to set DOUT to LOW: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO25, LOW);
        if (ret == -1) {
            log_error("Failed to set solenoid to LOW: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO23, HIGH);
        if (ret == -1) {
            log_error("Failed to set DOUT to HIGH: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO25, HIGH);
        if (ret == -1) {
            log_error("Failed to set solenoid to HIGH: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO23, LOW);
        if (ret == -1) {
            log_error("Failed to set DOUT to LOW: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO25, LOW);
        if (ret == -1) {
            log_error("Failed to set solenoid to LOW: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = read_hx711(GPIO24);
        if (ret == -1) {
            retries++;
            if (retries > MAX_RETRIES) {
                log_error("Failed to read from HX711 after %d retries", MAX_RETRIES);
                exit(EXIT_FAILURE);
            }
            continue;
        }

        tare_readings[0] = read_hx711(GPIO24);
        for (int i = 1; i < TARE_READINGS; i++) {
            ret = read_hx711(GPIO24);
            if (ret == -1) {
                retries++;
                if (retries > MAX_RETRIES) {
                    log_error("Failed to read from HX711 after %d retries", MAX_RETRIES);
                    exit(EXIT_FAILURE);
                }
                continue;
            }
            tare_readings[i] = ret;
        }

        average_readings(tare_readings, TARE_READINGS, &average_weight);
        total_weight = average_weight * scale;

        if (total_weight > threshold) {
            log_info("Weight exceeds threshold: %d grams", total_weight);
            gpio_set_level(GPIO25, HIGH);
            usleep(duration * 1000);
            gpio_set_level(GPIO25, LOW);
        }

        gpio_set_level(GPIO23, LOW);
        usleep(POLL_INTERVAL * 1000);
    }

    gpio_set_level(GPIO23, LOW);
    gpio_set_level(GPIO25, LOW);
    close(GPIO23);
    close(GPIO24);
    close(GPIO25);

    log_info("Exiting...");
    return 0;
}

