        ret = gpio_set_level(GPIO23, LOW);
        if (ret == -1) {
            log_error("Failed to set DOUT to LOW: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO25, LOW);
        if (ret == -1) {
            log_error("Failed to set solenoid to LOW: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO23, HIGH);
        if (ret == -1) {
            log_error("Failed to set DOUT to HIGH: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO25, HIGH);
        if (ret == -1) {
            log_error("Failed to set solenoid to HIGH: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO23, LOW);
        if (ret == -1) {
            log_error("Failed to set DOUT to LOW: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = gpio_set_level(GPIO25, LOW);
        if (ret == -1) {
            log_error("Failed to set solenoid to LOW: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }

        ret = read_hx711(GPIO24);
        if (ret == -1) {
            retries++;
            if (retries > MAX_RETRIES) {
                log_error("Failed to read from HX711 after %d retries", MAX_RETRIES);
                exit(EXIT_FAILURE);
            }
            continue;
        }

        tare_readings[0] = read_hx711(GPIO24);
        for (int i = 1; i < TARE_READINGS; i++) {
            ret = read_hx711(GPIO24);
            if (ret == -1) {
                retries++;
                if (retries > MAX_RETRIES) {
                    log_error("Failed to read from HX711 after %d retries", MAX_RETRIES);
                    exit(EXIT_FAILURE);
                }
                continue;
            }
            tare_readings[i] = ret;
        }

        average_readings(tare_readings, TARE_READINGS, &average_weight);
        total_weight = average_weight * scale;

        if (total_weight > threshold) {
            log_info("Weight exceeds threshold: %d grams", total_weight);
            gpio_set_level(GPIO25, HIGH);
            usleep(duration * 1000);
            gpio_set_level(GPIO25, LOW);
        }

        gpio_set_level(GPIO23, LOW);
        usleep(POLL_INTERVAL * 1000);
    }

    gpio_set_level(GPIO23, LOW);
    gpio_set_level(GPIO25, LOW);
    close(GPIO23);
    close(GPIO24);
    close(GPIO25);

    log_info("Exiting...");
    return 0;
}
```

This code sets up GPIO pins for reading from an HX711 amplifier and controlling a solenoid lock using libgpiod. It reads weight from the load cell, averages 5 readings, and triggers the solenoid when the weight exceeds a specified threshold. The program accepts optional command-line arguments for threshold, scale, and duration, and polls the weight every 500 ms. It handles errors, retries, and graceful shutdown.

Before compiling, make sure to install libgpiod:

```sh
sudo apt-get install libgpiod-dev
```

Compile the code with:

```sh
gcc -o load_cell_controller load_cell_controller.c -lgpiod
```

Run the program with:

```sh
./load_cell_controller [threshold] [scale] [duration]
```

Replace `[threshold]`, `[scale]`, and `[duration]` with the desired values.

