#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <pthread.h>
#include <mosquitto.h>
#include <pigpio.h>

#define RELAY_PIN 11
#define MQTT_TOPIC "home/lights/control"
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_KEEPALIVE_INTERVAL 60
#define MQTT_CLEANSESSION
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883

void log_error(const char *msg, int severity, const char *tag, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(severity, tag, LOG_USER, fmt, args);
    va_end(args);
}

void mqtt_connect_callback(void *obj, mosquitto_client *client) {
    log_error("MQTT Connect Callback\n", LOG_USER, "mqtt_relay", "Connection result: %s\n", mosquitto_conn_status(client));
    if (mosquitto_conn_status(client) == MOS_CONNACK) {
        log_error("MQTT Connack\n", LOG_USER, "mqtt_relay", "Connack: %s\n", mosquitto_connack_string(client));
    } else {
        log_error("MQTT Connect Success\n", LOG_USER, "mqtt_relay", "Connected successfully\n");
    }
}

void mqtt_disconnect_callback(void *obj, mosquitto_client *client, int rc) {
    log_error("MQTT Disconnect Callback\n", LOG_USER, "mqtt_relay", "Disconnected with error code: %d\n", rc);
}

void mqtt_message_callback(void *obj, mosquitto_message *message) {
    char *payload = mosquitto_message_payload(message);
    int len = mosquitto_message_length(message);

    if (payload && len > 0) {
        if (strcmp(payload, "ON") == 0 || strcmp(payload, "1") == 0) {
            gpioSetMode(RELAY_PIN, PI_OUTPUT);
            gpioWrite(RELAY_PIN, 0); // LOW (relay OFF)
        } else if (strcmp(payload, "OFF") == 0 || strcmp(payload, "0") == 0) {
            gpioSetMode(RELAY_PIN, PI_OUTPUT);
            gpioWrite(RELAY_PIN, 1); // HIGH (relay ON)
        } else {
            log_error("Invalid command: %s\n", payload, LOG_ERR, "mqtt_relay");
        }
        free(payload);
    }
}

int main(int argc, char *argv[]) {
    pigpio_init();
    gpioSetup(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Relays OFF at startup

    mosquitto_lib_init();
    mosquitto_client_callback_t connect_cb = mqtt_connect_callback;
    mosquitto_client_callback_t disconnect_cb = mqtt_disconnect_callback;
    mosquitto_callback_t message_cb = mqtt_message_callback;

    mosquitto_client *client = mosquitto_new(connect_cb, disconnect_cb, message_cb);
    if (!client) {
        log_error("Failed to create MQTT client\n", LOG_ERR, "mqtt_relay");
        return -1;
    }

    mosquitto_client_set_callback_set(client, connect_cb, disconnect_cb, message_cb);
    mosquitto_client_set_clean_session(client, 1);
    mosquitto_client_set_keepalive(client, MQTT_KEEPALIVE_INTERVAL);

    mosquitto_client_connect(client, MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, MQTT_CLEANSESSION);
    if (mosquitto_client_connect_ok(client) == 0) {
        log_error("Failed to connect to MQTT broker\n", LOG_ERR, "mqtt_relay");
        mosquitto_client_disconnect(client);
        mosquitto_lib_cleanup();
        pigpio_terminate();
        return -1;
    }

    mosquitto_client_subscribe(client, NULL, 0, MQTT_TOPIC);

    while (1) {
        mosquitto_loop(client, -1);
        usleep(100000); // Sleep for 100ms between checks
    }

    mosquitto_client_disconnect(client);
    mosquitto_lib_cleanup();
    pigpio_terminate();
    closelog();

    return 0;
}

