#include <unistd.h>
#include <string.h>
#include <pigpio.h>

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_init(5); // Initialize pigpio with 5 pins (BCM GPIO 7-11)

    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pii_strerror(pi));
        return 1;
    }

    // Set PWM frequency to 50 Hz (20 ms period)
    pi_set_pwm_range(0, 1000); // 0 ms to 1000 ms (50 Hz)

    // Set PWM frequency for all pins
    for (int i = 1; i <= 5; i++) {
        pi_set_pwm_range(i, 1000); // 0 ms to 1000 ms (50 Hz)
    }

    // Servo positions (microseconds)
    int positions[] = {1000, 1500, 2000, 500, 2500};

    // Apply pulse widths to each servo
    for (int i = 0; i < 5; i++) {
        pi_set_servo_pulsewidth(i + 1, positions[i]);
        printf("Setting servo %d to position %d us\n", i + 1, positions[i]);
        usleep(3000000); // Hold for 3 seconds
    }

    // Stop PWM and clean up
    for (int i = 1; i <= 5; i++) {
        pi_stop_pwm(i);
    }

    pi_cleanup(); // Release resources

    return 0;
}

