#include <pigpio.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define KP 0.5
#define KI 0.05
#define PWM_PERIOD_MS 100
#define PWM_FREQ_HZ 10000
#define ENCODER_STALL_TIME_MS 2000
#define ENCODER_A_GPIO 4
#define ENCODER_B_GPIO 12
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define MAX_ENCODER_VALUE 64

volatile uint32_t encoder_a_count = 0;
volatile uint32_t encoder_b_count = 0;
uint32_t encoder_a_last_update = 0;
uint32_t encoder_b_last_update = 0;

double motor_a_rpm = 0;
double motor_b_rpm = 0;

struct {
    double error;
    double integral;
    double previous_error;
} controller;

void setup_pigpio() {
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

void setup_encoder_isr() {
    struct sigaction sa;
    sa.sa_sigaction = encoder_isr;
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        exit(EXIT_FAILURE);
    }
}

void encoder_isr(int signo) {
    static uint32_t last_update = 0;
    uint32_t current_a = gpioRead(ENCODER_A_GPIO);
    uint32_t current_b = gpioRead(ENCODER_B_GPIO);

    uint32_t delta_a = current_a - last_update;
    uint32_t delta_b = current_b - last_update;

    encoder_a_count += delta_a;
    encoder_b_count += delta_b;

    last_update = current_a;

    if (encoder_a_count >= MAX_ENCODER_VALUE || encoder_b_count >= MAX_ENCODER_VALUE) {
        encoder_a_count = 0;
        encoder_b_count = 0;
        last_update = 0;
    }

    if (encoder_a_count >= ENCODER_STALL_TIME_MS * 1000 && encoder_b_count >= ENCODER_STALL_TIME_MS * 1000) {
        fprintf(stderr, "Encoder stall detected!\n");
    }
}

void motor_control_loop() {
    static double last_time = 0;
    double target_rpm = 50.0;
    double error = 0;
    double integral = 0;

    double motor_a_duty = 0;
    double motor_b_duty = 0;

    double time_since_last_update = 0;

    while (1) {
        time_since_last_update = uptime() - last_time;
        last_time = uptime();

        if (time_since_last_update >= 1.0 / PWM_FREQ_HZ) {
            motor_a_duty = target_rpm * 60 / 2 * piPWM(MOTOR_A_IN1, 0, 255);
            motor_b_duty = target_rpm * 60 / 2 * piPWM(MOTOR_B_IN3, 0, 255);

            motor_a_rpm = (encoder_a_count * 64.0 / time_since_last_update) / 60;
            motor_b_rpm = (encoder_b_count * 64.0 / time_since_last_update) / 60;

            error = target_rpm - motor_a_rpm;
            integral += error;
            error = target_rpm - motor_b_rpm;

            controller.error = error;
            controller.integral += integral;
            controller.previous_error = error;

            motor_a_duty = Kp * error + Ki * integral;
            motor_b_duty = Kp * error + Ki * integral;

            if (motor_a_duty > 255) motor_a_duty = 255;
            if (motor_a_duty < 0) motor_a_duty = 0;
            if (motor_b_duty > 255) motor_b_duty = 255;
            if (motor_b_duty < 0) motor_b_duty = 0;

            gpioWrite(MOTOR_A_IN1, motor_a_duty);
            gpioWrite(MOTOR_A_IN2, !motor_a_duty);

            gpioWrite(MOTOR_B_IN3, motor_b_duty);
            gpioWrite(MOTOR_B_IN4, !motor_b_duty);

            printf("Motor A RPM: %.2f, PWM Duty: %d\n", motor_a_rpm, motor_a_duty);
            printf("Motor B RPM: %.2f, PWM Duty: %d\n", motor_b_rpm, motor_b_duty);
        }
    }
}

int main() {
    setup_pigpio();
    setup_encoder_isr();

    gpioSetup(ENCODER_A_GPIO, GPIO_OUTPUT);
    gpioSetup(ENCODER_B_GPIO, GPIO_OUTPUT);
    gpioSetup(MOTOR_A_IN1, GPIO_OUTPUT);
    gpioSetup(MOTOR_A_IN2, GPIO_OUTPUT);
    gpioSetup(MOTOR_B_IN3, GPIO_OUTPUT);
    gpioSetup(MOTOR_B_IN4, GPIO_OUTPUT);

    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

    motor_control_loop();

    piGPIO_cleanup();
    return 0;
}

