#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define RELAY_GPIO 17
#define BH1750_I2C_ADDR 0x23
#define POLLING_INTERVAL_SEC 5.0
#define HYS_LOW_LUX 50
#define HYS_HIGH_LUX 200
#define HYS_DELAY_MS 180

#define LOG_FILE "chicken_coop_log.txt"

void log_sensor_reading(int lux) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s: Lux = %d, Relay = %s\n",
            get_current_date_time(), lux, (lux < HYS_LOW_LUX ? "ON" : "OFF"));
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int relay_gpio = RELAY_GPIO;
    int bh1750_i2c_fd;
    int lux;
    int relay_state = 0;
    struct i2c_client i2c_client;
    struct bh1750_data bh1750_data;

    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (i2c_open(BH1750_I2C_ADDR, &i2c_client) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (i2c_write_byte_data(i2c_client, 0x21, 0x20) < 0) {
        perror("Failed to set One-Time High-Resolution Mode 2");
        i2c_close(&i2c_client);
        return EXIT_FAILURE;
    }

    while (1) {
        if (i2c_read_byte_data(i2c_client, &bh1750_data.raw_lux) < 0) {
            perror("Failed to read lux data from BH1750");
            relay_state = 0;
            log_sensor_reading(lux);
            continue;
        }

        lux = bh1750_data.raw_lux * 1.0 / 1.2;

        if (lux < HYS_LOW_LUX) {
            relay_state = 1;
            log_sensor_reading(lux);
        } else if (lux > HYS_HIGH_LUX) {
            relay_state = 0;
            log_sensor_reading(lux);
        }

        usleep(HYS_DELAY_MS * 1000); // Wait for hysteresis delay

        if (relay_state == 1) {
            gpioSet(relay_gpio, 1);
            log_sensor_reading(lux);
        } else {
            gpioSet(relay_gpio, 0);
            log_sensor_reading(lux);
        }

        usleep(POLLING_INTERVAL_SEC * 1000000); // Sleep for polling interval
    }

    pigpio_terminate(NULL);
    i2c_close(&i2c_client);
    fclose(stdout);
    return EXIT_SUCCESS;
}

