#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define SENSOR_GPIO 4
#define DEBOUNCE_DELAY 50
#define TOGGLE_DELAY 10

void debouncing_callback(const gpio_value_t *value) {
    static unsigned long last_change_time = 0;
    unsigned long current_time = millis();
    if (current_time - last_change_time > DEBOUNCE_DELAY) {
        last_change_time = current_time;
        gpioWrite(RELAY_GPIO, gpioRead(RELAY_GPIO) ^ 1);
    }
}

void signal_handler(int signum) {
    gpioWrite(RELAY_GPIO, 0);
    pigpio_exit(0);
    printf("Program terminated by user.\n");
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    int ret;

    // Initialize pigpio
    ret = gpioInitialise();
    if (ret != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioErrorText(ret));
        return EXIT_FAILURE;
    }

    // Configure GPIO 4 as input and GPIO 17 as output
    gpioSetMode(SENSOR_GPIO, PIGO_INPUT);
    gpioSetMode(RELAY_GPIO, PIGO_OUTPUT);

    // Set up debouncing callback
    gpioAddEventCallback(SENSOR_GPIO, debouncing_callback);

    // Set initial relay state
    gpioWrite(RELAY_GPIO, 0);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        usleep(TOGGLE_DELAY * 1000 / hrtoms(1)); // 10 ms sleep
        // Check if sensor has gone low after a touch
        if (gpioRead(SENSOR_GPIO) == 0) {
            gpioWrite(RELAY_GPIO, gpioRead(RELAY_GPIO) ^ 1);
            printf("Relay state changed: %s\n", gpioRead(RELAY_GPIO) ? "ON" : "OFF");
        }
    }

    // Clean up and exit
    gpioExit();
    return EXIT_SUCCESS;
}

