#include <time.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 11
#define SOLENOID_PIN 27
#define DEBOUNCE_TIMEOUT_MS 1000
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define HYSTERESIS 0.5

typedef struct {
    pthread_mutex_t pulse_mutex;
    time_t last_log_time;
} LogData;

void log_data(LogData *log_data, int lpm, int solenoid_state) {
    time_t current_time = time(NULL);
    if (current_time < log_data->last_log_time) {
        usleep(100000); // Sleep until next timestamp
    }
    log_data->last_log_time = current_time;

    FILE *log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%lu %d\n", current_time, lpm);
    fprintf(log_file, "Solenoid state: %d\n", solenoid_state);
    fclose(log_file);
}

void solenoid_isr(int pin, int level, void *user_data) {
    LogData *log_data = (LogData *)user_data;
    int lpm = 0;
    int pulse_count = 0;

    pthread_mutex_lock(&log_data->pulse_mutex);
    while (pulse_count < 450) {
        pulse_count += gpioRead(FLOW_SENSOR_PIN);
        usleep(10000); // Debounce delay
