#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>
#include <json-c/json.h>

#define CONFIG_FILE "config.ini"
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT "12345"
#define HX711_DATA_GPIO 23
#define HX711_SCK_GPIO 24
#define SERVO_GPIO 18
#define SERVO_MIN_PW_US 1000
#define SERVO_MAX_PW_US 2000
#define CALIBRATION_FACTOR 100.0

struct dispensing_event {
    time_t timestamp;
    double target_weight;
    double actual_weight;
    char error_message[256];
};

static json_object *dispensing_log = NULL;

void read_config(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening config file: %s\n", filename);
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (strstr(line, "calibration_factor")) {
            sscanf(line, "calibration_factor=%f", &CALIBRATION_FACTOR);
        } else if (strstr(line, "server_ip")) {
            strcpy(DEFAULT_SERVER_IP, line);
        } else if (strstr(line, "server_port")) {
            sscanf(line, "server_port=%d", &DEFAULT_SERVER_PORT);
        }
    }
    fclose(file);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        pigpio_stop();
        close(12345);
        exit(0);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    read_config(CONFIG_FILE);

    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_strerror());
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioErrorString());
        pigpio_stop();
        close(12345);
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(HX711_DATA_GPIO, PIGIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", HX711_DATA_GPIO, gpioErrorString());
        pigpio_stop();
        close(12345);
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(HX711_SCK_GPIO, PIGIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", HX711_SCK_GPIO, gpioErrorString());
        pigpio_stop();
        close(12345);
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(SERVO_GPIO, PIGIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", SERVO_GPIO, gpioErrorString());
        pigpio_stop();
        close(12345);
        exit(EXIT_FAILURE);
    }

    json_object *log_obj = json_object_new();
    json_object *event = json_object_new();
    event->key = "timestamp";
    event->value = (json_object *)json_object_fromlong(time(NULL));

    json_object *target_weight = json_object_new();
    target_weight->key = "target_weight";
    target_weight->value = (json_object *)json_object_fromlong(0);

    json_object *actual_weight = json_object_new();
    actual_weight->key = "actual_weight";
    actual_weight->value = (json_object *)json_object_fromdouble(0);

    json_object *error_message = json_object_new();
    error_message->key = "error_message";
    error_message->value = (json_object *)json_object_fromnull();

    dispensing_log = log_obj;

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        pigpio_stop();
        close(12345);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(DEFAULT_SERVER_PORT);
    if (inet_pton(AF_INET, DEFAULT_SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/address not supported");
        close(sockfd);
        pigpio_stop();
        exit(EXIT_FAILURE);
    }

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind");
        close(sockfd);
        pigpio_stop();
        exit(EXIT_FAILURE);
    }

    if (listen(sockfd, 5) < 0) {
        perror("Failed to listen");
        close(sockfd);
        pigpio_stop();
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_addr_len = sizeof(client_addr);
        int client_fd = accept(sockfd, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_fd < 0) {
            perror("Accept failed");
            close(sockfd);
            pigpio_stop();
            exit(EXIT_FAILURE);
        }

        char buffer[1024];
        read(client_fd, buffer, 1024);
        if (strcmp(buffer, "dispense") == 0) {
            double target_weight_val;
            if (sscanf(buffer, "dispense %f", &target_weight_val) != 1) {
                json_object_set(event, "error_message", json_object_fromstr("Invalid target weight format"));
                json_object_set(log_obj, "timestamp", event->timestamp);
                json_object_set(log_obj, "target_weight", target_weight_val);
                json_object_set(log_obj, "actual_weight", 0);
                json_object_set(log_obj, "error_message", json_object_fromstr("Invalid target weight format"));
                json_object_print_ff(stdout, log_obj);
                json_object_put(log_obj);
                close(client_fd);
                continue;
            }

            double actual_weight_val = 0;
            int attempts = 0;
            while (attempts < 1000) {
                gpioWrite(HX711_DATA_GPIO, 0);
                gpioWrite(HX711_SCK_GPIO, 0);
                usleep(100000);
                gpioWrite(HX711_DATA_GPIO, 1);
                gpioWrite(HX711_SCK_GPIO, 1);
                usleep(100000);
                gpioWrite(HX711_DATA_GPIO, 0);
                gpioWrite(HX711_SCK_GPIO, 0);
                usleep(100000);

                actual_weight_val = (double)gpioRead(HX711_DATA_GPIO) * CALIBRATION_FACTOR;
                if (actual_weight_val != 0) {
                    break;
                }
                attempts++;
            }

            if (attempts == 1000) {
                json_object_set(event, "error_message", json_object_fromstr("HX711 sensor not ready"));
                json_object_set(log_obj, "timestamp", event->timestamp);
                json_object_set(log_obj, "target_weight", target_weight_val);
                json_object_set(log_obj, "actual_weight", 0);
                json_object_set(log_obj, "error_message", json_object_fromstr("HX711 sensor not ready"));
                json_object_print_ff(stdout, log_obj);
                json_object_put(log_obj);
