#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_TIME_MS 50

void signal_handler(int signum) {
    printf("Received signal %d, turning off relay and exiting.\n", signum);
    gpioInitialise();
    gpioWrite(RELAY_GPIO, 0);
    pigpio_exit(NULL);
    exit(0);
}

void setup_gpio(int debounce_ms) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialise pigpio");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetMode(TOUCH_GPIO, PI_INPUT);

    if (debounce_ms > 0) {
        struct sigaction sa;
        sa.sa_handler = signal_handler;
        sigaction(SIGINT, &sa, NULL);
        sigaction(SIGTERM, &sa, NULL);
    }
}

void toggle_relay(int state) {
    if (state) {
        gpioWrite(RELAY_GPIO, 1);
        printf("Relay: ON\n");
    } else {
        gpioWrite(RELAY_GPIO, 0);
        printf("Relay: OFF\n");
    }
}

int main(int argc, char *argv[]) {
    int relay_state = 0;
    int touch_state = 0;
    int debounce_time_ms = DEBOUNCE_TIME_MS;

    if (argc > 1) {
        debounce_time_ms = atoi(argv[1]);
    }

    setup_gpio(debounce_time_ms);

    while (1) {
        touch_state = gpioRead(TOUCH_GPIO);
        if (touch_state == PI_INPUT_HIGH) {
            if (relay_state == 0 && !touch_state) {
                toggle_relay(1);
                relay_state = 1;
            }
        } else if (relay_state && touch_state) {
            toggle_relay(0);
            relay_state = 0;
        }
        usleep(100000 / debounce_time_ms); // Debounce delay
    }

    return 0;
}

