#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <termios.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US 20000000
#define MIN_PW_US 500
#define MAX_PW_US 2500
#define INITIAL_ANGLE 90

int servo_angle = INITIAL_ANGLE;

void handle_signal(int signum) {
    printf("\nStopping servo...\n");
    gpioStopPWM(SERVO_PIN);
    gpioTerminate();
    exit(0);
}

void setup_terminal() {
    termios term;
    tcgetattr(STDIN_FILENO, &term);
    term.c_lflag &= ~ECHO;
    term.c_lflag &= ~ICANON;
    tcsetattr(STDIN_FILENO, TCSANOW, &term);
}

void restore_terminal() {
    tcsetattr(STDIN_FILENO, TCSANOW, &old_term);
}

void init_gpio() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }
}

void terminate_gpio() {
    gpioTerminate();
}

void gpioServo(int pin, int angle) {
    int pw_us = (int)((angle / 10.0) * (MAX_PW_US - MIN_PW_US) + MIN_PW_US);
    if (pw_us < MIN_PW_US || pw_us > MAX_PW_US) {
        fprintf(stderr, "Pulse width out of range, clamping to [500, 2500] µs\n");
        pw_us = (pw_us < MIN_PW_US) ? MIN_PW_US : pw_us;
    }
    if (pw_us < PWM_PERIOD_US / 2) pw_us = PWM_PERIOD_US / 2;
    if (pw_us > PWM_PERIOD_US * 3 / 2) pw_us = PWM_PERIOD_US * 3 / 2;
    gpioPWM(pin, 0, pw_us);
}

int main(int argc, char *argv[]) {
    setup_terminal();
    signal(SIGINT, handle_signal);

    init_gpio();

    while (1) {
        char key;
        scanf("%c", &key);
        if (key == 'q' || key == '\n') {
            gpioStopPWM(SERVO_PIN);
            terminate_gpio();
            restore_terminal();
            printf("Servo stopped, exiting...\n");
            exit(0);
        } else if (key == '+') {
            servo_angle += 10;
            printf("Servo angle: %d°\n", servo_angle);
        } else if (key == '-') {
            servo_angle -= 10;
            printf("Servo angle: %d°\n", servo_angle);
        }
    }

    terminate_gpio();
    restore_terminal();
    return 0;
}

