#include <sys/stat.h>
#include <sys/epoll.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_WINDOW_MS 2000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "motor_rpm.log"

#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S,%f,%.2f\n"

void print_rpm(double rpm) {
    fprintf(stdout, "Current RPM: %.2f\n", rpm);
}

void log_rpm(double rpm) {
    char timestamp[38];
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    strftime(timestamp, sizeof(timestamp), LOG_FORMAT, local_time);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s", timestamp);
        fprintf(log_file, ",%f\n", rpm);
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    gpiod_line_request_input_flags(gpiod_get_line(GPIO_PIN), GPIOD_LINE_REQUEST_FLAG_DISABLE);
    fclose(log_file);
    exit(0);
}

int main() {
    int fd_epoll;
    struct epoll_event event;
    event.events = EPOLLIN;
    event.data.fd = fd_epoll;

    fd_epoll = epoll_create1(0);
    if (fd_epoll == -1) {
        perror("epoll_create1");
        exit(EXIT_FAILURE);
    }

    event.data.fd = GPIO_PIN;
    if (epoll_ctl(fd_epoll, EPOLLIN, GPIO_PIN, &event) == -1) {
        perror("epoll_ctl");
        close(fd_epoll);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_t *chip;
    gpiod_chip_open(&chip, NULL);
    if (!chip) {
        perror("gpiod_chip_open");
        close(fd_epoll);
        exit(EXIT_FAILURE);
    }

    gpiod_line_t *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(fd_epoll);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_input_flags(line, GPIOD_LINE_REQUEST_FLAG_ENABLE | GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);

    clock_gettime(CLOCK_MONOTONIC, &start_time);
    double pulse_count = 0;
    double rpm = 0.0;

    while (1) {
        int ret = gpiod_line_event_wait(line, &event);
        if (ret == -1) {
            perror("gpiod_line_event_wait");
            break;
        }

        if (event.data.fd == GPIO_PIN && event.events & EPOLLIN) {
            if (event.data.value & GPIOD_LINE_EVENT_RISING_EDGE) {
                pulse_count++;
            }
        }

        if (pulse_count > 0 && event.events & EPOLLIN) {
            double rpm_value = (double)pulse_count / SAMPLE_INTERVAL_S * 60.0;
            log_rpm(rpm_value);
            print_rpm(rpm_value);
            rpm = rpm_value;
            pulse_count = 0;
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed_ms = (now.tv_sec - start_time.tv_sec) * 1000 + (now.tv_nsec / 1000000.0 - start_time.tv_nsec / 1000000.0);
        if (elapsed_ms >= DEBOUNCE_WINDOW_MS) {
            pulse_count = 0;
        }
    }

    gpiod_line_request_input_flags(line, GPIOD_LINE_REQUEST_FLAG_DISABLE);
    gpiod_chip_close(chip);
    close(fd_epoll);

    return 0;
}

