#define GPIO_SENSOR 24
#define FLOW_RATE_CMD_ARG "-t"
#define FLOW_RATE_CALIBRATION 450
#define KP 1.0

#define LOG_FILE "flow_log.csv"
#define LOG_INTERVAL 100

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    pigpio_terminate();
    close(logfd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int valve_gpio = GPIO_VALVE, enable_gpio = GPIO_ENABLE, sensor_gpio = GPIO_SENSOR;
    int valve_state = 0, pwm_duty_cycle = 0, pulse_count = 0, last_time = 0;
    double target_flow_rate = 0.0;
    FILE *logfd;

    if (argc < 2) {
        fprintf(stderr, "Error: Missing target flow rate. Use -t <value>.\n");
        exit(1);
    }

    target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0) {
        fprintf(stderr, "Error: Invalid target flow rate. Must be positive.\n");
        exit(1);
    }

    pigpio_init(5); // Initialize pigpio with 5-second timeout

    if (pigpio_setup_timer(LOG_INTERVAL, 0, 0, signal_handler) < 0) {
        fprintf(stderr, "Error initializing timer.\n");
        pigpio_terminate();
        exit(1);
    }

    if (pigpio_setup_gpio_mode(valve_gpio, PIGPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output.\n", valve_gpio);
        pigpio_terminate();
        exit(1);
    }

    if (pigpio_setup_gpio_mode(enable_gpio, PIGPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output.\n", enable_gpio);
        pigpio_terminate();
        exit(1);
    }

    if (pigpio_setup_gpio_mode(sensor_gpio, PIGPIO_INPUT, PIGPIO_PULLUP) < 0) {
        fprintf(stderr, "Error setting GPIO %d as input with pull-up.\n", sensor_gpio);
        pigpio_terminate();
        exit(1);
    }

    if (pigpio_setup_interrupt(sensor_gpio, PIGPIO_RISING, 0, 0, 0) < 0) {
        fprintf(stderr, "Error setting interrupt on GPIO %d.\n", sensor_gpio);
        pigpio_terminate();
        exit(1);
    }

    logfd = fopen(LOG_FILE, "a");
    if (!logfd) {
        fprintf(stderr, "Error opening log file.\n");
        pigpio_terminate();
        exit(1);
    }

    while (1) {
        int time_ms = (int)(millis() * 1000);
        if (time_ms - last_time >= LOG_INTERVAL) {
            double flow_rate = (double)pulse_count / FLOW_RATE_CALIBRATION;
            double error = target_flow_rate - flow_rate;
            pwm_duty_cycle = (int)(Kp * error);
            pwm_duty_cycle = min(max(pwm_duty_cycle, 0), 255);

            if (pwm_duty_cycle != 0) {
                pigpio_set_duty_cycle(valve_gpio, pwm_duty_cycle);
            }

            fprintf(logfd, "%d,%.2f,%d\n", time_ms, flow_rate, pwm_duty_cycle);
            pulse_count = 0;
            last_time = time_ms;
        }

        if (pigpio_get_gpio_value(enable_gpio) == 0) {
            pigpio_set_gpio_value(enable_gpio, 1);
        }

        pulse_count += pigpio_get_gpio_pulsecount(sensor_gpio);
    }

    pigpio_terminate();
    close(logfd);
    return 0;
}

