#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/epoll.h>
#include <errno.h>
#include <pigpio.h>
#include <spidev.h>

#define GPIO_LOCK_A 17
#define GPIO_LOCK_B 27
#define SPI_CHANNEL 0
#define SPI_FREQ 100000
#define RFID_VALID_TAG {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}
#define BUTTON_PIN 22
#define DEBOUNCE_TIME 50
#define LOG_FILE "/var/log/door_access.log"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%SZ"

void log_access_attempt(const char* attempt_type) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), LOG_FORMAT, localtime(&ts.tv_sec));
    FILE* log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }
    fprintf(log_file, "%s: %s\n", timestamp, attempt_type);
    fclose(log_file);
}

int main(int argc, char* argv[]) {
    int lock_a, lock_b, spi_fd, log_fd;
    struct spi_device *spi_dev;
    pigpio pi;

    if (pi_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return EXIT_FAILURE;
    }

    spi_fd = spiOpen(SPI_CHANNEL, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        return EXIT_FAILURE;
    }

    spi_dev = spi_device_byid(spi_fd, 0);
    if (!spi_dev) {
        fprintf(stderr, "Failed to find SPI device.\n");
        return EXIT_FAILURE;
    }

    lock_a = gpioPinSetup(GPIO_LOCK_A, GPIO_OUTPUT);
    lock_b = gpioPinSetup(GPIO_LOCK_B, GPIO_OUTPUT);
    if (lock_a < 0 || lock_b < 0) {
        fprintf(stderr, "Failed to set GPIO pins.\n");
        return EXIT_FAILURE;
    }

    if (spiXfer(spi_dev, RFID_VALID_TAG, 10) != 10) {
        log_access_attempt("RFID read failure");
        gpioWrite(lock_a, GPIO_HIGH);
        gpioWrite(lock_b, GPIO_HIGH);
        return EXIT_FAILURE;
    }

    if (spiXfer(spi_dev, NULL, 0) != 0) {
        log_access_attempt("RFID read failure");
        gpioWrite(lock_a, GPIO_HIGH);
        gpioWrite(lock_b, GPIO_HIGH);
        return EXIT_FAILURE;
    }

    if (gpioRead(BUTTON_PIN) == GPIO_LOW) {
        if (debounceCheck()) {
            log_access_attempt("Button press without valid tag");
            gpioWrite(lock_a, GPIO_HIGH);
            gpioWrite(lock_b, GPIO_HIGH);
            return EXIT_FAILURE;
        }
    }

    gpioWrite(lock_a, GPIO_LOW);
    gpioWrite(lock_b, GPIO_LOW);
    delay(5000);
    gpioWrite(lock_a, GPIO_HIGH);
    gpioWrite(lock_b, GPIO_HIGH);

    log_access_attempt("Access successful");

    gpioTerminate();
    spiClose(spi_dev);
    close(log_fd);
    return EXIT_SUCCESS;
}

int debounceCheck() {
    static unsigned long last_time = 0;
    unsigned long current_time = millis();
    unsigned long elapsed_time = current_time - last_time;

    if (elapsed_time > DEBOUNCE_TIME) {
        last_time = current_time;
        return 0;
    }

    return 1;
}

int gpioInitialise() {
    int ret;
    ret = gpioSetup(GPIO_LOCK_A, GPIO_OUTPUT);
    if (ret < 0) {
        return ret;
    }
    ret = gpioSetup(GPIO_LOCK_B, GPIO_OUTPUT);
    if (ret < 0) {
        return ret;
    }
    return 0;
}

int spiXfer(struct spi_device *dev, const void *src, size_t len) {
    return spiTransfer(dev, src, len, 0);
}

int gpioWrite(int pin, int level) {
    return pigpio_write(pin, level);
}

int gpioRead(int pin) {
    return pigpio_read(pin);
}

int delay(unsigned long ms) {
    return pigpio_delay(ms);
}

int gpioInitialise() {
    int ret;
    ret = gpioSetup(GPIO_LOCK_A, GPIO_OUTPUT);
    if (ret < 0) {
        return ret;
    }
    ret = gpioSetup(GPIO_LOCK_B, GPIO_OUTPUT);
    if (ret < 0) {
        return ret;
    }
    return 0;
}

int spiOpen(int channel, int speed) {
    int ret;
    ret = spiOpen(channel, speed);
    if (ret < 0) {
        return ret;
    }
    return ret;
}

int spiClose(struct spi_device *dev) {
    int ret;
    ret = spiClose(dev);
    if (ret < 0) {
        return ret;
    }
    return 0;
}

