// Encoder thread function
void *encoder_thread(void *arg) {
    int *count = (int *)arg;
    int dir = 0;

    while (1) {
        int read_ret = gpiod_edge_event_read(count[0]);
        if (read_ret < 0) {
            perror("Failed to read encoder count");
            break;
        }

        if (read_ret & 1) {
            dir = -1;
        } else {
            dir = 1;
        }

        encoder_count_1 = read_ret;
        encoder_mutex_1 = pthread_mutex_lock(&encoder_mutex_1);
        encoder_mutex_2 = pthread_mutex_lock(&encoder_mutex_2);

        encoder_count_2 = gpiod_edge_event_read(count[1]);
        encoder_mutex_1 = pthread_mutex_unlock(&encoder_mutex_1);
        encoder_mutex_2 = pthread_mutex_unlock(&encoder_mutex_2);

        if (encoder_count_1 >= ENCODER_PULSES_PER_REV && encoder_count_2 >= ENCODER_PULSES_PER_REV) {
            encoder_count_1 = 0;
            encoder_count_2 = 0;
        }
