        return EXIT_FAILURE;
    }
    if (libgpiod_line_open(GPIO_MOTOR1_IN2) < 0) {
        perror("Failed to open GPIO line for Motor 1 IN2");
        return EXIT_FAILURE;
    }
    if (libgpiod_line_open(GPIO_MOTOR2_ENB) < 0) {
        perror("Failed to open GPIO line for Motor 2 ENB");
        return EXIT_FAILURE;
    }
    if (libgpiod_line_open(GPIO_MOTOR2_IN3) < 0) {
        perror("Failed to open GPIO line for Motor 2 IN3");
        return EXIT_FAILURE;
    }
    if (libgpiod_line_open(GPIO_MOTOR2_IN4) < 0) {
        perror("Failed to open GPIO line for Motor 2 IN4");
        return EXIT_FAILURE;
    }

    // Initialize encoder threads
    pthread_mutex_init(&encoder_mutex_1, NULL);
    pthread_mutex_init(&encoder_mutex_2, NULL);
    encoder_thread_1 = pthread_create(&encoder_thread_1, NULL, encoder_thread, (void *)GPIO_MOTOR1_A);
    if (encoder_thread_1 == NULL) {
        perror("Failed to create encoder thread 1");
        return EXIT_FAILURE;
    }

    encoder_thread_2 = pthread_create(&encoder_thread_2, NULL, encoder_thread, (void *)GPIO_MOTOR2_A);
    if (encoder_thread_2 == NULL) {
        perror("Failed to create encoder thread 2");
        return EXIT_FAILURE;
    }

    // Start control loop
    pid = pthread_create(&control_loop_thread, NULL, control_loop, NULL);
    if (pid < 0) {
        perror("Failed to create control loop thread");
        return EXIT_FAILURE;
    }

    // Install signal handlers
    atexit(signal_handler);

    // Run the control loop indefinitely
    while (1) {
        usleep(100000);
    }

    // Close GPIO lines and exit
    libgpiod_line_close(GPIO_MOTOR1_ENA);
    libgpiod_line_close(GPIO_MOTOR1_IN1);
    libgpiod_line_close(GPIO_MOTOR1_IN2);
    libgpiod_line_close(GPIO_MOTOR2_ENB);
    libgpiod_line_close(GPIO_MOTOR2_IN3);
    libgpiod_line_close(GPIO_MOTOR2_IN4);
    libgpiod_exit();

    return EXIT_SUCCESS;
}

