    pthread_join(encoder_thread_2, NULL);

    gpiod_edge_event_close(edge_event_fd_1);
    gpiod_edge_event_close(edge_event_fd_2);
}

// Encoder thread function
void *encoder_thread(void *arg) {
    int *count = (int *)arg;
    int dir = 0;

    while (1) {
        int read_ret = gpiod_edge_event_read(count[0]);
        if (read_ret < 0) {
            perror("Failed to read encoder count");
            break;
        }

        if (read_ret & 1) {
            dir = -1;
        } else {
            dir = 1;
        }

        encoder_count_1 = read_ret;
        encoder_mutex_1 = pthread_mutex_lock(&encoder_mutex_1);
        encoder_mutex_2 = pthread_mutex_lock(&encoder_mutex_2);

        encoder_count_2 = gpiod_edge_event_read(count[1]);
        encoder_mutex_1 = pthread_mutex_unlock(&encoder_mutex_1);
        encoder_mutex_2 = pthread_mutex_unlock(&encoder_mutex_2);

        if (encoder_count_1 >= ENCODER_PULSES_PER_REV && encoder_count_2 >= ENCODER_PULSES_PER_REV) {
            encoder_count_1 = 0;
            encoder_count_2 = 0;
        }
    }

    return NULL;
}

// Main control loop
void control_loop() {
    float target_speed_1 = TARGET_RPM_1 * 2 * pi / 60;
    float target_speed_2 = TARGET_RPM_2 * 2 * pi / 60;
    float duty_cycle_1 = 0.0, duty_cycle_2 = 0.0;

    while (1) {
        pid_init(&pid_error_1, &pid_error_2, &pid_integral_1, &pid_error_prev_1);
        pid_init(&pid_error_2, &pid_error_1, &pid_integral_2, &pid_error_prev_2);

        pid_error_1 = target_speed_1 - encoder_count_1 / PID_T;
        pid_error_2 = target_speed_2 - encoder_count_2 / PID_T;

        pid_update(&pid_output_1, &pid_error_1, &pid_integral_1, PID_T);
        pid_update(&pid_output_2, &pid_error_2, &pid_integral_2, PID_T);

        duty_cycle_1 = pid_output_1;
        duty_cycle_2 = pid_output_2;

        // Software PWM using libgpiod line
        ret = libgpiod_line_set_freq(GPIO_MOTOR1_ENA, 100);
        if (ret < 0) {
            perror("Failed to set PWM frequency");
            break;
        }

        ret = libgpiod_line_set_duty(GPIO_MOTOR1_ENA, duty_cycle_1);
        if (ret < 0) {
            perror("Failed to set PWM duty cycle for Motor 1");
            break;
        }

        ret = libgpiod_line_set_dir(GPIO_MOTOR1_IN1, dir);
        if (ret < 0) {
            perror("Failed to set direction for Motor 1");
            break;
        }

        ret = libgpiod_line_set_dir(GPIO_MOTOR1_IN2, dir);
        if (ret < 0) {
            perror("Failed to set direction for Motor 1");
            break;
        }

        ret = libgpiod_line_set_freq(GPIO_MOTOR2_ENB, 100);
        if (ret < 0) {
            perror("Failed to set PWM frequency for Motor 2");
            break;
        }

        ret = libgpiod_line_set_duty(GPIO_MOTOR2_ENB, duty_cycle_2);
        if (ret < 0) {
            perror("Failed to set PWM duty cycle for Motor 2");
            break;
        }

        ret = libgpiod_line_set_dir(GPIO_MOTOR2_IN3, dir);
        if (ret < 0) {
            perror("Failed to set direction for Motor 2");
            break;
        }

        ret = libgpiod_line_set_dir(GPIO_MOTOR2_IN4, dir);
        if (ret < 0) {
            perror("Failed to set direction for Motor 2");
            break;
        }

        // Log motor speeds and PID components
        fprintf(log_file, "%f, %f, %f, %f, %f, %f\n", encoder_count_1 / PID_T, encoder_count_2 / PID_T, pid_output_1, pid_output_2, pid_error_1, pid_error_2);

        usleep(PID_T * 1000 / 1000);
    }
}

int main(int argc, char *argv[]) {
    pid_t pid;
    pthread_t encoder_thread_1, encoder_thread_2;

    // Initialize libgpiod
    if (libgpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    // Open GPIO lines
    if (libgpiod_line_open(GPIO_MOTOR1_ENA) < 0) {
        perror("Failed to open GPIO line for Motor 1 ENA");
        return EXIT_FAILURE;
    }
    if (libgpiod_line_open(GPIO_MOTOR1_IN1) < 0) {
        perror("Failed to open GPIO line for Motor 1 IN1");
        return EXIT_FAILURE;
    }
    if (libgpiod_line_open(GPIO_MOTOR1_IN2) < 0) {
        perror("Failed to open GPIO line for Motor 1 IN2");
        return EXIT_FAILURE;
    }
    if (libgpiod_line_open(GPIO_MOTOR2_ENB) < 0) {
        perror("Failed to open GPIO line for Motor 2 ENB");
        return EXIT_FAILURE;
    }
    if (libgpiod_line_open(GPIO_MOTOR2_IN3) < 0) {
        perror("Failed to open GPIO line for Motor 2 IN3");
        return EXIT_FAILURE;
    }
    if (libgpiod_line_open(GPIO_MOTOR2_IN4) < 0) {
        perror("Failed to open GPIO line for Motor 2 IN4");
        return EXIT_FAILURE;
    }

    // Initialize encoder threads
    pthread_mutex_init(&encoder_mutex_1, NULL);
    pthread_mutex_init(&encoder_mutex_2, NULL);
    encoder_thread_1 = pthread_create(&encoder_thread_1, NULL, encoder_thread, (void *)GPIO_MOTOR1_A);
    if (encoder_thread_1 == NULL) {
        perror("Failed to create encoder thread 1");
        return EXIT_FAILURE;
    }

    encoder_thread_2 = pthread_create(&encoder_thread_2, NULL, encoder_thread, (void *)GPIO_MOTOR2_A);
    if (encoder_thread_2 == NULL) {
        perror("Failed to create encoder thread 2");
        return EXIT_FAILURE;
    }

    // Start control loop
    pid = pthread_create(&control_loop_thread, NULL, control_loop, NULL);
    if (pid < 0) {
        perror("Failed to create control loop thread");
        return EXIT_FAILURE;
    }

    // Install signal handlers
    atexit(signal_handler);

    // Run the control loop indefinitely
    while (1) {
        usleep(100000);
    }

    // Close GPIO lines and exit
    libgpiod_line_close(GPIO_MOTOR1_ENA);
    libgpiod_line_close(GPIO_MOTOR1_IN1);
    libgpiod_line_close(GPIO_MOTOR1_IN2);
    libgpiod_line_close(GPIO_MOTOR2_ENB);
    libgpiod_line_close(GPIO_MOTOR2_IN3);
    libgpiod_line_close(GPIO_MOTOR2_IN4);
    libgpiod_exit();

    return EXIT_SUCCESS;
}
