#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_STATUS_REG 0x00
#define RELEASE_STATUS_REG 0x01
#define POLL_INTERVAL 50

void log_relay_state(const char *timestamp, int state) {
    FILE *file = fopen("relay_log.txt", "a");
    if (file == NULL) {
        perror("Failed to open relay_log.txt");
        return;
    }
    time_t now = time(NULL);
    fprintf(file, "%s %d\n", ctime(&now), state);
    fclose(file);
}

int main() {
    int i2c_fd, relay_state = 0;

    // Initialize pigpio
    if (piGPIOInit() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(piI2CPath(I2C_BUS, I2C_ADDR), O_RDWR | O_NOCTTY | O_NDELAY);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        piGPIOExit();
        return EXIT_FAILURE;
    }

    // MPR121 initialization sequence
    if (piI2CMemWrite(i2c_fd, 0x00, 0x00, 4) < 0) {
        perror("Failed to write soft reset to MPR121");
        close(i2c_fd);
        piGPIOExit();
        return EXIT_FAILURE;
    }

    if (piI2CMemWrite(i2c_fd, 0x01, 0x00, 4) < 0) {
        perror("Failed to configure filtering");
        close(i2c_fd);
        piGPIOExit();
        return EXIT_FAILURE;
    }

    if (piI2CMemWrite(i2c_fd, 0x02, 0x00, 12) < 0) {
        perror("Failed to set touch thresholds");
        close(i2c_fd);
        piGPIOExit();
        return EXIT_FAILURE;
    }

    if (piI2CMemWrite(i2c_fd, 0x03, 0x00, 12) < 0) {
        perror("Failed to enable run mode");
        close(i2c_fd);
        piGPIOExit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int status_reg[2];
        if (piI2CRead(i2c_fd, TOUCH_STATUS_REG, 1, &status_reg[0]) < 0) {
            perror("Failed to read touch status register");
            break;
        }
        if (status_reg[0] & 0x01) { // Electrode touched
            relay_state = 1;
            log_relay_state(ctime(NULL), relay_state);
        } else {
            relay_state = 0;
            log_relay_state(ctime(NULL), relay_state);
        }

        usleep(POLL_INTERVAL * 1000 / 1000); // Convert ms to us
    }

    // Clean up and exit
    piI2CClose(i2c_fd);
    piGPIOExit();

    return EXIT_SUCCESS;
}

