#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_LINE_1 17
#define GPIO_LINE_2 18
#define VALVE_1_DURATION 500
#define VALVE_2_DURATION 1000
#define PAUSE_TIME 5000

void log_event(const char *event_type, const char *timestamp) {
    FILE *log_file = fopen("valve_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file for writing.");
        return;
    }
    time_t now = time(NULL);
    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%T", localtime(&now));
    fprintf(log_file, "%s: %s\n", timestamp_str, event_type);
    fclose(log_file);
    syslog(LOG_INFO, "Logged event: %s", event_type);
}

int main() {
    gpiod_context ctx;
    gpiod_chip_t chip;
    gpiod_line_t lines[2];
    gpiod_line_request_output_attr_t req;
    gpiod_line_request_output_res_t res;

    if (gpiod_init(GPIOD_CHIP_ANY, &ctx) != 0) {
        syslog(LOG_ERR, "Failed to initialize gpiod.");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_add_and_request_lines(&ctx, GPIO_LINE_1, &lines[0]) != 0 ||
        gpiod_chip_add_and_request_lines(&ctx, GPIO_LINE_2, &lines[1]) != 0) {
        syslog(LOG_ERR, "Failed to add GPIO lines.");
        return EXIT_FAILURE;
    }

    req.output_en = 1;
    req.polarity = GPIOD_OUTPUT_POLARITY_HIGH;
    if (gpiod_line_request_output(&ctx, lines[0], &req) != 0 ||
        gpiod_line_request_output(&ctx, lines[1], &req) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO lines as output.");
        return EXIT_FAILURE;
    }

    while (1) {
        log_event("Valve 1 ON", gmtime(&now));
        gpiod_line_output_enable(&ctx, lines[0]);
        usleep(VALVE_1_DURATION * 1000);
        gpiod_line_output_disable(&ctx, lines[0]);
        log_event("Valve 1 OFF", gmtime(&now));

        log_event("Pause", gmtime(&now));
        sleep(PAUSE_TIME);

        log_event("Valve 2 ON", gmtime(&now));
        gpiod_line_output_enable(&ctx, lines[1]);
        usleep(VALVE_2_DURATION * 1000);
        gpiod_line_output_disable(&ctx, lines[1]);
        log_event("Valve 2 OFF", gmtime(&now));

        log_event("Pause", gmtime(&now));
    }

    gpiod_line_output_disable(&ctx, lines[0]);
    gpiod_line_output_disable(&ctx, lines[1]);
    gpiod_chip_del(&ctx, lines, 2);
    gpiod_exit(&ctx);

    syslog(LOG_INFO, "Exiting cleanly.");
    return EXIT_SUCCESS;
}

