#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define MPR121_ADDR 0x5A
#define SDA_PIN 2
#define SCL_PIN 3

void handle_sigint(int sig) {
    pigpio_stop();
    printf("Program received SIGINT, exiting gracefully.\n");
    exit(0);
}

void handle_sigterm(int sig) {
    pigpio_stop();
    printf("Program received SIGTERM, exiting gracefully.\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    int ret;
    sigset_t sigset;
    pid_t pid;

    // Initialize signal handlers
    sigset_t sigmask;
    memset(&sigmask, 0, sizeof(sigmask));
    sigaddset(&sigmask, SIGINT);
    sigaddset(&sigmask, SIGTERM);
    sigprocmask(SIG_BLOCK, &sigmask, NULL);

    // Initialize pigpio
    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Initialize MPR121
    if (mp121_init(MPR121_ADDR, 0x10, 0x0A, 0x20, 0x01, 0x20) < 0) {
        perror("Failed to initialize MPR121");
        pigpio_stop();
        return EXIT_FAILURE;
    }

    // Configure MPR121 in run mode
    if (mp121_run_mode(MPR121_ELE_EN) < 0) {
        perror("Failed to set MPR121 to run mode");
        pigpio_stop();
        return EXIT_FAILURE;
    }

    // Wait for stabilization
    usleep(100000);

    // Set relay pin as output, initially off
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    // Main loop
    while (1) {
        // Read touch status
        int touch_status = mp121_read_status();

        // Check if any electrode is touched
        if (touch_status > 0) {
            printf("Touch detected on electrode: %d\n", touch_status);
            gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN)); // Toggle relay
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up and exit
    pigpio_stop();
    printf("Program exiting.\n");
    return EXIT_SUCCESS;
}

