#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_MODE_OUTPUT
#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DURATION 50
#define MAX_DURATION 200
#define STEP_DURATION 50

volatile sig_atomic_t shutdown = 0;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Haptic feedback pattern generation stopped.\n");
        pigpio_stop();
        exit(0);
    }
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(1);
    }

    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    if (gpioInitialise(GPIO_PIN_17, GPIO_MODE_OUTPUT) == -1 ||
        gpioInitialise(GPIO_PIN_27, GPIO_MODE_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO pins as output.\n");
        pigpio_stop();
        exit(1);
    }

    srand(time(NULL));

    while (!shutdown) {
        int steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
        for (int i = 0; i < steps; i++) {
            int duty1 = rand() % 256;
            int duty2 = rand() % 256;
            int duration = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;
            gpioPWM(GPIO_PIN_17, 0, duty1, duration);
            gpioPWM(GPIO_PIN_27, 0, duty2, duration);
            usleep(STEP_DURATION * 100000); // Convert microseconds to seconds
        }
        usleep(1000000); // Sleep for 1 second
    }

    pigpio_stop();
    return 0;
}

