#define GPIO_LOAD_CELL 4
#define GPIO_SOLENOID 27
#define CALIBRATION_FILE "calibration.txt"
#define CALIBRATION_TIMEOUT 0.5
#define CALIBRATION_READINGS 100
#define CALIBRATION_THRESHOLD 10.0
#define LOG_FILE "weight_log.txt"
#define LOG_FORMAT "%s: %f\n"

void handle_signal(int signum) {
    pigpio_stop();
    close(stdout);
    close(stderr);
    close(logfd);
    exit(0);
}

void setup_pigpio() {
    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void load_calibration(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open calibration file: %s\n", filename);
        return;
    }

    char line[1024];
    double scale_factor = 1.0, offset = 0.0;
    int count = 0;

    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%lf %lf", &scale_factor, &offset) == 2) {
            break;
        }
        count++;
    }

    fclose(file);

    if (count < 2) {
        fprintf(stderr, "Invalid calibration file format, using defaults.\n");
        scale_factor = 1.0;
        offset = 0.0;
    }

    // Save calibration data back to file
    FILE *new_file = fopen(CALIBRATION_FILE, "w");
    if (!new_file) {
        perror("Failed to open calibration file for writing");
        return;
    }
    fprintf(new_file, "%f %f\n", scale_factor, offset);
    fclose(new_file);
}

void startup_calibration() {
    double total_raw = 0;
    for (int i = 0; i < CALIBRATION_READINGS; i++) {
        int raw_value = gpioRead(GPIO_LOAD_CELL);
        total_raw += raw_value;
    }
    offset = total_raw / CALIBRATION_READINGS;
    printf("Startup calibration completed. Offset: %f\n", offset);
    save_calibration(CALIBRATION_FILE);
}

void read_load_cell() {
    int raw_value = gpioRead(GPIO_LOAD_CELL);
    double weight = raw_value * scale_factor + offset;
    if (weight > CALIBRATION_THRESHOLD) {
        gpioWrite(GPIO_SOLENOID, 1);
    } else {
        gpioWrite(GPIO_SOLENOID, 0);
    }
}

void log_reading(const char *timestamp) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char time_str[80];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", local_time);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open weight log file for appending");
        return;
    }
    fprintf(log_file, LOG_FORMAT "%s: %f\n", time_str, weight);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);

    setup_pigpio();
    load_calibration(CALIBRATION_FILE);
    startup_calibration();

    while (1) {
        read_load_cell();
        usleep(500000 / 1000); // Sleep for 500 ms
        log_reading(ctime(NULL));
    }

    pigpio_stop();
    return 0;
}

