#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define CALIBRATION_TIMEOUT 100000
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S %p %c: %f kg"

void calibrate_load_cell(double known_weight_kg) {
    printf("Please place a known weight in kg: ");
    double raw_value;
    read_hx711_raw(&raw_value);
    double calibration_factor = raw_value / known_weight_kg;
    write_calibration(calibration_factor);
}

void read_hx711_raw(int *raw_value) {
    *raw_value = pigpio_get_bit_read(HX711_DATA_PIN);
    usleep(100000); // Adjust clock high and low delays as needed
}

void write_calibration(double calibration_factor) {
    FILE *file = fopen(CALIBRATION_FILE, "w");
    if (!file) {
        perror("Failed to open calibration file");
        return;
    }
    fprintf(file, "%f\n", calibration_factor);
    fclose(file);
}

void log_event(double weight_kg) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open security log file");
        return;
    }
    fprintf(log_file, LOG_FORMAT, timestamp, weight_kg, weight_kg);
    fclose(log_file);
}

void drive_solenoid(int duration_ms) {
    pigpio_set_mode(SOLENOID_PIN, PIGIO_OUTPUT);
    pigpio_write(SOLENOID_PIN, 1);
    sleep((duration_ms / 1000.0) / 0.1); // Adjust duration as needed
    pigpio_write(SOLENOID_PIN, 0);
}

int main() {
    int hx711_raw;
    double calibration_factor = 0.0;

    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (open(CALIBRATION_FILE, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR) < 0) {
        perror("Failed to open calibration file");
        return EXIT_FAILURE;
    }

    if (read_calibration(&calibration_factor) < 0) {
        perror("Failed to read calibration factor");
        return EXIT_FAILURE;
    }

    calibrate_load_cell(1.0); // Initial calibration with 1 kg

    while (1) {
        read_hx711_raw(&hx711_raw);
        double weight_kg = (hx711_raw * 1024.0) / 65536.0;

        if (weight_kg > 5.0) {
            log_event(weight_kg);
            drive_solenoid(5000); // 5 seconds
        }

        sleep(0.1); // Adjust read interval as needed
    }

    pigpio_terminate(1000); // Terminate pigpio with a timeout

    return EXIT_SUCCESS;
}

int read_calibration(double *calibration_factor) {
    FILE *file = fopen(CALIBRATION_FILE, "r");
    if (!file) {
        return errno;
    }
    fscanf(file, "%lf", calibration_factor);
    fclose(file);
    return 0;
}

