#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <libgpiod.h>

#define CHIP_NAME "Keywish KY-022"
#define SENSOR_PIN 16
#define RELAY_PIN 20
#define RELAY_STATE_ON 1
#define RELAY_STATE_OFF 0

void log_event(const char *message) {
    FILE *file = fopen("relay_events.log", "a");
    if (!file) {
        fprintf(stderr, "Error opening relay_events.log: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(&now));
    fprintf(file, "%s: %s\n", timestamp, message);
    fclose(file);
}

int main(int argc, char *argv[]) {
    gpiod_chip_handle_t chip;
    gpiod_line_t sensor_line, relay_line;
    gpiod_line_direction_t direction;
    int sensor_value, relay_value;

    if (gpiod_chip_open_by_name(&chip, CHIP_NAME) < 0) {
        fprintf(stderr, "Failed to open chip: %s\n", gpiod_strerror(gpiod_get_last_error()));
        return EXIT_FAILURE;
    }

    if (gpiod_chip_get_line(chip, SENSOR_PIN, &sensor_line) < 0) {
        fprintf(stderr, "Failed to get sensor line: %s\n", gpiod_strerror(gpiod_get_last_error()));
        return EXIT_FAILURE;
    }

    direction = gpiod_line_direction_output(sensor_line);
    if (direction < 0) {
        fprintf(stderr, "Failed to set sensor line direction: %s\n", gpiod_strerror(gpiod_get_last_error()));
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_bulk_inputs(&sensor_line, 1) < 0) {
        fprintf(stderr, "Failed to request sensor line inputs: %s\n", gpiod_strerror(gpiod_get_last_error()));
        return EXIT_FAILURE;
    }

    if (gpiod_line_get_value(&sensor_line, &sensor_value) < 0) {
        fprintf(stderr, "Failed to get sensor value: %s\n", gpiod_strerror(gpiod_get_last_error()));
        return EXIT_FAILURE;
    }

    if (sensor_value == 0) { // Obstacle detected
        relay_value = !gpiod_line_get_value(&relay_line, &relay_value);
        if (relay_value) {
            log_event("Relay turned ON");
        } else {
            log_event("Relay turned OFF");
        }
        gpiod_line_set_value(&relay_line, relay_value);
    } else {
        relay_value = !gpiod_line_get_value(&relay_line, &relay_value);
        if (relay_value) {
            log_event("Relay turned ON");
        } else {
            log_event("Relay turned OFF");
        }
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);

    if (gpiod_chip_close(chip) < 0) {
        fprintf(stderr, "Failed to close chip: %s\n", gpiod_strerror(gpiod_get_last_error()));
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

