#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIR 17
#define GPIO_BUZzer 18

void sigint_handler(int sig) {
    gpiod_line_set_value(GPIO_BUZzer, 0);
    close(1); // Close the log file descriptor
    gpiod_chip_close(gpiod_chip_from_number(0));
    exit(0);
}

void sigterm_handler(int sig) {
    gpiod_line_set_value(GPIO_BUZzer, 0);
    close(1); // Close the log file descriptor
    gpiod_chip_close(gpiod_chip_from_number(0));
    exit(0);
}

int main(int argc, char *argv[]) {
    gpiod_chip_t *chip;
    gpiod_line_t *line_in, *line_out;
    struct tm now;
    char timestamp[32];

    gpiod_chip_open(&chip, 0);

    if (!gpiod_chip_is_open(chip)) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    line_in = gpiod_line_from_number(GPIO_PIR);
    line_out = gpiod_line_from_number(GPIO_BUZzer);

    if (!gpiod_line_is_input(line_in)) {
        fprintf(stderr, "Line %d is not an input line.\n", GPIO_PIR);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (!gpiod_line_is_output(line_out)) {
        fprintf(stderr, "Line %d is not an output line.\n", GPIO_BUZzer);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (gpiod_line_get_value(line_in) == GPIO_INPUT_HIGH) {
            gpiod_line_set_value(line_out, GPIO_OUTPUT_HIGH);
            gpiod_line_request_output(line_out);

            // Get current time
            time_t now_time = time(NULL);
            struct timeval tv;
            tv.tv_sec = now_time / 1000;
            tv.tv_usec = (now_time % 1000) * 1000;
            gettimeofday(&tv, NULL);

            // Format timestamp
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

            // Append to log file
            FILE *log_file = fopen("motion_log.txt", "a");
            if (log_file == NULL) {
                perror("fopen");
                exit(EXIT_FAILURE);
            }
            fprintf(log_file, "%s: Motion detected\n", timestamp);
            fclose(log_file);

            // Delay for 2 seconds
            usleep(200000000);

            // Turn off buzzer
            gpiod_line_set_value(line_out, GPIO_OUTPUT_LOW);
            gpiod_line_request_output(line_out);
        }

        usleep(100000); // Check every 100ms
    }

    gpiod_line_request_input_trailing(line_in);
    gpiod_line_request_output(line_out);
    gpiod_chip_close(chip);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return 0;
}

