            fclose(fp);
            close(fd);
            gpiod_deinit();
            return EXIT_FAILURE;
        }
        break;
    }
    fclose(fp);

    // Set GPIO line as output with active-low, default off
    if (gpiod_chip_find(GPIO_LINE, &chip) < 0) {
        fprintf(stderr, "Failed to find GPIO line %d\n", GPIO_LINE);
        close(fd);
        gpiod_deinit();
        return EXIT_FAILURE;
