    if (gpiod_line_value_set(line, VALVE_ON) < 0) {
        fprintf(stderr, "Failed to set GPIO line %d to on\n", GPIO_LINE);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        close(fd);
        gpiod_deinit();
        return EXIT_FAILURE;
    }

