    struct itimerspec timerspec;
    timerspec.it_value.tv_sec = duration;
    timerspec.it_value.tv_nsec = 0;
    if (timeradd(&timerspec, (struct timespec *)NULL, &timerspec) < 0) {
        fprintf(stderr, "Failed to set timer for %d seconds\n", duration);
        gpiod_line_value_set(line, VALVE_OFF);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        close(fd);
        gpiod_deinit();
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (!sig_interrupt_flag) {
        // Check valve status
        if (gpiod_line_value_get(line) == VALVE_ON) {
            fprintf(stdout, "Valve is ON\n");
        } else {
            fprintf(stdout, "Valve is OFF\n");
        }

        // Sleep for a short duration to avoid busy-waiting
        usleep(10000);
    }

    // Turn off the valve
    if (gpiod_line_value_set(line, VALVE_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO line %d to off\n", GPIO_LINE);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        close(fd);
        gpiod_deinit();
        return EXIT_FAILURE;
    }

    // Release resources
    gpiod_line_free(line);
    gpiod_chip_free(chip);
    close(fd);
    gpiod_deinit();

    return EXIT_SUCCESS;
}

