#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_GPIO_LEFT 4
#define SENSOR_GPIO_MIDDLE 17
#define SENSOR_GPIO_RIGHT 27
#define MOTOR_PWM_LEFT 22
#define MOTOR_PWM_RIGHT 23
#define MOTOR_PWM_FORWARD 24
#define MOTOR_PWM_BACKWARD 25
#define BASE_SPEED 150
#define LOG_FILE "trace_log.txt"
#define LOG_INTERVAL 10

void log_control_cycle(const char *timestamp, int left_sensor, int right_sensor, int middle_sensor, int left_speed, int right_speed) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp_str[80];
    sprintf(timestamp_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1, local_time->tm_mday,
            local_time->tm_hour, local_time->tm_min, local_time->tm_sec);

    fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", timestamp_str, left_sensor, right_sensor, middle_sensor, left_speed, right_speed);
    fclose(log_file);
}

void motor_control(int left_speed, int right_speed) {
    gpioSetMode(MOTOR_PWM_LEFT, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_RIGHT, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR_PWM_LEFT, 1000);
    gpioSetPWMfrequency(MOTOR_PWM_RIGHT, 1000);
    gpioSetPWM(MOTOR_PWM_LEFT, left_speed);
    gpioSetPWM(MOTOR_PWM_RIGHT, right_speed);
}

void sensor_control(int left_sensor, int right_sensor, int middle_sensor) {
    int left_motor_speed = 128;
    int right_motor_speed = 128;

    if (middle_sensor) {
        log_control_cycle(NULL, left_sensor, right_sensor, middle_sensor, left_motor_speed, right_motor_speed);
        motor_control(left_motor_speed, right_motor_speed);
    } else if (left_sensor) {
        log_control_cycle(NULL, left_sensor, right_sensor, middle_sensor, left_motor_speed, right_motor_speed);
        left_motor_speed /= 2;
        right_motor_speed /= 2;
        motor_control(left_motor_speed, right_motor_speed);
    } else if (right_sensor) {
        log_control_cycle(NULL, left_sensor, right_sensor, middle_sensor, left_motor_speed, right_motor_speed);
        left_motor_speed /= 2;
        right_motor_speed /= 2;
        motor_control(left_motor_speed, right_motor_speed);
    } else {
        log_control_cycle(NULL, left_sensor, right_sensor, middle_sensor, 0, 0);
        motor_control(0, 0);
    }
}

int main(int argc, char *argv[]) {
    pigpio_init(5);
    if (pigpio_init_rw(5) != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpioSetup(SENSOR_GPIO_LEFT, PI_INPUT);
    gpioSetup(SENSOR_GPIO_MIDDLE, PI_INPUT);
    gpioSetup(SENSOR_GPIO_RIGHT, PI_INPUT);

    gpioSetup(MOTOR_PWM_LEFT, PI_OUTPUT);
    gpioSetup(MOTOR_PWM_RIGHT, PI_OUTPUT);
    gpioSetup(MOTOR_PWM_FORWARD, PI_OUTPUT);
    gpioSetup(MOTOR_PWM_BACKWARD, PI_OUTPUT);

    while (1) {
        int left_sensor = gpioRead(SENSOR_GPIO_LEFT);
        int right_sensor = gpioRead(SENSOR_GPIO_RIGHT);
        int middle_sensor = gpioRead(SENSOR_GPIO_MIDDLE);

        sensor_control(left_sensor, right_sensor, middle_sensor);
        usleep(LOG_INTERVAL * 1000 / 1000); // Convert to microseconds
    }

    pigpioTerminate();
    return 0;
}

void signal_handler(int signum) {
    printf("Received signal %d, stopping motors and exiting.\n", signum);
    motor_control(0, 0);
    fclose(stdout);
    fclose(stderr);
    fclose(log_file);
    pigpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    pigpio_init(5);
    if (pigpio_init_rw(5) != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Rest of the code as shown above

    return 0;
}

