#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define RELAY_GPIO 23
#define LOG_FILE "grow_log.txt"
#define DELAY_MS 180000  // 180 ms
#define LOW_LUX_THRESHOLD 150

void log_lux_reading(int lux) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%02d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }
    fprintf(log_file, "%s: Lux = %d\n", time_str, lux);
    fclose(log_file);
}

int main() {
    int relay_state = 1;  // Initially, the relay is ON
    pigpio_init(1);  // Initialize pigpio with I2C bus 1

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        pigpio_terminate(1);
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        pigpio_terminate(1);
        return -1;
    }

    if (pigpio_setup_i2c(i2c_fd) < 0) {
        perror("Failed to setup I2C");
        close(i2c_fd);
        pigpio_terminate(1);
        return -1;
    }

    int lux;
    while (1) {
        if (pigpio_transfer(i2c_fd, 0x10, 1, 0) < 0) {
            fprintf(stderr, "Failed to read from BH1750 sensor\n");
            log_lux_reading(0);
            continue;
        }

        lux = pigpio_get_i2c_byte(i2c_fd);
        log_lux_reading(lux);

        if (lux < LOW_LUX_THRESHOLD) {
            relay_state = 0;
            printf("Lux is below threshold, turning off relay\n");
            if (pigpio_write(RELAY_GPIO, 0) < 0) {
                fprintf(stderr, "Failed to turn off relay\n");
            }
        } else {
            relay_state = 1;
            printf("Lux is above threshold, turning on relay\n");
            if (pigpio_write(RELAY_GPIO, 1) < 0) {
                fprintf(stderr, "Failed to turn on relay\n");
            }
        }

        usleep(DELAY_MS * 1000 / 1000);  // Convert ms to microseconds
    }

    pigpio_cleanup(i2c_fd);
    pigpio_terminate(1);
    printf("Exiting...\n");
    return 0;
}

