    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(1);
    }

    if (pigpioInit() == -1) {
        fprintf(stderr, "pigpio_init() failed\n");
        return 1;
    }

    gpioSetMode(servo_gpio, PI_OUTPUT);
    gpioSetMode(lock_button_gpio, PI_INPUT_PULLUP);
    gpioSetMode(unlock_button_gpio, PI_INPUT_PULLUP);

