    printf("Lock button connected to GPIO%d (pull-up)\n", lock_button_gpio);
    printf("Unlock button connected to GPIO%d (pull-up)\n", unlock_button_gpio);

    while (1) {
        int lock_button_state = gpioRead(lock_button_gpio);
        int unlock_button_state = gpioRead(unlock_button_gpio);

        if (lock_button_state == 0) {
            // Lock button pressed
            servo_pulse_width = 1500; // Unlocked position
            gpioWrite(servo_gpio, servo_pulse_width);
            usleep(DEBOUNCE_DELAY * 1000); // Debounce delay
        } else if (unlock_button_state == 0) {
            // Unlock button pressed
            servo_pulse_width = 2500; // Locked position
            gpioWrite(servo_gpio, servo_pulse_width);
            usleep(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        // Constrain pulse width to safe range
        if (servo_pulse_width < 500) {
            servo_pulse_width = 500;
        }
        if (servo_pulse_width > 2500) {
            servo_pulse_width = 2500;
        }

        usleep(1000); // Check every second
    }

    pigpioTerminate();
    return 0;
}

