#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_LINE1 17
#define GPIO_LINE2 27

void signal_handler(int signum) {
    gpiod_line_request_output(GPIO_LINE1, 0);
    gpiod_line_request_output(GPIO_LINE2, 0);
    exit(0);
}

int main() {
    struct gpiod_line *line1, *line2;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    line1 = gpiod_line_new(GPIO_LINE1, GPIOD_OUT);
    if (!line1) {
        perror("Failed to create GPIO line 1");
        exit(EXIT_FAILURE);
    }

    line2 = gpiod_line_new(GPIO_LINE2, GPIOD_OUT);
    if (!line2) {
        perror("Failed to create GPIO line 2");
        exit(EXIT_FAILURE);
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start pulsing motors
    while (1) {
        gpiod_line_set_value(line1, 1);
        gpiod_line_set_value(line2, 0);
        usleep(200000); // 200 ms delay

        gpiod_line_set_value(line1, 0);
        gpiod_line_set_value(line2, 1);
        usleep(300000); // 300 ms delay

        // Check for errors
        if (gpiod_line_get_status(line1) != GPIOD_LINE_ON) {
            perror("Failed to set GPIO line 1 value");
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_get_status(line2) != GPIOD_LINE_ON) {
            perror("Failed to set GPIO line 2 value");
            exit(EXIT_FAILURE);
        }
    }

    // Release GPIO lines
    gpiod_line_release(line1);
    gpiod_line_release(line2);

    // Clean up libgpiod
    gpiod_cleanup();

    return 0;
}

