#include <libgpiod.h>

#define GPIO_SOUND_SENSOR 17
#define ALARM_LED 27
#define ZEROMQ_TOPIC "SOUND_ALERTS"
#define ZEROMQ_PORT 5555

void sound_sensor_mode(int argc, char *argv[]) {
    gpiod_context_t ctx;
    gpiod_button_t button;
    int zmq_fd;
    struct sockaddr_in zeromq_addr;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor_mode>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if (strcmp(argv[1], "sound_sensor") != 0) {
        fprintf(stderr, "Invalid mode. Use 'sound_sensor' for sound detection.\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_new_button(&ctx, GPIO_SOUND_SENSOR, GPIOD_IN, &button) < 0) {
        perror("Failed to create GPIO button");
        exit(EXIT_FAILURE);
    }

    zmq_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (zmq_socket(zmq_fd, ZMQ_PUB) < 0) {
        perror("Failed to create ZeroMQ socket");
        exit(EXIT_FAILURE);
    }

    memset(&zeromq_addr, 0, sizeof(zeromq_addr));
    zeromq_addr.sin_family = AF_INET;
    zeromq_addr.sin_port = htons(ZEROMQ_PORT);
    zeromq_addr.sin_addr.s_addr = INADDR_ANY;

    if (zmq_connect(zmq_fd, (struct sockaddr *)&zeromq_addr, sizeof(zeromq_addr)) < 0) {
        perror("Failed to connect to ZeroMQ server");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int button_state = gpiod_get_value(&button);
        if (!button_state) {
            char msg[64];
            sprintf(msg, "Sound detected on GPIO%d", GPIO_SOUND_SENSOR);
            if (zmq_send(zmq_fd, msg, strlen(msg), 0) < 0) {
                perror("Failed to send message on ZeroMQ");
                exit(EXIT_FAILURE);
            }
        }
        usleep(10000); // 10 ms delay
    }
}

void alarm_node_mode(int argc, char *argv[]) {
    gpiod_context_t ctx;
    gpiod_button_t button;
    struct zmq_socket *zmq_socket;
    char msg[64];
    int zmq_fd;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <alarm_node_mode>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if (strcmp(argv[1], "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode. Use 'alarm_node' for receiving alerts.\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_new_button(&ctx, ALARM_LED, GPIOD_OUT, NULL) < 0) {
        perror("Failed to create GPIO button");
        exit(EXIT_FAILURE);
    }

    zmq_fd = zmq_socket(NULL, ZMQ_SUB);
    if (zmq_socket_connect(zmq_fd, "tcp://localhost:5555", 0) < 0) {
        perror("Failed to connect to ZeroMQ server");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int msg_len = zmq_recv(zmq_fd, msg, 64, 0);
        if (msg_len > 0) {
            printf("Received alert: %s\n", msg);
            gpiod_button_set(ctx, true);
            usleep(1000000); // 1 second delay
            gpiod_button_set(ctx, false);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <sound_sensor_mode|alarm_node_mode>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        sound_sensor_mode(argc, argv);
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        alarm_node_mode(argc, argv);
    } else {
        fprintf(stderr, "Invalid mode. Use 'sound_sensor' or 'alarm_node'.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

