#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <paho-mqtt/mqtt.h>

#define GPIO_PIN 17
#define IR_RECEIVER_PIN GPIO_PIN
#define CHECKSUM_OFFSET 16

void ir_callback(char *data, int length) {
    syslog(LOG_INFO, "Received IR signal: %s", data);
    char decoded_address[10];
    char decoded_command[10];
    int checksum, address_inverted;

    // Decode NEC frame
    memcpy(decoded_address, data, 8);
    memcpy(decoded_command, data + 8, 6);

    // Validate checksum
    checksum = 0;
    for (int i = 0; i < 6; i++) {
        checksum += data[i];
    }
    checksum = ~checksum;
    if (checksum != data[6]) {
        syslog(LOG_ERR, "Invalid checksum");
        return;
    }

    // Inverted address validation (not required for extended NEC frames)
    address_inverted = ~((unsigned int)decoded_address[0]) << 7 |
                       ((unsigned int)decoded_address[1]) << 6 |
                       ((unsigned int)decoded_address[2]) << 5 |
                       ((unsigned int)decoded_address[3]) << 4 |
                       ((unsigned int)decoded_address[4]) << 3 |
                       ((unsigned int)decoded_address[5]) << 2 |
                       ((unsigned int)decoded_address[6]) << 1 |
                       ((unsigned int)decoded_address[7]);

    // Publish decoded command to MQTT
    mqtt_publish("ir/decoded", decoded_command, strlen(decoded_command));
}

int main() {
    int ret;

    // Initialize syslog
    openlog("ir_decoder");

    // Initialize pigpio
    ret = piGPIOinit(1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    // Set up GPIO17 as input with pull-up
    ret = piGPIOsetMode(IR_RECEIVER_PIN, PI_INPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set GPIO17 as input");
        return 1;
    }
    ret = piGPIOsetPullUp(IR_RECEIVER_PIN);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to enable pull-up on GPIO17");
        return 1;
    }

    // Register pigpio alert callback
    ret = piGPIOsetEdgedCallback(IR_RECEIVER_PIN, ir_callback);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to register pigpio alert callback");
        return 1;
    }

    // Initialize MQTT client
    mqtt_client_handle client;
    mqtt_client_init(&client, "ir_decoder");
    mqtt_client_set_callback_data(&client, NULL);
    mqtt_client_set_callback_on_connect(&client, NULL);
    mqtt_client_set_callback_on_message(&client, NULL);
    mqtt_client_set_callback_on_disconnect(&client, NULL);
    mqtt_client_set_callback_on_error(&client, NULL);
    mqtt_client_connect("localhost", 1883);

    // Start MQTT network loop
    mqtt_loop();

    // Clean up resources
    piGPIOexit();
    mqtt_client_destroy(&client);
    closelog();

    return 0;
}

