#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <time.h>

#define ADDR_LIST {0x23, 0x24, 0x25, 0x26}
#define ADDR_COUNT 4
#define LUX_CONVERSION_FACTOR 1.2
#define UDP_MULTICAST_ADDRESS {239, 255, 255, 250}
#define UDP_MULTICAST_PORT 5005

#define BUFFER_SIZE 1024

#define I2C_DEVICE "/dev/i2c-1"
#define UDP_SOCKET (socket(AF_INET, SOCK_DGRAM, 0))

double sensor_readings[ADDR_COUNT];
int sensor_readings_valid[ADDR_COUNT] = {0};
int exit_flag = 0;

void *read_sensors(void *arg) {
    int i;
    for (i = 0; i < ADDR_COUNT; i++) {
        int fd = open(I2C_DEVICE, O_RDWR);
        if (fd < 0) {
            perror("open I2C device");
            continue;
        }

        if (ioctl(fd, I2C_SLAVE, ADDR_LIST[i]) < 0) {
            close(fd);
            sensor_readings[i] = NAN;
            continue;
        }

        uint8_t command[1] = {0x20};
        write(fd, command, 1);
        if (write(fd, NULL, 0) < 0) {
            close(fd);
            sensor_readings[i] = NAN;
            continue;
        }

        struct i2c_msg msg;
        msg.addr = ADDR_LIST[i];
        msg.len = 2;
        msg.data = (uint8_t *)malloc(2);

        if (ioctl(fd, I2C_MSG_READ, &msg) < 0) {
            close(fd);
            sensor_readings[i] = NAN;
            continue;
        }

        if (msg.len < 2) {
            close(fd);
            sensor_readings[i] = NAN;
            continue;
        }

        sensor_readings[i] = ((msg.data[0] << 8) | msg.data[1]) / LUX_CONVERSION_FACTOR;
        free(msg.data);
    }
    close(fd);
    return NULL;
}

void *udp_broadcast(void *arg) {
    struct sockaddr_in dest_addr;
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(UDP_MULTICAST_PORT);
    dest_addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDRESS);

    char buffer[BUFFER_SIZE];
    int len = 0;

    while (!exit_flag) {
        time_t now = time(NULL);
        char time_str[8];
        sprintf(time_str, "%08ld", now);

        for (int i = 0; i < ADDR_COUNT; i++) {
            if (sensor_readings_valid[i]) {
                snprintf(buffer, BUFFER_SIZE, "%d,%f;", i + 1, sensor_readings[i]);
                len += strlen(buffer);
            }
        }

        if (len > 0) {
            sendto(UDP_SOCKET, buffer, len, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr));
            len = 0;
        }

        usleep(180000000); // 180 seconds
    }

    close(UDP_SOCKET);
    return NULL;
}

int main(int argc, char *argv[]) {
    pthread_t read_sensors_thread, udp_broadcast_thread;

    if (pthread_mutex_init(NULL, NULL) != 0) {
        perror("pthread_mutex_init");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&read_sensors_thread, NULL, read_sensors, NULL) != 0) {
        perror("pthread_create");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&udp_broadcast_thread, NULL, udp_broadcast, NULL) != 0) {
        perror("pthread_create");
        exit(EXIT_FAILURE);
    }

    if (pthread_join(read_sensors_thread, NULL) != 0) {
        perror("pthread_join");
        exit(EXIT_FAILURE);
    }

    if (pthread_join(udp_broadcast_thread, NULL) != 0) {
        perror("pthread_join");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_destroy(NULL, NULL);
    close(UDP_SOCKET);
    return 0;
}

