#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "airflow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY 100

typedef struct {
    int fd;
    long long raw_value;
} sensor_data;

static sensor_data data;

void i2c_read_retry(int fd, unsigned char command, int count) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        int ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
        if (ret < 0) {
            perror("ioctl I2C_SLAVE");
            if (errno == EIO) {
                printf("Bus error detected, retrying...\n");
                usleep(RETRY_DELAY * 1000);
                retries--;
            } else {
                printf("Error reading from I2C device, exiting.\n");
                exit(EXIT_FAILURE);
            }
        }

        ret = ioctl(fd, I2C_MEMREAD, &command);
        if (ret < 0) {
            perror("ioctl I2C_MEMREAD");
            if (errno == ENXIO) {
                printf("Sensor not present, retrying...\n");
                usleep(RETRY_DELAY * 1000);
                retries--;
            } else {
                printf("Error reading from I2C device, exiting.\n");
                exit(EXIT_FAILURE);
            }
        }

        data.raw_value = ntohl(read(fd, &command, sizeof(command)));
        if (data.raw_value == 0) {
            printf("Sensor read failed, retrying...\n");
            usleep(RETRY_DELAY * 1000);
            retries--;
        } else {
            break;
        }
    }
}

void log_airflow(long long raw_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening airflow_log.txt");
        return;
    }

    double flow = (raw_value - 3277) * 0.1;
    fprintf(fp, "%llu\t%f\n", (long long)flow, flow);
    fclose(fp);
}

void sigint_handler(int signum) {
    printf("\nSIGINT received. Closing I2C device and flushing log file.\n");
    close(data.fd);
    fclose(fopen(LOG_FILE, "a"));
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    int fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        perror("Error opening airflow_log.txt");
        return EXIT_FAILURE;
    }

    data.fd = open("/dev/i2c-1", O_RDWR | O_SYNC);
    if (data.fd == -1) {
        perror("Error opening /dev/i2c-1");
        close(fd);
        return EXIT_FAILURE;
    }

    i2c_read_retry(data.fd, 0x00, 2);
    log_airflow(data.raw_value);

    close(data.fd);
    fclose(fd);
    return EXIT_SUCCESS;
}

