#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define WHO_AM_ID 0x24
#define ENABLE 0x80
#define CFG6 0xAF
#define SP_EN 0x01
#define SPECTRAL_REG_START 0x60
#define SPECTRAL_REG_END 0x73

#define LOG_FILE "spectral_log.csv"
#define LOG_INTERVAL 5

int main(int argc, char *argv[]) {
    int file;
    struct i2c_client *client;
    long value;
    char timestamp[20];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_interval_seconds>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if ((file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    client = i2c_open(I2C_BUS, 0);
    if (!client) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(client->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        i2c_close(client, 1);
        close(file);
        exit(EXIT_FAILURE);
    }

    if (read(client->fd, &value, 1) != 1 || value != 0x19) {
        fprintf(stderr, "Sensor not found or address mismatch\n");
        i2c_close(client, 1);
        close(file);
        exit(EXIT_FAILURE);
    }

    if (write(client->fd, &ENABLE, 1) != 1 || write(client->fd, &CFG6, 1) != 1 ||
        write(client->fd, &SP_EN, 1) != 1) {
        perror("write");
        i2c_close(client, 1);
        close(file);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 10; i++) {
        if (read(client->fd, &value, 1) != 1) {
            perror("read");
            break;
        }

        // Simplified lux approximation (assuming each channel's value is proportional to light intensity)
        double lux = (value >> 8) * 100; // Assuming each channel's value is in 10s of lux

        // Format timestamp and lux value
        sprintf(timestamp, "%s%d", ctime(NULL), (int)lux);

        // Append to log file
        if (write(file, timestamp, strlen(timestamp)) != strlen(timestamp)) {
            perror("write");
            break;
        }
    }

    i2c_close(client, 1);
    close(file);

    return 0;
}

