#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define LUX_UPDATE_INTERVAL 1000

#define UDP_MULTICAST_ADDR {123, 123, 123, 255}
#define UDP_MULTICAST_PORT 5000

void signal_handler(int signum) {
    close(1); // Close stdout
    close(2); // Close stderr
    close(3); // Close stdin
    close(4); // Close file descriptor for I2C
    close(5); // Close UDP socket
    exit(0);
}

int main() {
    int i2c_fd, sockfd;
    struct sockaddr_in6 addr;
    struct i2c_rdwr_cmd cmd;
    unsigned char raw_lux;
    double lux;
    char buffer[1024];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_SYNC);
    if (i2c_fd == -1) {
        perror("Failed to open i2c-1");
        exit(EXIT_FAILURE);
    }

    memset(&cmd, 0, sizeof(cmd));
    cmd.command = I2C_READ_BYTE;
    cmd.len = 1;
    cmd.addr = I2C_ADDR;

    if (ioctl(i2c_fd, I2C_MASTER, &cmd) < 0) {
        perror("Failed to send power-on command");
        exit(EXIT_FAILURE);
    }

    cmd.command = 0x10; // Continuous high-resolution mode
    if (ioctl(i2c_fd, I2C_MASTER, &cmd) < 0) {
        perror("Failed to set continuous mode");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (ioctl(i2c_fd, I2C_RD_BLOCK, &cmd) < 0) {
            if (errno == EIO || errno == EBUSY) {
                printf("Sensor not present or bus error, retrying in 1 second...\n");
                usleep(1000000);
                continue;
            } else {
                perror("Failed to read raw lux value from sensor");
                exit(EXIT_FAILURE);
            }
        }

        raw_lux = cmd.response;

        lux = (double)raw_lux / 1.2;

        snprintf(buffer, sizeof(buffer), "lux: %.2f\n", lux);
        sendto(sockfd, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)),
            addr.sin6_port = htons(UDP_MULTICAST_PORT);

        if (sendto(sockfd, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
            perror("Failed to send lux value over UDP multicast");
            exit(EXIT_FAILURE);
        }

        usleep(LUX_UPDATE_INTERVAL * 1000000); // Sleep for 1 second
    }

    close(i2c_fd);
    close(sockfd);

    return 0;
}

