#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define BAUD_RATE 921600
#define MAGIC_WORD_LEN 8
#define TLV_PAYLOAD_LEN 4

#define RADAR_DATA_FILE "radar_data.csv"

void write_to_csv(int object_index, float range_m, float velocity_mps) {
    FILE *file = fopen(RADAR_DATA_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return;
    }
    time_t now = time(NULL);
    fprintf(file, "%d,%f,%f\n", object_index, (double)now / 1000000, velocity_mps);
    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <radar_data_file>\n", argv[0]);
        return 1;
    }

    const char *radar_data_file = argv[1];

    int uart_fd = open( "/dev/ttyS0", O_RDWR | O_NOCTTY | O_NDELAY );
    if (uart_fd == -1) {
        perror("Failed to open /dev/ttyS0");
        return 1;
    }

    pigpio_init(1);

    gpioSetMode(0, PI_OUTPUT);
    gpioSetMode(1, PI_OUTPUT);

    char magic_word[MAGIC_WORD_LEN];
    char tlv_payload[TLV_PAYLOAD_LEN];
    char buffer[1024];
    int buffer_index = 0;
    int frame_size = 0;
    int object_index = 0;
    float range_m = 0.0;
    float velocity_mps = 0.0;

    while (1) {
        int read_bytes = read(uart_fd, buffer, sizeof(buffer));
        if (read_bytes == -1) {
            perror("Failed to read from UART");
            continue;
        }

        if (read_bytes == 0) {
            continue;
        }

        if (buffer_index + read_bytes > sizeof(buffer)) {
            fprintf(stderr, "Buffer overflow detected, skipping frame\n");
            continue;
        }

        memcpy(magic_word, buffer, MAGIC_WORD_LEN);
        if (memcmp(magic_word, (void *)0x02040306, MAGIC_WORD_LEN) != 0) {
            fprintf(stderr, "Invalid magic word, skipping frame\n");
            continue;
        }

        frame_size = read_bytes - MAGIC_WORD_LEN;
        memcpy(tlv_payload, buffer + MAGIC_WORD_LEN, frame_size);

        if (frame_size < TLV_PAYLOAD_LEN) {
            fprintf(stderr, "TLV payload is incomplete, skipping frame\n");
            continue;
        }

        range_m = *(float *)tlv_payload;
        velocity_mps = *(float *)(tlv_payload + 4);

        write_to_csv(object_index, range_m, velocity_mps);
        object_index++;

        buffer_index += frame_size;
    }

    close(uart_fd);
    pigpio_terminate(1);
    fclose(radar_data_file);
    return 0;
}

