#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/termios.h>
#include <signal.h>
#include <time.h>

#define BUFFER_SIZE 1024
#define BAUD_RATE 115200
#define INTER_BYTE_TIMEOUT 0.5
#define DATA_TIMEOUT 2

#define UART_DEVICE "/dev/serial0"
#define DATA_LINE "\n"
#define TIME_FORMAT "%Y-%m-%d %H:%M:%S"

typedef struct {
    time_t timestamp;
    double range;
} RadarData;

RadarData data_buffer[BUFFER_SIZE];
int data_buffer_index = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        close(fileno(ttyname(STDIN_FILENO)));
        exit(0);
    }
}

void setup_tty() {
    termios term;
    struct termios term_backup;

    if (tcgetattr(STDIN_FILENO, &term) != 0) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    term_backup = term;
    term.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD | CSIZE(5);
    term.c_iflag = IGNPAR;
    term.c_oflag = 0;
    term.c_lflag = ICANON | ECHO;
    term.c_cc[VMIN] = 1;
    term.c_cc[VTIME] = (int)INTER_BYTE_TIMEOUT;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &term) != 0) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

void teardown_tty() {
    termios term;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &term_backup) != 0) {
        perror("tcsetattr");
    }
}

void read_data() {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    select(STDIN_FILENO + 1, NULL, &fd_read, NULL, NULL, NULL);

    if (fd_read == -1) {
        perror("select");
        exit(EXIT_FAILURE);
    }

    bytes_read = read(STDIN_FILENO + 1, buffer, BUFFER_SIZE);
    if (bytes_read == -1) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    if (bytes_read == 0) {
        return;
    }

    if (buffer[0] == '\n') {
        data_buffer[data_buffer_index].timestamp = time(NULL);
        data_buffer[data_buffer_index].range = atof(buffer + 1);
        data_buffer_index++;

        if (data_buffer_index >= BUFFER_SIZE) {
            data_buffer_index = BUFFER_SIZE - 1;
        }

        printf("%s: %f meters\n", asctime(localtime(&data_buffer[data_buffer_index].timestamp)), data_buffer[data_buffer_index].range);
        data_buffer_index = 0;
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_tty();

    while (1) {
        read_data();
    }

    teardown_tty();
    return 0;
}

