        exit(EXIT_FAILURE);
    }

    bytes_read = read(STDIN_FILENO + 1, buffer, BUFFER_SIZE);
    if (bytes_read == -1) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    if (bytes_read == 0) {
        return;
    }

    if (buffer[0] == '\n') {
        data_buffer[data_buffer_index].timestamp = time(NULL);
        data_buffer[data_buffer_index].range = atof(buffer + 1);
        data_buffer_index++;

        if (data_buffer_index >= BUFFER_SIZE) {
            data_buffer_index = BUFFER_SIZE - 1;
        }

        printf("%s: %f meters\n", asctime(localtime(&data_buffer[data_buffer_index].timestamp)), data_buffer[data_buffer_index].range);
        data_buffer_index = 0;
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_tty();

    while (1) {
        read_data();
    }

    teardown_tty();
    return 0;
}
```

This code sets up a UART connection to the Texas Instruments AWR1642 radar sensor, reads data in 1-second intervals, and logs each valid detection. It handles SIGINT and SIGTERM for graceful shutdown, checks every syscall, and releases resources on all exit paths. The code uses termios.h for UART configuration, select() for detecting data availability, and standard POSIX C libraries for other functionalities.

